01-xray:
// MOTION: A bright, high-contrast airport X-ray scanner beam with a wide glowing band and fading phosphor wake sweeps the full height of the radiograph in one second, lighting up the bag and all its contents before a second diagnostic pass and flicker follow.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;

// Hyperrealistic Radiograph of a Woman's Handbag
// Rendered with p5.js v2 + p5.brush in WEBGL

const PAL = {
  bgDeep: "#02060d",
  bgPrussian: "#040d1a",
  bgCharcoal: "#07172b",
  bgIndigo: "#091f38",
  veilDark: "#0c2844",
  veilMid: "#153d63",
  veilLight: "#215785",
  cyanLow: "#3275a6",
  cyanMid: "#4d98c7",
  cyanBright: "#72bce6",
  cyanGlow: "#9cd8f7",
  milkSoft: "#c7ecff",
  milkBright: "#e4f6ff",
  whitePure: "#ffffff"
};

let stillImg = null;

// Coordinate transform helper: maps local (lx, ly) into canvas space
// centered at (cx, cy) and rotated by deg degrees
function xform(lx, ly, cx, cy, deg) {
  let r = (deg * Math.PI) / 180;
  let c = Math.cos(r);
  let s = Math.sin(r);
  return [cx + lx * c - ly * s, cy + lx * s + ly * c];
}

// Generate polygon points for an ellipse in local coordinates, transformed to world space
function ellipsePts(lx, ly, rx, ry, cx, cy, deg, n = 36, startDeg = 0, endDeg = 360) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = ((startDeg + ((endDeg - startDeg) * i) / n) * Math.PI) / 180;
    let px = lx + Math.cos(a) * rx;
    let py = ly + Math.sin(a) * ry;
    pts.push(xform(px, py, cx, cy, deg));
  }
  return pts;
}

// Generate rounded rectangle polygon points in local coordinates, transformed to world space
function roundRectPts(lx, ly, w, h, rad, cx, cy, deg, segs = 6) {
  let pts = [];
  let hw = w / 2;
  let hh = h / 2;
  let r = Math.min(rad, hw, hh);
  let corners = [
    { x: lx + hw - r, y: ly - hh + r, a0: -90, a1: 0 },
    { x: lx + hw - r, y: ly + hh - r, a0: 0, a1: 90 },
    { x: lx - hw + r, y: ly + hh - r, a0: 90, a1: 180 },
    { x: lx - hw + r, y: ly - hh + r, a0: 180, a1: 270 }
  ];
  for (let c of corners) {
    for (let i = 0; i <= segs; i++) {
      let a = ((c.a0 + ((c.a1 - c.a0) * i) / segs) * Math.PI) / 180;
      pts.push(xform(c.x + Math.cos(a) * r, c.y + Math.sin(a) * r, cx, cy, deg));
    }
  }
  return pts;
}

// Helper to draw a closed or open polyline from world points
function strokePoly(pts, close = true, curvature = 0.1) {
  if (pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.25) clean.push(pts[i]);
  }
  if (close && clean.length > 2) {
    let dx = clean[0][0] - clean[clean.length - 1][0];
    let dy = clean[0][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy <= 0.25) clean.pop();
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    return;
  }
  brush.beginShape(curvature);
  for (let p of clean) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(close);
}

// Helper for X-ray translucent additive density wash
function xrayWash(pts, col, alpha) {
  if (pts.length < 3) return;
  let poly = new brush.Polygon(pts);
  poly.wash(col, alpha);
}

// Helper for multi-step soft radiographic bloom around a polygon
function xrayBloomPoly(pts, cx, cy, colCore, alphaCore, layers = 3, spread = 1.12) {
  for (let l = layers; l >= 1; l--) {
    let s = 1 + ((spread - 1) * l) / layers;
    let expanded = pts.map((p) => [
      cx + (p[0] - cx) * s,
      cy + (p[1] - cy) * s
    ]);
    let poly = new brush.Polygon(expanded);
    poly.wash(colCore, Math.max(3, Math.floor(alphaCore / (l * 1.35))));
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4089);
  noiseSeed(4089);

  // Ultra-fine technical pen for solder pins, circuit traces, spring coils, zipper teeth
  brush.add("xray_pen", {
    type: "default",
    weight: 0.16,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.15,
    opacity: 235,
    spacing: 0.12,
    pressure: [0.85, 1.0, 0.85],
    rotate: "none",
    noise: 0.15
  });

  // Soft white radiographic pencil for milky gradients and delicate tonal build-up
  brush.add("xray_pencil", {
    type: "default",
    weight: 0.34,
    scatter: 0.35,
    sharpness: 0.38,
    grain: 0.65,
    opacity: 145,
    spacing: 0.18,
    pressure: [0.4, 1.15, 0.35],
    rotate: "natural",
    noise: 0.45
  });

  // Soft halation / film bloom brush
  brush.add("xray_bloom", {
    type: "spray",
    weight: 6.5,
    scatter: 2.8,
    opacity: 18,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4],
    rotate: "random",
    noise: 0.3
  });

  // Smooth X-ray density shader brush
  brush.add("xray_shader", {
    type: "marker",
    weight: 2.2,
    scatter: 0.15,
    opacity: 22,
    spacing: 0.25,
    pressure: [0.6, 1.0, 0.6],
    markerTip: false,
    rotate: "natural",
    noise: 0.1
  });
}

function paintStill() {
  translate(-width / 2, -height / 2);
  background(PAL.bgDeep);
  brush.noField();

  // 1. DEEP PRUSSIAN BLUE-BLACK CHARCOAL GROUND
  drawPrussianCharcoalGround();

  // Global handbag transform parameters (tilted diagonally, cropped hard at corners)
  const bagCX = 610;
  const bagCY = 620;
  const bagAngle = -27;

  // 2. HANDBAG LEATHER STRUCTURE, GUSSETS, SEAMS & HANDLES
  drawHandbagStructure(bagCX, bagCY, bagAngle);

  // 3. SOFT FILM HALATION / BLOOM UNDERLAYS FOR CONTENTS
  drawContentsHalation(bagCX, bagCY, bagAngle);

  // 4. FOLDED TELESCOPIC UMBRELLA (RIBS, SHAFT, HELICAL SPRING, STRETCHERS)
  drawFoldedUmbrella(615, 585, -36);

  // 5. SMARTPHONE CIRCUIT BOARD, COILS, BATTERY & SOLDER POINTS
  drawSmartphoneXray(735, 675, -11);

  // 6. LIPSTICK BULLET IN SWIVEL HELICAL TUBE
  drawLipstickXray(350, 790, 39);

  // 7. GLASS PERFUME ATOMIZER & SAFETY PIN (INTIMATE SMALL INCIDENTS)
  drawPerfumeAtomizer(235, 565, -52);
  drawSafetyPinAndBobbyPin(535, 855, 18);

  // 8. RING OF KEYS & ELECTRONIC TRANSPONDER FOB
  drawKeyRingCluster(435, 415, 14);

  // 9. LOOSE COINS IN LOWER GUSSET (BI-METALLIC, MILLED RIMS, OVERLAPS)
  drawLooseCoins(bagCX, bagCY, bagAngle);

  // 10. HANDBAG ZIPPERS (HUNDREDS OF TINY TEETH, SLIDERS, HARDWARE CLASPS)
  drawZippersAndHardware(bagCX, bagCY, bagAngle);

  // 11. OVERLAPPING DENSITY HIGHLIGHTS, FILM BLOOM & SCANNER ARTIFACTS
  drawSpecularOverlapsAndFilmFinish(bagCX, bagCY, bagAngle);
}

function draw() {
  const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;
  if (frameCount > TOTAL_FRAMES) return;

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  background(PAL.bgDeep);
  image(stillImg, -width / 2, -height / 2);
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();

  // k runs from 1 to 47 across the 2-second clip (k = 23 is 1.0 second)
  const k = frameCount - 1;
  const u = k / (TOTAL_FRAMES - 1);

  // PASS 1: Bold, high-contrast primary scanner sweep across the entire frame in ~1 second (k = 1..25)
  // Starts immediately at x = 180 on k = 1, reaches x = 420 by frame 6 (k = 5), and crosses to x = 1135 by 1s (k = 23)
  let u1 = constrain(k / 23, 0, 1.18);
  let scanX1 = lerp(180, 1135, Math.min(1, u1)) + Math.max(0, u1 - 1) * 650;
  let env1 = k === 1 ? 0.52 : k === 2 ? 0.85 : k <= 24 ? 1.0 : Math.max(0, 1 - (k - 24) / 7);

  // PASS 2: Faster secondary diagnostic pass & high-voltage tube flicker in second 2 (k = 19..47)
  let u2 = constrain((k - 19) / 26, 0, 1.1);
  let scanX2 = lerp(110, 1155, Math.min(1, u2)) + Math.max(0, u2 - 1) * 500;
  let env2 = 0;
  if (k >= 19) {
    let rampIn = constrain((k - 19) / 4, 0, 1);
    let rampOut = k > 43 ? constrain(1 - (k - 43) / 5, 0, 1) : 1;
    let tubeFlicker = 0.78 + 0.22 * Math.sin(k * 1.65);
    env2 = 0.76 * rampIn * rampOut * tubeFlicker;
  }

  // Whole-radiograph ambient X-ray tube excitation pulse (reacts across the entire bag)
  let globalPulse =
    0.34 * env1 * (0.75 + 0.25 * Math.sin(k * 0.6)) +
    0.28 * env2 * (0.65 + 0.35 * Math.cos(k * 1.4));

  drawFullRadiographReaction(scanX1, env1, scanX2, env2, globalPulse, u, k);
}

// =============================================================================
// HIGH-CONTRAST FULL-FRAME SCANNER SWEEP, WAKE & RADIOGRAPH REACTION
// =============================================================================

// Combined excitation at world coordinate wx from Pass 1, Pass 2, and global tube pulse
function combinedExcitation(wx, scanX1, env1, scanX2, env2, trail1 = 490, lead1 = 85) {
  let e1 = 0;
  if (env1 > 0.01) {
    let dx1 = scanX1 - wx;
    if (dx1 >= -lead1 && dx1 <= trail1) {
      if (dx1 < 0) {
        let t = (dx1 + lead1) / lead1;
        e1 = t * t * env1;
      } else {
        let t = 1 - dx1 / trail1;
        e1 = Math.pow(t, 1.28) * env1;
      }
    }
  }
  let e2 = 0;
  if (env2 > 0.01) {
    let trail2 = trail1 * 0.78;
    let lead2 = lead1 * 0.85;
    let dx2 = scanX2 - wx;
    if (dx2 >= -lead2 && dx2 <= trail2) {
      if (dx2 < 0) {
        let t = (dx2 + lead2) / lead2;
        e2 = t * t * env2;
      } else {
        let t = 1 - dx2 / trail2;
        e2 = Math.pow(t, 1.35) * env2;
      }
    }
  }
  return Math.min(1.25, e1 + e2 * 0.85);
}

function drawFullRadiographReaction(scanX1, env1, scanX2, env2, globalPulse, u, k) {
  const bagCX = 610;
  const bagCY = 620;
  const bagAngle = -27;

  // 1. Wide, bright fading phosphor wake & glowing ionization band for Pass 1 (and Pass 2)
  if (env1 > 0.01) {
    drawScannerBandAndWake(scanX1, env1, 520, 95, 7001);
  }
  if (env2 > 0.01) {
    drawScannerBandAndWake(scanX2, env2 * 0.85, 420, 75, 7002);
  }

  // 2. Whole handbag leather body, gussets, seams, and handles lighting up as the beam passes
  randomSeed(5050);
  noiseSeed(5050);
  drawReactingHandbagStructure(bagCX, bagCY, bagAngle, scanX1, env1, scanX2, env2, globalPulse);

  // 3. Large radiographic halation blooms & full-body illumination of all contents inside the bag
  randomSeed(5150);
  noiseSeed(5150);
  drawReactingContentsUnderlays(scanX1, env1, scanX2, env2, globalPulse);

  // 4. High-contrast flare of perfume atomizer, lipstick mechanism, and pins
  randomSeed(5202);
  noiseSeed(5202);
  drawReactingSmallContents(scanX1, env1, scanX2, env2, globalPulse);

  // 5. High-contrast flare of key ring cluster, 3 keys, and transponder fob
  randomSeed(5303);
  noiseSeed(5303);
  drawReactingKeyCluster(435, 415, 14, scanX1, env1, scanX2, env2, globalPulse);

  // 6. High-contrast flare of folded umbrella (canopy, shaft, 152 spring coils, hubs, 8 ribs)
  randomSeed(5404);
  noiseSeed(5404);
  drawReactingUmbrella(615, 585, -36, scanX1, env1, scanX2, env2, globalPulse);

  // 7. High-contrast flare of smartphone (chassis, battery, PCB, BGA chips, MagSafe coil, camera)
  randomSeed(5505);
  noiseSeed(5505);
  drawReactingSmartphone(735, 675, -11, scanX1, env1, scanX2, env2, globalPulse, u);

  // 8. High-contrast flare of loose coins & incandescent overlap lenses
  randomSeed(5606);
  noiseSeed(5606);
  drawReactingCoins(bagCX, bagCY, bagAngle, scanX1, env1, scanX2, env2, globalPulse);

  // 9. High-contrast flare of handbag zippers (257 teeth), sliders, D-rings & clasps
  randomSeed(5101);
  noiseSeed(5101);
  drawReactingZippersAndHardware(bagCX, bagCY, bagAngle, scanX1, env1, scanX2, env2, globalPulse);

  // 10. Blazing white-hot scanner beam core spine & animated clinical detector HUD
  randomSeed(5707);
  noiseSeed(5707);
  if (env1 > 0.01) {
    drawBeamCoreSpine(scanX1, env1, 1.0);
  }
  if (env2 > 0.01) {
    drawBeamCoreSpine(scanX2, env2, 0.78);
  }
  drawScannerCalibrationHUD(scanX1, env1, scanX2, env2, globalPulse, u, k);
}

// Wide glowing band + 520px fading phosphor wake + full-frame horizontal detector scanlines
function drawScannerBandAndWake(scanX, env, wakeWidth, leadWidth, seedVal) {
  randomSeed(seedVal);
  noiseSeed(seedVal);

  // Graded vertical wash curtains spanning the full 1200px height of the radiograph
  const curtains = [
    { x0: -wakeWidth, x1: -wakeWidth * 0.72, col: PAL.veilLight, a: 42 },
    { x0: -wakeWidth * 0.72, x1: -wakeWidth * 0.48, col: PAL.cyanLow, a: 54 },
    { x0: -wakeWidth * 0.48, x1: -wakeWidth * 0.28, col: PAL.cyanMid, a: 68 },
    { x0: -wakeWidth * 0.28, x1: -wakeWidth * 0.14, col: PAL.cyanBright, a: 82 },
    { x0: -wakeWidth * 0.14, x1: -42, col: PAL.cyanGlow, a: 96 },
    // The bright glowing scanner band itself (-42 to +28 around scanX)
    { x0: -42, x1: -14, col: PAL.milkSoft, a: 125 },
    { x0: -14, x1: 8, col: PAL.whitePure, a: 165 },
    { x0: 8, x1: 30, col: PAL.milkSoft, a: 105 },
    // Forward ionization scatter ahead of the beam
    { x0: 30, x1: leadWidth * 0.65, col: PAL.cyanGlow, a: 68 },
    { x0: leadWidth * 0.65, x1: leadWidth, col: PAL.cyanMid, a: 38 }
  ];

  for (let c of curtains) {
    let lx = constrain(scanX + c.x0, 0, 1200);
    let rx = constrain(scanX + c.x1, 0, 1200);
    if (rx - lx > 1) {
      let pts = [
        [lx, 0],
        [rx, 0],
        [rx, 1200],
        [lx, 1200]
      ];
      xrayWash(pts, c.col, Math.max(3, Math.floor(c.a * env)));
    }
  }

  // Dense horizontal X-ray detector readout lines sweeping across the wake & active band
  const numDetectorLines = 76;
  for (let i = 0; i < numDetectorLines; i++) {
    let y = map(i, 0, numDetectorLines - 1, 8, 1192);
    let rowMod = 0.75 + 0.25 * Math.sin(i * 1.7 + scanX * 0.02);
    let wStart = constrain(scanX - wakeWidth * 0.92 * rowMod, 0, 1200);
    let wEnd = constrain(scanX + leadWidth * 0.7, 0, 1200);
    if (wEnd - wStart > 6) {
      let col = i % 3 === 0 ? PAL.milkBright : i % 2 === 0 ? PAL.cyanGlow : PAL.cyanBright;
      let w = (i % 3 === 0 ? 0.95 : 0.65) * env;
      brush.set("xray_pencil", col, w);
      brush.line(wStart, y, wEnd, y);
    }

    // Brightest core readout streak right inside the glowing band
    let cStart = constrain(scanX - 95 * rowMod, 0, 1200);
    let cEnd = constrain(scanX + 24, 0, 1200);
    if (cEnd - cStart > 4 && i % 2 === 0) {
      brush.set("xray_pen", PAL.whitePure, 0.95 * env);
      brush.line(cStart, y, cEnd, y);
    }
  }
}

// Blazing white-hot collimated beam spine spanning full canvas height
function drawBeamCoreSpine(scanX, env, scaleStr) {
  let s = env * scaleStr;
  let x = constrain(scanX, 2, 1198);

  // Full-height column of overlapping halation bloom spheres along the beam spine
  for (let i = 0; i <= 16; i++) {
    let by = map(i, 0, 16, 20, 1180);
    brush.set("xray_bloom", PAL.cyanGlow, 1.85 * s);
    brush.circle(x - 6, by, 92, 0.22);
    brush.set("xray_bloom", PAL.whitePure, 1.35 * s);
    brush.circle(x, by, 48, 0.18);
  }

  // Multi-pass glowing marker & pencil core lines
  brush.set("xray_shader", PAL.cyanGlow, 2.8 * s);
  brush.line(x - 6, 0, x - 6, 1200);

  brush.set("xray_shader", PAL.milkBright, 2.2 * s);
  brush.line(x - 2, 0, x - 2, 1200);

  brush.set("xray_shader", PAL.whitePure, 1.8 * s);
  brush.line(x, 0, x, 1200);

  brush.set("xray_pencil", PAL.whitePure, 1.9 * s);
  brush.line(x - 3, 0, x - 3, 1200);
  brush.line(x + 2, 0, x + 2, 1200);

  brush.set("xray_pen", PAL.whitePure, 1.85 * s);
  brush.line(x - 1.5, 0, x - 1.5, 1200);
  brush.line(x, 0, x, 1200);
  brush.line(x + 1.5, 0, x + 1.5, 1200);
}

// Whole handbag structure (leather panels, gussets, collar, straps, handles) reacting to the scan
function drawReactingHandbagStructure(cx, cy, ang, scanX1, env1, scanX2, env2, globalPulse) {
  let bagOuter = [
    xform(-520, -340, cx, cy, ang),
    xform(520, -340, cx, cy, ang),
    xform(650, 410, cx, cy, ang),
    xform(590, 465, cx, cy, ang),
    xform(-590, 465, cx, cy, ang),
    xform(-650, 410, cx, cy, ang)
  ];

  // Global handbag body excitation wash
  let bagCenterResp = Math.max(globalPulse, combinedExcitation(cx, scanX1, env1, scanX2, env2, 540, 140) * 0.65);
  if (bagCenterResp > 0.04) {
    xrayWash(bagOuter, PAL.cyanLow, Math.floor(42 * bagCenterResp));
    xrayWash(bagOuter, PAL.cyanMid, Math.floor(28 * bagCenterResp));
  }

  // Left gusset, right gusset, top collar, bottom panel, and inner pocket reacting as the beam crosses them
  const panels = [
    {
      cxLocal: -510,
      pts: [
        xform(-520, -340, cx, cy, ang),
        xform(-390, -310, cx, cy, ang),
        xform(-430, 120, cx, cy, ang),
        xform(-590, 465, cx, cy, ang),
        xform(-650, 410, cx, cy, ang)
      ],
      col: PAL.cyanBright,
      a: 62
    },
    {
      cxLocal: 510,
      pts: [
        xform(520, -340, cx, cy, ang),
        xform(390, -310, cx, cy, ang),
        xform(430, 120, cx, cy, ang),
        xform(590, 465, cx, cy, ang),
        xform(650, 410, cx, cy, ang)
      ],
      col: PAL.cyanBright,
      a: 62
    },
    {
      cxLocal: 0,
      pts: [
        xform(-525, -340, cx, cy, ang),
        xform(525, -340, cx, cy, ang),
        xform(542, -235, cx, cy, ang),
        xform(-542, -235, cx, cy, ang)
      ],
      col: PAL.cyanGlow,
      a: 55
    },
    {
      cxLocal: 0,
      pts: [
        xform(-590, 465, cx, cy, ang),
        xform(-480, 355, cx, cy, ang),
        xform(480, 355, cx, cy, ang),
        xform(590, 465, cx, cy, ang),
        xform(490, 520, cx, cy, ang),
        xform(-490, 520, cx, cy, ang)
      ],
      col: PAL.cyanGlow,
      a: 58
    },
    {
      cxLocal: -10,
      pts: [
        xform(-290, -175, cx, cy, ang),
        xform(270, -175, cx, cy, ang),
        xform(285, 195, cx, cy, ang),
        xform(-275, 195, cx, cy, ang)
      ],
      col: PAL.cyanBright,
      a: 48
    }
  ];

  for (let p of panels) {
    let wPt = xform(p.cxLocal, 0, cx, cy, ang);
    let resp = Math.max(globalPulse * 0.7, combinedExcitation(wPt[0], scanX1, env1, scanX2, env2, 480, 110));
    if (resp > 0.06) {
      xrayWash(p.pts, p.col, Math.floor(p.a * resp));
      brush.set("xray_pencil", PAL.milkSoft, 0.95 * resp);
      strokePoly(p.pts, true, 0.08);
    }
  }

  // Vertical leather straps & rolled leather piping flaring in milky cyan-white
  for (let side of [-1, 1]) {
    let sx = side * 265;
    let sw = xform(sx, 100, cx, cy, ang);
    let sResp = Math.max(globalPulse * 0.7, combinedExcitation(sw[0], scanX1, env1, scanX2, env2, 460, 95));
    if (sResp > 0.06) {
      let strapPts = [
        xform(sx - 28, -260, cx, cy, ang),
        xform(sx + 28, -260, cx, cy, ang),
        xform(sx + 34, 465, cx, cy, ang),
        xform(sx - 34, 465, cx, cy, ang)
      ];
      xrayWash(strapPts, PAL.cyanGlow, Math.floor(65 * sResp));
      brush.set("xray_pen", PAL.whitePure, 1.0 * sResp);
      strokePoly(strapPts, true, 0.05);
    }
  }

  // Rolled leather handles arching out the top of the bag lighting up as the beam sweeps across
  const handleConfigs = [
    { yBase: -295, yPeak: -760, xSkew: -20 },
    { yBase: -285, yPeak: -630, xSkew: 55 }
  ];
  for (let hc of handleConfigs) {
    let steps = 28;
    let outerWall = [];
    let innerWall = [];
    let coreCenter = [];
    let xLeft = -265, xRight = 265, tubeHalf = 19;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let u = 1 - t;
      let px =
        u * u * u * xLeft +
        3 * u * u * t * (xLeft * 1.08 + hc.xSkew) +
        3 * u * t * t * (xRight * 1.08 + hc.xSkew) +
        t * t * t * xRight;
      let py =
        u * u * u * hc.yBase +
        3 * u * u * t * hc.yPeak +
        3 * u * t * t * hc.yPeak +
        t * t * t * hc.yBase;
      let wMid = xform(px, py, cx, cy, ang);
      let hResp = combinedExcitation(wMid[0], scanX1, env1, scanX2, env2, 450, 90);
      if (hResp > 0.12) {
        coreCenter.push(wMid);
        outerWall.push(xform(px, py - tubeHalf, cx, cy, ang));
        innerWall.push(xform(px, py + tubeHalf, cx, cy, ang));
      }
    }
    if (coreCenter.length >= 2) {
      brush.set("xray_pencil", PAL.milkBright, 1.3);
      strokePoly(outerWall, false, 0.2);
      strokePoly(innerWall, false, 0.2);
      brush.set("xray_pen", PAL.whitePure, 1.05);
      strokePoly(coreCenter, false, 0.2);
    }
  }
}

// Large glowing radiographic halation blooms beneath every object as the beam excites them
function drawReactingContentsUnderlays(scanX1, env1, scanX2, env2, globalPulse) {
  const glows = [
    { x: 615, y: 585, rx: 470, ry: 105, ang: -36 },
    { x: 735, y: 675, rx: 260, ry: 145, ang: -11 },
    { x: 435, y: 415, rx: 180, ry: 155, ang: 14 },
    { x: 350, y: 790, rx: 145, ry: 72, ang: 39 },
    { x: 690, y: 970, rx: 235, ry: 95, ang: -27 },
