}

function drawReactingSmallContents(scanX1, env1, scanX2, env2, globalPulse) {
  // 1. Perfume Atomizer (235, 565, -52)
  const pCX = 235, pCY = 565, pAng = -52;
  let pResp = Math.max(globalPulse * 0.65, combinedExcitation(pCX, scanX1, env1, scanX2, env2, 470, 95));
  if (pResp > 0.06) {
    let outerGlass = roundRectPts(0, 12, 46, 112, 6, pCX, pCY, pAng);
    let crimpCollar = roundRectPts(0, -52, 28, 20, 2, pCX, pCY, pAng);
    let nozzleCap = roundRectPts(0, -72, 22, 22, 3, pCX, pCY, pAng);
    let glassBase = roundRectPts(0, 56, 45, 22, 5, pCX, pCY, pAng);

    xrayWash(outerGlass, PAL.cyanGlow, Math.floor(85 * pResp));
    xrayWash(glassBase, PAL.whitePure, Math.floor(135 * pResp));
    xrayWash(crimpCollar, PAL.whitePure, Math.floor(175 * pResp));
    xrayWash(nozzleCap, PAL.milkBright, Math.floor(135 * pResp));

    brush.set("xray_pen", PAL.whitePure, 1.25 * pResp);
    strokePoly(outerGlass, true, 0.08);
    strokePoly(crimpCollar, true, 0.04);
    strokePoly(nozzleCap, true, 0.04);

    for (let c = 0; c < 11; c++) {
      let sy = lerp(-62, -32, c / 11);
      let sy2 = lerp(-62, -32, (c + 1) / 11);
      let sx = c % 2 === 0 ? -4.5 : 4.5;
      let sx2 = (c + 1) % 2 === 0 ? -4.5 : 4.5;
      let p0 = xform(sx, sy, pCX, pCY, pAng);
      let p1 = xform(sx2, sy2, pCX, pCY, pAng);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
    brush.set("xray_bloom", PAL.whitePure, 1.3 * pResp);
    brush.circle(pCX, pCY, 62, 0.2);
  }

  // 2. Lipstick Bullet in Swivel Helical Tube (350, 790, 39)
  const lCX = 350, lCY = 790, lAng = 39;
  let lResp = Math.max(globalPulse * 0.65, combinedExcitation(lCX, scanX1, env1, scanX2, env2, 470, 95));
  if (lResp > 0.06) {
    let outerCap = roundRectPts(0, -32, 62, 148, 8, lCX, lCY, lAng);
    let innerBrass = roundRectPts(0, 34, 48, 104, 3, lCX, lCY, lAng);
    let midRing = roundRectPts(0, 30, 65, 16, 2, lCX, lCY, lAng);
    let baseWeight = roundRectPts(0, 94, 58, 12, 3, lCX, lCY, lAng);
    let bulletPts = [
      xform(-19, 14, lCX, lCY, lAng),
      xform(-19, -58, lCX, lCY, lAng),
      xform(-15, -78, lCX, lCY, lAng),
      xform(-2, -92, lCX, lCY, lAng),
      xform(14, -84, lCX, lCY, lAng),
      xform(19, -68, lCX, lCY, lAng),
      xform(19, 14, lCX, lCY, lAng)
    ];

    xrayWash(outerCap, PAL.cyanGlow, Math.floor(75 * lResp));
    xrayWash(innerBrass, PAL.milkSoft, Math.floor(95 * lResp));
    xrayWash(bulletPts, PAL.milkBright, Math.floor(95 * lResp));
    xrayWash(midRing, PAL.whitePure, Math.floor(155 * lResp));
    xrayWash(baseWeight, PAL.whitePure, Math.floor(185 * lResp));

    // Helical cam spiral slots glowing brightly
    let spiralSteps = 36;
    for (let pass = 0; pass < 2; pass++) {
      let slotPts = [];
      let phase = pass * 180;
      for (let i = 0; i <= spiralSteps; i++) {
        let t = i / spiralSteps;
        let sy = lerp(-12, 78, t);
        let sx = Math.sin(((t * 520 + phase) * Math.PI) / 180) * 22;
        slotPts.push(xform(sx, sy, lCX, lCY, lAng));
      }
      brush.set("xray_pen", PAL.whitePure, (pass === 0 ? 1.25 : 0.95) * lResp);
      strokePoly(slotPts, false, 0.25);
    }

    for (let side of [-1, 1]) {
      let lug = ellipsePts(side * 22, 12, 5.5, 4.5, lCX, lCY, lAng, 12);
      xrayWash(lug, PAL.whitePure, Math.floor(220 * lResp));
    }

    brush.set("xray_pen", PAL.whitePure, 1.2 * lResp);
    strokePoly(outerCap, true, 0.06);
    strokePoly(bulletPts, true, 0.2);
    strokePoly(midRing, true, 0.04);

    brush.set("xray_bloom", PAL.whitePure, 1.35 * lResp);
    brush.circle(lCX, lCY, 75, 0.2);
  }

  // 3. Safety Pin & Bobby Pin (535, 855, 18)
  const sCX = 535, sCY = 855, sAng = 18;
  let bCX = sCX - 95, bCY = sCY + 68, bAng = sAng - 44;
  let sResp = Math.max(globalPulse * 0.65, combinedExcitation(sCX, scanX1, env1, scanX2, env2, 460, 90));
  if (sResp > 0.06) {
    let coilEnd = ellipsePts(-42, 0, 9, 9, sCX, sCY, sAng, 18);
    let claspHead = roundRectPts(42, 0, 22, 16, 6, sCX, sCY, sAng);
    xrayWash(coilEnd, PAL.whitePure, Math.floor(175 * sResp));
    xrayWash(claspHead, PAL.whitePure, Math.floor(175 * sResp));

    let top0 = xform(-42, -8, sCX, sCY, sAng);
    let top1 = xform(38, -5, sCX, sCY, sAng);
    let bot0 = xform(-42, 8, sCX, sCY, sAng);
    let bot1 = xform(38, 5, sCX, sCY, sAng);
    brush.set("xray_pen", PAL.whitePure, 1.35 * sResp);
    brush.line(top0[0], top0[1], top1[0], top1[1]);
    brush.line(bot0[0], bot0[1], bot1[0], bot1[1]);
    strokePoly(coilEnd, true, 0.15);
    strokePoly(claspHead, true, 0.1);

    let wavyLeg = [];
    for (let i = 0; i <= 20; i++) {
      let lx = map(i, 0, 20, -48, 42);
      let ly = -3.5 + (i > 2 && i < 18 ? Math.sin(i * 1.35) * 2.6 : 0);
      wavyLeg.push(xform(lx, ly, bCX, bCY, bAng));
    }
    let straightLeg = [xform(-48, 4, bCX, bCY, bAng), xform(44, 2, bCX, bCY, bAng)];
    strokePoly(wavyLeg, false, 0.25);
    strokePoly(straightLeg, false, 0.1);
  }
}

function drawReactingKeyCluster(cx, cy, ang, scanX1, env1, scanX2, env2, globalPulse) {
  let kResp = Math.max(globalPulse * 0.7, combinedExcitation(cx, scanX1, env1, scanX2, env2, 480, 100));
  if (kResp < 0.05) return;

  // 1. Electronic Transponder Key Fob
  let fx = cx - 58, fy = cy - 52, fAng = ang - 48;
  let fobShell = roundRectPts(0, 0, 96, 56, 18, fx, fy, fAng, 6);
  let crBatt = ellipsePts(-14, 0, 18, 18, fx, fy, fAng, 22);
  let coilBar = roundRectPts(16, -16, 24, 5, 1, fx, fy, fAng);
  xrayWash(fobShell, PAL.cyanGlow, Math.floor(75 * kResp));
  xrayWash(crBatt, PAL.whitePure, Math.floor(165 * kResp));
  xrayWash(coilBar, PAL.whitePure, Math.floor(185 * kResp));

  brush.set("xray_pen", PAL.whitePure, 1.2 * kResp);
  strokePoly(fobShell, true, 0.12);
  strokePoly(crBatt, true, 0.1);
  strokePoly(coilBar, true, 0.04);

  // 2. Main Split Key Ring & Threading Hotspots
  let ringOuterPts = ellipsePts(0, 0, 54, 54, cx, cy, ang, 36);
  let ringInnerPts = ellipsePts(0, 0, 45, 45, cx, cy, ang, 36);
  let ringBand = ringOuterPts.concat(ringInnerPts.slice().reverse());
  xrayWash(ringBand, PAL.whitePure, Math.floor(155 * kResp));
  brush.set("xray_pen", PAL.whitePure, 1.35 * kResp);
  strokePoly(ringOuterPts, true, 0.15);
  strokePoly(ringInnerPts, true, 0.15);

  const threadHotspots = [
    { x: 48, y: -16, rx: 13, ry: 9, a: -18 },
    { x: 44, y: 21, rx: 13, ry: 9, a: 26 },
    { x: -12, y: 48, rx: 12, ry: 8, a: 76 },
    { x: -46, y: -22, rx: 12, ry: 8, a: -48 }
  ];
  for (let h of threadHotspots) {
    let wp = xform(h.x, h.y, cx, cy, ang);
    let hotPoly = ellipsePts(0, 0, h.rx, h.ry, wp[0], wp[1], ang + h.a, 14);
    xrayWash(hotPoly, PAL.whitePure, Math.floor(215 * kResp));
  }

  // 3. Full Key Bows & Serrated Blades Flaring Brightly
  const keys = [
    { kx: cx + 22, ky: cy - 12, kAng: ang - 18, sc: 1.05, style: "house", bitting: [2, 5, 1, 6, 3, 5, 2] },
    { kx: cx + 18, ky: cy + 16, kAng: ang + 26, sc: 1.12, style: "dimple", bitting: [3, 2, 4, 2, 5, 1] },
    { kx: cx - 16, ky: cy + 28, kAng: ang + 76, sc: 0.84, style: "small", bitting: [4, 1, 5, 2, 4] }
  ];

  for (let k of keys) {
    let bowPts = roundRectPts(-4 * k.sc, 0, 62 * k.sc, 58 * k.sc, 14 * k.sc, k.kx, k.ky, k.kAng, 5);
    let bladeLen = 128 * k.sc;
    let bladeW = 15 * k.sc;
    let bladeLocal = [
      [22 * k.sc, -bladeW],
      [bladeLen - 12 * k.sc, -bladeW],
      [bladeLen, -2 * k.sc],
      [bladeLen - 8 * k.sc, bladeW]
    ];
    let numTeeth = k.bitting.length;
    for (let i = numTeeth - 1; i >= 0; i--) {
      let tx = map(i, 0, numTeeth - 1, 42 * k.sc, bladeLen - 18 * k.sc);
      let depth = k.bitting[i] * 2.1 * k.sc;
      bladeLocal.push([tx + 5 * k.sc, bladeW]);
      bladeLocal.push([tx, bladeW - depth]);
      bladeLocal.push([tx - 5 * k.sc, bladeW]);
    }
    bladeLocal.push([22 * k.sc, bladeW]);
    let bladePts = bladeLocal.map((p) => xform(p[0], p[1], k.kx, k.ky, k.kAng));

    xrayWash(bowPts, PAL.milkBright, Math.floor(110 * kResp));
    xrayWash(bladePts, PAL.whitePure, Math.floor(125 * kResp));

    let holePts = ellipsePts(-17 * k.sc, 0, 9.5 * k.sc, 9.5 * k.sc, k.kx, k.ky, k.kAng, 16);
    xrayWash(holePts, PAL.bgIndigo, Math.floor(145 * kResp));

    brush.set("xray_pen", PAL.whitePure, 1.25 * kResp);
    strokePoly(bowPts, true, 0.1);
    strokePoly(bladePts, true, 0.03);
    strokePoly(holePts, true, 0.1);
  }

  brush.set("xray_bloom", PAL.cyanGlow, 1.75 * kResp);
  brush.circle(cx, cy, 115, 0.22);
  brush.set("xray_bloom", PAL.whitePure, 1.3 * kResp);
  brush.circle(cx, cy, 65, 0.18);
}

function drawReactingUmbrella(cx, cy, ang, scanX1, env1, scanX2, env2, globalPulse) {
  // 1. Pleated Nylon Canopy Folds & Central Shaft lighting up in sections as beam sweeps
  let umbResp = Math.max(globalPulse * 0.7, combinedExcitation(cx, scanX1, env1, scanX2, env2, 520, 110));
  if (umbResp > 0.05) {
    for (let lobe = -2; lobe <= 2; lobe += 2) {
      let yOff = lobe * 18;
      let len = 360 - Math.abs(lobe) * 14;
      let canopyFold = [
        xform(-len, yOff - 14, cx, cy, ang),
        xform(len - 40, yOff - 22, cx, cy, ang),
        xform(len + 10, yOff + 4, cx, cy, ang),
        xform(len - 35, yOff + 22, cx, cy, ang),
        xform(-len, yOff + 14, cx, cy, ang)
      ];
      xrayWash(canopyFold, PAL.cyanGlow, Math.floor(42 * umbResp));
    }

    let shaftOuter = roundRectPts(-20, 0, 820, 18, 2, cx, cy, ang);
    xrayWash(shaftOuter, PAL.milkBright, Math.floor(95 * umbResp));
  }

  // 2. 152 Internal Helical Compression Spring Coils blazing along the shaft
  let springStart = -365;
  let springEnd = 265;
  let numCoils = 152;
  for (let i = 0; i < numCoils; i += 2) {
    let x0 = lerp(springStart, springEnd, i / numCoils);
    let x1 = lerp(springStart, springEnd, (i + 1) / numCoils);
    let x2 = lerp(springStart, springEnd, (i + 2) / numCoils);
    let b0 = xform(x0, -6.5, cx, cy, ang);
    let resp = Math.max(globalPulse * 0.5, combinedExcitation(b0[0], scanX1, env1, scanX2, env2, 420, 85));
    if (resp < 0.1) continue;

    let b1 = xform(x1, 6.5, cx, cy, ang);
    let f1 = xform(x2, -6.5, cx, cy, ang);

    brush.set("xray_pen", PAL.whitePure, 0.95 + 0.65 * resp);
    brush.line(b0[0], b0[1], b1[0], b1[1]);
    brush.line(b1[0], b1[1], f1[0], f1[1]);
  }

  // 3. Slotted Metal Hubs, Handle Counterweight & Top Ferrule Cap
  const hubs = [
    { x: 355, w: 34, h: 48, bloom: true },
    { x: -95, w: 44, h: 52, bloom: true },
    { x: 145, w: 28, h: 42, bloom: true },
    { x: -190, w: 26, h: 21, bloom: false },
    { x: 95, w: 26, h: 21, bloom: false },
    { x: -378, w: 18, h: 52, bloom: true },
    { x: 395, w: 32, h: 18, bloom: false }
  ];

  for (let h of hubs) {
    let hW = xform(h.x, 0, cx, cy, ang);
    let hResp = Math.max(globalPulse * 0.65, combinedExcitation(hW[0], scanX1, env1, scanX2, env2, 460, 95));
    if (hResp < 0.08) continue;

    let hubPoly = roundRectPts(h.x, 0, h.w, h.h, 4, cx, cy, ang);
    xrayWash(hubPoly, PAL.whitePure, Math.floor(175 * hResp));
    brush.set("xray_pen", PAL.whitePure, 1.25 * hResp);
    strokePoly(hubPoly, true, 0.05);

    if (h.bloom) {
      brush.set("xray_bloom", PAL.whitePure, 1.2 * hResp);
      brush.circle(hW[0], hW[1], 64, 0.2);
    }
  }

  // 4. 8 Folded Steel Ribs, U-Channel Stretchers, Clevis Hinges & Bulbous Tips
  const ribOffsets = [-52, -37, -23, -11, 11, 24, 38, 53];
  for (let idx = 0; idx < ribOffsets.length; idx++) {
    let ry = ribOffsets[idx];
    let spreadTip = ry * 1.38;
    let midY = ry * 1.12;
    let tipX = -355 + (idx % 3) * 14;

    let rStart = xform(355, ry * 0.44, cx, cy, ang);
    let rMid = xform(125, midY, cx, cy, ang);
    let rFold = xform(-155, ry * 1.18, cx, cy, ang);
    let rTip = xform(tipX, spreadTip, cx, cy, ang);

    let ribResp = Math.max(
      globalPulse * 0.6,
      combinedExcitation(rMid[0], scanX1, env1, scanX2, env2, 460, 95),
      combinedExcitation(rFold[0], scanX1, env1, scanX2, env2, 460, 95)
    );
    if (ribResp > 0.08) {
      brush.set("xray_pencil", PAL.milkBright, 1.15 * ribResp);
      brush.spline([rStart, rMid, rFold, rTip], 0.18);
      brush.set("xray_pen", PAL.whitePure, 1.1 * ribResp);
      brush.spline([rStart, rMid, rFold, rTip], 0.18);

      let tipBulb = ellipsePts(tipX - 5, spreadTip, 7.5, 4.2, cx, cy, ang, 12);
      xrayWash(tipBulb, PAL.whitePure, Math.floor(195 * ribResp));
    }
  }
}

function drawReactingSmartphone(cx, cy, ang, scanX1, env1, scanX2, env2, globalPulse, u) {
  let phResp = Math.max(globalPulse * 0.7, combinedExcitation(cx, scanX1, env1, scanX2, env2, 500, 110));
  if (phResp < 0.05) return;

  const pw = 430;
  const ph = 216;

  // 1. Outer Aluminum Chassis, Battery Pouch & L-Shaped Logic Board lighting up brightly
  let outerChassis = roundRectPts(0, 0, pw, ph, 34, cx, cy, ang, 8);
  let battRect = roundRectPts(48, -32, 215, 112, 8, cx, cy, ang, 4);
  let pcbHoriz = roundRectPts(-15, 58, 285, 56, 4, cx, cy, ang);
  let pcbVert = roundRectPts(-115, -10, 74, 165, 4, cx, cy, ang);

  xrayWash(outerChassis, PAL.cyanGlow, Math.floor(62 * phResp));
  xrayWash(battRect, PAL.milkSoft, Math.floor(85 * phResp));
  xrayWash(pcbHoriz, PAL.cyanBright, Math.floor(88 * phResp));
  xrayWash(pcbVert, PAL.cyanBright, Math.floor(88 * phResp));

  brush.set("xray_pencil", PAL.whitePure, 1.45 * phResp);
  strokePoly(outerChassis, true, 0.08);
  brush.set("xray_pen", PAL.whitePure, 1.25 * phResp);
  strokePoly(outerChassis, true, 0.08);
  strokePoly(battRect, true, 0.05);

  // 2. Triple Camera Module Lenses & OIS Housings
  const lenses = [
    { x: -176, y: -68, r: 19 },
    { x: -176, y: -24, r: 19 },
    { x: -138, y: -46, r: 19 }
  ];
  for (let l of lenses) {
    let lW = xform(l.x, l.y, cx, cy, ang);
    let lResp = Math.max(globalPulse * 0.65, combinedExcitation(lW[0], scanX1, env1, scanX2, env2, 450, 90));
    if (lResp > 0.08) {
      let ring1 = ellipsePts(l.x, l.y, l.r, l.r, cx, cy, ang, 20);
      let ring2 = ellipsePts(l.x, l.y, l.r * 0.74, l.r * 0.74, cx, cy, ang, 16);
      xrayWash(ring1, PAL.milkBright, Math.floor(115 * lResp));
      xrayWash(ring2, PAL.whitePure, Math.floor(165 * lResp));
      brush.set("xray_pen", PAL.whitePure, 1.25 * lResp);
      strokePoly(ring1, true, 0.1);
      strokePoly(ring2, true, 0.1);
    }
  }

  // 3. 6 Silicon IC Packages & BGA Solder Ball Grids
  const icChips = [
    { x: -115, y: 12, w: 48, h: 48, bga: 6 },
    { x: -115, y: -42, w: 40, h: 34, bga: 5 },
    { x: -62, y: 58, w: 44, h: 36, bga: 5 },
    { x: -8, y: 58, w: 36, h: 32, bga: 4 },
    { x: 46, y: 58, w: 38, h: 34, bga: 5 },
    { x: 95, y: 58, w: 30, h: 28, bga: 4 }
  ];
  for (let ic of icChips) {
    let icW = xform(ic.x, ic.y, cx, cy, ang);
    let icResp = Math.max(globalPulse * 0.65, combinedExcitation(icW[0], scanX1, env1, scanX2, env2, 440, 85));
    if (icResp < 0.08) continue;

    let chipPoly = roundRectPts(ic.x, ic.y, ic.w, ic.h, 2, cx, cy, ang);
    let diePoly = roundRectPts(ic.x, ic.y, ic.w * 0.68, ic.h * 0.68, 1, cx, cy, ang);
    xrayWash(chipPoly, PAL.milkBright, Math.floor(110 * icResp));
    xrayWash(diePoly, PAL.whitePure, Math.floor(155 * icResp));
    brush.set("xray_pen", PAL.whitePure, 1.15 * icResp);
    strokePoly(chipPoly, true, 0.02);
    strokePoly(diePoly, true, 0.02);
  }

  // 4. MagSafe Ring of 18 Rare-Earth Magnets & Planar Copper Induction Coil
  const coilCX = 5, coilCY = -5;
  let coilW = xform(coilCX, coilCY, cx, cy, ang);
  let cResp = Math.max(globalPulse * 0.7, combinedExcitation(coilW[0], scanX1, env1, scanX2, env2, 470, 95));
  if (cResp > 0.06) {
    let coilDisc = ellipsePts(coilCX, coilCY, 68, 68, cx, cy, ang, 32);
    xrayWash(coilDisc, PAL.milkBright, Math.floor(95 * cResp));

    let numMags = 18;
    for (let m = 0; m < numMags; m++) {
      let a0 = (m * 360) / numMags + 2.5;
      let a1 = ((m + 1) * 360) / numMags - 2.5;
      if (a0 > 165 && a1 < 195) continue;
      let magPts = [
        xform(coilCX + cos(a0) * 58, coilCY + sin(a0) * 58, cx, cy, ang),
        xform(coilCX + cos(a0) * 68, coilCY + sin(a0) * 68, cx, cy, ang),
        xform(coilCX + cos(a1) * 68, coilCY + sin(a1) * 68, cx, cy, ang),
        xform(coilCX + cos(a1) * 58, coilCY + sin(a1) * 58, cx, cy, ang)
      ];
      xrayWash(magPts, PAL.whitePure, Math.floor(175 * cResp));
      brush.set("xray_pen", PAL.whitePure, 1.1 * cResp);
      strokePoly(magPts, true, 0.02);
    }

    // Rotating induced current wave around the spiral coil
    let spiralPts = [];
    let totalTurns = 10;
    let stepsPerTurn = 18;
    for (let s = 0; s <= totalTurns * stepsPerTurn; s++) {
      let t = s / (totalTurns * stepsPerTurn);
      let r = lerp(20, 53, t);
      let theta = s * (360 / stepsPerTurn) + u * 720;
      spiralPts.push(xform(coilCX + cos(theta) * r, coilCY + sin(theta) * r, cx, cy, ang));
    }
    brush.set("xray_pen", PAL.whitePure, 1.05 * cResp);
    strokePoly(spiralPts, false, 0.15);

    brush.set("xray_bloom", PAL.cyanGlow, 1.8 * cResp);
    brush.circle(coilW[0], coilW[1], 125, 0.22);
    brush.set("xray_bloom", PAL.whitePure, 1.35 * cResp);
    brush.circle(coilW[0], coilW[1], 68, 0.18);
  }

  // 5. Taptic Engine Tungsten Mass & USB-C Port
  let tapW = xform(155, 52, cx, cy, ang);
  let tapResp = Math.max(globalPulse * 0.65, combinedExcitation(tapW[0], scanX1, env1, scanX2, env2, 450, 90));
  if (tapResp > 0.08) {
    let tungstenMass = roundRectPts(155, 52, 42, 26, 2, cx, cy, ang);
    let usbShell = roundRectPts(196, 0, 28, 24, 3, cx, cy, ang);
    xrayWash(tungstenMass, PAL.whitePure, Math.floor(210 * tapResp));
    xrayWash(usbShell, PAL.whitePure, Math.floor(185 * tapResp));
    brush.set("xray_pen", PAL.whitePure, 1.25 * tapResp);
    strokePoly(tungstenMass, true, 0.04);
    strokePoly(usbShell, true, 0.04);
  }
}

function drawReactingCoins(bagCX, bagCY, bagAngle, scanX1, env1, scanX2, env2, globalPulse) {
  const coins = [
    { lx: -65, ly: 295, rx: 35, ry: 31, rot: -15, bimetallic: true },
    { lx: -25, ly: 312, rx: 31, ry: 27, rot: 22, bimetallic: false },
    { lx: 85, ly: 325, rx: 37, ry: 22, rot: -8, bimetallic: true },
    { lx: 122, ly: 335, rx: 28, ry: 25, rot: 35, bimetallic: false },
    { lx: 215, ly: 305, rx: 33, ry: 16, rot: -22, bimetallic: false },
    { lx: -165, ly: 275, rx: 26, ry: 24, rot: 12, bimetallic: false }
  ];

  let coinWorldCenters = [];

  for (let c of coins) {
    let wc = xform(c.lx, c.ly, bagCX, bagCY, bagAngle);
    let totalAng = bagAngle + c.rot;
    coinWorldCenters.push({ wc, rx: c.rx, ry: c.ry, ang: totalAng });

    let cResp = Math.max(globalPulse * 0.7, combinedExcitation(wc[0], scanX1, env1, scanX2, env2, 460, 95));
    if (cResp < 0.06) continue;

    let haloPts = ellipsePts(0, 0, c.rx * 1.35, c.ry * 1.35, wc[0], wc[1], totalAng, 24);
    let outerPts = ellipsePts(0, 0, c.rx, c.ry, wc[0], wc[1], totalAng, 30);
    xrayWash(haloPts, PAL.cyanGlow, Math.floor(65 * cResp));
    xrayWash(outerPts, PAL.milkBright, Math.floor(135 * cResp));

    if (c.bimetallic) {
      let coreInner = ellipsePts(0, 0, c.rx * 0.63, c.ry * 0.63, wc[0], wc[1], totalAng, 22);
      xrayWash(coreInner, PAL.whitePure, Math.floor(155 * cResp));
      brush.set("xray_pen", PAL.whitePure, 1.15 * cResp);
      strokePoly(coreInner, true, 0.1);
    }

    brush.set("xray_pen", PAL.whitePure, 1.3 * cResp);
    strokePoly(outerPts, true, 0.1);
  }

  // Incandescent white lens-shaped coin overlaps
  const overlapPairs = [
    [0, 1],
    [2, 3]
  ];
  for (let pair of overlapPairs) {
    let cA = coinWorldCenters[pair[0]];
    let cB = coinWorldCenters[pair[1]];
    let midX = (cA.wc[0] + cB.wc[0]) * 0.5;
    let midY = (cA.wc[1] + cB.wc[1]) * 0.5;
    let oResp = Math.max(globalPulse * 0.75, combinedExcitation(midX, scanX1, env1, scanX2, env2, 480, 100));
    if (oResp < 0.06) continue;

    let lensHalo = ellipsePts(0, 0, 26, 26, midX, midY, 0, 20);
    xrayWash(lensHalo, PAL.whitePure, Math.floor(175 * oResp));
    brush.set("xray_bloom", PAL.whitePure, 1.35 * oResp);
    brush.circle(midX, midY, 58, 0.18);
  }
}

function drawReactingZippersAndHardware(cx, cy, ang, scanX1, env1, scanX2, env2, globalPulse) {
  const tracks = [
    { xStart: -515, xEnd: 495, yBase: -292, sliderX: 185, numTeeth: 165, sc: 1.15 },
    { xStart: -245, xEnd: 225, yBase: -135, sliderX: -135, numTeeth: 92, sc: 0.82 }
  ];

  for (let tr of tracks) {
    // Zipper tape glow
    let tapePts = [];
    for (let i = 0; i <= 24; i++) {
      let lx = lerp(tr.xStart, tr.xEnd, i / 24);
      let curveY = tr.yBase + Math.sin((i / 24) * Math.PI) * 18 * tr.sc;
      tapePts.push(xform(lx, curveY - 16 * tr.sc, cx, cy, ang));
    }
    for (let i = 24; i >= 0; i--) {
      let lx = lerp(tr.xStart, tr.xEnd, i / 24);
      let curveY = tr.yBase + Math.sin((i / 24) * Math.PI) * 18 * tr.sc;
      tapePts.push(xform(lx, curveY + 16 * tr.sc, cx, cy, ang));
    }
    xrayWash(tapePts, PAL.cyanGlow, Math.floor(48 * Math.max(env1, env2)));

    // Zipper teeth flaring in sequence across the wide wake
    for (let i = 0; i < tr.numTeeth; i += 2) {
      let t = i / (tr.numTeeth - 1);
      let lx = lerp(tr.xStart, tr.xEnd, t);
      let curveY = tr.yBase + Math.sin(t * Math.PI) * 18 * tr.sc;
      let wCenter = xform(lx, curveY, cx, cy, ang);
      let resp = Math.max(globalPulse * 0.55, combinedExcitation(wCenter[0], scanX1, env1, scanX2, env2, 420, 85));
      if (resp < 0.1) continue;

      let pBase = xform(lx, curveY - 7 * tr.sc, cx, cy, ang);
      let pTip = xform(lx, curveY + 7 * tr.sc, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, (0.95 + 0.65 * resp) * tr.sc);
      brush.line(pBase[0], pBase[1], pTip[0], pTip[1]);
    }

    // Zipper Slider & Pull Tab
    let sT = (tr.sliderX - tr.xStart) / (tr.xEnd - tr.xStart);
    let sliderY = tr.yBase + Math.sin(sT * Math.PI) * 18 * tr.sc;
    let sliderW = xform(tr.sliderX, sliderY, cx, cy, ang);
    let sResp = Math.max(globalPulse * 0.7, combinedExcitation(sliderW[0], scanX1, env1, scanX2, env2, 460, 95));
    if (sResp > 0.06) {
      let sliderBody = [
        xform(tr.sliderX - 18 * tr.sc, sliderY - 11 * tr.sc, cx, cy, ang),
        xform(tr.sliderX + 18 * tr.sc, sliderY - 15 * tr.sc, cx, cy, ang),
        xform(tr.sliderX + 20 * tr.sc, sliderY + 15 * tr.sc, cx, cy, ang),
        xform(tr.sliderX - 18 * tr.sc, sliderY + 11 * tr.sc, cx, cy, ang)
      ];
      xrayWash(sliderBody, PAL.whitePure, Math.floor(185 * sResp));
      brush.set("xray_pen", PAL.whitePure, 1.3 * tr.sc * sResp);
      strokePoly(sliderBody, true, 0.08);

      let pullTab = roundRectPts(26 * tr.sc, 0, 48 * tr.sc, 20 * tr.sc, 7 * tr.sc, sliderW[0], sliderW[1], ang + 52, 5);
      xrayWash(pullTab, PAL.whitePure, Math.floor(145 * sResp));
      strokePoly(pullTab, true, 0.08);
    }
  }

  // Handle Anchor D-Rings, Center Magnetic Snap & Bottom Base Studs
  let snapW = xform(0, -215, cx, cy, ang);
  let snapResp = Math.max(globalPulse * 0.7, combinedExcitation(snapW[0], scanX1, env1, scanX2, env2, 460, 95));
  if (snapResp > 0.06) {
    let magOuter = ellipsePts(0, -215, 24, 24, cx, cy, ang, 22);
    xrayWash(magOuter, PAL.whitePure, Math.floor(165 * snapResp));
    brush.set("xray_pen", PAL.whitePure, 1.25 * snapResp);
    strokePoly(magOuter, true, 0.1);
  }

  for (let side of [-1, 1]) {
    let hx = side * 265, hy = -285;
    let hW = xform(hx, hy + 10, cx, cy, ang);
    let hResp = Math.max(globalPulse * 0.7, combinedExcitation(hW[0], scanX1, env1, scanX2, env2, 460, 95));
    if (hResp > 0.06) {
      let dOuter = ellipsePts(hx, hy + 6, 32, 34, cx, cy, ang, 18, 180, 360);
      let dInner = ellipsePts(hx, hy + 6, 21, 23, cx, cy, ang, 18, 180, 360);
      let dRingPoly = dOuter.concat(dInner.slice().reverse());
      xrayWash(dRingPoly, PAL.whitePure, Math.floor(175 * hResp));
      brush.set("xray_pen", PAL.whitePure, 1.3 * hResp);
      strokePoly(dRingPoly, true, 0.1);
    }
  }

  for (let sx of [-410, -145, 145, 410]) {
    let stW = xform(sx, 455, cx, cy, ang);
    let stResp = Math.max(globalPulse * 0.7, combinedExcitation(stW[0], scanX1, env1, scanX2, env2, 460, 95));
    if (stResp > 0.06) {
      let dome = ellipsePts(sx, 463, 22, 11, cx, cy, ang, 18);
      xrayWash(dome, PAL.whitePure, Math.floor(165 * stResp));
      brush.set("xray_pen", PAL.whitePure, 1.2 * stResp);
      strokePoly(dome, true, 0.1);
    }
  }
}

function drawScannerCalibrationHUD(scanX1, env1, scanX2, env2, globalPulse, u, k) {
  // Top and bottom sliding tracking reticles for active beams
  const beams = [
    { x: scanX1, e: env1 },
    { x: scanX2, e: env2 }
  ];
  for (let b of beams) {
    if (b.e < 0.05 || b.x < 0 || b.x > 1200) continue;
    for (let edgeY of [26, 1174]) {
      let dir = edgeY < 600 ? 1 : -1;
      brush.set("xray_pen", PAL.whitePure, 1.3 * b.e);
      brush.line(b.x - 24, edgeY, b.x + 24, edgeY);
      brush.line(b.x, edgeY, b.x, edgeY + dir * 18);
      brush.line(b.x - 10, edgeY, b.x - 10, edgeY + dir * 9);
      brush.line(b.x + 10, edgeY, b.x + 10, edgeY + dir * 9);
    }
  }

  // Calibration scales and corner crosshairs pulsing with the scanner sweep
  let hudGlow = Math.max(env1, env2, globalPulse);
  for (let t = 0; t <= 40; t += 2) {
    let pos = 45 + t * 8;
    let len = t % 10 === 0 ? 16 : t % 5 === 0 ? 11 : 6;
    brush.set("xray_pen", t % 10 === 0 ? PAL.whitePure : PAL.milkBright, 0.9 * hudGlow);
    brush.line(1182 - len, pos, 1182, pos);
    brush.line(pos, 1182 - len, pos, 1182);
  }

  const crosshairs = [
    [38, 38],
    [1162, 38],
    [38, 1162],
    [1162, 1162]
  ];
  for (let ch of crosshairs) {
    brush.set("xray_pen", PAL.whitePure, 0.95 * hudGlow);
    brush.line(ch[0] - 12, ch[1], ch[0] + 12, ch[1]);
    brush.line(ch[0], ch[1] - 12, ch[0], ch[1] + 12);
  }
}

// =============================================================================
// 1. PRUSSIAN BLUE-BLACK CHARCOAL GROUND
// =============================================================================
function drawPrussianCharcoalGround() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Deep base washes in Prussian blue-black
  let fullRect = [[0, 0], [1200, 0], [1200, 1200], [0, 1200]];
  xrayWash(fullRect, PAL.bgPrussian, 220);

  // Layered charcoal mass zones building rich darkroom depth
  const charcoalZones = [
    { x: -80, y: -80, w: 720, h: 720, col: "#051020", str: 0.7 },
    { x: 520, y: -60, w: 740, h: 700, col: "#030b17", str: 0.65 },
    { x: -60, y: 520, w: 740, h: 740, col: "#030914", str: 0.7 },
    { x: 500, y: 500, w: 760, h: 760, col: "#061427", str: 0.75 },
    { x: 180, y: 160, w: 840, h: 880, col: "#081b33", str: 0.55 }
  ];

  for (let z of charcoalZones) {
    let pts = [
      [z.x, z.y],
      [z.x + z.w, z.y + random(-25, 25)],
      [z.x + z.w, z.y + z.h],
      [z.x + random(-25, 25), z.y + z.h]
    ];
    let p = new brush.Polygon(pts);
    p.wash(z.col, 110);
  }

  // Charcoal mass passes for dry-pigment velvet texture in the darks
  brush.noStroke();
  brush.noFill();
  const massPatches = [
    [[0, 0], [650, 0], [580, 620], [0, 580]],
    [[550, 0], [1200, 0], [1200, 660], [600, 590]],
    [[0, 540], [620, 590], [660, 1200], [0, 1200]],
    [[580, 570], [1200, 620], [1200, 1200], [560, 1200]]
  ];
  for (let i = 0; i < massPatches.length; i++) {
    brush.mass("charcoal", i % 2 === 0 ? "#030812" : "#071629", {
      precision: 0.35,
      strength: 0.45,
      gradient: 0.25,
      outline: false
    });
    let poly = new brush.Polygon(massPatches[i]);
    poly.mass();
  }
  brush.noMass();

  // Cross-hatched charcoal grain across the canvas
  let canvasPoly = new brush.Polygon(fullRect);
  brush.hatchStyle("charcoal", "#091d36", 0.9);
  canvasPoly.hatch(18, -27, { rand: 0.12 });
  brush.hatchStyle("charcoal", "#02060c", 1.1);
  canvasPoly.hatch(22, 63, { rand: 0.15 });
  brush.noHatch();

  // Subtle airport scanner linear sweep bands (ghostly detector lines)
  for (let i = 0; i < 65; i++) {
    let y = map(i, 0, 64, 10, 1190) + random(-4, 4);
    let col = i % 3 === 0 ? "#0c2540" : "#02070f";
    brush.set("charcoal", col, random(0.4, 1.1));
    brush.line(0, y, 1200, y + random(-3, 3));
  }
}

// =============================================================================
// 2. HANDBAG LEATHER STRUCTURE, GUSSETS, SEAMS & HANDLES
// =============================================================================
function drawHandbagStructure(cx, cy, ang) {
  // Outer trapezoidal silhouette of the handbag (bleeding past canvas corners)
  let bagOuter = [
    xform(-520, -340, cx, cy, ang),
    xform(520, -340, cx, cy, ang),
    xform(650, 410, cx, cy, ang),
    xform(590, 465, cx, cy, ang),
    xform(-590, 465, cx, cy, ang),
    xform(-650, 410, cx, cy, ang)
  ];

  // Soft radiographic bloom outside the bag edges
  xrayBloomPoly(bagOuter, cx, cy, PAL.veilDark, 24, 4, 1.08);

  // Main leather body density washes (layered translucent Prussian-cyan)
  xrayWash(bagOuter, PAL.veilDark, 55);
  xrayWash(bagOuter, PAL.veilMid, 28);

  // Watercolor texture pass for organic supple leather variation
  brush.noStroke();
  brush.fill(PAL.veilMid, 38);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.55, 0.35);
  brush.beginShape(0.15);
  for (let p of bagOuter) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Side folded leather gussets (where leather folds 3x thick, X-ray density increases)
  let leftGusset = [
    xform(-520, -340, cx, cy, ang),
    xform(-390, -310, cx, cy, ang),
    xform(-430, 120, cx, cy, ang),
    xform(-590, 465, cx, cy, ang),
    xform(-650, 410, cx, cy, ang)
  ];
  let rightGusset = [
    xform(520, -340, cx, cy, ang),
    xform(390, -310, cx, cy, ang),
    xform(430, 120, cx, cy, ang),
    xform(590, 465, cx, cy, ang),
    xform(650, 410, cx, cy, ang)
  ];
  xrayWash(leftGusset, PAL.veilLight, 38);
  xrayWash(rightGusset, PAL.veilLight, 38);

  // Inner gusset V-pleat triangles
  let leftPleat = [
    xform(-510, -330, cx, cy, ang),
    xform(-445, -40, cx, cy, ang),
    xform(-595, 390, cx, cy, ang)
  ];
  let rightPleat = [
    xform(510, -330, cx, cy, ang),
    xform(445, -40, cx, cy, ang),
    xform(595, 390, cx, cy, ang)
  ];
  xrayWash(leftPleat, PAL.cyanLow, 35);
  xrayWash(rightPleat, PAL.cyanLow, 35);

  // Reinforced bottom leather base board (foreshortened elliptical/rectangular panel)
  let bottomPanel = [
    xform(-590, 465, cx, cy, ang),
    xform(-480, 355, cx, cy, ang),
    xform(480, 355, cx, cy, ang),
    xform(590, 465, cx, cy, ang),
    xform(490, 520, cx, cy, ang),
    xform(-490, 520, cx, cy, ang)
  ];
  xrayWash(bottomPanel, PAL.veilLight, 48);
  xrayWash(bottomPanel, PAL.cyanLow, 26);

  // Top folded leather collar / facing reinforcement strip
  let topCollar = [
    xform(-525, -340, cx, cy, ang),
    xform(525, -340, cx, cy, ang),
    xform(542, -235, cx, cy, ang),
    xform(-542, -235, cx, cy, ang)
  ];
  xrayWash(topCollar, PAL.veilLight, 45);
  xrayWash(topCollar, PAL.cyanLow, 24);

  // Internal hanging zippered pocket (translucent lining fabric + leather trim)
  let innerPocket = [
    xform(-290, -175, cx, cy, ang),
    xform(270, -175, cx, cy, ang),
    xform(285, 195, cx, cy, ang),
    xform(-275, 195, cx, cy, ang)
  ];
  xrayWash(innerPocket, PAL.veilLight, 30);

  let pocketWelt = roundRectPts(-10, -135, 510, 42, 6, cx, cy, ang);
  xrayWash(pocketWelt, PAL.cyanLow, 42);

  // Fine grain hatching over leather panels to convey natural hide texture in radiograph
  let outerPoly = new brush.Polygon(bagOuter);
  brush.hatchStyle("2B", PAL.veilLight, 0.45);
  outerPoly.hatch(14, ang + 2, { rand: 0.08 });
  brush.hatchStyle("2B", PAL.veilMid, 0.4);
  outerPoly.hatch(19, ang + 88, { rand: 0.1 });
  brush.noHatch();

  // Rolled leather piping along edges (thick leather welt cord inside folded edge)
  drawLeatherPiping(
    [
      [-520, -340],
      [-585, 35],
      [-645, 405],
      [-585, 465],
      [0, 480],
      [585, 465],
      [645, 405],
      [585, 35],
      [520, -340]
    ],
    cx,
    cy,
    ang
  );

  // Gusset fold crease ridges
  drawGlowingCrease([[-520, -340], [-440, -30], [-585, 465]], cx, cy, ang, 1.2);
  drawGlowingCrease([[520, -340], [440, -30], [585, 465]], cx, cy, ang, 1.2);
  drawGlowingCrease([[-590, 465], [-475, 355], [475, 355], [590, 465]], cx, cy, ang, 1.0);
  drawGlowingCrease([[-540, -235], [0, -225], [540, -235]], cx, cy, ang, 0.9);

  // Double-stitched needle perforations & thread dashes along structural seams
  drawStitchLine([-512, -330], [-632, 402], cx, cy, ang, 68);
  drawStitchLine([-504, -330], [-624, 402], cx, cy, ang, 68);
  drawStitchLine([512, -330], [632, 402], cx, cy, ang, 68);
  drawStitchLine([504, -330], [624, 402], cx, cy, ang, 68);
  drawStitchLine([-535, -242], [535, -242], cx, cy, ang, 95);
