    drawStitchLine([sx + 22, -250], [sx + 27, 455], cx, cy, ang, 64);
  }

  // Rolled Leather Handles arching out the top of the bag (cropped at canvas edges)
  drawRolledHandle(cx, cy, ang, -265, 265, -295, -760);
  // Second handle falling slightly forward in ghostly overlap
  drawRolledHandle(cx, cy, ang, -265, 265, -285, -630, 55);

  // Metal Base Studs (feet) on bottom panel seen in X-ray with internal screw posts
  const studPositions = [-410, -145, 145, 410];
  for (let sx of studPositions) {
    drawMetalBaseStud(sx, 455, cx, cy, ang);
  }
}

function drawLeatherPiping(localPts, cx, cy, ang) {
  let wPts = localPts.map((p) => xform(p[0], p[1], cx, cy, ang));
  // Soft outer glow
  brush.set("xray_shader", PAL.cyanLow, 2.2);
  brush.spline(wPts, 0.25);
  // Dense folded leather rim
  brush.set("xray_pencil", PAL.cyanBright, 1.3);
  brush.spline(wPts, 0.25);
  // Internal cotton/plastic piping core wire
  brush.set("xray_pen", PAL.milkSoft, 0.8);
  brush.spline(wPts, 0.25);
}

function drawGlowingCrease(localPts, cx, cy, ang, weight = 1.0) {
  let wPts = localPts.map((p) => xform(p[0], p[1], cx, cy, ang));
  brush.set("xray_shader", PAL.cyanLow, 1.6 * weight);
  brush.spline(wPts, 0.3);
  brush.set("xray_pencil", PAL.cyanBright, 0.85 * weight);
  brush.spline(wPts, 0.3);
}

function drawStitchLine(p0, p1, cx, cy, ang, count) {
  for (let i = 0; i < count; i++) {
    let t0 = i / count;
    let t1 = (i + 0.55) / count;
    let x0 = lerp(p0[0], p1[0], t0);
    let y0 = lerp(p0[1], p1[1], t0);
    let x1 = lerp(p0[0], p1[0], t1);
    let y1 = lerp(p0[1], p1[1], t1);
    let w0 = xform(x0, y0, cx, cy, ang);
    let w1 = xform(x1, y1, cx, cy, ang);
    brush.set("xray_pen", PAL.cyanGlow, 0.65);
    brush.line(w0[0], w0[1], w1[0], w1[1]);
  }
}

function drawRolledHandle(cx, cy, ang, xLeft, xRight, yBase, yPeak, xSkew = -20) {
  let steps = 42;
  let outerWall = [];
  let innerWall = [];
  let coreCenter = [];
  let tubeHalf = 19;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Cubic Bezier arch in local bag coordinates
    let u = 1 - t;
    let px =
      u * u * u * xLeft +
      3 * u * u * t * (xLeft * 1.08 + xSkew) +
      3 * u * t * t * (xRight * 1.08 + xSkew) +
      t * t * t * xRight;
    let py =
      u * u * u * yBase +
      3 * u * u * t * yPeak +
      3 * u * t * t * yPeak +
      t * t * t * yBase;

    // Approximate tangent for normal offset
    let dt = 0.01;
    let t2 = Math.min(1, t + dt);
    let u2 = 1 - t2;
    let px2 =
      u2 * u2 * u2 * xLeft +
      3 * u2 * u2 * t2 * (xLeft * 1.08 + xSkew) +
      3 * u2 * t2 * t2 * (xRight * 1.08 + xSkew) +
      t2 * t2 * t2 * xRight;
    let py2 =
      u2 * u2 * u2 * yBase +
      3 * u2 * u2 * t2 * yPeak +
      3 * u2 * t2 * t2 * yPeak +
      t2 * t2 * t2 * yBase;

    let dx = px2 - px;
    let dy = py2 - py;
    let len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    outerWall.push(xform(px + nx * tubeHalf, py + ny * tubeHalf, cx, cy, ang));
    innerWall.unshift(xform(px - nx * tubeHalf, py - ny * tubeHalf, cx, cy, ang));
    coreCenter.push(xform(px, py, cx, cy, ang));
  }

  let tubePoly = outerWall.concat(innerWall);
  xrayWash(tubePoly, PAL.veilLight, 50);
  xrayWash(tubePoly, PAL.cyanLow, 30);

  // Bright tangential X-ray walls of the rolled leather tube
  brush.set("xray_pencil", PAL.cyanGlow, 1.15);
  strokePoly(outerWall, false, 0.2);
  strokePoly(innerWall, false, 0.2);

  // Internal twisted cord core inside the rolled leather handle
  brush.set("xray_pen", PAL.milkSoft, 0.7);
  strokePoly(coreCenter, false, 0.2);
}

function drawMetalBaseStud(lx, ly, cx, cy, ang) {
  let dome = ellipsePts(lx, ly + 8, 22, 11, cx, cy, ang, 24);
  let washer = ellipsePts(lx, ly - 8, 17, 7, cx, cy, ang, 20);
  let post = roundRectPts(lx, ly, 10, 20, 2, cx, cy, ang, 3);

  xrayBloomPoly(dome, dome[0][0], dome[0][1], PAL.cyanBright, 30, 3, 1.3);
  xrayWash(dome, PAL.milkSoft, 130);
  xrayWash(washer, PAL.cyanGlow, 110);
  xrayWash(post, PAL.whitePure, 170);

  brush.set("xray_pen", PAL.whitePure, 0.85);
  strokePoly(dome, true, 0.1);
  strokePoly(washer, true, 0.1);
  // Internal screw threads on the stud post
  for (let i = -6; i <= 6; i += 3) {
    let p0 = xform(lx - 5, ly + i, cx, cy, ang);
    let p1 = xform(lx + 5, ly + i + 1, cx, cy, ang);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

