// =============================================================================
// 4. FOLDED TELESCOPIC UMBRELLA (SHAFT, SPRING, RIBS, STRETCHERS, CANOPY)
// =============================================================================
function drawFoldedUmbrella(cx, cy, ang) {
  // A. Ghostly pleated nylon canopy folds enveloping the ribs
  for (let lobe = -3; lobe <= 3; lobe++) {
    let yOff = lobe * 18;
    let len = 360 - Math.abs(lobe) * 14;
    let canopyFold = [
      xform(-len, yOff - 14, cx, cy, ang),
      xform(len - 40, yOff - 22, cx, cy, ang),
      xform(len + 10, yOff + 4, cx, cy, ang),
      xform(len - 35, yOff + 22, cx, cy, ang),
      xform(-len, yOff + 14, cx, cy, ang)
    ];
    xrayWash(canopyFold, PAL.veilLight, 24);
    if (lobe % 2 === 0) {
      xrayWash(canopyFold, PAL.cyanLow, 18);
    }
    brush.set("xray_pencil", PAL.cyanMid, 0.55);
    strokePoly(canopyFold, true, 0.25);
  }

  // Wrapping strap around umbrella middle with metallic snap fastener (ring-spring visible)
  let strapBand = roundRectPts(15, 0, 58, 128, 8, cx, cy, ang);
  xrayWash(strapBand, PAL.cyanLow, 38);
  brush.set("xray_pencil", PAL.cyanBright, 0.65);
  strokePoly(strapBand, true, 0.1);
  drawStitchLine([38, -60], [38, 60], cx, cy, ang, 18);
  drawStitchLine([-8, -60], [-8, 60], cx, cy, ang, 18);

  // Snap fastener on umbrella strap (double concentric brass ring + S-spring wire)
  let snapOuter = ellipsePts(16, 22, 14, 14, cx, cy, ang, 24);
  let snapInner = ellipsePts(16, 22, 7, 7, cx, cy, ang, 18);
  xrayWash(snapOuter, PAL.cyanGlow, 95);
  xrayWash(snapInner, PAL.whitePure, 130);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(snapOuter, true, 0.1);
  strokePoly(snapInner, true, 0.1);

  // B. Central Telescopic Steel/Aluminum Shaft (3 nested concentric tubes)
  let shaftOuter = roundRectPts(-20, 0, 820, 18, 2, cx, cy, ang);
  let shaftInner = roundRectPts(-60, 0, 680, 12, 1, cx, cy, ang);
  xrayWash(shaftOuter, PAL.cyanMid, 75);
  xrayWash(shaftInner, PAL.cyanGlow, 65);

  // Bright tangential tube walls (X-ray grazing incidence on hollow metal cylinders)
  for (let yWall of [-9, -6, 6, 9]) {
    let p0 = xform(-430, yWall, cx, cy, ang);
    let p1 = xform(390, yWall, cx, cy, ang);
    brush.set("xray_pen", Math.abs(yWall) === 9 ? PAL.milkBright : PAL.whitePure, 0.95);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Telescopic joint collars (double-thickness metal sleeves)
  for (let jx of [-190, 95]) {
    let collar = roundRectPts(jx, 0, 26, 21, 2, cx, cy, ang);
    xrayWash(collar, PAL.whitePure, 155);
    brush.set("xray_pen", PAL.whitePure, 0.9);
    strokePoly(collar, true, 0.05);
  }

  // C. Internal Helical Compression Spring inside the telescopic shaft (155 tight coils!)
  let springStart = -365;
  let springEnd = 265;
  let numCoils = 152;
  for (let i = 0; i < numCoils; i++) {
    let x0 = lerp(springStart, springEnd, i / numCoils);
    let x1 = lerp(springStart, springEnd, (i + 0.5) / numCoils);
    let x2 = lerp(springStart, springEnd, (i + 1) / numCoils);
    // Back coil diagonal
    let b0 = xform(x0, -6.5, cx, cy, ang);
    let b1 = xform(x1, 6.5, cx, cy, ang);
    brush.set("xray_pen", PAL.cyanGlow, 0.65);
    brush.line(b0[0], b0[1], b1[0], b1[1]);
    // Front coil diagonal
    let f0 = xform(x1, 6.5, cx, cy, ang);
    let f1 = xform(x2, -6.5, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 0.85);
    brush.line(f0[0], f0[1], f1[0], f1[1]);
    // Specular crest dot where coil wire turns tangentially to the X-ray beam
    brush.set("xray_pen", PAL.whitePure, 1.15);
    brush.line(b0[0], b0[1], b0[0] + 0.8, b0[1] + 0.8);
    brush.line(f0[0], f0[1], f0[0] + 0.8, f0[1] + 0.8);
  }

  // Internal locking catch pawl & micro-spring at shaft handle end
  let pawlPts = [
    xform(-310, -8, cx, cy, ang),
    xform(-288, -14, cx, cy, ang),
    xform(-285, -3, cx, cy, ang)
  ];
  xrayWash(pawlPts, PAL.whitePure, 180);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(pawlPts, true, 0.02);

  // D. Upper Crown Hub & Sliding Runner Hub (dense slotted metal rings with wire bindings)
  const hubs = [
    { x: 355, w: 34, h: 48, slots: 8 }, // Top crown notch
    { x: -95, w: 44, h: 52, slots: 8 }, // Main sliding runner
    { x: 145, w: 28, h: 42, slots: 8 }  // Secondary stretcher hub
  ];
  for (let h of hubs) {
    let hubPoly = roundRectPts(h.x, 0, h.w, h.h, 5, cx, cy, ang);
    xrayBloomPoly(hubPoly, hubPoly[0][0], hubPoly[0][1], PAL.cyanBright, 35, 3, 1.35);
    xrayWash(hubPoly, PAL.milkBright, 145);
    brush.set("xray_pen", PAL.whitePure, 1.0);
    strokePoly(hubPoly, true, 0.05);

    // Circumferential wire tie rings that hinge the ribs in the notch
    for (let ringOff of [-h.w * 0.28, h.w * 0.28]) {
      for (let s = 0; s < h.slots; s++) {
        let sy = map(s, 0, h.slots - 1, -h.h * 0.44, h.h * 0.44);
        let clevis = ellipsePts(h.x + ringOff, sy, 3.2, 2.2, cx, cy, ang, 10);
        xrayWash(clevis, PAL.whitePure, 210);
      }
      let pTop = xform(h.x + ringOff, -h.h * 0.48, cx, cy, ang);
      let pBot = xform(h.x + ringOff, h.h * 0.48, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, 1.15);
      brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
    }
  }

  // E. Bundle of 8 Folded Steel Ribs, Hinged U-Channel Stretchers & Clevis Rivets
  const ribOffsets = [-52, -37, -23, -11, 11, 24, 38, 53];
  for (let idx = 0; idx < ribOffsets.length; idx++) {
    let ry = ribOffsets[idx];
    let spreadTip = ry * 1.38;
    let midY = ry * 1.12;

    // 1. Primary stretcher bar from sliding runner (-95) to mid-rib joint (125)
    let st0 = xform(-90, ry * 0.42, cx, cy, ang);
    let st1 = xform(125, midY, cx, cy, ang);
    // U-channel stretcher has double bright edge lines
    let stTop0 = xform(-90, ry * 0.42 - 1.8, cx, cy, ang);
    let stTop1 = xform(125, midY - 1.8, cx, cy, ang);
    let stBot0 = xform(-90, ry * 0.42 + 1.8, cx, cy, ang);
    let stBot1 = xform(125, midY + 1.8, cx, cy, ang);

    brush.set("xray_pencil", PAL.cyanGlow, 0.9);
    brush.line(st0[0], st0[1], st1[0], st1[1]);
    brush.set("xray_pen", PAL.milkBright, 0.75);
    brush.line(stTop0[0], stTop0[1], stTop1[0], stTop1[1]);
    brush.line(stBot0[0], stBot0[1], stBot1[0], stBot1[1]);

    // 2. Main long rib from top crown (355) back toward handle (-345)
    let rStart = xform(355, ry * 0.44, cx, cy, ang);
    let rMid = xform(125, midY, cx, cy, ang);
    let rFold = xform(-155, ry * 1.18, cx, cy, ang);
    let rTip = xform(-355 + (idx % 3) * 14, spreadTip, cx, cy, ang);

    brush.set("xray_pencil", PAL.cyanBright, 0.85);
    brush.spline([rStart, rMid, rFold, rTip], 0.18);
    brush.set("xray_pen", PAL.whitePure, 0.78);
    brush.spline([rStart, rMid, rFold, rTip], 0.18);

    // 3. Secondary folding pantograph link wire
    let pLink0 = xform(145, ry * 0.38, cx, cy, ang);
    let pLink1 = xform(-155, ry * 1.18, cx, cy, ang);
    brush.set("xray_pen", PAL.cyanGlow, 0.65);
    brush.line(pLink0[0], pLink0[1], pLink1[0], pLink1[1]);

    // 4. Articulated clevis hinge brackets & glowing white rivets along each rib
    for (let jPt of [
      [125, midY],
      [-155, ry * 1.18],
      [-25, ry * 0.85]
    ]) {
      let bracket = roundRectPts(jPt[0], jPt[1], 14, 6, 2, cx, cy, ang);
      xrayWash(bracket, PAL.milkBright, 150);
      brush.set("xray_pen", PAL.whitePure, 0.85);
      strokePoly(bracket, true, 0.05);
      // Hollow tubular rivet pin
      let rPin = ellipsePts(jPt[0], jPt[1], 2.5, 2.5, cx, cy, ang, 10);
      xrayWash(rPin, PAL.whitePure, 230);
    }

    // 5. Tiny bulbous metal rib tip (ferrule) with thread eye hole
    let tipX = -355 + (idx % 3) * 14;
    let tipBulb = ellipsePts(tipX - 5, spreadTip, 7, 3.8, cx, cy, ang, 14);
    xrayWash(tipBulb, PAL.whitePure, 210);
    brush.set("xray_pen", PAL.whitePure, 0.9);
    strokePoly(tipBulb, true, 0.1);

    // Tension coil spring attached to middle pantograph link on outer ribs
    if (Math.abs(ry) > 20) {
      for (let c = 0; c < 14; c++) {
        let sx = lerp(15, 85, c / 14);
        let sy = lerp(ry * 0.72, midY * 0.92, c / 14) + (c % 2 === 0 ? -2.5 : 2.5);
        let sx2 = lerp(15, 85, (c + 1) / 14);
        let sy2 = lerp(ry * 0.72, midY * 0.92, (c + 1) / 14) + ((c + 1) % 2 === 0 ? -2.5 : 2.5);
        let sp0 = xform(sx, sy, cx, cy, ang);
        let sp1 = xform(sx2, sy2, cx, cy, ang);
        brush.set("xray_pen", PAL.whitePure, 0.7);
        brush.line(sp0[0], sp0[1], sp1[0], sp1[1]);
      }
    }
  }

  // F. Umbrella Handle (Bottom-Left) & Top Ferrule Cap (Top-Right)
  // Cylindrical handle with internal metal weight ring and wrist strap eyelet
  let handleBody = roundRectPts(-425, 0, 115, 58, 16, cx, cy, ang);
  xrayWash(handleBody, PAL.veilLight, 55);
  xrayWash(handleBody, PAL.cyanLow, 35);
  brush.set("xray_pencil", PAL.cyanBright, 1.0);
  strokePoly(handleBody, true, 0.15);

  // Internal threaded metal insert & counterweight ring inside handle
  let handleRing = roundRectPts(-378, 0, 18, 52, 3, cx, cy, ang);
  xrayWash(handleRing, PAL.milkBright, 160);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(handleRing, true, 0.05);

  // Push-button auto-open mechanism & spring inside handle
  let btnHousing = roundRectPts(-405, -24, 24, 14, 3, cx, cy, ang);
  xrayWash(btnHousing, PAL.cyanGlow, 110);
  for (let k = 0; k < 8; k++) {
    let bx = -414 + k * 2.4;
    let p0 = xform(bx, -16, cx, cy, ang);
    let p1 = xform(bx + 1.2, -4, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 0.8);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Top ferrule cap (right end of umbrella)
  let ferruleCap = roundRectPts(405, 0, 56, 26, 8, cx, cy, ang);
  xrayWash(ferruleCap, PAL.cyanMid, 85);
  let ferruleCore = roundRectPts(395, 0, 32, 18, 3, cx, cy, ang);
  xrayWash(ferruleCore, PAL.milkBright, 155);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(ferruleCap, true, 0.1);
  strokePoly(ferruleCore, true, 0.05);
}

// =============================================================================
// 5. SMARTPHONE CIRCUIT BOARD, COILS, BATTERY & SOLDER POINTS
// =============================================================================
function drawSmartphoneXray(cx, cy, ang) {
  const pw = 430;
  const ph = 216;

  // A. Outer Aluminum & Glass Chassis Frame
  let outerChassis = roundRectPts(0, 0, pw, ph, 34, cx, cy, ang, 10);
  let innerChassis = roundRectPts(0, 0, pw - 14, ph - 14, 28, cx, cy, ang, 10);

  xrayBloomPoly(outerChassis, cx, cy, PAL.cyanLow, 28, 3, 1.08);
  xrayWash(outerChassis, PAL.veilLight, 55);
  xrayWash(innerChassis, PAL.cyanLow, 35);

  // Bright milled aluminum perimeter rail (high X-ray edge attenuation)
  brush.set("xray_pencil", PAL.cyanGlow, 1.35);
  strokePoly(outerChassis, true, 0.08);
  brush.set("xray_pen", PAL.milkBright, 0.95);
  strokePoly(outerChassis, true, 0.08);
  strokePoly(innerChassis, true, 0.08);

  // Antenna dielectric plastic break bands on the metal frame + side micro-switches
  const antBreaks = [
    [-145, -ph / 2],
    [145, -ph / 2],
    [-145, ph / 2],
    [145, ph / 2]
  ];
  for (let b of antBreaks) {
    let b0 = xform(b[0], b[1] - 4, cx, cy, ang);
    let b1 = xform(b[0], b[1] + 4, cx, cy, ang);
    brush.set("xray_pen", PAL.bgPrussian, 1.4);
    brush.line(b0[0], b0[1], b1[0], b1[1]);
  }

  // Side volume & power buttons with internal metal dome switches and bracket screws
  for (let btnX of [-85, -30]) {
    let btn = roundRectPts(btnX, -ph / 2 - 2.5, 34, 5, 2, cx, cy, ang);
    xrayWash(btn, PAL.whitePure, 175);
    brush.set("xray_pen", PAL.whitePure, 0.85);
    strokePoly(btn, true, 0.05);
  }
  let pwrBtn = roundRectPts(-55, ph / 2 + 2.5, 48, 5, 2, cx, cy, ang);
  xrayWash(pwrBtn, PAL.whitePure, 175);
  brush.set("xray_pen", PAL.whitePure, 0.85);
  strokePoly(pwrBtn, true, 0.05);

  // B. Multi-Cell Li-Ion Battery Pouch (Upper-Right quadrant of phone)
  let battRect = roundRectPts(48, -32, 215, 112, 8, cx, cy, ang, 5);
  xrayWash(battRect, PAL.cyanMid, 62);
  xrayWash(battRect, PAL.cyanBright, 38);

  // Fine hatching inside battery to show rolled electrode foil layers
  let battPoly = new brush.Polygon(battRect);
  brush.hatchStyle("xray_pencil", PAL.cyanGlow, 0.55);
  battPoly.hatch(5.5, ang, { rand: 0.03 });
  brush.noHatch();

  brush.set("xray_pen", PAL.milkSoft, 0.8);
  strokePoly(battRect, true, 0.05);

  // Battery Protection Circuit Module (PCM) strip & spot-welded nickel tabs
  let pcmStrip = roundRectPts(-68, -32, 16, 106, 3, cx, cy, ang);
  xrayWash(pcmStrip, PAL.cyanGlow, 95);
  brush.set("xray_pen", PAL.whitePure, 0.8);
  strokePoly(pcmStrip, true, 0.05);
  for (let ty of [-62, -25, 12]) {
    let tab = roundRectPts(-60, ty, 12, 14, 1, cx, cy, ang);
    xrayWash(tab, PAL.whitePure, 190);
  }

  // C. L-Shaped Main Logic Board (PCB) — Obsessive Circuit Traces, BGAs & Solder Points
  // Horizontal arm along bottom + vertical arm on left side
  let pcbHoriz = roundRectPts(-15, 58, 285, 56, 4, cx, cy, ang);
  let pcbVert = roundRectPts(-115, -10, 74, 165, 4, cx, cy, ang);
  xrayWash(pcbHoriz, PAL.cyanLow, 75);
  xrayWash(pcbVert, PAL.cyanLow, 75);
  xrayWash(pcbHoriz, PAL.cyanMid, 40);
  xrayWash(pcbVert, PAL.cyanMid, 40);

  brush.set("xray_pen", PAL.cyanGlow, 0.8);
  strokePoly(pcbHoriz, true, 0.03);
  strokePoly(pcbVert, true, 0.03);

  // RF Shielding Cans & Silicon IC Packages on the Logic Board
  const icChips = [
    { x: -115, y: 12, w: 48, h: 48, bga: 8 },   // Main SoC / Application Processor
    { x: -115, y: -42, w: 40, h: 34, bga: 6 },  // NAND Flash Storage
    { x: -62, y: 58, w: 44, h: 36, bga: 7 },    // Baseband Modem
    { x: -8, y: 58, w: 36, h: 32, bga: 5 },     // Power Management IC (PMIC)
    { x: 46, y: 58, w: 38, h: 34, bga: 6 },     // RF Transceiver
    { x: 95, y: 58, w: 30, h: 28, bga: 4 }      // Audio / Charging Controller
  ];

  for (let ic of icChips) {
    let chipPoly = roundRectPts(ic.x, ic.y, ic.w, ic.h, 2, cx, cy, ang);
    xrayWash(chipPoly, PAL.cyanBright, 85);
    let diePoly = roundRectPts(ic.x, ic.y, ic.w * 0.68, ic.h * 0.68, 1, cx, cy, ang);
    xrayWash(diePoly, PAL.milkSoft, 95);

    brush.set("xray_pen", PAL.whitePure, 0.85);
    strokePoly(chipPoly, true, 0.02);
    strokePoly(diePoly, true, 0.02);

    // Microscopic BGA solder ball array glowing through the silicon substrate!
    let marginX = ic.w * 0.38;
    let marginY = ic.h * 0.38;
    for (let r = 0; r < ic.bga; r++) {
      for (let c = 0; c < ic.bga; c++) {
        let bx = ic.x + map(c, 0, ic.bga - 1, -marginX, marginX);
        let by = ic.y + map(r, 0, ic.bga - 1, -marginY, marginY);
        let sp = xform(bx, by, cx, cy, ang);
        brush.set("xray_pen", PAL.whitePure, 0.95);
        brush.line(sp[0] - 0.7, sp[1], sp[0] + 0.7, sp[1]);
        brush.line(sp[0], sp[1] - 0.7, sp[0], sp[1] + 0.7);
      }
    }
  }

  // 45-degree routed copper PCB buses, traces, and bright white solder vias
  for (let t = 0; t < 38; t++) {
    let yOff = map(t, 0, 37, 34, 82);
    let xStart = -140 + (t % 5) * 12;
    let xKnee1 = xStart + 25 + (t % 7) * 14;
    let xKnee2 = xKnee1 + 12;
    let xEnd = Math.min(122, xKnee2 + 30 + (t % 4) * 22);
    let yShift = (t % 2 === 0 ? 1 : -1) * 8;

    let trPts = [
      xform(xStart, yOff, cx, cy, ang),
      xform(xKnee1, yOff, cx, cy, ang),
      xform(xKnee2, constrain(yOff + yShift, 34, 82), cx, cy, ang),
      xform(xEnd, constrain(yOff + yShift, 34, 82), cx, cy, ang)
    ];
    brush.set("xray_pen", t % 3 === 0 ? PAL.milkBright : PAL.cyanGlow, 0.52);
    strokePoly(trPts, false, 0.02);

    // Bright solder point vias at trace ends
    let v0 = trPts[0];
    let v1 = trPts[trPts.length - 1];
    brush.set("xray_pen", PAL.whitePure, 1.15);
    brush.line(v0[0] - 0.9, v0[1], v0[0] + 0.9, v0[1]);
    brush.line(v1[0] - 0.9, v1[1], v1[0] + 0.9, v1[1]);
  }

  // Vertical PCB traces & SMD capacitor banks (twin-pad glowing solder blocks)
  for (let v = 0; v < 24; v++) {
    let vx = map(v, 0, 23, -148, -82);
    let vy0 = -85 + (v % 4) * 10;
    let vy1 = 55 - (v % 3) * 12;
    let p0 = xform(vx, vy0, cx, cy, ang);
    let p1 = xform(vx, vy1, cx, cy, ang);
    brush.set("xray_pen", PAL.cyanGlow, 0.5);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Dense clusters of SMD capacitors/resistors (bright twin solder pads)
  for (let k = 0; k < 65; k++) {
    let sx = random(-146, 118);
    let sy = sx < -80 ? random(-82, 78) : random(34, 80);
    let pA = xform(sx - 1.8, sy, cx, cy, ang);
    let pB = xform(sx + 1.8, sy, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 1.1);
    brush.line(pA[0], pA[1], pA[0] + 0.8, pA[1] + 0.5);
    brush.line(pB[0], pB[1], pB[0] + 0.8, pB[1] + 0.5);
  }

  // Board-to-board multi-pin mezzanine connectors (comb-like solder pins)
  const b2bConnectors = [
    { x: -138, y: -22, len: 28, vertical: true },
    { x: -82, y: 20, len: 26, vertical: true },
    { x: 18, y: 36, len: 32, vertical: false },
    { x: 75, y: 36, len: 26, vertical: false }
  ];
  for (let c of b2bConnectors) {
    let w = c.vertical ? 7 : c.len;
    let h = c.vertical ? c.len : 7;
    let connBox = roundRectPts(c.x, c.y, w, h, 1, cx, cy, ang);
    xrayWash(connBox, PAL.milkSoft, 140);
    brush.set("xray_pen", PAL.whitePure, 0.75);
    strokePoly(connBox, true, 0.02);
    let pins = 14;
    for (let i = 0; i <= pins; i++) {
      let off = map(i, 0, pins, -c.len * 0.45, c.len * 0.45);
      let px0 = c.vertical ? c.x - 4.5 : c.x + off;
      let py0 = c.vertical ? c.y + off : c.y - 4.5;
      let px1 = c.vertical ? c.x + 4.5 : c.x + off;
      let py1 = c.vertical ? c.y + off : c.y + 4.5;
      let w0 = xform(px0, py0, cx, cy, ang);
      let w1 = xform(px1, py1, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, 0.75);
      brush.line(w0[0], w0[1], w1[0], w1[1]);
    }
  }

  // D. Wireless Charging / MagSafe Planar Copper Coil + Ring of Alignment Magnets
  const coilCX = 5;
  const coilCY = -5;
  // Outer ring of 18 trapezoidal rare-earth magnets
  let numMags = 18;
  for (let m = 0; m < numMags; m++) {
    let a0 = (m * 360) / numMags + 2.5;
    let a1 = ((m + 1) * 360) / numMags - 2.5;
    // Leave tiny gap at bottom for flex cable routing
    if (a0 > 165 && a1 < 195) continue;
    let rIn = 58;
    let rOut = 68;
    let magPts = [
      xform(coilCX + cos(a0) * rIn, coilCY + sin(a0) * rIn, cx, cy, ang),
      xform(coilCX + cos(a0) * rOut, coilCY + sin(a0) * rOut, cx, cy, ang),
      xform(coilCX + cos(a1) * rOut, coilCY + sin(a1) * rOut, cx, cy, ang),
      xform(coilCX + cos(a1) * rIn, coilCY + sin(a1) * rIn, cx, cy, ang)
    ];
    xrayWash(magPts, PAL.milkBright, 155);
    brush.set("xray_pen", PAL.whitePure, 0.8);
    strokePoly(magPts, true, 0.02);
  }

  // Multi-turn planar spiral copper induction coil (16 tight concentric turns)
  let spiralPts = [];
  let totalTurns = 15;
  let stepsPerTurn = 28;
  for (let s = 0; s <= totalTurns * stepsPerTurn; s++) {
    let t = s / (totalTurns * stepsPerTurn);
    let r = lerp(20, 53, t);
    let theta = s * (360 / stepsPerTurn);
    spiralPts.push(xform(coilCX + cos(theta) * r, coilCY + sin(theta) * r, cx, cy, ang));
  }
  let coilWashPoly = ellipsePts(coilCX, coilCY, 54, 54, cx, cy, ang, 32);
  xrayWash(coilWashPoly, PAL.cyanGlow, 45);
  brush.set("xray_pen", PAL.milkBright, 0.65);
  strokePoly(spiralPts, false, 0.15);

  // E. Triple Camera Module (Left end of phone, upper-left corner in local space)
  let camPlateau = roundRectPts(-158, -46, 82, 92, 16, cx, cy, ang, 6);
  xrayWash(camPlateau, PAL.cyanMid, 75);
  brush.set("xray_pen", PAL.milkSoft, 0.85);
  strokePoly(camPlateau, true, 0.08);

  const lenses = [
    { x: -176, y: -68, r: 19 },
    { x: -176, y: -24, r: 19 },
    { x: -138, y: -46, r: 19 }
  ];
  for (let l of lenses) {
    // Square OIS voice-coil actuator housing
    let oisBox = roundRectPts(l.x, l.y, l.r * 2.1, l.r * 2.1, 4, cx, cy, ang);
    xrayWash(oisBox, PAL.cyanGlow, 85);
    brush.set("xray_pen", PAL.milkBright, 0.75);
    strokePoly(oisBox, true, 0.04);

    // Concentric heavy glass lens elements & copper voice-coil ring
    let ring1 = ellipsePts(l.x, l.y, l.r, l.r, cx, cy, ang, 24);
    let ring2 = ellipsePts(l.x, l.y, l.r * 0.74, l.r * 0.74, cx, cy, ang, 20);
    let ring3 = ellipsePts(l.x, l.y, l.r * 0.42, l.r * 0.42, cx, cy, ang, 16);
    xrayWash(ring1, PAL.milkSoft, 110);
    xrayWash(ring2, PAL.whitePure, 130);
    xrayWash(ring3, PAL.veilMid, 120); // Optical aperture center

    brush.set("xray_pen", PAL.whitePure, 0.95);
    strokePoly(ring1, true, 0.1);
    strokePoly(ring2, true, 0.1);
    strokePoly(ring3, true, 0.1);

    // 4 tiny corner OIS corner magnets around each lens
    for (let ca of [45, 135, 225, 315]) {
      let mx = l.x + cos(ca) * (l.r * 1.15);
      let my = l.y + sin(ca) * (l.r * 1.15);
      let mDot = ellipsePts(mx, my, 2.2, 2.2, cx, cy, ang, 8);
      xrayWash(mDot, PAL.whitePure, 210);
    }
  }

  // LiDAR scanner & LED Flash modules inside camera plateau
  let lidar = ellipsePts(-138, -74, 7.5, 7.5, cx, cy, ang, 14);
  let flash = ellipsePts(-138, -18, 7.5, 7.5, cx, cy, ang, 14);
  xrayWash(lidar, PAL.milkBright, 135);
  xrayWash(flash, PAL.whitePure, 155);
  brush.set("xray_pen", PAL.whitePure, 0.8);
  strokePoly(lidar, true, 0.1);
  strokePoly(flash, true, 0.1);

  // F. Taptic Engine (Linear Resonant Actuator) & Speaker Module at Right End of Phone
  let tapticBox = roundRectPts(155, 52, 68, 42, 4, cx, cy, ang);
  xrayWash(tapticBox, PAL.cyanGlow, 95);
  // Dense internal tungsten seismic mass (very high X-ray attenuation = pure white block!)
  let tungstenMass = roundRectPts(155, 52, 42, 26, 2, cx, cy, ang);
  xrayWash(tungstenMass, PAL.whitePure, 195);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(tapticBox, true, 0.04);
  strokePoly(tungstenMass, true, 0.04);

  // Flex springs & drive coils on either side of the tungsten mass
  for (let side of [-1, 1]) {
    for (let c = 0; c < 6; c++) {
      let sx = 155 + side * (22 + c * 1.6);
      let p0 = xform(sx, 39, cx, cy, ang);
      let p1 = xform(sx, 65, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, 0.8);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // USB-C Charging Port at Right Edge (with 24-pin internal contact comb & flanking pentalobe screws)
  let usbShell = roundRectPts(196, 0, 28, 24, 3, cx, cy, ang);
  xrayWash(usbShell, PAL.milkBright, 165);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(usbShell, true, 0.04);
  // Internal contact pins
  for (let p = -9; p <= 9; p += 2.2) {
    let pin0 = xform(182, p, cx, cy, ang);
    let pin1 = xform(206, p, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 0.72);
    brush.line(pin0[0], pin0[1], pin1[0], pin1[1]);
  }
  // Two bottom pentalobe screws flanking the USB-C port
  for (let sy of [-22, 22]) {
    let screw = roundRectPts(204, sy, 14, 4.5, 1, cx, cy, ang);
    xrayWash(screw, PAL.whitePure, 210);
    for (let th = 198; th <= 210; th += 2.2) {
      let t0 = xform(th, sy - 2.5, cx, cy, ang);
      let t1 = xform(th, sy + 2.5, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, 0.8);
      brush.line(t0[0], t0[1], t1[0], t1[1]);
    }
  }
}

// =============================================================================
// 6. LIPSTICK BULLET IN SWIVEL HELICAL TUBE
// =============================================================================
function drawLipstickXray(cx, cy, ang) {
  // Positioned locally along Y-axis: base at y = +95, bullet tip at y = -110
  // 1. Outer Metallic Cap & Base Casing (translucent square-shouldered cylinder)
  let outerCap = roundRectPts(0, -32, 62, 148, 8, cx, cy, ang);
  let outerBase = roundRectPts(0, 66, 64, 72, 6, cx, cy, ang);

  xrayBloomPoly(outerCap, cx, cy, PAL.cyanLow, 28, 3, 1.15);
  xrayWash(outerCap, PAL.veilLight, 58);
  xrayWash(outerBase, PAL.cyanLow, 72);

  // Double-wall vertical metal grazing edges
  for (let xWall of [-31, -28, 28, 31]) {
    let p0 = xform(xWall, -104, cx, cy, ang);
    let p1 = xform(xWall, 100, cx, cy, ang);
    brush.set("xray_pen", Math.abs(xWall) === 31 ? PAL.milkBright : PAL.cyanGlow, 0.88);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
  brush.set("xray_pen", PAL.milkSoft, 0.9);
  strokePoly(outerCap, true, 0.06);
  strokePoly(outerBase, true, 0.06);

  // Weighted metal base disc at bottom of lipstick
  let baseWeight = roundRectPts(0, 94, 58, 12, 3, cx, cy, ang);
  xrayWash(baseWeight, PAL.whitePure, 175);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(baseWeight, true, 0.04);

  // 2. Internal Brass Swivel Mechanism Tube (from y = -18 to y = +86)
  let innerBrass = roundRectPts(0, 34, 48, 104, 3, cx, cy, ang);
  xrayWash(innerBrass, PAL.cyanMid, 75);
  xrayWash(innerBrass, PAL.cyanBright, 45);
  brush.set("xray_pen", PAL.milkBright, 0.9);
  strokePoly(innerBrass, true, 0.04);

  // Center decorative metal ferrule band where cap meets base
  let midRing = roundRectPts(0, 30, 65, 16, 2, cx, cy, ang);
  xrayWash(midRing, PAL.milkSoft, 115);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(midRing, true, 0.04);

  // 3. Helical Cam Spiral Slots cut into the inner cylinder (front & back spirals crossing in X-pattern!)
  let spiralSteps = 44;
  for (let pass = 0; pass < 2; pass++) {
    let slotTop = [];
    let slotBot = [];
    let phase = pass * 180;
    for (let i = 0; i <= spiralSteps; i++) {
      let t = i / spiralSteps;
      let sy = lerp(-12, 78, t);
      let theta = t * 520 + phase;
      let sx = Math.sin((theta * Math.PI) / 180) * 22;
      slotTop.push(xform(sx, sy - 2.6, cx, cy, ang));
      slotBot.push(xform(sx, sy + 2.6, cx, cy, ang));
    }
    let col = pass === 0 ? PAL.whitePure : PAL.cyanGlow;
    let w = pass === 0 ? 0.9 : 0.65;
    brush.set("xray_pen", col, w);
    strokePoly(slotTop, false, 0.25);
    strokePoly(slotBot, false, 0.25);
  }

  // 4. Internal Follower Cup (holding the wax bullet) + Two Bright White Guide Lug Pins
  let cupBody = roundRectPts(0, 6, 42, 46, 3, cx, cy, ang);
  xrayWash(cupBody, PAL.milkSoft, 110);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(cupBody, true, 0.04);

  // Internal vertical retention ribs inside the follower cup
  for (let rx of [-14, -7, 0, 7, 14]) {
    let r0 = xform(rx, -15, cx, cy, ang);
    let r1 = xform(rx, 26, cx, cy, ang);
    brush.set("xray_pen", PAL.cyanGlow, 0.6);
    brush.line(r0[0], r0[1], r1[0], r1[1]);
  }

  // Two protruding metal lug pins riding in the helical cam tracks
  for (let side of [-1, 1]) {
    let lug = ellipsePts(side * 22, 12, 4.8, 3.8, cx, cy, ang, 14);
    xrayWash(lug, PAL.whitePure, 235);
    brush.set("xray_pen", PAL.whitePure, 1.0);
    strokePoly(lug, true, 0.1);
  }

  // 5. The Sculpted Wax Lipstick Bullet (Translucent velvety milky-cyan with chisel bevel)
  let bulletPts = [
    xform(-19, 14, cx, cy, ang),
    xform(-19, -58, cx, cy, ang),
    xform(-15, -78, cx, cy, ang),
    xform(-2, -92, cx, cy, ang),
    xform(14, -84, cx, cy, ang),
    xform(19, -68, cx, cy, ang),
    xform(19, 14, cx, cy, ang)
  ];
  xrayWash(bulletPts, PAL.cyanMid, 68);
  xrayWash(bulletPts, PAL.cyanGlow, 42);

  // Chisel facet ellipse at top of lipstick bullet
  let bevelFace = ellipsePts(2, -76, 15, 9, cx, cy, ang + 28, 22);
  xrayWash(bevelFace, PAL.milkSoft, 65);

  // Delicate soft white pencil shading on the lipstick bullet
  let bulletPoly = new brush.Polygon(bulletPts);
  brush.hatchStyle("xray_pencil", PAL.milkSoft, 0.55);
  bulletPoly.hatch(4.5, ang + 90, { rand: 0.05 });
  brush.noHatch();

  brush.set("xray_pencil", PAL.milkBright, 0.95);
  strokePoly(bulletPts, true, 0.2);
  brush.set("xray_pen", PAL.milkBright, 0.7);
  strokePoly(bevelFace, true, 0.2);
}

// =============================================================================
// 7. GLASS PERFUME ATOMIZER & SAFETY PIN
// =============================================================================
function drawPerfumeAtomizer(cx, cy, ang) {
  // Thick-walled glass vial (y = -45 to +65) + metal crimp spray pump (y = -80 to -45)
  let outerGlass = roundRectPts(0, 12, 46, 112, 6, cx, cy, ang);
  let innerCavity = [
    xform(-16, -38, cx, cy, ang),
    xform(16, -38, cx, cy, ang),
    xform(15, 52, cx, cy, ang),
    xform(0, 44, cx, cy, ang), // Characteristic thick concave glass punt at bottom!
    xform(-15, 52, cx, cy, ang)
  ];

  xrayBloomPoly(outerGlass, cx, cy, PAL.cyanLow, 26, 3, 1.15);
  xrayWash(outerGlass, PAL.cyanMid, 82);
  // Thick glass base & walls glow brighter where glass path length is longest
  let glassBase = roundRectPts(0, 56, 45, 22, 5, cx, cy, ang);
  xrayWash(glassBase, PAL.milkSoft, 110);

  brush.set("xray_pencil", PAL.milkSoft, 1.0);
  strokePoly(outerGlass, true, 0.08);
  brush.set("xray_pen", PAL.milkBright, 0.8);
  strokePoly(innerCavity, true, 0.15);

  // Liquid meniscus level inside glass vial
  let meniscus = [
    xform(-15.5, -8, cx, cy, ang),
    xform(0, -4, cx, cy, ang),
    xform(15.5, -8, cx, cy, ang)
  ];
  brush.set("xray_pencil", PAL.cyanGlow, 0.75);
  strokePoly(meniscus, false, 0.3);

  // Metal crimp collar & actuator nozzle at top
  let crimpCollar = roundRectPts(0, -52, 28, 20, 2, cx, cy, ang);
  let nozzleCap = roundRectPts(0, -72, 22, 22, 3, cx, cy, ang);
  xrayWash(crimpCollar, PAL.milkBright, 165);
  xrayWash(nozzleCap, PAL.cyanGlow, 115);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(crimpCollar, true, 0.04);
  strokePoly(nozzleCap, true, 0.04);

  // Spray orifice dot
  let orifice = ellipsePts(9, -73, 2.2, 2.2, cx, cy, ang, 8);
  xrayWash(orifice, PAL.whitePure, 230);

  // Internal stainless steel metering spring & check-ball inside pump housing
  for (let c = 0; c < 11; c++) {
    let sy = lerp(-62, -32, c / 11);
    let sy2 = lerp(-62, -32, (c + 1) / 11);
    let sx = c % 2 === 0 ? -4.5 : 4.5;
    let sx2 = (c + 1) % 2 === 0 ? -4.5 : 4.5;
    let p0 = xform(sx, sy, cx, cy, ang);
    let p1 = xform(sx2, sy2, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 0.85);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
  let checkBall = ellipsePts(0, -30, 3.0, 3.0, cx, cy, ang, 10);
  xrayWash(checkBall, PAL.whitePure, 235);

  // Curved capillary dip tube reaching into the bottom corner of the glass vial
  let dipTubeL = [
    xform(-1.8, -30, cx, cy, ang),
    xform(-1.5, 5, cx, cy, ang),
    xform(-7, 32, cx, cy, ang),
    xform(-14, 50, cx, cy, ang)
  ];
  let dipTubeR = [
    xform(1.8, -30, cx, cy, ang),
    xform(1.5, 5, cx, cy, ang),
    xform(-3.5, 32, cx, cy, ang),
    xform(-10.5, 50, cx, cy, ang)
  ];
  brush.set("xray_pen", PAL.milkSoft, 0.72);
  strokePoly(dipTubeL, false, 0.25);
  strokePoly(dipTubeR, false, 0.25);
}

function drawSafetyPinAndBobbyPin(cx, cy, ang) {
  // 1. Closed Steel Safety Pin (with double-coiled spring loop at one end & clasp head at the other)
  let coilEnd = ellipsePts(-42, 0, 9, 9, cx, cy, ang, 20);
  let coilInner = ellipsePts(-42, 0, 5, 5, cx, cy, ang, 16);
  xrayWash(coilEnd, PAL.milkBright, 165);
  brush.set("xray_pen", PAL.whitePure, 1.15);
  strokePoly(coilEnd, true, 0.15);
  strokePoly(coilInner, true, 0.15);

  // Two shafts of the safety pin
  let topShaft0 = xform(-42, -8, cx, cy, ang);
  let topShaft1 = xform(38, -5, cx, cy, ang);
  let botShaft0 = xform(-42, 8, cx, cy, ang);
  let botShaft1 = xform(38, 5, cx, cy, ang);
  brush.set("xray_pencil", PAL.cyanGlow, 1.1);
  brush.line(topShaft0[0], topShaft0[1], topShaft1[0], topShaft1[1]);
  brush.line(botShaft0[0], botShaft0[1], botShaft1[0], botShaft1[1]);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  brush.line(topShaft0[0], topShaft0[1], topShaft1[0], topShaft1[1]);
  brush.line(botShaft0[0], botShaft0[1], botShaft1[0], botShaft1[1]);

  // Folded sheet-metal safety clasp head (showing the sharp needle point tucked inside!)
  let claspHead = roundRectPts(42, 0, 22, 16, 6, cx, cy, ang);
  xrayWash(claspHead, PAL.milkBright, 175);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(claspHead, true, 0.1);
  // Needle point visible inside clasp
  let pt0 = xform(34, -5, cx, cy, ang);
  let pt1 = xform(48, -1, cx, cy, ang);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  brush.line(pt0[0], pt0[1], pt1[0], pt1[1]);

  // 2. Stray Wavy Steel Bobby Pin nearby
  let bx = cx - 95;
  let by = cy + 68;
  let bAng = ang - 44;
  let straightLeg = [xform(-48, 4, bx, by, bAng), xform(44, 2, bx, by, bAng)];
  let uBend = ellipsePts(-48, 0, 5, 4, bx, by, bAng, 12, 90, 270);
  let wavyLeg = [];
  for (let i = 0; i <= 24; i++) {
    let lx = map(i, 0, 24, -48, 42);
    let ly = -3.5 + (i > 3 && i < 21 ? Math.sin(i * 1.15) * 2.6 : 0);
    wavyLeg.push(xform(lx, ly, bx, by, bAng));
  }
  brush.set("xray_pencil", PAL.cyanGlow, 1.0);
  strokePoly(straightLeg, false, 0.1);
  strokePoly(wavyLeg, false, 0.25);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(straightLeg, false, 0.1);
  strokePoly(uBend, false, 0.2);
  strokePoly(wavyLeg, false, 0.25);
}

// =============================================================================
// 8. RING OF KEYS & ELECTRONIC TRANSPONDER FOB
// =============================================================================
function drawKeyRingCluster(cx, cy, ang) {
  // A. Electronic Automotive Key Fob (overlapping under the split ring)
  drawTransponderKeyFob(cx - 58, cy - 52, ang - 48);

  // B. Key 1: Classic Brass House Key (fanned to upper-right)
  drawDetailedMetalKey(cx + 22, cy - 12, ang - 18, 1.05, "house", [2, 5, 1, 6, 3, 5, 2]);

  // C. Key 2: High-Security Dimple / Wave-Track Key (fanned to lower-right, overlapping Key 1 & Umbrella!)
  drawDetailedMetalKey(cx + 18, cy + 16, ang + 26, 1.12, "dimple", [3, 2, 4, 2, 5, 1]);

  // D. Key 3: Small Vintage / Mailbox Brass Key (fanned downward-left)
  drawDetailedMetalKey(cx - 16, cy + 28, ang + 76, 0.84, "small", [4, 1, 5, 2, 4]);

  // E. Swivel Lobster Clasp with Internal Torsion Spring
  drawSwivelClasp(cx - 48, cy + 22, ang + 128);

  // F. Main Tempered Steel Split Key Ring (double-coiled loop of flat wire)
  let rOuter = 54;
  let rInner = 45;
  let ringOuterPts = ellipsePts(0, 0, rOuter, rOuter, cx, cy, ang, 48);
  let ringInnerPts = ellipsePts(0, 0, rInner, rInner, cx, cy, ang, 48);
  let ringMidPts = ellipsePts(1.5, -1, (rOuter + rInner) / 2, (rOuter + rInner) / 2, cx, cy, ang, 48);

  // Ring band polygon (outer minus inner via radial segments)
  let ringBand = ringOuterPts.concat(ringInnerPts.slice().reverse());
  xrayWash(ringBand, PAL.milkBright, 165);
  xrayWash(ringBand, PAL.whitePure, 85);

  brush.set("xray_pen", PAL.whitePure, 1.1);
  strokePoly(ringOuterPts, true, 0.15);
  strokePoly(ringInnerPts, true, 0.15);
  // Line separating the two overlapping coils of the split ring
  brush.set("xray_pen", PAL.cyanGlow, 0.75);
  strokePoly(ringMidPts, true, 0.15);

  // Split ends of the key ring coil
  for (let splitAng of [35, 215]) {
    let s0 = xform(cos(splitAng) * rInner, sin(splitAng) * rInner, cx, cy, ang);
    let s1 = xform(cos(splitAng + 8) * rOuter, sin(splitAng + 8) * rOuter, cx, cy, ang);
    brush.set("xray_pen", PAL.whitePure, 1.1);
    brush.line(s0[0], s0[1], s1[0], s1[1]);
  }

  // Bright pure-white additive hotspots where keys thread onto the split ring
  const threadHotspots = [
    { x: 48, y: -16, rx: 11, ry: 7, a: -18 },
    { x: 44, y: 21, rx: 11, ry: 7, a: 26 },
    { x: -12, y: 48, rx: 10, ry: 6, a: 76 },
    { x: -46, y: -22, rx: 10, ry: 6, a: -48 }
  ];
  for (let h of threadHotspots) {
    let wp = xform(h.x, h.y, cx, cy, ang);
    let hotPoly = ellipsePts(0, 0, h.rx, h.ry, wp[0], wp[1], ang + h.a, 16);
    xrayWash(hotPoly, PAL.whitePure, 225);
    brush.set("xray_pen", PAL.whitePure, 1.0);
    strokePoly(hotPoly, true, 0.1);
  }
}

function drawDetailedMetalKey(kx, ky, ang, sc, style, bitting) {
  // Bow (head of key) centered at local (0, 0), blade extending to +X
  let bowPts = [];
  if (style === "house") {
    // Hexagonal / architectural brass key bow
    bowPts = [
      [-34, -22], [-12, -36], [16, -34], [28, -16],
      [28, 16], [16, 34], [-12, 36], [-34, 22]
    ].map((p) => xform(p[0] * sc, p[1] * sc, kx, ky, ang));
  } else if (style === "dimple") {
    // Rounded trapezoidal high-security bow
    bowPts = roundRectPts(-4 * sc, 0, 64 * sc, 62 * sc, 14 * sc, kx, ky, ang, 6);
  } else {
    // Classic oval bow
    bowPts = ellipsePts(-4 * sc, 0, 30 * sc, 26 * sc, kx, ky, ang, 28);
  }

  // Key blade polygon with serrated bitting teeth along bottom edge
  let bladeLen = 128 * sc;
  let bladeW = 15 * sc;
  let bladeLocal = [
    [22 * sc, -bladeW],
    [22 * sc, -bladeW - 5 * sc], // Shoulder stop
    [32 * sc, -bladeW - 5 * sc],
    [32 * sc, -bladeW],
    [bladeLen - 12 * sc, -bladeW],
    [bladeLen, -2 * sc],         // Angled tip of key
    [bladeLen - 8 * sc, bladeW]
  ];

  // Add V-notched bitting serrations along bottom edge of blade from tip back to shoulder
  let numTeeth = bitting.length;
  for (let i = numTeeth - 1; i >= 0; i--) {
    let tx = map(i, 0, numTeeth - 1, 42 * sc, bladeLen - 18 * sc);
    let depth = bitting[i] * 2.1 * sc;
    bladeLocal.push([tx + 5 * sc, bladeW]);
    bladeLocal.push([tx, bladeW - depth]);
    bladeLocal.push([tx - 5 * sc, bladeW]);
  }
  bladeLocal.push([32 * sc, bladeW]);
  bladeLocal.push([32 * sc, bladeW + 4 * sc]);
  bladeLocal.push([22 * sc, bladeW + 4 * sc]);
  bladeLocal.push([22 * sc, bladeW]);

  let bladePts = bladeLocal.map((p) => xform(p[0], p[1], kx, ky, ang));

  // X-ray density washes for key bow & blade
  xrayBloomPoly(bowPts, kx, ky, PAL.cyanBright, 24, 2, 1.15);
  xrayWash(bowPts, PAL.cyanGlow, 115);
  xrayWash(bowPts, PAL.milkSoft, 75);
  xrayWash(bladePts, PAL.cyanGlow, 115);
  xrayWash(bladePts, PAL.milkSoft, 75);

  // Keyring hole punched in the bow (darker translucent Prussian hole with bright rim)
  let holePts = ellipsePts(-17 * sc, 0, 9.5 * sc, 9.5 * sc, kx, ky, ang, 20);
  xrayWash(holePts, PAL.bgIndigo, 155);

  // Longitudinal milled keyway grooves (thinner metal = slightly more X-ray translucent!)
  if (style === "dimple") {
    // Serpentine laser-milled wave track down the center of the blade + dimple pits
    let waveTop = [];
    let waveBot = [];
    for (let s = 0; s <= 24; s++) {
      let wx = lerp(34 * sc, (bladeLen - 16) * sc, s / 24);
      let wy = Math.sin(s * 0.65) * 4.5 * sc;
      waveTop.push(xform(wx, wy - 3 * sc, kx, ky, ang));
      waveBot.push(xform(wx, wy + 3 * sc, kx, ky, ang));
    }
    let wavePoly = waveTop.concat(waveBot.slice().reverse());
    xrayWash(wavePoly, PAL.veilMid, 95);
    brush.set("xray_pen", PAL.whitePure, 0.85);
    strokePoly(waveTop, false, 0.25);
    strokePoly(waveBot, false, 0.25);

    // Conical drilled security dimples
    for (let d = 0; d < 5; d++) {
      let dx = (46 + d * 15) * sc;
      let dy = (d % 2 === 0 ? -5.5 : 5.5) * sc;
      let dimple = ellipsePts(dx, dy, 3.2 * sc, 3.2 * sc, kx, ky, ang, 12);
      xrayWash(dimple, PAL.veilMid, 110);
      brush.set("xray_pen", PAL.whitePure, 0.75);
      strokePoly(dimple, true, 0.1);
    }
  } else {
    // Classic parallel milled ward grooves
    for (let gy of [-5 * sc, 1.5 * sc]) {
      let groove = roundRectPts((bladeLen * 0.58), gy, bladeLen * 0.68, 3.5 * sc, 1, kx, ky, ang);
      xrayWash(groove, PAL.veilMid, 95);
      brush.set("xray_pen", PAL.whitePure, 0.75);
      strokePoly(groove, true, 0.02);
    }
  }

  // Crisp white pencil and technical pen outlines on bow, hole, and bitting teeth
  brush.set("xray_pencil", PAL.milkBright, 1.0);
  strokePoly(bowPts, true, 0.1);
  strokePoly(bladePts, true, 0.04);
  brush.set("xray_pen", PAL.whitePure, 0.92);
  strokePoly(bowPts, true, 0.1);
  strokePoly(holePts, true, 0.1);
  strokePoly(bladePts, true, 0.03);
}

function drawTransponderKeyFob(fx, fy, ang) {
  // Molded plastic key fob shell (ghostly cyan) revealing internal coin-cell battery, PCB, switches & RFID coil
  let fobShell = roundRectPts(0, 0, 96, 56, 18, fx, fy, ang, 8);
  xrayWash(fobShell, PAL.veilLight, 58);
  xrayWash(fobShell, PAL.cyanLow, 35);
  brush.set("xray_pencil", PAL.cyanBright, 0.9);
  strokePoly(fobShell, true, 0.12);

  // Internal PCB outline
  let fobPCB = roundRectPts(2, 0, 76, 42, 8, fx, fy, ang, 5);
  xrayWash(fobPCB, PAL.cyanMid, 62);
  brush.set("xray_pen", PAL.cyanGlow, 0.7);
  strokePoly(fobPCB, true, 0.05);

  // CR2032 Coin-Cell Battery inside the fob (dense glowing circle + spring clip prongs)
  let crBatt = ellipsePts(-14, 0, 18, 18, fx, fy, ang, 28);
  xrayWash(crBatt, PAL.milkSoft, 145);
  xrayWash(crBatt, PAL.whitePure, 65);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(crBatt, true, 0.1);

  // Battery retention spring contact fingers overlapping the coin cell
  let prong = [
    xform(-32, -8, fx, fy, ang),
    xform(-14, -4, fx, fy, ang),
    xform(-10, 0, fx, fy, ang),
    xform(-14, 4, fx, fy, ang),
    xform(-32, 8, fx, fy, ang)
  ];
  xrayWash(prong, PAL.whitePure, 210);
  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(prong, true, 0.05);

  // 3 Tactile Micro-Switches (Lock / Unlock / Trunk) with metal snap domes & 4 solder legs
  for (let sx of [12, 26]) {
    for (let sy of (sx === 12 ? [-10, 10] : [0])) {
      let swBox = roundRectPts(sx, sy, 9, 9, 1, fx, fy, ang);
      xrayWash(swBox, PAL.milkBright, 150);
      brush.set("xray_pen", PAL.whitePure, 0.8);
      strokePoly(swBox, true, 0.02);
      let dome = ellipsePts(sx, sy, 3.2, 3.2, fx, fy, ang, 10);
      xrayWash(dome, PAL.whitePure, 220);
    }
  }

  // Wound copper transponder inductor coil along upper edge of PCB
  let coilBar = roundRectPts(16, -16, 24, 5, 1, fx, fy, ang);
  xrayWash(coilBar, PAL.whitePure, 175);
  for (let w = 5; w <= 27; w += 1.8) {
    let p0 = xform(w, -19, fx, fy, ang);
    let p1 = xform(w + 0.6, -13, fx, fy, ang);
    brush.set("xray_pen", PAL.whitePure, 0.78);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

function drawSwivelClasp(sx, sy, ang) {
  // Lobster claw clasp + D-shackle + internal curved wire spring
  let shackle = ellipsePts(-18, 0, 12, 10, sx, sy, ang, 20);
  let body = roundRectPts(8, 0, 32, 16, 6, sx, sy, ang, 5);
  xrayWash(shackle, PAL.milkBright, 150);
  xrayWash(body, PAL.milkBright, 160);
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(shackle, true, 0.1);
  strokePoly(body, true, 0.1);

  // Internal coiled torsion spring inside the lobster clasp body
  let springLoop = ellipsePts(2, 0, 5, 5, sx, sy, ang, 14);
