  brush.set("xray_pen", PAL.whitePure, 0.9);
  strokePoly(springLoop, true, 0.1);
}

// =============================================================================
// 9. LOOSE COINS IN LOWER GUSSET (BI-METALLIC, MILLED RIMS, OVERLAPS)
// =============================================================================
function drawLooseCoins(bagCX, bagCY, bagAngle) {
  // Coins resting in the lower folds of the bag (some overlapping so intersections glow white)
  const coins = [
    { lx: -65, ly: 295, rx: 35, ry: 31, rot: -15, bimetallic: true },
    { lx: -25, ly: 312, rx: 31, ry: 27, rot: 22, bimetallic: false },
    { lx: 85, ly: 325, rx: 37, ry: 22, rot: -8, bimetallic: true },
    { lx: 122, ly: 335, rx: 28, ry: 25, rot: 35, bimetallic: false },
    { lx: 215, ly: 305, rx: 33, ry: 16, rot: -22, bimetallic: false },
    { lx: -165, ly: 275, rx: 26, ry: 24, rot: 12, bimetallic: false }
  ];

  let coinWorldCenters = [];

  for (let c of coins) {
    let wc = xform(c.lx, c.ly, bagCX, bagCY, bagAngle);
    let totalAng = bagAngle + c.rot;
    coinWorldCenters.push({ wc, rx: c.rx, ry: c.ry, ang: totalAng });

    let outerPts = ellipsePts(0, 0, c.rx, c.ry, wc[0], wc[1], totalAng, 36);
    let rimPts = ellipsePts(0, 0, c.rx * 0.9, c.ry * 0.9, wc[0], wc[1], totalAng, 32);

    xrayBloomPoly(outerPts, wc[0], wc[1], PAL.cyanBright, 28, 3, 1.2);
    xrayWash(outerPts, PAL.cyanGlow, 125);
    xrayWash(outerPts, PAL.milkSoft, 75);

    if (c.bimetallic) {
      // Bi-metallic coin (e.g. 2-Euro style): distinct inner core disc & thin expansion gap!
      let coreOuter = ellipsePts(0, 0, c.rx * 0.66, c.ry * 0.66, wc[0], wc[1], totalAng, 28);
      let coreInner = ellipsePts(0, 0, c.rx * 0.63, c.ry * 0.63, wc[0], wc[1], totalAng, 28);
      xrayWash(coreInner, PAL.milkBright, 65);
      // Crisp dark-cyan micro-seam between outer brass ring and inner nickel-brass core
      brush.set("xray_pen", PAL.bgIndigo, 1.0);
      strokePoly(coreOuter, true, 0.1);
      brush.set("xray_pen", PAL.whitePure, 0.85);
      strokePoly(coreInner, true, 0.1);
    }

    // Raised coin rim & milled edge reeds
    brush.set("xray_pencil", PAL.milkBright, 1.1);
    strokePoly(outerPts, true, 0.1);
    brush.set("xray_pen", PAL.whitePure, 0.95);
    strokePoly(outerPts, true, 0.1);
    brush.set("xray_pen", PAL.milkSoft, 0.65);
    strokePoly(rimPts, true, 0.1);

    // Milled reed notches around the coin edge
    let reeds = 44;
    for (let r = 0; r < reeds; r++) {
      let a = (r * 360) / reeds;
      let p0 = xform(cos(a) * c.rx * 0.91, sin(a) * c.ry * 0.91, wc[0], wc[1], totalAng);
      let p1 = xform(cos(a) * c.rx * 1.0, sin(a) * c.ry * 1.0, wc[0], wc[1], totalAng);
      brush.set("xray_pen", PAL.whitePure, 0.65);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }

    // Ghostly stamped relief silhouette inside the coin face
    let reliefPts = ellipsePts(-c.rx * 0.08, 0, c.rx * 0.36, c.ry * 0.42, wc[0], wc[1], totalAng, 16);
    xrayWash(reliefPts, PAL.whitePure, 55);
    brush.set("xray_pencil", PAL.milkBright, 0.6);
    strokePoly(reliefPts, false, 0.25);
  }

  // Compute and render pure incandescent white lens-shaped overlaps between intersecting coins!
  const overlapPairs = [
    [0, 1],
    [2, 3]
  ];
  for (let pair of overlapPairs) {
    let cA = coinWorldCenters[pair[0]];
    let cB = coinWorldCenters[pair[1]];
    let polyA = ellipsePts(0, 0, cA.rx, cA.ry, cA.wc[0], cA.wc[1], cA.ang, 48);
    // Filter points of coin A that lie inside coin B's ellipse, and vice versa
    let lensPts = [];
    for (let p of polyA) {
      let dx = p[0] - cB.wc[0];
      let dy = p[1] - cB.wc[1];
      let r = (-cB.ang * Math.PI) / 180;
      let lx = dx * Math.cos(r) - dy * Math.sin(r);
      let ly = dx * Math.sin(r) + dy * Math.cos(r);
      if ((lx * lx) / (cB.rx * cB.rx) + (ly * ly) / (cB.ry * cB.ry) <= 1.02) {
        lensPts.push(p);
      }
    }
    let polyB = ellipsePts(0, 0, cB.rx, cB.ry, cB.wc[0], cB.wc[1], cB.ang, 48);
    for (let p of polyB) {
      let dx = p[0] - cA.wc[0];
      let dy = p[1] - cA.wc[1];
      let r = (-cA.ang * Math.PI) / 180;
      let lx = dx * Math.cos(r) - dy * Math.sin(r);
      let ly = dx * Math.sin(r) + dy * Math.cos(r);
      if ((lx * lx) / (cA.rx * cA.rx) + (ly * ly) / (cA.ry * cA.ry) <= 1.02) {
        lensPts.push(p);
      }
    }
    if (lensPts.length >= 4) {
      // Sort points radially around their centroid to form a clean convex lens polygon
      let mx = lensPts.reduce((s, p) => s + p[0], 0) / lensPts.length;
      let my = lensPts.reduce((s, p) => s + p[1], 0) / lensPts.length;
      lensPts.sort((a, b) => Math.atan2(a[1] - my, a[0] - mx) - Math.atan2(b[1] - my, b[0] - mx));
      xrayWash(lensPts, PAL.whitePure, 210);
      brush.set("xray_pen", PAL.whitePure, 1.05);
      strokePoly(lensPts, true, 0.1);
    }
  }
}

// =============================================================================
// 10. HANDBAG ZIPPERS (TINY INTERLOCKING TEETH, SLIDERS, HARDWARE CLASPS)
// =============================================================================
function drawZippersAndHardware(cx, cy, ang) {
  // A. Main Top Handbag Zipper Track (sweeping across top opening of bag, partially unzipped on left)
  drawZipperTrack(
    cx,
    cy,
    ang,
    -515,
    495,
    -292,
    185, // Slider position at local x = 185 (closed to the left, parted to the right)
    165,
    1.15
  );

  // B. Inner Pocket Zipper Track (smaller gauge teeth, slider near left end)
  drawZipperTrack(
    cx,
    cy,
    ang,
    -245,
    225,
    -135,
    -135, // Slider at local x = -135
    92,
    0.82
  );

  // C. Center Magnetic Snap Clasp on Bag Collar (Circular neodymium magnet + folded metal prongs)
  let snapCX = 0;
  let snapCY = -215;
  let magOuter = ellipsePts(snapCX, snapCY, 24, 24, cx, cy, ang, 28);
  let magInner = ellipsePts(snapCX, snapCY, 15, 15, cx, cy, ang, 22);
  let magHole = ellipsePts(snapCX, snapCY, 5, 5, cx, cy, ang, 14);
  xrayBloomPoly(magOuter, magOuter[0][0], magOuter[0][1], PAL.cyanBright, 32, 3, 1.3);
  xrayWash(magOuter, PAL.milkSoft, 140);
  xrayWash(magInner, PAL.whitePure, 175);
  xrayWash(magHole, PAL.veilMid, 140);

  // Folded brass mounting prongs behind the magnetic snap washer
  for (let side of [-1, 1]) {
    let prong = roundRectPts(snapCX + side * 14, snapCY, 10, 5, 1, cx, cy, ang);
    xrayWash(prong, PAL.whitePure, 230);
  }
  brush.set("xray_pen", PAL.whitePure, 0.95);
  strokePoly(magOuter, true, 0.1);
  strokePoly(magInner, true, 0.1);
  strokePoly(magHole, true, 0.1);

  // D. Heavy Brass Handle Anchor D-Rings, Hinged Brackets & Rivets
  for (let side of [-1, 1]) {
    let hx = side * 265;
    let hy = -285;

    // Rectangular leather/metal anchor tab with two bright dome rivets
    let mountPlate = roundRectPts(hx, hy + 34, 48, 44, 6, cx, cy, ang);
    xrayWash(mountPlate, PAL.cyanGlow, 110);
    brush.set("xray_pen", PAL.whitePure, 0.9);
    strokePoly(mountPlate, true, 0.05);

    for (let rx of [-13, 13]) {
      for (let ry of [hy + 22, hy + 46]) {
        let rivOuter = ellipsePts(hx + rx, ry, 5.5, 5.5, cx, cy, ang, 14);
        let rivCore = ellipsePts(hx + rx, ry, 2.5, 2.5, cx, cy, ang, 10);
        xrayWash(rivOuter, PAL.milkBright, 175);
        xrayWash(rivCore, PAL.whitePure, 240);
        brush.set("xray_pen", PAL.whitePure, 0.9);
        strokePoly(rivOuter, true, 0.1);
      }
    }

    // Cylindrical hinge barrel sleeve
    let barrel = roundRectPts(hx, hy + 10, 52, 13, 4, cx, cy, ang);
    xrayWash(barrel, PAL.whitePure, 195);
    brush.set("xray_pen", PAL.whitePure, 1.0);
    strokePoly(barrel, true, 0.05);

    // Heavy Brass D-Ring Arch
    let dOuter = ellipsePts(hx, hy + 6, 32, 34, cx, cy, ang, 24, 180, 360);
    let dInner = ellipsePts(hx, hy + 6, 21, 23, cx, cy, ang, 24, 180, 360);
    let dRingPoly = dOuter.concat(dInner.slice().reverse());
    xrayBloomPoly(dRingPoly, dOuter[12][0], dOuter[12][1], PAL.cyanBright, 35, 3, 1.25);
    xrayWash(dRingPoly, PAL.milkBright, 170);
    xrayWash(dRingPoly, PAL.whitePure, 85);

    brush.set("xray_pen", PAL.whitePure, 1.05);
    strokePoly(dRingPoly, true, 0.1);
  }
}

function drawZipperTrack(cx, cy, ang, xStart, xEnd, yBase, sliderX, numTeeth, sc) {
  // Woven zipper fabric tape ribbons (ghostly cyan bands on either side of the teeth)
  let tapePts = [];
  for (let i = 0; i <= 36; i++) {
    let lx = lerp(xStart, xEnd, i / 36);
    let curveY = yBase + Math.sin((i / 36) * Math.PI) * 18 * sc;
    tapePts.push(xform(lx, curveY - 16 * sc, cx, cy, ang));
  }
  for (let i = 36; i >= 0; i--) {
    let lx = lerp(xStart, xEnd, i / 36);
    let curveY = yBase + Math.sin((i / 36) * Math.PI) * 18 * sc;
    tapePts.push(xform(lx, curveY + 16 * sc, cx, cy, ang));
  }
  xrayWash(tapePts, PAL.cyanLow, 42);

  // Draw every individual metal zipper tooth with its interlocking scoop crown!
  for (let i = 0; i < numTeeth; i++) {
    let t = i / (numTeeth - 1);
    let lx = lerp(xStart, xEnd, t);
    let curveY = yBase + Math.sin(t * Math.PI) * 18 * sc;

    // Check if tooth is in the closed (interlocked) section or parted section
    let parted = lx > sliderX;
    let gap = parted ? Math.min(22 * sc, (lx - sliderX) * 0.14) : 0;

    if (!parted) {
      // Interlocked alternating teeth: top tooth and bottom tooth mesh together on the centerline
      let isTop = i % 2 === 0;
      let ty0 = isTop ? curveY - 6.5 * sc : curveY + 6.5 * sc;
      let ty1 = isTop ? curveY + 1.8 * sc : curveY - 1.8 * sc;
      let pBase = xform(lx, ty0, cx, cy, ang);
      let pTip = xform(lx, ty1, cx, cy, ang);

      // Tooth leg gripping the corded tape beaded edge
      brush.set("xray_pen", PAL.milkBright, 0.85 * sc);
      brush.line(pBase[0], pBase[1], pTip[0], pTip[1]);

      // Bright white locking crown nub at the tooth tip (where teeth overlap on centerline!)
      let nub0 = xform(lx - 1.1 * sc, ty1, cx, cy, ang);
      let nub1 = xform(lx + 1.1 * sc, ty1, cx, cy, ang);
      brush.set("xray_pen", PAL.whitePure, 1.25 * sc);
      brush.line(nub0[0], nub0[1], nub1[0], nub1[1]);
    } else {
      // Parted zipper tracks: both upper and lower rows of teeth visible separately!
      for (let row of [-1, 1]) {
        let tyBase = curveY + row * (gap + 6.5 * sc);
        let tyTip = curveY + row * gap;
        let p0 = xform(lx, tyBase, cx, cy, ang);
        let p1 = xform(lx, tyTip, cx, cy, ang);
        brush.set("xray_pen", PAL.milkBright, 0.8 * sc);
        brush.line(p0[0], p0[1], p1[0], p1[1]);

        let nub0 = xform(lx - 0.9 * sc, tyTip, cx, cy, ang);
        let nub1 = xform(lx + 0.9 * sc, tyTip, cx, cy, ang);
        brush.set("xray_pen", PAL.whitePure, 1.1 * sc);
        brush.line(nub0[0], nub0[1], nub1[0], nub1[1]);
      }
    }
  }

  // Die-Cast Zinc-Alloy Zipper Slider & Pull Tab at sliderX
  let sT = (sliderX - xStart) / (xEnd - xStart);
  let sliderY = yBase + Math.sin(sT * Math.PI) * 18 * sc;

  let sliderBody = [
    xform(sliderX - 18 * sc, sliderY - 11 * sc, cx, cy, ang),
    xform(sliderX + 18 * sc, sliderY - 15 * sc, cx, cy, ang),
    xform(sliderX + 20 * sc, sliderY + 15 * sc, cx, cy, ang),
    xform(sliderX - 18 * sc, sliderY + 11 * sc, cx, cy, ang)
  ];
  xrayBloomPoly(sliderBody, sliderBody[0][0], sliderBody[0][1], PAL.cyanBright, 38, 3, 1.35);
  xrayWash(sliderBody, PAL.milkBright, 175);
  xrayWash(sliderBody, PAL.whitePure, 95);
  brush.set("xray_pen", PAL.whitePure, 1.05 * sc);
  strokePoly(sliderBody, true, 0.08);

  // Internal Y-channel throat visible inside the zipper slider in X-ray!
  let yThroat = [
    xform(sliderX + 16 * sc, sliderY - 10 * sc, cx, cy, ang),
    xform(sliderX - 4 * sc, sliderY, cx, cy, ang),
    xform(sliderX + 16 * sc, sliderY + 10 * sc, cx, cy, ang)
  ];
  brush.set("xray_pen", PAL.bgIndigo, 0.9 * sc);
  strokePoly(yThroat, false, 0.15);

  // Hanging Metal Pull Tab with Rectangular Cutout Slot
  let pullAng = ang + 52;
  let sliderW = xform(sliderX, sliderY, cx, cy, ang);
  let pullTab = roundRectPts(26 * sc, 0, 48 * sc, 20 * sc, 7 * sc, sliderW[0], sliderW[1], pullAng, 5);
  let pullHole = roundRectPts(32 * sc, 0, 22 * sc, 8 * sc, 3 * sc, sliderW[0], sliderW[1], pullAng, 4);
  xrayWash(pullTab, PAL.milkBright, 165);
  xrayWash(pullHole, PAL.veilMid, 120);
  brush.set("xray_pen", PAL.whitePure, 1.0 * sc);
  strokePoly(pullTab, true, 0.08);
  strokePoly(pullHole, true, 0.08);
}

// =============================================================================
// 11. OVERLAPPING DENSITY HIGHLIGHTS, FILM BLOOM & SCANNER ARTIFACTS
// =============================================================================
function drawSpecularOverlapsAndFilmFinish(bagCX, bagCY, bagAngle) {
  // 1. Explicit additive density highlight zones where major objects cross one another:
  //    - Umbrella ribs crossing beneath the Left Side / Camera / PCB of the Smartphone
  //    - Key 2 blade crossing over the Top-Left of the Umbrella ribs & Inner Pocket Zipper
  const overlapPolys = [
    // Umbrella shaft & ribs crossing the left edge of the smartphone
    roundRectPts(-152, -32, 68, 95, 6, 735, 675, -11),
    // Key 2 blade overlapping the inner pocket zipper & umbrella ribs
    roundRectPts(65, 22, 54, 18, 3, 435, 415, 40)
  ];

  for (let poly of overlapPolys) {
    xrayWash(poly, PAL.milkBright, 55);
  }

  // 2. Soft Film Halation / Bloom Spray Passes over brightest metallic clusters
  const bloomCenters = [
    [435, 415, 95],   // Key ring cluster
    [735, 675, 110],  // Smartphone logic board & coils
    [590, 560, 85],   // Umbrella runner hub & smartphone camera overlap
    [350, 790, 65],   // Lipstick swivel mechanism
    [660, 965, 75],   // Overlapping coins
    [235, 565, 45],   // Perfume atomizer pump
    [720, 290, 60]    // Main zipper slider
  ];

  for (let b of bloomCenters) {
    brush.set("xray_bloom", PAL.cyanGlow, 1.3);
    brush.circle(b[0], b[1], b[2], 0.25);
    brush.set("xray_bloom", PAL.whitePure, 0.85);
    brush.circle(b[0], b[1], b[2] * 0.55, 0.2);
  }

  // 3. Delicate Soft White Pencil Contour Shading Across Ghostly Leather Folds
  for (let i = 0; i < 28; i++) {
    let lx = map(i, 0, 27, -480, 480);
    let ly0 = -310 + sin(i * 22) * 35;
    let ly1 = 420 + cos(i * 18) * 35;
    let p0 = xform(lx, ly0, bagCX, bagCY, bagAngle);
    let pMid = xform(lx + sin(i * 35) * 28, (ly0 + ly1) * 0.5, bagCX, bagCY, bagAngle);
    let p1 = xform(lx, ly1, bagCX, bagCY, bagAngle);
    brush.set("xray_pencil", PAL.veilLight, 0.45);
    brush.spline([p0, pMid, p1], 0.35);
  }

  // 4. Subtle Clinical Radiograph Calibration Ticks & Film Border Grain at Hard-Cropped Edges
  // Top-right and bottom-left radiographic calibration scales (ultra-fine technical pen)
  for (let t = 0; t <= 40; t++) {
    let pos = 45 + t * 8;
    let len = t % 10 === 0 ? 14 : t % 5 === 0 ? 9 : 5;
    // Top-right edge calibration ticks
    brush.set("xray_pen", PAL.cyanMid, t % 10 === 0 ? 0.65 : 0.42);
    brush.line(1182 - len, pos, 1182, pos);
    // Bottom-left edge calibration ticks
    brush.line(pos, 1182 - len, pos, 1182);
  }

  // Tiny radiographic crosshairs near corners
  const crosshairs = [
    [38, 38],
    [1162, 38],
    [38, 1162],
    [1162, 1162]
  ];
  for (let ch of crosshairs) {
    brush.set("xray_pen", PAL.cyanMid, 0.55);
    brush.line(ch[0] - 10, ch[1], ch[0] + 10, ch[1]);
    brush.line(ch[0], ch[1] - 10, ch[0], ch[1] + 10);
    let cPts = ellipsePts(0, 0, 5, 5, ch[0], ch[1], 0, 14);
    strokePoly(cPts, true, 0.1);
  }
}

