// MOTION: Iridescent soap bubbles wobble and swirl as three hero domes pop in a chain reaction, spraying droplets and ripples across the brushed steel sink.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

// Hyperrealistic Dish-Soap Foam in a Brushed Steel Kitchen Sink
// Wet-in-wet opal watercolour washes & crisp graphite pencil arcs (p5.brush)

const SEED = 4281;

const PALETTE = {
  paper: "#edf2f6",
  steelDarkest: "#182026",
  steelDeep: "#28333c",
  steelShadow: "#3d4b56",
  steelMid: "#5c6b77",
  steelLight: "#8a99a6",
  steelBright: "#bac6d0",
  steelGleam: "#e2eaf0",

  milkBase: "#e4edf4",
  milkBright: "#f5f9fc",
  milkShadow: "#adc0cf",
  pureWhite: "#ffffff",

  // Opal play-of-colour (Peacock Blue primary accent + electric flashes)
  peacockDeep: "#005f7a",
  peacockMid: "#0091b5",
  peacockBright: "#00bfe0",
  peacockPale: "#6ce5f7",

  electricGreen: "#00d46a",
  chartreuse: "#7bf1a8",

  violetDeep: "#621b99",
  violetBright: "#9d4edd",
  magentaFlash: "#d06bf7",

  tangerine: "#ff6d00",
  amberGlow: "#ffaa1d",

  graphiteDark: "#222b33",
  graphiteMid: "#465461",
  graphiteLight: "#768694",
  graphiteFaint: "#9eadba"
};

let bubbles = [];
let microBubbles = [];
let septums = [];
let plateauNodes = [];

// Animation state cached after Frame 0
let stillImg = null;
let animBubbles = [];
let popEvents = [];
let slidingDrops = [];
let steelRipples = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom brushes for specular glints, thin-film streaks, and fine froth
  brush.add("film_glaze", {
    type: "marker",
    weight: 4,
    scatter: 0.15,
    opacity: 28,
    spacing: 0.35,
    pressure: [0.3, 1.2, 0.3],
    markerTip: false,
    noise: 0.3
  });

  brush.add("razor_pencil", {
    type: "default",
    weight: 0.42,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 0.45,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.4, 1.15, 0.35],
    noise: 0.25
  });

  brush.add("specular_nib", {
    type: "default",
    weight: 0.85,
    scatter: 0.02,
    sharpness: 0.95,
    grain: 0.15,
    opacity: 250,
    spacing: 0.1,
    pressure: [0.6, 1.3, 0.5],
    noise: 0.1
  });

  brush.add("froth_stipple", {
    type: "spray",
    weight: 3.2,
    scatter: 2.4,
    opacity: 95,
    spacing: 0.45,
    pressure: [0.6, 1.1, 0.6],
    noise: 0.5
  });

  // Add a custom gentle sink-brush vector field
  brush.addField("steel_grain", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        // Subtle sweeping curve of a pressed stainless steel sink basin
        let baseAngle = -16 + 14 * sin(nx * 140 - ny * 90) + 6 * cos(ny * 180);
        field[col][row] = baseAngle;
      }
    }
    return field;
  });

  buildFoamGeometry();
}

function draw() {
  if (frameCount > TOTAL_FRAMES) return;
  translate(-width / 2, -height / 2);

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    initAnimation();
    return;
  }

  const t = (frameCount - 1) / window.PIECE_FPS;
  drawAnimatedFrame(t);
}

function paintStill() {
  background(PALETTE.paper);

  // 1. Brushed Stainless Steel Sink Basin
  drawBrushedSteelSink();

  // 2. Recessed Steel Sink Drain / Strainer (Upper Right)
  drawSinkDrain(915, 255, 195, 0.66, -14);

  // 3. Cast Shadow & Iridescent Caustics of the Foam Pile on Wet Steel
  drawFoamShadowsAndCaustics();

  // 4. Dense Milky Under-Foam & Whipped Suds Banks
  drawMilkyUnderFoam();

  // 5. Wet-in-Wet Watercolour Opal Iridescence (Batched by Colour for Smooth Bleeds)
  drawBatchedOpalWashes();

  // 6. Internal Pressed Bubble Walls (Septums) & Plateau Border Menisci
  drawInternalFoamWalls();

  // 7. Outer Bubble Domes, Colored Pencil Iridescent Rims & Micro-Froth
  drawBubbleDomesAndRims();

  // 8. Hyperrealistic Warped Window Reflections & Specular Highlights
  drawSpecularReflections();

  // 9. Stray Water Droplets & Final Crisp Graphite Accents
  drawSurfaceDetails();
}

// =============================================================================
// ANIMATION INITIALIZATION & PER-FRAME RENDERING
// =============================================================================
function initAnimation() {
  randomSeed(SEED + 9001);
  noiseSeed(SEED + 9001);

  let scaleP = stillImg.width / width;

  // Identify the 3 hero bubbles that pop in a chain reaction:
  // Pop 1 (frame 5, t=0.17s): (605, 475, r~94) facing the upper-right steel drain
  // Pop 2 (frame 15, t=0.58s): (355, 455, r~106) crowning upper-left-center hero dome
  // Pop 3 (frame 27, t=1.08s): (750, 805, r~108) prominent lower-right hero dome
  const popTargets = [
    { tx: 605, ty: 475, popFrame: 5, steelAng: -32, driftAng: -22 },
    { tx: 355, ty: 455, popFrame: 15, steelAng: -125, driftAng: -65 },
    { tx: 750, ty: 805, popFrame: 27, steelAng: 28, driftAng: -12 }
  ];

  let popMap = new Map();
  for (let idx = 0; idx < popTargets.length; idx++) {
    let pt = popTargets[idx];
    let bestB = null;
    let bestD = 999999;
    for (let b of bubbles) {
      if (b.tier === 3) {
        let d = dist(b.x, b.y, pt.tx, pt.ty);
        if (d < bestD) {
          bestD = d;
          bestB = b;
        }
      }
    }
    if (bestB) {
      popMap.set(bestB.id, { ...pt, order: idx, bubble: bestB });
    }
  }

  // Lift circular image patches for all medium and hero bubbles (r >= 32)
  animBubbles = [];
  for (let b of bubbles) {
    if (b.r < 32) continue;

    let patchRad = ceil(b.r * 1.045);
    let pSize = patchRad * 2;
    let imgSize = round(pSize * scaleP);
    let patch = createImage(imgSize, imgSize);

    let srcX0 = round((b.x - patchRad) * scaleP);
    let srcY0 = round((b.y - patchRad) * scaleP);
    let dstX0 = 0;
    let dstY0 = 0;
    let copyW = imgSize;
    let copyH = imgSize;

    if (srcX0 < 0) { dstX0 = -srcX0; copyW += srcX0; srcX0 = 0; }
    if (srcY0 < 0) { dstY0 = -srcY0; copyH += srcY0; srcY0 = 0; }
    if (srcX0 + copyW > stillImg.width) copyW = stillImg.width - srcX0;
    if (srcY0 + copyH > stillImg.height) copyH = stillImg.height - srcY0;

    if (copyW > 0 && copyH > 0) {
      patch.copy(stillImg, srcX0, srcY0, copyW, copyH, dstX0, dstY0, copyW, copyH);
    }

    // Apply smooth circular feather mask so lifted bubble domes blend seamlessly
    patch.loadPixels();
    let half = imgSize * 0.5;
    let innerR = (b.r * 0.985) / patchRad;
    let outerR = 1.0;
    for (let py = 0; py < imgSize; py++) {
      let ny = (py + 0.5 - half) / half;
      for (let px = 0; px < imgSize; px++) {
        let nx = (px + 0.5 - half) / half;
        let rn = sqrt(nx * nx + ny * ny);
        let aIdx = 4 * (py * imgSize + px) + 3;
        if (rn >= outerR) {
          patch.pixels[aIdx] = 0;
        } else if (rn > innerR) {
          let u = (rn - innerR) / (outerR - innerR);
          let alpha = 1 - u * u * (3 - 2 * u);
          patch.pixels[aIdx] = round(255 * alpha);
        }
      }
    }
    patch.updatePixels();

    // Find unobstructed outer rim angular segments for crisp dynamic graphite redraw
    let freeArcs = [];
    let numSegs = 24;
    let segStep = 360 / numSegs;
    for (let s = 0; s < numSegs; s++) {
      let a1 = s * segStep;
      let a2 = a1 + segStep + 2;
      let aMid = (a1 + a2) * 0.5;
      let px = b.x + cos(aMid) * b.r;
      let py = b.y + sin(aMid) * b.r;
      let buriedCount = 0;
      for (let other of bubbles) {
        if (other.id === b.id) continue;
        if (dist(px, py, other.x, other.y) < other.r * 0.94) {
          buriedCount += other.id > b.id ? 2 : 1;
        }
      }
      if (buriedCount === 0) {
        freeArcs.push({ a1, a2, aMid });
      }
    }

    let popInfo = popMap.get(b.id) || null;

    animBubbles.push({
      ...b,
      patchImg: patch,
      patchRad: patchRad,
      freeArcs: freeArcs,
      seed: SEED + 1000 + b.id * 73,
      phase: random(360),
      freq: random(190, 250),
      popFrame: popInfo ? popInfo.popFrame : 9999,
      popInfo: popInfo,
      isPoppedNow: false,
      curX: b.x,
      curY: b.y,
      state: { dx: 0, dy: 0, sx: 1, sy: 1, axisAng: 0, dRot: 0 }
    });
  }

  // Build detailed sub-bubbles, soap-ring beads, spray droplets, and daughter bubbles for each pop
  popEvents = [];
  for (let ab of animBubbles) {
    if (!ab.popInfo) continue;
    randomSeed(ab.seed + 555);

    // Pre-generate 8 sub-bubbles revealed in the foam pocket underneath the popped dome
    let subBubbles = [];
    let accents = ["peacock", "green", "violet", "tangerine", "peacock"];
    let baseFoamAng = ab.popInfo.steelAng + 180;
    for (let k = 0; k < 8; k++) {
      let a = baseFoamAng + map(k, 0, 7, -115, 115) + random(-12, 12);
      let d = ab.r * random(0.22, 0.66);
      if (k < 2) d = ab.r * random(0.08, 0.28);
      let sr = map(k % 3, 0, 2, 17, 29) * random(0.9, 1.1);
      subBubbles.push({
        lx: cos(a) * d,
        ly: sin(a) * d,
        r: sr,
        accent: accents[k % accents.length],
        rot: random(360),
        phase: random(360),
        seed: ab.seed + 2000 + k * 31
      });
    }

    // Beaded micro-bubble soap ring left on the exposed steel rim
    let ringMicros = [];
    for (let k = 0; k < 22; k++) {
      let a = ab.popInfo.steelAng + map(k, 0, 21, -95, 95) + random(-5, 5);
      let d = ab.r * random(0.84, 0.99);
      ringMicros.push({
        lx: cos(a) * d,
        ly: sin(a) * d,
        r: random(2.4, 6.2)
      });
    }

    // 22 flying soap droplets & iridescent mist beads
    let sprayDrops = [];
    const dropCols = [
      PALETTE.peacockPale,
      PALETTE.chartreuse,
      PALETTE.amberGlow,
      PALETTE.magentaFlash,
      PALETTE.milkBright,
      PALETTE.pureWhite
    ];
    for (let k = 0; k < 22; k++) {
      let a = k * (360 / 22) + random(-8, 8);
      let spd = random(180, 390);
      sprayDrops.push({
        ang: a,
        spd: spd,
        startR: ab.r * random(0.28, 0.68),
        r: random(2.2, 5.2),
        col: dropCols[k % dropCols.length],
        lifeFrames: floor(random(11, 20)),
        gravity: random(90, 180)
      });
    }

    // Floating translucent daughter bubble pinched off from the collapsing film
    let daughter = {
      startX: ab.x + cos(ab.popInfo.steelAng) * (ab.r * 0.32),
      startY: ab.y + sin(ab.popInfo.steelAng) * (ab.r * 0.32),
      vx: cos(ab.popInfo.driftAng) * 92,
      vy: sin(ab.popInfo.driftAng) * 92,
      r: random(15, 19),
      accent: ab.accent,
      seed: ab.seed + 888
    };

    popEvents.push({
      ab: ab,
      popFrame: ab.popFrame,
      steelAng: ab.popInfo.steelAng,
      subBubbles: subBubbles,
      ringMicros: ringMicros,
      sprayDrops: sprayDrops,
      daughter: daughter,
      seed: ab.seed + 777
    });
  }

  // Schedule expanding specular ripples on the wet brushed steel where droplets hit
  steelRipples = [
    { x: 735, y: 365, startFrame: 9, maxR: 48, seed: SEED + 401 },
    { x: 815, y: 430, startFrame: 11, maxR: 38, seed: SEED + 402 },
    { x: 655, y: 295, startFrame: 13, maxR: 42, seed: SEED + 403 },
    { x: 205, y: 285, startFrame: 19, maxR: 50, seed: SEED + 404 },
    { x: 435, y: 240, startFrame: 21, maxR: 40, seed: SEED + 405 },
    { x: 965, y: 785, startFrame: 31, maxR: 52, seed: SEED + 406 },
    { x: 1035, y: 865, startFrame: 33, maxR: 42, seed: SEED + 407 }
  ];

  // Select 4 existing water droplets on the sloped steel sink to slide toward the drain
  slidingDrops = [
    { x0: 645, y0: 165, rx: 14, ry: 9, rot: -15, vx: 28, vy: 11, seed: SEED + 501 },
    { x0: 705, y0: 210, rx: 8, ry: 6, rot: -12, vx: 34, vy: 13, seed: SEED + 502 },
    { x0: 845, y0: 425, rx: 10, ry: 7, rot: -15, vx: 22, vy: -18, seed: SEED + 503 },
    { x0: 1055, y0: 585, rx: 16, ry: 11, rot: -14, vx: -16, vy: -24, seed: SEED + 504 }
  ];
}

function drawAnimatedFrame(t) {
  // Smooth ease-in over first 3 frames so Frame 1 continues Frame 0 without a jump
  let env = constrain(t / 0.12, 0, 1);
  env = env * env * (3 - 2 * env);

  // 1. Stamp the cached Frame 0 still as the base layer
  background(PALETTE.paper);
  image(stillImg, 0, 0, width, height);

  // 2. Update physics state (wobble, shockwave recoil, pre-pop tension) for all bubbles
  updateBubblePhysics(t, env);

  // 3. Stamp the deformed lifted bubble patches in depth order (skipping popped bubbles)
  for (let ab of animBubbles) {
    if (ab.isPoppedNow) continue;
    let st = ab.state;
    push();
    translate(ab.x + st.dx, ab.y + st.dy);
    rotate(st.axisAng);
    scale(st.sx, st.sy);
    rotate(-st.axisAng + st.dRot);
    image(ab.patchImg, -ab.patchRad, -ab.patchRad, ab.patchRad * 2, ab.patchRad * 2);
    pop();
  }

  // 4. Paint the uncovered wet steel, soap rings, and sub-foam craters for popped bubbles
  for (let pe of popEvents) {
    if (frameCount >= pe.popFrame) {
      drawPoppedBubbleFootprint(pe, frameCount - pe.popFrame, t);
    }
  }

  // 5. Paint dynamic swirling thin-film iridescence, pre-pop apex drainage, and crisp rims on surviving domes
  drawDynamicBubbleOverlays(t, env);

  // 6. Paint sliding droplets and expanding impact ripples on the wet brushed steel
  drawAnimatedSteelDetails(t, env);

  // 7. Paint high-speed rupture rings, flying soap droplets, and floating daughter bubbles
  for (let pe of popEvents) {
    if (frameCount >= pe.popFrame) {
      drawPopBurstAndDaughter(pe, frameCount - pe.popFrame, t);
    }
  }
}

// =============================================================================
// PHYSICS UPDATE: SURFACE TENSION WOBBLE, PRE-POP SWELL & SHOCKWAVE RECOIL
// =============================================================================
function updateBubblePhysics(t, env) {
  const drainX = 915;
  const drainY = 255;

  for (let ab of animBubbles) {
    ab.isPoppedNow = frameCount >= ab.popFrame;

    // Gentle gravitational creep toward the recessed steel sink drain
    let toDrainAng = atan2(drainY - ab.y, drainX - ab.x);
    let creepDist = env * t * map(ab.r, 32, 140, 1.4, 3.2);
    let dx = cos(toDrainAng) * creepDist;
    let dy = sin(toDrainAng) * creepDist;

    // Continuous capillary surface-tension wave across the foam mound
    let wavePhase = t * 310 - (ab.x * 0.32 - ab.y * 0.24) + ab.phase;
    let baseAniso = env * 0.028 * sin(wavePhase);
    let dRot = env * 2.4 * cos(wavePhase * 0.85);

    dx += env * 1.6 * cos(wavePhase);
    dy += env * 1.4 * sin(wavePhase);

    // Pre-pop rapid tension swell in the 4 frames right before a hero bubble pops
    let preSwell = 0;
    let axisAng = -25 + (ab.id * 29) % 180;
    if (!ab.isPoppedNow && ab.popFrame < 999) {
      let framesToPop = ab.popFrame - frameCount;
      if (framesToPop <= 4) {
        let u = map(framesToPop, 4, 1, 0.22, 1.0);
        u = u * u;
        preSwell = 0.072 * u;
        // High-frequency surface tremor right before rupture
        let tremor = sin(frameCount * 135) * 0.022 * u;
        baseAniso += 0.035 * u + tremor;
        axisAng = ab.popInfo.steelAng;
      }
    }

    // Accumulate radial elastic shockwaves from all pops that have occurred
    let shockAniso = 0;
    let maxShockWeight = 0;
    for (let pe of popEvents) {
      if (pe.ab.id === ab.id) continue;
      if (frameCount < pe.popFrame) continue;

      let popTime = (pe.popFrame - 1) / window.PIECE_FPS;
      let d = dist(ab.x, ab.y, pe.ab.x, pe.ab.y);
      let vShock = 560;
      let arrivalDelay = max(0, (d - pe.ab.r * 0.65) / vShock);
      let dtShock = t - (popTime + arrivalDelay);

      if (dtShock > 0) {
        let atten = constrain(map(d, 90, 560, 1.0, 0.14), 0.14, 1.0);
        // Damped harmonic jello oscillation
        let ring = exp(-dtShock * 3.8) * sin(dtShock * 560);
        let pushOut = atten * (max(0, ring) * 7.5 + exp(-dtShock * 2.8) * 3.8);
        let rAng = atan2(ab.y - pe.ab.y, ab.x - pe.ab.x);

        dx += cos(rAng) * pushOut;
        dy += sin(rAng) * pushOut;

        let localShock = atten * ring * 0.068;
        shockAniso += localShock;
        if (atten * exp(-dtShock * 2.5) > maxShockWeight) {
          maxShockWeight = atten * exp(-dtShock * 2.5);
          axisAng = rAng;
        }
      }
    }

    let totalAniso = constrain(baseAniso + shockAniso, -0.085, 0.085);
    let shiftRatio = sqrt(dx * dx + dy * dy) / ab.r;
    // Keep minimum scale >= 1 + shiftRatio so lifted patch always covers its static footprint
    let minScale = 1.0 + shiftRatio * 0.95 + 0.008 * env + preSwell;

    let sx, sy;
    if (totalAniso >= 0) {
      sx = minScale + totalAniso * 1.18;
      sy = minScale;
    } else {
      sx = minScale;
      sy = minScale + (-totalAniso) * 1.18;
    }

    ab.curX = ab.x + dx;
    ab.curY = ab.y + dy;
    ab.state = { dx, dy, sx, sy, axisAng, dRot, preSwell, totalAniso };
  }
}

function bubbleWorldPt(ab, lx, ly) {
  let st = ab.state;
  let ca = cos(st.axisAng);
  let sa = sin(st.axisAng);
  let rx = lx * ca + ly * sa;
  let ry = -lx * sa + ly * ca;
  rx *= st.sx;
  ry *= st.sy;
  let wx = rx * ca - ry * sa;
  let wy = rx * sa + ry * ca;
  return [ab.x + st.dx + wx, ab.y + st.dy + wy];
}

// =============================================================================
// POPPED BUBBLE CRATER: EXPOSED WET STEEL, SOAP RING & SUB-FOAM BUBBLES
// =============================================================================
function clampCraterPt(wx, wy, popB) {
  for (let other of animBubbles) {
    if (other.id === popB.id || other.isPoppedNow) continue;
    let ox = other.curX;
    let oy = other.curY;
    let dCenters = dist(popB.x, popB.y, ox, oy);
    if (dCenters >= (popB.r + other.r) * 1.08) continue;

    let keepOutR;
    if (other.id > popB.id) {
      keepOutR = other.r * 1.015;
    } else if (other.tier === 3) {
      let aOther = (other.r * other.r - popB.r * popB.r + dCenters * dCenters) / (2 * dCenters);
      keepOutR = constrain(aOther, other.r * 0.84, other.r * 0.98);
    } else {
      continue;
    }

    let dx = wx - ox;
    let dy = wy - oy;
    let dPt = sqrt(dx * dx + dy * dy);
    if (dPt < keepOutR && dPt > 0.001) {
      wx = ox + (dx / dPt) * keepOutR;
      wy = oy + (dy / dPt) * keepOutR;
    }
  }
  return [wx, wy];
}

function makeClampedDisk(popB, cx, cy, rx, ry, rotDeg, steps) {
  let pts = [];
  let stepA = 360 / steps;
  for (let i = 0; i < steps; i++) {
    let ep = ellipsePt(cx, cy, rx, ry, rotDeg, i * stepA);
    pts.push(clampCraterPt(ep[0], ep[1], popB));
  }
  return pts;
}

function drawPoppedBubbleFootprint(pe, dtFrames, t) {
  let popB = pe.ab;
  randomSeed(pe.seed);
  noiseSeed(pe.seed);

  brush.noField();
  brush.noStroke();
  brush.noFill();

  // 1. Opaque paper reset wash over the popped dome's clamped footprint to erase old highlights
  brush.wash(PALETTE.paper, 248);
  drawSmoothPoly(makeClampedDisk(popB, popB.x, popB.y, popB.r * 1.04, popB.r * 1.04, 0, 28), 0.3);

  // 2. Brushed stainless steel under-washes matching the local sink basin gradient
  brush.wash(PALETTE.steelMid, 125);
  drawSmoothPoly(makeClampedDisk(popB, popB.x, popB.y, popB.r * 1.03, popB.r * 1.03, 0, 24), 0.3);

  let sAng = pe.steelAng;
  let offSteelX = popB.x + cos(sAng) * (popB.r * 0.22);
  let offSteelY = popB.y + sin(sAng) * (popB.r * 0.22);
  brush.wash(PALETTE.steelLight, 95);
  drawSmoothPoly(makeClampedDisk(popB, offSteelX, offSteelY, popB.r * 0.85, popB.r * 0.78, -14, 20), 0.3);

  // Deep contact shadow under the remaining foam ledge
  let offFoamX = popB.x - cos(sAng) * (popB.r * 0.18);
  let offFoamY = popB.y - sin(sAng) * (popB.r * 0.18);
  brush.wash(PALETTE.steelDeep, 125);
  drawSmoothPoly(makeClampedDisk(popB, offFoamX, offFoamY, popB.r * 0.82, popB.r * 0.78, sAng + 90, 20), 0.3);

  // Peacock caustic refraction on the wet steel inside the popped footprint
  brush.wash(PALETTE.peacockMid, 48);
  drawSmoothPoly(makeClampedDisk(popB, offSteelX, offSteelY, popB.r * 0.65, popB.r * 0.48, -14, 16), 0.35);

  // Milky under-foam lather bed in the foam-facing half of the crater
  brush.wash(PALETTE.milkShadow, 155);
  drawSmoothPoly(makeClampedDisk(popB, offFoamX, offFoamY, popB.r * 0.74, popB.r * 0.68, sAng + 90, 18), 0.35);

  brush.wash(PALETTE.milkBase, 175);
  drawSmoothPoly(makeClampedDisk(popB, offFoamX, offFoamY, popB.r * 0.66, popB.r * 0.60, sAng + 90, 18), 0.35);
  brush.noWash();

  // 3. Brushed steel grain lines across the newly exposed metal
  for (let i = 0; i < 14; i++) {
    let ly = map(i, 0, 13, -popB.r * 0.78, popB.r * 0.78);
    let halfLen = sqrt(max(10, popB.r * popB.r * 0.88 - ly * ly));
    let p1 = clampCraterPt(
      popB.x + cos(-14) * (-halfLen) - sin(-14) * ly,
      popB.y + sin(-14) * (-halfLen) + cos(-14) * ly,
      popB
    );
    let p2 = clampCraterPt(
      popB.x + cos(-14) * halfLen - sin(-14) * ly,
      popB.y + sin(-14) * halfLen + cos(-14) * ly,
      popB
    );
    if (i % 2 === 0) {
      brush.set("2H", PALETTE.steelShadow, 0.65);
    } else {
      brush.set("razor_pencil", PALETTE.steelGleam, 0.75);
    }
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 4. Newly uncovered sub-bubbles jiggling in the crater pocket
  let recoil = exp(-dtFrames * 0.22) * sin(dtFrames * 46);
  for (let sb of pe.subBubbles) {
    randomSeed(sb.seed);
    let wob = 1.0 + recoil * 0.08 * sin(sb.phase + dtFrames * 25);
    let sx = popB.x + sb.lx * (1 + recoil * 0.05);
    let sy = popB.y + sb.ly * (1 + recoil * 0.05);
    let cPt = clampCraterPt(sx, sy, popB);
    // Skip if center was clamped right onto a foreground boundary
    if (dist(sx, sy, cPt[0], cPt[1]) > sb.r * 0.35) continue;

    let rx = sb.r * wob;
    let ry = sb.r * (2 - wob);

    brush.noStroke();
    brush.wash(PALETTE.milkBase, 190);
    drawEllipsePoly(sx, sy, rx, ry, 0, 10, 0.35);

    brush.wash(PALETTE.steelShadow, 95);
    drawSmoothPoly(makeCrescentPoly(sx, sy, rx * 0.72, rx * 0.32, -60, 130), 0.35);

    let opalCol = sb.accent === "green"
      ? PALETTE.electricGreen
      : (sb.accent === "violet" ? PALETTE.violetBright : (sb.accent === "tangerine" ? PALETTE.tangerine : PALETTE.peacockBright));
    brush.wash(opalCol, 115);
    drawSmoothPoly(makeCrescentPoly(sx, sy, rx * 0.82, rx * 0.42, sb.rot + t * 55, 135), 0.35);

    brush.wash(PALETTE.pureWhite, 235);
    drawSmoothPoly(makeSphericalWindowPatch(sx, sy, rx, 205, 252, 0.52, 0.78), 0.25);
    brush.noWash();

    brush.set("2H", PALETTE.graphiteDark, 0.72);
    brush.arc(sx, sy, (rx + ry) * 0.5, 0, 360);
  }

  // 5. Beaded soap-film footprint ring of micro-bubbles left on the wet steel
  for (let rm of pe.ringMicros) {
    let mx = popB.x + rm.lx;
    let my = popB.y + rm.ly;
    let cPt = clampCraterPt(mx, my, popB);
    if (dist(mx, my, cPt[0], cPt[1]) > 2.5) continue;

    brush.noStroke();
    brush.wash(PALETTE.milkBright, 210);
    drawEllipsePoly(mx, my, rm.r, rm.r, 0, 6, 0.25);
    brush.wash(PALETTE.pureWhite, 245);
    drawEllipsePoly(mx - rm.r * 0.28, my - rm.r * 0.28, rm.r * 0.35, rm.r * 0.35, 0, 5, 0.2);
    brush.noWash();

    brush.set("2H", PALETTE.graphiteMid, 0.48);
    brush.circle(mx, my, rm.r, 0.1);
  }

  // 6. Re-stroke crisp septum walls where surviving bubbles press against the crater
  for (let other of animBubbles) {
    if (other.id === popB.id || other.isPoppedNow) continue;
    let d = dist(popB.x, popB.y, other.curX, other.curY);
    if (d < (popB.r + other.r) * 1.02) {
      let aMid = atan2(popB.y - other.curY, popB.x - other.curX);
      let span = 34;
      brush.set("2H", PALETTE.graphiteDark, 1.05);
      brush.arc(other.curX, other.curY, other.r * 1.005, aMid - span, aMid + span);
      brush.set("specular_nib", PALETTE.pureWhite, 0.8);
      brush.arc(other.curX, other.curY, other.r * 0.99, aMid - span * 0.85, aMid + span * 0.85);
    }
  }
}

// =============================================================================
// DYNAMIC SWIRLING IRIDESCENCE, PRE-POP APEX FLASH & CRISP WOBBLING RIMS
// =============================================================================
function drawDynamicBubbleOverlays(t, env) {
  brush.noField();

  const glazeCols = [
    PALETTE.peacockBright,
    PALETTE.electricGreen,
    PALETTE.violetBright,
    PALETTE.tangerine,
    PALETTE.peacockPale,
    PALETTE.chartreuse,
    PALETTE.magentaFlash
  ];

  for (let ab of animBubbles) {
    if (ab.isPoppedNow) continue;
    randomSeed(ab.seed);
    noiseSeed(ab.seed);

    let swirlDeg = t * (52 + (ab.id % 5) * 11) * ab.swirlDir;

    // A) Swirling thin-film interference ribbons inside hero & medium bubbles
    if (ab.r > 44) {
      let count = ab.tier === 3 ? 4 : 2;
      for (let k = 0; k < count; k++) {
        let startA = ab.rot + k * (360 / count) + swirlDeg;
        let spanA = 65 + (k % 2) * 28;
        let rad = ab.r * map(k, 0, count - 1, 0.44, 0.82);
        let col = glazeCols[(ab.id + k) % glazeCols.length];

        let pts = [];
        for (let u = 0; u <= 1.001; u += 0.25) {
          let a = startA + u * spanA;
          let rNow = rad * (1 - 0.1 * sin(u * 180));
          let wPt = bubbleWorldPt(ab, cos(a) * rNow, sin(a) * rNow);
          pts.push([wPt[0], wPt[1], (sin(u * 180) * 1.1 + 0.3) * env]);
        }
        brush.set("film_glaze", col, map(ab.r, 44, 140, 0.65, 1.35) * env);
        brush.spline(pts, 0.55);
      }
    }

    // B) Revolving colored-pencil iridescent rim crescents & electric sparkles
    if (ab.tier === 3) {
      for (let cIdx = 0; cIdx < 3; cIdx++) {
        let a1 = ab.rot + cIdx * 120 + swirlDeg * 0.7;
        let a2 = a1 + 52;
        let col = glazeCols[(ab.id + cIdx * 2) % glazeCols.length];
        let pts = [];
        for (let u = 0; u <= 1.001; u += 0.25) {
          let a = lerp(a1, a2, u);
          let wPt = bubbleWorldPt(ab, cos(a) * (ab.r * 0.955), sin(a) * (ab.r * 0.955));
          pts.push([wPt[0], wPt[1], 0.85 * env]);
        }
        brush.set("cpencil", col, map(ab.r, 70, 140, 0.65, 1.15) * env);
        brush.spline(pts, 0.5);
      }

      // Orbiting opal flecks
      brush.noStroke();
      for (let k = 0; k < 4; k++) {
        let a = ab.rot + k * 90 + swirlDeg * 1.15;
        let rad = ab.r * (0.58 + 0.18 * sin(k * 77 + t * 180));
        let wPt = bubbleWorldPt(ab, cos(a) * rad, sin(a) * rad);
        let sCol = glazeCols[(ab.id + k * 3) % glazeCols.length];
        brush.wash(sCol, round(210 * env));
        drawEllipsePoly(wPt[0], wPt[1], 4.2, 2.2, a + 90, 6, 0.25);
      }
      brush.noWash();

      // Crisp dynamic graphite & specular arcs along unobstructed outer dome segments
      if (abs(ab.state.totalAniso) > 0.012 || ab.state.preSwell > 0) {
        for (let seg of ab.freeArcs) {
          let pts = [];
          for (let u = 0; u <= 1.001; u += 0.5) {
            let a = lerp(seg.a1, seg.a2, u);
            let wPt = bubbleWorldPt(ab, cos(a) * ab.r, sin(a) * ab.r);
            pts.push([wPt[0], wPt[1], 0.9]);
          }
          brush.set("2H", PALETTE.graphiteDark, map(ab.r, 70, 140, 0.7, 1.2) * env);
          brush.spline(pts, 0.45);
        }
      }
    }

    // C) Pre-pop apex membrane thinning & tension flash (4 frames prior to rupture)
    if (ab.state.preSwell > 0.001) {
      let u = constrain(ab.state.preSwell / 0.072, 0, 1);
      let pAng = ab.popInfo.steelAng;
      let apexPt = bubbleWorldPt(ab, cos(pAng) * (ab.r * 0.45), sin(pAng) * (ab.r * 0.45));

      brush.noStroke();
      brush.wash(PALETTE.tangerine, round(135 * u));
      drawEllipsePoly(apexPt[0], apexPt[1], ab.r * 0.36 * u, ab.r * 0.24 * u, pAng + 90, 10, 0.35);

      brush.wash(PALETTE.peacockPale, round(165 * u));
      drawEllipsePoly(apexPt[0], apexPt[1], ab.r * 0.26 * u, ab.r * 0.16 * u, pAng + 90, 10, 0.35);

      brush.wash(PALETTE.pureWhite, round(235 * u));
      drawEllipsePoly(apexPt[0], apexPt[1], ab.r * 0.15 * u, ab.r * 0.09 * u, pAng + 90, 8, 0.3);
      brush.noWash();

      // Tension fracture hairlines radiating around the thinning apex
      brush.set("specular_nib", PALETTE.pureWhite, 1.1 * u);
      brush.arc(ab.curX, ab.curY, ab.r * (0.68 + 0.18 * u), pAng - 38 * u, pAng + 38 * u);
    }
  }
}

// =============================================================================
// POP BURST RING, FLYING SOAP DROPLETS & FLOATING DAUGHTER BUBBLES
// =============================================================================
function drawPopBurstAndDaughter(pe, dtFrames, t) {
  let popB = pe.ab;
  randomSeed(pe.seed + dtFrames * 17);
  noiseSeed(pe.seed + dtFrames * 17);
  brush.noField();

  // 1. Retracting soap-film rim & expanding atomized burst ring (first 11 frames after pop)
  if (dtFrames <= 11) {
    let u = dtFrames / 11;
    let easeOut = 1 - pow(1 - u, 2.2);
    let fade = 1 - u;
    let ringR = popB.r * lerp(0.38, 1.48, easeOut);

    // Retracting liquid film roll in the first 5 frames
    if (dtFrames <= 5) {
      let uFilm = dtFrames / 5;
      let filmR = popB.r * lerp(0.32, 0.98, uFilm);
      let oppAng = pe.steelAng + 180;
      brush.noStroke();
      brush.wash(PALETTE.peacockPale, round(125 * (1 - uFilm)));
      drawSmoothPoly(
        makeCrescentPoly(popB.x, popB.y, popB.r * 0.96, filmR, oppAng, lerp(240, 85, uFilm)),
        0.35
      );
      brush.noWash();
    }

    //Segmented snapping meniscus arcs and iridescent mist flecks
    let numArcs = 12;
    for (let i = 0; i < numArcs; i++) {
      let a1 = i * (360 / numArcs) + dtFrames * 4;
      let a2 = a1 + (18 - u * 12);
      if (i % 2 === 0) {
        brush.set("specular_nib", PALETTE.pureWhite, 1.15 * fade);
      } else {
        let c = i % 4 === 1 ? PALETTE.peacockBright : PALETTE.tangerine;
        brush.set("cpencil", c, 1.05 * fade);
      }
      brush.arc(popB.x, popB.y, ringR + (i % 3) * 4, a1, a2);
    }

    // Fine spray puffs along the expanding shock ring
    if (dtFrames <= 7) {
      brush.set("froth_stipple", PALETTE.pureWhite, 0.95 * (1 - dtFrames / 8));
      for (let k = 0; k < 8; k++) {
        let a = pe.steelAng + map(k, 0, 7, -110, 110);
        let sx = popB.x + cos(a) * ringR;
        let sy = popB.y + sin(a) * ringR;
        brush.line(sx, sy, sx + cos(a) * 12, sy + sin(a) * 12);
      }
    }
  }

  // 2. Ballistic flying soap droplets & mist beads
  let dtSec = dtFrames / window.PIECE_FPS;
  for (let d of pe.sprayDrops) {
    if (dtFrames > d.lifeFrames) continue;
    let u = dtFrames / d.lifeFrames;
    let travel = d.startR + d.spd * dtSec * (1 - 0.32 * u);
    let dx = popB.x + cos(d.ang) * travel;
    let dy = popB.y + sin(d.ang) * travel + 0.5 * d.gravity * dtSec * dtSec;

    if (dx < 10 || dx > width - 10 || dy < 10 || dy > height - 10) continue;

    let fade = 1 - pow(u, 1.8);
    let dr = d.r * (0.65 + 0.35 * fade);

    // Motion streak tail during fast initial burst
    if (dtFrames <= 6) {
      let tailLen = map(dtFrames, 0, 6, 18, 5);
      brush.set("specular_nib", PALETTE.pureWhite, 0.75 * fade);
      brush.line(dx, dy, dx - cos(d.ang) * tailLen, dy - sin(d.ang) * tailLen);
    }

    // Droplet shadow, iridescent body & pinpoint specular glint
    brush.noStroke();
    brush.wash(PALETTE.steelDeep, round(130 * fade));
    drawEllipsePoly(dx + 2, dy + 2.5, dr, dr * 0.8, d.ang, 6, 0.25);

    brush.wash(d.col, round(215 * fade));
    drawEllipsePoly(dx, dy, dr, dr * 0.78, d.ang, 6, 0.25);

    brush.wash(PALETTE.pureWhite, round(250 * fade));
    drawEllipsePoly(dx - dr * 0.28, dy - dr * 0.28, dr * 0.42, dr * 0.35, d.ang, 5, 0.2);
    brush.noWash();
  }

  // 3. Detached translucent daughter bubble floating gently across the sink
  let db = pe.daughter;
  randomSeed(db.seed);
  let floatEase = 1 - exp(-dtSec * 2.4);
  let bx = db.startX + db.vx * floatEase + sin(dtSec * 320 + db.seed) * 6;
  let by = db.startY + db.vy * floatEase - 28 * dtSec + cos(dtSec * 260) * 4;
  let wob = 1 + 0.06 * sin(dtSec * 480);
  let brx = db.r * wob;
  let bry = db.r * (2 - wob);

  // Soft cast shadow below the floating daughter bubble
  brush.noStroke();
  brush.wash(PALETTE.steelDeep, 85);
  drawEllipsePoly(bx + 12, by + 16, brx * 0.9, bry * 0.75, -14, 8, 0.3);

  // Daughter bubble translucent film, iridescent crescent & window glint
  brush.wash(PALETTE.milkBase, 145);
  drawEllipsePoly(bx, by, brx, bry, 0, 10, 0.35);

  let dCol = db.accent === "tangerine" ? PALETTE.tangerine : PALETTE.peacockBright;
  brush.wash(dCol, 130);
  drawSmoothPoly(makeCrescentPoly(bx, by, brx * 0.84, brx * 0.44, 45 + dtSec * 120, 140), 0.35);

  brush.wash(PALETTE.electricGreen, 110);
  drawSmoothPoly(makeCrescentPoly(bx, by, brx * 0.76, brx * 0.42, 195 - dtSec * 110, 120), 0.35);

  brush.wash(PALETTE.pureWhite, 245);
  drawSmoothPoly(makeSphericalWindowPatch(bx, by, db.r, 204, 252, 0.52, 0.80), 0.25);
  brush.noWash();

  brush.set("2H", PALETTE.graphiteDark, 0.7);
  brush.arc(bx, by, db.r, 0, 360);
  brush.set("specular_nib", PALETTE.pureWhite, 0.75);
  brush.arc(bx, by, db.r * 0.97, 190, 290);
}

// =============================================================================
// ANIMATED WET STEEL DETAILS: SLIDING DROPLETS & EXPANDING RIPPLES
// =============================================================================
function drawAnimatedSteelDetails(t, env) {
  brush.noField();

  // 1. Sliding water droplets creeping toward the recessed steel sink drain
  for (let sd of slidingDrops) {
    randomSeed(sd.seed);
    let dx = sd.vx * t * env;
    let dy = sd.vy * t * env;
    let curX = sd.x0 + dx;
    let curY = sd.y0 + dy;

    // Cover original static droplet on stillImg with local brushed steel wash + grain
    brush.noStroke();
    brush.wash(PALETTE.paper, 240);
    drawEllipsePoly(sd.x0 + 1, sd.y0 + 1, sd.rx * 1.32, sd.ry * 1.35, sd.rot, 10, 0.3);
    let baseSteel = sd.y0 < 350 ? PALETTE.steelLight : PALETTE.steelMid;
    brush.wash(baseSteel, 145);
    drawEllipsePoly(sd.x0 + 1, sd.y0 + 1, sd.rx * 1.32, sd.ry * 1.35, sd.rot, 10, 0.3);

    // Glistening wet trail behind the sliding droplet
    brush.wash(PALETTE.steelGleam, round(130 * env));
    brush.beginShape(0.3);
    brush.vertex(sd.x0, sd.y0 - sd.ry * 0.35);
    brush.vertex(curX, curY - sd.ry * 0.5);
    brush.vertex(curX, curY + sd.ry * 0.5);
    brush.vertex(sd.x0, sd.y0 + sd.ry * 0.35);
    brush.endShape(true);

    // Redraw the droplet at its new position
    brush.wash(PALETTE.steelDeep, 150);
    drawEllipsePoly(curX + 2.5, curY + 3, sd.rx, sd.ry, sd.rot, 10, 0.3);

    brush.wash(PALETTE.steelGleam, 195);
    drawEllipsePoly(curX + 1, curY + 1.2, sd.rx * 0.85, sd.ry * 0.78, sd.rot, 10, 0.3);
    brush.noWash();

    brush.set("2H", PALETTE.steelDarkest, 0.75);
    let topPts = [];
    for (let a = 175; a <= 355; a += 30) {
      topPts.push(ellipsePt(curX, curY, sd.rx, sd.ry, sd.rot, a));
    }
    brush.spline(topPts, 0.5);

    brush.noStroke();
    brush.wash(PALETTE.pureWhite, 250);
    drawEllipsePoly(curX - sd.rx * 0.35, curY - sd.ry * 0.32, sd.rx * 0.28, sd.ry * 0.22, sd.rot, 6, 0.2);
    brush.noWash();
  }

  // 2. Expanding concentric ripples on the wet brushed steel where pop droplets land
  for (let rp of steelRipples) {
    if (frameCount < rp.startFrame) continue;
    let dtF = frameCount - rp.startFrame;
    let dur = 16;
    if (dtF > dur) continue;

    randomSeed(rp.seed);
    let u = dtF / dur;
    let ease = 1 - pow(1 - u, 2.0);
    let fade = 1 - u;
    let rx = lerp(4, rp.maxR, ease);
    let ry = rx * 0.66;

    // Outer specular ripple crest & inner dark meniscus trough
    let crestPts = [];
    let troughPts = [];
    for (let a = 0; a <= 360; a += 24) {
      crestPts.push(ellipsePt(rp.x, rp.y, rx, ry, -14, a));
      troughPts.push(ellipsePt(rp.x, rp.y, rx * 0.72, ry * 0.72, -14, a));
    }
    brush.set("2H", PALETTE.steelShadow, 0.65 * fade);
    brush.spline(troughPts, 0.5);

    brush.set("specular_nib", PALETTE.pureWhite, 0.85 * fade);
    brush.spline(crestPts, 0.5);

    // Newly landed beaded droplet at the center of the ripple
    let dr = 4.2 * (1 - 0.2 * u);
    brush.noStroke();
    brush.wash(PALETTE.steelDeep, 145);
    drawEllipsePoly(rp.x + 1.5, rp.y + 2, dr, dr * 0.7, -14, 6, 0.25);
    brush.wash(PALETTE.pureWhite, 240);
    drawEllipsePoly(rp.x - 1, rp.y - 1, dr * 0.45, dr * 0.35, -14, 5, 0.2);
    brush.noWash();
  }
}

// =============================================================================
// GEOMETRY GENERATION: 3D-Layered Soap Foam & Plateau Intersections
// =============================================================================
function buildFoamGeometry() {
  bubbles = [];
  microBubbles = [];
  septums = [];
  plateauNodes = [];

  // Define the main diagonal/curved ridge of piled soap foam in the sink
  // Sweeping from bottom-left (120, 1080) through center (560, 620) to lower-right (1050, 880)
  // and billowing up toward (380, 290)
  const heroCenters = [
    { x: 460, y: 580, r: 138, tier: 3, accent: "peacock" },
    { x: 645, y: 650, r: 124, tier: 3, accent: "green" },
    { x: 325, y: 725, r: 118, tier: 3, accent: "violet" },
    { x: 525, y: 795, r: 112, tier: 3, accent: "tangerine" },
    { x: 355, y: 455, r: 106, tier: 3, accent: "peacock" },
    { x: 750, y: 805, r: 108, tier: 3, accent: "peacock" },
    { x: 215, y: 575, r: 96, tier: 3, accent: "green" },
    { x: 605, y: 475, r: 94, tier: 3, accent: "tangerine" },
    { x: 425, y: 945, r: 104, tier: 3, accent: "violet" },
    { x: 220, y: 880, r: 98, tier: 3, accent: "peacock" },
    { x: 665, y: 950, r: 95, tier: 3, accent: "green" },
    { x: 875, y: 695, r: 88, tier: 3, accent: "violet" },
    { x: 255, y: 365, r: 84, tier: 3, accent: "peacock" },
    { x: 895, y: 885, r: 92, tier: 3, accent: "tangerine" },
    { x: 515, y: 355, r: 78, tier: 3, accent: "green" },
    { x: 125, y: 740, r: 86, tier: 3, accent: "violet" },
    { x: 745, y: 545, r: 76, tier: 3, accent: "peacock" },
    { x: 315, y: 1045, r: 82, tier: 3, accent: "tangerine" }
  ];

  for (let h of heroCenters) {
    bubbles.push({
      x: h.x + random(-8, 8),
      y: h.y + random(-8, 8),
      r: h.r * random(0.95, 1.05),
      tier: h.tier,
      accent: h.accent,
      rot: random(360),
      swirlDir: random() > 0.5 ? 1 : -1,
      id: bubbles.length
    });
  }

  // Pack medium bubbles (radii 34..68) into the foam mound
  const accents = ["peacock", "peacock", "green", "violet", "tangerine", "peacock"];
  let attempts = 0;
  while (bubbles.length < 66 && attempts < 2500) {
    attempts++;
    // Sample near existing bubbles or within the foam basin zone
    let anchor = random(bubbles);
    let ang = random(360);
    let rCand = map(pow(random(), 1.35), 0, 1, 32, 70);
    let distFactor = random(0.68, 0.96);
    let cx = anchor.x + cos(ang) * (anchor.r + rCand) * distFactor;
    let cy = anchor.y + sin(ang) * (anchor.r + rCand) * distFactor;

    // Keep out of the upper-right exposed steel drain zone
    let distToDrain = dist(cx, cy, 930, 240);
    if (distToDrain < 285 && random() < 0.92) continue;
    if (cx < 55 || cx > 1145 || cy < 130 || cy > 1150) continue;

    // Check packing constraints: allow realistic foam compression (0.64 to 0.95 of sum of radii)
    let valid = true;
    for (let b of bubbles) {
      let d = dist(cx, cy, b.x, b.y);
      let minD = (b.r + rCand) * 0.58;
      if (d < minD) {
        valid = false;
        break;
      }
    }
    if (valid) {
      bubbles.push({
        x: cx,
        y: cy,
        r: rCand,
        tier: 2,
        accent: random(accents),
        rot: random(360),
        swirlDir: random() > 0.5 ? 1 : -1,
        id: bubbles.length
      });
    }
  }

  // Pack smaller perimeter & crevice bubbles (radii 16..32)
  attempts = 0;
  while (bubbles.length < 105 && attempts < 2500) {
    attempts++;
    let anchor = random(bubbles);
    let ang = random(360);
    let rCand = random(16, 31);
    let distFactor = random(0.74, 1.02);
    let cx = anchor.x + cos(ang) * (anchor.r + rCand) * distFactor;
    let cy = anchor.y + sin(ang) * (anchor.r + rCand) * distFactor;

    if (dist(cx, cy, 930, 240) < 230 && random() < 0.85) continue;
    if (cx < 40 || cx > 1160 || cy < 95 || cy > 1165) continue;

    let valid = true;
    for (let b of bubbles) {
      let d = dist(cx, cy, b.x, b.y);
      if (d < (b.r + rCand) * 0.62) {
        valid = false;
        break;
      }
    }
    if (valid) {
      bubbles.push({
        x: cx,
        y: cy,
        r: rCand,
        tier: 1,
        accent: random(accents),
        rot: random(360),
        swirlDir: random() > 0.5 ? 1 : -1,
        id: bubbles.length
      });
    }
  }

  // Sort bubbles so smaller/deeper ones draw first and large hero domes crown the top,
  // with slight y-sorting for natural 3D overlap
  bubbles.sort((a, b) => (a.tier * 100 + a.r) - (b.tier * 100 + b.r));

  // Re-assign sorted indices
  for (let i = 0; i < bubbles.length; i++) bubbles[i].id = i;

  // Compute pairwise pressed bubble walls (Plateau septums)
  for (let i = 0; i < bubbles.length; i++) {
    for (let j = i + 1; j < bubbles.length; j++) {
      let b1 = bubbles[i];
      let b2 = bubbles[j];
      let d = dist(b1.x, b1.y, b2.x, b2.y);
      let rSum = b1.r + b2.r;

      if (d < rSum * 0.99 && d > abs(b1.r - b2.r) * 0.55) {
        let a = (b1.r * b1.r - b2.r * b2.r + d * d) / (2 * d);
        a = constrain(a, -b1.r * 0.92, b1.r * 0.92);
        let h = sqrt(max(4, b1.r * b1.r - a * a));

        let ux = (b2.x - b1.x) / d;
        let uy = (b2.y - b1.y) / d;
        let nx = -uy;
        let ny = ux;

        let mx = b1.x + a * ux;
        let my = b1.y + a * uy;

        let p1 = { x: mx + h * nx, y: my + h * ny };
        let p2 = { x: mx - h * nx, y: my - h * ny };

        // Young-Laplace pressure law: higher pressure inside smaller bubble bends wall toward larger bubble
        let bendDir = b1.r > b2.r ? -1 : 1;
        let ratioDiff = abs(b1.r - b2.r) / max(b1.r, b2.r);
        let bendAmt = h * (0.12 + 0.18 * ratioDiff) * bendDir;
        let mid = {
          x: mx + ux * bendAmt,
          y: my + uy * bendAmt
        };

        septums.push({
          p1,
          mid,
          p2,
          b1,
          b2,
          len: h * 2,
          nx: ux,
          ny: uy
        });

        plateauNodes.push({ x: p1.x, y: p1.y, r: constrain(h * 0.16, 3, 11) });
        plateauNodes.push({ x: p2.x, y: p2.y, r: constrain(h * 0.16, 3, 11) });
      }
    }
  }

  // Generate clusters of tiny micro-bubbles along Plateau borders and foam edges
  for (let node of plateauNodes) {
    let count = floor(random(2, 6));
    for (let k = 0; k < count; k++) {
      let ang = random(360);
      let rad = random(1.5, node.r * 1.4);
      microBubbles.push({
        x: node.x + cos(ang) * rad,
        y: node.y + sin(ang) * rad,
        r: random(2.2, 7.5)
      });
    }
  }

  // Add perimeter foam micro-bubbles where suds meet the wet steel
  for (let b of bubbles) {
    if (b.tier === 1 || random() < 0.35) {
      let n = floor(random(4, 10));
      let baseAng = random(360);
      for (let k = 0; k < n; k++) {
        let a = baseAng + random(-55, 55);
        let d = b.r + random(-4, 16);
        microBubbles.push({
          x: b.x + cos(a) * d,
          y: b.y + sin(a) * d,
          r: random(2.5, 9.5)
        });
      }
    }
  }
}

// =============================================================================
// 1. BRUSHED STAINLESS STEEL SINK BASIN
// =============================================================================
function drawBrushedSteelSink() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base metallic gradient washes across the sink
  // Deep cool corner in top-left and lower-right, luminous diagonal steel sheen
  const steelBands = [
    {
      col: PALETTE.steelMid,
      op: 65,
      pts: [[0, 0], [1200, 0], [1200, 1200], [0, 1200]]
    },
    {
      col: PALETTE.steelShadow,
      op: 85,
      pts: [[0, 0], [760, 0], [420, 480], [0, 680]]
    },
    {
      col: PALETTE.steelDeep,
      op: 95,
      pts: [[0, 0], [420, 0], [190, 320], [0, 420]]
    },
    {
      col: PALETTE.steelLight,
      op: 75,
      pts: [[480, 0], [1200, 0], [1200, 680], [640, 420]]
    },
    {
      col: PALETTE.steelGleam,
      op: 110,
      pts: [[580, 0], [920, 0], [1200, 360], [1200, 560], [720, 310]]
    },
    {
      col: PALETTE.steelShadow,
      op: 80,
      pts: [[780, 560], [1200, 480], [1200, 1200], [680, 1200]]
    },
    {
      col: PALETTE.steelDeep,
      op: 90,
      pts: [[940, 820], [1200, 740], [1200, 1200], [840, 1200]]
    }
  ];

  // Fast solid under-washes for rich metallic depth
  for (let b of steelBands) {
    brush.wash(b.col, b.op);
    drawSmoothPoly(b.pts, 0.25);
  }
  brush.noWash();

  // Wet watercolour steel blooms for soft out-of-focus metallic blur
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);

  const blurPatches = [
    { x: 180, y: 170, rx: 240, ry: 140, rot: -18, col: PALETTE.steelDeep, op: 55 },
    { x: 760, y: 120, rx: 290, ry: 130, rot: -14, col: PALETTE.steelGleam, op: 65 },
    { x: 1050, y: 520, rx: 250, ry: 160, rot: -15, col: PALETTE.steelMid, op: 50 },
    { x: 1060, y: 980, rx: 260, ry: 180, rot: -16, col: PALETTE.steelShadow, op: 60 },
    { x: 540, y: 210, rx: 220, ry: 110, rot: -15, col: PALETTE.steelBright, op: 55 }
  ];

  for (let p of blurPatches) {
    brush.fill(p.col, p.op);
    drawEllipsePoly(p.x, p.y, p.rx, p.ry, p.rot, 10, 0.4);
  }
  brush.noFill();

  // Fine Brushed Steel Grain using the custom "steel_grain" vector field
  brush.field("steel_grain");

  // Dark brushed grain lines
  brush.set("2H", PALETTE.steelShadow, 0.7);
  for (let i = 0; i < 220; i++) {
    let sx = random(-40, 1180);
    let sy = random(-20, 1180);
    // Concentrate where steel is visible or semi-visible
    if (sx < 750 && sy > 420 && sy < 980 && random() < 0.65) continue;
    brush.flowLine(sx, sy, random(90, 260), -14);
  }

  // Mid-tone satin grain lines
  brush.set("HB", PALETTE.steelLight, 0.65);
  for (let i = 0; i < 180; i++) {
    let sx = random(-40, 1180);
    let sy = random(-20, 1180);
    if (sx < 700 && sy > 450 && sy < 960 && random() < 0.65) continue;
    brush.flowLine(sx, sy, random(80, 220), -14);
  }

  // Specular brushed-steel highlight hairlines
  brush.set("razor_pencil", PALETTE.steelGleam, 0.8);
  for (let i = 0; i < 150; i++) {
    let sx = random(250, 1180);
    let sy = random(0, 750);
    brush.flowLine(sx, sy, random(70, 200), -14);
  }

  // Subtle curved sink basin bevel crease in upper-left
  brush.noField();
  brush.set("charcoal", PALETTE.steelDeep, 1.1);
  brush.spline([
    [0, 310, 0.6],
    [220, 185, 0.9],
    [485, 78, 0.8],
    [740, 0, 0.4]
  ], 0.5);

  brush.set("razor_pencil", PALETTE.pureWhite, 0.9);
  brush.spline([
    [0, 326, 0.4],
    [225, 200, 0.9],
    [495, 92, 0.8],
    [760, 10, 0.3]
  ], 0.5);
}

// =============================================================================
// 2. RECESSED STAINLESS STEEL SINK DRAIN / STRAINER
// =============================================================================
function drawSinkDrain(cx, cy, radius, aspect, tiltDeg) {
  brush.noField();
  brush.noStroke();

  // Outer stamped sink recess bezel
  brush.wash(PALETTE.steelShadow, 140);
  drawEllipsePoly(cx, cy, radius * 1.18, radius * 1.18 * aspect, tiltDeg, 24, 0.3);

  brush.wash(PALETTE.steelGleam, 165);
  drawEllipsePoly(cx + 5, cy + 4, radius * 1.12, radius * 1.12 * aspect, tiltDeg, 24, 0.3);

  // Strainer basket outer flange
  brush.wash(PALETTE.steelMid, 190);
  drawEllipsePoly(cx, cy, radius * 0.98, radius * 0.98 * aspect, tiltDeg, 24, 0.3);

  // Deep recessed well shadow (upper crescent inside strainer)
  brush.wash(PALETTE.steelDarkest, 210);
  drawEllipsePoly(cx, cy, radius * 0.80, radius * 0.80 * aspect, tiltDeg, 24, 0.3);

  brush.wash(PALETTE.steelLight, 185);
  drawEllipsePoly(cx + 6, cy + 10, radius * 0.76, radius * 0.74 * aspect, tiltDeg, 24, 0.3);

  brush.wash(PALETTE.steelMid, 165);
  drawEllipsePoly(cx + 3, cy + 6, radius * 0.68, radius * 0.66 * aspect, tiltDeg, 20, 0.3);

  // Radial perforated strainer slots
  let numSlots = 14;
  for (let i = 0; i < numSlots; i++) {
    let a = i * (360 / numSlots) + 12;
    let rSlot = radius * 0.48;
    // Local coordinates before tilt
    let lx = cos(a) * rSlot;
    let ly = sin(a) * rSlot * aspect;
    let sx = cx + lx * cos(tiltDeg) - ly * sin(tiltDeg);
    let sy = cy + lx * sin(tiltDeg) + ly * cos(tiltDeg);

    let slotRot = atan2(sin(a) * aspect, cos(a)) + tiltDeg;

    // Metallic rim glint under slot
    brush.wash(PALETTE.pureWhite, 190);
    drawEllipsePoly(sx + 1.5, sy + 2.2, 16, 6.5, slotRot, 8, 0.3);

    // Dark drain hole
    brush.wash(PALETTE.steelDarkest, 240);
    drawEllipsePoly(sx, sy, 15, 5.8, slotRot, 8, 0.3);
  }

  // Center strainer post / locking knob
  brush.wash(PALETTE.steelDarkest, 220);
  drawEllipsePoly(cx, cy + 2, radius * 0.22, radius * 0.22 * aspect, tiltDeg, 16, 0.3);

  brush.wash(PALETTE.steelBright, 220);
  drawEllipsePoly(cx - 2, cy - 1, radius * 0.18, radius * 0.18 * aspect, tiltDeg, 16, 0.3);

  // Center screw slot
  brush.wash(PALETTE.steelDarkest, 230);
  drawEllipsePoly(cx - 2, cy - 1, radius * 0.12, 3.2, tiltDeg - 25, 8, 0.2);

  brush.noWash();

  // Crisp graphite & white specular ellipses along the stamped metal rims
  let rimScales = [1.18, 1.12, 0.98, 0.80, 0.22];
  for (let s of rimScales) {
    let ptsTop = [];
    let ptsBot = [];
    for (let a = 160; a <= 350; a += 12) {
      ptsTop.push(ellipsePt(cx, cy, radius * s, radius * s * aspect, tiltDeg, a));
    }
    for (let a = -10; a <= 165; a += 12) {
      ptsBot.push(ellipsePt(cx, cy, radius * s, radius * s * aspect, tiltDeg, a));
    }
    brush.set("2H", PALETTE.steelDarkest, 0.95);
    brush.spline(ptsTop, 0.5);

    brush.set("specular_nib", PALETTE.pureWhite, 0.85);
    brush.spline(ptsBot, 0.5);
  }
}

// =============================================================================
// 3. FOAM CAST SHADOWS & IRIDESCENT CAUSTICS ON WET STEEL
// =============================================================================
function drawFoamShadowsAndCaustics() {
  brush.noStroke();

  // Deep cool contact shadow under the foam edge on the brushed steel
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.6, 0.35);

  brush.fill(PALETTE.steelDeep, 115);
  for (let b of bubbles) {
    if (b.tier <= 2) {
      drawEllipsePoly(b.x + 16, b.y + 18, b.r * 1.06, b.r * 0.96, 12, 10, 0.35);
    }
  }
  brush.noFill();

  // Subtle peacock-blue and emerald caustic light refracted onto the wet steel near perimeter bubbles
  brush.fillBleed(0.4, "out");
  brush.fill(PALETTE.peacockMid, 42);
  const causticSpots = [
    { x: 640, y: 345, r: 58 },
    { x: 825, y: 495, r: 64 },
    { x: 965, y: 690, r: 54 },
    { x: 185, y: 300, r: 52 },
    { x: 985, y: 895, r: 60 }
  ];
  for (let c of causticSpots) {
    drawEllipsePoly(c.x, c.y, c.r * 1.2, c.r * 0.8, -15, 9, 0.4);
  }
  brush.noFill();
}

// =============================================================================
// 4. DENSE MILKY UNDER-FOAM & WHIPPED SUDS BANKS
// =============================================================================
function drawMilkyUnderFoam() {
  brush.noStroke();

  // Soft milky base lather underneath the bubble clusters
  for (let b of bubbles) {
    brush.wash(PALETTE.milkShadow, 95);
    drawEllipsePoly(b.x + 4, b.y + 6, b.r * 1.02, b.r * 0.98, 0, 12, 0.3);
  }

  for (let b of bubbles) {
    brush.wash(PALETTE.milkBase, 145);
    drawEllipsePoly(b.x, b.y, b.r * 0.97, b.r * 0.95, 0, 12, 0.3);
  }

  // Bright whipped-cream froth banks in the crevices between bubbles
  for (let node of plateauNodes) {
    brush.wash(PALETTE.milkBright, 175);
    drawEllipsePoly(node.x, node.y, node.r * 2.2, node.r * 1.9, random(180), 8, 0.3);
  }
  brush.noWash();

  // Fine stippled froth texture across the milky lather
  brush.set("froth_stipple", PALETTE.pureWhite, 1.1);
  for (let i = 0; i < 95; i++) {
    let b = random(bubbles);
    let a = random(360);
    let d = b.r * random(0.65, 1.08);
    let sx = b.x + cos(a) * d;
    let sy = b.y + sin(a) * d;
    brush.line(sx, sy, sx + random(-18, 18), sy + random(-18, 18));
  }
}

// =============================================================================
// 5. WET-IN-WET WATERCOLOUR OPAL IRIDESCENCE (BATCHED BY COLOUR)
// =============================================================================
function drawBatchedOpalWashes() {
  brush.noStroke();

  // Collect watercolor crescent/pool polygons into color batches for authentic bleed & high performance
  let batches = {
    darkCore: [],
    peacockDeep: [],
    peacockBright: [],
    electricGreen: [],
    violet: [],
    tangerine: [],
    milkyRim: []
  };

  for (let b of bubbles) {
    if (b.r < 20) continue;

    // 1. Dark steel reflection core inside the transparent upper-center of the bubble
    batches.darkCore.push(
      makeCrescentPoly(b.x, b.y, b.r * 0.72, b.r * 0.32, -65 + b.rot * 0.08, 135)
    );

    // 2. Primary Peacock Blue opalescent pool (every bubble has some peacock blue to anchor the accent)
    let pAng = 35 + (b.id * 37) % 160;
    batches.peacockBright.push(
      makeCrescentPoly(b.x, b.y, b.r * 0.82, b.r * 0.44, pAng, 145)
    );

    if (b.r > 42) {
      batches.peacockDeep.push(
        makeCrescentPoly(b.x, b.y, b.r * 0.64, b.r * 0.28, pAng - 35, 120)
      );
    }

    // 3. Secondary opal play-of-colour flashes (electric green, violet, tangerine)
    if (b.accent === "peacock" || b.accent === "green" || b.r > 65) {
      batches.electricGreen.push(
        makeCrescentPoly(b.x, b.y, b.r * 0.78, b.r * 0.50, pAng + 65 * b.swirlDir, 115)
      );
    }

    if (b.accent === "violet" || b.r > 58) {
      batches.violet.push(
        makeCrescentPoly(b.x, b.y, b.r * 0.74, b.r * 0.42, pAng + 135 * b.swirlDir, 110)
      );
    }

    if (b.accent === "tangerine" || b.r > 72) {
      batches.tangerine.push(
        makeCrescentPoly(b.x, b.y, b.r * 0.68, b.r * 0.38, pAng - 95 * b.swirlDir, 95)
      );
    }

    // 4. Gravity-drained milky white meniscus pool along the bottom of the sphere
    batches.milkyRim.push(
      makeCrescentPoly(b.x, b.y, b.r * 0.92, b.r * 0.68, 78, 125)
    );
  }

  // Render each color batch with wet-in-wet bleed
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.68, 0.38);

  // Batch 1: Cool dark sink reflection cores
  brush.fill(PALETTE.steelShadow, 88);
  for (let poly of batches.darkCore) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 2: Deep Peacock Blue pools
  brush.fillBleed(0.32, "out");
  brush.fill(PALETTE.peacockDeep, 95);
  for (let poly of batches.peacockDeep) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 3: Luminous Peacock Blue blooms
  brush.fill(PALETTE.peacockBright, 105);
  for (let poly of batches.peacockBright) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 4: Electric Green interference bands
  brush.fill(PALETTE.electricGreen, 98);
  for (let poly of batches.electricGreen) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 5: Violet / Amethyst blooms
  brush.fill(PALETTE.violetBright, 90);
  for (let poly of batches.violet) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 6: Tangerine / Amber flecks
  brush.fill(PALETTE.tangerine, 96);
  for (let poly of batches.tangerine) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Batch 7: Milky opalescent lower meniscus veils
  brush.fillBleed(0.22, "in");
  brush.fill(PALETTE.pureWhite, 115);
  for (let poly of batches.milkyRim) drawSmoothPoly(poly, 0.45);
  brush.noFill();

  // Add swirling thin-film interference ribbons inside hero bubbles using "film_glaze" marker
  for (let b of bubbles) {
    if (b.r < 48) continue;
    let ribbons = floor(map(b.r, 48, 140, 3, 7));
    for (let k = 0; k < ribbons; k++) {
      let startA = b.rot + k * 58;
      let spanA = random(65, 135);
      let rad = b.r * random(0.38, 0.84);
      let colChoice = [
        PALETTE.peacockBright,
        PALETTE.electricGreen,
        PALETTE.violetBright,
        PALETTE.tangerine,
        PALETTE.peacockPale,
        PALETTE.chartreuse
      ][(b.id + k) % 6];

      let pts = [];
      for (let t = 0; t <= 1; t += 0.2) {
        let a = startA + t * spanA;
        let rNow = rad * (1 - 0.12 * sin(t * 180));
        pts.push([
          b.x + cos(a) * rNow,
          b.y + sin(a) * rNow,
          sin(t * 180) * 1.2 + 0.3
        ]);
      }
      brush.set("film_glaze", colChoice, map(b.r, 48, 140, 0.7, 1.45));
      brush.spline(pts, 0.6);
    }
  }
}

// =============================================================================
// 6. INTERNAL PRESSED BUBBLE WALLS (SEPTUMS) & PLATEAU BORDER MENISCI
// =============================================================================
function drawInternalFoamWalls() {
  brush.noField();

  // First draw ghosted internal polyhedral walls seen through the translucent domes
  for (let s of septums) {
    // Soft milky liquid film along the shared wall
    brush.set("cpencil", PALETTE.milkBright, 1.2);
    brush.spline([
      [s.p1.x + s.nx * 1.8, s.p1.y + s.ny * 1.8, 0.5],
      [s.mid.x + s.nx * 1.8, s.mid.y + s.ny * 1.8, 1.1],
      [s.p2.x + s.nx * 1.8, s.p2.y + s.ny * 1.8, 0.5]
    ], 0.5);

    // Iridescent refraction hairline along the pressed septum
    let refractCol = (s.b1.id + s.b2.id) % 3 === 0
      ? PALETTE.peacockBright
      : ((s.b1.id + s.b2.id) % 3 === 1 ? PALETTE.electricGreen : PALETTE.magentaFlash);
    brush.set("razor_pencil", refractCol, 0.85);
    brush.spline([
      [s.p1.x - s.nx * 1.4, s.p1.y - s.ny * 1.4, 0.4],
      [s.mid.x - s.nx * 1.4, s.mid.y - s.ny * 1.4, 1.0],
      [s.p2.x - s.nx * 1.4, s.p2.y - s.ny * 1.4, 0.4]
    ], 0.5);

    // Crisp graphite pencil arc marking the pressed bubble wall
    brush.set("2H", PALETTE.graphiteDark, map(s.len, 15, 160, 0.65, 1.25, true));
    brush.spline([
      [s.p1.x, s.p1.y, 0.9],
      [s.mid.x, s.mid.y, 1.25],
      [s.p2.x, s.p2.y, 0.9]
    ], 0.5);

    // Bright specular liquid meniscus thread right on the ridge
    brush.set("specular_nib", PALETTE.pureWhite, 0.75);
    brush.spline([
      [s.p1.x, s.p1.y, 0.8],
      [s.mid.x + s.nx * 0.9, s.mid.y + s.ny * 0.9, 1.1],
      [s.p2.x, s.p2.y, 0.8]
    ], 0.5);
  }

  // Draw triangular Plateau border nodes where three soap films meet at 120 degrees
  brush.noStroke();
  for (let node of plateauNodes) {
    brush.wash(PALETTE.pureWhite, 225);
    let r = node.r;
    let a0 = (node.x * 13 + node.y * 7) % 360;
    let triPts = [];
    for (let k = 0; k < 3; k++) {
      let a = a0 + k * 120;
      triPts.push([node.x + cos(a) * r, node.y + sin(a) * r]);
      let aMid = a + 60;
      triPts.push([node.x + cos(aMid) * (r * 0.36), node.y + sin(aMid) * (r * 0.36)]);
    }
    drawSmoothPoly(triPts, 0.35);
  }
  brush.noWash();

  // Crisp graphite accents on Plateau border triangles
  for (let i = 0; i < plateauNodes.length; i += 2) {
    let node = plateauNodes[i];
    let r = node.r * 0.95;
    let a0 = (node.x * 13 + node.y * 7) % 360;
    brush.set("HB", PALETTE.graphiteMid, 0.65);
    for (let k = 0; k < 3; k++) {
      let a1 = a0 + k * 120;
      let a2 = a0 + ((k + 1) % 3) * 120;
      let aMid = a1 + 60;
      brush.spline([
        [node.x + cos(a1) * r, node.y + sin(a1) * r, 0.6],
        [node.x + cos(aMid) * (r * 0.32), node.y + sin(aMid) * (r * 0.32), 1.0],
        [node.x + cos(a2) * r, node.y + sin(a2) * r, 0.6]
      ], 0.5);
    }
  }
}

// =============================================================================
// 7. OUTER BUBBLE DOMES, COLORED PENCIL IRIDESCENT RIMS & MICRO-FROTH
// =============================================================================
function drawBubbleDomesAndRims() {
  for (let b of bubbles) {
    // 1. Colored pencil opalescent rim arcs just inside the bubble contour
    let rimCols = [
      PALETTE.peacockBright,
      PALETTE.electricGreen,
      PALETTE.tangerine,
      PALETTE.violetBright
    ];

    for (let cIdx = 0; cIdx < 3; cIdx++) {
      let startA = (b.rot + cIdx * 115) % 360;
      let endA = startA + random(55, 95);
      let col = rimCols[(b.id + cIdx) % rimCols.length];
      brush.set("cpencil", col, map(b.r, 16, 140, 0.55, 1.15));
      brush.arc(b.x, b.y, b.r * 0.96, startA, endA);
    }

    // 2. Crisp graphite pencil arcs around the outer sphere wall
    // Check which angular segments of bubble `b` are on the outer free dome vs deeply buried
    let numSegs = 24;
    let segStep = 360 / numSegs;
    for (let s = 0; s < numSegs; s++) {
      let a1 = s * segStep;
      let a2 = a1 + segStep + 2;
      let aMid = (a1 + a2) * 0.5;
      let px = b.x + cos(aMid) * b.r;
      let py = b.y + sin(aMid) * b.r;

      // Test if covered by a larger foreground bubble
      let buriedCount = 0;
      for (let other of bubbles) {
        if (other.id === b.id) continue;
        let d = dist(px, py, other.x, other.y);
        if (d < other.r * 0.94) {
          if (other.id > b.id) buriedCount += 2;
          else buriedCount += 1;
        }
      }

      if (buriedCount === 0) {
        // Unobstructed outer dome wall: crisp dark pencil arc + milky edge
        brush.set("2H", PALETTE.graphiteDark, map(b.r, 16, 140, 0.75, 1.35));
        brush.arc(b.x, b.y, b.r, a1, a2);

        if (sin(aMid - 45) > 0.15) {
          brush.set("specular_nib", PALETTE.pureWhite, 0.75);
          brush.arc(b.x, b.y, b.r * 0.985, a1, a2);
        }
      } else if (buriedCount === 1) {
        // Partially seen through an adjacent transparent membrane: delicate ghosted pencil arc
        brush.set("2H", PALETTE.graphiteLight, 0.55);
        brush.arc(b.x, b.y, b.r, a1, a2);
      }
    }

    // 3. Subtle spherical contour hatching along the lower-right shadow crescent of larger bubbles
    if (b.r > 52) {
      brush.set("razor_pencil", PALETTE.peacockDeep, 0.6);
      for (let k = 0; k < 5; k++) {
        let rArc = b.r * map(k, 0, 4, 0.84, 0.95);
        brush.arc(b.x, b.y, rArc, 15 + k * 4, 110 - k * 4);
      }
    }
  }

  // Render the hundreds of tiny micro-bubbles nestled in the Plateau crevices
  for (let mb of microBubbles) {
    brush.noStroke();
    brush.wash(PALETTE.milkBright, 200);
    drawEllipsePoly(mb.x, mb.y, mb.r, mb.r, 0, 7, 0.25);
    brush.noWash();

    brush.set("2H", PALETTE.graphiteMid, 0.5);
    brush.circle(mb.x, mb.y, mb.r, 0.12);

    // Tiny white pinprick glint on each micro-bubble
    brush.noStroke();
    brush.wash(PALETTE.pureWhite, 245);
    drawEllipsePoly(mb.x - mb.r * 0.3, mb.y - mb.r * 0.3, mb.r * 0.36, mb.r * 0.36, 0, 5, 0.2);
    brush.noWash();
  }
}

// =============================================================================
// 8. HYPERREALISTIC WARPED WINDOW REFLECTIONS & SPECULAR HIGHLIGHTS
// =============================================================================
function drawSpecularReflections() {
  for (let b of bubbles) {
    if (b.r < 18) continue;

    // A) SECONDARY INVERTED BACK-SURFACE REFLECTION (Lower-right interior of the hollow soap sphere)
    if (b.r > 32) {
      let secPanes = [
        { a1: 28, a2: 52, r1: 0.62, r2: 0.74 },
        { a1: 56, a2: 80, r1: 0.62, r2: 0.74 },
        { a1: 28, a2: 52, r1: 0.77, r2: 0.86 },
        { a1: 56, a2: 80, r1: 0.77, r2: 0.86 }
      ];
      brush.noStroke();
      for (let idx = 0; idx < secPanes.length; idx++) {
        let p = secPanes[idx];
        let tint = idx % 2 === 0 ? PALETTE.peacockPale : PALETTE.chartreuse;
        brush.wash(tint, 115);
        let quad = makeSphericalWindowPatch(b.x, b.y, b.r, p.a1, p.a2, p.r1, p.r2);
        drawSmoothPoly(quad, 0.25);
      }
      brush.noWash();
    }

    // B) PRIMARY FRONT-SURFACE WARPED KITCHEN WINDOW REFLECTION (Upper-left dome)
    if (b.r > 38) {
      // Soft glowing bloom behind the window catchlight
      brush.noStroke();
      brush.wash(PALETTE.milkBright, 110);
      let halo = makeSphericalWindowPatch(b.x, b.y, b.r, 198, 258, 0.44, 0.84);
      drawSmoothPoly(halo, 0.35);

      // 4 warped window panes separated by a thin curved mullion cross
      let priPanes = [
        { a1: 202, a2: 227, r1: 0.48, r2: 0.64 },
        { a1: 232, a2: 256, r1: 0.48, r2: 0.64 },
        { a1: 202, a2: 227, r1: 0.68, r2: 0.82 },
        { a1: 232, a2: 256, r1: 0.68, r2: 0.82 }
      ];

      for (let idx = 0; idx < priPanes.length; idx++) {
        let p = priPanes[idx];
        let quad = makeSphericalWindowPatch(b.x, b.y, b.r, p.a1, p.a2, p.r1, p.r2);

        // Subtle chromatic aberration fringe on window reflection edge
        if (b.r > 65) {
          let fringeCol = idx < 2 ? PALETTE.tangerine : PALETTE.peacockBright;
          brush.wash(fringeCol, 95);
          let fringeQuad = makeSphericalWindowPatch(
            b.x,
            b.y,
            b.r,
            p.a1 - 1.5,
            p.a2 + 1.5,
            p.r1 - 0.015,
            p.r2 + 0.015
          );
          drawSmoothPoly(fringeQuad, 0.2);
        }

        // Brilliant pure white window reflection
        brush.wash(PALETTE.pureWhite, 240);
        drawSmoothPoly(quad, 0.2);
      }
      brush.noWash();

      // Crisp specular white nib outline on the brightest upper-left window pane
      brush.set("specular_nib", PALETTE.pureWhite, 0.95);
      brush.arc(b.x, b.y, b.r * 0.81, 202, 255);
    } else {
      // Smaller bubble: single curved crescent window glint
      brush.noStroke();
      brush.wash(PALETTE.pureWhite, 235);
      let glint = makeSphericalWindowPatch(b.x, b.y, b.r, 208, 250, 0.55, 0.78);
      drawSmoothPoly(glint, 0.25);
      brush.noWash();
    }

    // C) Tiny secondary overhead kitchen ceiling light pinpoint near top pole
    brush.noStroke();
    brush.wash(PALETTE.pureWhite, 250);
    let px = b.x + cos(268) * (b.r * 0.56);
    let py = b.y + sin(268) * (b.r * 0.56);
    drawEllipsePoly(px, py, max(2.2, b.r * 0.055), max(1.4, b.r * 0.032), -18, 6, 0.2);
    brush.noWash();
  }
}

// =============================================================================
// 9. STRAY WATER DROPLETS ON STEEL & FINAL CRISP GRAPHITE ACCENTS
// =============================================================================
function drawSurfaceDetails() {
  // Beaded water and soap droplets scattered on the exposed brushed steel sink
  const droplets = [
    { x: 645, y: 165, rx: 14, ry: 9, rot: -15 },
    { x: 705, y: 210, rx: 8, ry: 6, rot: -12 },
    { x: 525, y: 135, rx: 11, ry: 8, rot: -18 },
    { x: 1055, y: 585, rx: 16, ry: 11, rot: -14 },
    { x: 1095, y: 635, rx: 9, ry: 7, rot: -10 },
    { x: 1020, y: 745, rx: 12, ry: 8, rot: -16 },
    { x: 115, y: 235, rx: 15, ry: 10, rot: -14 },
    { x: 165, y: 265, rx: 7, ry: 5, rot: -14 },
    { x: 845, y: 425, rx: 10, ry: 7, rot: -15 },
    { x: 1075, y: 1025, rx: 14, ry: 9, rot: -12 }
  ];

  for (let d of droplets) {
    // Contact shadow under droplet
    brush.noStroke();
    brush.wash(PALETTE.steelDeep, 150);
    drawEllipsePoly(d.x + 2.5, d.y + 3, d.rx, d.ry, d.rot, 10, 0.3);

    // Refracted bright steel interior on lower half of droplet
    brush.wash(PALETTE.steelGleam, 195);
    drawEllipsePoly(d.x + 1, d.y + 1.2, d.rx * 0.85, d.ry * 0.78, d.rot, 10, 0.3);

    // Crisp dark upper meniscus
    brush.noWash();
    brush.set("2H", PALETTE.steelDarkest, 0.75);
    let topPts = [];
    for (let a = 175; a <= 355; a += 30) {
      topPts.push(ellipsePt(d.x, d.y, d.rx, d.ry, d.rot, a));
    }
    brush.spline(topPts, 0.5);

    // Pinpoint specular highlight on upper-left of droplet
    brush.noStroke();
    brush.wash(PALETTE.pureWhite, 250);
    drawEllipsePoly(d.x - d.rx * 0.35, d.y - d.ry * 0.32, d.rx * 0.28, d.ry * 0.22, d.rot, 6, 0.2);
    brush.noWash();
  }

  // Final electric flecks & iridescent sparkles inside the hero bubbles
  const sparkleCols = [
    PALETTE.peacockPale,
    PALETTE.chartreuse,
    PALETTE.amberGlow,
    PALETTE.magentaFlash,
    PALETTE.pureWhite
  ];

  for (let b of bubbles) {
    if (b.r < 55) continue;
    for (let k = 0; k < 6; k++) {
      let a = b.rot + k * 60 + random(-15, 15);
      let rad = b.r * random(0.45, 0.88);
      let sx = b.x + cos(a) * rad;
      let sy = b.y + sin(a) * rad;
      let sCol = sparkleCols[(b.id + k) % sparkleCols.length];

      brush.noStroke();
      brush.wash(sCol, 220);
      drawEllipsePoly(sx, sy, random(2.5, 5.5), random(1.5, 3.2), a + 90, 6, 0.25);
      brush.noWash();
    }
  }
}

// =============================================================================
// HELPER FUNCTIONS FOR ORGANIC & SPHERICAL SHAPES
// =============================================================================
function drawSmoothPoly(pts, curvature = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function ellipsePt(cx, cy, rx, ry, rotDeg, angDeg) {
  let lx = cos(angDeg) * rx;
  let ly = sin(angDeg) * ry;
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  return [cx + lx * c - ly * s, cy + lx * s + ly * c];
}

function drawEllipsePoly(cx, cy, rx, ry, rotDeg = 0, steps = 12, curvature = 0.35) {
  let pts = [];
  let stepA = 360 / steps;
  for (let i = 0; i < steps; i++) {
    pts.push(ellipsePt(cx, cy, rx, ry, rotDeg, i * stepA));
  }
  drawSmoothPoly(pts, curvature);
}

function makeCrescentPoly(cx, cy, rOuter, rInner, centerAng, spanAng) {
  let pts = [];
  let halfSpan = spanAng * 0.5;
  let aStart = centerAng - halfSpan;
  let aEnd = centerAng + halfSpan;
  let steps = 6;

  // Outer arc
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(aStart, aEnd, t);
    pts.push([cx + cos(a) * rOuter, cy + sin(a) * rOuter]);
  }

  // Inner arc (slightly offset center for natural crescent taper)
  let offX = cx + cos(centerAng) * (rOuter - rInner) * 0.35;
  let offY = cy + sin(centerAng) * (rOuter - rInner) * 0.35;
  for (let i = steps - 1; i >= 1; i--) {
    let t = i / steps;
    let a = lerp(aStart, aEnd, t);
    pts.push([offX + cos(a) * rInner, offY + sin(a) * rInner]);
  }

  return pts;
}

function makeSphericalWindowPatch(cx, cy, R, a1, a2, rf1, rf2) {
  let pts = [];
  let steps = 4;
  for (let i = 0; i <= steps; i++) {
    let a = lerp(a1, a2, i / steps);
    pts.push([cx + cos(a) * R * rf2, cy + sin(a) * R * rf2]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(a1, a2, i / steps);
    pts.push([cx + cos(a) * R * rf1, cy + sin(a) * R * rf1]);
  }
  return pts;
}

03-rooster:
// MOTION: The rooster cocks its head upward, swings its scarlet wattles, ripples its Petrykivka neck hackles in a bold wave, and blinks its amber eye fast
window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;

const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

let stillImg = null;
let cleanBackdropImg = null;
let headCutoutImg = null;
let wattleCutoutImg = null;
let layersPrepared = false;

let recordedNeckCommas = [];
let recordedJewelCommas = [];
let isRecordingStill = false;

// Anatomical pivots in 1200x1200 canvas space
const HPX = 575;
const HPY = 435;
const WPX = 700;
const WPY = 498;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42891);
  noiseSeed(10733);

  // Custom Petrykivka comma-stroke brushes (registered after scaleBrushes(3) for exact pixel control)
  // 1. Plump gouache body brush: swells rapidly into a loaded fat drop, then tapers to a hair-fine point
  brush.add("comma_body", {
    type: "custom",
    weight: 10.5,
    scatter: 0.02,
    opacity: 215,
    spacing: 0.09,
    noise: 0.14,
    rotate: "natural",
    markerTip: false,
    tip: (_m) => {
      _m.ellipse(0, 0, 2.5, 2.0);
    },
    pressure: (t) => {
      if (t < 0.13) {
        let u = t / 0.13;
        return 0.42 + 1.32 * Math.sin(u * Math.PI * 0.5);
      }
      let u = (t - 0.13) / 0.87;
      return 1.74 * Math.pow(1 - u, 2.2) + 0.015;
    }
  });

  // 2. Kolinsky/cat-hair bristle core brush for Petrykivka transitional ("perekhidnyj") brush tracks
  brush.add("comma_bristle", {
    type: "default",
    weight: 8.2,
    scatter: 0.07,
    sharpness: 0.74,
    grain: 15,
    opacity: 175,
    spacing: 0.12,
    noise: 0.22,
    pressure: (t) => {
      if (t < 0.13) {
        let u = t / 0.13;
        return 0.35 + 1.25 * Math.sin(u * Math.PI * 0.5);
      }
      let u = (t - 0.13) / 0.87;
      return 1.60 * Math.pow(1 - u, 2.15) + 0.012;
    }
  });

  // 3. Hair-fine script liner for the razor-sharp filament tail and micro-details
  brush.add("comma_filament", {
    type: "default",
    weight: 2.3,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 7,
    opacity: 220,
    spacing: 0.08,
    noise: 0.12,
    pressure: (t) => 1.15 * Math.pow(1 - t, 1.85) + 0.01
  });

  // 4. Organic vascular brush for veins in the waxy comb and wattles
  brush.add("vein_brush", {
    type: "default",
    weight: 2.2,
    scatter: 0.04,
    sharpness: 0.82,
    grain: 9,
    opacity: 165,
    spacing: 0.1,
    noise: 0.38,
    pressure: (t) => 1.05 * Math.pow(1 - t, 1.35) + 0.06
  });

  // 5. Soft waxy glaze brush for sculptural flesh and horn modeling
  brush.add("waxy_glaze", {
    type: "custom",
    weight: 16,
    scatter: 0.16,
    opacity: 42,
    spacing: 0.18,
    noise: 0.2,
    rotate: "random",
    markerTip: false,
    tip: (_m) => {
      _m.ellipse(0, 0, 3.0, 2.1);
    },
    pressure: [0.3, 1.25, 0.25]
  });

  background("#04060a");
}

// Helper: Draw a filled/washed closed shape from an array of [x, y] points
function drawClosedShape(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Helper: Interpolate along a 4-point control array
function evalQuadPath(pts, t) {
  let n = pts.length - 1;
  let scaled = t * n;
  let idx = Math.min(Math.floor(scaled), n - 1);
  let f = scaled - idx;
  let p0 = pts[idx];
  let p1 = pts[idx + 1];
  return [
    p0[0] + (p1[0] - p0[0]) * f,
    p0[1] + (p1[1] - p0[1]) * f
  ];
}

// Helper: Render a single loaded Petrykivka comma stroke with fat drop, transitional belly, and hair-fine tail
function drawPetrykivkaComma(pts, colBase, colBelly, colTail, wScale = 1.0, colDropBead = null) {
  // 1. Dark iridescent cushion shadow slightly offset to give photographic depth to the accumulation
  let shadowPts = pts.map((p, i) => [p[0] + 1.8, p[1] + 2.4 * (1 - i / pts.length)]);
  brush.set("comma_body", "#040c10", wScale * 0.92);
  brush.spline(shadowPts, 0.55);

  // 2. Main loaded comma stroke body (fat drop tapering to tail)
  brush.set("comma_body", colBase, wScale);
  brush.spline(pts, 0.55);

  // 3. Transitional bristle pass ("perekhidnyj mazok") shifting color through the belly
  let bellyPts = [
    evalQuadPath(pts, 0.04),
    evalQuadPath(pts, 0.28),
    evalQuadPath(pts, 0.58),
    evalQuadPath(pts, 0.88)
  ];
  brush.set("comma_bristle", colBelly, wScale * 0.80);
  brush.spline(bellyPts, 0.55);

  // 4. Optional wet pigment bead inside the fat drop head
  if (colDropBead) {
    let dropPts = [
      evalQuadPath(pts, 0.02),
      evalQuadPath(pts, 0.11),
      evalQuadPath(pts, 0.24),
      evalQuadPath(pts, 0.40)
    ];
    brush.set("comma_body", colDropBead, wScale * 0.52);
    brush.spline(dropPts, 0.5);
  }

  // 5. Hair-fine whip tail extending from the mid-belly out to a razor-sharp tip
  let last = pts[pts.length - 1];
  let prev = pts[pts.length - 2];
  let dx = last[0] - prev[0];
  let dy = last[1] - prev[1];
  let tailPts = [
    evalQuadPath(pts, 0.16),
    evalQuadPath(pts, 0.48),
    evalQuadPath(pts, 0.82),
    [last[0] + dx * 0.22, last[1] + dy * 0.22]
  ];
  brush.set("comma_filament", colTail, wScale * 0.68);
  brush.spline(tailPts, 0.55);
}

// Helper: Generate control points for a curved comma stroke starting at (x, y)
function buildCommaPath(x, y, angleRad, length, bendAmount) {
  let pts = [];
  let steps = 4;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAngle = angleRad + bendAmount * Math.pow(t, 1.25);
    let dist = length * t;
    let cx = x;
    let cy = y;
    let sub = 8;
    let dt = t / sub;
    for (let s = 1; s <= sub; s++) {
      let st = (s - 0.5) * dt;
      let a = angleRad + bendAmount * Math.pow(st, 1.25);
      cx += Math.cos(a) * (length * dt);
      cy += Math.sin(a) * (length * dt);
    }
    pts.push([cx, cy]);
  }
  return pts;
}

// Helper: Recursive vascular vein generator for the waxy comb and wattles
function drawVeinTree(x, y, angleRad, len, weight, depth, isBrightZone) {
  if (depth <= 0 || len < 10) return;

  let pts = [[x, y]];
  let cx = x;
  let cy = y;
  let curA = angleRad;
  let segs = 4;
  let stepLen = len / segs;

  for (let i = 1; i <= segs; i++) {
    curA += random(-0.22, 0.22);
    cx += Math.cos(curA) * stepLen;
    cy += Math.sin(curA) * stepLen;
    pts.push([cx, cy]);
  }

  let hlPts = pts.map(p => [p[0] - 1.6, p[1] - 1.2]);
  brush.set("vein_brush", isBrightZone ? "#ff8e85" : "#b83b5e", weight * 0.72);
  brush.spline(hlPts, 0.5);

  brush.set("vein_brush", isBrightZone ? "#c4141c" : "#6e081f", weight * 1.15);
  brush.spline(pts, 0.5);

  brush.set("vein_brush", isBrightZone ? "#5c061a" : "#330210", weight * 0.68);
  brush.spline(pts, 0.5);

  let branchCount = depth >= 3 ? 2 : (random() < 0.75 ? 2 : 1);
  for (let b = 0; b < branchCount; b++) {
    let pickIdx = b === 0 ? 4 : Math.floor(random(2, 4));
    let bp = pts[pickIdx];
    let spread = (b === 0 ? 1 : -1) * random(0.24, 0.52);
    drawVeinTree(
      bp[0],
      bp[1],
      curA + spread,
      len * random(0.58, 0.76),
      weight * 0.66,
      depth - 1,
      isBrightZone
    );
  }
}

// Exact still painting function (100% unchanged random/noise stream and mark order)
function paintStill() {
  recordedNeckCommas = [];
  recordedJewelCommas = [];
  isRecordingStill = true;

  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. LACQUERED BLACK GROUND WITH COOL ABYSSAL DEPTH
  // =========================================================================
  brush.noStroke();
  brush.wash("#04060a", 255);
  brush.rect(0, 0, 1200, 1200, "corner");
