  brush.fill("#08101c", 55);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.25, 0.08);
  brush.circle(560, 520, 460, 0.15);
  brush.fill("#060c16", 45);
  brush.circle(480, 740, 520, 0.15);
  brush.noFill();

  // Fine vertical lacquer sheen whispers in the dark negative space
  for (let i = 0; i < 45; i++) {
    let lx = random(40, 1160);
    let ly = random(40, 1100);
    brush.set("2H", "#0b1320", random(0.3, 0.7));
    brush.line(lx, ly, lx + random(-8, 8), ly + random(60, 180));
  }

  // =========================================================================
  // 2. ANATOMICAL UNDERPAINTING OF THE NECK, HEAD & FAR WATTLE
  // =========================================================================
  const neckUnderSilhouette = [
    [590, 355], [465, 352], [355, 405], [240, 520],
    [130, 690], [52, 910], [28, 1195], [945, 1195],
    [905, 1005], [840, 845], [765, 685], [720, 505], [650, 410]
  ];
  brush.noStroke();
  brush.wash("#051214", 255);
  drawClosedShape(neckUnderSilhouette, 0.3);
  brush.noWash();

  // Deep sap-green & Prussian teal-black tonal bed for the hackles
  brush.noStroke();
  brush.fill("#0b261e", 150);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.4, 0.15);
  drawClosedShape([
    [540, 365], [380, 420], [210, 610], [80, 920],
    [70, 1190], [890, 1190], [810, 860], [670, 530]
  ], 0.35);

  // Warm burnt-umber & deep vermilion glow along the upper dorsal arch of the neck
  brush.fill("#361207", 140);
  drawClosedShape([
    [560, 355], [440, 365], [310, 470], [180, 680],
    [100, 950], [360, 960], [500, 670], [610, 450]
  ], 0.35);
  brush.noFill();

  // =========================================================================
  // 3. PETRYKIVKA NECK HACKLES — LAYERED VERMILION, SAFFRON & SAP GREEN
  // =========================================================================
  function getNeckBounds(y) {
    let t = constrain((y - 345) / (1190 - 345), 0, 1);
    let xLeft = 468 - 435 * Math.pow(t, 0.82) + 18 * Math.sin(t * Math.PI);
    let xRight = 625 + 315 * Math.pow(t, 1.15);
    return { xLeft, xRight, t };
  }

  // Pass 3A: Deep Iridescent Plume Fans ("Hrebinchyk" / Onion-Frond Clusters) in Lower & Mid Neck
  const fanRows = [1155, 1075, 995, 915, 835, 755, 675, 595];
  for (let r = 0; r < fanRows.length; r++) {
    let ry = fanRows[r];
    let { xLeft, xRight, t } = getNeckBounds(ry);
    let span = xRight - xLeft;
    let fanCount = Math.floor(map(r, 0, fanRows.length - 1, 6, 4));

    for (let f = 0; f < fanCount; f++) {
      let u = (f + 0.5 + (r % 2) * 0.35) / (fanCount + 0.4);
      if (u > 0.96) continue;
      let cx = xLeft + span * u + random(-14, 14);
      let cy = ry + random(-12, 12);

      let baseAxis = map(u, 0, 1, 2.08, 1.38) + random(-0.08, 0.08);
      let plumeLen = map(t, 0.3, 1.0, 105, 165) * random(0.92, 1.08);

      let inWattleShadow = (cx > 540 && cy < 940);
      let lightFactor = constrain(1.0 - u * 0.95 - (inWattleShadow ? 0.35 : 0), 0.05, 1.0);

      for (let k = -2; k <= 2; k++) {
        let side = k === 0 ? 1 : Math.sign(k);
        let offsetAngle = k * 0.21;
        let sx = cx + Math.cos(baseAxis - Math.PI * 0.5) * (k * 13);
        let sy = cy + Math.sin(baseAxis - Math.PI * 0.5) * (k * 13);
        let strokeLen = plumeLen * (1.0 - Math.abs(k) * 0.11);
        let bend = -side * (0.42 + Math.abs(k) * 0.08);

        let pts = buildCommaPath(sx, sy, baseAxis + offsetAngle, strokeLen, bend);

        let cBase, cBelly, cTail, cBead = null;
        if (Math.abs(k) === 2 || lightFactor < 0.38) {
          cBase = random(["#0b2b22", "#123d29", "#0d3338"]);
          cBelly = random(["#1e5c32", "#286e39", "#195752"]);
          cTail = random(["#439448", "#38876c", "#6eb85a"]);
          if (random() < 0.4) cBead = "#2f7d40";
        } else if (Math.abs(k) === 1) {
          if (lightFactor > 0.58) {
            cBase = random(["#c72214", "#d93018", "#215e2e"]);
            cBelly = random(["#eb491c", "#f07c14", "#39853e"]);
            cTail = random(["#ffb324", "#ffd147", "#5eb04e"]);
            cBead = "#ff6e24";
          } else {
            cBase = random(["#164728", "#8f1912", "#14423d"]);
            cBelly = random(["#297036", "#c93118", "#246b5c"]);
            cTail = random(["#52a149", "#f28d18", "#54ab8e"]);
          }
        } else {
          if (lightFactor > 0.45) {
            cBase = random(["#d92b16", "#e85c12"]);
            cBelly = random(["#f59314", "#ffad1f"]);
            cTail = random(["#ffdc5e", "#e8f299"]);
            cBead = "#ffe36e";
          } else {
            cBase = "#19522c";
            cBelly = "#36823c";
            cTail = "#f29718";
            cBead = "#56ab4e";
          }
        }

        let wSc = random(0.88, 1.15);
        drawPetrykivkaComma(pts, cBase, cBelly, cTail, wSc, cBead);

        if (isRecordingStill && Math.abs(k) <= 1 && (!inWattleShadow || cy > 860)) {
          recordedNeckCommas.push({
            sx, sy,
            angle: baseAxis + offsetAngle,
            len: strokeLen,
            bend,
            u,
            pts0: pts,
            cBase, cBelly, cTail, wScale: wSc, cBead,
            seed: 20000 + r * 100 + f * 10 + (k + 2)
          });
        }
      }
    }
  }

  // Pass 3B: Primary Accumulation of Hundreds of Imbricated Lanceolate Comma Strokes
  const totalTiers = 24;
  for (let tier = 0; tier < totalTiers; tier++) {
    let normTier = tier / (totalTiers - 1);
    let baseY = lerp(1140, 348, Math.pow(normTier, 0.92));
    let { xLeft, xRight, t } = getNeckBounds(baseY);

    if (baseY < 520) {
      xRight = map(baseY, 348, 520, 610, 565);
    } else if (baseY < 860) {
      xRight = Math.min(xRight, map(baseY, 520, 860, 660, 830));
    }

    let span = Math.max(80, xRight - xLeft);
    let strokeCount = Math.floor(map(normTier, 0, 1, 21, 13));
    let stagger = (tier % 2) * 0.48;

    for (let i = -1; i <= strokeCount; i++) {
      let u = (i + stagger + random(-0.14, 0.14)) / strokeCount;
      if (u < -0.06 || u > 1.04) continue;

      let sx = xLeft + span * u;
      let sy = baseY + Math.sin(u * Math.PI) * 18 + random(-7, 7);

      let flowAngle;
      if (baseY < 470) {
        flowAngle = map(u, 0, 1, 2.52, 2.05) + random(-0.08, 0.08);
      } else {
        flowAngle = map(u, 0, 1, 2.28, 1.32) + random(-0.09, 0.09);
      }

      let baseLen = map(normTier, 0, 1, 148, 54) * map(Math.abs(u - 0.35), 0, 0.7, 1.12, 0.84);
      let strokeLen = baseLen * random(0.88, 1.14);

      let bendDir = u < 0.22 ? 1 : (u > 0.78 ? -1 : (i % 2 === 0 ? 1 : -0.7));
      let bendAmount = bendDir * random(0.36, 0.68);

      let pts = buildCommaPath(sx, sy, flowAngle, strokeLen, bendAmount);

      let inWattleShadow = (sx > 530 && sy > 480 && sy < 930);
      let cylinderLight = Math.exp(-Math.pow((u - 0.26) / 0.36, 2));
      let heightLight = map(normTier, 0, 1, 0.65, 1.05);
      let lum = cylinderLight * heightLight * (inWattleShadow ? 0.42 : 1.0);

      let wScale = map(normTier, 0, 1, 1.12, 0.64) * random(0.88, 1.12);

      let roll = (i * 7 + tier * 3) % 10;
      let cBase, cBelly, cTail, cBead = null;

      if (lum > 0.68) {
        if (roll < 4) {
          cBase = random(["#e06b0e", "#eb8410", "#d44d12"]);
          cBelly = random(["#ffad19", "#ffc429", "#ffa014"]);
          cTail = random(["#ffe875", "#fff2a6", "#d9f285"]);
          cBead = random(["#d92514", "#fff099"]);
        } else if (roll < 8) {
          cBase = random(["#b81812", "#d42616", "#e03419"]);
          cBelly = random(["#f2481d", "#ff5e24", "#eb3b18"]);
          cTail = random(["#ffb824", "#ffd447", "#ff9519"]);
          cBead = "#ffad24";
        } else {
          cBase = random(["#194f28", "#205e2e"]);
          cBelly = random(["#36853b", "#459944"]);
          cTail = random(["#8cd158", "#ffcf40"]);
          cBead = "#6ec252";
        }
      } else if (lum > 0.36) {
        if (roll < 4) {
