        } else {
          cBase = "#143822";
          cBelly = "#8c520f";
          cTail = "#d98c16";
        }
      }

      drawPetrykivkaComma(pts, cBase, cBelly, cTail, wScale, cBead);

      if (isRecordingStill && (u < 0.16 || ((i + tier) % 2 === 0 && u < 0.85))) {
        recordedNeckCommas.push({
          sx, sy,
          angle: flowAngle,
          len: strokeLen,
          bend: bendAmount,
          u,
          pts0: pts,
          cBase, cBelly, cTail, wScale, cBead,
          seed: 30000 + tier * 100 + (i + 5)
        });
      }

      if (u < 0.55 && random() < 0.58) {
        let subAngle = flowAngle + (bendDir * 0.14);
        let subPts = buildCommaPath(
          sx + random(6, 13),
          sy + random(4, 10),
          subAngle,
          strokeLen * 0.76,
          bendAmount * 1.12
        );
        let scBase = roll % 2 === 0 ? "#1b592e" : "#cf2917";
        let scBelly = roll % 2 === 0 ? "#3b8c3f" : "#f58216";
        let scTail = roll % 2 === 0 ? "#ffd24c" : "#62b54e";
        drawPetrykivkaComma(subPts, scBase, scBelly, scTail, wScale * 0.72, null);
      }
    }
  }

  // Pass 3C: Signature Hero Comma Strokes Along the Dorsal Crest & Cascading Plume Tips
  for (let h = 0; h < 42; h++) {
    let ht = h / 41;
    let hy = lerp(355, 1130, ht);
    let { xLeft, xRight } = getNeckBounds(hy);
    let hu = (h % 3 === 0) ? random(-0.02, 0.06) : random(0.14, 0.52);
    let hx = xLeft + (xRight - xLeft) * hu;
    let hAngle = map(hu, -0.02, 0.52, 2.38, 1.82) + (hy < 460 ? 0.22 : 0);
