    } else {
      cBase = "#164f28"; cBelly = "#34873c"; cTail = "#ffba24";
      wSc = map(ht, 0, 1, 0.75, 1.15); cBead = "#6bc454";
    }
    drawPetrykivkaComma(hPts, cBase, cBelly, cTail, wSc, cBead);

    if (isRecordingStill) {
      recordedNeckCommas.push({
        sx: hx, sy: hy,
