  brush.fill("#5e081c", 185);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.25);
  drawClosedShape([
    [775, 515], [848, 575], [882, 675], [865, 755], [815, 785], [775, 690]
  ], 0.4);
  brush.fill("#ab1422", 140);
  drawClosedShape([
    [835, 580], [878, 665], [868, 745], [832, 768], [822, 675]
  ], 0.4);
  brush.noFill();

  drawVeinTree(810, 540, 1.35, 165, 0.95, 3, false);
  drawVeinTree(840, 610, 1.55, 130, 0.80, 2, false);

