    [758, 390], [835, 395], [912, 418], [970, 452],
    [994, 482], [958, 474], [895, 466], [812, 463], [732, 466]
  ];
  const lowerBeakPts = [
    [732, 466], [812, 465], [895, 469], [964, 480],
    [912, 496], [835, 503], [742, 498]
  ];

  brush.noStroke();
  brush.wash("#141821", 255);
  drawClosedShape(upperBeakPts, 0.25);
  drawClosedShape(lowerBeakPts, 0.25);
