  brush.fill("#5c482e", 170);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.35, 0.2);
  drawClosedShape([
    [795, 405], [885, 418], [965, 452], [988, 480], [900, 466], [805, 460]
  ], 0.25);

