    brush.set("comma_filament", col, random(0.35, 0.65));
    brush.spline([
      [lerp(768, 742, t), yStart],
      [855, yMid],
      [930, lerp(438, 471, t)],
      [lerp(988, 962, t), yEnd]
    ], 0.45);
