    [[wx + 2.8, wy + 1.2], [wx + 8.2, wy + 2.0], [wx + 7.6, wy + 6.5], [wx + 3.0, wy + 5.8]]
  ];

  brush.noStroke();
  for (let p = 0; p < panes.length; p++) {
    brush.wash(p < 2 ? "#f2f8ff" : "#cbe2fa", 255);
    drawClosedShape(panes[p], 0.15);
  }
  brush.noWash();

  brush.set("comma_filament", "#ffffff", 0.72);
  brush.line(wx - 3.8, wy - 3.6, wx + 0.4, wy - 4.6);
  brush.line(wx + 3.0, wy - 4.8, wx + 7.2, wy - 3.6);
  brush.set("comma_body", "#ffffff", 0.28);
  brush.line(wx - 2.0, wy - 2.8, wx - 0.5, wy - 3.2);

  brush.set("comma_filament", "#b8d4f2", 0.45);
  brush.spline([
    [EX - 21, EY + 21],
    [EX - 12, EY + 27],
    [EX - 1, EY + 29],
    [EX + 9, EY + 27]
  ], 0.5);
  brush.set("comma_body", "#ffffff", 0.24);
  brush.line(EX + 27, EY + 14, EX + 28.5, EY + 14.5);

  isRecordingStill = false;
}

function smooth01(x) {
  let c = constrain(x, 0, 1);
  return c * c * (3 - 2 * c);
}

// Dividing line y between the Head (Comb, Face, Ear-Lobe, Beak) and the Neck / Wattles below
function getHeadBottomY(x) {
  if (x < 462) {
    return map(x, 220, 462, 235, 354, true);
  } else if (x < 492) {
    return map(x, 462, 492, 354, 540);
  } else if (x < 562) {
    return 580;
  } else if (x < 602) {
    return map(x, 562, 602, 580, 502);
  } else if (x < 745) {
    return map(x, 602, 745, 502, 498);
  } else {
    return 508;
  }
}

// Prepare lifted cutout layers (Head + Comb + Beak, Pendulous Wattles, and Clean Backdrop) once on frame 2
function prepareCutoutLayers() {
  if (layersPrepared || !stillImg) return;
  const W = stillImg.width;
  const H = stillImg.height;
  const sx = 1200 / W;
  const sy = 1200 / H;

  cleanBackdropImg = createImage(W, H);
  headCutoutImg = createImage(W, H);
  wattleCutoutImg = createImage(W, H);

  stillImg.loadPixels();
  cleanBackdropImg.loadPixels();
  headCutoutImg.loadPixels();
  wattleCutoutImg.loadPixels();

  const src = stillImg.pixels;
  const bgDst = cleanBackdropImg.pixels;
  const headDst = headCutoutImg.pixels;
  const watDst = wattleCutoutImg.pixels;

  for (let py = 0; py < H; py++) {
    let y = py * sy;
    for (let px = 0; px < W; px++) {
      let x = px * sx;
      let idx = (py * W + px) * 4;
      let r = src[idx];
      let g = src[idx + 1];
      let b = src[idx + 2];
      let a = src[idx + 3];

      // Default: copy pixel to cleanBackdropImg
      bgDst[idx] = r;
      bgDst[idx + 1] = g;
      bgDst[idx + 2] = b;
      bgDst[idx + 3] = a;

      // 1. Evaluate HEAD cutout mask (Comb + Veins + Beak + Face + Eye + Ear-Lobe)
      let hAlpha = 0;
      if (x >= 135 && x <= 1025 && y >= 5 && y <= 592) {
        let hBot = getHeadBottomY(x);
        if (y <= hBot + 8) {
          // Exclude green/gold neck hackles to the left of the face/ear-lobe (x < 548, y > 356)
          let inEarLobe = Math.hypot(x - 540, y - 530) < 54;
          let inFaceOrCombOrBeak = (y <= 356) || (x >= 546) || inEarLobe;
          if (inFaceOrCombOrBeak) {
            let seamFade = smooth01((hBot + 6 - y) / 11);
            let leftFade = (y > 356 && !inEarLobe) ? smooth01((x - 542) / 14) : 1.0;
            // In outer background areas (y < 348 or x > 730), only lift non-background painted pixels
            let isPainted = true;
            if (y < 346 || x > 735 || x < 455) {
              isPainted = (r > 13 || g > 19 || b > 31);
            }
            if (isPainted) {
              hAlpha = Math.round(255 * seamFade * leftFade);
            }
          }
        }
      }

      if (hAlpha > 0) {
        headDst[idx] = r;
        headDst[idx + 1] = g;
        headDst[idx + 2] = b;
        headDst[idx + 3] = hAlpha;

        // Clean outer Comb and Beak pixels from cleanBackdropImg so tilting the head leaves zero ghost behind
        if (y < 350 || x > 725 || x < 458) {
          bgDst[idx] = 4;
          bgDst[idx + 1] = 6;
          bgDst[idx + 2] = 10;
        }
      }

      // 2. Evaluate WATTLE cutout mask (Near Wattle + Far Wattle + Projecting Scarlet Veins)
      let wAlpha = 0;
      if (x >= 530 && x <= 935 && y >= 484 && y <= 985) {
        let topFade = smooth01((y - 484) / 14);
        // Core solid wattle envelope
        let leftEdge = y < 700 ? map(y, 490, 700, 595, 610) : map(y, 700, 912, 610, 680);
        let rightEdge = y < 690 ? map(y, 490, 690, 815, 902) : (y < 795 ? map(y, 690, 795, 902, 845) : map(y, 795, 912, 845, 745));
        let inCore = (y >= 490 && y <= 910 && x >= leftEdge && x <= rightEdge);
        if (inCore && (r > 22 || g > 12)) {
          let edgeDist = Math.min(x - leftEdge, rightEdge - x, 910 - y);
          let coreFade = smooth01((edgeDist + 4) / 8);
          wAlpha = Math.round(255 * topFade * coreFade);
        } else {
          // Capture projecting red capillary veins around the wattle perimeter
          if (r > g + 16 && r > 32 && r > b + 10) {
            let veinStrength = constrain((r - g - 12) / 36, 0, 1);
            wAlpha = Math.round(255 * topFade * veinStrength);
          }
        }
      }

      if (wAlpha > 0) {
        watDst[idx] = r;
        watDst[idx + 1] = g;
        watDst[idx + 2] = b;
        watDst[idx + 3] = wAlpha;

        // Clean lifted wattle & vein pixels from cleanBackdropImg:
        // To the right of the neck edge -> black lacquer (#04060a); over the neck -> deep cast shadow (#040a0e)
        let neckRightEdge = 625 + 315 * Math.pow(constrain((y - 345) / (1190 - 345), 0, 1), 1.15);
        if (x > neckRightEdge - 12) {
          bgDst[idx] = 4;
          bgDst[idx + 1] = 6;
          bgDst[idx + 2] = 10;
        } else {
          let cleanMix = (wAlpha / 255) * 0.92;
          bgDst[idx] = Math.round(lerp(r, 4, cleanMix));
          bgDst[idx + 1] = Math.round(lerp(g, 11, cleanMix));
          bgDst[idx + 2] = Math.round(lerp(b, 14, cleanMix));
        }
      }
    }
  }

  cleanBackdropImg.updatePixels();
  headCutoutImg.updatePixels();
  wattleCutoutImg.updatePixels();
  layersPrepared = true;
}

// Compute the rooster's articulated head cocking & wattle pendulum state at time t (seconds)
function getRoosterMotionState(t) {
  // Fast onset within the first 5 frames
  let fastEase = smooth01(t / 0.14);

  // Proud head-cocking curve: tilts sharply upward/back in first 0.55s, gives an alert nod around 1.15s, holds proud pose
  let cockMain = Math.sin(constrain(t / 1.05, 0, 1) * Math.PI * 0.5);
  let cockNod = 0.32 * Math.sin(t * 5.4 - 0.4);
  let headSignal = fastEase * (0.82 * cockMain + cockNod);

  // Negative angle = counter-clockwise in screen space (raises the beak on the right, tilts the tall comb back/up!)
  let headTiltDeg = -8.4 * headSignal;
  let headDx = -10.0 * headSignal;
  let headDy = -18.5 * headSignal;

  // Throat wattle pivot moves with the jaw/head
  let [wPivotX, wPivotY] = transformHeadPt(WPX, WPY, headDx, headDy, headTiltDeg * 0.8);

  // Heavy pendulum swing of the wattles triggered by the sharp head cock
  // Swings boldly right (-10.5 deg) at t=0.28s, swings back left (+8.0 deg) at t=0.82s, then secondary swing
  let wattleSwingDeg = fastEase * (-10.8 * Math.sin(t * 5.5) * Math.exp(-t * 0.18) - 2.5 * headSignal);

  return {
    fastEase,
    headSignal,
    headTiltDeg,
    headDx,
    headDy,
    wPivotX,
    wPivotY,
    wattleSwingDeg
  };
}

function transformHeadPt(x, y, headDx, headDy, headTiltDeg) {
  let rad = headTiltDeg * Math.PI / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  let dx = x - HPX;
  let dy = y - HPY;
  return [
    HPX + headDx + dx * c - dy * s,
    HPY + headDy + dx * s + dy * c
  ];
}

function transformWattlePt(x, y, wPivotX, wPivotY, wattleSwingDeg) {
  let rad = wattleSwingDeg * Math.PI / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  let dx = x - WPX;
  let dy = y - WPY;
  return [
    wPivotX + dx * c - dy * s,
    wPivotY + dx * s + dy * c
  ];
}

// Render a boldly rippling & flaring Petrykivka comma stroke across the neck cape
function renderAnimatedComma(cm, t, state, isJewel = false) {
  let ny = constrain((cm.sy - 348) / 805, 0, 1);
  let nu = constrain(cm.u, 0, 1);

  // Fast, high-amplitude traveling ruffle wave sweeping from nape (ny=0) down the cape (ny=1)
  let wavePhase = t * 7.2 - ny * 4.0 - nu * 0.75;
  let ripple = Math.sin(wavePhase);
  let whipFollow = Math.sin(wavePhase - 0.95);

  // Strong hackle erection envelope across the clip
  let proudFlare = Math.sin(constrain(t / 0.85, 0, 1) * Math.PI * 0.5) * (0.85 + 0.25 * Math.sin(t * 4.5 - ny * 2.5));
  let dorsalBoost = map(nu, 0, 0.8, 1.35, 0.65, true);

  // Large angular lift (up to ~21 degrees) and S-curve whip flex so every comma stroke visibly travels 25–42 px
  let dAngle = state.fastEase * dorsalBoost * (0.22 * proudFlare + 0.16 * ripple);
  let dBend = state.fastEase * dorsalBoost * (0.28 * whipFollow + 0.10 * proudFlare);
  let lenScale = 1.0 + state.fastEase * (0.07 * proudFlare + 0.05 * ripple);

  // Upper neck feathers couple smoothly into the cocking head motion
  let headCouple = isJewel ? map(ny, 0, 0.4, 0.85, 0.35, true) : Math.pow(constrain(1.0 - ny * 1.65, 0, 1), 1.5);
  let [coupledX, coupledY] = transformHeadPt(
    cm.sx,
    cm.sy,
    state.headDx * headCouple,
    state.headDy * headCouple,
    state.headTiltDeg * headCouple
  );

  // Additional outward dorsal puff along the left arch of the neck
  let puffX = state.fastEase * (-13.5 * dorsalBoost * (0.65 * proudFlare + 0.35 * Math.max(0, ripple)));
  let puffY = state.fastEase * (-9.5 * dorsalBoost * (0.65 * proudFlare + 0.35 * ripple));

  let headRadCouple = (state.headTiltDeg * Math.PI / 180) * headCouple * 0.65;

  let newPts = buildCommaPath(
    coupledX + puffX,
    coupledY + puffY,
    cm.angle + dAngle + headRadCouple,
    cm.len * lenScale,
    cm.bend + dBend
  );

  randomSeed(cm.seed);
  noiseSeed(cm.seed);

  // Erase the static frame-0 comma footprint in cleanBackdropImg down to the dark emerald-black neck bed
  let bedCol = cm.u < 0.06 ? "#04070b" : (cm.sy < 540 ? "#12100a" : "#061915");
  brush.set("comma_body", bedCol, cm.wScale * 1.38);
  brush.spline(cm.pts0, 0.55);

  // Iridescent color shift as the feather tilts into the light on the wave crest
  let colBelly = cm.cBelly;
  let colTail = cm.cTail;
  let colBead = cm.cBead;
  if (ripple > 0.15) {
    if (cm.cBase === "#164f28" || cm.cBase === "#19522c" || cm.cBase === "#0f3820" || cm.cBase === "#174a28") {
      colBelly = "#3da146";
      colTail = "#b2f57d";
      colBead = "#ffe875";
    } else {
      colTail = "#fff6ad";
      colBead = "#ffe366";
    }
  }

  drawPetrykivkaComma(newPts, cm.cBase, colBelly, colTail, cm.wScale * 1.06, colBead);
}

