// Fast, high-contrast avian eye blink locked to the cocking head
function renderAnimatedEye(t, state) {
  const [EX, EY] = transformHeadPt(650, 435, state.headDx, state.headDy, state.headTiltDeg);

  // Fast Blink 1 right in frames 2..12 (t = 0.04s .. 0.46s, 100% shut at frames 5, 6, 7!)
  // Fast Blink 2 around 1 second (frames 25..34, t = 1.00s .. 1.38s)
  let blinkAmt = 0;
  let nictAmt = 0;

  if (t >= 0.02 && t <= 0.48) {
    if (t < 0.15) {
      blinkAmt = smooth01((t - 0.02) / 0.13);
    } else if (t < 0.26) {
      blinkAmt = 1.0;
    } else {
      blinkAmt = 1.0 - smooth01((t - 0.26) / 0.22);
    }
    if (t < 0.13) {
      nictAmt = smooth01((t - 0.01) / 0.12);
    } else if (t < 0.28) {
      nictAmt = 1.0;
    } else {
      nictAmt = 1.0 - smooth01((t - 0.28) / 0.20);
    }
  } else if (t >= 0.98 && t <= 1.40) {
    if (t < 1.12) {
      blinkAmt = smooth01((t - 0.98) / 0.14);
    } else if (t < 1.20) {
      blinkAmt = 0.96;
    } else {
      blinkAmt = 0.96 * (1.0 - smooth01((t - 1.20) / 0.20));
    }
    nictAmt = Math.min(1.0, blinkAmt * 1.15);
  }

  // Sharp pupil reflex as the eye snaps open after Blink 1
  let pupilRadius = 14.2;
  if (t < 0.22) {
    pupilRadius = 14.2 + 2.2 * smooth01(t / 0.20);
  } else if (t < 0.68) {
    let u = smooth01((t - 0.22) / 0.46);
    pupilRadius = lerp(16.4, 10.5, Math.sin(u * Math.PI * 0.5));
  } else {
    let u = smooth01((t - 0.68) / 1.25);
    pupilRadius = lerp(10.5, 13.8, u);
  }

  randomSeed(91001);
  noiseSeed(91001);

  // 1. Leathery dark charcoal-plum & scarlet outer eyelid ring
  brush.noStroke();
  brush.wash("#1a0910", 255);
  brush.circle(EX, EY, 39, 0.08);
  brush.noWash();

  // 2. Deep recessed corneal socket & limbal ring
  brush.noStroke();
  brush.wash("#060304", 255);
  brush.circle(EX, EY, 33.5, 0.04);
  brush.noWash();

  // 3. Glowing Amber & Burnt-Sienna Iris Base
  brush.noStroke();
  brush.wash("#6e2004", 255);
  brush.circle(EX, EY, 29.5, 0.03);
  brush.noWash();

  brush.noStroke();
  brush.fill("#c94e06", 210);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.25, 0.1);
  brush.circle(EX, EY, 26.5, 0.04);

  brush.fill("#ff9d0a", 195);
  drawClosedShape([
    [EX - 24, EY - 4], [EX - 15, EY - 14], [EX + 12, EY + 14],
    [EX + 22, EY + 6], [EX + 14, EY + 23], [EX - 14, EY + 22]
  ], 0.4);
  brush.noFill();

  // 4. Microscopic Radial Iris Fibers tracking the contracting/dilating pupil
  let rScale = pupilRadius / 14.2;
  for (let i = 0; i < 150; i++) {
    let a = (i / 150) * Math.PI * 2 + random(-0.02, 0.02);
    let rIn = random(13.5, 15.5) * rScale;
    let rOut = random(27.5, 30.5);
    let x1 = EX + Math.cos(a) * rIn;
    let y1 = EY + Math.sin(a) * rIn;
    let xm = EX + Math.cos(a + 0.05) * ((rIn + rOut) * 0.5);
    let ym = EY + Math.sin(a + 0.05) * ((rIn + rOut) * 0.5);
    let x2 = EX + Math.cos(a) * rOut;
    let y2 = EY + Math.sin(a) * rOut;

    let isLower = Math.sin(a) > -0.15;
    let col = isLower
      ? random(["#ffad14", "#ffd242", "#eb5a0c", "#fff099", "#b83906"])
      : random(["#3b1003", "#6e2206", "#9e3808", "#d4650b"]);
    brush.set("comma_filament", col, random(0.26, 0.46));
    brush.spline([[x1, y1], [xm, ym], [x2, y2]], 0.4);
  }

  for (let i = 0; i < 24; i++) {
    let a1 = (i / 24) * Math.PI * 2;
    let a2 = ((i + 1.2) / 24) * Math.PI * 2;
    brush.set("vein_brush", "#080304", 0.85);
    brush.spline([
      [EX + Math.cos(a1) * 30.5, EY + Math.sin(a1) * 30.5],
      [EX + Math.cos((a1 + a2) * 0.5) * 31.2, EY + Math.sin((a1 + a2) * 0.5) * 31.2],
      [EX + Math.cos(a2) * 30.5, EY + Math.sin(a2) * 30.5]
    ], 0.5);
  }

  // 5. Jet-Black Pupil
  brush.noStroke();
  brush.wash("#020306", 255);
  brush.circle(EX, EY, pupilRadius, 0.02);
  brush.wash("#070e1c", 160);
  brush.circle(EX - 1.5, EY - 1.5, pupilRadius * 0.67, 0.02);
  brush.noWash();

  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * Math.PI * 2;
    let px1 = EX + Math.cos(a) * (pupilRadius - 0.2);
    let py1 = EY + Math.sin(a) * (pupilRadius - 0.2);
    let px2 = EX + Math.cos(a) * (pupilRadius + 2.4);
    let py2 = EY + Math.sin(a) * (pupilRadius + 2.4);
    brush.set("comma_filament", Math.sin(a) > 0 ? "#ffe066" : "#b84c08", 0.32);
    brush.line(px1, py1, px2, py2);
  }

  // 6. Translucent Avian Nictitating Membrane sweeping across the cornea
  if (nictAmt > 0.02) {
    randomSeed(92002);
    noiseSeed(92002);
    let sweepDist = lerp(-32, 33, nictAmt);
    let dirX = -0.78;
    let dirY = 0.62;
    let perpX = -dirY;
    let perpY = dirX;

    let leadCx = EX + dirX * sweepDist;
    let leadCy = EY + dirY * sweepDist;

    let memPts = [
      [EX + 24, EY - 24],
      [EX + 33, EY - 6],
      [EX + 26, EY + 19],
      [leadCx + perpX * 26, leadCy + perpY * 26],
      [leadCx + dirX * 4, leadCy + dirY * 4],
      [leadCx - perpX * 26, leadCy - perpY * 26],
      [EX - 16, EY - 29],
      [EX + 6, EY - 33]
    ];

    brush.noStroke();
    brush.fill("#edd0c5", 170);
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.25, 0.15);
    drawClosedShape(memPts, 0.35);

    brush.fill("#c44952", 120);
    drawClosedShape(memPts, 0.35);
    brush.noFill();

    let edgePts = [
      [leadCx - perpX * 28, leadCy - perpY * 28],
      [leadCx + dirX * 3 - perpX * 10, leadCy + dirY * 3 - perpY * 10],
      [leadCx + dirX * 3 + perpX * 10, leadCy + dirY * 3 + perpY * 10],
      [leadCx + perpX * 28, leadCy + perpY * 28]
    ];
    brush.set("vein_brush", "#8f1d2c", 0.62);
    brush.spline(edgePts, 0.5);
    brush.set("comma_filament", "#ffffff", 0.68);
    brush.spline(edgePts, 0.5);
  }

  // 7. Closing Upper & Lower Fleshy Scarlet-Plum Eyelids
  if (blinkAmt > 0.01) {
    randomSeed(93003);
    noiseSeed(93003);

    let meetY = EY + 2.0;
    let upperLidY = lerp(EY - 34.5, meetY + 1.5, blinkAmt);
    let lowerLidY = lerp(EY + 34.5, meetY - 1.5, blinkAmt);

    let upperLidPts = [
      [EX - 37, EY + 2],
      [EX - 34, EY - 20],
      [EX - 18, EY - 35],
      [EX + 4, EY - 37],
      [EX + 24, EY - 31],
      [EX + 36, EY - 14],
      [EX + 37, EY + 2],
      [EX + 20, lerp(EY - 22, upperLidY + 2, blinkAmt)],
      [EX, upperLidY],
      [EX - 20, lerp(EY - 22, upperLidY + 2, blinkAmt)]
    ];

    let lowerLidPts = [
      [EX - 37, EY + 1],
      [EX - 20, lerp(EY + 22, lowerLidY - 2, blinkAmt)],
      [EX, lowerLidY],
      [EX + 20, lerp(EY + 22, lowerLidY - 2, blinkAmt)],
      [EX + 37, EY + 1],
      [EX + 34, EY + 21],
      [EX + 16, EY + 35],
      [EX - 6, EY + 37],
      [EX - 25, EY + 30]
    ];

    brush.noStroke();
    brush.wash("#300711", 255);
    drawClosedShape(upperLidPts, 0.35);
    drawClosedShape(lowerLidPts, 0.35);
    brush.noWash();

    brush.noStroke();
    brush.fill("#b81620", 225);
    brush.fillBleed(0.1, "in");
    brush.fillTexture(0.35, 0.2);
    drawClosedShape(upperLidPts, 0.35);
    drawClosedShape(lowerLidPts, 0.35);

    if (blinkAmt > 0.2) {
      brush.fill("#f02c19", 185);
      drawClosedShape([
        [EX - 26, EY - 10],
        [EX - 12, EY - 26],
        [EX + 14, EY - 26],
        [EX + 26, EY - 10],
        [EX + 14, upperLidY - 2],
        [EX - 14, upperLidY - 2]
      ], 0.4);
    }
    brush.noFill();

    let upperMargin = [
      [EX - 35, EY + 1],
      [EX - 18, lerp(EY - 24, upperLidY + 1.5, blinkAmt)],
      [EX, upperLidY],
      [EX + 18, lerp(EY - 24, upperLidY + 1.5, blinkAmt)],
      [EX + 35, EY + 1]
    ];
    let lowerMargin = [
      [EX - 35, EY + 2],
      [EX - 18, lerp(EY + 24, lowerLidY - 1.5, blinkAmt)],
      [EX, lowerLidY],
      [EX + 18, lerp(EY + 24, lowerLidY - 1.5, blinkAmt)],
      [EX + 35, EY + 2]
    ];

    brush.set("vein_brush", "#120206", 1.0);
    brush.spline(upperMargin, 0.45);
    brush.spline(lowerMargin, 0.45);

    let creaseY1 = lerp(EY - 30, (EY - 32 + upperLidY) * 0.5, blinkAmt);
    brush.set("vein_brush", "#450612", 0.65);
    brush.spline([[EX - 28, EY - 6], [EX - 12, creaseY1], [EX + 12, creaseY1], [EX + 28, EY - 6]], 0.45);
    brush.set("comma_filament", "#ff8578", 0.48);
    brush.spline([[EX - 26, EY - 7], [EX - 12, creaseY1 - 1.5], [EX + 12, creaseY1 - 1.5], [EX + 26, EY - 7]], 0.45);

    for (let s = 1; s <= 11; s++) {
      let u = s / 12;
      let upPt = evalQuadPath(upperMargin, u);
      let loPt = evalQuadPath(lowerMargin, u);
      brush.set("comma_body", "#4a121f", 0.34);
      brush.line(upPt[0] - 1.5, upPt[1] - 1.5, upPt[0] + 1.5, upPt[1] - 1.5);
      brush.set("comma_filament", "#ebbfd0", 0.38);
      brush.line(upPt[0] - 1, upPt[1] - 2.2, upPt[0] + 1.2, upPt[1] - 1.8);

      brush.set("comma_body", "#3d101b", 0.32);
      brush.line(loPt[0] - 1.5, loPt[1] + 1.5, loPt[0] + 1.5, loPt[1] + 1.5);
      brush.set("comma_filament", "#cfdcf2", 0.35);
      brush.line(loPt[0] - 1, loPt[1] + 1.0, loPt[0] + 1.2, loPt[1] + 1.2);
    }
  }

  // Outer 28 fleshy eyelid rim tubercles
  randomSeed(94004);
  noiseSeed(94004);
  for (let i = 0; i < 28; i++) {
    let a = (i / 28) * Math.PI * 2;
    let tx = EX + Math.cos(a) * 36.5;
    let ty = EY + Math.sin(a) * 35.5;
    brush.set("comma_body", "#3d121d", 0.34);
    brush.line(tx, ty, tx + Math.cos(a) * 3, ty + Math.sin(a) * 3);
    brush.set("comma_filament", i < 16 ? "#d49eb2" : "#cfdcf2", 0.35);
    brush.line(tx - 1, ty - 1, tx + 1.5, ty - 0.5);
  }

  // 8. Pinpoint reflection of the 4-pane window on the glossy corneal dome
  if (blinkAmt < 0.50) {
    const wx = EX + 6 - state.headSignal * 1.4;
    const wy = EY - 13 + state.headSignal * 1.1;

    brush.noStroke();
    brush.fill("#8cb8eb", 95);
    brush.fillBleed(0.18, "out");
    brush.circle(wx + 4, wy + 4, 11, 0.05);
    brush.noFill();

    const panes = [
      [[wx - 4.5, wy - 4.0], [wx + 0.8, wy - 5.2], [wx + 1.2, wy - 0.5], [wx - 4.2, wy + 0.4]],
      [[wx + 2.6, wy - 5.5], [wx + 7.8, wy - 4.2], [wx + 8.2, wy + 0.4], [wx + 2.8, wy - 0.5]],
      [[wx - 4.0, wy + 2.0], [wx + 1.2, wy + 1.2], [wx + 1.5, wy + 5.8], [wx - 3.4, wy + 6.4]],
      [[wx + 2.8, wy + 1.2], [wx + 8.2, wy + 2.0], [wx + 7.6, wy + 6.5], [wx + 3.0, wy + 5.8]]
    ];

    brush.noStroke();
    for (let p = 0; p < panes.length; p++) {
      brush.wash(p < 2 ? "#f2f8ff" : "#cbe2fa", 255);
      drawClosedShape(panes[p], 0.15);
    }
    brush.noWash();

    brush.set("comma_filament", "#ffffff", 0.75);
    brush.line(wx - 3.8, wy - 3.6, wx + 0.4, wy - 4.6);
    brush.line(wx + 3.0, wy - 4.8, wx + 7.2, wy - 3.6);
    brush.set("comma_body", "#ffffff", 0.30);
    brush.line(wx - 2.0, wy - 2.8, wx - 0.5, wy - 3.2);
  }

  if (blinkAmt < 0.70) {
    brush.set("comma_filament", "#b8d4f2", 0.48);
    brush.spline([
      [EX - 21, EY + 21],
      [EX - 12, EY + 27],
      [EX - 1, EY + 29],
      [EX + 9, EY + 27]
    ], 0.5);
    brush.set("comma_body", "#ffffff", 0.26);
    brush.line(EX + 27, EY + 14, EX + 28.5, EY + 14.5);
  }
}

function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  // Frame 0 (frameCount === 1): paint the exact reference still and cache its snapshot
  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // On Frame 1 (frameCount === 2): extract the Head/Comb/Beak cutout, Wattle cutout, and Clean Backdrop once
  if (!layersPrepared) {
    prepareCutoutLayers();
  }

  const t = (frameCount - 1) / window.PIECE_FPS;
  const state = getRoosterMotionState(t);

  background("#04060a");
  translate(-width / 2, -height / 2);

  // 1. Stamp the cleaned backdrop (background + neck bed, with protruding Comb, Beak, and Wattle ghosts removed)
  image(cleanBackdropImg, 0, 0, 1200, 1200);

  // 2. Stamp the lifted Pendulous Wattles swinging around the throat pivot
  push();
  translate(state.wPivotX, state.wPivotY);
  rotate(state.wattleSwingDeg);
  translate(-WPX, -WPY);
  image(wattleCutoutImg, 0, 0, 1200, 1200);
  pop();

  // 3. Stamp the lifted Head (Comb, Beak, Face, Ear-Lobe) cocking upward and tilting around the skull/atlas pivot
  push();
  translate(HPX + state.headDx, HPY + state.headDy);
  rotate(state.headTiltDeg);
  translate(-HPX, -HPY);
  image(headCutoutImg, 0, 0, 1200, 1200);
  pop();

  // 4. Ripple and flare hundreds of Petrykivka comma strokes down the entire neck hackle cape
  for (let i = 0; i < recordedNeckCommas.length; i++) {
    renderAnimatedComma(recordedNeckCommas[i], t, state, false);
  }

  // 5. Repaint the porcelain-white ear-lobe cushion and foreground jewel commas to knit the head-neck junction
  renderAnimatedEarLobe(state);
  for (let i = 0; i < recordedJewelCommas.length; i++) {
    renderAnimatedComma(recordedJewelCommas[i], t, state, true);
  }

  // 6. Animate the swinging wattle drapery folds, crevices, and cocked comb/beak specular glints
  renderAnimatedWattleAndCombDetails(t, state);

  // 7. Fast, high-contrast avian blink and pupil reflex on the cocked head
  renderAnimatedEye(t, state);
}

04-vending:
// MOTION: The towering cumulus cloud visibly swells and boils across the sky, the flooded rice paddy ripples across its entire surface, the vending machine's display and 27 button lights blink as a cold red cola can drops into the pickup chute, and large red dragonflies rocket past on the summer wind.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

// Hyperreal Rural Vending Machine Beside a Flooded Rice Paddy
// Hand-painted anime background style (opaque watercolor / gouache + fine technical pen)

const Y_HORIZON = 825;
const VP1 = { x: -160, y: Y_HORIZON }; // Left vanishing point (front plane & paddy rows)
const VP2 = { x: 1560, y: Y_HORIZON }; // Right vanishing point (side plane & crossarms)

let stillImg = null;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(19980815);
  noiseSeed(19980815);

  // Register custom brushes for gouache cloud edges, enamel texture, and technical pen work
  brush.add("cloud_puff", {
    type: "default",
    weight: 7,
    scatter: 1.35,
    sharpness: 0.22,
    grain: 14,
    opacity: 48,
    spacing: 0.32,
    pressure: [0.35, 1.15, 0.35],
    noise: 0.6
  });

  brush.add("gouache_flat", {
    type: "custom",
    weight: 4.5,
    scatter: 0.12,
    opacity: 85,
    spacing: 0.22,
    pressure: [0.8, 1.1, 0.7],
    tip: (_m) => {
      _m.rotate(15);
      _m.rect(-2.2, -0.7, 4.4, 1.4);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.25
  });

  brush.add("fine_liner", {
    type: "default",
    weight: 0.55,
    scatter: 0.01,
    sharpness: 0.94,
    grain: 2,
    opacity: 230,
    spacing: 0.12,
    pressure: [0.9, 1.0, 0.9],
    noise: 0.12
  });

  brush.add("foliage_dab", {
    type: "default",
    weight: 3.5,
    scatter: 0.9,
    sharpness: 0.45,
    grain: 10,
    opacity: 95,
    spacing: 0.4,
    pressure: [0.4, 1.2, 0.3],
    noise: 0.7
  });
}

function paintStill() {
  translate(-width / 2, -height / 2);
  background("#fcf4e3"); // Warm sunlit watercolor board base

  // 1. Wide Late-Summer Sky (Cerulean to Warm Apricot Horizon)
  drawSky();

  // 2. Towering Cumulus Cloud in Cerulean, Titanium White & Crisp Lilac Undersides
  drawToweringCumulus();

  // 3. Distant Mountains, Treeline & Sunlit Rural Hamlet on the Low Horizon
  drawDistantLandscape();

  // 4. Flooded Rice Paddy with Sky/Cloud Mirror Reflections & Rice Seedling Rows
  drawFloodedPaddy();

  // 5. Concrete Paddy Dike, Sunlit Rural Road, Cast Shadows & Summer Weeds
  drawRoadAndEmbankment();

  // 6. Distant Utility Poles & Main Weathered Concrete Pole with Transformer
  drawUtilityPoles();

  // 7. Roadside Recycling Bin (tucked beside the vending machine)
  drawRecyclingBin();

  // 8. Hero Hyperreal Rural Vending Machine (Enamel, Cans, Labels, Condensation, Cola Logo)
  drawVendingMachine();

  // 9. Foreground Roadside Grasses, Foxtails & Sunlit Dust Motes
  drawForegroundWeeds();

  // 10. Crisp Fine Pen Power Lines Sweeping Across the Sky
  drawPowerLines();
}

function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  // Frame 0 (frameCount === 1): paint the exact still and snapshot it pixel-for-pixel
  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // Normalized clip progress u in [0, 1] and time t in [0, 2.0] seconds
  const u = (frameCount - 1) / (TOTAL_FRAMES - 1);
  const t = (frameCount - 1) / window.PIECE_FPS;

  // Fast ramp-in over the first 5 frames so motion is immediate & bold without a frame-1 pop
  const envIn = sin(constrain(u * 9.0, 0, 1) * 90);
  // Fast surge curve that covers real distance by 0.5s - 1.0s and continues through 2.0s
  const surge = pow(u, 0.72);

  drawingContext.disable(drawingContext.DEPTH_TEST);
  background("#fcf4e3");
  image(stillImg, -width / 2, -height / 2, width, height);
  translate(-width / 2, -height / 2);

  // 1. BIG MOTION 1: Towering Cumulus visibly drifts, swells upward & boils across the sky
  drawAnimatedCumulus(u, t, surge, envIn);

  // 2. Restore foreground structures that sit in front of the boiling cloud + animate swaying power lines
  restoreForegroundOverCloud(u, t, surge, envIn);

  // 3. BIG MOTION 2: Flooded Rice Paddy reflection ripples & sloshes across its entire surface
  drawAnimatedPaddyFullSurface(u, t, surge, envIn);

  // 4. BIG MOTION 3: Vending Machine display & 27 button lights blink, glass glare sweeps & red Cola can drops into chute
  drawAnimatedVendingMachineBold(u, t, surge, envIn);

  // 5. BIG MOTION 4: Gusting roadside weeds, streaming dandelion seeds & large fast foreground red dragonflies
  drawAnimatedForegroundWindAndDragonflies(u, t, surge, envIn);
}

// ============================================================================
// SNAPSHOT BLIT HELPER (HANDLES ANY PIXEL DENSITY CLEANLY)
// ============================================================================

function blitStill(dx, dy, dw, dh, sx, sy, sw, sh) {
  if (!stillImg || dw <= 0 || dh <= 0 || sw <= 0 || sh <= 0) return;
  const pd = stillImg.width / width;
  image(stillImg, dx, dy, dw, dh, sx * pd, sy * pd, sw * pd, sh * pd);
}

// ============================================================================
// 1. TOWERING CUMULUS DRIFTING, SWELLING & BOILING ACROSS THE SKY
// ============================================================================

function drawAnimatedCumulus(u, t, surge, envIn) {
  randomSeed(3001);
  noiseSeed(3001);

  // A. Repaint clean cerulean sky bands along the left trailing edge so the lifted cloud can slide right & up cleanly
  const skyPatchBands = [
    { y0: 70,  y1: 115, col: "#17609c" },
    { y0: 110, y1: 205, col: "#1e72b0" },
    { y0: 200, y1: 315, col: "#2b85bf" },
    { y0: 310, y1: 425, col: "#3e99cc" },
    { y0: 420, y1: 535, col: "#57aed8" },
    { y0: 530, y1: 635, col: "#77c2e0" },
    { y0: 630, y1: 720, col: "#a1d5e3" },
    { y0: 715, y1: 765, col: "#d6e2cf" }
  ];
  for (let b of skyPatchBands) {
    washPoly([[15, b.y0], [520, b.y0], [520, b.y1], [15, b.y1]], b.col, Math.round(235 * envIn));
  }

  // B. Lift the Towering Cumulus from stillImg in 58 soft-overlapping horizontal slices
  // and slide/swell them with differential parallax & internal boiling turbulence
  const stepY = 11;
  for (let sy = 740; sy >= 78; sy -= stepY) {
    // Normalized height in cloud: 0 at base (y=740), 1 at summit (y=78)
    let hNorm = constrain((740 - sy) / (740 - 78), 0, 1);
    let tierEnv = sin(constrain(hNorm * 1.15, 0, 1) * 90);

    // Bold rightward drift (+48px at summit, +22px at base) + boiling horizontal wave
    let boilX = sin(sy * 2.6 - t * 340) * 8.5 * envIn;
    let dx = (18 + 34 * tierEnv) * surge + boilX;

    // Bold upward convective swelling (-36px at summit turrets, tapering at anvil base)
    let boilY = cos(sy * 3.1 - t * 380) * 5.5 * envIn;
    let dy = (-36 * pow(hNorm, 1.15) - 6) * surge + boilY;

    // Horizontal expansion (cloud billows outward by up to +38px as it boils)
    let swellW = (16 + 26 * sin(hNorm * 180)) * surge;

    // Approximate left/right cloud bounds at altitude sy
    let sx0 = max(15, 110 - 95 * sin(hNorm * 165));
    let sx1 = min(1165, 1020 + 110 * sin((1 - hNorm) * 140));
    let sw = sx1 - sx0;

    blitStill(
      sx0 + dx - swellW * 0.35,
      sy + dy,
      sw + swellW,
      stepY + 4,
      sx0,
      sy,
      sw,
      stepY + 4
    );
  }

  // C. Paint soft gouache boiling cauliflower billows & lilac shadow pockets swelling over the lifted cloud
  const boilPuffs = [
    // Summit dome boiling crowns
    { x: 445, y: 165, r: 62, vx: 38, vy: -32, col: "#ffffff", shadow: "#8472a8", seed: 3101 },
    { x: 540, y: 125, r: 72, vx: 44, vy: -36, col: "#ffffff", shadow: "#766598", seed: 3102 },
    { x: 640, y: 158, r: 64, vx: 42, vy: -30, col: "#fffdf9", shadow: "#8472a8", seed: 3103 },
    { x: 365, y: 245, r: 58, vx: 34, vy: -26, col: "#ffffff", shadow: "#8b78ab", seed: 3104 },
    // Mid-tier cauliflower turrets boiling outward
    { x: 265, y: 390, r: 64, vx: 28, vy: -22, col: "#fffdf8", shadow: "#7f6da3", seed: 3105 },
    { x: 355, y: 315, r: 74, vx: 32, vy: -25, col: "#ffffff", shadow: "#756499", seed: 3106 },
    { x: 485, y: 270, r: 82, vx: 36, vy: -28, col: "#ffffff", shadow: "#6d5d91", seed: 3107 },
    { x: 625, y: 285, r: 78, vx: 38, vy: -24, col: "#fffdf8", shadow: "#7f6da3", seed: 3108 },
    { x: 755, y: 345, r: 68, vx: 36, vy: -20, col: "#fffaf0", shadow: "#8472a8", seed: 3109 },
    // Lower sunlit shoulders & crisp lilac underside shelves
    { x: 205, y: 525, r: 58, vx: 24, vy: -16, col: "#fffaf0", shadow: "#69588c", seed: 3110 },
    { x: 345, y: 465, r: 72, vx: 26, vy: -18, col: "#fffdf8", shadow: "#7b699e", seed: 3111 },
    { x: 515, y: 445, r: 76, vx: 30, vy: -18, col: "#fffaf0", shadow: "#6c5b91", seed: 3112 },
    { x: 675, y: 465, r: 70, vx: 32, vy: -15, col: "#fffaf0", shadow: "#7b699e", seed: 3113 },
    { x: 825, y: 505, r: 62, vx: 28, vy: -14, col: "#fff8ea", shadow: "#8572a8", seed: 3114 }
  ];

  for (let i = 0; i < boilPuffs.length; i++) {
    let bp = boilPuffs[i];
    randomSeed(bp.seed);
    noiseSeed(bp.seed);

    let px = bp.x + bp.vx * surge + sin(t * 240 + i * 37) * 5 * envIn;
    let py = bp.y + bp.vy * surge + cos(t * 220 + i * 53) * 4 * envIn;
    let pr = bp.r * (0.88 + 0.28 * surge + 0.06 * sin(t * 300 + i * 29));

    // Lilac underside shadow tuck of boiling turret
    drawCircleWash(px + 14, py + 16, pr * 0.92, bp.shadow, Math.round(165 * envIn));
    // Warm apricot-mauve transition rim
    drawCircleWash(px + 5, py + 6, pr * 0.95, "#e6cfe0", Math.round(175 * envIn));
    // Sunlit titanium white gouache billow crown
    drawCircleWash(px, py, pr, bp.col, Math.round(220 * envIn));

    // Soft gouache cloud-puff rim arc on upper-left sunlit edge
    let arcPts = [];
    for (let a = 190; a <= 325; a += 27) {
      arcPts.push([px + cos(a) * pr * 0.96, py + sin(a) * pr * 0.90]);
    }
    drawSpline(arcPts, "cloud_puff", "#ffffff", 0.72 * envIn, 0.5);
  }

  // Rolling lilac cloud-base shelves drifting across the lower anvil (y = 655..765)
  randomSeed(3190);
  noiseSeed(3190);
  let baseDx = 24 * surge;
  let baseDy = -8 * surge;
  washPoly([
    [135 + baseDx, 675 + baseDy], [410 + baseDx, 650 + baseDy],
    [710 + baseDx, 656 + baseDy], [955 + baseDx, 682 + baseDy],
    [895 + baseDx, 735 + baseDy], [580 + baseDx, 744 + baseDy],
    [240 + baseDx, 736 + baseDy]
  ], "#6c5b91", Math.round(185 * envIn), 0.15);

  washPoly([
    [210 + baseDx, 725 + baseDy], [510 + baseDx, 712 + baseDy],
    [810 + baseDx, 720 + baseDy], [855 + baseDx, 762 + baseDy],
    [540 + baseDx, 770 + baseDy], [250 + baseDx, 760 + baseDy]
  ], "#9682b8", Math.round(175 * envIn), 0.15);

  // High-altitude cirrus streaks streaming rightward across the upper cerulean sky
  const cirrusBands = [
