}

// ============================================================================
// 2. RESTORE FOREGROUND STRUCTURES OVER CLOUD & SWAY POWER LINES
// ============================================================================

function restoreForegroundOverCloud(u, t, surge, envIn) {
  // A. Restore the distant mountain horizon strip (y = 746..826) from stillImg so the mountain ridge stays crisp
  blitStill(0, 748, 665, 78, 0, 748, 665, 78);
  blitStill(1085, 748, 115, 78, 1085, 748, 115, 78);

  // B. Restore the exact Vending Machine & Recycling Bin silhouette from stillImg in vertical perspective strips
  // Front roof runs from (665, 495.0) to (965, 375.0); Side roof runs from (965, 375.0) to (1085, 465.8)
  const vmStripW = 6;
  for (let x = 663; x < 1088; x += vmStripW) {
    let xm = x + vmStripW * 0.5;
    let yRoof = xm <= 965
      ? lerp(495.0, 375.0, constrain((xm - 665) / (965 - 665), 0, 1))
      : lerp(375.0, 465.8, constrain((xm - 965) / (1085 - 965), 0, 1));
    let yTop = floor(yRoof) - 2;
    let h = 1082 - yTop;
    blitStill(x, yTop, vmStripW, h, x, yTop, vmStripW, h);
  }
  // Restore Recycling Bin silhouette (x = 1055..1154, y = 780..1030)
  blitStill(1055, 780, 100, 252, 1055, 780, 100, 252);

  // C. Redraw the 3 Utility Poles & Pole-Mounted Transformer cleanly in front of the boiling cloud
  randomSeed(19980815);
  noiseSeed(19980815);
  drawUtilityPoles();

  // D. Draw the Power Lines swaying visibly in the late-summer wind
  drawAnimatedPowerLines(u, t, surge, envIn);
}

function drawAnimatedPowerLines(u, t, surge, envIn) {
  const cables = [
    { p0: [1215, 22],  p1: [612 - 29, 102], sag: 38, w: 0.48, freq: 1.0 },
    { p0: [1215, 48],  p1: [612 - 13, 106], sag: 42, w: 0.45, freq: 1.1 },
    { p0: [1215, 76],  p1: [612 + 11, 111], sag: 45, w: 0.45, freq: 0.95 },
    { p0: [1215, 102], p1: [612 + 24, 115], sag: 48, w: 0.42, freq: 1.05 },

    { p0: [1215, 128], p1: [612 - 24, 156], sag: 36, w: 0.42, freq: 1.15 },
    { p0: [1215, 155], p1: [612 + 18, 166], sag: 40, w: 0.40, freq: 1.0 },

    { p0: [612 - 29, 102], p1: [-15, 165], sag: 52, w: 0.42, freq: 0.9 },
    { p0: [612 - 13, 106], p1: [-15, 195], sag: 56, w: 0.38, freq: 1.05 },
    { p0: [612 + 11, 111], p1: [-15, 228], sag: 60, w: 0.38, freq: 1.15 },

    { p0: [612 - 24, 156], p1: [345 - 10, 614], sag: 44, w: 0.36, freq: 1.2 },
    { p0: [612 + 18, 166], p1: [345 + 9,  618], sag: 48, w: 0.35, freq: 1.1 },
    { p0: [612,      215], p1: [345,      636], sag: 38, w: 0.38, freq: 1.0 },

    { p0: [345 - 10, 614], p1: [255 - 5, 742], sag: 16, w: 0.28, freq: 1.3 },
    { p0: [345 + 9,  618], p1: [255 + 4, 744], sag: 18, w: 0.28, freq: 1.25 },

    { p0: [612 + 8, 295],  p1: [1052, 430],    sag: 34, w: 0.44, freq: 1.1 }
  ];

  for (let idx = 0; idx < cables.length; idx++) {
    let c = cables[idx];
    randomSeed(9100 + idx * 17);
    noiseSeed(9100 + idx * 17);

    // Wind-driven catenary sway & transverse wave
    let sagWave = (6.5 * sin(t * 340 * c.freq + idx * 42) + 4.5 * surge) * envIn;
    let latWave = 4.0 * cos(t * 280 * c.freq + idx * 29) * envIn;

    let pts = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let s = i / steps;
      let envCat = 4 * s * (1 - s);
      let harm = sin(s * 360) * 2.5 * sin(t * 420 + idx * 55) * envIn;
      let x = lerp(c.p0[0], c.p1[0], s) + envCat * latWave;
      let y = lerp(c.p0[1], c.p1[1], s) + envCat * (c.sag + sagWave) + harm;
      pts.push([x, y]);
    }
    drawSpline(pts, "fine_liner", "#241f30", c.w, 0.35);
    if (c.w >= 0.40) {
      let hiPts = pts.map(p => [p[0], p[1] - 0.8]);
      drawSpline(hiPts, "fine_liner", "#857396", c.w * 0.45, 0.35);
    }
  }
}

// ============================================================================
// 3. WHOLE-SURFACE FLOODED RICE PADDY RIPPLING & SLOSHING
// ============================================================================

function drawAnimatedPaddyFullSurface(u, t, surge, envIn) {
  // A. Slosh and ripple the entire flooded paddy reflection from stillImg (y = 826..1200)
  const stripH = 7;
  for (let y = 826; y < 1200; y += stripH) {
    let depthNorm = (y - Y_HORIZON) / (1200 - Y_HORIZON); // 0 at horizon, 1 at bottom
    let dikeX = 212 + depthNorm * 253;

    // Bold travelling sine-wave slosh across the whole water surface (up to ±22px in foreground)
    let wavePhase = pow(depthNorm, 0.55) * 720 - t * 640;
    let dx = sin(wavePhase) * (4.5 + 18.0 * depthNorm) * envIn + (6.0 * depthNorm * surge);
    let dy = cos(wavePhase * 0.85) * (1.2 + 3.5 * depthNorm) * envIn;

    let w = max(10, dikeX - 4);
    let sx = constrain(-dx, 0, 28);
    let dw = max(8, w - max(0, dx));
    blitStill(max(0, dx), y + dy, dw, stripH + 1, sx, y, dw, stripH + 1);
  }

  // B. Bold gouache & fine-pen water reflection bands sweeping across the entire paddy surface
  const numWaveBands = 20;
  for (let i = 0; i < numWaveBands; i++) {
    randomSeed(4100 + i * 19);
    noiseSeed(4100 + i * 19);

    // Band travels toward the foreground with perspective acceleration
    let baseProg = ((i / numWaveBands) + t * 0.42) % 1.0;
    let depth = pow(baseProg, 1.55);
    let y = Y_HORIZON + 6 + depth * (1196 - Y_HORIZON - 6);
    let dikeX = 210 + depth * 250;

    let bandH = (2.2 + depth * 7.5) * envIn;
    let x0 = (i % 2 === 0) ? 0 : 35 * (1 - depth);
    let x1 = dikeX - 6;

    if (x1 - x0 > 20) {
      let inCloudZone = (y > 875 && y < 1165 && i % 3 !== 0);
      let bandCol = inCloudZone
        ? (i % 2 === 0 ? "#fff9eb" : "#8b79ab")
        : (i % 2 === 0 ? "#6eb4d9" : "#256496");
      let op = Math.round((130 + 75 * sin(baseProg * 180)) * envIn);

      // Painted horizontal gouache water-ripple ribbon
      washPoly([
        [x0, y - bandH * 0.5],
        [x1, y - bandH * 0.35],
        [x1, y + bandH * 0.5],
        [x0, y + bandH * 0.35]
      ], bandCol, op);

      // Crisp sunlit technical-pen crest line along the wave
      drawLine(x0, y - bandH * 0.4, x1, y - bandH * 0.3, "fine_liner", "#ffffff", (0.35 + depth * 0.45) * envIn);
    }
  }

  // C. Large expanding concentric ripple rings across the paddy water surface
  const rippleCenters = [
    { u0: 0.02, cx: 165, cy: 1065, maxR: 215, seed: 4201 },
    { u0: 0.10, cx: 245, cy: 965,  maxR: 175, seed: 4202 },
    { u0: 0.22, cx: 135, cy: 1135, maxR: 225, seed: 4203 },
    { u0: 0.34, cx: 285, cy: 1020, maxR: 185, seed: 4204 }
  ];

  for (let rc of rippleCenters) {
    if (u <= rc.u0) continue;
    let age = (u - rc.u0) / (1.0 - rc.u0);

    for (let ring = 0; ring < 4; ring++) {
      let rAge = age - ring * 0.12;
      if (rAge <= 0 || rAge >= 1.0) continue;

      let easeR = 1 - pow(1 - rAge, 1.85);
      let rx = 12 + easeR * rc.maxR;
      let ry = rx * 0.32;
      let fade = sin(constrain(rAge * 1.1, 0, 1) * 180) * envIn;
      let w = (0.78 - ring * 0.14) * fade;

      if (w > 0.08) {
        drawWaterRingArc(rc.cx, rc.cy, rx, ry, -170, -10, "#ffffff", w, rc.seed + ring * 23);
        drawWaterRingArc(rc.cx, rc.cy, rx, ry, 10, 170, "#ffffff", w * 0.95, rc.seed + ring * 29);
        drawWaterRingArc(rc.cx, rc.cy + 2.5, rx * 0.94, ry * 0.94, -160, 160, "#1d5585", w * 0.85, rc.seed + ring * 31);
      }
    }
  }

  // D. Redraw the perspective rows of young rice seedlings swaying boldly in the wind over the rippling water
  drawAnimatedRiceRows(u, t, surge, envIn);

  // E. Restore the crisp concrete paddy dike wall & curb edge so the water ripples stay cleanly inside the paddy basin
  const dikeWall = [[212, Y_HORIZON], [224, Y_HORIZON], [515, 1210], [465, 1210]];
  washPoly(dikeWall, "#7c7387", 245);
  const mossStrip = [[212, Y_HORIZON], [216, Y_HORIZON], [482, 1210], [465, 1210]];
  washPoly(mossStrip, "#526939", 225);
  drawLine(212, Y_HORIZON, 465, 1210, "fine_liner", "#2e3d23", 0.48);
  const dikeTop = [[224, Y_HORIZON], [238, Y_HORIZON], [575, 1210], [515, 1210]];
  washPoly(dikeTop, "#e8d9c3", 250);
  drawLine(224, Y_HORIZON, 515, 1210, "fine_liner", "#fff8eb", 0.5);
  drawLine(238, Y_HORIZON, 575, 1210, "fine_liner", "#9e8f80", 0.45);
}

function drawWaterRingArc(cx, cy, rx, ry, aStart, aEnd, col, weight, seed) {
  randomSeed(seed);
  noiseSeed(seed);
  let pts = [];
  let steps = 16;
  for (let i = 0; i <= steps; i++) {
    let ang = lerp(aStart, aEnd, i / steps);
    let px = cx + cos(ang) * rx;
    let py = cy + sin(ang) * ry;
    let dikeX = 212 + ((py - Y_HORIZON) / (1200 - Y_HORIZON)) * 252;
    if (px > -10 && px < dikeX - 4 && py > Y_HORIZON + 3 && py < 1205) {
      pts.push([px, py]);
    }
  }
  if (pts.length >= 3) {
    drawSpline(pts, "fine_liner", col, weight, 0.4);
  }
}

function drawAnimatedRiceRows(u, t, surge, envIn) {
  const vpX = 165;
  const vpY = Y_HORIZON;
  const rowBottomXs = [-520, -360, -210, -75, 50, 165, 270, 368, 455];

  for (let r = 0; r < rowBottomXs.length; r++) {
    let bx = rowBottomXs[r];
    let steps = 26;
    for (let i = 3; i < steps; i++) {
      let pNorm = pow(i / steps, 1.85);
      let py = vpY + (1205 - vpY) * pNorm;
      let px = vpX + (bx - vpX) * pNorm;

      let dikeX = 212 + ((py - Y_HORIZON) / (1200 - Y_HORIZON)) * 252;
      if (px < -15 || px > dikeX - 8) continue;

      let seed = 5000 + r * 100 + i;
      randomSeed(seed);
      noiseSeed(seed);

      let scale = 0.24 + pNorm * 1.35;
      let blades = 3 + floor(pNorm * 4);

      // Strong travelling wind wave bending the rice blades rightward
      let windBend = (7.5 + 9.5 * sin(px * 0.012 - t * 420 + py * 0.008) + 6.0 * surge) * scale * envIn;

      // Bright water meniscus ring oscillating at base of clump
      let menW = (6 + 2.5 * sin(t * 480 + i * 35)) * scale;
      drawLine(px - menW, py + 1, px + menW, py + 1, "fine_liner", "#ffffff", 0.35 * scale);

      // Sunlit emerald & lime-gold rice blades bending in the gust
      for (let b = 0; b < blades; b++) {
        let ang = -42 + (b / max(1, blades - 1)) * 84;
        let len = (14 + (b % 2) * 6) * scale;
        let tipX = px + sin(ang) * len * 0.72 + windBend;
        let tipY = py - cos(ang) * len + abs(windBend) * 0.24;
        let midX = (px + tipX) * 0.5 + windBend * 0.38;
        let midY = (py + tipY) * 0.5 - 2.5 * scale;

        let bladeCol = b % 3 === 0 ? "#55802b" : (b % 3 === 1 ? "#84b037" : "#c4e352");
        drawSpline([[px, py], [midX, midY], [tipX, tipY]], "fine_liner", bladeCol, (0.40 + pNorm * 0.36), 0.35);
      }
    }
  }
}

// ============================================================================
// 4. BOLD VENDING MACHINE ANIMATION: BLINKING DISPLAY & 27 BUTTON LIGHTS,
//    SWEEPING GLASS GLARE & LARGE RED COLA CAN DROPPING INTO THE CHUTE
// ============================================================================

function drawAnimatedVendingMachineBold(u, t, surge, envIn) {
  const frontP = makePanel(665, 495.0, 1008.3, 965, VP1.x, VP1.y, 0.86);

  // --------------------------------------------------------------------------
  // A. SWEEPING SKY/CLOUD REFLECTION & FLUORESCENT PULSE ON THE DISPLAY WINDOW
  // --------------------------------------------------------------------------
  randomSeed(6010);
  noiseSeed(6010);

  // Top interior fluorescent light tube pulsing brightly inside the display case
  let tubePulse = 0.5 + 0.5 * sin(t * 720);
  washPoly(panelQuad(frontP, 0.068, 0.082, 0.885, 0.104), "#ffffff", Math.round((140 + 105 * tubePulse) * envIn));
  washPoly(panelQuad(frontP, 0.068, 0.100, 0.885, 0.135), "#d4f0ff", Math.round(95 * tubePulse * envIn));

  // Bold diagonal cloud-glare ribbons sliding across the entire glass window pane as the cumulus boils overhead
  let glareShift = 0.24 * surge;
  let g1s0 = constrain(0.08 + glareShift, 0.065, 0.88);
  let g1s1 = constrain(0.32 + glareShift, 0.065, 0.91);
  let g1b0 = constrain(0.065 + glareShift * 0.7, 0.065, 0.85);
  let g1b1 = constrain(0.18 + glareShift * 0.7, 0.065, 0.90);

  washPoly([
    panelPt(frontP, g1s0, 0.084),
    panelPt(frontP, g1s1, 0.084),
    panelPt(frontP, g1b1, 0.536),
    panelPt(frontP, g1b0, 0.536)
  ], "#ffffff", Math.round(92 * envIn));

  let g2s0 = constrain(0.48 + glareShift * 0.85, 0.07, 0.90);
  let g2s1 = constrain(0.68 + glareShift * 0.85, 0.07, 0.92);
  let g2b0 = constrain(0.28 + glareShift * 0.85, 0.07, 0.88);
  let g2b1 = constrain(0.46 + glareShift * 0.85, 0.07, 0.92);

  washPoly([
    panelPt(frontP, g2s0, 0.084),
    panelPt(frontP, g2s1, 0.084),
    panelPt(frontP, g2b1, 0.536),
    panelPt(frontP, g2b0, 0.536)
  ], "#bfe6ff", Math.round(80 * envIn));

  // --------------------------------------------------------------------------
  // B. ALL 27 SELECTION BUTTON LIGHTS BLINKING ON & OFF IN A BOLD CHASE CASCADE
  // --------------------------------------------------------------------------
  const shelfBounds = [
    { tTop: 0.088, tBot: 0.228 },
    { tTop: 0.242, tBot: 0.378 },
    { tTop: 0.392, tBot: 0.525 }
  ];
  const sStart = 0.072;
  const sEnd = 0.862;
  const numSlots = 9;
  const slotW = (sEnd - sStart) / numSlots;

  // Fast 12Hz arcade chase index + whole-bank blink toggle
  let stepTick = floor(frameCount * 0.85);

  for (let sh = 0; sh < 3; sh++) {
    let sb = shelfBounds[sh];
    let tCanBottom = sb.tTop + (sb.tBot - sb.tTop) * 0.72;
    let tRailBottom = sb.tTop + (sb.tBot - sb.tTop) * 0.85;
    let tBtnBottom = sb.tBot;

    for (let i = 0; i < numSlots; i++) {
      randomSeed(6100 + sh * 20 + i);
      noiseSeed(6100 + sh * 20 + i);

      let s0 = sStart + i * slotW + slotW * 0.09;
      let s1 = sStart + (i + 1) * slotW - slotW * 0.09;
      let sMid = (s0 + s1) * 0.5;

      let btnQuad = panelQuad(frontP, s0 + 0.001, tRailBottom + 0.002, s1 - 0.001, tBtnBottom - 0.001);
      let ledPt = panelPt(frontP, sMid, (tRailBottom + tBtnBottom) * 0.5);

      // Determine bold ON/OFF blink state for each button
      let isHeroCola = (sh === 1 && i === 0);
      let isSoldOutSlot = (sh === 1 && i === 2) || (sh === 2 && i === 6) || ((i + sh + stepTick) % 5 === 0);
      let isLit = isHeroCola ? (frameCount % 3 !== 0) : ((i + sh * 2 + stepTick) % 2 === 0);

      if (isLit) {
        let glowCol = isHeroCola ? "#ffae24" : (isSoldOutSlot ? "#ff2e24" : "#2eff66");
        let coreCol = isHeroCola ? "#fffdf0" : (isSoldOutSlot ? "#ffd4cf" : "#e6ffed");

        // Full button face lights up with a vivid neon glow
        washPoly(btnQuad, glowCol, Math.round(225 * envIn));
        // Soft outer light halo on the shelf rail around the lit button
        drawCircleWash(ledPt[0], ledPt[1], 7.2 * envIn, glowCol, Math.round(135 * envIn));
        // Bright white incandescent/LED center core
        drawCircleWash(ledPt[0], ledPt[1], 3.2 * envIn, coreCol, Math.round(250 * envIn));
      } else {
        // Crisp dark unlit button state so the ON/OFF blinking has maximum contrast
        washPoly(btnQuad, "#15141c", Math.round(245 * envIn));
        drawCircleWash(ledPt[0], ledPt[1], 1.6, "#2e3040", Math.round(220 * envIn));
      }
    }
  }

  // --------------------------------------------------------------------------
  // C. DIGITAL 7-SEGMENT LED DISPLAY & BILL VALIDATOR BLINKING ON & OFF
  // --------------------------------------------------------------------------
  randomSeed(6180);
  noiseSeed(6180);
  const ledWin = panelQuad(frontP, 0.675, 0.590, 0.815, 0.622);
  let dispBlinkOn = (frameCount % 4 < 2);

  if (dispBlinkOn) {
    // Glowing red-orange digital readout halo + bright segments ("888" / "000" / "130")
    washPoly(panelQuad(frontP, 0.668, 0.585, 0.822, 0.627), "#ff441f", Math.round(145 * envIn));
    washPoly(ledWin, "#2b0d0a", 250);
    let dispText = u < 0.22 ? "130" : (frameCount % 8 < 4 ? "888" : "000");
    drawPanelText(frontP, dispText, 0.692, 0.594, 0.804, 0.618, "#ff6b3d", 0.62);
    drawPanelText(frontP, dispText, 0.692, 0.594, 0.804, 0.618, "#fff2bd", 0.32);
  } else {
    // Dark unlit LED window on alternate blink frames
    washPoly(ledWin, "#121118", 250);
    drawPanelText(frontP, "000", 0.692, 0.594, 0.804, 0.618, "#4a201c", 0.35);
  }

  // Blinking green/amber runway strip on the 1000-Yen bill validator bezel
  let billBlink = (frameCount % 4 >= 2);
  washPoly(
    panelQuad(frontP, 0.690, 0.642, 0.820, 0.655),
    billBlink ? "#4dff6e" : "#16381c",
    Math.round(245 * envIn)
  );

  // Promo "ICE" panel backlight flash
  if (dispBlinkOn) {
    washPoly(panelQuad(frontP, 0.068, 0.580, 0.596, 0.656), "#8ce0ff", Math.round(95 * envIn));
    drawPanelText(frontP, "ICE", 0.10, 0.592, 0.36, 0.638, "#ffffff", 0.62);
  }

  // --------------------------------------------------------------------------
  // D. CONDENSATION STREAMS RUNNING DOWN THE CHILLED GLASS WINDOW
  // --------------------------------------------------------------------------
  const trickleDrops = [
    { s: 0.14, t0: 0.18, speed: 0.28, seed: 6301 },
    { s: 0.26, t0: 0.22, speed: 0.25, seed: 6302 },
    { s: 0.39, t0: 0.16, speed: 0.30, seed: 6303 },
    { s: 0.52, t0: 0.24, speed: 0.26, seed: 6304 },
    { s: 0.66, t0: 0.19, speed: 0.29, seed: 6305 },
    { s: 0.79, t0: 0.21, speed: 0.27, seed: 6306 },
    { s: 0.87, t0: 0.25, speed: 0.24, seed: 6307 }
  ];

  for (let td of trickleDrops) {
    randomSeed(td.seed);
    noiseSeed(td.seed);
    let curT = min(0.534, td.t0 + td.speed * surge);
    let wigS = sin(u * 360 * 3 + td.seed) * 0.003;
    let pStart = panelPt(frontP, td.s, td.t0);
    let pMid = panelPt(frontP, td.s + wigS, (td.t0 + curT) * 0.5);
    let pCur = panelPt(frontP, td.s - wigS * 0.5, curT);

    drawSpline([pStart, pMid, pCur], "fine_liner", "#ffffff", 0.48 * envIn, 0.3);
    drawCircleWash(pCur[0] - 0.8, pCur[1] - 1.0, 3.0 * envIn, "#2c4c66", Math.round(180 * envIn));
    drawCircleWash(pCur[0] + 0.5, pCur[1] + 0.8, 2.8 * envIn, "#ffffff", Math.round(250 * envIn));
  }

  // --------------------------------------------------------------------------
  // E. PICKUP CHUTE: SMOKED-ACRYLIC FLAP SWINGS WIDE OPEN & LARGE RED COLA CAN DROPS IN
  // --------------------------------------------------------------------------
  randomSeed(6400);
  noiseSeed(6400);

  // 1. Pitch-black recessed interior cavity of the retrieval chute (high contrast for the red can!)
  washPoly(panelQuad(frontP, 0.085, 0.808, 0.775, 0.914), "#0d0c14", 250);
  // Sunlit brushed-steel lower chute tray floor
  washPoly(panelQuad(frontP, 0.088, 0.882, 0.772, 0.914), "#4a5264", 245);
  let trayLipL = panelPt(frontP, 0.088, 0.912);
  let trayLipR = panelPt(frontP, 0.772, 0.912);
  drawLine(trayLipL[0], trayLipL[1], trayLipR[0], trayLipR[1], "fine_liner", "#ffffff", 0.65 * envIn);

  // 2. Fast, bold trajectory of the large red COLA can dropping into the chute
  // Starts dropping immediately at Frame 2 (u = 0.02), hits bottom tray by Frame 9 (u = 0.17),
  // bounces high and visibly (Frames 9..20), then rolls along the front lip (Frames 20..48)
  let dropPhase = constrain((u - 0.01) / 0.42, 0, 1);
  let dropNorm;
  let tiltT = 0;

  if (dropPhase < 0.38) {
    // Fast plunge from top of chute throat into the basin
    let p = dropPhase / 0.38;
    dropNorm = p * p;
    tiltT = 0.012 * (1 - p);
  } else if (dropPhase < 0.72) {
    // Big unmistakable metallic bounce inside the open chute
    let p = (dropPhase - 0.38) / 0.34;
    dropNorm = 1.0 - 0.42 * sin(p * 180);
    tiltT = -0.010 * sin(p * 180);
  } else {
    // Second settle bounce
    let p = (dropPhase - 0.72) / 0.28;
    dropNorm = 1.0 - 0.14 * sin(p * 180);
    tiltT = 0.004 * sin(p * 180);
  }

  // Horizontal roll toward the center-right of the chute tray
  let rollS = 0.11 * pow(constrain(u * 1.4, 0, 1), 0.75);
  let canS0 = 0.22 + rollS;
  let canS1 = 0.52 + rollS; // Large 30%-panel-wide (~78px) Cola can!
  let canT0 = lerp(0.796, 0.842, dropNorm);
  let canT1 = canT0 + 0.062; // ~36px tall cylinder

  // Impact flash on the steel tray when the can hits at dropPhase ≈ 0.38
  if (dropPhase > 0.30 && dropPhase < 0.52) {
    let flashEnv = sin(((dropPhase - 0.30) / 0.22) * 180);
    let impPt = panelPt(frontP, (canS0 + canS1) * 0.5, 0.898);
    drawCircleWash(impPt[0], impPt[1], 22 * flashEnv, "#ffffff", Math.round(210 * flashEnv));
  }

  // Draw the vended red COLA can inside the chute
  let cTL = panelPt(frontP, canS0, max(0.808, canT0 - tiltT));
  let cTR = panelPt(frontP, canS1, max(0.808, canT0 + tiltT));
  let cBR = panelPt(frontP, canS1, min(0.913, canT1 + tiltT));
  let cBL = panelPt(frontP, canS0, min(0.913, canT1 - tiltT));

  // Deep contact shadow under the can
  washPoly(panelQuad(frontP, canS0 - 0.015, 0.892, canS1 + 0.015, 0.913), "#07060a", 245);

  // Vivid crimson-red aluminum can body
  washPoly([cTL, cTR, cBR, cBL], "#e62e22", 250);

  // Bright sunlit cylindrical highlight band along the upper face of the can
  let hTL = panelPt(frontP, canS0 + 0.008, max(0.810, canT0 + 0.010 - tiltT));
  let hTR = panelPt(frontP, canS1 - 0.008, max(0.810, canT0 + 0.010 + tiltT));
  let hBR = panelPt(frontP, canS1 - 0.008, max(0.814, canT0 + 0.024 + tiltT));
  let hBL = panelPt(frontP, canS0 + 0.008, max(0.814, canT0 + 0.024 - tiltT));
  washPoly([hTL, hTR, hBR, hBL], "#ff9e8a", 220);
  drawLine(hTL[0], hTL[1], hTR[0], hTR[1], "fine_liner", "#ffffff", 0.75);

  // Bold white dynamic Cola ribbon wave & legible "COLA" lettering on the vended can
  let wPts = [
    panelPt(frontP, canS0 + 0.02, max(0.812, canT0 + 0.028 - tiltT * 0.5)),
    panelPt(frontP, (canS0 + canS1) * 0.5, max(0.812, canT0 + 0.016)),
    panelPt(frontP, canS1 - 0.02, max(0.812, canT0 + 0.032 + tiltT * 0.5)),
    panelPt(frontP, canS1 - 0.02, min(0.910, canT0 + 0.044 + tiltT * 0.5)),
    panelPt(frontP, (canS0 + canS1) * 0.5, min(0.910, canT0 + 0.028)),
    panelPt(frontP, canS0 + 0.02, min(0.910, canT0 + 0.040 - tiltT * 0.5))
  ];
  washPoly(wPts, "#ffffff", 250);
  drawPanelText(
    frontP, "COLA",
    canS0 + 0.04, max(0.812, canT0 + 0.020),
    canS1 - 0.04, min(0.908, canT0 + 0.052),
    "#ffffff", 0.45
  );

  // Gleaming silver aluminum left & right end rims of the horizontal can
  washPoly([
    cTL,
    panelPt(frontP, canS0 + 0.016, max(0.808, canT0 - tiltT)),
    panelPt(frontP, canS0 + 0.016, min(0.913, canT1 - tiltT)),
    cBL
  ], "#f0f6fc", 250);
  washPoly([
    panelPt(frontP, canS1 - 0.016, max(0.808, canT0 + tiltT)),
    cTR,
    cBR,
    panelPt(frontP, canS1 - 0.016, min(0.913, canT1 + tiltT))
  ], "#c8d4e0", 250);
  strokePoly([cTL, cTR, cBR, cBL], "fine_liner", "#1a1822", 0.45, true);

  // 3. Smoked-Acrylic Chute Push-Flap hinged at t = 0.812, pushed wide open above the can
  // and catching a bright sky-blue & white reflection flash as it swings
  let flapOpen = 0.62 * envIn + 0.22 * sin(t * 520) * exp(-u * 2.2) * envIn;
  let flapBotT = 0.892 - flapOpen * 0.058;
  let kickX = -flapOpen * 12;
  let kickY = -flapOpen * 4.5;

  let fTL = panelPt(frontP, 0.095, 0.812);
  let fTR = panelPt(frontP, 0.765, 0.812);
  let fBR0 = panelPt(frontP, 0.765, flapBotT);
  let fBL0 = panelPt(frontP, 0.095, flapBotT);
  let fBR = [fBR0[0] + kickX, fBR0[1] + kickY];
  let fBL = [fBL0[0] + kickX, fBL0[1] + kickY];

  washPoly([fTL, fTR, fBR, fBL], "#5a7696", Math.round(195 * envIn));
  // Bright sunlit specular highlight band across the tilted acrylic flap
  washPoly([
    fTL, fTR,
    [(fTR[0] + fBR[0]) * 0.5, (fTR[1] + fBR[1]) * 0.5],
    [(fTL[0] + fBL[0]) * 0.5, (fTL[1] + fBL[1]) * 0.5]
  ], "#d9f0ff", Math.round(210 * envIn));
  drawLine(fBL[0], fBL[1], fBR[0], fBR[1], "fine_liner", "#ffffff", 0.72 * envIn);
}

// ============================================================================
// 5. FOREGROUND WIND GUST, STREAMING DANDELION SEEDS & LARGE FAST DRAGONFLIES
// ============================================================================

function drawAnimatedForegroundWindAndDragonflies(u, t, surge, envIn) {
  // A. Roadside weed clusters & golden foxtails bending boldly in the summer wind gust
  const gustClusters = [
    { cx: 495, cy: 1135, scale: 1.38, count: 14, seed: 7001 },
    { cx: 555, cy: 1175, scale: 1.48, count: 16, seed: 7002 },
    { cx: 645, cy: 1020, scale: 1.08, count: 12, seed: 7003 },
    { cx: 685, cy: 1042, scale: 0.94, count: 10, seed: 7004 },
    { cx: 390, cy: 955,  scale: 0.76, count: 9,  seed: 7005 },
    { cx: 580, cy: 915,  scale: 0.88, count: 10, seed: 7006 }
  ];

  for (let gc of gustClusters) {
    randomSeed(gc.seed);
    noiseSeed(gc.seed);

    let gustAng = (18 + 14 * sin(t * 360 + gc.cx * 0.02) + 10 * surge) * envIn;
    for (let i = 0; i < gc.count; i++) {
      let baseAng = -45 + (i / max(1, gc.count - 1)) * 95 + gustAng;
      let len = (22 + (i % 3) * 11) * gc.scale;
      let tx = gc.cx + sin(baseAng) * len * 0.85;
      let ty = gc.cy - cos(baseAng) * len;
      let mx = (gc.cx + tx) * 0.5 + sin(baseAng) * 5 * gc.scale;
      let my = (gc.cy + ty) * 0.5 - 4 * gc.scale;

      let col = i % 2 === 0 ? "#84b037" : "#d2e655";
      drawSpline([[gc.cx, gc.cy], [mx, my], [tx, ty]], "fine_liner", col, 0.48 * gc.scale * envIn, 0.4);

      if (i % 3 === 1) {
        let fx = tx + sin(baseAng + 10) * 10 * gc.scale;
        let fy = ty - cos(baseAng + 10) * 6 * gc.scale;
        drawLine(tx, ty, fx, fy, "gouache_flat", "#e3ed72", 0.65 * gc.scale * envIn);
      }
    }
  }

  // B. Wind-borne dandelion pappus seeds streaming fast across the road & machine
  const seeds = [
    { x0: 482, y0: 1098, vx: 320, vy: -185, scale: 1.45, seed: 7101 },
    { x0: 508, y0: 1085, vx: 365, vy: -215, scale: 1.35, seed: 7102 },
    { x0: 525, y0: 1105, vx: 295, vy: -160, scale: 1.50, seed: 7103 },
    { x0: 542, y0: 1122, vx: 340, vy: -195, scale: 1.40, seed: 7104 },
    { x0: 632, y0: 995,  vx: 380, vy: -210, scale: 1.25, seed: 7105 },
    { x0: 648, y0: 988,  vx: 350, vy: -240, scale: 1.20, seed: 7106 },
    { x0: 662, y0: 1002, vx: 410, vy: -175, scale: 1.30, seed: 7107 },
    { x0: 390, y0: 955,  vx: 360, vy: -205, scale: 1.15, seed: 7108 },
    { x0: 335, y0: 905,  vx: 390, vy: -225, scale: 1.10, seed: 7109 },
    { x0: 495, y0: 1135, vx: 420, vy: -260, scale: 1.55, seed: 7110 },
    { x0: 555, y0: 1175, vx: 445, vy: -245, scale: 1.60, seed: 7111 },
    { x0: 580, y0: 915,  vx: 370, vy: -190, scale: 1.18, seed: 7112 }
  ];

  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];
    randomSeed(s.seed);
    noiseSeed(s.seed);

    let sx = s.x0 + s.vx * surge + cos(t * 240 + i * 37) * 9 * envIn;
    let sy = s.y0 + s.vy * surge + sin(t * 280 + i * 53) * 11 * envIn;
    let tilt = 18 + sin(t * 260 + i * 41) * 22;
    let sc = s.scale * envIn;

    push();
    translate(sx, sy);
    rotate(tilt);

    let stemLen = 11 * sc;
    drawCircleWash(0, stemLen * 0.55, 1.8 * sc, "#6e4e32", Math.round(240 * envIn));
    drawLine(0, stemLen * 0.5, 0, -stemLen * 0.45, "fine_liner", "#e6dac6", 0.36 * sc);

    let crownY = -stemLen * 0.45;
    for (let r = 0; r < 7; r++) {
      let rAng = -70 + (r / 6) * 140;
      let rLen = (9 + (r % 2) * 2.5) * sc;
      drawLine(0, crownY, sin(rAng) * rLen, crownY - cos(rAng) * rLen * 0.75, "fine_liner", "#ffffff", 0.34 * sc);
    }
    drawCircleWash(0, crownY - 2 * sc, 4.2 * sc, "#ffffff", Math.round(205 * envIn));
    pop();
  }

  // C. TWO LARGE, FAST FOREGROUND RED DRAGONFLIES (AKIAKANE) SWEEPING ACROSS THE FRAME
  const dt = 0.008;
  for (let d = 1; d >= 0; d--) {
    let pos = getFastDragonflyPos(d, surge, u);
    let posNext = getFastDragonflyPos(d, pow(min(1, u + dt), 0.72), min(1, u + dt));
    let posPrev = getFastDragonflyPos(d, pow(max(0, u - dt), 0.72), max(0, u - dt));

    let heading = atan2(posNext[1] - posPrev[1], posNext[0] - posPrev[0]);

    // Large, unmistakable foreground wingspan (~235px for Hero Dragonfly 0, ~150px for Companion 1)
    let baseScale = (d === 0)
      ? lerp(2.55, 1.75, u)
      : lerp(1.65, 1.18, u);
    let sc = baseScale * envIn;

    // 1. Bold inverted water reflection when over the flooded rice paddy
    let reflY = pos[1] + 55 + max(0, 1020 - pos[1]) * 0.25;
    let dikeX = 212 + ((reflY - Y_HORIZON) / (1200 - Y_HORIZON)) * 252;
    if (pos[0] > 0 && pos[0] < dikeX - 8 && reflY > Y_HORIZON + 10 && reflY < 1195) {
      drawDragonflyWaterReflection(pos[0], reflY, heading, sc * 0.72, u, 8100 + d * 100);
    }

    // 2. Specular reflection on the vending machine display window when passing in front
    if (pos[0] > 665 && pos[0] < 960 && pos[1] > 420 && pos[1] < 800) {
      drawDragonflyGlassReflection(pos[0] - 36, pos[1] - 22, heading, sc * 0.58, 8300 + d * 50);
    }

    // 3. Paint the large hyperreal red dragonfly with rapid 4-wing beats
    drawHyperrealDragonfly(pos[0], pos[1], heading, sc, u, d, 8500 + d * 200);
  }
}

function getFastDragonflyPos(which, surge, u) {
  if (which === 0) {
    // HERO FOREGROUND DRAGONFLY:
    // Already well inside lower-left paddy by Frame 2-4, sweeps fast across dike & vending machine
    let p0 = [-20, 1055];
    let p1 = [295, 965];
    let p2 = [645, 760];
    let p3 = [935, 535];
    let p4 = [1190, 340];
    let pos = evalQuarticBezier(p0, p1, p2, p3, p4, surge);
    pos[1] += sin(u * 360 * 1.6) * 22 * sin(u * 180);
    return pos;
  } else {
    // SECOND FAST DRAGONFLY:
    // Sweeps from mid-paddy across the utility pole and up in front of the boiling cumulus cloud
    let p0 = [-15, 920];
    let p1 = [255, 865];
    let p2 = [515, 640];
    let p3 = [755, 410];
    let p4 = [1045, 225];
    let pos = evalQuarticBezier(p0, p1, p2, p3, p4, surge);
    pos[0] += sin(u * 360 * 1.3) * 18 * sin(u * 180);
    pos[1] += cos(u * 360 * 1.3) * 16 * sin(u * 180);
    return pos;
  }
}

function evalQuarticBezier(p0, p1, p2, p3, p4, t) {
  let it = 1 - t;
  let b0 = it * it * it * it;
  let b1 = 4 * it * it * it * t;
  let b2 = 6 * it * it * t * t;
  let b3 = 4 * it * t * t * t;
  let b4 = t * t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0] + b4 * p4[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1] + b4 * p4[1]
  ];
}

function drawDragonflyWaterReflection(rx, ry, heading, sc, u, seed) {
  randomSeed(seed);
  noiseSeed(seed);

  push();
  translate(rx, ry);
  scale(1, -0.55);
  rotate(heading);

  let flap = sin(u * 360 * 14 + seed) * 26;
  for (let side of [-1, 1]) {
    let wAng = side * (78 + flap * 0.5);
    drawLine(4 * sc, 0, cos(wAng) * 38 * sc, sin(wAng) * 38 * sc, "gouache_flat", "#d8e9f2", 0.65 * sc);
  }
  drawLine(-30 * sc, 0, 16 * sc, 0, "gouache_flat", "#b82830", 0.72 * sc);
  pop();

  drawLine(rx - 22 * sc, ry, rx + 22 * sc, ry, "fine_liner", "#ffffff", 0.42 * sc);
}

function drawDragonflyGlassReflection(gx, gy, heading, sc, seed) {
  randomSeed(seed);
  noiseSeed(seed);

  push();
  translate(gx, gy);
  rotate(heading);
  drawLine(-24 * sc, 0, 14 * sc, 0, "gouache_flat", "#ff9488", 0.55 * sc);
  drawLine(2 * sc, -30 * sc, 2 * sc, 30 * sc, "gouache_flat", "#ffffff", 0.52 * sc);
  pop();
}

function drawHyperrealDragonfly(x, y, heading, sc, u, idx, seed) {
  randomSeed(seed);
  noiseSeed(seed);

  push();
  translate(x, y);
  rotate(heading);

  let glideMask = 0.42 + 0.58 * pow(sin(u * 360 * 2.5 + idx * 70), 2);
  let foreFlap = sin(u * 360 * 15 + idx * 45) * 30 * glideMask;
  let hindFlap = sin(u * 360 * 15 + idx * 45 - 55) * 28 * glideMask;

  // A. Four Translucent Iridescent Wings
  const wingConfigs = [
    { attachX: 2 * sc, side: -1, baseAng: -96 + hindFlap, len: 43 * sc, w: 8.8 * sc },
    { attachX: 2 * sc, side:  1, baseAng:  96 - hindFlap, len: 41 * sc, w: 8.8 * sc },
    { attachX: 8 * sc, side: -1, baseAng: -74 + foreFlap, len: 48 * sc, w: 7.0 * sc },
    { attachX: 8 * sc, side:  1, baseAng:  74 - foreFlap, len: 46 * sc, w: 7.0 * sc }
  ];

  for (let w = 0; w < wingConfigs.length; w++) {
    let wc = wingConfigs[w];
    randomSeed(seed + 10 + w * 7);
    noiseSeed(seed + 10 + w * 7);

    let ca = cos(wc.baseAng);
    let sa = sin(wc.baseAng);
    let pa = -sa * wc.side;
    let pb = ca * wc.side;

    let bx = wc.attachX;
    let by = wc.side * 2.2 * sc;
    let tx = bx + ca * wc.len;
    let ty = by + sa * wc.len;

    let pLeadMid = [bx + ca * wc.len * 0.55, by + sa * wc.len * 0.55];
    let pTip     = [tx, ty];
    let pTrail1  = [bx + ca * wc.len * 0.78 - pa * wc.w * 0.72, by + sa * wc.len * 0.78 - pb * wc.w * 0.72];
    let pTrail2  = [bx + ca * wc.len * 0.38 - pa * wc.w,        by + sa * wc.len * 0.38 - pb * wc.w];
    let wingPoly = [[bx, by], pLeadMid, pTip, pTrail1, pTrail2];

    // Motion-blur ghost wing arc
    let blurAng = wc.baseAng - wc.side * 16;
    drawLine(bx, by, bx + cos(blurAng) * wc.len * 0.92, by + sin(blurAng) * wc.len * 0.92, "gouache_flat", "#ffffff", 0.48 * sc);

    // Translucent sunlit membrane wash
    washPoly(wingPoly, wc.side < 0 ? "#fffef7" : "#dff0fa", 165, 0.15);

    // Amber wing-root tint
    washPoly([
      [bx, by],
      [bx + ca * wc.len * 0.28, by + sa * wc.len * 0.28],
      [bx + ca * wc.len * 0.25 - pa * wc.w * 0.55, by + sa * wc.len * 0.25 - pb * wc.w * 0.55]
    ], "#f5b84c", 150);

    // Dark pterostigma spot near wing tip
    drawLine(
      bx + ca * wc.len * 0.80, by + sa * wc.len * 0.80,
      bx + ca * wc.len * 0.90, by + sa * wc.len * 0.90,
      "fine_liner", "#6e2219", 0.65 * sc
    );

    // Costal leading vein & white specular rim
    drawLine(bx, by, tx, ty, "fine_liner", "#2b1c19", 0.42 * sc);
    drawLine(bx, by - 0.8, tx, ty - 0.8, "fine_liner", "#ffffff", 0.38 * sc);
    strokePoly(wingPoly, "fine_liner", "#5e4b47", 0.24 * sc, true, 0.15);
  }

  // B. Tucked Spiny Black Legs
  randomSeed(seed + 50);
  noiseSeed(seed + 50);
  for (let lg of [-1, 0, 1]) {
    let lx = (4 + lg * 3.5) * sc;
    drawLine(lx, 1.5 * sc, lx - 3 * sc, 6.5 * sc, "fine_liner", "#1e1a24", 0.32 * sc);
    drawLine(lx - 3 * sc, 6.5 * sc, lx + 1 * sc, 8.5 * sc, "fine_liner", "#1e1a24", 0.28 * sc);
  }

  // C. Scarlet-Crimson Segmented Abdomen, Thorax & Glossy Compound Eyes
  randomSeed(seed + 70);
  noiseSeed(seed + 70);

  let tailLen = 38 * sc;
  let tailTipY = sin(u * 360 * 3 + idx * 90) * 2.2 * sc;

  // Tapered scarlet abdomen polygon + sunlit highlight
  let abdPoly = [
    [0, -1.8 * sc],
    [-tailLen * 0.5, -1.3 * sc],
    [-tailLen, tailTipY - 0.8 * sc],
    [-tailLen, tailTipY + 1.0 * sc],
    [-tailLen * 0.5, 1.5 * sc],
    [0, 2.0 * sc]
  ];
  washPoly(abdPoly, "#e32e20", 250);
  drawSpline([[-tailLen * 0.92, tailTipY - 0.5 * sc], [-tailLen * 0.45, -0.9 * sc], [0, -1.0 * sc]], "fine_liner", "#ffab85", 0.48 * sc, 0.3);
  strokePoly(abdPoly, "fine_liner", "#2b1216", 0.28 * sc, true);

  for (let seg = 1; seg <= 7; seg++) {
    let sx = -tailLen * (seg / 8.0);
    let sy = lerp(0, tailTipY, seg / 8.0);
    drawLine(sx, sy - 1.6 * sc, sx, sy + 1.6 * sc, "fine_liner", "#2b1216", 0.28 * sc);
  }

  // Robust crimson-amber thorax
  let thoraxPoly = [
    [0, -3.2 * sc], [6 * sc, -4.2 * sc], [11.5 * sc, -3.0 * sc],
    [11.5 * sc, 3.0 * sc], [6 * sc, 4.2 * sc], [0, 3.2 * sc]
  ];
  washPoly(thoraxPoly, "#c93824", 250);
  washPoly([[1 * sc, -3.0 * sc], [10.5 * sc, -2.6 * sc], [10.5 * sc, 0], [1 * sc, 0]], "#f57242", 235);
  strokePoly(thoraxPoly, "fine_liner", "#2b1417", 0.32 * sc, true);

  // Compound eyes with bright afternoon sun pinpoint
  drawCircleWash(13.8 * sc, -2.0 * sc, 3.5 * sc, "#4f1419", 250);
  drawCircleWash(13.8 * sc,  2.0 * sc, 3.5 * sc, "#330d12", 250);
  drawCircleWash(13.2 * sc,  0.0,      3.7 * sc, "#8c1d22", 250);
  drawCircleWash(14.5 * sc, -1.8 * sc, 1.4 * sc, "#ffffff", 250);

  pop();
}

// ============================================================================
// SAFE P5.BRUSH PRIMITIVE HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
}

function washPoly(pts, col, opacity = 255, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function watercolorPoly(pts, col, opacity = 110, bleed = 0.14, tex = 0.38, border = 0.25, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts = {}, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function strokePoly(pts, brushName, col, weight = 1, closed = true, curvature = 0) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
  resetBrushState();
}

function drawLine(x1, y1, x2, y2, brushName, col, weight = 1) {
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetBrushState();
}

function drawSpline(pts, brushName, col, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.spline(pts, curvature);
  resetBrushState();
}

function drawCircleWash(x, y, r, col, opacity = 255) {
  resetBrushState();
  brush.wash(col, opacity);
  brush.circle(x, y, r, 0.03);
  resetBrushState();
}

// ============================================================================
// 2-POINT PERSPECTIVE PANEL ENGINE
// ============================================================================

function makePanel(x0, yTop0, yBot0, x1, vx, vy, depthRatio = 1.0) {
  return { x0, yTop0, yBot0, x1, vx, vy, depthRatio };
}

function panelPt(p, s, t) {
  let sp = p.depthRatio === 1.0 ? s : (s * p.depthRatio) / (1 + s * (p.depthRatio - 1));
  let x = p.x0 + (p.x1 - p.x0) * sp;
  let yAtX0 = p.yTop0 + (p.yBot0 - p.yTop0) * t;
  let y = p.vy + (yAtX0 - p.vy) * ((x - p.vx) / (p.x0 - p.vx));
  return [x, y];
}

function panelQuad(p, s0, t0, s1, t1) {
  return [
    panelPt(p, s0, t0),
    panelPt(p, s1, t0),
    panelPt(p, s1, t1),
    panelPt(p, s0, t1)
  ];
}

