    "#8f7344", 85, 0.2, 0.4, 0.2
  );

  // Distant treeline reflection along the top edge of the paddy
  washPoly([[-10, 825], [225, 825], [238, 844], [-10, 846]], "#49633e", 210);

  // 3. Fine Pen Water Ripples & Shimmering Sky Slices Across the Reflection
  for (let y = 834; y < 1195; y += 6 + (y - 825) * 0.035) {
    let maxX = 215 + ((y - Y_HORIZON) / (1200 - Y_HORIZON)) * 255;
    let segs = 3 + floor(random(3));
    for (let s = 0; s < segs; s++) {
      let x1 = random(-5, maxX - 30);
      let len = random(18, 65) * (1 + (y - 825) / 350);
      let x2 = min(maxX - 4, x1 + len);
      if (x2 <= x1 + 5) continue;

      let inCloudRefl = (x1 > 80 && x2 < 380 && y > 895 && y < 1150);
      let rippleCol = inCloudRefl
        ? (random() < 0.55 ? "#579ec7" : "#8b79ab")
        : (random() < 0.6 ? "#fff9eb" : "#256496");
      drawLine(x1, y, x2, y, "fine_liner", rippleCol, 0.32 + (y - 825) * 0.0008);
    }
  }

  // Wavy dark reflection of the distant utility poles in the paddy water
  const poleRefls = [
    { x: 255, y0: 826, y1: 915 },
    { x: 345, y0: 895, y1: 1095 }
  ];
  for (let pr of poleRefls) {
    for (let y = pr.y0; y < pr.y1; y += 4) {
      let w = 2.5 + (y - pr.y0) * 0.02;
      let ox = sin(y * 18) * 2.2;
      drawLine(pr.x + ox - w, y, pr.x + ox + w, y, "fine_liner", "#4b4763", 0.45);
    }
  }

  // 4. Perspective Rows of Young Flooded Rice Seedlings Converging to VP_PADDY
  const vpX = 165;
  const vpY = Y_HORIZON;
  const rowBottomXs = [-520, -360, -210, -75, 50, 165, 270, 368, 455];

  for (let r = 0; r < rowBottomXs.length; r++) {
    let bx = rowBottomXs[r];
    let steps = 34;
    for (let i = 2; i < steps; i++) {
      // Non-linear perspective spacing from horizon to bottom
      let t = pow(i / steps, 1.85);
      let py = vpY + (1205 - vpY) * t;
      let px = vpX + (bx - vpX) * t;

      // Clip to visible paddy region
      let dikeX = 212 + ((py - Y_HORIZON) / (1200 - Y_HORIZON)) * 252;
      if (px < -15 || px > dikeX - 8) continue;

      let scale = 0.22 + t * 1.35;
      let blades = 4 + floor(t * 5);

      // A. Inverted dark olive reflection in the water below the clump
      for (let b = 0; b < blades - 1; b++) {
        let ang = -55 + (b / max(1, blades - 2)) * 110 + random(-8, 8);
        let len = (9 + random(7)) * scale * 0.65;
        let rx2 = px + sin(ang) * len * 0.65;
        let ry2 = py + cos(ang) * len * 0.55;
        drawLine(px, py + 1, rx2, ry2, "fine_liner", "#3b5729", 0.35 * scale);
      }

      // B. Tiny bright water meniscus ring at the base of the rice clump
      drawLine(px - 6 * scale, py + 1, px + 6 * scale, py + 1, "fine_liner", "#e6f5fa", 0.3 * scale);

      // C. Crisp sunlit emerald & yellow-green rice blades fanning upward
      for (let b = 0; b < blades; b++) {
        let ang = -48 + (b / max(1, blades - 1)) * 96 + random(-6, 6);
        let len = (13 + random(10)) * scale;
        let tipX = px + sin(ang) * len * 0.72;
        let tipY = py - cos(ang) * len;
        let midX = (px + tipX) * 0.5 + sin(ang) * 2 * scale;
        let midY = (py + tipY) * 0.5 - 2 * scale;

        let bladeCol = b % 3 === 0 ? "#55802b" : (b % 3 === 1 ? "#84b037" : "#b8d64b");
        drawSpline([[px, py], [midX, midY], [tipX, tipY]], "fine_liner", bladeCol, (0.38 + t * 0.35), 0.35);
      }
    }
  }
}

