function drawPanelText(panel, str, s0, t0, s1, t1, col, weight = 0.35) {
  let n = str.length;
  if (n === 0) return;
  let cellW = (s1 - s0) / n;
  for (let i = 0; i < n; i++) {
    let ch = str[i].toUpperCase();
    let strokes = GLYPHS[ch];
    if (!strokes) continue;
    let cs0 = s0 + (i + 0.14) * cellW;
    let cs1 = s0 + (i + 0.86) * cellW;
    for (let st of strokes) {
      let pts = st.map(uv => panelPt(panel, cs0 + (cs1 - cs0) * uv[0], t0 + (t1 - t0) * uv[1]));
      strokePoly(pts, "fine_liner", col, weight, false, 0);
    }
  }
}

