function drawPowerLines() {
  // Draw crisp catenary cables with fine technical pen ("rotring" / "fine_liner")
  const cables = [
    // Upper high-voltage trio from right off-screen to main pole (x = 612)
    { p0: [1215, 22],  p1: [612 - 29, 102], sag: 38, w: 0.48 },
    { p0: [1215, 48],  p1: [612 - 13, 106], sag: 42, w: 0.45 },
    { p0: [1215, 76],  p1: [612 + 11, 111], sag: 45, w: 0.45 },
    { p0: [1215, 102], p1: [612 + 24, 115], sag: 48, w: 0.42 },

    // Lower crossarm cables from right off-screen to main pole
    { p0: [1215, 128], p1: [612 - 24, 156], sag: 36, w: 0.42 },
    { p0: [1215, 155], p1: [612 + 18, 166], sag: 40, w: 0.40 },

    // Cables sweeping left across the wide cumulus cloud to top-left off-screen
    { p0: [612 - 29, 102], p1: [-15, 165], sag: 52, w: 0.42 },
    { p0: [612 - 13, 106], p1: [-15, 195], sag: 56, w: 0.38 },
    { p0: [612 + 11, 111], p1: [-15, 228], sag: 60, w: 0.38 },

    // Perspective cables receding down to the mid-distance pole (x = 345)
    { p0: [612 - 24, 156], p1: [345 - 10, 614], sag: 44, w: 0.36 },
    { p0: [612 + 18, 166], p1: [345 + 9,  618], sag: 48, w: 0.35 },
    { p0: [612,      215], p1: [345,      636], sag: 38, w: 0.38 },

    // Further perspective cables from mid pole (x = 345) to far pole (x = 255)
    { p0: [345 - 10, 614], p1: [255 - 5, 742], sag: 16, w: 0.28 },
    { p0: [345 + 9,  618], p1: [255 + 4, 744], sag: 18, w: 0.28 },

    // Service drop-wire feeding from the main pole down into the vending machine's conduit!
    { p0: [612 + 8, 295],  p1: [1052, 430],    sag: 34, w: 0.44 }
  ];

  for (let c of cables) {
    let pts = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let x = lerp(c.p0[0], c.p1[0], t);
      let y = lerp(c.p0[1], c.p1[1], t) + 4 * t * (1 - t) * c.sag;
      pts.push([x, y]);
    }
    // Crisp dark ink cable line
    drawSpline(pts, "fine_liner", "#241f30", c.w, 0.35);
    // Delicate warm afternoon sunlight glint along the upper edge of main cables
