    strokePoly([
      [loopX - 6, loopY], [loopX, loopY + 9], [loopX + 6, loopY]
    ], "fine_liner", "#241f30", 0.38, false, 0.4);
  }
}

05-bowling:
// MOTION: The candy-apple lowrider bowling ball rolls and hooks forward toward the camera down the polished maple lane.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * PIECE_FPS;

// Hyperrealistic Candy-Apple Burgundy Lowrider Bowling Ball on Polished Maple Lane
// Rendered with p5.js v2 + p5.brush in WEBGL

const CX = 600;
const CY = 615;
const R = 345;
const VX = 600;
const VY = 175;
const Y_HORIZON = 235;
const Y_CONTACT = CY + R; // 960

// Ball 3D orientation (tilted slightly toward viewer and turned slightly for dynamic symmetry)
const BALL_YAW = -0.11;   // radians
const BALL_PITCH = 0.16;  // radians

// Primary light direction (upper-left window crown)
const LIGHT = normalize3([-0.42, -0.54, 0.73]);

// Snapshots captured passively during paintStill() on Frame 0
let laneCleanImg = null;
let laneReflImg = null;
let ballBaseImg = null;
let ballSurfaceImg = null;
let stillImg = null;

// Preprocessed typed arrays for fast, zero-boiling spherical pixel transport
let buffersReady = false;
let W = 1200;
let H = 1200;
let laneCleanPx = null;
let laneReflPx = null;
let ballBasePx = null;
let ballSurfPx = null;
let stillPx = null;
let smoothBasePx = null;
let winTransPx = null; // 3-channel normalized window reflection transmission map
let frameImg = null;

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

// Project spherical coordinates (u = longitude from spine, v = latitude) onto the 2D canvas
function projectBall(u, v, radScale = 1.0) {
  let lx = Math.sin(u) * Math.cos(v);
  let ly = Math.sin(v);
  let lz = Math.cos(u) * Math.cos(v);

  // Rotate around Y (yaw)
  let cy = Math.cos(BALL_YAW), sy = Math.sin(BALL_YAW);
  let x1 = lx * cy + lz * sy;
  let y1 = ly;
  let z1 = -lx * sy + lz * cy;

  // Rotate around X (pitch)
  let cp = Math.cos(BALL_PITCH), sp = Math.sin(BALL_PITCH);
  let nx = x1;
  let ny = y1 * cp - z1 * sp;
  let nz = y1 * sp + z1 * cp;

  let rad = R * radScale;
  return {
    x: CX + nx * rad,
    y: CY + ny * rad,
    z: nz * rad,
    nx: nx,
    ny: ny,
    nz: nz,
    visible: nz > 0.015,
    foreshorten: Math.max(0.12, nz)
  };
}

// Compute x coordinate of maple board seam b at canvas height y
function boardSeamX(b, y) {
  let widthAtContact = 76; // 1.06" board width relative to 8.5" ball (690px)
  let t = (y - VY) / (Y_CONTACT - VY);
  return VX + b * widthAtContact * t;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7719);
  noiseSeed(7719);

  // Custom brushes for hyperrealistic automotive lacquer, airbrush, metal-flake & Mack sword striping
  brush.add("soft_glaze", {
