    pressure: [0.2, 1.0, 0.2],
    noise: 0.1
  });

  brush.add("mack_striper", {
    type: "default",
    weight: 2.35,
    scatter: 0.015,
    sharpness: 0.91,
    grain: 1,
    opacity: 235,
