    noise: 0.55
  });
}

// Smooth velocity ease-in over first ~4 frames into steady rolling momentum
function getMotionProgress(k) {
  if (k <= 0) return 0;
  const raw = (x) => x - 1.65 * (1 - Math.exp(-x / 1.65));
  return raw(k) / raw(TOTAL_FRAMES - 1);
}

// Exact still painting routine executed on frameCount === 1
function paintStill() {
  background("#0b1018");

  // 1. Moody Cool-Toned Alley Background (above horizon)
  drawAlleyBackground();

  // 2. Polished Maple Lane Boards in Linear Perspective
  let boardColors = drawMapleLane();

  // 3. Lane Surface Reflections (Window Sheen, Ball Burgundy Reflection & Reflected Pinstripes)
  drawLaneReflections(boardColors);
  laneReflImg = get();

  // 4. The Candy-Apple Burgundy Sphere Base & Internal Depth
  drawCandySphereBase(boardColors);

  // 5. Metallic Micro-Flake Layer Suspended in the Candy Base
  drawMetalFlakeLayer();

  // 6. Translucent Candy-Apple Lacquer Over-Glaze
  drawCandyOverGlaze();
  ballBaseImg = get();

  // 7. Custom-Shop Lowrider Pinstripes (Lime Green, Cream & Cool Cyan Accents)
  drawAllPinstripes();

  // 8. Crisp, Dark, Bevelled Finger Holes
  drawAllFingerHoles();
  ballSurfaceImg = get();

  // 9. Sharp Mirrored Window Reflection Across the Crown & Final Specular Gloss
  drawCrownWindowReflection();
  stillImg = get();
}

function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  translate(-width / 2, -height / 2);

  // Frame 0: Exact pixel-for-pixel still
  if (frameCount === 1) {
    paintStill();
    return;
  }

  // On Frame 1 (frameCount === 2), initialize pixel buffers from the Frame 0 snapshots
  if (!buffersReady) {
    initSnapshotBuffers();
  }

  let k = frameCount - 1;
  let p = getMotionProgress(k);

  renderRollingFrame(k, p);
  image(frameImg, 0, 0, width, height);
}

// ============================================================================
// PIXEL BUFFER INITIALIZATION & SPHERICAL ROLL ENGINE
// ============================================================================
function initSnapshotBuffers() {
  laneCleanImg.loadPixels();
  laneReflImg.loadPixels();
  ballBaseImg.loadPixels();
  ballSurfaceImg.loadPixels();
  stillImg.loadPixels();

  W = stillImg.width;
  H = stillImg.height;

  laneCleanPx = new Uint8ClampedArray(laneCleanImg.pixels);
  laneReflPx = new Uint8ClampedArray(laneReflImg.pixels);
  ballBasePx = new Uint8ClampedArray(ballBaseImg.pixels);
  ballSurfPx = new Uint8ClampedArray(ballSurfaceImg.pixels);
  stillPx = new Uint8ClampedArray(stillImg.pixels);

  // 1. Transfer the 3 small finger-hole bevel starburst glints from stillPx into ballSurfPx
  // so those 3 bevel glints travel with the rolling finger holes while the window reflection stays put
  const holeGlintCenters = [
    projectBall(-0.11, -0.50, 0.998),
    projectBall(0.23, -0.50, 0.998),
    projectBall(0.07, -0.13, 0.998)
  ];
  const scaleCoord = W / 1200;
  const glintRad = 12 * scaleCoord;
  for (let gc of holeGlintCenters) {
    let gx = Math.round(gc.x * scaleCoord);
    let gy = Math.round(gc.y * scaleCoord);
    let rInt = Math.ceil(glintRad);
    for (let dy = -rInt; dy <= rInt; dy++) {
      let py = gy + dy;
      if (py < 0 || py >= H) continue;
      for (let dx = -rInt; dx <= rInt; dx++) {
        let px = gx + dx;
        if (px < 0 || px >= W) continue;
        let d = Math.hypot(dx, dy);
        if (d <= glintRad) {
          let w = Math.min(1, (glintRad - d) / (3 * scaleCoord));
          let idx = (py * W + px) * 4;
          ballSurfPx[idx]     = Math.round(lerp(ballSurfPx[idx],     stillPx[idx],     w));
          ballSurfPx[idx + 1] = Math.round(lerp(ballSurfPx[idx + 1], stillPx[idx + 1], w));
          ballSurfPx[idx + 2] = Math.round(lerp(ballSurfPx[idx + 2], stillPx[idx + 2], w));
        }
      }
    }
  }

  // 2. Build smoothBasePx (separable box blur of ballBasePx inside the ball disc)
  // This separates the stationary macro lighting gradient from the 2,400 rotating metal flakes
  smoothBasePx = new Uint8ClampedArray(ballBasePx);
  let tempPx = new Uint8ClampedArray(ballBasePx);
  let cxS = CX * scaleCoord;
  let cyS = CY * scaleCoord;
  let rS = (R - 2) * scaleCoord;
  let rS2 = rS * rS;
  let blurR = Math.max(3, Math.round(7 * scaleCoord));

  let xMin = Math.max(0, Math.floor(cxS - rS));
  let xMax = Math.min(W - 1, Math.ceil(cxS + rS));
  let yMin = Math.max(0, Math.floor(cyS - rS));
  let yMax = Math.min(H - 1, Math.ceil(cyS + rS));

  // Horizontal pass inside ball disc
  for (let y = yMin; y <= yMax; y++) {
    let dy = y - cyS;
    let dy2 = dy * dy;
    for (let x = xMin; x <= xMax; x++) {
      let dx = x - cxS;
      if (dx * dx + dy2 > rS2) continue;
      let sr = 0, sg = 0, sb = 0, cnt = 0;
      for (let k = -blurR; k <= blurR; k++) {
        let nx = x + k;
        let ndx = nx - cxS;
        if (ndx * ndx + dy2 <= rS2) {
          let nIdx = (y * W + nx) * 4;
          sr += ballBasePx[nIdx];
          sg += ballBasePx[nIdx + 1];
          sb += ballBasePx[nIdx + 2];
          cnt++;
        }
      }
      if (cnt > 0) {
        let idx = (y * W + x) * 4;
        tempPx[idx]     = sr / cnt;
        tempPx[idx + 1] = sg / cnt;
        tempPx[idx + 2] = sb / cnt;
      }
    }
  }

  // Vertical pass inside ball disc
  for (let y = yMin; y <= yMax; y++) {
    let dy = y - cyS;
    let dy2 = dy * dy;
    for (let x = xMin; x <= xMax; x++) {
      let dx = x - cxS;
      if (dx * dx + dy2 > rS2) continue;
      let sr = 0, sg = 0, sb = 0, cnt = 0;
      for (let k = -blurR; k <= blurR; k++) {
        let ny = y + k;
        let ndy = ny - cyS;
        if (dx * dx + ndy * ndy <= rS2) {
          let nIdx = (ny * W + x) * 4;
          sr += tempPx[nIdx];
          sg += tempPx[nIdx + 1];
          sb += tempPx[nIdx + 2];
          cnt++;
        }
      }
      if (cnt > 0) {
        let idx = (y * W + x) * 4;
        smoothBasePx[idx]     = sr / cnt;
        smoothBasePx[idx + 1] = sg / cnt;
        smoothBasePx[idx + 2] = sb / cnt;
      }
    }
  }

  // 3. Precompute the Crown Window & Overhead Specular Transmission Map (winTransPx)
  // Also compute an inpainted version across the narrow 2px pinstripe tracks under the window panes
  // so no faint stripe ghost remains inside the glass reflection after the stripe rolls away
  winTransPx = new Float32Array(W * H * 3);
  let winCleanPx = new Float32Array(W * H * 3);
  let onStripeMask = new Uint8Array(W * H);

  for (let y = yMin; y <= yMax; y++) {
    let dy = y - cyS;
    for (let x = xMin; x <= xMax; x++) {
      let dx = x - cxS;
      if (dx * dx + dy * dy > (R + 2) * (R + 2) * scaleCoord * scaleCoord) continue;
      let pIdx = y * W + x;
      let idx = pIdx * 4;
      let tIdx = pIdx * 3;

      let sR = ballSurfPx[idx],     sG = ballSurfPx[idx + 1], sB = ballSurfPx[idx + 2];
      let fR = stillPx[idx],        fG = stillPx[idx + 1],    fB = stillPx[idx + 2];
      let bR = ballBasePx[idx],     bG = ballBasePx[idx + 1], bB = ballBasePx[idx + 2];

      let tr = fR > sR ? (fR - sR) / Math.max(1, 255 - sR) : 0;
      let tg = fG > sG ? (fG - sG) / Math.max(1, 255 - sG) : 0;
      let tb = fB > sB ? (fB - sB) / Math.max(1, 255 - sB) : 0;

      winTransPx[tIdx]     = tr;
      winTransPx[tIdx + 1] = tg;
      winTransPx[tIdx + 2] = tb;
      winCleanPx[tIdx]     = tr;
      winCleanPx[tIdx + 1] = tg;
      winCleanPx[tIdx + 2] = tb;

      // Detect if a pinstripe or finger-hole edge was underneath this window reflection pixel on Frame 0
      let diffSurfBase = Math.abs(sR - bR) + Math.abs(sG - bG) + Math.abs(sB - bB);
      if (diffSurfBase > 28 && (tr + tg + tb) > 0.08) {
        onStripeMask[pIdx] = 1;
      }
    }
  }

  // Smoothly interpolate winCleanPx across the narrow stripe tracks from adjacent pure-glass pixels
  let searchR = Math.max(3, Math.round(6 * scaleCoord));
  for (let y = yMin + searchR; y <= yMax - searchR; y++) {
    for (let x = xMin + searchR; x <= xMax - searchR; x++) {
      let pIdx = y * W + x;
      if (!onStripeMask[pIdx]) continue;
      let sr = 0, sg = 0, sb = 0, sw = 0;
      for (let ky = -searchR; ky <= searchR; ky++) {
        let ny = y + ky;
        for (let kx = -searchR; kx <= searchR; kx++) {
          let nx = x + kx;
          let npIdx = ny * W + nx;
          if (!onStripeMask[npIdx]) {
            let d2 = kx * kx + ky * ky;
            let w = 1.0 / (1.0 + d2);
            let ntIdx = npIdx * 3;
            sr += winTransPx[ntIdx]     * w;
            sg += winTransPx[ntIdx + 1] * w;
            sb += winTransPx[ntIdx + 2] * w;
            sw += w;
          }
        }
      }
      if (sw > 0) {
        let tIdx = pIdx * 3;
        winCleanPx[tIdx]     = sr / sw;
        winCleanPx[tIdx + 1] = sg / sw;
        winCleanPx[tIdx + 2] = sb / sw;
      }
    }
  }
  // Store cleaned transmission in winTransPx (at k=1 we blend with stillPx anyway)
  winTransPx = winCleanPx;

  frameImg = createImage(W, H);
  frameImg.loadPixels();
  buffersReady = true;
}

// Bilinear sampler on a Uint8ClampedArray (W x H x 4)
function sampleBilinear(pxArr, x, y, out) {
  let x0 = Math.floor(x);
  let y0 = Math.floor(y);
  let x1 = Math.min(W - 1, x0 + 1);
  let y1 = Math.min(H - 1, y0 + 1);
  x0 = Math.max(0, Math.min(W - 1, x0));
  y0 = Math.max(0, Math.min(H - 1, y0));

  let fx = x - x0;
  let fy = y - y0;
  let w00 = (1 - fx) * (1 - fy);
  let w10 = fx * (1 - fy);
  let w01 = (1 - fx) * fy;
  let w11 = fx * fy;

  let i00 = (y0 * W + x0) * 4;
  let i10 = (y0 * W + x1) * 4;
  let i01 = (y1 * W + x0) * 4;
  let i11 = (y1 * W + x1) * 4;

  out[0] = pxArr[i00] * w00 + pxArr[i10] * w10 + pxArr[i01] * w01 + pxArr[i11] * w11;
  out[1] = pxArr[i00 + 1] * w00 + pxArr[i10 + 1] * w10 + pxArr[i01 + 1] * w01 + pxArr[i11 + 1] * w11;
  out[2] = pxArr[i00 + 2] * w00 + pxArr[i10 + 2] * w10 + pxArr[i01 + 2] * w01 + pxArr[i11 + 2] * w11;
}

function sampleBilinear3(pxArr, x, y, out) {
  let x0 = Math.floor(x);
  let y0 = Math.floor(y);
  let x1 = Math.min(W - 1, x0 + 1);
  let y1 = Math.min(H - 1, y0 + 1);
  x0 = Math.max(0, Math.min(W - 1, x0));
  y0 = Math.max(0, Math.min(H - 1, y0));

  let fx = x - x0;
  let fy = y - y0;
  let w00 = (1 - fx) * (1 - fy);
  let w10 = fx * (1 - fy);
  let w01 = (1 - fx) * fy;
  let w11 = fx * fy;

  let i00 = (y0 * W + x0) * 3;
  let i10 = (y0 * W + x1) * 3;
  let i01 = (y1 * W + x0) * 3;
  let i11 = (y1 * W + x1) * 3;

  out[0] = pxArr[i00] * w00 + pxArr[i10] * w10 + pxArr[i01] * w01 + pxArr[i11] * w11;
  out[1] = pxArr[i00 + 1] * w00 + pxArr[i10 + 1] * w10 + pxArr[i01 + 1] * w01 + pxArr[i11 + 1] * w11;
  out[2] = pxArr[i00 + 2] * w00 + pxArr[i10 + 2] * w10 + pxArr[i01 + 2] * w01 + pxArr[i11 + 2] * w11;
}

function renderRollingFrame(k, p) {
  const sC = W / 1200;
  let outPx = frameImg.pixels;

  // 1. Start with the clean static alley + maple lane backdrop
  outPx.set(laneCleanPx);

  // 2. Compute current ball position, scale, and 3D roll / spin parameters
  let curR = (R + 42 * p) * sC;
  let curYContact = (Y_CONTACT + 66 * p) * sC;
  let curCY = curYContact - curR;
  let curCX = (CX - 5 * Math.sin(p * Math.PI * 0.75)) * sC;
  let curScale = curR / (R * sC);

  let cx0 = CX * sC;
  let cy0 = CY * sC;
  let r0 = R * sC;
  let yContact0 = Y_CONTACT * sC;

  // 3. Update the lane reflection & cast shadow beneath the growing, advancing ball
  let reflYMin = Math.max(Math.floor(Y_HORIZON * sC), Math.floor(curYContact - 45 * curScale * sC));
  let reflXMin = Math.max(0, Math.floor(curCX - 430 * curScale * sC));
  let reflXMax = Math.min(W - 1, Math.ceil(curCX + 430 * curScale * sC));

  let sampRefl = [0, 0, 0];
  let sampClean = [0, 0, 0];
  let sampStripe = [0, 0, 0];
  let sampStripeClean = [0, 0, 0];

  for (let y = reflYMin; y < H; y++) {
    let dy = y - curYContact;
    let y0 = yContact0 + dy / curScale;
    if (y0 < Y_HORIZON * sC || y0 >= H - 1) continue;

    for (let x = reflXMin; x <= reflXMax; x++) {
      let dx = x - curCX;
      let x0 = cx0 + dx / curScale;
      if (x0 < 1 || x0 >= W - 2) continue;

      sampleBilinear(laneReflPx, x0, y0, sampRefl);
      sampleBilinear(laneCleanPx, x0, y0, sampClean);

      let idx = (y * W + x) * 4;
      let baseR = outPx[idx];
      let baseG = outPx[idx + 1];
      let baseB = outPx[idx + 2];

      // Apply shadow & burgundy reflection multiplicatively over the stationary maple boards
      let rR = sampRefl[0] <= sampClean[0]
        ? baseR * (sampRefl[0] / Math.max(1, sampClean[0]))
        : baseR + (sampRefl[0] - sampClean[0]);
      let rG = sampRefl[1] <= sampClean[1]
        ? baseG * (sampRefl[1] / Math.max(1, sampClean[1]))
        : baseG + (sampRefl[1] - sampClean[1]);
      let rB = sampRefl[2] <= sampClean[2]
        ? baseB * (sampRefl[2] / Math.max(1, sampClean[2]))
        : baseB + (sampRefl[2] - sampClean[2]);

      // Shift the reflected lime/cream pinstripes slightly as the ball's surface turns
      if (y > curYContact) {
        let signX = dx >= 0 ? 1 : -1;
        let xStripe0 = x0 + (signX * 14 * p - 10 * p) * sC;
        let yStripe0 = y0 + 18 * p * sC;
        if (xStripe0 >= 1 && xStripe0 < W - 2 && yStripe0 < H - 1) {
          sampleBilinear(laneReflPx, xStripe0, yStripe0, sampStripe);
          sampleBilinear(laneCleanPx, xStripe0, yStripe0, sampStripeClean);
          let addG = Math.max(0, sampStripe[1] - sampStripeClean[1]);
          if (addG > 4) {
            let addR = Math.max(0, sampStripe[0] - sampStripeClean[0]);
            let addB = Math.max(0, sampStripe[2] - sampStripeClean[2]);
            rR = Math.min(255, rR + addR * 0.65);
            rG = Math.min(255, rG + addG * 0.65);
            rB = Math.min(255, rB + addB * 0.65);
          }
        }
      }

      outPx[idx]     = Math.max(0, Math.min(255, Math.round(rR)));
      outPx[idx + 1] = Math.max(0, Math.min(255, Math.round(rG)));
      outPx[idx + 2] = Math.max(0, Math.min(255, Math.round(rB)));
    }
  }

  // 4. Render the Rolling & Scaling Ball by lifting & rotating pixels from Frame 0
  // Spin angle + Mobius spherical latitude/longitude roll preserve the disc bijectively
  let spinAngle = -0.24 * p; // Counter-clockwise hook spin (~13.8 deg) as it rolls forward
  let cosSpin = Math.cos(spinAngle);
  let sinSpin = Math.sin(spinAngle);

  let rollLatA = 0.35 * p;   // Strong forward spherical roll toward the camera
  let rollLonB = -0.07 * p;  // Subtle 3D hook yaw

  let bXMin = Math.max(0, Math.floor(curCX - curR - 2));
  let bXMax = Math.min(W - 1, Math.ceil(curCX + curR + 2));
  let bYMin = Math.max(0, Math.floor(curCY - curR - 2));
  let bYMax = Math.min(H - 1, Math.ceil(curCY + curR + 2));

  let sSurf = [0, 0, 0];
  let sBase0 = [0, 0, 0];
  let sSmooth0 = [0, 0, 0];
  let sSmoothCur = [0, 0, 0];
  let sWinT = [0, 0, 0];

  for (let y = bYMin; y <= bYMax; y++) {
    let dy = y - curCY;
    for (let x = bXMin; x <= bXMax; x++) {
      let dx = x - curCX;
      let dist = Math.hypot(dx, dy);
      if (dist > curR + 1.2 * sC) continue;

      // Antialiased outer silhouette edge coverage
      let edgeAlpha = Math.max(0, Math.min(1, (curR + 0.7 * sC - dist) / (1.4 * sC)));
      if (edgeAlpha <= 0) continue;

      // Normalized coordinates inside the current ball disc (clamped to unit disc)
      let rNorm = Math.min(0.9995, dist / curR);
      let scaleNorm = dist > 1e-5 ? rNorm / (dist / curR) : 1.0;
      let ux = (dx / curR) * scaleNorm;
      let uy = (dy / curR) * scaleNorm;

      // Unscaled canonical coordinates on the sphere (for stationary lighting & window reflection)
      let xCanon = cx0 + ux * r0;
      let yCanon = cy0 + uy * r0;

      // Inverse spin + 3D spherical meridian/latitude roll to find Frame 0 surface source (ux0, uy0)
      let uxRot = ux * cosSpin - uy * sinSpin;
      let uyRot = ux * sinSpin + uy * cosSpin;

      let v = Math.max(-0.9995, Math.min(0.9995, uyRot));
      let cosLat = Math.sqrt(Math.max(1e-6, 1 - v * v));
      let w = Math.max(-0.9995, Math.min(0.9995, uxRot / cosLat));

      // Mobius spherical roll along latitude v and longitude w
      let v0 = (v - rollLatA) / (1 - v * rollLatA);
      let w0 = (w - rollLonB) / (1 - w * rollLonB);

      let uy0 = v0;
      let ux0 = w0 * Math.sqrt(Math.max(0, 1 - v0 * v0));

      let xSurf0 = cx0 + ux0 * r0;
      let ySurf0 = cy0 + uy0 * r0;

      // Sample rotated surface (pinstripes, finger holes, flakes) & stationary lighting envelope
      sampleBilinear(ballSurfPx, xSurf0, ySurf0, sSurf);
      sampleBilinear(ballBasePx, xSurf0, ySurf0, sBase0);
      sampleBilinear(smoothBasePx, xSurf0, ySurf0, sSmooth0);
      sampleBilinear(smoothBasePx, xCanon, yCanon, sSmoothCur);

      // Determine whether source pixel is on a pinstripe / finger hole vs candy metal-flake coat
      let diffFeature = Math.max(
        Math.abs(sSurf[0] - sBase0[0]),
        Math.abs(sSurf[1] - sBase0[1]),
        Math.abs(sSurf[2] - sBase0[2])
      );
      let featW = Math.max(0, Math.min(1, (diffFeature - 3) / 16.0));

      // 1) Candy base + rotating metal-flake speckle (keeps macro shading sSmoothCur fixed to light)
      let candyR = sSmoothCur[0] + (sBase0[0] - sSmooth0[0]);
      let candyG = sSmoothCur[1] + (sBase0[1] - sSmooth0[1]);
      let candyB = sSmoothCur[2] + (sBase0[2] - sSmooth0[2]);

      // 2) Pinstripes & finger holes (preserve exact color/crispness, modulated gently by spherical lighting)
      let lumCur = sSmoothCur[0] * 0.5 + sSmoothCur[1] * 0.3 + sSmoothCur[2] * 0.2;
      let lum0   = sSmooth0[0]   * 0.5 + sSmooth0[1]   * 0.3 + sSmooth0[2]   * 0.2;
      let lightMod = Math.max(0.74, Math.min(1.14, (lumCur + 150) / (lum0 + 150)));

      let featR = sSurf[0] * lightMod;
      let featG = sSurf[1] * lightMod;
      let featB = sSurf[2] * lightMod;

      // Blend candy coat and surface features, fading features smoothly right at the 2px outer rim
      let rimKeep = rNorm > 0.975 ? Math.max(0, (0.996 - rNorm) / 0.021) : 1.0;
      let fw = featW * rimKeep;

      let surfR = candyR + (featR - candyR) * fw;
      let surfG = candyG + (featG - candyG) * fw;
      let surfB = candyB + (featB - candyB) * fw;

      // 3) Composite the stationary Crown Window Reflection & Specular Highlight on top
      sampleBilinear3(winTransPx, xCanon, yCanon, sWinT);

      let finalR = surfR + sWinT[0] * (255 - surfR);
      let finalG = surfG + sWinT[1] * (255 - surfG);
      let finalB = surfB + sWinT[2] * (255 - surfB);

      let idx = (y * W + x) * 4;
      if (edgeAlpha >= 0.999) {
        outPx[idx]     = Math.max(0, Math.min(255, Math.round(finalR)));
        outPx[idx + 1] = Math.max(0, Math.min(255, Math.round(finalG)));
        outPx[idx + 2] = Math.max(0, Math.min(255, Math.round(finalB)));
      } else {
        outPx[idx]     = Math.max(0, Math.min(255, Math.round(lerp(outPx[idx],     finalR, edgeAlpha))));
        outPx[idx + 1] = Math.max(0, Math.min(255, Math.round(lerp(outPx[idx + 1], finalG, edgeAlpha))));
        outPx[idx + 2] = Math.max(0, Math.min(255, Math.round(lerp(outPx[idx + 2], finalB, edgeAlpha))));
      }
    }
  }

  // On Frame 1 (k === 1), blend 35% with stillPx so the sub-pixel start is 100% seamless
  if (k === 1) {
    for (let i = 0; i < outPx.length; i += 4) {
      outPx[i]     = Math.round(outPx[i]     * 0.65 + stillPx[i]     * 0.35);
      outPx[i + 1] = Math.round(outPx[i + 1] * 0.65 + stillPx[i + 1] * 0.35);
      outPx[i + 2] = Math.round(outPx[i + 2] * 0.65 + stillPx[i + 2] * 0.35);
    }
  }

  frameImg.updatePixels();
}

// ============================================================================
// 1. ALLEY BACKGROUND (UNCHANGED FROM STILL)
// ============================================================================
function drawAlleyBackground() {
  brush.noField();
  brush.noStroke();

  // Deep cool navy-charcoal backdrop
  brush.wash("#090e17", 255);
  brush.rect(0, 0, 1200, Y_HORIZON + 15, "corner");

  // Distant atmospheric cool window/ceiling glow
  let glowBands = [
    { x: 460, y: 110, w: 680, h: 170, c: "#162436", a: 120 },
    { x: 420, y: 95,  w: 520, h: 130, c: "#1f354d", a: 95 },
    { x: 380, y: 80,  w: 360, h: 95,  c: "#2d4c6b", a: 75 }
  ];
  for (let g of glowBands) {
    brush.wash(g.c, g.a);
    brush.rect(g.x, g.y, g.w, g.h, "center");
  }

  // Subtle horizontal structural beams & pin-deck shadow line at the horizon
  brush.set("soft_glaze", "#1c2d42", 1.4);
  for (let y = 30; y < Y_HORIZON - 20; y += 26) {
    brush.line(40, y, 1160, y);
  }

  // Crisp dark gutter/pit horizon divider
  brush.noStroke();
  brush.wash("#05070c", 235);
  brush.rect(0, Y_HORIZON - 16, 1200, 22, "corner");

  brush.set("rotring", "#2b3e54", 0.9);
  brush.line(0, Y_HORIZON, 1200, Y_HORIZON);
}

// ============================================================================
// 2. POLISHED MAPLE LANE BOARDS (UNCHANGED FROM STILL)
// ============================================================================
function drawMapleLane() {
  brush.noField();

  // Base lane foundation
  brush.noStroke();
  brush.wash("#333942", 255);
  brush.rect(0, Y_HORIZON, 1200, 1200 - Y_HORIZON, "corner");

  // Cool-shifted rock maple palette (silvered honey, ash-taupe, slate-amber, cool pewter)
  const mapleTones = [
    "#54565c", "#6c6864", "#7d776f", "#4a4e57",
    "#8a8177", "#5e5f63", "#746e68", "#636266",
    "#948b80", "#4f5259", "#827b73", "#595b61"
  ];

  let boardMeta = {};

  // Draw individual perspective boards from b = -22 to +22
  for (let b = -22; b <= 21; b++) {
    let idx = Math.abs(b * 7 + 13) % mapleTones.length;
    let col = mapleTones[idx];
    // Slight vertical reflection jitter per board (realistic floorboard tilt)
    let jitter = (noise(b * 0.7, 1.3) - 0.5) * 9.0;
    boardMeta[b] = { col, jitter };

    let xTopL = boardSeamX(b, Y_HORIZON);
    let xTopR = boardSeamX(b + 1, Y_HORIZON);
    let xBotL = boardSeamX(b, 1200);
    let xBotR = boardSeamX(b + 1, 1200);

    // Skip if completely off-screen
    if (Math.max(xTopL, xTopR, xBotL, xBotR) < -20 || Math.min(xTopL, xTopR, xBotL, xBotR) > 1220) {
      continue;
    }

    // Board base wash
    brush.noStroke();
    brush.wash(col, 230);
    brush.beginShape(0);
    brush.vertex(constrain(xTopL, -40, 1240), Y_HORIZON);
    brush.vertex(constrain(xTopR, -40, 1240), Y_HORIZON);
    brush.vertex(constrain(xBotR, -80, 1280), 1200);
    brush.vertex(constrain(xBotL, -80, 1280), 1200);
    brush.endShape(true);

    // Subtle tonal variation along the board length (plank joints)
    let jointY = map(noise(b * 1.9 + 5), 0, 1, 340, 880);
    let xJL = boardSeamX(b, jointY);
    let xJR = boardSeamX(b + 1, jointY);
    brush.wash(b % 2 === 0 ? "#242a34" : "#aba196", 32);
    brush.beginShape(0);
    brush.vertex(constrain(xJL, -40, 1240), jointY);
    brush.vertex(constrain(xJR, -40, 1240), jointY);
    brush.vertex(constrain(xBotR, -80, 1280), 1200);
    brush.vertex(constrain(xBotL, -80, 1280), 1200);
    brush.endShape(true);

    // Fine wood-grain fibers along perspective lines
    let grainCount = b >= -8 && b <= 8 ? 5 : 3;
    for (let g = 1; g <= grainCount; g++) {
      let frac = g / (grainCount + 1);
      let gx1 = lerp(xTopL, xTopR, frac);
      let gx2 = lerp(xBotL, xBotR, frac);
      if (gx2 > -50 && gx2 < 1250) {
        let grainCol = (g + b) % 2 === 0 ? "#36383f" : "#9c9388";
        brush.set("wood_grain", grainCol, 0.85);
        brush.line(gx1, Y_HORIZON, gx2, 1200);
      }
    }

    // Range-finder arrows inlaid on every 5th board in the upper mid-ground
    if (b % 5 === 0 && b >= -10 && b <= 10) {
      let arrowY = 390 - Math.abs(b) * 8;
      let arrowLen = 48;
      let axMidTop = boardSeamX(b + 0.5, arrowY - arrowLen);
      let axL = boardSeamX(b + 0.08, arrowY);
      let axR = boardSeamX(b + 0.92, arrowY);
      let axMidIn = boardSeamX(b + 0.5, arrowY - 12);
      brush.noStroke();
      brush.wash("#22252e", 185);
      brush.beginShape(0);
      brush.vertex(axMidTop, arrowY - arrowLen);
      brush.vertex(axR, arrowY);
      brush.vertex(axMidIn, arrowY - 12);
      brush.vertex(axL, arrowY);
      brush.endShape(true);
    }
  }

  // Crisp board seam lines converging to (VX, VY)
  for (let b = -22; b <= 22; b++) {
    let xTop = boardSeamX(b, Y_HORIZON);
    let xBot = boardSeamX(b, 1200);
    if (Math.max(xTop, xBot) < -20 || Math.min(xTop, xBot) > 1220) continue;

    // Dark seam groove
    brush.set("rotring", "#232730", 0.55);
    brush.line(xTop, Y_HORIZON, xBot, 1200);

    // Subtle specular catch along adjacent board edge
    brush.set("2H", "#a39d95", 0.4);
    brush.line(xTop + 0.6, Y_HORIZON, xBot + 1.2, 1200);
  }

  return boardMeta;
}

// ============================================================================
// 3. LANE SURFACE REFLECTIONS & SHADOWS (UNCHANGED FROM STILL)
// ============================================================================
function drawLaneReflections(boardMeta) {
  brush.noField();

  // A. Cool Window Specular Column stretching down the left-center of the lane
  for (let i = 0; i < 12; i++) {
    let t = i / 11;
    let bStart = lerp(-9, -6.5, t);
    let bEnd = lerp(-0.5, -2.5, t);
    let xTL = boardSeamX(bStart, Y_HORIZON);
    let xTR = boardSeamX(bEnd, Y_HORIZON);
    let xBL = boardSeamX(bStart, 1200);
    let xBR = boardSeamX(bEnd, 1200);

    brush.noStroke();
    brush.wash("#b5d8f0", 14);
    brush.beginShape(0);
    brush.vertex(xTL, Y_HORIZON);
    brush.vertex(xTR, Y_HORIZON);
    brush.vertex(xBR, 1200);
    brush.vertex(xBL, 1200);
    brush.endShape(true);
  }

  // B. Cool Slate Vignette on outer lane edges and horizon depth
  brush.noStroke();
  brush.wash("#121a26", 110);
  brush.beginShape(0);
  brush.vertex(0, Y_HORIZON);
  brush.vertex(boardSeamX(-7, Y_HORIZON), Y_HORIZON);
  brush.vertex(boardSeamX(-7, 1200), 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);

  brush.wash("#101722", 125);
  brush.beginShape(0);
  brush.vertex(boardSeamX(6, Y_HORIZON), Y_HORIZON);
  brush.vertex(1200, Y_HORIZON);
  brush.vertex(1200, 1200);
  brush.vertex(boardSeamX(6, 1200), 1200);
  brush.endShape(true);

  // Passive snapshot of the clean lane before the ball's floor reflection and cast shadow
  laneCleanImg = get();

  // C. Board-broken Mirror Reflection of the Candy-Apple Burgundy Ball on the Lane
  // The reflection sits directly below Y_CONTACT (960 down to 1200) across boards -5 to +5
  for (let b = -5; b <= 4; b++) {
    let meta = boardMeta[b] || { jitter: 0 };
    let jit = meta.jitter;

    // Sample vertical slices within board b
    let yTop = Y_CONTACT - 18 + jit;
    let yBot = 1200;
    let xTL = boardSeamX(b, yTop);
    let xTR = boardSeamX(b + 1, yTop);
    let xBL = boardSeamX(b, yBot);
    let xBR = boardSeamX(b + 1, yBot);

    // Distance from center board determines how deep the burgundy reflection reaches
    let distFromCenter = Math.abs(b + 0.5);
    if (distFromCenter < 4.6) {
      let reach = Math.sqrt(Math.max(0, 1 - Math.pow(distFromCenter / 4.6, 2)));
      let reflEnd = Math.min(1200, Y_CONTACT + reach * 255 + jit * 2);

      let xEL = boardSeamX(b, reflEnd);
      let xER = boardSeamX(b + 1, reflEnd);

      // Deep wine reflection wash on this board strip
      brush.noStroke();
      brush.wash("#2b0410", 145);
      brush.beginShape(0);
      brush.vertex(xTL, yTop);
      brush.vertex(xTR, yTop);
      brush.vertex(xER, reflEnd);
      brush.vertex(xEL, reflEnd);
      brush.endShape(true);

      // Brighter candy-crimson core reflection near the middle boards
      if (distFromCenter < 3.2) {
        let midEnd = Math.min(1200, Y_CONTACT + reach * 190 + jit);
        let xML = boardSeamX(b, midEnd);
        let xMR = boardSeamX(b + 1, midEnd);
        brush.wash("#59071f", 110);
        brush.beginShape(0);
        brush.vertex(xTL, yTop + 10);
        brush.vertex(xTR, yTop + 10);
        brush.vertex(xMR, midEnd);
        brush.vertex(xML, midEnd);
        brush.endShape(true);
      }
    }
  }

  // Soft airbrushed burgundy & lime-green glow in the lane reflection
  for (let r = 260; r >= 50; r -= 25) {
    let col = r > 160 ? "#24030d" : (r > 95 ? "#4a0619" : "#6e0a25");
    brush.set("soft_glaze", col, 2.2);
    brush.arc(CX, Y_CONTACT + 75, r, 10, 170);
  }

  // Reflected Pinstripe Ghosts in the Polished Maple (lime green & cream curves)
  const reflStripes = [
    { pts: [[-185, 1005], [-110, 1065], [-35, 1135], [0, 1165]], c: "#78bd14", w: 1.1 },
    { pts: [[185, 1005], [110, 1065], [35, 1135], [0, 1165]], c: "#78bd14", w: 1.1 },
    { pts: [[-120, 995], [-68, 1045], [-18, 1095], [0, 1130]], c: "#d9d2b8", w: 0.9 },
    { pts: [[120, 995], [68, 1045], [18, 1095], [0, 1130]], c: "#d9d2b8", w: 0.9 },
    { pts: [[-235, 1020], [-155, 1085], [-75, 1150]], c: "#639e10", w: 0.85 },
    { pts: [[235, 1020], [155, 1085], [75, 1150]], c: "#639e10", w: 0.85 }
  ];
  for (let rs of reflStripes) {
    let spts = rs.pts.map(p => [CX + p[0], p[1], 0.8]);
    brush.set("fine_glaze", rs.c, rs.w);
    brush.spline(spts, 0.5);
    brush.set("mack_striper", rs.c, rs.w * 0.55);
    brush.spline(spts, 0.5);
  }

  // Re-scribe crisp board seams across the reflection so the reflection sits *inside* the wood finish
  for (let b = -6; b <= 6; b++) {
    let x1 = boardSeamX(b, Y_CONTACT - 30);
    let x2 = boardSeamX(b, 1200);
    brush.set("rotring", "#161820", 0.6);
    brush.line(x1, Y_CONTACT - 30, x2, 1200);
  }

  // Horizontal glossy polyurethane reflection streaks across the lane
  for (let i = 0; i < 45; i++) {
    let ry = random(Y_HORIZON + 15, 1190);
    let span = map(ry, Y_HORIZON, 1200, 90, 420);
    let rx = CX + random(-420, 320);
    let col = ry > Y_CONTACT - 10 && Math.abs(rx - CX) < 240 ? "#7a1632" : "#b8d4eb";
    brush.set("2H", col, random(0.3, 0.7));
    brush.line(rx - span * 0.5, ry, rx + span * 0.5, ry);
  }

  // D. Cast Shadow & Tight Contact Ambient Occlusion under the Ball
  let shadowLayers = [
    { rx: 280, ry: 46, yOff: 8,  c: "#0d1018", a: 110 },
    { rx: 220, ry: 34, yOff: 5,  c: "#08070d", a: 150 },
    { rx: 155, ry: 22, yOff: 2,  c: "#050308", a: 195 },
    { rx: 95,  ry: 12, yOff: 0,  c: "#020104", a: 245 }
  ];
  brush.noStroke();
  for (let sl of shadowLayers) {
    brush.wash(sl.c, sl.a);
    drawEllipsePoly(CX + 12, Y_CONTACT + sl.yOff, sl.rx, sl.ry, 40);
  }
}

function drawEllipsePoly(cx, cy, rx, ry, steps = 48) {
  brush.beginShape(0);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    brush.vertex(cx + cos(a) * rx, cy + sin(a) * ry);
  }
  brush.endShape(true);
}

// ============================================================================
// 4. CANDY-APPLE BURGUNDY SPHERE BASE & CURVED LANE BOUNCE REFLECTION
// ============================================================================
function drawCandySphereBase(boardMeta) {
  brush.noField();
  brush.noStroke();

  // 1. Deepest black-cherry / midnight-plum foundation sphere
  brush.wash("#120208", 255);
  drawEllipsePoly(CX, CY, R, R, 72);

  // 2. Concentric eccentric shading layers building toward the upper-left light core
  const candyRamp = [
    { ox: -15,  oy: -18,  rad: 0.96, c: "#1c030c", a: 210 },
    { ox: -28,  oy: -34,  rad: 0.90, c: "#290411", a: 190 },
    { ox: -42,  oy: -50,  rad: 0.83, c: "#3b0518", a: 175 },
    { ox: -56,  oy: -66,  rad: 0.75, c: "#4f0620", a: 165 },
    { ox: -70,  oy: -82,  rad: 0.67, c: "#660828", a: 155 },
    { ox: -84,  oy: -98,  rad: 0.58, c: "#800a31", a: 150 },
    { ox: -98,  oy: -112, rad: 0.49, c: "#9c0d3b", a: 145 },
    { ox: -110, oy: -125, rad: 0.40, c: "#b81145", a: 140 },
    { ox: -122, oy: -136, rad: 0.31, c: "#d41952", a: 130 },
    { ox: -132, oy: -146, rad: 0.22, c: "#eb2864", a: 115 }
  ];

  for (let layer of candyRamp) {
    brush.wash(layer.c, layer.a);
    drawEllipsePoly(CX + layer.ox, CY + layer.oy, R * layer.rad, R * layer.rad, 60);
  }

  // 3. Soft spray/glaze transitions along the spherical terminator
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let rad = lerp(R * 0.18, R * 0.96, t);
    let ox = lerp(-130, 0, t);
    let oy = lerp(-145, 0, t);
    let col = t < 0.35 ? "#d91c54" : (t < 0.68 ? "#7a092c" : "#2b0311");
    brush.set("soft_glaze", col, 1.8);
    // Clip arc inside sphere by keeping ox+rad <= R
    let safeRad = Math.min(rad, R - Math.hypot(ox, oy) - 4);
    if (safeRad > 15) {
      brush.arc(CX + ox, CY + oy, safeRad, 0, 360);
    }
  }

  // 4. Fisheye Reflection of the Maple Lane Boards on the Lower Hemisphere of the Ball
  for (let b = -6; b <= 5; b++) {
    let uL = b * 0.17;
    let uR = (b + 1) * 0.17;
    let vTop = 0.36;
    let vBot = 1.18;

    let polyPts = [];
    for (let s = 0; s <= 6; s++) {
      let u = lerp(uL, uR, s / 6);
      let p = projectBall(u, vTop, 0.992);
      if (p.visible) polyPts.push([p.x, p.y]);
    }
    for (let s = 6; s >= 0; s--) {
      let u = lerp(uL, uR, s / 6);
      let p = projectBall(u, vBot, 0.992);
      if (p.visible) polyPts.push([p.x, p.y]);
    }

    if (polyPts.length >= 4) {
      brush.noStroke();
      let tone = Math.abs(b) % 2 === 0 ? "#4f2632" : "#381522";
      brush.wash(tone, 58);
      brush.beginShape(0);
      for (let pt of polyPts) brush.vertex(pt[0], pt[1]);
      brush.endShape(true);

      // Curved board seam line reflected on the lower sphere
      let seamPts = [];
      for (let sv = vTop; sv <= vBot; sv += 0.12) {
        let sp = projectBall(uL, sv, 0.992);
        if (sp.visible) seamPts.push([sp.x, sp.y, sp.foreshorten * 0.7]);
      }
      if (seamPts.length >= 3) {
        brush.set("rotring", "#1a040c", 0.45);
        brush.spline(seamPts, 0.4);
      }
    }
  }

  // 5. Cool Palette Fresnel Rim Reflections (Left & Upper-Right Edges of Sphere)
  for (let pass = 0; pass < 3; pass++) {
    let rad = R - 3 - pass * 4;
    brush.set("fine_glaze", pass === 0 ? "#6ea8cc" : "#3a5a78", 1.2 - pass * 0.25);
    brush.arc(CX, CY, rad, 135, 225); // Left cool rim
    brush.arc(CX, CY, rad, 305, 45);  // Right cool rim
  }
}

// ============================================================================
// 5. METAL-FLAKE LAYER (FINE SPECKLE SUSPENDED IN CANDY BASE)
// ============================================================================
function drawMetalFlakeLayer() {
  brush.noField();

  // A. Spray bands of metallic shimmer across the illuminated hemisphere
  for (let i = 0; i < 48; i++) {
    let u1 = random(-1.1, 0.4);
    let v1 = random(-1.05, 0.35);
    let u2 = u1 + random(0.18, 0.45);
    let v2 = v1 + random(-0.15, 0.15);

    let p1 = projectBall(u1, v1, 0.97);
    let p2 = projectBall(u2, v2, 0.97);
    if (!p1.visible || !p2.visible) continue;

    let dotL = p1.nx * LIGHT[0] + p1.ny * LIGHT[1] + p1.nz * LIGHT[2];
    if (dotL > -0.15) {
      let col = dotL > 0.65 ? "#ff6b93" : (dotL > 0.3 ? "#d9164b" : "#780b32");
      brush.set("flake_spray", col, map(dotL, -0.15, 1, 0.55, 1.35));
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // B. Individual crisp micro-flakes (2,400 metallic prism specks)
  for (let i = 0; i < 2400; i++) {
    // Concentrate flakes toward the lit side and mid-tone ring
    let u = random(-1.35, 1.25);
    let v = random(-1.25, 1.15);
    let p = projectBall(u, v, random(0.96, 0.992));
    if (!p.visible) continue;

    let dotL = p.nx * LIGHT[0] + p.ny * LIGHT[1] + p.nz * LIGHT[2];
    // Stochastic acceptance weighted by illumination
    if (random() > map(dotL, -0.5, 1.0, 0.08, 0.95)) continue;

    let flakeCol;
    let w;
    if (dotL > 0.72) {
      // Hot crown zone: sparkling rose-gold, cool silver-pink, cyan prism & vivid ruby
      let r = random();
      flakeCol = r < 0.35 ? "#ffb3c9" : (r < 0.65 ? "#ff3870" : (r < 0.85 ? "#fff0f5" : "#a8ecff"));
      w = random(0.55, 1.15);
    } else if (dotL > 0.35) {
      // Rich candy zone: electric crimson, magenta-berry & warm copper-rose
      let r = random();
      flakeCol = r < 0.45 ? "#e0164c" : (r < 0.8 ? "#b00e44" : "#ff668c");
      w = random(0.45, 0.95);
    } else if (dotL > 0.0) {
      // Deep oxblood transition: plum-magenta & dark ruby
      flakeCol = random() < 0.6 ? "#7a0930" : "#59123a";
      w = random(0.35, 0.75);
    } else {
      // Shadow core: faint cool violet-wine glints
      flakeCol = "#3b0a29";
      w = random(0.3, 0.6);
    }

    let len = random(1.2, 2.8) * p.foreshorten;
    let ang = random(0, 180) * (Math.PI / 180);
    let dx = Math.cos(ang) * len * 0.5;
    let dy = Math.sin(ang) * len * 0.5;

    brush.set("rotring", flakeCol, w * p.foreshorten);
    brush.line(p.x - dx, p.y - dy, p.x + dx, p.y + dy);
  }
}

// ============================================================================
// 6. TRANSLUCENT CANDY-APPLE LACQUER OVER-GLAZE
// ============================================================================
function drawCandyOverGlaze() {
  brush.noField();
  brush.noStroke();

  // Embeds the metal-flake beneath rich, glassy candy-apple dye
  brush.wash("#5e0521", 48);
  drawEllipsePoly(CX, CY, R * 0.99, R * 0.99, 64);

  brush.wash("#9e0b37", 42);
  drawEllipsePoly(CX - 75, CY - 85, R * 0.62, R * 0.62, 54);

  // Deep shadow crescent along the bottom-right core to amplify 3D roundness
  for (let i = 0; i < 8; i++) {
    let rad = R * lerp(0.76, 0.97, i / 7);
    brush.set("soft_glaze", "#14020a", 2.1);
    brush.arc(CX + 18, CY + 18, rad, 345, 115);
  }

  // Crisp outer sphere silhouette refinement
  brush.set("rotring", "#240512", 0.95);
  brush.arc(CX, CY, R, 0, 360);
}

// ============================================================================
// 7. LOWRIDER PINSTRIPES (SYMMETRICAL SCROLLS IN LIME GREEN & CREAM)
// ============================================================================
function drawSphericalCurve(uvPts, brushName, col, weightMult = 1.0, offsetPx = [0, 0]) {
  let dense = [];
  for (let i = 0; i < uvPts.length - 1; i++) {
    let a = uvPts[i];
    let b = uvPts[i + 1];
    let dist = Math.hypot(b[0] - a[0], b[1] - a[1]);
    let steps = Math.max(3, Math.ceil(dist / 0.045));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      dense.push([
        lerp(a[0], b[0], t),
        lerp(a[1], b[1], t),
        lerp(a[2] ?? 1.0, b[2] ?? 1.0, t)
      ]);
    }
  }
  dense.push(uvPts[uvPts.length - 1]);

  let screenPts = [];
  for (let pt of dense) {
    let p = projectBall(pt[0], pt[1], 0.996);
    if (p.visible) {
      let sx = p.x + offsetPx[0];
      let sy = p.y + offsetPx[1];
      let sp = Math.max(0.08, (pt[2] ?? 1.0) * Math.pow(p.foreshorten, 0.65));
      if (screenPts.length === 0 || Math.hypot(sx - screenPts[screenPts.length - 1][0], sy - screenPts[screenPts.length - 1][1]) > 2.2) {
        screenPts.push([sx, sy, sp]);
      }
    }
  }

  if (screenPts.length >= 3) {
    brush.set(brushName, col, weightMult);
    brush.spline(screenPts, 0.45);
  } else if (screenPts.length === 2) {
    brush.set(brushName, col, weightMult * screenPts[0][2]);
    brush.line(screenPts[0][0], screenPts[0][1], screenPts[1][0], screenPts[1][1]);
  }
}

function drawSymPinstripe(uvPts, baseCol, coreCol, weightMult = 1.0, hasCenterMirror = true) {
  let sides = hasCenterMirror ? [1, -1] : [1];
  for (let dir of sides) {
    let mirrored = uvPts.map(p => [p[0] * dir, p[1], p[2] ?? 1.0]);

    // 1. Sub-surface clearcoat shadow onto the candy base
    drawSphericalCurve(mirrored, "mack_striper", "#160208", weightMult * 0.95, [2.2, 3.2]);

    // 2. Main lacquer stroke with Mack sword striper
    drawSphericalCurve(mirrored, "mack_striper", baseCol, weightMult, [0, 0]);

    // 3. Wet specular ridge down the center of the stroke
    if (coreCol) {
      drawSphericalCurve(mirrored, "mack_core", coreCol, weightMult * 0.72, [-0.3, -0.3]);
    }
  }
}

function drawSymDot(u, v, radiusPx, baseCol, coreCol) {
  let sides = Math.abs(u) < 0.001 ? [1] : [1, -1];
  for (let dir of sides) {
    let p = projectBall(u * dir, v, 0.996);
    if (!p.visible) continue;
    let r = radiusPx * p.foreshorten;
    brush.set("mack_striper", "#160208", r * 0.9);
    brush.line(p.x + 2, p.y + 2.5, p.x + 2 + 0.8, p.y + 2.5 + 0.8);

    brush.set("mack_striper", baseCol, r);
    brush.line(p.x - 0.5, p.y - 0.5, p.x + 0.5, p.y + 0.5);

    if (coreCol) {
      brush.set("mack_core", coreCol, r * 0.75);
      brush.line(p.x - 0.3, p.y - 0.3, p.x + 0.3, p.y + 0.3);
    }
  }
}

