    [
      [0.72, 0.26, 0.15], [0.92, 0.32, 0.90], [1.10, 0.46, 0.12]
    ]
  ];

  for (let cc of creamCurves) {
    drawSymPinstripe(cc, CREAM_BASE, CREAM_CORE, 0.96, true);
  }

  const cyanAccents = [
    [
      [0.0, -0.84, 0.12], [0.06, -0.72, 0.75], [0.0, -0.58, 0.12]
    ],
    [
      [0.22, 0.04, 0.12], [0.44, 0.14, 0.80], [0.56, 0.28, 0.65], [0.46, 0.38, 0.12]
    ],
