  brush.noField();

  for (let y = horizonY; y < 825; y += 3.4) {
    let t = map(y, horizonY, 825, 0, 1);
    let col;
    if (t < 0.2) {
      col = lerpColor(color("#b2bfca"), color("#8b99a7"), t / 0.2);
    } else if (t < 0.55) {
      col = lerpColor(color("#8b99a7"), color("#667380"), (t - 0.2) / 0.35);
    } else {
      col = lerpColor(color("#667380"), color("#424c57"), (t - 0.55) / 0.45);
    }
    let leftX = getAPillarX(y) + 10;
    brush.set("soft_blend", col, random(0.65, 1.1));
    brush.line(leftX, y, 1190, y + random(-1.5, 1.5));

    let swellWave = sin(pow(t, 0.65) * 720 + noise(y * 0.03) * 90);
    let pencilCol = swellWave > 0
      ? lerpColor(col, color("#d4dfe8"), 0.25 * swellWave)
      : lerpColor(col, color("#333b44"), -0.28 * swellWave);
    brush.set("color_pencil", pencilCol, random(0.35, 0.7));
    for (let s = 0; s < 3; s++) {
      let sx = random(leftX, 1020);
      let len = random(90, 260) * (0.5 + 0.7 * t);
      brush.line(sx, y + random(-1, 1), min(1190, sx + len), y + random(-1, 1));
    }
  }

  const pierStartX = 355;
  const pierEndX = 1195;
  const pierDeckY = 463;

  for (let x = pierStartX; x < pierEndX; x += 4.5) {
    let pNorm = map(x, pierStartX, pierEndX, 0, 1);
    let reflDepth = map(pNorm, 0, 1, 24, 62) * random(0.75, 1.2);
    let reflCol = lerpColor(color("#626d78"), color("#47505a"), pNorm * 0.8);
    brush.set("color_pencil", reflCol, random(0.3, 0.55));
    brush.line(x + random(-1, 1), horizonY + 3, x + random(-2, 2), horizonY + 3 + reflDepth);
  }
  for (let y = horizonY + 5; y < horizonY + 65; y += 3.5) {
    let c = lerpColor(color("#9aa7b3"), color("#74828f"), map(y, horizonY, horizonY + 65, 0, 1));
    brush.set("color_pencil", c, 0.42);
    brush.line(pierStartX - 20, y, pierEndX, y + random(-0.5, 0.5));
  }

  brush.noStroke();
  brush.wash("#6b747f", 95);
  brush.beginShape(0.2);
  brush.vertex(740, horizonY);
  brush.vertex(830, horizonY - 9);
  brush.vertex(960, horizonY - 14);
  brush.vertex(1100, horizonY - 18);
  brush.vertex(1195, horizonY - 16);
  brush.vertex(1195, horizonY + 2);
  brush.endShape(true);
  brush.noWash();

  let pilingX = pierStartX;
  while (pilingX < pierEndX) {
    let pNorm = map(pilingX, pierStartX, pierEndX, 0, 1);
    let deckY = pierDeckY - pNorm * 5;
    let baseY = horizonY + 2 + pNorm * 5;
    let pCol = lerpColor(color("#555e68"), color("#394048"), pNorm);

    brush.set("color_pencil", pCol, map(pNorm, 0, 1, 0.38, 0.78));
    brush.line(pilingX, deckY, pilingX, baseY);
    brush.set("color_pencil", lerpColor(pCol, color("#68737f"), 0.35), map(pNorm, 0, 1, 0.3, 0.6));
    brush.line(pilingX + 2.5 + pNorm * 2, deckY + 1, pilingX + 2.5 + pNorm * 2, baseY);

    let step = map(pNorm, 0, 1, 7.5, 19);
    if (pilingX + step < pierEndX && random() < 0.75) {
      brush.set("2H", pCol, 0.28);
      brush.line(pilingX, deckY + 2, pilingX + step, baseY - 1);
      brush.line(pilingX + step, deckY + 2, pilingX, baseY - 1);
    }
    pilingX += step;
  }

  for (let k = 0; k < 6; k++) {
    let dy = k * 0.9;
    let deckCol = k < 2 ? "#626b75" : "#404750";
    brush.set("color_pencil", deckCol, 0.55);
    brush.line(pierStartX - 2, pierDeckY + dy, pierEndX, pierDeckY - 5 + dy);
  }

  const sheds = [
    { x: 372, w: 26, h: 11, roofH: 6, c: "#4e5660", rc: "#5d6671" },
    { x: 545, w: 48, h: 15, roofH: 9, c: "#464e58", rc: "#57606b" },
    { x: 602, w: 24, h: 11, roofH: 5, c: "#4c545e", rc: "#5d6670" }
  ];
  for (let sh of sheds) {
    let pNorm = map(sh.x, pierStartX, pierEndX, 0, 1);
    let by = pierDeckY - pNorm * 5;
    brush.set("color_pencil", sh.c, 0.45);
    for (let sx = sh.x; sx <= sh.x + sh.w; sx += 2.2) {
      brush.line(sx, by, sx, by - sh.h);
    }
    brush.set("color_pencil", sh.rc, 0.48);
    for (let r = 0; r <= 1; r += 0.15) {
      let ry = by - sh.h - r * sh.roofH;
      let rx1 = sh.x - 2 + r * (sh.w * 0.35);
      let rx2 = sh.x + sh.w + 2 - r * (sh.w * 0.35);
      brush.line(rx1, ry, rx2, ry);
    }
  }

  const lampXs = [362, 430, 505, 590, 685, 795, 920, 1060];
  for (let lx of lampXs) {
    let pNorm = map(lx, pierStartX, pierEndX, 0, 1);
    let by = pierDeckY - pNorm * 5;
    let lh = map(pNorm, 0, 1, 12, 21);
    brush.set("2H", "#505963", 0.32);
    brush.line(lx, by, lx, by - lh);
    brush.set("soft_blend", "#e8c89e", 0.32);
    brush.line(lx - 2, by - lh, lx + 2, by - lh);
    brush.set("white_pencil", "#f7e4c8", 0.38);
    brush.line(lx - 0.6, by - lh, lx + 0.6, by - lh);
  }

  for (let i = 0; i < 38; i++) {
    let my = random(horizonY - 28, horizonY + 26);
    let mx1 = random(240, 750);
    let mx2 = min(1190, mx1 + random(180, 460));
    brush.set("soft_blend", "#c4d0da", random(0.45, 0.85));
    brush.line(mx1, my, mx2, my + random(-1, 1));
  }
  pop();
}

// ===========================================================================
// WIPER KINEMATICS & POLAR GEOMETRY
// ===========================================================================
function getWiperPoint(s, thetaDeg, normalOffset = 0) {
  let xRest = WIPER_PIVOT_X - s;
  let yRest = getRestingWiperY(xRest);
  let dx0 = -s;
  let dy0 = (yRest - WIPER_PIVOT_Y) + normalOffset;
  let c = cos(thetaDeg);
  let sn = sin(thetaDeg);
  return [
    WIPER_PIVOT_X + dx0 * c - dy0 * sn,
    WIPER_PIVOT_Y + dx0 * sn + dy0 * c
  ];
}

// Evaluate wiper angle at frame index f (0..47)
function getWiperAngle(f) {
  if (f <= 0) return 0;
  const peakFrame = 28;
  const maxAng = 50.5;
  if (f <= peakFrame) {
    let u = f / peakFrame;
    // Smooth, immediate ease-in from rest and gentle deceleration into apex
    let s = 0.5 - 0.5 * cos(pow(u, 0.84) * 180);
    return maxAng * s;
  } else {
    let v = (f - peakFrame) / (47 - peakFrame);
    let sDown = 0.5 - 0.5 * cos(pow(v, 1.05) * 162);
    return maxAng - 40.2 * sDown;
  }
}

// Convert windshield point (x, y) into wiper polar coordinates (s, clockwiseAngleDeg)
function getPointWiperPolar(x, y) {
  let dx = x - WIPER_PIVOT_X;
  let dy = y - WIPER_PIVOT_Y;
  let s = sqrt(dx * dx + dy * dy);
  let xRest = WIPER_PIVOT_X - min(s, WIPER_MAX_S);
  let yRest = getRestingWiperY(xRest);
  let baseAng = atan2(yRest - WIPER_PIVOT_Y, -min(s, WIPER_MAX_S));
  let ptAng = atan2(dy, dx);
  let cwAng = (ptAng - baseAng + 360) % 360;
  if (cwAng > 180) cwAng -= 360;
  return { s, cwAng };
}

// Check if wiper swept across (s, cwAng) between frame fStart and fEnd
function didWiperCrossBetween(s, cwAng, fStart, fEnd) {
  if (s > WIPER_MAX_S + 6 || cwAng < -3 || cwAng > 51.5) return false;
  let startF = max(1, ceil(fStart));
  for (let k = startF; k <= fEnd; k++) {
    let a0 = getWiperAngle(k - 1);
    let a1 = getWiperAngle(k);
    let minA = min(a0, a1) - 1.4;
    let maxA = max(a0, a1) + 1.4;
    if (cwAng >= minA && cwAng <= maxA) return k;
  }
  return 0;
}

// ===========================================================================
// INITIALIZE MOTION ASSETS ONCE ON FRAME 2
// ===========================================================================
function initMotionAssets() {
  // 1. Render the clean glass backdrop (Paper + Sky + Ocean + Pier)
  paintClearBackdrop();
  clearSceneImg = get();

  // 2. Create 2D offscreen compositor
  compPg = createGraphics(1200, 1200);
  compPg.pixelDensity(1);

  randomSeed(9102);
  noiseSeed(9102);

  // 3. Select heavy droplets from savedDroplets to slide down the glass
  let candidates = [];
  for (let i = 0; i < savedDroplets.length; i++) {
    let d = savedDroplets[i];
    if (d.isTerminal) {
      candidates.push({ d, priority: 100 });
    } else if (d.r >= 11.5 && d.y < 660) {
      candidates.push({ d, priority: d.r + (d.x > 600 && d.y < 420 ? 8 : 0) });
    } else if (d.r >= 8.2 && d.y < 360 && d.x > 640) {
      candidates.push({ d, priority: d.r + 5 });
    }
  }
  candidates.sort((a, b) => b.priority - a.priority);

  let chosen = [];
  for (let c of candidates) {
    if (chosen.length >= 26) break;
    let tooClose = false;
    for (let ch of chosen) {
      if (dist(c.d.x, c.d.y, ch.x, ch.y) < 58) {
        tooClose = true;
        break;
      }
    }
    if (!tooClose) chosen.push(c.d);
  }

  // Lift each sliding droplet's exact pixel patch from stillImg and precompute its trajectory
  for (let idx = 0; idx < chosen.length; idx++) {
    let d = chosen[idx];
    let rx = d.rx || d.r;
    let ry = d.ry || d.r * d.sag;
    let pad = ceil(max(rx, ry) * 1.45) + 4;
    let pw = pad * 2;
    let ph = pad * 2;

    // Extract masked elliptical droplet patch from stillImg using a tiny 2D canvas
    let patchPg = createGraphics(pw, ph);
    patchPg.pixelDensity(1);
    let pctx = patchPg.drawingContext;
    pctx.save();
    pctx.beginPath();
    pctx.ellipse(pad, pad + ry * 0.08, rx * 1.18 + 1.5, ry * 1.24 + 2.0, 0, 0, Math.PI * 2);
    pctx.clip();
    pctx.drawImage(
      stillImg.canvas,
      d.x - pad, d.y - pad, pw, ph,
      0, 0, pw, ph
    );
    pctx.restore();

    // Start frame & speed profile
    let startFrame = d.isTerminal ? 0 : (idx < 10 ? floor(random(0, 3)) : floor(random(1, 9)));
    let baseSpeed = d.isTerminal
      ? random(6.2, 8.8)
      : map(d.r, 8, 22, 4.2, 7.6) * random(0.88, 1.15);
    let driftRate = random(-0.28, -0.05);
    let seed = 3000 + idx * 97;

    // Precompute 48-frame trajectory & check if/when the wiper sweeps across it
    let traj = [];
    let cx = d.x;
    let cy = d.y;
    let hitFrame = 999;

    for (let f = 0; f < TOTAL_FRAMES; f++) {
      if (f > startFrame) {
        let dt = f - startFrame;
        // Smooth ease-in over first 3 frames after release, plus natural coalescing surges
        let ramp = constrain(dt / 3.0, 0.28, 1.0);
        let surge = 1.0 + 0.32 * sin(dt * 24 + idx * 47);
        let stepY = baseSpeed * ramp * surge;
        let stepX = driftRate + (noise(seed + f * 0.12) - 0.5) * 1.6;
        cx += stepX;
        cy += stepY;
      }

      let maxAllowedY = getDashY(cx) - 22 - ry;
      if (cy > maxAllowedY) cy = maxAllowedY;

      let pol = getPointWiperPolar(cx, cy);
      if (hitFrame === 999 && f >= 1) {
        let crossed = didWiperCrossBetween(pol.s, pol.cwAng, f - 1, f);
        if (crossed > 0) {
          hitFrame = crossed;
        }
      }

      traj.push({
        f,
        x: cx,
        y: cy,
        s: pol.s,
        cwAng: pol.cwAng
      });
    }

    // Generate deterministic satellite beads along this trajectory
    let satBeads = [];
    for (let f = startFrame + 2; f < min(TOTAL_FRAMES, hitFrame); f += 3) {
      let pt = traj[f];
      if (dist(pt.x, pt.y, d.x, d.y) > d.r * 0.8) {
        let side = ((f + idx) % 2 === 0) ? -1 : 1;
        let bx = pt.x + side * (rx * 0.62 + random(1.5, 4.0));
        let by = pt.y + random(-2, 2);
        let polB = getPointWiperPolar(bx, by);
        satBeads.push({
          x: bx,
          y: by,
          r: random(1.8, 3.3),
          fCreated: f,
          s: polB.s,
          cwAng: polB.cwAng
        });
      }
    }

    slidingDrops.push({
      x0: d.x,
      y0: d.y,
      r: d.r,
      rx,
      ry,
      pad,
      patchPg,
      startFrame,
      hitFrame,
      traj,
      satBeads,
      seed
    });
  }

  // 4. Schedule fresh coastal drizzle droplets landing in the wiped zone
  for (let i = 0; i < 18; i++) {
    let isAfterPeak = i >= 7;
    let landFrame = isAfterPeak ? floor(random(27, 42)) : floor(random(10, 24));
    // Pick a polar coordinate inside the wiped sector that the wiper has already passed
    let targetS = random(180, 840);
    let targetAng = isAfterPeak ? random(24, 48) : random(4, 22);
    let [fx, fy] = getWiperPoint(targetS, targetAng, 0);
    if (isOnWindshield(fx, fy, 12)) {
      freshDrops.push({
        x: fx,
        y: fy,
        r: random(2.4, 5.4),
        landFrame,
        slideSpeed: random() < 0.45 ? random(1.2, 2.8) : 0,
        seed: 7000 + i * 53
      });
    }
  }

  assetsInitialized = true;
}

// ===========================================================================
// BUILD 2D COMPOSITE FOR FRAME f (WIPED SECTOR + RUNNEL WAKES + SLIDING PATCHES)
// ===========================================================================
function buildFrameComposite(f) {
  let ctx = compPg.drawingContext;
  ctx.clearRect(0, 0, 1200, 1200);

  // 1. Base is the exact Frame 0 still painting
  ctx.drawImage(stillImg.canvas, 0, 0);

  // 2. Clip strictly to the open windshield glass polygon so cabin/dials/wheel are untouched
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(getAPillarX(0) + 5, getRoofY(getAPillarX(0) + 5));
  for (let y = 20; y <= 820; y += 25) {
    ctx.lineTo(getAPillarX(y) + 5, y);
  }
  for (let x = 75; x <= 1200; x += 25) {
    ctx.lineTo(x, getDashY(x) + 1);
  }
  ctx.lineTo(1200, 140);
  ctx.lineTo(1055, 134);
  ctx.lineTo(1035, 98);
  ctx.lineTo(1045, 58);
  for (let x = 1040; x >= 220; x -= 40) {
    ctx.lineTo(x, getRoofY(x) + 1);
  }
  ctx.closePath();
  ctx.clip();

  // 3. Carve clear glass wakes along all sliding droplets (erasing static origin + swallowed beads)
  ctx.save();
  ctx.beginPath();
  for (let sd of slidingDrops) {
    let activeF = min(f, sd.hitFrame);
    let curPt = sd.traj[activeF];
    let movedDist = dist(sd.x0, sd.y0, curPt.x, curPt.y);
    if (movedDist > 0.4) {
      // Erase static droplet at origin (sd.x0, sd.y0)
      ctx.moveTo(sd.x0 + sd.rx * 1.22, sd.y0 + sd.ry * 0.08);
      ctx.ellipse(sd.x0, sd.y0 + sd.ry * 0.08, sd.rx * 1.22 + 2, sd.ry * 1.28 + 2.5, 0, 0, Math.PI * 2);

      // Erase path corridor down to curPt
      let hw = sd.rx * 0.92;
      ctx.moveTo(sd.x0 - hw, sd.y0);
      for (let k = sd.startFrame; k <= activeF; k++) {
        ctx.lineTo(sd.traj[k].x - hw, sd.traj[k].y);
      }
      for (let k = activeF; k >= sd.startFrame; k--) {
        ctx.lineTo(sd.traj[k].x + hw, sd.traj[k].y + sd.ry * 0.35);
      }
      ctx.closePath();
    }
  }
  ctx.clip();
  ctx.drawImage(clearSceneImg.canvas, 0, 0);
  ctx.restore();

  // 4. Wiper Swept Fan Sector (reveals clearSceneImg over the entire arc swept up to frame f)
  let thetaMax = 0;
  for (let k = 1; k <= f; k++) {
    thetaMax = max(thetaMax, getWiperAngle(k));
  }

  if (thetaMax > 0.1) {
    ctx.save();
    ctx.beginPath();
    // Bottom edge along resting wiper blade bottom
    for (let s = 0; s <= WIPER_MAX_S; s += 30) {
      let [px, py] = getWiperPoint(s, 0, 21);
      if (s === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    // Outer tip arc from 0 to thetaMax
    for (let a = 0; a <= thetaMax; a += 2.0) {
      let [px, py] = getWiperPoint(WIPER_MAX_S + 2, a, 0);
      ctx.lineTo(px, py);
    }
    // Upper edge along thetaMax ray back to pivot
    for (let s = WIPER_MAX_S; s >= 0; s -= 30) {
      let [px, py] = getWiperPoint(s, thetaMax, -3);
      ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.clip();

    // Draw clear glass background inside the wiped sector
    ctx.drawImage(clearSceneImg.canvas, 0, 0);

    // Subtle cool wet-glass optical contrast glaze on the freshly wiped region
    ctx.fillStyle = "rgba(34, 43, 54, 0.065)";
    ctx.fillRect(0, 0, 1200, 900);
    ctx.restore();
  }

  // 5. Stamp the lifted sliding droplet patches at their current positions (if not yet wiped)
  for (let sd of slidingDrops) {
    if (f < sd.hitFrame) {
      let pt = sd.traj[f];
      let prevPt = sd.traj[max(0, f - 1)];
      let vy = constrain(pt.y - prevPt.y, 0, 12);
      // Slight vertical elongation when sliding fast
      let stretchY = 1.0 + vy * 0.009;
      let stretchX = 1.0 - vy * 0.003;
      let dw = sd.patchPg.width * stretchX;
      let dh = sd.patchPg.height * stretchY;
      ctx.drawImage(
        sd.patchPg.canvas,
        pt.x - dw * 0.5,
        pt.y - dh * 0.5,
        dw,
        dh
      );
    }
  }

  ctx.restore();
}

// ===========================================================================
// HELPER: DRAW A SINGLE DROPLET LENS IN COLOURED PENCIL
// ===========================================================================
function paintPencilDrop(x, y, r, seedVal) {
  randomSeed(seedVal);
  noiseSeed(seedVal);
  let rx = r * 0.98;
  let ry = r * 1.04;
  let dialX = 462, dialY = 1085;
  let distToDial = dist(x, y, dialX, dialY - 180);
  let amberFactor = constrain(map(y, 440, 800, 0, 1), 0, 1) *
                    constrain(map(distToDial, 520, 80, 0, 1), 0, 1);

  if (r < 3.4) {
    brush.set("color_pencil", "#2b323b", 0.36);
    brush.line(x - rx * 0.75, y - ry * 0.45, x + rx * 0.75, y - ry * 0.45);
    let bellyCol = amberFactor > 0.25 ? "#f5ba72" : "#d8e4ed";
    brush.set("color_pencil", bellyCol, 0.38);
    brush.line(x - rx * 0.6, y + ry * 0.38, x + rx * 0.6, y + ry * 0.38);
    brush.set("white_pencil", "#ffffff", 0.48);
    brush.line(x - rx * 0.38, y - ry * 0.32, x + rx * 0.15, y - ry * 0.36);
  } else {
    brush.set("color_pencil", "#363e48", 0.38);
    brush.spline(makeDropArc(x, y + ry * 0.18, rx * 0.92, ry * 0.95, 25, 155, 4), 0.5);
    brush.set("color_pencil", "#2b333d", 0.44);
    brush.spline(makeDropArc(x, y, rx * 0.84, ry * 0.84, 195, 345, 4), 0.5);
    brush.set("color_pencil", "#d8e6f0", 0.46);
    brush.spline(makeDropArc(x, y, rx * 0.80, ry * 0.78, 30, 150, 4), 0.5);
    if (amberFactor > 0.12) {
      brush.set("color_pencil", "#f2a855", 0.44);
      brush.spline(makeDropArc(x, y, rx * 0.84, ry * 0.84, 55, 135, 3), 0.5);
    }
    brush.set("white_pencil", "#ffffff", 0.62);
    brush.line(x - rx * 0.42, y - ry * 0.42, x + rx * 0.08, y - ry * 0.48);
  }
}

// ===========================================================================
// MAIN FILM LOOP (48 FRAMES AT 24 FPS)
// ===========================================================================
function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  // -------------------------------------------------------------------------
  // FRAME 0 (frameCount === 1): Exact pixel-for-pixel still painting
  // -------------------------------------------------------------------------
  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // -------------------------------------------------------------------------
  // FRAME 1+ (frameCount >= 2): Initialize motion assets once, then animate
  // -------------------------------------------------------------------------
  if (!assetsInitialized) {
    initMotionAssets();
  }

  let f = frameCount - 1; // f = 1..47
  let theta = getWiperAngle(f);
  let prevTheta = getWiperAngle(f - 1);
  let isMovingUp = theta >= prevTheta;

  let thetaMax = 0;
  for (let k = 1; k <= f; k++) {
    thetaMax = max(thetaMax, getWiperAngle(k));
  }

  // 1. Build & stamp the 2D composite backdrop
  buildFrameComposite(f);
  background("#7b8087");
  image(compPg, -width / 2, -height / 2);
  translate(-width / 2, -height / 2);

  const horizonY = 468;
  const dialX = 462;
  const dialY = 1085;

  // =========================================================================
  // 2. P5.BRUSH OVERLAYS: SLIDING DROPLET RUNNEL BORDERS, BEADS & GLINTS
  // =========================================================================
  for (let sd of slidingDrops) {
    randomSeed(sd.seed);
    noiseSeed(sd.seed);

    let maxF = min(f, sd.hitFrame);
    let edgeW = sd.rx * 0.68;

    // Draw newly carved runnel borders for segments not yet wiped by the blade
    for (let k = max(1, sd.startFrame + 1); k <= maxF; k++) {
      let p1 = sd.traj[k - 1];
      let p2 = sd.traj[k];
      if (dist(p1.x, p1.y, p2.x, p2.y) < 0.5) continue;

      // Check if wiper swept over this trail segment after frame k
      if (didWiperCrossBetween(p2.s, p2.cwAng, k, f) > 0) continue;

      let wakeCol = p2.y < horizonY ? "#7c8998" : "#566370";
      brush.set("soft_blend", wakeCol, 0.42);
      brush.line(p1.x, p1.y, p2.x, p2.y);

      brush.set("color_pencil", "#cad6e0", 0.27);
      brush.line(p1.x - edgeW, p1.y, p2.x - edgeW, p2.y);
      brush.line(p1.x + edgeW, p1.y, p2.x + edgeW, p2.y);
    }

    // Draw satellite micro-beads left along the runnel margins
    for (let sb of sd.satBeads) {
      if (f >= sb.fCreated) {
        if (didWiperCrossBetween(sb.s, sb.cwAng, sb.fCreated, f) === 0) {
          paintPencilDrop(sb.x, sb.y, sb.r, sd.seed + sb.fCreated * 13);
        }
      }
    }

    // Dynamic catchlight shimmer & lower-windshield amber glow on active sliding droplet head
    if (f < sd.hitFrame && f > sd.startFrame) {
      let pt = sd.traj[f];
      randomSeed(sd.seed + 500);
      noiseSeed(sd.seed + 500);

      let distToDial = dist(pt.x, pt.y, dialX, dialY - 180);
      let amberFactor = constrain(map(pt.y, 420, 790, 0, 1), 0, 1) *
                        constrain(map(distToDial, 520, 80, 0, 1), 0, 1);

      if (amberFactor > 0.08) {
        let ambCol = lerpColor(color("#e08538"), color("#ffd484"), amberFactor);
        brush.set("color_pencil", ambCol, 0.52 * (0.4 + 0.6 * amberFactor));
        brush.spline(makeDropArc(pt.x, pt.y, sd.rx * 0.85, sd.ry * 0.88, 50, 130, 4), 0.5);
      }

      // Crisp white-pencil catchlight riding on the moving droplet dome
      brush.set("white_pencil", "#ffffff", map(sd.r, 8, 22, 0.62, 0.95));
      brush.spline(makeDropArc(pt.x, pt.y, sd.rx * 0.58, sd.ry * 0.58, 220, 265, 3), 0.5);
    }
  }

  // =========================================================================
  // 3. FRESH COASTAL DRIZZLE DROPLETS LANDING ON WIPED GLASS
  // =========================================================================
  for (let fd of freshDrops) {
    if (f >= fd.landFrame) {
      let age = f - fd.landFrame;
      let curY = fd.y + age * fd.slideSpeed;
      let pol = getPointWiperPolar(fd.x, curY);
      // Only visible if wiper hasn't swept over it since it landed
      if (didWiperCrossBetween(pol.s, pol.cwAng, fd.landFrame + 1, f) === 0) {
        randomSeed(fd.seed);
        noiseSeed(fd.seed);
        if (age <= 2) {
          // Tiny landing ripple ring
          let rr = fd.r * map(age, 0, 2, 0.7, 1.35);
          brush.set("white_pencil", "#e6f0f8", 0.45);
          brush.arc(fd.x, curY, rr, 0, 360);
        }
        paintPencilDrop(fd.x, curY, fd.r, fd.seed);
      }
    }
  }

  // =========================================================================
  // 4. WIPED-GLASS OUTER WATER RIDGE & CURVED WET DRAG STREAKS
  // =========================================================================
  if (thetaMax > 2.0) {
    randomSeed(8421);
    noiseSeed(8421);

    // Outer arc ridge at s = WIPER_MAX_S where wiper tip pushed dew aside
    let outerArcPts = [];
    for (let a = 1; a <= thetaMax; a += 3.0) {
      outerArcPts.push(getWiperPoint(WIPER_MAX_S + 2, a, 0));
    }
    if (outerArcPts.length >= 2) {
      brush.set("color_pencil", "#485462", 0.42);
      brush.spline(outerArcPts, 0.4);
      let innerArcPts = outerArcPts.map(p => [p[0] + 2.5, p[1] + 1.5]);
      brush.set("color_pencil", "#cad8e4", 0.46);
      brush.spline(innerArcPts, 0.4);
    }

    // Beaded water droplets pushed along the outer arc boundary
    for (let a = 2.5; a <= thetaMax - 1; a += 3.6) {
      let [bx, by] = getWiperPoint(WIPER_MAX_S + 2 + random(-1.5, 1.5), a, 0);
      if (isOnWindshield(bx, by, 4)) {
        paintPencilDrop(bx, by, random(2.2, 4.2), 8500 + floor(a * 10));
      }
    }

    // Subtle circular wet water-film drag arcs trailing behind the moving wiper blade
    let streakRadii = [190, 275, 360, 445, 535, 620, 710, 795, 865];
    for (let idx = 0; idx < streakRadii.length; idx++) {
      let sr = streakRadii[idx];
      let trailSpan = 13;
      let aStart = isMovingUp ? max(1, theta - trailSpan) : theta + 1;
      let aEnd = isMovingUp ? theta - 1 : min(thetaMax, theta + trailSpan);

      if (aEnd - aStart > 2.5) {
        let sPts = [];
        for (let a = aStart; a <= aEnd; a += 2.5) {
          sPts.push(getWiperPoint(sr, a, 0));
        }
        if (sPts.length >= 2) {
          brush.set("color_pencil", idx % 2 === 0 ? "#b8c7d4" : "#586675", 0.28);
          brush.spline(sPts, 0.45);
        }
      }
    }
  }

  // =========================================================================
  // 5. THE MOVING WINDSHIELD WIPER BLADE, TRUSS & PLOWED WATER RIDGE
  // =========================================================================
  randomSeed(6210);
  noiseSeed(6210);

  // 5A. Glistening ridge of collected water & foam beads pushed ahead of the blade lip
  let ridgeOffset = isMovingUp ? -3.2 : 17.5;
  let ridgePts = [];
  for (let s = 40; s <= WIPER_MAX_S; s += 45) {
    ridgePts.push(getWiperPoint(s, theta, ridgeOffset));
  }
  brush.set("soft_blend", "#9eb0c0", 0.55);
  brush.spline(ridgePts, 0.4);
  brush.set("color_pencil", "#dce8f2", 0.48);
  brush.spline(ridgePts, 0.4);

  // Sparkling water beads & absorption splashes riding along the wiper's leading edge
  for (let s = 55; s < WIPER_MAX_S - 10; s += random(14, 28)) {
    let [wx, wy] = getWiperPoint(s, theta, ridgeOffset);
    if (wy < getDashY(wx) - 2) {
      let br = random(2.0, 4.2);
      brush.set("color_pencil", "#28303a", 0.38);
      brush.line(wx - br, wy, wx + br, wy);
      brush.set("white_pencil", "#ffffff", random(0.52, 0.78));
      brush.line(wx - br * 0.5, wy - 1, wx + br * 0.4, wy - 1);
    }
  }

  // Extra splash glints when a heavy sliding droplet is swept up by the blade
  for (let sd of slidingDrops) {
    if (f >= sd.hitFrame && f <= sd.hitFrame + 3) {
      let hitPt = sd.traj[sd.hitFrame];
      let [sx, sy] = getWiperPoint(hitPt.s, theta, ridgeOffset - 2);
      brush.set("soft_blend", "#dbe7f0", 0.55);
      brush.line(sx - 12, sy - 4, sx + 12, sy + 4);
      brush.set("white_pencil", "#ffffff", 0.78);
      brush.line(sx - 8, sy - 2, sx + 8, sy + 2);
    }
  }

  // 5B. Dark rubber blade & articulated metal frame (cross-strokes + longitudinal splines)
  for (let s = 0; s <= WIPER_MAX_S; s += 4.5) {
    let bladeThick = s > 260 ? 15 : map(s, 0, 260, 22, 15);
    let [x1, y1] = getWiperPoint(s, theta, 0);
    let [x2, y2] = getWiperPoint(s, theta, bladeThick);
    let dashLim1 = getDashY(x1) + 2;
    let dashLim2 = getDashY(x2) + 2;
    if (y1 < dashLim1 || y2 < dashLim2) {
      brush.set("charcoal", "#1e2228", 0.65);
      brush.line(x1, min(y1, dashLim1), x2, min(y2, dashLim2));
    }
  }

  for (let offset = 0; offset <= 15; offset += 2.2) {
    let pts = [];
    for (let s = 0; s <= WIPER_MAX_S + 5; s += 45) {
      let [px, py] = getWiperPoint(s, theta, offset);
      pts.push([px, min(py, getDashY(px) + 3)]);
    }
    let col = offset < 3 ? "#8e9ba8" : (offset < 8 ? "#323842" : "#1a1e24");
    let brName = offset < 3 ? "color_pencil" : "2B";
    brush.set(brName, col, offset < 3 ? 0.54 : 0.65);
    brush.spline(pts, 0.4);
  }

  // 5C. Secondary upper wiper bracket truss & connecting struts
  let bracketPts = [];
  let bracketHiPts = [];
  for (let xOrig = 340; xOrig <= 760; xOrig += 35) {
    let s = WIPER_PIVOT_X - xOrig;
    let u = map(xOrig, 340, 760, 0, 1);
    let arch = 11 * sin(u * 180);
    bracketPts.push(getWiperPoint(s, theta, -arch));
    bracketHiPts.push(getWiperPoint(s, theta, -arch - 1.5));
  }
  brush.set("2B", "#252a32", 0.75);
  brush.spline(bracketPts, 0.4);
  brush.set("color_pencil", "#7f8c99", 0.44);
  brush.spline(bracketHiPts, 0.4);

  // Articulated claw struts between bracket arch and main blade
  for (let sStrut of [360, 490, 620]) {
    let [bx, by] = getWiperPoint(sStrut, theta, -9);
    let [tx, ty] = getWiperPoint(sStrut, theta, 2);
    brush.set("2B", "#22272f", 0.6);
    brush.line(bx, by, tx, ty);
  }

  // 5D. Warm amber reflection along underside bevel of the moving wiper near the binnacle
  let amberFade = constrain(map(theta, 0, 42, 1.0, 0.25), 0.25, 1.0);
  let wiperAmberPts = [];
  for (let xOrig = 250; xOrig <= 680; xOrig += 30) {
    let s = WIPER_PIVOT_X - xOrig;
    wiperAmberPts.push(getWiperPoint(s, theta, 12.5));
  }
  let ambBladeCol = lerpColor(color("#593a24"), color("#e68a3e"), amberFade);
  brush.set("color_pencil", ambBladeCol, 0.48 * (0.4 + 0.6 * amberFade));
  brush.spline(wiperAmberPts, 0.4);

  // 5E. Re-tuck the right wiper pivot cleanly under the dashboard cowl edge
  randomSeed(7711);
  noiseSeed(7711);
  for (let r = 0; r < 14; r += 3.2) {
    let cowlPts = [];
    for (let x = 820; x <= 1140; x += 32) {
      cowlPts.push([x, getDashY(x) + r]);
    }
    let col = r < 8
      ? lerpColor(color("#6e7b88"), color("#3f4752"), r / 8)
      : lerpColor(color("#3f4752"), color("#20242b"), (r - 8) / 24);
    brush.set("color_pencil", col, 0.56);
    brush.spline(cowlPts, 0.4);
  }

  // =========================================================================
  // 6. SUBTLE ENGINE-IDLE NEEDLE RESPONSE & WARM AMBER SHIMMER ON DASHBOARD
  // =========================================================================
  randomSeed(9933);
  noiseSeed(9933);

  const dialR = 114;
  // Subtle living idle breathe on the speedometer/tachometer needle
  let idleDelta = 1.15 * sin(f * 15) + 0.55 * sin(f * 33);
  let needleAng = 166 + idleDelta;
  let nxTip = dialX + (dialR - 6) * cos(needleAng);
  let nyTip = dialY + (dialR - 6) * sin(needleAng);

  // Darken old needle line slightly so the subtly quivering needle reads cleanly
  let oldTipX = dialX + (dialR - 6) * cos(166);
  let oldTipY = dialY + (dialR - 6) * sin(166);
  brush.set("charcoal", "#1c1512", 0.55);
  brush.line(dialX + 16 * cos(166), dialY + 16 * sin(166), oldTipX, oldTipY);

  // Repaint glowing idle needle and center cap
  brush.set("soft_blend", "#eb7328", 0.7);
  brush.line(dialX, dialY, nxTip, nyTip);
  brush.set("color_pencil", "#ff9e44", 0.85);
  brush.line(dialX, dialY, nxTip, nyTip);
  brush.set("white_pencil", "#fff2d1", 0.65);
  brush.line(dialX, dialY, nxTip, nyTip);

  brush.set("color_pencil", "#2b201b", 0.8);
  brush.circle(dialX, dialY, 14, 0.05);
  brush.set("color_pencil", "#f29b48", 0.52);
  brush.arc(dialX, dialY, 15, 190, 340);
}

08-pod:
// MOTION: The wide-eyed child in the convex screen leans closer, blinks, and fogs the glass with breath as a glowing CRT raster wave sweeps the visor and the chrome antenna swivels.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

const DEG2RAD = Math.PI / 180;

// Core geometry anchors (1200 x 1200 canvas)
const HORIZON_Y = 858;
const TV_CX = 588;
const TV_CY = 492;
const TV_RX = 368;
const TV_RY = 358;

// Convex CRT screen center & radii (tilted slightly left/forward)
const SCR_CX = 546;
const SCR_CY = 476;
const SCR_RX = 256;
const SCR_RY = 246;

// Cached Frame 0 snapshot & deterministic surface details captured during paintStill()
let stillImg = null;
let cleanAntennaPatch = null;
let cachedFingerprints = [];
let cachedScreenDust = [];
let cachedLintFibers = [];
let isCapturingStill = false;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(701971);
  noiseSeed(701971);

  // Scale built-in brushes for 1200x1200 canvas before registering precision custom brushes
