function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  // Frame 0 (frameCount === 1): Render the exact still pixel-for-pixel and snapshot it
  if (frameCount === 1) {
    isCapturingStill = true;
    paintStill();
    isCapturingStill = false;
    stillImg = get();
    return;
  }

  // Build the clean wall patch behind the top loop antenna once on frameCount === 2
  if (!cleanAntennaPatch && stillImg) {
    cleanAntennaPatch = buildCleanAntennaWallPatch(stillImg, 480, 46, 210, 82);
  }

  const t = (frameCount - 1) / window.PIECE_FPS;

  // Stamp the cached still backdrop and clean wall patch before any p5.brush calls
  background("#faf3e3");
  translate(-width / 2, -height / 2);
  image(stillImg, 0, 0);
  if (cleanAntennaPatch) {
    image(cleanAntennaPatch, 480, 46);
  }

  brush.noField();

  // 1. Top chrome loop antenna swiveling smoothly in 3D on its crown mount
  renderAnimatedTopAntenna(t);

  // 2. Side recessed tuning bar knob rotating to tune the Space-Age set
  renderAnimatedSideTunerPod(t);

  // 3. Dynamic CRT turquoise & tangerine light bounce on the terrazzo floor & pedestal
  renderAnimatedFloorAndPedestalGlow(t);

  // 4. Inner cream visor bezel & black rubber CRT gasket with active screen radiosity
  renderAnimatedVisorBezelAndGasket(t);

  // 5. Convex CRT screen: parallax window, leaning/blinking child reflection & rolling CRT raster wave
  renderAnimatedScreenAndChild(t);

  // 6. Breath condensation mist, surface glass highlights, cached fingerprints & drifting dust motes
  renderAnimatedScreenSurface(t);
}

// ============================================================================
// EXACT STILL PAINTING (FRAME 0)
// ============================================================================

function paintStill() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Clean bright daylight background wall & sunbeam atmosphere
  renderDaylightWall();

  // 2. White shag-free terrazzo floor in low worm's-eye perspective
  renderTerrazzoFloor();

  // 3. Floor cast shadow & glowing tangerine/turquoise bounce reflections
  renderFloorReflectionsAndShadow();

  // 4. Top chrome loop antenna & side recessed tuning pod (behind/flanking shell)
  renderTopChromeAntenna();
  renderSideTunerPod();

  // 5. Chrome silver swivel pedestal & neck gimbal assembly
  renderChromePedestal();

  // 6. Monumental tangerine fibreglass astronaut-helmet shell & mould seams
  renderTangerineHelmetShell();

  // 7. Recessed cream inner visor frame & deep black rubber CRT gasket
  renderVisorInnerBezelAndGasket();

  // 8. Convex grey CRT screen & distorted fisheye reflection (window + child's wide-eyed face)
  renderConvexScreenAndReflections();

  // 9. Snapped pure-white marker highlights, fingerprint smudge & static dust motes
  renderGlossHighlightsAndSurfaceRealism();
}

// ============================================================================
// ANIMATION HELPERS & CHOREOGRAPHY (FRAMES 1..47)
// ============================================================================

function easeInOutCubic(x) {
  x = constrain(x, 0, 1);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function easeOutCubic(x) {
  x = constrain(x, 0, 1);
  return 1 - Math.pow(1 - x, 3);
}

function fastStartEase(t, duration) {
  // Responsive motion curve: already clearly underway by frame 2-6, smooth arrival
  let u = constrain(t / duration, 0, 1);
  return Math.pow(u, 1.18) * (2.0 - Math.pow(u, 1.18));
}

// Builds a seamless horizontal wall interpolation patch behind the top chrome antenna
function buildCleanAntennaWallPatch(srcImg, px, py, pw, ph) {
  let patch = createImage(pw, ph);
  srcImg.loadPixels();
  patch.loadPixels();
  let sw = srcImg.width;

  for (let y = 0; y < ph; y++) {
    let sy = py + y;
    let leftIdx = (sy * sw + px) * 4;
    let rightIdx = (sy * sw + (px + pw - 1)) * 4;
    let r0 = srcImg.pixels[leftIdx];
    let g0 = srcImg.pixels[leftIdx + 1];
    let b0 = srcImg.pixels[leftIdx + 2];
    let r1 = srcImg.pixels[rightIdx];
    let g1 = srcImg.pixels[rightIdx + 1];
    let b1 = srcImg.pixels[rightIdx + 2];

    for (let x = 0; x < pw; x++) {
      let u = x / (pw - 1);
      let dstIdx = (y * pw + x) * 4;
      patch.pixels[dstIdx] = Math.round(r0 + (r1 - r0) * u);
      patch.pixels[dstIdx + 1] = Math.round(g0 + (g1 - g0) * u);
      patch.pixels[dstIdx + 2] = Math.round(b0 + (b1 - b0) * u);
      patch.pixels[dstIdx + 3] = 255;
    }
  }
  patch.updatePixels();
  return patch;
}

function renderAnimatedTopAntenna(t) {
  randomSeed(810101);
  noiseSeed(810101);

  const antCX = TV_CX - 4;
  const antCY = 92;

  // 3D swivel motion: immediate turn within first 6 frames, sweeping through 54 degrees
  let swivel = fastStartEase(t, 1.35) * 52 - 14 * Math.max(0, (t - 1.25) / 0.75);
  let yawRad = swivel * DEG2RAD;
  let outerRX = 88 * (0.48 + 0.52 * Math.cos(yawRad));
  let outerRY = 33 + 3.2 * Math.sin(yawRad * 0.9);
  let rot = -3 + 5.2 * Math.sin(yawRad);
  let tubeThicknessX = 4.2 * Math.sin(yawRad);
