  // Secondary 3D rim edge when loop turns in perspective
  if (Math.abs(tubeThicknessX) > 0.4) {
    drawArcStroke("micro_pen", "#2c3740", 4.5, antCX + tubeThicknessX, antCY + 0.8, outerRX, outerRY, -180, 180, 26, rot, 0.95);
