  // Outer chrome loop shadow & base silver
  for (let w = 13; w >= 3; w -= 2.5) {
    let col = w > 10 ? "#36424d" : (w > 6 ? "#9eadb8" : "#e8f1f5");
    drawArcStroke("micro_pen", col, w, antCX, antCY, outerRX, outerRY, -180, 180, 28, rot, 1.0);
  }

  // Travelling chrome reflections inside the antenna ring
  drawArcStroke("gloss_marker_thin", "#ff6624", 1.2, antCX, antCY + 2, outerRX, outerRY, 15 + specShift * 0.4, 165 + specShift * 0.4, 18, rot, 0.9);
  drawArcStroke("gloss_marker_thin", "#2bd9ed", 1.1, antCX, antCY - 2, outerRX, outerRY, -165 + specShift * 0.4, -20 + specShift * 0.4, 18, rot, 0.9);
  drawArcStroke("micro_pen", "#182026", 2.2, antCX, antCY, outerRX, outerRY, -175 + specShift * 0.6, -110 + specShift * 0.6, 12, rot, 0.9);
  drawArcStroke("micro_pen", "#182026", 2.2, antCX, antCY, outerRX, outerRY, -60 + specShift * 0.6, 10 + specShift * 0.6, 12, rot, 0.9);

  // Pure white specular glints sliding along the swiveling loop
  drawArcStroke("gloss_marker_thin", "#ffffff", 1.45, antCX, antCY - 1, outerRX, outerRY, -150 + specShift * 0.85, -75 + specShift * 0.85, 12, rot, 1.0);
  drawArcStroke("gloss_marker_thin", "#ffffff", 1.25, antCX, antCY + 1, outerRX, outerRY, 35 - specShift * 0.7, 115 - specShift * 0.7, 12, rot, 1.0);

  // Chrome pedestal boss mounting the antenna to the helmet crown
  washEllipse(antCX, 131, 34, 11, "#2a333b", 235);
  washEllipse(antCX - 4 + tubeThicknessX * 0.35, 129, 26, 8, "#cfdbe3", 225);
