  washEllipse(antCX - 9 + tubeThicknessX * 0.5, 128, 12, 4, "#ffffff", 245);
}

function renderAnimatedSideTunerPod(t) {
  randomSeed(810202);
  noiseSeed(810202);

  const podCX = 936;
  const podCY = 514;
  const podRX = 42;
  const podRY = 108;
  const rot = -7;

  // Repaint recessed brushed dark-silver dial plate to cleanly cover the t=0 knob
  washEllipse(podCX - 4, podCY, podRX - 10, podRY - 16, "#1f272e", 252, 36, rot);
  washEllipse(podCX - 2, podCY + 2, podRX - 13, podRY - 22, "#52606b", 220, 36, rot);

  // Rotary tuning bar angle: clicks/turns smoothly through 58 degrees
  let dialDeg = fastStartEase(t, 1.05) * 58 + 6 * Math.sin(t * 3.8);
  let rad = dialDeg * DEG2RAD;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);

  // Helper to project a 2D point on the circular dial face into the foreshortened pod ellipse
  function projectKnobPt(kx, ky, depthX = 0) {
    let rx = kx * ca - ky * sa;
    let ry = kx * sa + ky * ca;
    return [
      podCX + depthX + rx * 0.38,
      podCY + ry * 0.98 + rx * 0.12
    ];
  }

  // Base shadow & body of the rotated tuning bar
  let basePoly = [
    projectKnobPt(-11, -36, -6),
    projectKnobPt(11, -36, 12),
    projectKnobPt(11, 34, 12),
    projectKnobPt(-11, 34, -6)
  ];
  let chromePoly = [
    projectKnobPt(-8, -32, -3),
    projectKnobPt(9, -32, 10),
    projectKnobPt(9, 30, 10),
    projectKnobPt(-8, 30, -3)
  ];
  let tangPoly = [
    projectKnobPt(0, -28, 4),
    projectKnobPt(9, -28, 10),
    projectKnobPt(9, 26, 10),
    projectKnobPt(0, 26, 4)
  ];

  washPoly(basePoly, "#161c22", 245, 0.15);
  washPoly(chromePoly, "#d8e4ec", 235, 0.15);
  washPoly(tangPoly, "#ff5519", 215, 0.1);

  let hiA = projectKnobPt(-5, -30, -1);
  let hiB = projectKnobPt(8, -30, 8);
  brush.set("micro_pen", "#ffffff", 1.4);
  brush.line(hiA[0], hiA[1], hiB[0], hiB[1]);
  brush.noStroke();
}

