function renderAnimatedScreenAndChild(t) {
  randomSeed(810505);
  noiseSeed(810505);

  // --------------------------------------------------------------------------
  // A. Base Convex Grey CRT Glass Dome
  // --------------------------------------------------------------------------
  let screenOutline = visorOpeningPoly(SCR_CX, SCR_CY, SCR_RX, SCR_RY, 72);
  washPoly(screenOutline, "#1b2229", 255, 0.25);

  for (let i = 0; i < 18; i++) {
    let f = i / 17;
    let s = lerp(0.98, 0.22, f);
    let ox = lerp(0, -32, f);
    let oy = lerp(0, -28, f);
    let col = f < 0.35 ? "#252e37" : (f < 0.75 ? "#333f4a" : "#43525e");
    washPoly(visorOpeningPoly(SCR_CX + ox, SCR_CY + oy, SCR_RX * s, SCR_RY * s, 56), col, 22, 0.25);
  }

  drawArcStroke("airbrush_fine", "#637785", 1.2, SCR_CX, SCR_CY, SCR_RX - 5, SCR_RY - 5, 110, 245, 18, 0, 0.9);

  // --------------------------------------------------------------------------
  // B. Curvilinear Distorted Reflection of Sunlit Picture Window (with Parallax)
  // --------------------------------------------------------------------------
  // As the child leans in and the helmet swivels slightly, the reflected room/window shifts in parallax
  let pLean = fastStartEase(t, 1.25);
  let winShiftU = 0.042 * pLean + 0.014 * Math.sin(t * 2.4);
  let winShiftV = 0.022 * pLean;

  washPoly(screenGridPoly(0.36 + winShiftU, -0.92, 0.96, 0.22 + winShiftV, 6, 8), "#7a786e", 55, 0.2);
  washPoly(screenGridPoly(0.42 + winShiftU, -0.82, 0.92, 0.12 + winShiftV, 6, 8), "#a69e8e", 45, 0.2);
  washPoly(screenGridPoly(0.46 + winShiftU, -0.58, 0.95, 0.28 + winShiftV, 6, 8), "#2c6d7a", 50, 0.2);

  washPoly(screenGridPoly(-0.92, 0.24 + winShiftV, 0.92, 0.95, 10, 6), "#4f5250", 65, 0.2);
  washPoly(screenGridPoly(-0.78, 0.36 + winShiftV, 0.78, 0.92, 10, 6), "#7d796e", 55, 0.2);
  washPoly(screenGridPoly(-0.62, 0.48 + winShiftV, 0.52, 0.88, 8, 5), "#a89f8e", 45, 0.2);

  const winCols = [
    [-0.91 + winShiftU, -0.45 + winShiftU],
    [-0.41 + winShiftU, 0.01 + winShiftU],
    [0.05 + winShiftU, 0.43 + winShiftU]
  ];
  const winRows = [
    [-0.92 + winShiftV * 0.5, -0.55 + winShiftV],
    [-0.50 + winShiftV, 0.09 + winShiftV]
  ];

  for (let i = 0; i < 6; i++) {
    let pad = i * 0.035;
    washPoly(
      screenGridPoly(-0.93 + winShiftU - pad, -0.94 - pad, 0.46 + winShiftU + pad, 0.12 + winShiftV + pad, 10, 8),
      "#8cebf7",
      18,
      0.25
    );
  }

  for (let r = 0; r < winRows.length; r++) {
    for (let c = 0; c < winCols.length; c++) {
      let u0 = winCols[c][0];
      let u1 = winCols[c][1];
      let v0 = winRows[r][0];
      let v1 = winRows[r][1];

      let baseCol = r === 0
        ? (c === 0 ? "#6beaf7" : (c === 1 ? "#2ad4e8" : "#0faec4"))
        : (c === 0 ? "#ffffff" : (c === 1 ? "#c7f8ff" : "#7cebf7"));
      let baseAlpha = r === 0 ? 155 : (c === 0 ? 225 : 175);

      washPoly(screenGridPoly(u0, v0, u1, v1, 7, 6), baseCol, baseAlpha, 0.2);

      if (r === 1) {
        washPoly(screenGridPoly(u0, -0.12 + winShiftV, u1, v1, 6, 4), "#fff6db", c === 0 ? 210 : 155, 0.2);
        washPoly(screenGridPoly(u0, -0.02 + winShiftV, u1, v1, 6, 4), "#ffe4b3", 95, 0.2);
      }
    }
  }

  for (let i = 0; i < 8; i++) {
    let f = i / 7;
    let u0 = lerp(-0.88, -0.62, f) + winShiftU;
    let u1 = lerp(0.12, -0.25, f) + winShiftU;
    let v0 = lerp(-0.82, -0.52, f) + winShiftV;
    let v1 = lerp(0.06, -0.18, f) + winShiftV;
    washPoly(screenGridPoly(u0, v0, u1, v1, 6, 6), "#ffffff", 26, 0.25);
  }

  const mullionUs = [-0.91 + winShiftU, -0.43 + winShiftU, 0.03 + winShiftU, 0.44 + winShiftU];
  for (let idx = 0; idx < mullionUs.length; idx++) {
    randomSeed(810510 + idx);
    noiseSeed(810510 + idx);
    let u = mullionUs[idx];
    let pts = [];
    for (let k = 0; k <= 12; k++) {
      let v = -0.92 + winShiftV * 0.5 + (1.02 * k) / 12;
      let p = screenProject(u, v);
      pts.push([p[0], p[1], 0.9]);
    }
    brush.set("micro_pen", "#263842", 1.8);
    brush.spline(pts, 0.45);
    let ptsHi = pts.map(p => [p[0] + 1.5, p[1], 0.8]);
    brush.set("micro_pen", "#dff9fc", 0.95);
    brush.spline(ptsHi, 0.45);
  }

  const transomVs = [-0.92 + winShiftV * 0.5, -0.525 + winShiftV, 0.095 + winShiftV];
  for (let idx = 0; idx < transomVs.length; idx++) {
    randomSeed(810520 + idx);
    noiseSeed(810520 + idx);
    let v = transomVs[idx];
    let pts = [];
    for (let k = 0; k <= 14; k++) {
      let u = -0.91 + winShiftU + (1.35 * k) / 14;
      let p = screenProject(u, v);
      pts.push([p[0], p[1], 0.9]);
    }
    brush.set("micro_pen", "#263842", 1.8);
    brush.spline(pts, 0.45);
    let ptsHi = pts.map(p => [p[0], p[1] + 1.5, 0.8]);
    brush.set("micro_pen", "#dff9fc", 0.95);
    brush.spline(ptsHi, 0.45);
  }
  brush.noStroke();

  // --------------------------------------------------------------------------
  // C. Sweeping CRT Phosphor Raster Wave (Behind/Through Reflection)
  // --------------------------------------------------------------------------
  let crtRamp = Math.min(1, t / 0.16);
  // Sweeps from top (v = -0.78) to bottom (v = +0.85) in ~1.05s, then a second harmonic wave
  let scanCycle = (t * 0.94) % 1.0;
  let scanV = lerp(-0.78, 0.82, scanCycle);

  if (crtRamp > 0.01) {
    // Broad atomic-turquoise & warm tangerine cathode-ray phosphor band
    for (let i = 0; i < 6; i++) {
      let halfH = 0.24 - i * 0.032;
      let v0 = constrain(scanV - halfH, -0.92, 0.92);
      let v1 = constrain(scanV + halfH, -0.92, 0.92);
      if (v1 > v0 + 0.01) {
        let uSpan = Math.sqrt(Math.max(0.08, 0.90 - scanV * scanV * 0.65));
        let col = i < 2 ? "#29d8eb" : (i < 4 ? "#8cf6ff" : "#ffffff");
        washPoly(screenGridPoly(-uSpan, v0, uSpan, v1, 10, 3), col, Math.round((14 + i * 5) * crtRamp), 0.2);
      }
    }
    // Warm tangerine sub-carrier trail just above the scan bar
    let trailV0 = constrain(scanV - 0.30, -0.92, 0.92);
    let trailV1 = constrain(scanV - 0.08, -0.92, 0.92);
    if (trailV1 > trailV0 + 0.01) {
      washPoly(screenGridPoly(-0.82, trailV0, 0.82, trailV1, 8, 3), "#ff6a26", Math.round(18 * crtRamp), 0.2);
    }
  }

  // --------------------------------------------------------------------------
  // D. The Animated Child's Wide-Eyed Face (Leaning In, Tracking Eyes & Blinking)
  // --------------------------------------------------------------------------
  renderAnimatedChildFace(t, pLean, scanV, crtRamp);

  // --------------------------------------------------------------------------
  // E. Active CRT Scanline Sheen & Fresnel Rim Shadow
  // --------------------------------------------------------------------------
  for (let k = -18; k <= 18; k++) {
    randomSeed(810600 + k + 25);
    noiseSeed(810600 + k + 25);
    let v = k * 0.05;
    let uMax = Math.sqrt(Math.max(0.05, 0.92 - v * v));
    let distToScan = Math.abs(v - scanV);
    let isScanCrest = distToScan < 0.09 && crtRamp > 0.1;

    let pts = [];
    for (let s = 0; s <= 12; s++) {
      let u = -uMax + (2 * uMax * s) / 12;
      // Subtle horizontal deflection ripple along the active CRT scan bar
      let rippleV = isScanCrest ? v + 0.008 * Math.sin(s * 0.9 + t * 18) : v;
      let p = screenProject(u, rippleV);
      pts.push([p[0], p[1], isScanCrest ? 0.95 : 0.6]);
    }
    let scanCol = isScanCrest ? "#b8fbff" : (k % 2 === 0 ? "#12181e" : "#4b5f6b");
    let scanW = isScanCrest ? 0.78 : 0.45;
    brush.set("micro_pen", scanCol, scanW);
    brush.spline(pts, 0.45);
  }
  brush.noStroke();

  for (let i = 0; i < 9; i++) {
    randomSeed(810700 + i);
    noiseSeed(810700 + i);
    let inset = i * 3.2;
    drawArcStroke("airbrush_fine", "#0d1217", 1.6 - i * 0.14, SCR_CX, SCR_CY, SCR_RX - inset, SCR_RY - inset, -180, 180, 32, 0, 1.0);
  }
}

function renderAnimatedChildFace(t, pLean, scanV, crtRamp) {
  // Motion parameters for the child reflected in the convex fisheye lens:
  // 1. Head lean & nonlinear fisheye magnification (starts immediately, unmistakable by 1s)
  let headScale = 1.0 + 0.21 * pLean;
  let noseExtraScale = 1.0 + 0.31 * pLean; // Nose is closest to convex mirror -> magnifies most!
  let headShiftU = -0.038 * pLean + 0.022 * Math.sin(t * 2.7);
  let headShiftV = -0.024 * pLean + 0.012 * Math.sin(t * 1.9);
  let headTiltDeg = -4.2 * Math.sin(Math.min(1, t / 1.15) * Math.PI * 0.75) + 2.8 * Math.max(0, (t - 1.1) / 0.9);
  let caH = Math.cos(headTiltDeg * DEG2RAD);
  let saH = Math.sin(headTiltDeg * DEG2RAD);

  // 2. Eye saccade / gaze tracking:
  // First 0.28s: eyes dart up-left to catch the incoming CRT scan bar;
  // 0.28s..1.15s: eyes sweep across and down following the glowing wave;
  // 1.15s..2.0s: eyes lock center-left in wide-eyed wonder.
  let gazeU = 0;
  let gazeV = 0;
  if (t < 0.32) {
    let u = easeOutCubic(t / 0.32);
    gazeU = -0.036 * u;
    gazeV = -0.026 * u;
  } else if (t < 1.18) {
    let u = easeInOutCubic((t - 0.32) / 0.86);
    gazeU = lerp(-0.036, 0.044, u);
    gazeV = lerp(-0.026, 0.020, u);
  } else {
    let u = easeInOutCubic((t - 1.18) / 0.82);
    gazeU = lerp(0.044, -0.014, u);
    gazeV = lerp(0.020, -0.008, u);
  }

  // 3. Expressive blink between t = 0.54s and t = 0.78s (frames 14..19), then wider eyes!
  let blink = 0;
  if (t > 0.54 && t < 0.78) {
    let bu = (t - 0.54) / 0.24;
    blink = Math.pow(Math.sin(bu * Math.PI), 1.4);
  }
  let postBlinkWide = t > 0.66 ? easeOutCubic(Math.min(1, (t - 0.66) / 0.45)) : 0;
  let browLift = 0.016 * pLean + 0.022 * postBlinkWide - 0.012 * blink;
  let mouthOpen = pLean * 1.15 + 0.25 * postBlinkWide;

  // Transform a point (u, v) in the child's head frame around pivot (0.02, 0.08)
  function xformHeadUV(u, v, localScale = headScale) {
    let du = (u - 0.02) * localScale;
    let dv = (v - 0.08) * localScale;
    let ru = du * caH - dv * saH;
    let rv = du * saH + dv * caH;
    return [0.02 + headShiftU + ru, 0.08 + headShiftV + rv];
  }

  function xformCurvePoly(uvPts, localScale = headScale) {
    let pts = [];
    for (let i = 0; i < uvPts.length; i++) {
      let tuv = xformHeadUV(uvPts[i][0], uvPts[i][1], localScale);
      pts.push(screenProject(tuv[0], tuv[1]));
    }
    return pts;
  }

  function washHeadUVEllipse(uc, vc, ru, rv, col, alpha, n = 32, rotDeg = 0, localScale = headScale) {
    let uvPts = [];
    let ca = Math.cos(rotDeg * DEG2RAD);
    let sa = Math.sin(rotDeg * DEG2RAD);
    for (let i = 0; i < n; i++) {
      let a = (i / n) * Math.PI * 2;
      let du = Math.cos(a) * ru;
      let dv = Math.sin(a) * rv;
      let u = uc + du * ca - dv * sa;
      let v = vc + du * sa + dv * ca;
      uvPts.push(xformHeadUV(u, v, localScale));
    }
    washPoly(screenCurvePoly(uvPts), col, alpha, 0.3);
  }

  // 1. Backlit halo around the child's head against the bright window reflection
  for (let i = 0; i < 7; i++) {
    let s = 1.0 + i * 0.045;
    washHeadUVEllipse(0.02, 0.08, 0.56 * s, 0.56 * s, "#b8f4fc", 14, 36, 0, headScale);
  }

  // 2. Child's shoulders & Space-Age ringer T-shirt at bottom of screen
  let shScale = 1.0 + 0.12 * pLean;
  washPoly(xformCurvePoly([
    [-0.68, 0.92], [-0.54, 0.68], [-0.24, 0.58],
    [0.28, 0.58], [0.58, 0.68], [0.72, 0.92],
    [0.35, 0.96], [-0.35, 0.96]
  ], shScale), "#1b2830", 160, 0.25);

  washPoly(xformCurvePoly([
    [-0.48, 0.88], [-0.36, 0.69], [0.02, 0.64],
    [0.40, 0.69], [0.52, 0.88], [0.02, 0.94]
  ], shScale), "#8fa3ad", 85, 0.25);
  washPoly(xformCurvePoly([
    [-0.28, 0.64], [0.02, 0.72], [0.32, 0.64],
    [0.26, 0.59], [0.02, 0.66], [-0.22, 0.59]
  ], shScale), "#1ebbd1", 95, 0.25);

  // 3. Tousled Hair & Cranium Silhouette
  const hairUV = [
    [-0.56, 0.16], [-0.62, -0.06], [-0.58, -0.28], [-0.42, -0.44],
    [-0.18, -0.52], [0.08, -0.53], [0.34, -0.47], [0.52, -0.32],
    [0.61, -0.10], [0.58, 0.15], [0.46, 0.28], [-0.44, 0.28]
  ];
  washPoly(xformCurvePoly(hairUV, headScale * 0.98), "#19181b", 190, 0.3);
  washPoly(xformCurvePoly(hairUV.map(p => [p[0] * 0.94, p[1] * 0.94]), headScale * 0.98), "#29201d", 145, 0.3);

  washHeadUVEllipse(-0.22, -0.42, 0.26, 0.11, "#8c4d2b", 75, 28, -18, headScale * 0.98);
  washHeadUVEllipse(-0.36, -0.30, 0.18, 0.12, "#d47c42", 70, 24, -35, headScale * 0.98);
  washHeadUVEllipse(-0.12, -0.47, 0.22, 0.06, "#ffe4b5", 95, 24, -8, headScale * 0.98);
  washHeadUVEllipse(0.24, -0.42, 0.20, 0.07, "#6be3f2", 65, 24, 16, headScale * 0.98);

  // Ears peeking through hair
  washHeadUVEllipse(-0.52, 0.18, 0.07, 0.14, "#4a3832", 140, 20, -10, headScale * 0.96);
  washHeadUVEllipse(-0.51, 0.18, 0.05, 0.10, "#9e6248", 95, 20, -10, headScale * 0.96);
  washHeadUVEllipse(0.55, 0.18, 0.07, 0.14, "#2d282b", 150, 20, 10, headScale * 0.96);

  // 4. Child's Face Oval
  const faceUV = [
    [-0.44, -0.12], [-0.34, -0.30], [0.02, -0.34], [0.38, -0.30],
    [0.47, -0.12], [0.49, 0.14], [0.42, 0.38], [0.24, 0.56],
    [0.02, 0.63], [-0.20, 0.56], [-0.39, 0.38], [-0.47, 0.14]
  ];
  washPoly(xformCurvePoly(faceUV, headScale), "#2d2b2e", 175, 0.35);
  washPoly(xformCurvePoly(faceUV.map(p => [p[0] * 0.96, p[1] * 0.96]), headScale), "#4f3a34", 120, 0.35);

  for (let i = 0; i < 8; i++) {
    let f = i / 7;
    let s = lerp(0.95, 0.45, f);
    washHeadUVEllipse(-0.18, 0.14, 0.28 * s, 0.32 * s, f < 0.5 ? "#9c5238" : "#d9825b", 22);
    washHeadUVEllipse(0.24, 0.18, 0.25 * s, 0.28 * s, f < 0.5 ? "#423d42" : "#874b39", 22);
    washHeadUVEllipse(-0.04, -0.16, 0.32 * s, 0.15 * s, f < 0.5 ? "#ad7055" : "#e8b496", 20);
    washHeadUVEllipse(0.02, 0.53, 0.16 * s, 0.09 * s, "#b86b4d", 18);
  }

  // Tangerine radiosity glow on lower cheeks & nose underside (intensifies as child leans closer!)
  let tangBoost = Math.round(32 + 24 * pLean);
  washHeadUVEllipse(-0.28, 0.24, 0.16, 0.14, "#ff6b2b", tangBoost, 24, -12);
  washHeadUVEllipse(0.29, 0.25, 0.15, 0.13, "#ff5d1f", tangBoost - 4, 24, 12);
  washHeadUVEllipse(0.02, 0.31, 0.14, 0.07, "#ff6829", tangBoost, 24, 0);

  // Moving CRT raster light band illuminating the child's skin as the scan bar passes!
  if (crtRamp > 0.05 && scanV > -0.45 && scanV < 0.62) {
    washHeadUVEllipse(0.0, constrain(scanV, -0.28, 0.48), 0.36, 0.11, "#72f2ff", Math.round(28 * crtRamp), 28, 0);
  }

  for (let i = 0; i < 6; i++) {
    let s = 1.0 - i * 0.14;
    washHeadUVEllipse(-0.22, 0.18, 0.14 * s, 0.09 * s, "#ffd8bd", 22, 24, -14);
    washHeadUVEllipse(-0.14, -0.16, 0.18 * s, 0.08 * s, "#ffe7d1", 22, 24, -8);
    washHeadUVEllipse(0.02, 0.04, 0.055 * s, 0.13 * s, "#f5c5a6", 20, 20, 0);
  }

  // 5. Tousled Bangs Falling Across the Forehead (with slight secondary sway)
  let bangSway = 0.008 * Math.sin(t * 3.4 - 0.5);
  const bangLocks = [
    [[-0.44, -0.18], [-0.34, -0.34], [-0.20 + bangSway, -0.12], [-0.36 + bangSway, -0.08]],
    [[-0.24, -0.36], [-0.06, -0.38], [-0.08 + bangSway, -0.14], [-0.20 + bangSway, -0.16]],
    [[-0.04, -0.38], [0.16, -0.36], [0.10 + bangSway, -0.15], [-0.02 + bangSway, -0.18]],
    [[0.16, -0.36], [0.36, -0.28], [0.28 + bangSway, -0.10], [0.14 + bangSway, -0.16]],
    [[0.34, -0.28], [0.46, -0.12], [0.40 + bangSway, 0.02], [0.30 + bangSway, -0.12]]
  ];
  for (let i = 0; i < bangLocks.length; i++) {
    washPoly(xformCurvePoly(bangLocks[i], headScale), i < 2 ? "#2b1d17" : "#1c181a", 165, 0.3);
  }

  // 6. THE WIDE-EYED WONDER: Animated Gaze, Blinking Eyelids & Dilating Pupils
  let eyeScale = headScale * (1.0 + 0.04 * pLean);
  let openFactor = (1.0 + 0.09 * postBlinkWide) * (1.0 - 0.88 * blink);

  const eyes = [
    { uc: -0.215, vc: 0.025, rot: -7, isLeft: true, seed: 810810 },
    { uc: 0.255, vc: 0.025, rot: 7, isLeft: false, seed: 810820 }
  ];

  for (let e of eyes) {
    randomSeed(e.seed);
    noiseSeed(e.seed);

    let uc = e.uc;
    let vc = e.vc;
    let rot = e.rot;

    // Eye socket shadow & upper eyelid fold
    washHeadUVEllipse(uc, vc - 0.01, 0.165, 0.125, "#1f2229", 130, 28, rot, eyeScale);
    washHeadUVEllipse(uc, vc + 0.01, 0.15, 0.105, "#15191f", 180, 28, rot, eyeScale);

    // Wide-open sclera (modulated vertically by blink & post-blink wonder)
    washHeadUVEllipse(uc, vc, 0.132, 0.086 * openFactor, "#7b929e", 195, 30, rot, eyeScale);
    washHeadUVEllipse(uc - 0.01, vc - 0.004, 0.115, 0.074 * openFactor, "#bdd2dc", 185, 28, rot, eyeScale);
    washHeadUVEllipse(uc - 0.02, vc - 0.008, 0.092, 0.058 * openFactor, "#e6f4f9", 150, 24, rot, eyeScale);

    // Iris & pupil (shifted by gazeU, gazeV as the child's eyes track across the screen)
    let irisU = uc + (e.isLeft ? 0.012 : -0.012) + gazeU;
    let irisV = vc - 0.003 + gazeV * openFactor;
    let irisRV = 0.072 * openFactor;

    washHeadUVEllipse(irisU, irisV, 0.074, irisRV, "#121b21", 235, 28, 0, eyeScale);
    washHeadUVEllipse(irisU, irisV, 0.064, 0.062 * openFactor, "#2d5763", 215, 28, 0, eyeScale);
    washHeadUVEllipse(irisU + 0.005, irisV + 0.008 * openFactor, 0.052, 0.048 * openFactor, "#7d5130", 170, 24, 0, eyeScale);
    washHeadUVEllipse(irisU + 0.008, irisV + 0.014 * openFactor, 0.038, 0.032 * openFactor, "#c27d44", 135, 20, 0, eyeScale);

    // Radial iris fibers (visible when eye is open)
    if (openFactor > 0.35) {
      let irisCenter = screenProject(...xformHeadUV(irisU, irisV, eyeScale));
      for (let k = 0; k < 16; k++) {
        let ang = (k / 16) * Math.PI * 2;
        let pOut = screenProject(...xformHeadUV(
          irisU + Math.cos(ang) * 0.06,
          irisV + Math.sin(ang) * 0.058 * openFactor,
          eyeScale
        ));
        brush.set("micro_pen", k % 2 === 0 ? "#5bd6e6" : "#d99252", 0.55);
        brush.line(irisCenter[0], irisCenter[1], pOut[0], pOut[1]);
      }
      brush.noStroke();
    }

    // Deep pupil (constricts slightly as the bright CRT scan bar crosses the eyes, then dilates in wonder)
    let pupilPulse = 1.0 - 0.14 * Math.exp(-Math.pow((scanV - vc) / 0.18, 2)) + 0.08 * postBlinkWide;
    washHeadUVEllipse(irisU, irisV, 0.034 * pupilPulse, 0.033 * pupilPulse * openFactor, "#06080a", 250, 24, 0, eyeScale);

    // Corneal reflections of the sunlit picture window & glowing CRT bar!
    let glintU = irisU - 0.024 - gazeU * 0.35;
    let glintV = irisV - 0.022 * openFactor - gazeV * 0.35;
    washHeadUVEllipse(glintU, glintV, 0.024, 0.017 * openFactor, "#9ef4ff", 230, 16, -15, eyeScale);
    washHeadUVEllipse(glintU + 0.002, glintV + 0.002, 0.017, 0.012 * openFactor, "#ffffff", 255, 16, -15, eyeScale);
    washHeadUVEllipse(irisU + 0.020, irisV + 0.022 * openFactor, 0.015, 0.009 * openFactor, "#ff6d2b", 215, 14, 15, eyeScale);
    washHeadUVEllipse(irisU - 0.042, irisV + 0.018 * openFactor, 0.008, 0.006 * openFactor, "#ffffff", 210, 12, 0, eyeScale);

    // Moving CRT scan-bar reflection glint inside each cornea!
    if (crtRamp > 0.1 && openFactor > 0.4) {
      let crtCorneaV = irisV + constrain(scanV * 0.045, -0.04, 0.04) * openFactor;
      washHeadUVEllipse(irisU, crtCorneaV, 0.036, 0.006 * openFactor, "#80f8ff", Math.round(180 * crtRamp), 14, 0, eyeScale);
    }

    // Upper eyelid skin fold descending during the blink
    if (blink > 0.05) {
      washHeadUVEllipse(uc, vc - 0.02 * (1 - blink), 0.136, 0.082 * blink, "#59382e", Math.round(215 * blink), 28, rot, eyeScale);
    }

    // Tear duct & wet lower waterline
    let ductU = uc + (e.isLeft ? 0.118 : -0.118);
    washHeadUVEllipse(ductU, vc + 0.012, 0.018, 0.012 * openFactor, "#a84c42", 180, 12, 0, eyeScale);
    washHeadUVEllipse(ductU, vc + 0.010, 0.008, 0.006 * openFactor, "#ffffff", 220, 10, 0, eyeScale);

    // Upper eyelid lash line & crease (smoothly arches down during blink, opens higher after)
    let lashArch = lerp(-0.088 * (1.0 + 0.09 * postBlinkWide), 0.045, blink);
    let lashPts = [];
    let creasePts = [];
    for (let s = 0; s <= 10; s++) {
      let ang = (s / 10) * Math.PI;
      let du = -Math.cos(ang) * 0.138;
      let dv = Math.sin(ang) * lashArch;
      let pL = screenProject(...xformHeadUV(uc + du, vc + dv, eyeScale));
      let pC = screenProject(...xformHeadUV(uc + du * 1.06, vc - Math.sin(ang) * 0.11 * (1.0 - 0.45 * blink) - 0.018, eyeScale));
      lashPts.push([pL[0], pL[1], Math.sin(ang) * 1.1 + 0.2]);
      creasePts.push([pC[0], pC[1], Math.sin(ang) * 0.8 + 0.15]);
    }
    brush.set("micro_pen", "#0b0e12", 1.65);
    brush.spline(lashPts, 0.45);
    brush.set("micro_pen", "#1c1a1d", 1.05);
    brush.spline(creasePts, 0.45);

    // Raised arched eyebrow (lifts higher in wonder as child leans in!)
    let browPts = [];
    for (let s = 0; s <= 8; s++) {
      let f = s / 8;
      let bu = uc + (f - 0.5) * 0.27;
      let bv = vc - 0.145 - browLift - Math.sin(f * Math.PI) * (0.038 + 0.012 * postBlinkWide) + (e.isLeft ? -f * 0.015 : (1 - f) * -0.015);
      let pB = screenProject(...xformHeadUV(bu, bv, eyeScale));
      browPts.push([pB[0], pB[1], Math.sin(f * Math.PI) * 1.1 + 0.25]);
    }
    brush.set("airbrush_fine", "#221815", 0.9);
    brush.spline(browPts, 0.45);
    brush.noStroke();
  }

  // 7. Foreshortened Button Nose (magnifies strongly in the convex mirror as child leans in!)
  const noseU = 0.02 + gazeU * 0.12;
  const noseV = 0.205 + 0.012 * pLean;
  washHeadUVEllipse(noseU, noseV + 0.055, 0.115, 0.052, "#1c1a1e", 160, 24, 0, noseExtraScale);
  for (let i = 0; i < 7; i++) {
    let s = 1.0 - i * 0.12;
    washHeadUVEllipse(noseU, noseV, 0.105 * s, 0.078 * s, i < 3 ? "#8c4d38" : (i < 5 ? "#d18260" : "#ffd6b8"), 28, 24, 0, noseExtraScale);
  }
  washHeadUVEllipse(noseU - 0.018, noseV - 0.016, 0.036, 0.025, "#fff4e6", 130, 18, -12, noseExtraScale);
  washHeadUVEllipse(noseU - 0.020, noseV - 0.018, 0.016, 0.011, "#ffffff", 185, 14, -12, noseExtraScale);

  washHeadUVEllipse(noseU - 0.048, noseV + 0.042, 0.025, 0.015, "#0d1014", 225, 16, 18, noseExtraScale);
  washHeadUVEllipse(noseU + 0.048, noseV + 0.042, 0.025, 0.015, "#0d1014", 225, 16, -18, noseExtraScale);
  washHeadUVEllipse(noseU, noseV + 0.036, 0.028, 0.012, "#ff6e30", 85, 14, 0, noseExtraScale);

  // 8. Parted Lips Opening in an "Ooooh!" of Awe
  const mouthU = 0.02;
  const mouthV = 0.43 + 0.014 * pLean;
  let lipDrop = 0.024 * mouthOpen;
  let mouthNarrow = 1.0 - 0.08 * pLean;

  washHeadUVEllipse(mouthU, noseV + 0.11, 0.028, 0.038, "#302424", 90, 16, 0, headScale);

  // Upper lip (Cupid's bow)
  washPoly(xformCurvePoly([
    [mouthU - 0.155 * mouthNarrow, mouthV + 0.01],
    [mouthU - 0.065 * mouthNarrow, mouthV - 0.038 - lipDrop * 0.25],
    [mouthU, mouthV - 0.024 - lipDrop * 0.25],
    [mouthU + 0.065 * mouthNarrow, mouthV - 0.038 - lipDrop * 0.25],
    [mouthU + 0.155 * mouthNarrow, mouthV + 0.01],
    [mouthU, mouthV + 0.018 - lipDrop * 0.15]
  ], headScale), "#7a352e", 175, 0.3);

  // Lower lip dropping open in wonder
  washHeadUVEllipse(mouthU, mouthV + 0.036 + lipDrop, 0.135 * mouthNarrow, 0.044 + lipDrop * 0.25, "#9e463b", 165, 24, 0, headScale);
  washHeadUVEllipse(mouthU - 0.01, mouthV + 0.038 + lipDrop, 0.095 * mouthNarrow, 0.028 + lipDrop * 0.15, "#d9735f", 140, 20, 0, headScale);
  washHeadUVEllipse(mouthU - 0.02, mouthV + 0.036 + lipDrop, 0.048 * mouthNarrow, 0.014, "#ffd5c2", 160, 16, -5, headScale);

  // Parted mouth opening & upper teeth
  washHeadUVEllipse(mouthU, mouthV + 0.008 + lipDrop * 0.48, 0.098 * mouthNarrow, 0.022 + lipDrop * 0.62, "#121519", 230, 20, 0, headScale);
  washHeadUVEllipse(mouthU, mouthV + 0.002 - lipDrop * 0.08, 0.062 * mouthNarrow, 0.010 + lipDrop * 0.12, "#cad8de", 175, 16, 0, headScale);
}

function renderAnimatedScreenSurface(t) {
  randomSeed(810900);
  noiseSeed(810900);

  // --------------------------------------------------------------------------
  // A. Warm Breath Condensation Mist Blooming on the Cold Convex Glass
  // --------------------------------------------------------------------------
  if (t > 0.22) {
    let breathEnv = easeOutCubic(Math.min(1, (t - 0.22) / 0.85)) * (1.0 - 0.22 * Math.max(0, (t - 1.35) / 0.65));
    let fogScale = 0.45 + 0.65 * easeOutCubic(Math.min(1, (t - 0.22) / 1.1));
    let fogU = 0.01;
    let fogV = 0.34;

    for (let i = 0; i < 7; i++) {
      let s = (1.0 - i * 0.12) * fogScale;
      let uvPts = [];
      for (let k = 0; k < 28; k++) {
        let a = (k / 28) * Math.PI * 2;
        let rMod = 1.0 + 0.06 * Math.cos(3 * a + i);
        uvPts.push([
          fogU + Math.cos(a) * 0.26 * s * rMod,
          fogV + Math.sin(a) * 0.19 * s * rMod
        ]);
      }
      let col = i < 3 ? "#d8eef5" : "#fff9ed";
      let alpha = Math.round((9 + i * 2.2) * breathEnv);
      washPoly(screenCurvePoly(uvPts), col, alpha, 0.3);
    }
  }

  // --------------------------------------------------------------------------
  // B. Pure-White Glossy Surface Highlights on the Convex CRT Glass
  // --------------------------------------------------------------------------
  const glassHotspot = screenGridPoly(-0.84, -0.44, -0.48, -0.14, 6, 5);
  washPoly(glassHotspot, "#ffffff", 245, 0.25);

  let hotArc1 = [];
  let hotArc2 = [];
  for (let k = 0; k <= 10; k++) {
    let f = k / 10;
    let p1 = screenProject(lerp(-0.86, -0.46, f), lerp(-0.38, -0.46, f));
    let p2 = screenProject(lerp(-0.85, -0.52, f), lerp(-0.22, -0.30, f));
    hotArc1.push([p1[0], p1[1], Math.sin(f * Math.PI) * 1.0 + 0.2]);
    hotArc2.push([p2[0], p2[1], Math.sin(f * Math.PI) * 0.9 + 0.2]);
  }
  randomSeed(810910);
  noiseSeed(810910);
  brush.set("gloss_marker", "#ffffff", 0.95);
  brush.spline(hotArc1, 0.45);
  brush.set("gloss_marker_thin", "#ffffff", 1.1);
  brush.spline(hotArc2, 0.45);
  brush.noStroke();

  drawArcStroke("gloss_marker_thin", "#ffffff", 0.95, SCR_CX, SCR_CY, SCR_RX - 9, SCR_RY - 9, 24, 68, 14, 0, 0.95);

  // --------------------------------------------------------------------------
  // C. Cached Fingerprint Smudges on the Convex Screen (Zero Boiling / Teleport)
  // --------------------------------------------------------------------------
  for (let fpIdx = 0; fpIdx < cachedFingerprints.length; fpIdx++) {
    let fp = cachedFingerprints[fpIdx];
    randomSeed(810930 + fpIdx * 100);
    noiseSeed(810930 + fpIdx * 100);

    for (let i = 0; i < 6; i++) {
      let s = 1.15 - i * 0.14;
      washEllipse(fp.cx, fp.cy, fp.rx * s, fp.ry * s, i % 2 === 0 ? "#9cb6c4" : "#ffe8cc", 11, 28, fp.rotDeg);
    }
    let ca = Math.cos(fp.rotDeg * DEG2RAD);
    let sa = Math.sin(fp.rotDeg * DEG2RAD);
    washEllipse(fp.cx + sa * 12, fp.cy - ca * 12, fp.rx * 0.75, fp.ry * 0.9, "#8aa4b3", 9, 24, fp.rotDeg + 8);

    for (let rIdx = 0; rIdx < fp.ridges.length; rIdx++) {
      let ridge = fp.ridges[rIdx];
      randomSeed(810950 + fpIdx * 200 + rIdx);
      noiseSeed(810950 + fpIdx * 200 + rIdx);
      brush.set("micro_pen", ridge.col, 0.42);
      brush.spline(ridge.pts, 0.45);
    }
    brush.noStroke();
  }

  // --------------------------------------------------------------------------
  // D. Electrostatic Screen Dust Motes & Drifting Sunbeam Motes
  // --------------------------------------------------------------------------
  let scanCycle = (t * 0.94) % 1.0;
  let scanV = lerp(-0.78, 0.82, scanCycle);

  for (let i = 0; i < cachedScreenDust.length; i++) {
    let m = cachedScreenDust[i];
    randomSeed(812000 + i);
    noiseSeed(812000 + i);

    // Every 4th mote is an airborne mote drifting gently in the sunbeam toward the static screen;
    // the rest are static-clung on the glass and sparkle as the CRT scan bar passes behind them.
    let driftX = 0;
    let driftY = 0;
    if (i % 4 === 0) {
      let phase = i * 0.73;
      driftX = t * (6.5 + (i % 5) * 1.8) + 2.2 * Math.sin(t * 3.2 + phase);
      driftY = t * (4.2 + (i % 3) * 1.4) + 1.8 * Math.cos(t * 2.7 + phase);
    }
    let x = m.x + driftX;
    let y = m.y + driftY;

    // Sparkle boost when the sweeping CRT raster wave passes behind the mote
    let scanBoost = Math.abs(m.v - scanV) < 0.12 ? 1.35 : 1.0;
    let size = m.size * scanBoost;

    brush.set("dust_tip", "#4e626e", size * 0.45);
    brush.line(x + 2.2, y + 2.0, x + 2.2 + size * 0.5, y + 2.0 + size * 0.3);

    brush.set("dust_tip", scanBoost > 1.1 ? "#ffffff" : m.col, size * 0.62);
    brush.line(x, y, x + size * 0.65, y + size * 0.35);
  }

  for (let i = 0; i < cachedLintFibers.length; i++) {
    let lf = cachedLintFibers[i];
    randomSeed(813000 + i);
    noiseSeed(813000 + i);

    brush.set("micro_pen", "#425461", 0.38);
    brush.spline([[lf.x + 2.2, lf.y + 2.0, 0.3], [lf.midX + 2.2, lf.midY + 2.0, 0.6], [lf.endX + 2.2, lf.endY + 2.0, 0.3]], 0.5);

    brush.set("micro_pen", lf.col, 0.52);
    brush.spline([[lf.x, lf.y, 0.3], [lf.midX, lf.midY, 0.85], [lf.endX, lf.endY, 0.3]], 0.5);
  }

  brush.noStroke();
}

// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function washPoly(pts, col, alpha, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function ellipsePoly(cx, cy, rx, ry, n = 40, rotDeg = 0) {
  let pts = [];
  let ca = Math.cos(rotDeg * DEG2RAD);
  let sa = Math.sin(rotDeg * DEG2RAD);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ux = Math.cos(a) * rx;
    let uy = Math.sin(a) * ry;
    pts.push([cx + ux * ca - uy * sa, cy + ux * sa + uy * ca]);
  }
  return pts;
}

function washEllipse(cx, cy, rx, ry, col, alpha, n = 40, rotDeg = 0, curvature = 0.3) {
  washPoly(ellipsePoly(cx, cy, rx, ry, n, rotDeg), col, alpha, curvature);
}

function arcSplinePts(cx, cy, rx, ry, startDeg, endDeg, steps = 14, rotDeg = 0, peakPressure = 1.0) {
  let pts = [];
  let ca = Math.cos(rotDeg * DEG2RAD);
  let sa = Math.sin(rotDeg * DEG2RAD);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let deg = startDeg + (endDeg - startDeg) * t;
    let rad = deg * DEG2RAD;
    let ux = Math.cos(rad) * rx;
    let uy = Math.sin(rad) * ry;
    let x = cx + ux * ca - uy * sa;
    let y = cy + ux * sa + uy * ca;
    let p = Math.sin(t * Math.PI) * peakPressure + 0.12;
    pts.push([x, y, p]);
  }
  return pts;
}

function drawArcStroke(brushName, col, weight, cx, cy, rx, ry, startDeg, endDeg, steps = 14, rotDeg = 0, peakP = 1.0) {
  let pts = arcSplinePts(cx, cy, rx, ry, startDeg, endDeg, steps, rotDeg, peakP);
  brush.noFill();
  brush.noWash();
  brush.set(brushName, col, weight);
  brush.spline(pts, 0.45);
  brush.noStroke();
}

// Helmet outer silhouette generator (sculpted astronaut dome with slight visor cheek flare)
function helmetOuterPoly(n = 72, scaleX = 1.0, scaleY = 1.0, offX = 0, offY = 0) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ca = Math.cos(a);
    let sa = Math.sin(a);

    // Subtle aerodynamic helmet shaping: slightly broader cheek/jaw and flattened base neck
    let rModX = 1.0 + 0.028 * Math.sin(a) - 0.022 * Math.cos(2 * a);
    let rModY = 1.0 - (sa > 0.65 ? 0.045 * Math.pow((sa - 0.65) / 0.35, 1.6) : 0);
    // Left-front visor brow/cheek protrusion
    let visorBump = ca < -0.15 ? 0.025 * Math.exp(-Math.pow((sa + 0.08) / 0.65, 2)) : 0;

    let x = TV_CX + offX + ca * TV_RX * (rModX + visorBump) * scaleX;
    let y = TV_CY + offY + sa * TV_RY * rModY * scaleY;
    pts.push([x, y]);
  }
  return pts;
}

// Visor cowling opening polygon (slightly squared-circle Apollo faceplate contour)
function visorOpeningPoly(cx, cy, rx, ry, n = 64, superExp = 0.09) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ca = Math.cos(a);
    let sa = Math.sin(a);
    // Subtle squircle modulation so it reads like a moulded astronaut visor bezel
    let mod = 1.0 + superExp * Math.cos(4 * a) * 0.22 - 0.018 * Math.sin(a);
    pts.push([cx + ca * rx * mod, cy + sa * ry * mod]);
  }
  return pts;
}

// Curvilinear fisheye projection onto the convex CRT screen
function screenProject(u, v) {
  let r2 = u * u + v * v;
  // Barrel distortion of a spherical convex mirror
  let k = 0.62;
  let inv = 1.0 / Math.sqrt(1.0 + k * r2);
  // Slight worm's-eye upward Foreshortening inside the reflection
  let uProj = u * inv;
  let vProj = (v - 0.035 * (1.0 - Math.min(1.2, r2))) * inv;

  // Clamp strictly inside the glass boundary
  let mag = Math.sqrt(uProj * uProj + vProj * vProj);
  if (mag > 0.985) {
    uProj = (uProj / mag) * 0.985;
    vProj = (vProj / mag) * 0.985;
  }

  // Apply the slight squircle modulation of the CRT glass
  let ang = Math.atan2(vProj, uProj);
  let mod = 1.0 + 0.09 * Math.cos(4 * ang) * 0.22 - 0.018 * Math.sin(ang);

  return [
    SCR_CX + uProj * SCR_RX * mod,
    SCR_CY + vProj * SCR_RY * mod
  ];
}

function screenGridPoly(u0, v0, u1, v1, stepsU = 8, stepsV = 8) {
  let pts = [];
  for (let i = 0; i <= stepsU; i++) {
    pts.push(screenProject(u0 + (u1 - u0) * (i / stepsU), v0));
  }
  for (let j = 1; j <= stepsV; j++) {
    pts.push(screenProject(u1, v0 + (v1 - v0) * (j / stepsV)));
  }
  for (let i = stepsU - 1; i >= 0; i--) {
    pts.push(screenProject(u0 + (u1 - u0) * (i / stepsU), v1));
  }
  for (let j = stepsV - 1; j >= 1; j--) {
    pts.push(screenProject(u0, v0 + (v1 - v0) * (j / stepsV)));
  }
  return pts;
}

function screenCurvePoly(uvPts) {
  let pts = [];
  for (let i = 0; i < uvPts.length; i++) {
    pts.push(screenProject(uvPts[i][0], uvPts[i][1]));
  }
  return pts;
}

