function renderChromePedestal() {
  const baseCX = TV_CX;
  const bottomY = 926;
  const bottomRX = 228;
  const bottomRY = 35;

  const waistY = 876;
  const waistRX = 136;
  const waistRY = 20;

  const neckY = 844;
  const neckRX = 172;
  const neckRY = 27;

  // 1. Black rubber floor gasket rim at bottom of chrome trumpet base
  washEllipse(baseCX, bottomY + 6, bottomRX + 4, bottomRY + 3, "#14181d", 250, 48);
  drawArcStroke("micro_pen", "#6d7b87", 1.4, baseCX, bottomY + 5, bottomRX + 1, bottomRY + 1, 15, 165, 20, 0, 0.8);

  // 2. Chrome trumpet base body (silhouette connecting waist to bottom rim)
  let conePts = [];
  const steps = 28;
  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * Math.PI; // 0 to PI (front arc of bottom rim)
    conePts.push([baseCX + Math.cos(a) * bottomRX, bottomY + Math.sin(a) * bottomRY]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = (i / steps) * Math.PI; // PI to 0 (front arc of waist)
    conePts.push([baseCX + Math.cos(a) * waistRX, waistY + Math.sin(a) * waistRY]);
  }
  washPoly(conePts, "#c4d0d9", 255, 0.15);

  // Hyperreal chrome reflection bands across the trumpet base:
  // A. Warm cream terrazzo floor reflection along the lower lip
  for (let i = 0; i < 6; i++) {
    let t = i / 5;
    drawArcStroke("airbrush_fine", "#f7ebd4", 1.8 - t * 0.8, baseCX, bottomY - 4 - t * 5, bottomRX - 6 - t * 10, bottomRY - 2, 12, 168, 22, 0, 1.0);
  }

  // B. Dark horizon core reflection band wrapping through the mid-flare
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let y = bottomY - 16 - t * 16;
    let rx = lerp(bottomRX - 22, waistRX + 12, t);
    let ry = lerp(bottomRY - 4, waistRY + 2, t);
    let col = t < 0.4 ? "#1c242b" : (t < 0.75 ? "#2e221b" : "#45535e");
    drawArcStroke("airbrush_fine", col, 1.6, baseCX, y, rx, ry, 6, 174, 22, 0, 1.0);
  }

  // C. Vivid tangerine reflection from the underside of the helmet glowing on the upper flare
  for (let i = 0; i < 7; i++) {
    let t = i / 6;
    let y = waistY + 4 + t * 14;
    let rx = lerp(waistRX + 2, bottomRX - 45, t);
    let ry = lerp(waistRY, bottomRY - 9, t);
    let col = t < 0.5 ? "#ff5114" : "#ff8d4d";
    drawArcStroke("airbrush_fine", col, 1.5, baseCX, y, rx, ry, 15, 165, 20, 0, 1.0);
  }

  // D. Atomic turquoise reflection wedges on left and right flanks of chrome cone
  for (let i = 0; i < 5; i++) {
    let off = i * 4;
    washPoly([
      [baseCX - waistRX + 14 + off, waistY + 8],
      [baseCX - waistRX + 42 + off, waistY + 12],
      [baseCX - bottomRX + 68 + off, bottomY + 12],
      [baseCX - bottomRX + 24 + off, bottomY + 6]
    ], "#42d8eb", 35, 0.1);

    washPoly([
      [baseCX + waistRX - 48 - off, waistY + 11],
      [baseCX + waistRX - 12 - off, waistY + 7],
      [baseCX + bottomRX - 22 - off, bottomY + 5],
      [baseCX + bottomRX - 72 - off, bottomY + 12]
    ], "#22bfd4", 32, 0.1);
  }

  // E. Blinding vertical pure-white chrome specular flares on pedestal
  for (let i = 0; i < 5; i++) {
    let w = 22 - i * 4;
    washPoly([
      [baseCX - 72 - w * 0.4, waistY + 13],
      [baseCX - 72 + w * 0.4, waistY + 14],
      [baseCX - 112 + w * 0.7, bottomY + 22],
      [baseCX - 112 - w * 0.7, bottomY + 20]
    ], "#ffffff", 48, 0.1);

    washPoly([
      [baseCX + 46 - w * 0.3, waistY + 15],
      [baseCX + 46 + w * 0.3, waistY + 14],
      [baseCX + 74 + w * 0.55, bottomY + 25],
      [baseCX + 74 - w * 0.55, bottomY + 26]
