function renderTangerineHelmetShell() {
  // 1. Crisp base silhouette of the monumental tangerine helmet
  let baseHull = helmetOuterPoly(84, 1.0, 1.0, 0, 0);
  washPoly(baseHull, "#ff4d12", 255, 0.25);
  washPoly(baseHull, "#f54207", 140, 0.25);

  // 2. Deep volumetric core shadow on right & lower-right belly (30 smooth airbrush wash layers)
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let sx = lerp(0.99, 0.52, t);
    let sy = lerp(0.99, 0.55, t);
    let ox = lerp(4, 118, t);
    let oy = lerp(4, 72, t);
    let col = t < 0.35 ? "#d92b00" : (t < 0.7 ? "#a81800" : "#6e0a00");
    washPoly(helmetOuterPoly(64, sx, sy, ox, oy), col, 15, 0.25);
