  }

  // Subtle fibreglass satin spray sheen over midtones
  for (let i = 0; i < 8; i++) {
    let r = TV_RX * (0.72 + i * 0.03);
    drawArcStroke("satin_spray", "#ffb37a", 0.9, TV_CX - 25, TV_CY - 20, r, r * 0.96, -155, -55, 14, 0, 0.8);
    drawArcStroke("satin_spray", "#ff591c", 0.9, TV_CX, TV_CY, r, r * 0.96, -45, 75, 14, 0, 0.8);
