  }

  // B. Atomic turquoise ambient sky reflection hugging the right-hand shadow rim
  for (let i = 0; i < 8; i++) {
    let inset = 3 + i * 3.2;
    let col = i < 3 ? "#a8f3fc" : "#2bc9de";
    drawArcStroke("airbrush_soft", col, 0.95 - i * 0.08, TV_CX + 2, TV_CY, TV_RX - inset, TV_RY - inset, -52, 38, 18, 0, 0.95);
  }

  // 6. Sculpted Astronaut Visor Cowling / Chamfered Lip Surround
  const cowlingCX = SCR_CX + 4;
  const cowlingCY = SCR_CY + 2;
  const cowlingRX = SCR_RX + 34;
