  brush.set("micro_pen", "#ffe3bf", 0.85);
  brush.line(235, 310.3, 294, 334.3);

  // Lower-left jaw seam
  brush.set("micro_pen", "#7d1200", 0.95);
  brush.line(252, 652, 312, 622);
  brush.set("micro_pen", "#ffc28a", 0.85);
  brush.line(252, 650.2, 312, 620.2);

  // Crisp outer shell contour micro-refinement
  drawArcStroke("micro_pen", "#ffcaa0", 0.9, TV_CX, TV_CY, TV_RX, TV_RY, -165, -70, 20, 0, 0.9);
  drawArcStroke("micro_pen", "#4a0600", 1.0, TV_CX, TV_CY, TV_RX, TV_RY, 10, 95, 18, 0, 0.9);
