      let bu = uc + (t - 0.5) * 0.27;
      let bv = vc - 0.145 - Math.sin(t * Math.PI) * 0.038 + (e.isLeft ? -t * 0.015 : (1 - t) * -0.015);
      let pB = screenProject(bu, bv);
      browPts.push([pB[0], pB[1], Math.sin(t * Math.PI) * 1.1 + 0.25]);
    }
    brush.set("airbrush_fine", "#221815", 0.9);
    brush.spline(browPts, 0.45);
