    let p1 = screenProject(lerp(-0.86, -0.46, t), lerp(-0.38, -0.46, t));
    let p2 = screenProject(lerp(-0.85, -0.52, t), lerp(-0.22, -0.30, t));
    hotArc1.push([p1[0], p1[1], Math.sin(t * Math.PI) * 1.0 + 0.2]);
    hotArc2.push([p2[0], p2[1], Math.sin(t * Math.PI) * 0.9 + 0.2]);
  }
  brush.set("gloss_marker", "#ffffff", 0.95);
  brush.spline(hotArc1, 0.45);
  brush.set("gloss_marker_thin", "#ffffff", 1.1);
