  image(stillImg, 0, 0, width, height);

  // 2. Lift the globe's contents from the snapshot, nudge, rotate and bounce them in WebGL
  const bump = getGlobeBump(t);
  drawLiftedGlobeContents(600, 415, bump.dx, bump.dy, bump.rot);

  // 3. Paint all p5.brush animated layers on top
  brush.noField();
  brush.set("rotring", INK, 1);
  drawAnimatedScene(t, bump);

  pop();
}

function paintStill() {
  translate(-width / 2, -height / 2);
  background(PAPER);
  brush.noField();
  brush.set("rotring", INK, 1);

  // 1. Dusky twilight diner backdrop
  drawTwilightDinerBackdrop();

  // 2. Perspective checkerboard diner counter & chrome trim
  drawCheckerboardCounter();

  // 3. Cast shadow and glossy enamel reflection on the counter
  drawCounterReflectionsAndShadow();

  // 4. Back wall of glass globe & interior twilight refraction
  const globeCX = 600;
  const globeCY = 415;
  const globeR = 256;
  drawGlobeBack(globeCX, globeCY, globeR);

  // 5. Packed candy gumballs and wet human eyeballs
  drawGumballsAndEyeballs(globeCX, globeCY, globeR);

  // 6. Vintage cast-metal gumball machine body (candy-apple red enamel & chrome grin)
  drawMachineBody(globeCX, 650);

  // 7. Foreground glass globe reflections, caustic arcs & top acorn finial
  drawGlobeFrontAndFinial(globeCX, globeCY, globeR);

  // 8. Hot-rod black pen pinstripe flourishes curling off the base
  drawHotRodPinstripes(globeCX);
}

// ============================================================================
// MOTION CHOREOGRAPHY & DYNAMIC SCENE OVERLAYS (FRAMES 2..48)
// ============================================================================

function easeInOutCubic(u) {
  u = constrain(u, 0, 1);
  return u < 0.5 ? 4 * u * u * u : 1 - pow(-2 * u + 2, 3) / 2;
}

function easeOutCubic(u) {
  u = constrain(u, 0, 1);
  return 1 - pow(1 - u, 3);
}

function easeOutBack(u) {
  u = constrain(u, 0, 1);
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * pow(u - 1, 3) + c1 * pow(u - 1, 2);
}

// Physical bump, rotation, and settling bounce of the globe & machine
function getGlobeBump(t) {
  // Immediate hard bump starting on Frame 2 (t = 0.04s), peaking within the first 5 frames,
  // slamming down as the gumball drops into the chute, then bouncing and settling
  let env1 = exp(-t * 2.6);
  let waveRot = -11.5 * sin(t * 520) * env1 + 3.2 * sin(max(0, t - 0.1) * 180) * exp(-t * 1.2);
  let waveDX  = -15.0 * sin(t * 520) * env1 + 4.0 * sin(t * 260) * env1;
  let waveDY  = -22.0 * sin(t * 640) * exp(-t * 3.0) + 11.0 * easeOutCubic(constrain(t / 0.45, 0, 1));

  // Secondary mechanical shudder around t = 1.15s when the crank finishes its second ratchet
  let env2 = t > 1.05 ? exp(-(t - 1.05) * 4.5) * sin((t - 1.05) * 600) : 0;
  waveRot += env2 * 5.5;
  waveDX  += env2 * 8.0;
  waveDY  -= abs(env2) * 10.0;

  return {
    dx: waveDX,
    dy: waveDY,
    rot: waveRot,
    bodyTilt: waveRot * 0.012,
    bodyDY: waveDY * 0.38
  };
}

// Stamp the circular lifted globe contents from stillImg with rotation & bounce
function drawLiftedGlobeContents(cx, cy, dx, dy, rotDeg) {
  if (!globeRectImg) return;

  push();
  noStroke();
  // Dark twilight interior cavity behind the shifted gumball pack
  fill(TWI_VOID);
  circle(cx, cy, 496);
  fill(TWI_PLUM);
  arc(cx, cy, 488, 488, 195, 345, CHORD);

  // Textured circular fan of the lifted Frame-0 gumball pile, nudged & rotated
  translate(cx + dx, cy + dy);
  rotate(rotDeg);
  textureMode(NORMAL);
  texture(globeRectImg);
  beginShape(TRIANGLE_FAN);
  vertex(0, 0, 0.5, 0.5);
  const rad = 244;
  for (let i = 0; i <= 64; i++) {
    let a = (i / 64) * 360;
    let vx = cos(a) * rad;
    let vy = sin(a) * rad;
    let u = 0.5 + cos(a) * (rad / 496);
    let v = 0.5 + sin(a) * (rad / 496);
    vertex(vx, vy, u, v);
  }
  endShape();
  pop();
}

// Unison eyeball choreography: hard whip in frames 2..5, blink & snap straight at viewer,
// massive pupil dilation, second quick blink, downward glance at dropped ball, snap back
function getUnisonEyePose(idx, t) {
  const def = EYE_DEFS[idx];
  const gx0 = def.gx;
  const gy0 = def.gy;
  const rot0 = def.rot;

  // Convergence offset so "straight out at the viewer" focuses dead-on at the camera
  const convX = constrain((600 - def.x) / 1100, -0.05, 0.05);
  const convY = constrain((420 - def.y) / 1100, -0.05, 0.05);

  let gx, gy, rot, pupilScale, irisScale;

  if (t < 0.17) {
    // Frames 2..5: Immediate hard unison whip to the upper-left as the machine is bumped
    let u = easeOutCubic(t / 0.17);
    gx = lerp(gx0, -0.50, u);
    gy = lerp(gy0, -0.30, u);
    rot = lerp(rot0, -28, u);
    pupilScale = lerp(1.0, 0.66, u);
    irisScale = lerp(1.0, 1.06, u);
  } else if (t < 0.34) {
    // Frames 5..9: Unison snap dead-center to stare straight out at the viewer!
    let u = easeOutBack((t - 0.17) / 0.17);
    gx = lerp(-0.50, convX, u);
    gy = lerp(-0.30, convY, u);
    rot = lerp(-28, 0, u);
    pupilScale = lerp(0.66, 1.25, easeOutCubic((t - 0.17) / 0.17));
    irisScale = lerp(1.06, 1.16, easeOutCubic((t - 0.17) / 0.17));
  } else if (t < 1.08) {
    // Frames 9..26 (spanning the 1-second mark): Locked dead-on stare at viewer + huge pupil dilation!
    let u = easeOutCubic((t - 0.34) / 0.74);
    let microTremorX = sin(t * 720 + idx * 30) * 0.015;
    let microTremorY = cos(t * 640 + idx * 45) * 0.015;
    gx = convX + microTremorX;
    gy = convY + microTremorY;
    rot = sin(t * 360) * 4;
    pupilScale = lerp(1.25, 1.72, u);
    irisScale = lerp(1.16, 1.22, u);
  } else if (t < 1.32) {
    // Frames 26..32: Unison downward saccade to stare at the eyeball that dropped onto the counter
    let u = easeOutBack((t - 1.08) / 0.24);
    gx = lerp(convX, -0.06, u);
    gy = lerp(convY, 0.45, u);
    rot = lerp(0, 16, u);
    pupilScale = lerp(1.72, 1.15, easeOutCubic((t - 1.08) / 0.24));
    irisScale = 1.18;
  } else if (t < 1.56) {
    // Frames 32..38: Hold downward gaze on the counter eyeball
    gx = -0.06 + sin(t * 500) * 0.02;
    gy = 0.45;
    rot = 16;
    pupilScale = 1.20;
    irisScale = 1.18;
  } else {
    // Frames 38..48: Snap back dead-center at the viewer and dilate wide
    let u = easeOutBack((t - 1.56) / 0.44);
    gx = lerp(-0.06, convX, u);
    gy = lerp(0.45, convY, u);
    rot = lerp(16, 0, u);
    pupilScale = lerp(1.20, 1.76, easeOutCubic((t - 1.56) / 0.44));
    irisScale = 1.22;
  }

  // Two crisp unison blinks in the first second (around t = 0.22s and t = 0.74s) + one at t = 1.58s
  let blink = 0;
  if (t > 0.14 && t < 0.30) {
    blink = sin(((t - 0.14) / 0.16) * 180);
  } else if (t > 0.66 && t < 0.84) {
    blink = sin(((t - 0.66) / 0.18) * 180);
  } else if (t > 1.50 && t < 1.66) {
    blink = sin(((t - 1.50) / 0.16) * 180);
  }
  blink = pow(constrain(blink, 0, 1), 0.75);

  return { gx, gy, rot, pupilScale, irisScale, blink };
}

function drawAnimatedScene(t, bump) {
  const cx = 600;
  const globeCY = 415;
  const globeR = 256;
  const easeStart = constrain(t / 0.08, 0, 1);

  // -------------------------------------------------------------------------
  // A. DINER NEON SURGE & COUNTER REFLECTIONS (Covers wide backdrop & counter area)
  // -------------------------------------------------------------------------
  drawNeonAndCounterSurge(t, bump);

  // -------------------------------------------------------------------------
  // B. JOSTLING & SETTLING FOREGROUND GUMBALLS INSIDE THE GLOBE
  // -------------------------------------------------------------------------
  const themes = {
    candyRed:  { dark: CANDY_SHADOW, mid: CANDY_MID,   bright: CANDY_RED,    glow: CANDY_HOT,  rim: PINK_BUBBLE },
    bubblegum: { dark: PINK_DARK,    mid: PINK_MID,    bright: PINK_BUBBLE,  glow: PINK_LIGHT, rim: MINT_PALE },
    mint:      { dark: MINT_DARK,    mid: MINT_MID,    bright: MINT_BRIGHT,  glow: MINT_PALE,  rim: CREAM_BRIGHT },
    cream:     { dark: CREAM_SHADOW, mid: CREAM_MID,   bright: CREAM_BRIGHT, glow: PAPER,      rim: PINK_LIGHT },
    grape:     { dark: TWI_VOID,     mid: TWI_PLUM,    bright: TWI_MAUVE,    glow: PINK_BUBBLE,rim: MINT_BRIGHT },
    coral:     { dark: CANDY_DARK,   mid: "#e83825",   bright: "#ff6242",    glow: "#ffaa88",  rim: CREAM_BRIGHT }
  };

  // Fill upper rim & side crescents exposed when the pile drops/rotates
  brush.set("fine_marker", MINT_MID, 1.6);
  brush.arc(cx, globeCY, globeR - 5, 150, 240);
  brush.set("fine_marker", PINK_MID, 1.6);
  brush.arc(cx, globeCY, globeR - 5, 300, 390);

  for (let i = 0; i < FRONT_GUMBALLS.length; i++) {
    const g = FRONT_GUMBALLS[i];
    randomSeed(5000 + i * 73);
    noiseSeed(5000 + i * 73);

    // Individual ball jostle: Rigid rotation with the globe bump + individual radial/vertical bounce
    let relX = g.x - cx;
    let relY = g.y - globeCY;
    let rotA = bump.rot * 0.85 + sin(t * 480 + i * 47) * 5.0 * exp(-t * 2.1);
    let ca = cos(rotA);
    let sa = sin(rotA);

    // Lower balls drop further into the funnel neck as one ball is dispensed
    let funnelDrop = map(constrain(g.y, 240, 645), 240, 645, 3, 18) * easeOutCubic(constrain(t / 0.42, 0, 1));
    let indivBounceX = cos(i * 67 + t * 540) * 9.5 * exp(-t * 2.2);
    let indivBounceY = sin(i * 83 + t * 620) * 12.0 * exp(-t * 2.3) + funnelDrop;

    let gx = cx + (relX * ca - relY * sa) + bump.dx * 0.75 + indivBounceX;
    let gy = globeCY + (relX * sa + relY * ca) + bump.dy * 0.75 + indivBounceY;

    // Keep each jostling gumball inside the inner glass wall
    let clamped = clampPtToCircle(gx, gy, cx, globeCY, globeR - g.r - 8);
    drawSingleGumball(clamped[0], clamped[1], g.r, themes[g.t] || themes.bubblegum, false);
  }

  // -------------------------------------------------------------------------
  // C. ALL 6 GLOBE EYEBALLS SWIVEL HARD IN UNISON, BLINK & DILATE
  // -------------------------------------------------------------------------
  for (let i = 0; i < 6; i++) {
    const def = EYE_DEFS[i];
    const pose = getUnisonEyePose(i, t);
    randomSeed(8800 + i * 131);
    noiseSeed(8800 + i * 131);

    // Eyeballs jostle and bounce along with their neighboring gumballs
    let relX = def.x - cx;
    let relY = def.y - globeCY;
    let rotA = bump.rot * 0.75;
    let ca = cos(rotA);
    let sa = sin(rotA);
    let settleY = map(def.y, 280, 552, 4, 13) * easeOutCubic(constrain(t / 0.42, 0, 1));
    let ex = cx + (relX * ca - relY * sa) + bump.dx * 0.7;
    let ey = globeCY + (relX * sa + relY * ca) + bump.dy * 0.7 + settleY;
    let clamped = clampPtToCircle(ex, ey, cx, globeCY, globeR - def.r - 8);

    drawAnimatedEyeball(
      i,
      clamped[0],
      clamped[1],
      def.r,
      def.iris,
      pose.gx,
      pose.gy,
      pose.rot,
      pose.pupilScale,
      pose.irisScale,
      pose.blink,
      easeStart
    );
  }

  // -------------------------------------------------------------------------
  // D. FOREGROUND GLASS GLOBE REFLECTIONS & BUMPED ACORN FINIAL
  // -------------------------------------------------------------------------
  randomSeed(9050);
  noiseSeed(9050);
  drawGlobeFrontAndFinialAnimated(cx, globeCY, globeR, bump);

  // -------------------------------------------------------------------------
  // E. ROCKING MACHINE BODY, TURNING COIN KNOB, CHUTE & DROPPING EYEBALL
  // -------------------------------------------------------------------------
  randomSeed(9100);
  noiseSeed(9100);
  drawAnimatedMachineAndChute(cx, t, bump, easeStart);

  // -------------------------------------------------------------------------
  // F. FLEXING HOT-ROD PINSTRIPES CURLING OFF THE BASE
  // -------------------------------------------------------------------------
  randomSeed(9400);
  noiseSeed(9400);
  drawAnimatedPinstripes(cx, t, bump);
}

// Vivid kustom-kulture neon pulse & counter reflection sweep on impact
function drawNeonAndCounterSurge(t, bump) {
  randomSeed(9700);
  noiseSeed(9700);

  // Fast surge within the first 6 frames, pulsing with the diner neon buzz
  let surge = sin(constrain(t / 0.16, 0, 1) * 90) * (0.78 + 0.22 * sin(t * 420));
  if (surge <= 0.01) return;

  // 1. Twilight diner backdrop neon glow expansion (mint upper tubes & pink horizon tube)
  let mintOp = floor(58 * surge);
  let pinkOp = floor(64 * surge);

  // Upper mint neon halo washes & reflections across twilight window
  fillPolyWash([[20, 195], [410, 195], [410, 330], [20, 330]], MINT_BRIGHT, mintOp);
  fillPolyWash([[790, 195], [1180, 195], [1180, 330], [790, 330]], MINT_BRIGHT, mintOp);
  fillPolyWash([[0, 25], [1200, 25], [1200, 175], [0, 175]], TWI_PLUM, floor(48 * surge));

  // Full-width bubblegum-pink horizon neon flare (y = 510..685)
  fillPolyWash([[0, 515], [1200, 515], [1200, 685], [0, 685]], PINK_BUBBLE, pinkOp);
  brush.set("paper_spec", PAPER, 1.35 * surge);
  brush.line(40, 260, 355, 260);
  brush.line(845, 260, 1160, 260);
  brush.line(10, 595, 1190, 595);

  // 2. Sweeping neon reflection glaze across the perspective checkerboard counter
  // Left wing catches cool mint neon, right wing catches hot bubblegum pink, center catches candy red
  fillPolyWash([[0, 748], [460, 748], [340, 1124], [0, 1124]], MINT_BRIGHT, floor(52 * surge));
  fillPolyWash([[740, 748], [1200, 748], [1200, 1124], [860, 1124]], PINK_BUBBLE, floor(55 * surge));
  fillPolyWash([[340, 748], [860, 748], [920, 1124], [280, 1124]], CANDY_HOT, floor(38 * surge));

  // Sliding specular highlight streaks on the glossy diner counter top
  let shiftX = bump.dx * 1.8 + sin(t * 240) * 28;
  brush.set("paper_spec", PAPER, 1.5);
  brush.line(110 + shiftX, 815, 340 + shiftX, 815);
  brush.line(830 - shiftX, 835, 1080 - shiftX, 835);
  brush.line(80 + shiftX, 935, 310 + shiftX, 935);
  brush.line(870 - shiftX, 955, 1120 - shiftX, 955);

  // Ribbed chrome counter apron travelling highlight glints (y = 1126..1200)
  brush.set("fine_marker", MINT_PALE, 1.9);
  brush.line(0, 1143, 1200, 1143);
  brush.set("fine_marker", PINK_LIGHT, 1.9);
  brush.line(0, 1167, 1200, 1167);

  // Expanded glossy red reflection pool on the counter in front of the rocking base
  for (let i = 0; i < 20; i++) {
    let u = i / 19;
    let y = lerp(1008, 1120, u);
    let halfW = lerp(260, 175, u) + sin(i * 35 + t * 360) * 18;
    let col = i % 3 === 0 ? CANDY_HOT : i % 3 === 1 ? CANDY_RED : PINK_BUBBLE;
    brush.set("chisel_marker", col, 1.9);
    brush.line(600 + bump.dx * 0.5 - halfW, y, 600 + bump.dx * 0.5 + halfW, y);
  }
}

function drawGlobeFrontAndFinialAnimated(cx, cy, r, bump) {
  const shiftA = bump.rot * 1.2;

  // 1. Thick vintage glass rim refraction
  brush.set("chisel_marker", MINT_BRIGHT, 1.8);
  brush.arc(cx, cy, r - 4, 130 + shiftA, 232 + shiftA);
  brush.set("paper_spec", PAPER, 1.5);
  brush.arc(cx, cy, r - 2, 142 + shiftA, 222 + shiftA);

  brush.set("chisel_marker", PINK_BUBBLE, 1.8);
  brush.arc(cx, cy, r - 4, 308 + shiftA, 405 + shiftA);
  brush.set("paper_spec", PAPER, 1.3);
  brush.arc(cx, cy, r - 2, 320 + shiftA, 390 + shiftA);

  // 2. Large sweeping curved diner-window highlight on upper-left of glass globe
  let winArc1 = [];
  let winArc2 = [];
  for (let a = 192; a <= 248; a += 4) {
    let aa = a + shiftA * 0.6;
    winArc1.push([cx + cos(aa) * (r * 0.86), cy + sin(aa) * (r * 0.86)]);
  }
  for (let a = 248; a >= 192; a -= 4) {
    let aa = a + shiftA * 0.6;
    winArc2.push([cx + cos(aa) * (r * 0.72), cy + sin(aa) * (r * 0.72)]);
  }
  fillPolyWash(winArc1.concat(winArc2), PAPER, 240);

  brush.set("paper_spec", PAPER, 2.1);
  brush.arc(cx, cy, r * 0.83, 194 + shiftA * 0.6, 246 + shiftA * 0.6);
  brush.arc(cx, cy, r * 0.78, 196 + shiftA * 0.6, 244 + shiftA * 0.6);
  brush.arc(cx, cy, r * 0.74, 198 + shiftA * 0.6, 242 + shiftA * 0.6);

  // Secondary lower-left glass streak
  brush.set("paper_spec", PAPER, 1.6);
  brush.arc(cx, cy, r * 0.84, 152 + shiftA, 178 + shiftA);
  brush.arc(cx, cy, r * 0.78, 156 + shiftA, 174 + shiftA);

  // Upper-right curved glass reflection arc
  brush.set("fine_marker", MINT_PALE, 1.6);
  brush.arc(cx, cy, r * 0.84, 295 + shiftA, 342 + shiftA);
  brush.set("paper_spec", PAPER, 1.5);
  brush.arc(cx, cy, r * 0.81, 300 + shiftA, 336 + shiftA);

  // Outer glass globe contour in crisp ink
  brush.set("rotring", INK, 1.05);
  brush.circle(cx, cy, r, 0.01);
  brush.set("rotring", INK, 0.6);
  brush.circle(cx, cy, r - 6, 0.01);

  // 3. Top Acorn Lock Finial (jostling slightly with the bumped globe)
  let fx = cx + bump.dx * 0.35;
  let fyOff = bump.dy * 0.25;
  let capBase = [];
  for (let u = -1; u <= 1; u += 0.1) {
    capBase.push([fx + u * 112, 150 + fyOff + (1 - u * u) * 10]);
  }
  for (let u = 1; u >= -1; u -= 0.1) {
    capBase.push([fx + u * 128, 172 + fyOff + (1 - u * u) * 14]);
  }
  fillPolyWash(capBase, CANDY_DARK, 245);
  fillPolyWash(
    [[fx - 85, 152 + fyOff], [fx - 20, 156 + fyOff], [fx - 24, 178 + fyOff], [fx - 96, 172 + fyOff]],
    CANDY_RED,
    235
  );
  brush.set("paper_spec", PAPER, 1.5);
  brush.line(fx - 65, 154 + fyOff, fx - 68, 174 + fyOff);
  brush.line(fx - 50, 156 + fyOff, fx - 52, 176 + fyOff);

  let domeCap = [
    [fx - 72, 152 + fyOff],
    [fx - 54, 128 + fyOff],
    [fx - 18, 118 + fyOff],
    [fx + 18, 118 + fyOff],
    [fx + 54, 128 + fyOff],
    [fx + 72, 152 + fyOff]
  ];
  fillPolyWash(domeCap, CHROME_DARK, 245);
  fillPolyWash(
    [[fx - 50, 150 + fyOff], [fx - 36, 128 + fyOff], [fx + 8, 120 + fyOff], [fx + 12, 150 + fyOff]],
    CHROME_LIGHT,
    225
  );
  brush.set("paper_spec", PAPER, 1.6);
  brush.line(fx - 34, 150 + fyOff, fx - 22, 124 + fyOff);
  brush.line(fx - 18, 150 + fyOff, fx - 10, 122 + fyOff);

  let acornPts = makeEllipsePts(fx, 108 + fyOff, 16, 14, 0, 20);
  fillPolyWash(acornPts, CHROME_DARK, 250);
  brush.set("paper_spec", PAPER, 1.3);
  brush.arc(fx, 108 + fyOff, 11, 190, 290);

  brush.set("rotring", INK, 0.95);
  new brush.Polygon(capBase).draw("rotring", INK, 0.95);
  new brush.Polygon(domeCap).draw("rotring", INK, 0.95);
  brush.circle(fx, 108 + fyOff, 15, 0.01);
}

// Redraw the machine body with rocking enamel reflections, turning coin knob,
// opening chrome grille flap, and the eyeball-gumball dropping out of the chute onto the counter
function drawAnimatedMachineAndChute(cx, t, bump, easeStart) {
  const yStart = 690;
  const yEnd = 1012;
  const uShift = constrain(bump.bodyTilt, -0.14, 0.14);

  // 1. Candy-apple red enamel hourglass body with shifting specular bands as the machine rocks
  let bodyOutline = [];
  for (let y = yStart; y <= yEnd; y += 8) {
    bodyOutline.push([cx - getBodyHalfWidth(y), y]);
  }
  for (let u = -1; u <= 1; u += 0.08) {
    let x = cx + u * 260;
    bodyOutline.push([x, getBottomCurveY(x, cx, yEnd, 36)]);
  }
  for (let y = yEnd; y >= yStart; y -= 8) {
    bodyOutline.push([cx + getBodyHalfWidth(y), y]);
  }
  fillPolyWash(bodyOutline, CANDY_DARK, 250);

  const uBands = [
    { u0: -1.00, u1: -0.88, col: TWI_VOID,     op: 235 },
    { u0: -0.92, u1: -0.76, col: MINT_BRIGHT,  op: 205 },
    { u0: -0.78, u1: -0.58, col: CANDY_RED,    op: 235 },
    { u0: -0.60, u1: -0.34, col: CANDY_HOT,    op: 240 },
    { u0: -0.36, u1: -0.02, col: CANDY_RED,    op: 240 },
    { u0: -0.04, u1:  0.34, col: CANDY_MID,    op: 240 },
    { u0:  0.32, u1:  0.68, col: CANDY_SHADOW, op: 245 },
    { u0:  0.66, u1:  0.88, col: CANDY_RED,    op: 230 },
    { u0:  0.85, u1:  0.97, col: PINK_BUBBLE,  op: 220 },
    { u0:  0.95, u1:  1.00, col: TWI_VOID,     op: 240 }
  ];

  for (let b of uBands) {
    let bu0 = constrain(b.u0 + uShift, -1, 1);
    let bu1 = constrain(b.u1 + uShift, -1, 1);
    if (abs(bu1 - bu0) < 0.01) continue;
    let stripPts = [];
    for (let y = yStart; y <= yEnd; y += 10) {
      let hw = getBodyHalfWidth(y);
      let curveDrop = (1 - bu0 * bu0) * 32 * ((y - yStart) / (yEnd - yStart));
      stripPts.push([cx + bu0 * hw, y + curveDrop]);
    }
    for (let y = yEnd; y >= yStart; y -= 10) {
      let hw = getBodyHalfWidth(y);
      let curveDrop = (1 - bu1 * bu1) * 32 * ((y - yStart) / (yEnd - yStart));
      stripPts.push([cx + bu1 * hw, y + curveDrop]);
    }
    fillPolyWash(stripPts, b.col, b.op);
  }

  for (let u = -0.92; u <= 0.92; u += 0.045) {
    let us = u - uShift;
    let col =
      us < -0.78 ? MINT_PALE :
      us < -0.56 ? CANDY_RED :
      us < -0.36 ? CANDY_HOT :
      us < 0.0   ? CANDY_RED :
      us < 0.32  ? CANDY_MID :
      us < 0.68  ? CANDY_SHADOW :
      us < 0.85  ? CANDY_RED : PINK_LIGHT;

    let pts = [];
    for (let y = yStart + 6; y <= yEnd - 4; y += 16) {
      let hw = getBodyHalfWidth(y);
      let drop = (1 - u * u) * 30 * ((y - yStart) / (yEnd - yStart));
      pts.push([cx + u * hw, y + drop]);
    }
    brush.set("chisel_marker", col, 1.5);
    brush.spline(pts, 0.5);
  }

  // Shifting clean-paper specular ribbons on the rocking red body
  for (let uOff of [-0.50, -0.47, -0.44, -0.35]) {
    let u = constrain(uOff + uShift * 1.1, -0.88, 0.88);
    let w = uOff === -0.35 ? 0.9 : 1.75;
    let pts = [];
    for (let y = yStart + 12; y <= yEnd - 8; y += 16) {
      let hw = getBodyHalfWidth(y);
      let drop = (1 - u * u) * 30 * ((y - yStart) / (yEnd - yStart));
      pts.push([cx + u * hw, y + drop]);
    }
    brush.set("paper_spec", PAPER, w);
    brush.spline(pts, 0.5);
  }

  for (let yRing of [752, 845, 968]) {
    let hw = getBodyHalfWidth(yRing);
    let rPts = [];
    for (let u = -0.68; u <= -0.18; u += 0.1) {
      let uu = constrain(u + uShift, -0.9, 0.9);
      let drop = (1 - uu * uu) * 26 * ((yRing - yStart) / (yEnd - yStart));
      rPts.push([cx + uu * hw, yRing + drop]);
    }
    brush.set("paper_spec", PAPER, 1.35);
    brush.spline(rPts, 0.5);
  }

  // 2. Stepped heavy base foot & upper chrome collar
  let footPts = [];
  for (let u = -1; u <= 1; u += 0.06) {
    footPts.push([cx + u * 252, getBottomCurveY(cx + u * 252, cx, 974, 30)]);
  }
  for (let u = 1; u >= -1; u -= 0.06) {
    footPts.push([cx + u * 266, getBottomCurveY(cx + u * 266, cx, 1012, 38)]);
  }
  fillPolyWash(footPts, CANDY_SHADOW, 240);

  for (let d = 0; d <= 34; d += 4) {
    let yR = 976 + d;
    let wR = lerp(250, 265, d / 34);
    let col = d < 8 ? PAPER : d < 18 ? CANDY_HOT : d < 28 ? CANDY_RED : INK;
    let bName = d < 8 ? "paper_spec" : "fine_marker";
    let pts = [];
    for (let u = -0.95; u <= 0.95; u += 0.1) {
      if (d < 8 && (u < -0.75 + uShift || u > 0.15 + uShift)) continue;
      pts.push([cx + u * wR, getBottomCurveY(cx + u * wR, cx, yR, 34)]);
    }
    if (pts.length >= 2) {
      brush.set(bName, col, d < 8 ? 1.5 : 1.8);
      brush.spline(pts, 0.5);
    }
  }

  for (let fx of [cx - 205, cx + 205]) {
    let fy = getBottomCurveY(fx, cx, 1012, 38);
    let fPoly = makeEllipsePts(fx, fy + 6, 36, 13, 0, 20);
    fillPolyWash(fPoly, INK, 250);
    brush.set("paper_spec", PAPER, 0.9);
    brush.line(fx - 18, fy + 4, fx + 4, fy + 4);
  }

  // Upper stepped chrome collar (y = 650..705)
  let collarPts = [];
  for (let u = -1; u <= 1; u += 0.08) {
    collarPts.push([cx + u * 158, 650 + (1 - u * u) * 20]);
  }
  for (let u = 1; u >= -1; u -= 0.08) {
    collarPts.push([cx + u * 144, 696 + (1 - u * u) * 22]);
  }
  fillPolyWash(collarPts, CHROME_DARK, 245);

  const collarStrips = [
    { u0: -0.95, u1: -0.70, col: MINT_BRIGHT },
    { u0: -0.70, u1: -0.35, col: PAPER },
    { u0: -0.35, u1:  0.05, col: CHROME_LIGHT },
    { u0:  0.05, u1:  0.45, col: CHROME_DARK },
    { u0:  0.45, u1:  0.78, col: CANDY_RED },
    { u0:  0.78, u1:  0.96, col: PINK_LIGHT }
  ];
  for (let cs of collarStrips) {
    let cu0 = constrain(cs.u0 + uShift, -0.98, 0.98);
    let cu1 = constrain(cs.u1 + uShift, -0.98, 0.98);
    let sp = [
      [cx + cu0 * 156, 652 + (1 - cu0 * cu0) * 20],
      [cx + cu1 * 156, 652 + (1 - cu1 * cu1) * 20],
      [cx + cu1 * 144, 694 + (1 - cu1 * cu1) * 22],
      [cx + cu0 * 144, 694 + (1 - cu0 * cu0) * 22]
    ];
    fillPolyWash(sp, cs.col, cs.col === PAPER ? 255 : 225);
  }
  for (let u = -0.88; u <= 0.88; u += 0.16) {
    let xTop = cx + u * 155;
    let yTop = 652 + (1 - u * u) * 20;
    let xBot = cx + u * 143;
    let yBot = 695 + (1 - u * u) * 22;
    brush.set("rotring", INK, 0.75);
    brush.line(xTop, yTop, xBot, yBot);
    brush.set("paper_spec", PAPER, 0.85);
    brush.line(xTop + 3, yTop, xBot + 3, yBot);
  }

  // 3. Chrome Coin Shield & TURNING COIN KNOB
  let shieldPts = [
    [cx - 78, 735],
    [cx - 45, 722],
    [cx + 45, 722],
    [cx + 78, 735],
    [cx + 86, 795],
    [cx + 62, 852],
    [cx, 866],
    [cx - 62, 852],
    [cx - 86, 795]
  ];
  fillPolyWash(shieldPts, CHROME_DARK, 245);

  let shieldInner = [
    [cx - 70, 740],
    [cx - 40, 728],
    [cx + 40, 728],
    [cx + 70, 740],
    [cx + 78, 793],
    [cx + 55, 845],
    [cx, 858],
    [cx - 55, 845],
    [cx - 78, 793]
  ];
  fillPolyWash(shieldInner, CHROME_LIGHT, 225);

  randomSeed(9120);
  noiseSeed(9120);
  hatchPolyMarker(shieldInner, "fine_marker", CHROME_MID, 1.1, 7, 38, { rand: 0.02 });
  brush.set("paper_spec", PAPER, 1.6);
  brush.line(cx - 64, 748, cx - 18, 732);
  brush.line(cx - 70, 778, cx + 15, 735);
  brush.line(cx - 50, 838, cx + 52, 780);

  // Twin upper coin-slot "eyes" tracking & dilating with the globe eyeballs
  const shieldPose = getUnisonEyePose(4, t);
  const slotShiftX = shieldPose.gx * 10;
  const slotShiftY = shieldPose.gy * 6;
  for (let side of [-1, 1]) {
    let bx = cx + side * 42;
    let by = 762;
    let bossPts = makeCirclePts(bx, by, 21, 24);
    fillPolyWash(bossPts, CHROME_DARK, 250);
    let bossIn = makeCirclePts(bx - 2 + slotShiftX * 0.25, by - 2 + slotShiftY * 0.25, 16, 20);
    fillPolyWash(bossIn, side === -1 ? MINT_PALE : PINK_LIGHT, 230);

    let sx = bx + slotShiftX;
    let sy = by + slotShiftY;
    let sw = 3.2 * constrain(shieldPose.pupilScale, 0.75, 1.55);
    let sh = 11.0 * (1 - shieldPose.blink * 0.85);
    fillPolyWash(
      [[sx - sw, sy - sh], [sx + sw, sy - sh], [sx + sw, sy + sh], [sx - sw, sy + sh]],
      INK,
      255
    );
    brush.set("paper_spec", PAPER, 1.1);
    brush.arc(bx, by, 17, 195, 290);
    brush.set("rotring", INK, 0.8);
    brush.circle(bx, by, 21, 0.01);
  }

  // ROTATING WINGED TURN-CRANK KNOB at (cx, 814)
  // Turns a rapid 180 deg in the first 0.40s to dispense the eyeball, then ratchets another 180 deg!
  let crankTurn = 0;
  if (t < 0.40) {
    crankTurn = 180 * easeOutBack(t / 0.40);
  } else if (t < 1.05) {
    crankTurn = 180 + 180 * easeInOutCubic((t - 0.40) / 0.65);
  } else {
    crankTurn = 360 + 25 * sin((t - 1.05) * 380) * exp(-(t - 1.05) * 3.0);
  }
  let crankAngle = 14 + crankTurn;

  let hubPts = makeCirclePts(cx, 814, 24, 24);
  fillPolyWash(hubPts, CHROME_DARK, 250);

  let caK = cos(crankAngle);
  let saK = sin(crankAngle);
  const wingLen = 60;
  const wingHalfW = 7.5;
  let handleWing = [
    [cx - caK * wingLen + saK * wingHalfW, 814 - saK * wingLen - caK * wingHalfW],
    [cx + caK * wingLen + saK * wingHalfW, 814 + saK * wingLen - caK * wingHalfW],
    [cx + caK * wingLen - saK * wingHalfW, 814 + saK * wingLen + caK * wingHalfW],
    [cx - caK * wingLen - saK * wingHalfW, 814 - saK * wingLen + caK * wingHalfW]
  ];
  fillPolyWash(handleWing, CHROME_MID, 250);
  brush.set("paper_spec", PAPER, 1.6);
  brush.line(
    cx - caK * (wingLen - 4) + saK * 2,
    814 - saK * (wingLen - 4) - caK * 2,
    cx + caK * (wingLen - 4) + saK * 2,
    814 + saK * (wingLen - 4) - caK * 2
  );
  brush.set("rotring", INK, 0.95);
  new brush.Polygon(handleWing).draw("rotring", INK, 0.95);
  new brush.Polygon(shieldPts).draw("rotring", INK, 0.9);

  // 4. THE CHROME GRIN CHUTE & REPLACEMENT EYEBALL DROPPING INTO THE CHUTE
  let grinOuter = [];
  for (let u = -1; u <= 1; u += 0.08) {
    let gx = cx + u * 124;
    let gy = 892 + (1 - u * u) * 18 - pow(abs(u), 3) * 16;
    grinOuter.push([gx, gy]);
  }
  for (let u = 1; u >= -1; u -= 0.08) {
    let gx = cx + u * 116;
    let gy = 936 + (1 - u * u) * 38 - pow(abs(u), 2.5) * 18;
    grinOuter.push([gx, gy]);
  }
  fillPolyWash(grinOuter, CHROME_LIGHT, 245);

  let grinMouth = [];
  for (let u = -0.88; u <= 0.88; u += 0.08) {
    let gx = cx + u * 114;
    let gy = 900 + (1 - u * u) * 16 - pow(abs(u), 3) * 12;
    grinMouth.push([gx, gy]);
  }
  for (let u = 0.88; u >= -0.88; u -= 0.08) {
    let gx = cx + u * 106;
    let gy = 928 + (1 - u * u) * 34 - pow(abs(u), 2.5) * 14;
    grinMouth.push([gx, gy]);
  }
  fillPolyWash(grinMouth, INK, 255);

  // Replacement eyeball-gumball dropping from upper throat into the grin after t = 0.35s
  if (t > 0.32) {
    let uDrop = easeOutBack(constrain((t - 0.32) / 0.32, 0, 1));
    let repY = lerp(898, 926, uDrop);
    let repR = lerp(18, 26, constrain((t - 0.32) / 0.25, 0, 1));
    let grinPose = getUnisonEyePose(6, t);
    randomSeed(8800 + 6 * 131);
    noiseSeed(8800 + 6 * 131);
    drawAnimatedEyeball(
      6,
      cx + 12,
      repY,
      repR,
      "amber",
      grinPose.gx,
      grinPose.gy,
      grinPose.rot,
      grinPose.pupilScale,
      grinPose.irisScale,
      grinPose.blink,
      easeStart
    );
  }

  // Hinged vertical chrome grille teeth (kicking open upward during t = 0.04..0.38s as the first eyeball drops out!)
  let flapLift = 0;
  if (t < 0.38) {
    flapLift = sin((t / 0.38) * 180) * 18;
  }
  randomSeed(9500);
  noiseSeed(9500);
  for (let u = -0.76; u <= 0.76; u += 0.19) {
    if (abs(u - 0.09) < 0.12) continue;
    let tx = cx + u * 112;
    let tyTop = 900 + (1 - u * u) * 16 - pow(abs(u), 3) * 12;
    let tyBot = 926 + (1 - u * u) * 32 - pow(abs(u), 2.5) * 14 - flapLift * (1 - abs(u) * 0.5);

    fillPolyWash(
      [[tx - 5, tyTop], [tx + 5, tyTop], [tx + 4, tyBot], [tx - 4, tyBot]],
      CHROME_MID,
      245
    );
    brush.set("paper_spec", PAPER, 1.1);
    brush.line(tx - 1, tyTop + 1, tx - 1, tyBot - 1);
    brush.set("rotring", INK, 0.75);
    brush.line(tx - 5, tyTop, tx - 4, tyBot);
    brush.line(tx + 5, tyTop, tx + 4, tyBot);
  }

  let upperLipSpec = [];
  let lowerLipSpec = [];
  for (let u = -0.92; u <= 0.92; u += 0.1) {
    upperLipSpec.push([cx + u * 120, 895 + (1 - u * u) * 17 - pow(abs(u), 3) * 14]);
    lowerLipSpec.push([cx + u * 112, 933 + (1 - u * u) * 36 - pow(abs(u), 2.5) * 16]);
  }
  brush.set("paper_spec", PAPER, 1.45);
  brush.spline(upperLipSpec, 0.5);
  brush.spline(lowerLipSpec, 0.5);

  new brush.Polygon(grinOuter).draw("rotring", INK, 1.0);

  // Left and right silhouette ink outlines of the cast-iron body
  let leftSil = [];
  let rightSil = [];
  for (let y = yStart; y <= yEnd; y += 10) {
    leftSil.push([cx - getBodyHalfWidth(y), y]);
    rightSil.push([cx + getBodyHalfWidth(y), y]);
  }
  brush.set("rotring", INK, 1.05);
  brush.spline(leftSil, 0.5);
  brush.spline(rightSil, 0.5);

  // 5. THE DISPENSED EYEBALL-GUMBALL DROPPING OUT OF THE CHUTE ONTO THE COUNTER!
  // Starts at (612, 926, r = 26) at t = 0, drops through the chute in frames 2..8,
  // bounces onto the foreground counter at (568, 1068, r = 44), and stares up at the viewer!
  let dropX, dropY, dropR, dropRot;
  if (t < 0.26) {
    // Plunging down out of the chute mouth onto the counter
    let u = t / 0.26;
    dropX = lerp(612, 594, u);
    dropY = lerp(926, 1064, u * u);
    dropR = lerp(26, 43, u);
    dropRot = lerp(4, -35, u);
  } else if (t < 0.48) {
    // First big elastic bounce on the diner counter!
    let u = (t - 0.26) / 0.22;
    let arcH = 4 * u * (1 - u);
    dropX = lerp(594, 574, u);
    dropY = 1064 - arcH * 52;
    dropR = 43 + arcH * 2;
    dropRot = lerp(-35, 18, u);
  } else if (t < 0.68) {
    // Second smaller bounce
    let u = (t - 0.48) / 0.20;
    let arcH = 4 * u * (1 - u);
    dropX = lerp(574, 562, u);
    dropY = 1066 - arcH * 20;
    dropR = 44;
    dropRot = lerp(18, -6, u);
  } else {
    // Settled on the foreground counter, rolling slightly and staring dead-on at the viewer
    let u = constrain((t - 0.68) / 0.40, 0, 1);
    dropX = lerp(562, 556, easeOutCubic(u)) + sin(t * 240) * 1.5;
    dropY = 1066;
    dropR = 44;
    dropRot = lerp(-6, 0, easeOutCubic(u));
  }

  // Cast shadow of the dropped eyeball on the counter
  if (t > 0.12) {
    let shScale = map(constrain(dropY, 940, 1066), 940, 1066, 0.4, 1.0);
    let shPts = makeEllipsePts(dropX, 1076, dropR * 0.95 * shScale, dropR * 0.32 * shScale, 0, 28);
    fillPolyWash(shPts, INK, floor(230 * shScale));
  }

  const dropPose = getUnisonEyePose(6, t);
  randomSeed(8899);
  noiseSeed(8899);
  drawAnimatedEyeball(
    6,
    dropX,
    dropY,
    dropR,
    "mint",
    dropPose.gx * 0.6,
    dropPose.gy * 0.5 - 0.06,
    dropRot,
    dropPose.pupilScale,
    dropPose.irisScale,
    dropPose.blink,
    easeStart
  );
}

// Flexing hot-rod black pen & mint pinstripe flourishes curling off the bumped base
function drawAnimatedPinstripes(cx, t, bump) {
  const flex = bump.dx * 1.15 + sin(t * 360) * 9.0 * exp(-t * 1.4);
  const lift = bump.dy * 0.65 + cos(t * 420) * 6.0 * exp(-t * 1.5);

  const bodyScrolls = [
    [
      [96, 735, 0.4],
      [138, 756, 1.1],
      [148, 804, 1.2],
      [114, 848, 0.9],
      [134, 895, 1.1],
      [182, 938, 1.3],
      [226, 976, 0.5]
    ],
    [
      [88, 748, 0.3],
      [122, 768, 0.9],
      [130, 806, 1.0],
      [102, 846, 0.8],
      [118, 888, 0.9],
      [162, 932, 1.0],
      [202, 968, 0.3]
    ],
    [
      [35, 964, 0.5],
      [92, 974, 1.2],
      [158, 960, 1.1],
      [212, 928, 0.9],
      [194, 898, 0.6],
      [168, 912, 0.4]
    ]
  ];

  for (let sc of bodyScrolls) {
    let offsetSc = sc.map((p) => [p[0] + 2.5, p[1] + 2.5, p[2]]);
    drawSymmetricSpline(cx, offsetSc, "rotring", PAPER, 0.65, 0.6);
    drawSymmetricSpline(cx, sc, "sword_striper", INK, 1.05, 0.6);
  }

  // Whipping outer base curls that flex outward with a tip lag when the machine is bumped
  const baseCurls = [
    [
      [185, 992, 0.5],
      [255, 1005, 1.3],
      [348, 982, 1.4],
      [428, 926, 1.2],
      [452, 858, 1.0],
      [412, 808, 0.9],
      [358, 824, 0.8],
      [346, 872, 0.7],
      [384, 892, 0.4]
    ],
    [
      [215, 1010, 0.6],
      [308, 1032, 1.4],
      [422, 1018, 1.3],
      [512, 968, 1.1],
      [546, 898, 0.9],
      [515, 845, 0.7],
      [468, 862, 0.5]
    ],
    [
      [135, 1020, 0.5],
      [195, 1058, 1.3],
      [295, 1084, 1.4],
      [398, 1068, 1.2],
      [456, 1022, 1.0],
      [438, 976, 0.8],
      [388, 984, 0.6],
      [378, 1018, 0.4]
    ]
  ];

  for (let curl of baseCurls) {
    let flexedCurl = curl.map((p, idx) => {
      let w = idx / max(1, curl.length - 1);
      return [p[0] + flex * w * 1.4, p[1] + lift * w * 1.4, p[2]];
    });
    let mintEcho = flexedCurl.map((p) => [p[0] * 0.98 - 3, p[1] + 4, p[2] * 0.8]);
    drawSymmetricSpline(cx, mintEcho, "rotring", MINT_BRIGHT, 0.75, 0.65);
    drawSymmetricSpline(cx, flexedCurl, "sword_striper", INK, 1.18, 0.65);
  }
}

function clampPtToCircle(px, py, cx, cy, maxR) {
  let dx = px - cx;
  let dy = py - cy;
  let d = sqrt(dx * dx + dy * dy);
  if (d > maxR && d > 0.0001) {
    let s = maxR / d;
    return [cx + dx * s, cy + dy * s];
  }
  return [px, py];
}

function clampPolyToCircle(pts, cx, cy, maxR) {
  return pts.map((p) => clampPtToCircle(p[0], p[1], cx, cy, maxR));
}

function drawAnimatedEyeball(
  eyeIdx,
  cx,
  cy,
  r,
  irisStyle,
  gazeX,
  gazeY,
  rotDeg,
  pupilScale,
  irisScale,
  blink,
  easeStart
) {
  const def = EYE_DEFS[eyeIdx];
  const rec = eyeRecords[eyeIdx];
  const dgx = (gazeX - def.gx) * r;
  const dgy = (gazeY - def.gy) * r;
  const dRot = (rotDeg - def.rot) * 0.35;

  // 0. Opaque base knockout inside the eyeball sphere so Frame 0 never ghosts through
  let baseDark = makeCirclePts(cx, cy, r - 0.4, 36);
  fillPolyWash(baseDark, "#221734", 255);

  // 1. Sclera spherical base — twilight violet-grey shadow rim + warm fleshy pink corner
  let outerPts = makeCirclePts(cx, cy, r, 36);
  fillPolyWash(outerPts, "#635375", 240);

  let flushPts = makeCirclePts(
    cx + r * 0.1 + dgx * 0.14,
    cy + r * 0.12 + dgy * 0.14,
    r * 0.88,
    32
  );
  fillPolyWash(clampPolyToCircle(flushPts, cx, cy, r * 0.98), "#e38898", 190);

  let scleraLit = makeCirclePts(cx - r * 0.08, cy - r * 0.08, r * 0.85, 32);
  fillPolyWash(scleraLit, CREAM_BRIGHT, 235);

  let scleraCore = makeCirclePts(cx - r * 0.14, cy - r * 0.14, r * 0.7, 28);
  fillPolyWash(scleraCore, PAPER, 240);

  // Spherical shadow crescent on bottom-right of eyeball
  brush.set("fine_marker", "#473659", 1.7);
  brush.arc(cx, cy, r * 0.88, 10, 135);
  brush.set("fine_marker", "#b84b63", 1.2);
  brush.arc(cx, cy, r * 0.8, 25, 150);

  // 2. Branching bloodshot capillaries (stretching with the swiveling iris)
  const numVeins = 11;
  for (let v = 0; v < numVeins; v++) {
    const vr = rec.veins[v];
    let baseAngle = v * (360 / numVeins) + vr.r_base + dRot;
    let rStart = r * 0.94;
    let rMid = r * vr.r_mid;
    let rEnd = r * vr.r_end;

    let p0 = clampPtToCircle(
      cx + cos(baseAngle) * rStart + dgx * 0.18,
      cy + sin(baseAngle) * rStart + dgy * 0.18,
      cx, cy, r * 0.95
    );
    let p1 = clampPtToCircle(
      cx + cos(baseAngle + vr.r_x1) * rMid + dgx * 0.52,
      cy + sin(baseAngle + vr.r_y1) * rMid + dgy * 0.52,
      cx, cy, r * 0.92
    );
    let p2 = clampPtToCircle(
      cx + cos(baseAngle + vr.r_x2) * rEnd + dgx * 0.82,
      cy + sin(baseAngle + vr.r_y2) * rEnd + dgy * 0.82,
      cx, cy, r * 0.89
    );

    let forkAngle = baseAngle + vr.r_fork * (v % 2 === 0 ? 1 : -1);
    let pf = clampPtToCircle(
      cx + cos(forkAngle) * rEnd + dgx * 0.82,
      cy + sin(forkAngle) * rEnd + dgy * 0.82,
      cx, cy, r * 0.89
    );

    brush.set("pen", PINK_BUBBLE, 0.55);
    brush.line(p0[0], p0[1], p1[0], p1[1]);

    brush.set("rotring", CANDY_RED, 0.42);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    brush.set("rotring", CANDY_MID, 0.32);
    brush.line(p1[0], p1[1], pf[0], pf[1]);
  }

  // 3. THE IRIS (3D foreshortened & swelling forward as it locks on viewer)
  let ix = cx + gazeX * r;
  let iy = cy + gazeY * r;
  let irisR = r * 0.47 * (irisScale || 1.0);

  let gazeMag = constrain(dist(0, 0, gazeX, gazeY), 0, 0.65);
  let foreshorten = 1 - gazeMag * lerp(0.35, 0.46, easeStart);
  let irisRx = irisR * foreshorten;
  let irisRy = irisR;

  let gazeAngle = atan2(gazeY, gazeX);
  let alignWeight = easeStart * constrain((gazeMag - 0.12) / 0.25, 0, 1);
  let angleDiff = ((gazeAngle - rotDeg + 540) % 360) - 180;
  let ellipseRot = rotDeg + angleDiff * alignWeight;

  const irisPalettes = {
    mint: { limbal: "#0b2e28", outer: MINT_DARK, mid: MINT_MID, inner: MINT_BRIGHT, spark: MINT_PALE, collarette: "#f0d060" },
    amber: { limbal: "#2b0d08", outer: CANDY_DARK, mid: "#d45b12", inner: "#ffad29", spark: "#fff099", collarette: CANDY_RED },
    iceBlue: { limbal: "#0d1b36", outer: "#1c4973", mid: "#3598c4", inner: "#7ce8ff", spark: PAPER, collarette: PINK_LIGHT },
    crimsonHazel: { limbal: "#260714", outer: "#6b152b", mid: "#ba3c30", inner: "#e09f3e", spark: "#ffdf80", collarette: MINT_BRIGHT },
    emerald: { limbal: "#08291e", outer: "#125e42", mid: "#22b573", inner: "#68f7a6", spark: "#d4ffe4", collarette: "#ffbe4f" },
    violet: { limbal: "#1a0926", outer: TWI_PLUM, mid: PINK_DARK, inner: PINK_BUBBLE, spark: PINK_LIGHT, collarette: MINT_PALE }
  };
  let ip = irisPalettes[irisStyle] || irisPalettes.mint;

  // Dark limbal ring
  let limbalPts = clampPolyToCircle(
    makeEllipsePts(ix, iy, irisRx * 1.06, irisRy * 1.06, ellipseRot, 32),
    cx, cy, r * 0.965
  );
  fillPolyWash(limbalPts, ip.limbal, 245);

  // Outer iris body
  let irisOuterPts = clampPolyToCircle(
    makeEllipsePts(ix, iy, irisRx, irisRy, ellipseRot, 32),
    cx, cy, r * 0.96
  );
  fillPolyWash(irisOuterPts, ip.outer, 235);

  // Mid & inner glowing iris rings
  let irisMidPts = clampPolyToCircle(
    makeEllipsePts(ix, iy, irisRx * 0.84, irisRy * 0.84, ellipseRot, 28),
    cx, cy, r * 0.95
  );
  fillPolyWash(irisMidPts, ip.mid, 225);

  let innerScale = constrain(0.58 * lerp(1.0, pupilScale, 0.55), 0.42, 0.82);
  let irisInnerPts = clampPolyToCircle(
    makeEllipsePts(ix, iy, irisRx * innerScale, irisRy * innerScale, ellipseRot, 24),
    cx, cy, r * 0.94
  );
  fillPolyWash(irisInnerPts, ip.inner, 220);

  // Radial iris stroma fibers
  let ca = cos(ellipseRot);
  let sa = sin(ellipseRot);
  let torsionShift = rotDeg - ellipseRot;
  let r0 = constrain(0.34 * pupilScale, 0.18, 0.64);

  for (let i = 0; i < 42; i++) {
    const fr = rec.fibers[i];
    let a = (i / 42) * 360 + fr.r_a + torsionShift;
    let r1 = max(r0 + 0.08, fr.r_r1);
    let lx0 = cos(a) * irisRx * r0;
    let ly0 = sin(a) * irisRy * r0;
    let lx1 = cos(a) * irisRx * r1;
    let ly1 = sin(a) * irisRy * r1;

    let p0 = clampPtToCircle(ix + lx0 * ca - ly0 * sa, iy + lx0 * sa + ly0 * ca, cx, cy, r * 0.94);
    let p1 = clampPtToCircle(ix + lx1 * ca - ly1 * sa, iy + lx1 * sa + ly1 * ca, cx, cy, r * 0.95);

    let fCol = i % 3 === 0 ? ip.spark : i % 3 === 1 ? ip.limbal : ip.collarette;
    brush.set("rotring", fCol, i % 3 === 0 ? 0.45 : 0.35);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Upper corneal shadow across top of iris
  brush.set("fine_marker", ip.limbal, 1.3);
  brush.arc(ix, iy, irisR * 0.9 * foreshorten, 200, 340);

  // 4. DEEP JET-BLACK PUPIL (dilating huge as it locks onto the viewer)
  let pupFrac = constrain(0.38 * pupilScale, 0.20, 0.68);
  let pupilPts = clampPolyToCircle(
    makeEllipsePts(ix, iy, irisRx * pupFrac, irisRy * pupFrac, ellipseRot, 24),
    cx, cy, r * 0.93
  );
  fillPolyWash(pupilPts, INK, 255);
  brush.set("rotring", INK, 0.9);
  brush.circle(ix, iy, irisR * (pupFrac - 0.02) * foreshorten, 0.01);

  // 5. RAZOR-SHARP WET WINDOW SPECULAR HIGHLIGHTS (Clean Paper)
  let ix0 = cx + def.gx * r;
  let iy0 = cy + def.gy * r;
  let wx = lerp(ix0, ix, 0.68) - irisR * 0.32;
  let wy = lerp(iy0, iy, 0.68) - irisR * 0.34;
  let winPts = [
    [wx - r * 0.14, wy - r * 0.06],
    [wx + r * 0.10, wy - r * 0.14],
    [wx + r * 0.15, wy + r * 0.04],
    [wx - r * 0.08, wy + r * 0.12]
  ];
  fillPolyWash(winPts, PAPER, 255);
  brush.set("paper_spec", PAPER, 1.35);
  brush.line(wx - r * 0.1, wy - r * 0.04, wx + r * 0.08, wy - r * 0.1);
  brush.line(wx - r * 0.06, wy + r * 0.04, wx + r * 0.11, wy - r * 0.02);

  brush.set("paper_spec", PAPER, 1.15);
  brush.arc(ix, iy, irisR * 0.78 * foreshorten, 30, 75);
  brush.arc(cx, cy, r * 0.85, 55, 115);

  // 6. WET FLESHY EYELID BLINK (sweeping over the eyeball during unison blinks)
  if (blink > 0.02) {
    // Upper glossy bubblegum-pink eyelid sweeping down from top arc (180..360 deg)
    let upperLid = [];
    for (let a = 180; a <= 360; a += 10) {
      upperLid.push([cx + cos(a) * r, cy + sin(a) * r]);
    }
    let meetY = cy + r * 0.15 * blink;
    let openGap = r * (1.0 - blink);
    for (let u = 1; u >= -1; u -= 0.125) {
      let lx = cx + u * r * 0.98;
      let ly = meetY - openGap * (0.2 + 0.8 * (1 - u * u));
      upperLid.push(clampPtToCircle(lx, ly, cx, cy, r));
    }
    fillPolyWash(upperLid, PINK_DARK, 245);

    let upperHighlight = [];
    for (let u = -0.75; u <= 0.75; u += 0.15) {
      let lx = cx + u * r * 0.85;
      let ly = meetY - openGap * (0.2 + 0.8 * (1 - u * u)) - r * 0.18;
      upperHighlight.push(clampPtToCircle(lx, ly, cx, cy, r * 0.92));
    }
    fillPolyWash(upperHighlight, PINK_BUBBLE, 225);

    // Lower lid sweeping up from bottom arc (0..180 deg)
    let lowerLid = [];
    for (let a = 0; a <= 180; a += 10) {
      lowerLid.push([cx + cos(a) * r, cy + sin(a) * r]);
    }
    for (let u = -1; u <= 1; u += 0.125) {
      let lx = cx + u * r * 0.98;
      let ly = meetY + openGap * (0.2 + 0.7 * (1 - u * u));
      lowerLid.push(clampPtToCircle(lx, ly, cx, cy, r));
    }
    fillPolyWash(lowerLid, CANDY_DARK, 245);

    // Wet specular glint along the blinking eyelid margin & crisp ink crease
    let lidLine = [];
    for (let u = -0.92; u <= 0.92; u += 0.15) {
      let lx = cx + u * r * 0.95;
      let ly = meetY - openGap * (0.2 + 0.8 * (1 - u * u));
      lidLine.push(clampPtToCircle(lx, ly, cx, cy, r * 0.98));
    }
    brush.set("paper_spec", PAPER, 1.25);
    brush.spline(lidLine, 0.5);
    brush.set("rotring", INK, 0.95);
    brush.spline(lidLine, 0.5);
  }

  // Crisp outer eyeball contour
  brush.set("rotring", INK, 0.85);
  brush.circle(cx, cy, r, 0.015);
}

// ============================================================================
// POLYGON & MARKER HELPERS
// ============================================================================

function fillPolyWash(pts, col, opacity = 220) {
  if (pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

function hatchPolyMarker(pts, brushName, col, weight, dist, angle, opts = {}) {
  if (pts.length < 3) return;
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  let p = new brush.Polygon(pts);
  p.hatch(dist, angle, opts);
  brush.noHatch();
}

function makeCirclePts(cx, cy, r, n = 40) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function makeEllipsePts(cx, cy, rx, ry, rotDeg = 0, n = 36) {
  let pts = [];
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

