// ============================================================================
// 2. PERSPECTIVE CHECKERBOARD DINER COUNTER
// ============================================================================

function drawCheckerboardCounter() {
  const yTop = 746;
  const yBot = 1126;
  const vpX = 600;
  const vpY = 420;

  // Base cream/mint wash for the counter surface
  fillPolyWash([[0, yTop], [1200, yTop], [1200, yBot], [0, yBot]], CREAM_MID, 160);

  // Compute perspective rows (8 rows expanding toward viewer)
  const numRows = 8;
  const rowYs = [];
  for (let r = 0; r <= numRows; r++) {
    let t = r / numRows;
    let eased = pow(t, 1.52);
    rowYs.push(lerp(yTop, yBot, eased));
  }

  // Compute columns radiating from vanishing point (vpX, vpY)
  const numCols = 14; // -7 to +7 around center
  function getGridPt(colIdx, yVal) {
    // At yBot, each tile is 145px wide
    let xAtBot = 600 + colIdx * 145;
    let t = (yVal - vpY) / (yBot - vpY);
    let x = vpX + (xAtBot - vpX) * t;
    return [x, yVal];
  }

  // Draw tiles
  for (let r = 0; r < numRows; r++) {
    let y0 = rowYs[r];
    let y1 = rowYs[r + 1];
    for (let c = -numCols; c < numCols; c++) {
      let p00 = getGridPt(c, y0);
      let p10 = getGridPt(c + 1, y0);
      let p11 = getGridPt(c + 1, y1);
      let p01 = getGridPt(c, y1);

      // Skip if completely offscreen
      if (Math.max(p00[0], p10[0], p11[0], p01[0]) < -20) continue;
      if (Math.min(p00[0], p10[0], p11[0], p01[0]) > 1220) continue;

      let isDark = (r + c + 100) % 2 === 0;
      let poly = [p00, p10, p11, p01];

      if (isDark) {
        // Dusky twilight plum-black tile
        let darkCol = r < 3 ? TWI_DEEP : TWI_VOID;
        fillPolyWash(poly, darkCol, 235);
        hatchPolyMarker(poly, "fine_marker", TWI_PLUM, 0.9, 6, 12, { rand: 0.03 });
      } else {
        // Mint-tinted cream diner tile (leaving brightest areas near center as crisp paper)
        let distFromCenter = abs(c + 0.5);
        let lightCol =
          distFromCenter > 4
            ? CREAM_SHADOW
            : r < 2
            ? MINT_PALE
            : CREAM_BRIGHT;
        fillPolyWash(poly, lightCol, distFromCenter < 2.5 ? 95 : 175);
        hatchPolyMarker(
          poly,
          "fine_marker",
          r % 2 === 0 ? MINT_PALE : PINK_LIGHT,
          0.7,
          9,
          0,
          { rand: 0.02 }
        );
      }

      // Crisp tile grout lines in pen
      brush.set("rotring", INK, 0.55);
      brush.line(p00[0], p00[1], p10[0], p10[1]);
      brush.line(p10[0], p10[1], p11[0], p11[1]);
    }
  }

  // Glossy horizontal tabletop streak highlights (reserved clean paper strips)
  brush.set("paper_spec", PAPER, 1.3);
  for (let i = 0; i < 18; i++) {
    let sy = random(760, 1110);
    let sx = random(60, 960);
    let slen = random(60, 210);
    brush.line(sx, sy, sx + slen, sy);
  }

  // Art-Deco Ribbed Chrome Diner Counter Front Apron (y = 1126 to 1200)
  fillPolyWash([[0, 1126], [1200, 1126], [1200, 1200], [0, 1200]], CHROME_DARK, 245);
  const ribYs = [
    { y: 1130, col: PAPER, w: 1.5, brush: "paper_spec" },
    { y: 1136, col: CHROME_LIGHT, w: 1.8, brush: "fine_marker" },
    { y: 1143, col: MINT_BRIGHT, w: 1.2, brush: "fine_marker" },
    { y: 1152, col: TWI_VOID, w: 2.2, brush: "chisel_marker" },
    { y: 1160, col: PAPER, w: 1.3, brush: "paper_spec" },
    { y: 1167, col: PINK_BUBBLE, w: 1.4, brush: "fine_marker" },
    { y: 1176, col: CHROME_MID, w: 2.0, brush: "chisel_marker" },
    { y: 1185, col: PAPER, w: 1.1, brush: "paper_spec" },
    { y: 1193, col: TWI_VOID, w: 2.5, brush: "chisel_marker" }
  ];
  for (let rb of ribYs) {
    brush.set(rb.brush, rb.col, rb.w);
    brush.line(0, rb.y, 1200, rb.y);
  }

  // Vertical chrome seam plates along the counter edge
  for (let x of [160, 600, 1040]) {
    fillPolyWash([[x - 10, 1126], [x + 10, 1126], [x + 10, 1200], [x - 10, 1200]], CHROME_LIGHT, 210);
    brush.set("paper_spec", PAPER, 1.0);
    brush.line(x - 3, 1126, x - 3, 1200);
    brush.set("rotring", INK, 0.8);
    brush.line(x - 10, 1126, x - 10, 1200);
    brush.line(x + 10, 1126, x + 10, 1200);
  }

  brush.set("rotring", INK, 1.1);
  brush.line(0, 1126, 1200, 1126);
}

