function drawSingleGumball(cx, cy, r, theme, isBack) {
  let pts = makeCirclePts(cx, cy, r, 32);

  if (isBack) {
    fillPolyWash(pts, theme.dark, 235);
    let midPts = makeCirclePts(cx - r * 0.15, cy - r * 0.15, r * 0.72, 24);
    fillPolyWash(midPts, theme.mid, 210);
    brush.set("rotring", INK, 0.55);
    brush.circle(cx, cy, r, 0.02);
    return;
  }

  // 1. Ambient shadow base
  fillPolyWash(pts, theme.dark, 240);

  // 2. Main saturated marker body (shifted slightly toward upper-left light source)
  let mainPts = makeCirclePts(cx - r * 0.08, cy - r * 0.08, r * 0.88, 30);
  fillPolyWash(mainPts, theme.mid, 225);

  // 3. Hot saturated crown
  let hotPts = makeCirclePts(cx - r * 0.18, cy - r * 0.18, r * 0.68, 28);
  fillPolyWash(hotPts, theme.bright, 225);

  // 4. Layered marker contour strokes for glossy spherical form
  brush.set("fine_marker", theme.glow, 1.35);
  brush.arc(cx - r * 0.12, cy - r * 0.12, r * 0.55, 195, 295);

  // Shadow crescent on bottom-right
  brush.set("fine_marker", theme.dark, 1.8);
  brush.arc(cx, cy, r * 0.84, 15, 125);
  brush.set("fine_marker", INK, 1.1);
  brush.arc(cx, cy, r * 0.91, 25, 115);

  // Colorful neighbor bounce-light rim on lower-right edge
  brush.set("fine_marker", theme.rim, 1.1);
  brush.arc(cx, cy, r * 0.92, 30, 105);

  // 5. HARD SPECULAR HIGHLIGHT left as clean paper!
  let specX = cx - r * 0.34;
  let specY = cy - r * 0.34;
  let specPoly = makeEllipsePts(specX, specY, r * 0.24, r * 0.14, -42, 20);
  fillPolyWash(specPoly, PAPER, 255);
  brush.set("paper_spec", PAPER, 1.15);
  brush.arc(cx, cy, r * 0.72, 205, 252);
  // Secondary tiny pinpoint glint
  brush.set("paper_spec", PAPER, 1.3);
  brush.line(cx - r * 0.12, cy - r * 0.54, cx - r * 0.06, cy - r * 0.56);

  // Crisp ink contour around gumball
  brush.set("rotring", INK, 0.75);
  brush.circle(cx, cy, r, 0.015);
}

function drawWetEyeball(cx, cy, r, irisStyle, gazeX, gazeY, rotDeg) {
  const rec = { veins: [], fibers: [] };

  // 1. Sclera spherical base — twilight violet-grey shadow rim + warm fleshy pink corner
  let outerPts = makeCirclePts(cx, cy, r, 36);
  fillPolyWash(outerPts, "#635375", 240);

  // Pinkish vascular flush at the lower/side caruncle zone
  let flushPts = makeCirclePts(cx + r * 0.1, cy + r * 0.12, r * 0.88, 32);
  fillPolyWash(flushPts, "#e38898", 190);

  // Creamy-white lit sclera dome
  let scleraLit = makeCirclePts(cx - r * 0.08, cy - r * 0.08, r * 0.85, 32);
  fillPolyWash(scleraLit, CREAM_BRIGHT, 235);

  let scleraCore = makeCirclePts(cx - r * 0.14, cy - r * 0.14, r * 0.7, 28);
  fillPolyWash(scleraCore, PAPER, 240);

  // Spherical shadow crescent on bottom-right of eyeball
  brush.set("fine_marker", "#473659", 1.7);
  brush.arc(cx, cy, r * 0.88, 10, 135);
  brush.set("fine_marker", "#b84b63", 1.2);
  brush.arc(cx, cy, r * 0.8, 25, 150);

  // 2. Branching bloodshot capillaries in fine crimson & pink pen
  const numVeins = 11;
  for (let v = 0; v < numVeins; v++) {
    let r_base = random(-10, 10);
    let baseAngle = v * (360 / numVeins) + r_base;
    let rStart = r * 0.94;
    let r_mid = random(0.66, 0.76);
    let rMid = r * r_mid;
    let r_end = random(0.46, 0.56);
    let rEnd = r * r_end;

    let x0 = cx + cos(baseAngle) * rStart;
    let y0 = cy + sin(baseAngle) * rStart;
    let r_x1 = random(-8, 8);
    let x1 = cx + cos(baseAngle + r_x1) * rMid;
    let r_y1 = random(-8, 8);
    let y1 = cy + sin(baseAngle + r_y1) * rMid;
    let r_x2 = random(-16, 16);
    let x2 = cx + cos(baseAngle + r_x2) * rEnd;
    let r_y2 = random(-16, 16);
    let y2 = cy + sin(baseAngle + r_y2) * rEnd;

    // Soft pink halo around vein
    brush.set("pen", PINK_BUBBLE, 0.55);
    brush.line(x0, y0, x1, y1);

    // Sharp crimson capillary
    brush.set("rotring", CANDY_RED, 0.42);
    brush.line(x0, y0, x1, y1);
    brush.line(x1, y1, x2, y2);

    // Forked micro-branch
    let r_fork = random(10, 22);
    let forkAngle = baseAngle + r_fork * (v % 2 === 0 ? 1 : -1);
    let xf = cx + cos(forkAngle) * rEnd;
    let yf = cy + sin(forkAngle) * rEnd;
    brush.set("rotring", CANDY_MID, 0.32);
    brush.line(x1, y1, xf, yf);

    rec.veins.push({ r_base, r_mid, r_end, r_x1, r_y1, r_x2, r_y2, r_fork });
  }

  // 3. THE IRIS (positioned by gazeX, gazeY)
  let ix = cx + gazeX * r;
  let iy = cy + gazeY * r;
  let irisR = r * 0.47;
  // Slight perspective foreshortening if looking sideways
  let gazeMag = constrain(dist(0, 0, gazeX, gazeY), 0, 0.35);
  let irisRx = irisR * (1 - gazeMag * 0.35);
  let irisRy = irisR;

  const irisPalettes = {
    mint: { limbal: "#0b2e28", outer: MINT_DARK, mid: MINT_MID, inner: MINT_BRIGHT, spark: MINT_PALE, collarette: "#f0d060" },
    amber: { limbal: "#2b0d08", outer: CANDY_DARK, mid: "#d45b12", inner: "#ffad29", spark: "#fff099", collarette: CANDY_RED },
    iceBlue: { limbal: "#0d1b36", outer: "#1c4973", mid: "#3598c4", inner: "#7ce8ff", spark: PAPER, collarette: PINK_LIGHT },
    crimsonHazel: { limbal: "#260714", outer: "#6b152b", mid: "#ba3c30", inner: "#e09f3e", spark: "#ffdf80", collarette: MINT_BRIGHT },
    emerald: { limbal: "#08291e", outer: "#125e42", mid: "#22b573", inner: "#68f7a6", spark: "#d4ffe4", collarette: "#ffbe4f" },
    violet: { limbal: "#1a0926", outer: TWI_PLUM, mid: PINK_DARK, inner: PINK_BUBBLE, spark: PINK_LIGHT, collarette: MINT_PALE }
  };
  let ip = irisPalettes[irisStyle] || irisPalettes.mint;

  // Dark limbal ring
  let limbalPts = makeEllipsePts(ix, iy, irisRx * 1.06, irisRy * 1.06, rotDeg, 32);
  fillPolyWash(limbalPts, ip.limbal, 245);

  // Outer iris body
  let irisOuterPts = makeEllipsePts(ix, iy, irisRx, irisRy, rotDeg, 32);
  fillPolyWash(irisOuterPts, ip.outer, 235);

  // Mid & inner glowing iris rings
  let irisMidPts = makeEllipsePts(ix, iy, irisRx * 0.84, irisRy * 0.84, rotDeg, 28);
  fillPolyWash(irisMidPts, ip.mid, 225);

  let irisInnerPts = makeEllipsePts(ix, iy, irisRx * 0.58, irisRy * 0.58, rotDeg, 24);
  fillPolyWash(irisInnerPts, ip.inner, 220);

  // Obsessive radial iris stroma fibers in pen & fine marker
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  for (let i = 0; i < 42; i++) {
    let r_a = random(-3, 3);
    let a = (i / 42) * 360 + r_a;
    let r0 = 0.34;
    let r_r1 = random(0.86, 0.98);
    let r1 = r_r1;
    let lx0 = cos(a) * irisRx * r0;
    let ly0 = sin(a) * irisRy * r0;
    let lx1 = cos(a) * irisRx * r1;
    let ly1 = sin(a) * irisRy * r1;

    let x0 = ix + lx0 * ca - ly0 * sa;
    let y0 = iy + lx0 * sa + ly0 * ca;
    let x1 = ix + lx1 * ca - ly1 * sa;
    let y1 = iy + lx1 * sa + ly1 * ca;

    let fCol = i % 3 === 0 ? ip.spark : i % 3 === 1 ? ip.limbal : ip.collarette;
    brush.set("rotring", fCol, i % 3 === 0 ? 0.45 : 0.35);
    brush.line(x0, y0, x1, y1);

    rec.fibers.push({ r_a, r_r1 });
  }

  // Upper corneal shadow across top of iris
  brush.set("fine_marker", ip.limbal, 1.3);
  brush.arc(ix, iy, irisR * 0.9, 200, 340);

  // 4. DEEP JET-BLACK PUPIL
  let pupilPts = makeEllipsePts(ix, iy, irisRx * 0.38, irisRy * 0.38, rotDeg, 24);
  fillPolyWash(pupilPts, INK, 255);
  brush.set("rotring", INK, 0.9);
  brush.circle(ix, iy, irisR * 0.36, 0.01);

  // 5. RAZOR-SHARP WET WINDOW SPECULAR HIGHLIGHTS (Clean Paper)
  // Main curved window reflection bridging pupil & upper-left iris
  let wx = ix - irisR * 0.32;
  let wy = iy - irisR * 0.34;
  let winPts = [
    [wx - r * 0.14, wy - r * 0.06],
    [wx + r * 0.10, wy - r * 0.14],
    [wx + r * 0.15, wy + r * 0.04],
    [wx - r * 0.08, wy + r * 0.12]
  ];
  fillPolyWash(winPts, PAPER, 255);
  brush.set("paper_spec", PAPER, 1.35);
  brush.line(wx - r * 0.1, wy - r * 0.04, wx + r * 0.08, wy - r * 0.1);
  brush.line(wx - r * 0.06, wy + r * 0.04, wx + r * 0.11, wy - r * 0.02);

  // Secondary wet tear-meniscus highlight on lower-right of iris & sclera bottom
  brush.set("paper_spec", PAPER, 1.15);
  brush.arc(ix, iy, irisR * 0.78, 30, 75);
  brush.arc(cx, cy, r * 0.85, 55, 115);

  // Crisp outer eyeball contour
  brush.set("rotring", INK, 0.85);
  brush.circle(cx, cy, r, 0.015);

  eyeRecords.push(rec);
}

// ============================================================================
// 6. VINTAGE CAST-METAL MACHINE BODY (CANDY-APPLE RED ENAMEL & CHROME GRIN)
// ============================================================================

function getBodyHalfWidth(y) {
  // y ranges from 690 (neck) to 1015 (base skirt)
  let t = constrain((y - 690) / (1015 - 690), 0, 1);
  if (t < 0.22) {
    // Upper swell below collar
    let u = t / 0.22;
    return lerp(136, 174, sin(u * 90));
  } else if (t < 0.50) {
    // Tapered hourglass waist
    let u = (t - 0.22) / 0.28;
    return lerp(174, 146, sin(u * 90));
  } else if (t < 0.88) {
    // Bell flare toward base
    let u = (t - 0.50) / 0.38;
    return lerp(146, 242, pow(u, 1.15));
  } else {
    // Heavy cast base rim
    let u = (t - 0.88) / 0.12;
    return lerp(242, 260, sin(u * 90));
  }
}

function getBottomCurveY(x, cx, yCenter, dropAmp = 34) {
  let u = constrain((x - cx) / 260, -1, 1);
  return yCenter + (1 - u * u) * dropAmp;
}

function drawMachineBody(cx, collarTopY) {
  // -------------------------------------------------------------------------
  // A. MAIN CANDY-APPLE RED ENAMEL HOURGLASS BODY (y = 690 to 1015)
  // -------------------------------------------------------------------------
  const yStart = 690;
  const yEnd = 1012;

  // Build full silhouette polygon of the cast-metal body
  let bodyOutline = [];
  for (let y = yStart; y <= yEnd; y += 8) {
    bodyOutline.push([cx - getBodyHalfWidth(y), y]);
  }
  for (let u = -1; u <= 1; u += 0.08) {
    let x = cx + u * 260;
    bodyOutline.push([x, getBottomCurveY(x, cx, yEnd, 36)]);
  }
  for (let y = yEnd; y >= yStart; y -= 8) {
    bodyOutline.push([cx + getBodyHalfWidth(y), y]);
  }
  fillPolyWash(bodyOutline, CANDY_DARK, 245);

  // Render vertical contoured enamel bands across normalized horizontal coordinate u in [-1, 1]
  // This produces obsessive kustom-kulture candy-apple gloss!
  const uBands = [
    { u0: -1.00, u1: -0.88, col: TWI_VOID, op: 230 },
    { u0: -0.92, u1: -0.76, col: MINT_BRIGHT, op: 195 }, // Cool diner neon rim reflection
    { u0: -0.78, u1: -0.58, col: CANDY_RED, op: 230 },
    { u0: -0.60, u1: -0.34, col: CANDY_HOT, op: 235 },   // Scorching vermilion halo
    { u0: -0.36, u1: -0.02, col: CANDY_RED, op: 235 },
    { u0: -0.04, u1:  0.34, col: CANDY_MID, op: 235 },
    { u0:  0.32, u1:  0.68, col: CANDY_SHADOW, op: 245 }, // Deep oxblood shadow core
    { u0:  0.66, u1:  0.88, col: CANDY_RED, op: 225 },
    { u0:  0.85, u1:  0.97, col: PINK_BUBBLE, op: 215 }, // Bubblegum counter bounce light
    { u0:  0.95, u1:  1.00, col: TWI_VOID, op: 235 }
  ];

  for (let b of uBands) {
    let stripPts = [];
    for (let y = yStart; y <= yEnd; y += 10) {
      let hw = getBodyHalfWidth(y);
      let curveDrop = (1 - b.u0 * b.u0) * 32 * ((y - yStart) / (yEnd - yStart));
      stripPts.push([cx + b.u0 * hw, y + curveDrop]);
    }
    for (let y = yEnd; y >= yStart; y -= 10) {
      let hw = getBodyHalfWidth(y);
      let curveDrop = (1 - b.u1 * b.u1) * 32 * ((y - yStart) / (yEnd - yStart));
      stripPts.push([cx + b.u1 * hw, y + curveDrop]);
    }
    fillPolyWash(stripPts, b.col, b.op);
  }

  // Layered contour marker strokes following the hourglass curvature
  for (let u = -0.92; u <= 0.92; u += 0.045) {
    let col =
      u < -0.78
        ? MINT_PALE
        : u < -0.56
        ? CANDY_RED
        : u < -0.36
        ? CANDY_HOT
        : u < 0.0
        ? CANDY_RED
        : u < 0.32
        ? CANDY_MID
        : u < 0.68
        ? CANDY_SHADOW
        : u < 0.85
        ? CANDY_RED
        : PINK_LIGHT;

    let pts = [];
    for (let y = yStart + 6; y <= yEnd - 4; y += 16) {
      let hw = getBodyHalfWidth(y);
      let drop = (1 - u * u) * 30 * ((y - yStart) / (yEnd - yStart));
      pts.push([cx + u * hw, y + drop]);
    }
    brush.set("chisel_marker", col, 1.5);
    brush.spline(pts, 0.5);
  }

  // HARD CLEAN-PAPER SPECULAR HIGHLIGHT RIBBONS along left-front curve (u ~ -0.48)
  for (let uOff of [-0.50, -0.47, -0.44, -0.35]) {
    let w = uOff === -0.35 ? 0.9 : 1.75;
    let pts = [];
    for (let y = yStart + 12; y <= yEnd - 8; y += 16) {
      let hw = getBodyHalfWidth(y);
      let drop = (1 - uOff * uOff) * 30 * ((y - yStart) / (yEnd - yStart));
      pts.push([cx + uOff * hw, y + drop]);
    }
    brush.set("paper_spec", PAPER, w);
    brush.spline(pts, 0.5);
  }

  // Secondary horizontal waist & flare ring highlights in clean paper
  for (let yRing of [752, 845, 968]) {
    let hw = getBodyHalfWidth(yRing);
    let rPts = [];
    for (let u = -0.68; u <= -0.18; u += 0.1) {
      let drop = (1 - u * u) * 26 * ((yRing - yStart) / (yEnd - yStart));
      rPts.push([cx + u * hw, yRing + drop]);
    }
    brush.set("paper_spec", PAPER, 1.35);
    brush.spline(rPts, 0.5);
  }

  // -------------------------------------------------------------------------
  // B. STEPPED HEAVY BASE FOOT & CHROME TRIM RING (y = 975 to 1045)
  // -------------------------------------------------------------------------
  let footPts = [];
  for (let u = -1; u <= 1; u += 0.06) {
    footPts.push([cx + u * 252, getBottomCurveY(cx + u * 252, cx, 974, 30)]);
  }
  for (let u = 1; u >= -1; u -= 0.06) {
    footPts.push([cx + u * 266, getBottomCurveY(cx + u * 266, cx, 1012, 38)]);
  }
  fillPolyWash(footPts, CANDY_SHADOW, 240);

  // Vivid candy-red & paper highlight on stepped foot rim
  for (let d = 0; d <= 34; d += 4) {
    let yR = 976 + d;
    let wR = lerp(250, 265, d / 34);
    let col = d < 8 ? PAPER : d < 18 ? CANDY_HOT : d < 28 ? CANDY_RED : INK;
    let bName = d < 8 ? "paper_spec" : "fine_marker";
    let pts = [];
    for (let u = -0.95; u <= 0.95; u += 0.1) {
      if (d < 8 && (u < -0.75 || u > 0.15)) continue;
