  brush.set("chisel_marker", PINK_BUBBLE, 1.8);
  brush.arc(cx, cy, r - 4, 308, 405);
  brush.set("paper_spec", PAPER, 1.3);
  brush.arc(cx, cy, r - 2, 320, 390);

  // 2. Large sweeping curved diner-window highlight on upper-left of glass globe
  // Left as crisp clean paper with a translucent mint/white marker halo!
  let winArc1 = [];
  let winArc2 = [];
  for (let a = 192; a <= 248; a += 4) {
    winArc1.push([cx + cos(a) * (r * 0.86), cy + sin(a) * (r * 0.86)]);
  }
  for (let a = 248; a >= 192; a -= 4) {
    winArc2.push([cx + cos(a) * (r * 0.72), cy + sin(a) * (r * 0.72)]);
  }
  let bigGlassHighlight = winArc1.concat(winArc2);
  fillPolyWash(bigGlassHighlight, PAPER, 240);

  // Crisp window frame bars cutting across the curved glass highlight
  brush.set("paper_spec", PAPER, 2.1);
  brush.arc(cx, cy, r * 0.83, 194, 246);
  brush.arc(cx, cy, r * 0.78, 196, 244);
  brush.arc(cx, cy, r * 0.74, 198, 242);

  // Secondary lower-left glass streak
  brush.set("paper_spec", PAPER, 1.6);
  brush.arc(cx, cy, r * 0.84, 152, 178);
  brush.arc(cx, cy, r * 0.78, 156, 174);

  // Upper-right curved glass reflection arc
  brush.set("fine_marker", MINT_PALE, 1.6);
  brush.arc(cx, cy, r * 0.84, 295, 342);
  brush.set("paper_spec", PAPER, 1.5);
  brush.arc(cx, cy, r * 0.81, 300, 336);

  // Outer glass globe contour in crisp ink
  brush.set("rotring", INK, 1.05);
  brush.circle(cx, cy, r, 0.01);
  brush.set("rotring", INK, 0.6);
  brush.circle(cx, cy, r - 6, 0.01);

  // 3. TOP CAST-CHROME & CANDY-RED ACORN LOCK FINIAL (y = 104 to 176)
  // Seated cap ring on top of globe (y = 152 to 176)
  let capBase = [];
  for (let u = -1; u <= 1; u += 0.1) {
