    225
  );
  brush.set("paper_spec", PAPER, 1.6);
  brush.line(cx - 34, 150, cx - 22, 124);
  brush.line(cx - 18, 150, cx - 10, 122);

  // Acorn key-lock tip at (cx, 108)
  let acornPts = makeEllipsePts(cx, 108, 16, 14, 0, 20);
