  brush.circle(cx, 108, 15, 0.01);
}

// ============================================================================
// 8. HOT-ROD BLACK PEN PINSTRIPE FLOURISHES CURLING OFF THE BASE
// ============================================================================

function drawSymmetricSpline(cx, pts, brushName, col, weight, curvature = 0.65) {
  let leftPts = pts.map((p) => [cx - p[0], p[1], p[2] !== undefined ? p[2] : 1.0]);
  let rightPts = pts.map((p) => [cx + p[0], p[1], p[2] !== undefined ? p[2] : 1.0]);

  brush.set(brushName, col, weight);
  brush.spline(leftPts, curvature);
  brush.spline(rightPts, curvature);
}

function drawTeardrop(x, y, angleDeg, len, wid, col) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let pts = [
    [x, y],
    [x + ca * len * 0.65 - sa * wid, y + sa * len * 0.65 + ca * wid],
    [x + ca * len, y + sa * len],
    [x + ca * len * 0.65 + sa * wid, y + sa * len * 0.65 - ca * wid]
  ];
  fillPolyWash(pts, col, 250);
  brush.set("rotring", INK, 0.55);
  let p = new brush.Polygon(pts);
  p.draw("rotring", INK, 0.55);
}

function drawHotRodPinstripes(cx) {
  // -------------------------------------------------------------------------
  // A. KUSTOM-KULTURE SCROLLWORK ON THE CANDY-APPLE RED ENAMEL BODY
  // -------------------------------------------------------------------------
  const bodyScrolls = [
    // Flanking cheek scrolls around the coin shield
    [
      [96, 735, 0.4],
      [138, 756, 1.1],
      [148, 804, 1.2],
      [114, 848, 0.9],
      [134, 895, 1.1],
      [182, 938, 1.3],
      [226, 976, 0.5]
    ],
    // Inner harmonic echo line
    [
      [88, 748, 0.3],
      [122, 768, 0.9],
      [130, 806, 1.0],
      [102, 846, 0.8],
      [118, 888, 0.9],
      [162, 932, 1.0],
      [202, 968, 0.3]
    ],
    // Lower skirt bat-wing flourish framing the chrome grin
    [
      [35, 964, 0.5],
      [92, 974, 1.2],
      [158, 960, 1.1],
      [212, 928, 0.9],
      [194, 898, 0.6],
      [168, 912, 0.4]
    ]
  ];

  // Subtle cream/mint shadow-liner offset for true kustom-kulture depth
  for (let sc of bodyScrolls) {
    let offsetSc = sc.map((p) => [p[0] + 2.5, p[1] + 2.5, p[2]]);
    drawSymmetricSpline(cx, offsetSc, "rotring", PAPER, 0.65, 0.6);
    drawSymmetricSpline(cx, sc, "sword_striper", INK, 1.05, 0.6);
  }

  // -------------------------------------------------------------------------
  // B. ELABORATE BLACK PEN PINSTRIPE FLOURISHES CURLING OFF THE BASE!
  // Curling right off the cast-metal base onto the diner counter and air
  // -------------------------------------------------------------------------
  const baseCurls = [
    // 1. Primary sweeping master scroll curling out from base rim onto counter
    [
      [185, 992, 0.5],
      [255, 1005, 1.3],
      [348, 982, 1.4],
      [428, 926, 1.2],
      [452, 858, 1.0],
      [412, 808, 0.9],
      [358, 824, 0.8],
      [346, 872, 0.7],
      [384, 892, 0.4]
    ],
    // 2. Outer whip-curl sweeping wide across the checkerboard counter
    [
      [215, 1010, 0.6],
      [308, 1032, 1.4],
      [422, 1018, 1.3],
      [512, 968, 1.1],
      [546, 898, 0.9],
      [515, 845, 0.7],
      [468, 862, 0.5]
    ],
    // 3. Foreground counter-top S-scroll looping toward the bottom corners
    [
      [135, 1020, 0.5],
      [195, 1058, 1.3],
      [295, 1084, 1.4],
      [398, 1068, 1.2],
      [456, 1022, 1.0],
      [438, 976, 0.8],
      [388, 984, 0.6],
      [378, 1018, 0.4]
    ],
    // 4. Tight inner counter-scroll hugging the base shadow
    [
      [55, 1028, 0.4],
      [115, 1066, 1.2],
      [205, 1096, 1.3],
      [272, 1082, 1.0],
      [290, 1044, 0.8],
      [252, 1026, 0.5]
    ],
    // 5. Center-front spider-dagger flourish pointing toward viewer on counter
    [
      [0, 1022, 0.8],
      [28, 1062, 1.2],
      [18, 1102, 1.0],
      [52, 1118, 0.7],
      [84, 1098, 0.5]
    ],
    // 6. Upper-base reverse curl rising into the twilight air beside the waist
    [
      [228, 945, 0.5],
      [296, 918, 1.2],
      [348, 862, 1.1],
      [342, 795, 0.9],
      [298, 768, 0.7],
      [268, 792, 0.5],
      [284, 822, 0.3]
    ]
  ];

  // Draw crisp paper/mint double-line backing so black pen pops over dark tiles too
  for (let curl of baseCurls) {
    let haloCurl = curl.map((p) => [p[0] + 2.5, p[1] + 2.5, p[2] * 0.8]);
    drawSymmetricSpline(cx, haloCurl, "rotring", PAPER, 0.85, 0.65);

    let mintEcho = curl.map((p) => [p[0] * 0.97 - 4, p[1] + 5, p[2] * 0.65]);
    drawSymmetricSpline(cx, mintEcho, "rotring", MINT_BRIGHT, 0.55, 0.65);
  }

  // Draw main razor-sharp black pen & sword-striper flourishes
  for (let curl of baseCurls) {
    drawSymmetricSpline(cx, curl, "sword_striper", INK, 1.18, 0.65);
    drawSymmetricSpline(cx, curl, "rotring", INK, 0.75, 0.65);
  }

  // Classic Von Dutch central diamond-dagger & teardrops at the front of the base
  const teardrops = [
    { dx: 0, y: 982, a: 90, l: 28, w: 6, col: INK },
    { dx: 0, y: 1052, a: 90, l: 34, w: 7, col: CANDY_RED },
    { dx: 325, y: 954, a: -25, l: 26, w: 5.5, col: INK },
    { dx: 465, y: 942, a: -40, l: 24, w: 5, col: INK },
    { dx: 322, y: 1055, a: 18, l: 26, w: 5.5, col: INK }
  ];

  for (let td of teardrops) {
    if (td.dx === 0) {
      drawTeardrop(cx, td.y, td.a, td.l, td.w, td.col);
    } else {
      drawTeardrop(cx - td.dx, td.y, 180 - td.a, td.l, td.w, td.col);
      drawTeardrop(cx + td.dx, td.y, td.a, td.l, td.w, td.col);
    }
  }

  // Fine cross-tick accents along the master pinstripe stems
  for (let dx of [265, 280, 295]) {
    let ty = 1006 - (dx - 265) * 0.35;
    brush.set("rotring", INK, 0.7);
    brush.line(cx - dx, ty - 9, cx - dx - 6, ty + 9);
    brush.line(cx + dx, ty - 9, cx + dx + 6, ty + 9);
  }
}

10-skillet:
// MOTION: The egg white blisters and curls vigorously in boiling oil, ink spatters fly up and out of the pan, the yolk wobbles boldly, and wavy ink heat-shimmer lines rise above the skillet.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;

// Hyperrealistic Linocut / Wood-Engraving of a Cast-Iron Skillet with a Fried Egg
// Rendered entirely with p5.brush via swelling, tapering gouge marks and flow-field lines

const PAPER_BG = "#efe5d4";
