const PHI_SPOUT1 = PHI_HANDLE - Math.PI / 2; // ~51.5 deg (bottom-right pour spout)
const PHI_SPOUT2 = PHI_HANDLE + Math.PI / 2; // ~231.5 deg (top-left pour spout)

// Egg Center & Yolk Center in Pan-Floor (X, Y) Coordinates
const EX = 16;
const EY = -16;
const YX = 32;
const YY = -28;
const RY_X = 76;
const RY_Y = 76 * KAPPA;
const HY_DOME = 55;

let blisters = [];
let laceHoles = [];

// Animation state & cached layers (initialized on frame 2 after frame 1 is captured)
let stillImg = null;
let animInitialized = false;

const CAV_BOX = { x: 290, y: 310, w: 716, h: 490 };
const NUM_CAV_RINGS = 8;
let cavityRings = [];

let yolkCleanPatch = null;
let yolkSlices = [];
const YOLK_BOX = { x: 588, y: 456, w: 184, h: 152 };
const NUM_YOLK_SLICES = 10;

let heroBlisters = [];
let blisterAnimMeta = [];
let curlingEdgeLobes = [];
let edgeSizzleBubbles = [];
let oilRippleArcs = [];
let wallShimmerArcs = [];
let flyingSpatters = [];
let heatShimmerPlumes = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(RADIANS);
  randomSeed(42719);
  noiseSeed(8319);

  // Register custom linocut gouge and engraving burin brushes
  brush.add("v_gouge", {
    type: "default",
    weight: 1.35,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 26,
    opacity: 255,
    spacing: 0.12,
    pressure: [0.04, 1.35, 0.04],
    noise: 0.16
  });

  brush.add("u_gouge", {
    type: "default",
    weight: 2.1,
    scatter: 0.015,
    sharpness: 0.93,
    grain: 22,
    opacity: 255,
    spacing: 0.14,
    pressure: [0.08, 1.4, 0.08],
    noise: 0.2
  });

  brush.add("burin_flow", {
    type: "default",
    weight: 1.45,
    scatter: 0.01,
    sharpness: 0.95,
    grain: 24,
    opacity: 255,
    spacing: 0.13,
    pressure: [0.25, 1.15, 0.25],
    noise: 0.14
  });

  initEggMicroGeometry();
}

function draw() {
  const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;
  if (frameCount > TOTAL_FRAMES) return;

  translate(-width / 2, -height / 2);

  // Frame 0 (frameCount === 1): paint the exact still, pixel for pixel, and snapshot it
  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // Initialize lifted slices and pre-seeded animation data once on frame 2
  if (!animInitialized) {
    initAnimationData();
    animInitialized = true;
  }

  // Fast, bold onset: already at 62% on frame 2, 88% on frame 3, 100% by frame 4
  const t = (frameCount - 1) / window.PIECE_FPS;
  const env = constrain((frameCount - 1) / 3.0, 0, 1);

  // Stamp the cached still painting
  background(PAPER_BG);
  image(stillImg, 0, 0, width, height);

  // 1. Ripple and heave the concentric skillet-floor and egg-white layers
  drawRipplingCavityAndEgg(t, env);

  // 2. Boldly wobble, slosh, and squash-stretch the 3D domed yolk
  const yolkMotion = getYolkMotion(t, env);
  drawYolkSliceStack(yolkMotion);

  // 3. Crisp & curl the lacy egg-white perimeter with boiling black-and-white oil pockets
  drawCurlingLacyEdges(t, env);

  // 4. Swell and pop 24 large, high-contrast steam blisters across the entire egg white
  drawAnimatedBlisters(t, env, yolkMotion);

  // 5. Carve the wobbling yolk's sweeping cast shadow, contour ribs & sliding window glints
  drawYolkDynamicGouges(t, env, yolkMotion);

  // 6. Sweep bold hot-oil waves across the iron floor and shimmer the interior iron walls
  drawHotOilAndWallShimmer(t, env);

  // 7. Launch a barrage of oil spatter flecks & droplets up and out of the pan in ink flecks
  drawFlyingOilSpatterBarrage(t, env);

  // 8. Carve bold wavy ink heat-shimmer lines rising above the pan onto the off-white ground
  drawWavyInkHeatShimmer(t, env);
}

function paintStill() {
  background(PAPER_BG);

  // 1. Warm earth-toned rag paper border & subtle relief-print chatter in negative space
  drawPaperAndPrintChatter();

  // 2. Heavy cast shadow under skillet & handle, carved with tapering gouge marks
  drawTabletopCastShadow();

  // 3. Solid printer's-black base silhouettes for the iron skillet
  drawSkilletSolidSilhouettes();

  // 4. Back & side interior sloped wall gouges (hoop contours & vertical relief grooves)
  drawInteriorSlopedWall();

  // 5. Seasoned cast-iron floor: dense parallel flow-field gouges & oil-sheen rings
  drawSeasonedIronFloor();

  // 6. Fried Egg: crispy lacy bubbling edges, undulating albumen, steam blisters & domed yolk
  drawFriedEgg();

  // 7. Bare white oil spatter flecks across the hot iron floor, walls, and egg perimeter
  drawOilSpatterFlecks();

  // 8. Front exterior cast-iron belly (occluding the front floor edge)
  drawExteriorFrontBelly();

  // 9. Top rim & both pour spouts (360-degree swelling contour & bevel gouges)
  drawTopRimAndSpouts();

  // 10. Helper handle (top-right) & main handle with teardrop hole (bottom-left)
  drawHelperHandle();
  drawMainHandle();
}

// ============================================================================
// ANIMATION INITIALIZATION & BOLD LINOCUT MOTION SYSTEMS
