// ============================================================================
// 4. RAILWAY TRACKS, GRAVEL BALLAST, SLEEPERS & CROSSING PLANKING
// ============================================================================
function drawRailwayTrack() {
  brush.noStroke();
  brush.fillBleed(0.01, "out");
  brush.fillTexture(0.5, 0.4);

  // Dark crushed stone ballast bed along trackY(x)
  let ballastPts = [];
  for (let x = -20; x <= 1220; x += 50) {
    ballastPts.push([x, trackY(x) - 18 + random(-2, 2)]);
  }
  for (let x = 1220; x >= -20; x -= 50) {
    ballastPts.push([x, trackY(x) + 22 + random(-3, 3)]);
  }
  brush.fill("#1d232b", 225);
  drawShapePoly(ballastPts, 0.1);
  brush.noFill();

  // Ballast stone texture & snow patches along the track bed
  brush.set("charcoal", "#11151a", 0.55);
  for (let i = 0; i < 240; i++) {
    let bx = random(-10, 1210);
    let by = trackY(bx) + random(-15, 19);
    brush.line(bx, by, bx + random(2, 5), by + random(-1, 2));
  }

  // Wooden railway sleepers (ties) in perspective
  for (let x = -10; x <= 1210; x += 26) {
    let ty = trackY(x);
    // Skip central part of roadway where crossing planks cover the sleepers
    let inCrossing = (x > 295 && x < 575);
    if (!inCrossing) {
      // Dark creosote timber sleeper
      brush.noStroke();
      brush.wash("#141212", 235);
      drawShapePoly([
        [x - 7, ty - 15],
        [x + 5, ty - 16],
        [x + 12, ty + 16],
        [x - 1, ty + 17]
      ], 0);
      // Crisp white snow cap settled on the upper edge of each sleeper
      brush.wash("#eef5fc", 230);
      drawShapePoly([
        [x - 7, ty - 15],
        [x + 5, ty - 16],
        [x + 6, ty - 12],
        [x - 6, ty - 11]
      ], 0);
      brush.noWash();

      // Fine ink woodgrain & rail spike plates
      brush.set("rotring", "#090b0e", 0.3);
      brush.line(x - 6, ty - 14, x, ty + 16);
      brush.line(x + 4, ty - 15, x + 11, ty + 15);
    }
  }

  // Timber / concrete level crossing planking where the road meets the rails (X = 285..585)
  brush.noStroke();
  brush.fill("#2c343f", 220);
  drawShapePoly([
    [282, trackY(282) - 16],
    [588, trackY(588) - 15],
    [596, trackY(596) + 17],
    [274, trackY(274) + 18]
  ], 0);
  brush.noFill();

  // Plank seams packed with snow
  brush.set("rotring", "#12171d", 0.35);
  for (let o = -11; o <= 13; o += 6) {
    brush.line(280, trackY(280) + o, 592, trackY(592) + o);
  }
  brush.set("cpencil", "#e4edf5", 0.45);
  for (let o = -10; o <= 14; o += 6) {
    brush.line(285, trackY(285) + o, 585, trackY(585) + o);
  }

  // Patches of drifted snow partially burying the ballast outside the crossing
  brush.noStroke();
  brush.wash("#e9f1f8", 220);
  for (let i = 0; i < 28; i++) {
    let sx = random() < 0.4 ? random(0, 270) : random(600, 1190);
    let sy = trackY(sx) + random(-14, 14);
    let sw = random(18, 48);
    let sh = random(4, 9);
    drawShapePoly([
      [sx, sy], [sx + sw * 0.6, sy - sh], [sx + sw, sy - 1], [sx + sw * 0.4, sy + sh * 0.7]
    ], 0.2);
  }
  brush.noWash();

  // TWO PARALLEL STEEL RAILS (Far Rail & Near Rail)
  const railOffsets = [-9, 10];
  for (let rIdx = 0; rIdx < railOffsets.length; rIdx++) {
    let ro = railOffsets[rIdx];
    let yLeft = trackY(-20) + ro;
    let yRight = trackY(1220) + ro * 0.82;

    // 1. Dark steel shadow base and web of the rail
    brush.set("rotring", "#080b10", 0.95);
    brush.line(-20, yLeft + 2.2, 1220, yRight + 2.2);
    brush.set("rotring", "#1b2430", 0.65);
    brush.line(-20, yLeft + 0.8, 1220, yRight + 0.8);

    // 2. Cold polished steel top running surface reflecting the soft peach horizon!
    brush.set("techNib", "#f7d5be", 0.55);
    brush.line(-20, yLeft - 0.6, 1220, yRight - 0.6);
    brush.set("rotring", "#ffffff", 0.3);
    brush.line(180, lerp(yLeft, yRight, 180 / 1240) - 0.8, 920, lerp(yLeft, yRight, 920 / 1240) - 0.8);

    // 3. Rail clips / bolts along sleepers
    brush.set("rotring", "#0c1017", 0.35);
    for (let x = 0; x <= 1200; x += 26) {
      let t = (x + 20) / 1240;
      let ry = lerp(yLeft, yRight, t);
      brush.line(x - 1.5, ry + 2.5, x + 1.5, ry + 2.5);
    }
  }
}

