// 6. BICYCLE TIRE RUT & SOLITARY BOOT FOOTPRINTS IN THE SNOW
// ============================================================================
function drawTireTrackAndFootprints() {
  // --- A. Bicycle Tire Rut in the Fresh Snow ---
  // Curves from foreground left-center (360, 1210) up to rear wheel (885, 1004) and front wheel (535, 980)
  const rutRear = [
    [350, 1210], [455, 1145], [585, 1085], [735, 1042], [885, 1006]
  ];
  const rutFront = [
    [342, 1210], [415, 1120], [475, 1045], [535, 982]
  ];

  for (let rut of [rutRear, rutFront]) {
    // Raised bright snow lip on upper side
    let lipPts = rut.map(p => [p[0] - 3, p[1] - 4]);
    brush.set("cpencil", "#ffffff", 1.1);
    brush.spline(lipPts, 0.4);

    // Shadowed depression of the tire rut
    brush.set("2B", "#5e7894", 0.95);
    brush.spline(rut, 0.4);
    brush.set("rotring", "#3b526b", 0.35);
    brush.spline(rut, 0.4);

    // Fine herringbone tire tread notches inside the snow rut
    brush.set("techNib", "#2d4259", 0.28);
    for (let i = 0; i < rut.length - 1; i++) {
      for (let t = 0; t < 1; t += 0.14) {
        let px = lerp(rut[i][0], rut[i + 1][0], t);
        let py = lerp(rut[i][1], rut[i + 1][1], t);
        brush.line(px - 3, py - 1, px + 3, py + 2);
      }
    }
  }

  // --- B. Trail of Solitary Boot Footprints ---
  // Leading from beside the bicycle pedals (665, 935) up to the lowered barrier (390, 695)
  const steps = [
    { x: 675, y: 952, ang: -135, isLeft: false },
    { x: 622, y: 912, ang: -132, isLeft: true },
    { x: 592, y: 868, ang: -128, isLeft: false },
    { x: 540, y: 832, ang: -125, isLeft: true },
    { x: 512, y: 794, ang: -122, isLeft: false },
    { x: 465, y: 762, ang: -118, isLeft: true },
    { x: 440, y: 730, ang: -115, isLeft: false },
    { x: 402, y: 704, ang: -108, isLeft: true },
    { x: 418, y: 696, ang: -105, isLeft: false } // Standing pair pausing by the crossing
  ];

  for (let st of steps) {
    let sc = map(st.y, 680, 960, 0.48, 1.05);
    drawSingleBootPrint(st.x, st.y, st.ang, sc);
  }
}

function drawSingleBootPrint(cx, cy, ang, sc) {
  push();
  translate(cx, cy);
  rotate(ang);

  let L = 26 * sc;
  let W = 10.5 * sc;

  // 1. Bright displaced snow rim around the footprint (catching warm peach/white sky glow)
  brush.noStroke();
  brush.wash("#fff9f2", 235);
  drawShapePoly([
    [-L * 0.65, -W * 0.65],
    [L * 0.65, -W * 0.75],
    [L * 0.78, 0],
    [L * 0.62, W * 0.75],
    [-L * 0.65, W * 0.65],
    [-L * 0.78, 0]
  ], 0.3);

  // 2. Mid-blue vertical snow wall of the depression
  brush.wash("#6c87a3", 230);
  drawShapePoly([
    [-L * 0.52, -W * 0.46],
    [L * 0.55, -W * 0.54],
    [L * 0.64, 0],
    [L * 0.52, W * 0.54],
    [-L * 0.52, W * 0.46],
    [-L * 0.62, 0]
  ], 0.25);

  // 3. Deep Prussian shadow floor of the sole (front) and heel (back)
  brush.wash("#2b4259", 245);
  // Front sole pad
  drawShapePoly([
    [-L * 0.02, -W * 0.42],
    [L * 0.48, -W * 0.48],
    [L * 0.56, 0],
    [L * 0.46, W * 0.48],
    [-L * 0.02, W * 0.42]
  ], 0.2);
  // Back heel pad
  drawShapePoly([
    [-L * 0.50, -W * 0.38],
    [-L * 0.14, -W * 0.38],
    [-L * 0.14, W * 0.38],
    [-L * 0.50, W * 0.38],
    [-L * 0.56, 0]
  ], 0.15);
  brush.noWash();

  // 4. Crisp boot lug tread ribs inside the print
  brush.set("techNib", "#172636", 0.28 * sc);
  for (let tx = -L * 0.44; tx <= L * 0.46; tx += 3.8 * sc) {
    if (tx > -L * 0.13 && tx < 0) continue; // Arch gap
    brush.line(tx, -W * 0.34, tx, W * 0.34);
  }
  // Crisp snow ridge at the arch bridge
  brush.set("techNib", "#dce8f4", 0.3 * sc);
  brush.line(-L * 0.08, -W * 0.36, -L * 0.08, W * 0.36);

  pop();
}

