}

function drawBicycleWheel(cx, cy, rx, ry, isFront) {
  const tireThick = 14;
  const rimThick = 5.5;
  const rxRim = rx - tireThick;
  const ryRim = ry - tireThick;

  // --- 1. Tangential 3-Cross Spokes (32 Spokes per wheel) ---
  // Drawn before rim/tire so spoke ends tuck neatly into the rim bed
  const numSpokesPerFlange = 16;
  const rHub = 15;
  const flanges = [
    { dx: -5, col: "#344354", w: 0.25, angOff: 0 },  // Far hub flange
    { dx: 4,  col: "#17202b", w: 0.30, angOff: 11.25 } // Near hub flange
  ];

  for (let fl of flanges) {
    for (let i = 0; i < numSpokesPerFlange; i++) {
      let thetaRim = i * (360 / numSpokesPerFlange) + fl.angOff;
      // 3-cross tangential lacing angle (+68 deg for leading spokes, -68 deg for trailing)
      let crossDir = (i % 2 === 0) ? 68 : -68;
      let thetaHub = thetaRim + crossDir;

      let hx = cx + fl.dx + cos(thetaHub) * rHub;
      let hy = cy + sin(thetaHub) * rHub;
      let rmx = cx + cos(thetaRim) * (rxRim - 2);
      let rmy = cy + sin(thetaRim) * (ryRim - 2);

      // Fine, confident Rotring pen line for each spoke
      brush.set("rotring", fl.col, fl.w);
      brush.line(hx, hy, rmx, rmy);

      // Occasional cold sky/peach specular glint along selected spokes
      if ((i + (isFront ? 1 : 0)) % 4 === 0) {
        let gx1 = lerp(hx, rmx, 0.25);
        let gy1 = lerp(hy, rmy, 0.25);
        let gx2 = lerp(hx, rmx, 0.72);
        let gy2 = lerp(hy, rmy, 0.72);
        brush.set("techNib", "#c8d9e8", 0.22);
        brush.line(gx1, gy1, gx2, gy2);
      }

      // Brass/steel spoke nipple at the rim bed
      let nx = cx + cos(thetaRim) * (rxRim - 7);
      let ny = cy + sin(thetaRim) * (ryRim - 7);
      brush.set("rotring", "#8fa3b8", 0.45);
      brush.line(nx, ny, rmx, rmy);
    }
  }

  // Valve stem with tiny dust cap at bottom-left quadrant of wheel
  let vAng = isFront ? 128 : 62;
  let vx1 = cx + cos(vAng) * (rxRim - 1);
  let vy1 = cy + sin(vAng) * (ryRim - 1);
  let vx2 = cx + cos(vAng) * (rxRim - 16);
  let vy2 = cy + sin(vAng) * (ryRim - 16);
  brush.set("rotring", "#1a222b", 0.55);
  brush.line(vx1, vy1, vx2, vy2);
  brush.set("techNib", "#d4b886", 0.4);
  brush.line(vx1, vy1, vx2, vy2);

  // --- 2. Steel Rim & Black Rubber Tire Ring ---
  const steps = 72;
  for (let i = 0; i < steps; i++) {
    let a0 = (i / steps) * 360;
    let a1 = ((i + 1) / steps) * 360;
    let c0 = cos(a0), s0 = sin(a0);
    let c1 = cos(a1), s1 = sin(a1);

    // Chrome/Steel Rim Segment
    let rimCol = (s0 < -0.2) ? "#6e849c" : (s0 > 0.4 ? "#2a3644" : "#4a5c70");
    brush.noStroke();
    brush.wash(rimCol, 248);
    drawShapePoly([
      [cx + c0 * (rxRim - rimThick), cy + s0 * (ryRim - rimThick)],
      [cx + c1 * (rxRim - rimThick), cy + s1 * (ryRim - rimThick)],
      [cx + c1 * rxRim, cy + s1 * ryRim],
      [cx + c0 * rxRim, cy + s0 * ryRim]
    ], 0);

    // Black Rubber Tire Segment
    let tireCol = (s0 < -0.3) ? "#19212b" : "#0b0e13";
    brush.wash(tireCol, 252);
    drawShapePoly([
      [cx + c0 * rxRim, cy + s0 * ryRim],
      [cx + c1 * rxRim, cy + s1 * ryRim],
      [cx + c1 * rx, cy + s1 * ry],
      [cx + c0 * rx, cy + s0 * ry]
    ], 0);
  }
  brush.noWash();

  // Crisp metallic rim specular highlights & ink contours
  let rimInnerPts = [], rimOuterPts = [], tireOuterPts = [];
  for (let a = 0; a <= 360; a += 6) {
    let c = cos(a), s = sin(a);
    rimInnerPts.push([cx + c * (rxRim - rimThick), cy + s * (ryRim - rimThick)]);
    rimOuterPts.push([cx + c * rxRim, cy + s * ryRim]);
    tireOuterPts.push([cx + c * rx, cy + s * ry]);
  }
  brush.set("rotring", "#080b10", 0.42);
  brush.spline(rimInnerPts, 0.4);
  brush.spline(rimOuterPts, 0.4);
  brush.spline(tireOuterPts, 0.4);

  // Cold sky & peach horizon specular arcs along the polished chrome rim
  let rimGlintPts = [];
  for (let a = 200; a <= 335; a += 8) {
    rimGlintPts.push([cx + cos(a) * (rxRim - 2.5), cy + sin(a) * (ryRim - 2.5)]);
  }
  brush.set("techNib", "#e8f1fa", 0.38);
  brush.spline(rimGlintPts, 0.4);

  let rimPeachPts = [];
  for (let a = 25; a <= 155; a += 8) {
    rimPeachPts.push([cx + cos(a) * (rxRim - 2.5), cy + sin(a) * (ryRim - 2.5)]);
  }
  brush.set("techNib", "#f2cbb2", 0.35);
  brush.spline(rimPeachPts, 0.4);

  // Subtle sidewall sheen & molded rubber tread notches around outer edge of tire
  let sidewallPts = [];
  for (let a = 195; a <= 345; a += 8) {
    sidewallPts.push([cx + cos(a) * (rx - 6), cy + sin(a) * (ry - 6)]);
  }
  brush.set("2H", "#4d6178", 0.35);
  brush.spline(sidewallPts, 0.4);

  brush.set("rotring", "#06080b", 0.35);
  for (let a = 0; a < 360; a += 4) {
    let c = cos(a), s = sin(a);
    brush.line(
      cx + c * (rx - 2.5), cy + s * (ry - 2.5),
      cx + c * (rx + 1.2), cy + s * (ry + 1.2)
    );
  }

  // --- 3. Clinging Snow on Lower Tire Treads & Snow Cushion at Ground Contact ---
  // Snow clinging to the bottom arc of the tire (angles 45 to 135)
  brush.noStroke();
  brush.wash("#ffffff", 245);
  for (let a = 42; a <= 138; a += 7) {
    let c = cos(a), s = sin(a);
    let sx = cx + c * (rx - 3);
    let sy = cy + s * (ry - 3);
    let sw = random(4, 9);
    drawShapePoly([
      [sx - sw, sy], [sx, sy - 4], [sx + sw, sy], [sx, sy + 4]
    ], 0.25);
  }
  // Displaced snow pillow where bottom of wheel sinks into the fresh snow drift
  brush.wash("#89a3bd", 225);
  drawShapePoly([
    [cx - 58, cy + ry - 2],
    [cx, cy + ry - 12],
    [cx + 62, cy + ry - 2],
    [cx + 45, cy + ry + 11],
    [cx - 48, cy + ry + 10]
  ], 0.25);
  brush.wash("#ffffff", 252);
  drawShapePoly([
    [cx - 54, cy + ry - 4],
    [cx - 18, cy + ry - 13],
    [cx + 22, cy + ry - 12],
    [cx + 56, cy + ry - 4],
    [cx + 25, cy + ry + 4],
    [cx - 28, cy + ry + 4]
  ], 0.3);
  brush.noWash();

  // --- 4. Wheel Hub & Axle Nut ---
  brush.noStroke();
  brush.wash("#1b232e", 250);
  brush.circle(cx, cy, rHub, 0.04);
  brush.wash("#9cb2c9", 240);
  brush.circle(cx, cy, 8, 0.03);
  brush.wash("#ffffff", 250);
  brush.circle(cx - 2, cy - 2, 3, 0.02);
  brush.noWash();
  brush.set("rotring", "#07090d", 0.4);
  brush.circle(cx, cy, rHub, 0.03);
  brush.circle(cx, cy, 8, 0.03);
}

function drawFendersAndRearRack(FWC, RWC, ST, wheelR) {
  const rFender = wheelR + 9;

  // --- 1. Front Fender (Mudguard: angles 182 to 338) ---
  drawFenderArc(FWC.x, FWC.y, rFender * 0.96, rFender, 182, 338);
  // Thin steel fender stays from front dropout (FWC) to back of front fender
  brush.set("rotring", "#283442", 0.42);
  brush.line(FWC.x, FWC.y, FWC.x + cos(192) * (rFender * 0.96), FWC.y + sin(192) * rFender);
  brush.line(FWC.x, FWC.y, FWC.x + cos(222) * (rFender * 0.96), FWC.y + sin(222) * rFender);
  brush.set("techNib", "#b4c7d9", 0.22);
  brush.line(FWC.x, FWC.y - 1, FWC.x + cos(192) * (rFender * 0.96), FWC.y + sin(192) * rFender - 1);

  // --- 2. Rear Fender (Mudguard: angles 178 to 356) ---
  drawFenderArc(RWC.x, RWC.y, rFender * 0.99, rFender, 178, 356);
  // Rear fender stays
  brush.set("rotring", "#283442", 0.42);
  brush.line(RWC.x, RWC.y, RWC.x + cos(328) * (rFender * 0.99), RWC.y + sin(328) * rFender);
  brush.line(RWC.x, RWC.y, RWC.x + cos(352) * (rFender * 0.99), RWC.y + sin(352) * rFender);

  // Classic white safety paint tip & red reflector on tail of rear fender (angle 332..356)
  let rfTipPts = [];
  for (let a = 335; a <= 355; a += 5) {
    rfTipPts.push([RWC.x + cos(a) * (rFender * 0.99 + 4), RWC.y + sin(a) * (rFender + 4)]);
  }
  for (let a = 355; a >= 335; a -= 5) {
    rfTipPts.push([RWC.x + cos(a) * (rFender * 0.99 - 5), RWC.y + sin(a) * (rFender - 5)]);
  }
  brush.noStroke();
  brush.wash("#e8eff6", 240);
  drawShapePoly(rfTipPts, 0.1);
  // Red rear fender reflector jewel at angle 338
  let refX = RWC.x + cos(338) * (rFender * 0.99 + 3);
  let refY = RWC.y + sin(338) * (rFender + 3);
  brush.wash("#d92920", 250);
  brush.circle(refX, refY, 5.5, 0.03);
  brush.noWash();

  // --- 3. Rear Tubular Steel Carrier Rack (X = 772..962, Y = 710..718) ---
  // Vertical support struts from rear axle (885, 870) to rack (882, 714) and (942, 716)
  drawFrameTube(RWC.x, RWC.y, 882, 714, 5.5, false);
  drawFrameTube(RWC.x + 4, RWC.y, 942, 716, 5.0, false);
  // Horizontal top deck of carrier rack from seatstay bridge (772, 710) to rear (960, 716)
  drawFrameTube(772, 710, 960, 716, 7.5, true);
  // Far-side parallel bar of the rack
  drawFrameTube(776, 703, 954, 709, 5.5, true);
  // Rear ruby reflector on back of carrier rack (962, 716)
  brush.noStroke();
  brush.wash("#e62e25", 250);
  drawShapePoly([[958, 710], [965, 711], [965, 722], [958, 721]], 0);
  brush.noWash();
}

function drawFenderArc(cx, cy, rx, ry, aStart, aEnd) {
  let outerPts = [];
  let innerPts = [];
  for (let a = aStart; a <= aEnd; a += 5) {
    outerPts.push([cx + cos(a) * (rx + 5), cy + sin(a) * (ry + 5)]);
    innerPts.unshift([cx + cos(a) * (rx - 4), cy + sin(a) * (ry - 4)]);
  }
  // Black enameled fender blade
  brush.noStroke();
  brush.wash("#090c11", 252);
  drawShapePoly(outerPts.concat(innerPts), 0.15);
  brush.noWash();

  // Specular highlight & crisp ink border
  let specPts = [];
  for (let a = aStart + 8; a <= aEnd - 8; a += 6) {
    specPts.push([cx + cos(a) * (rx + 2), cy + sin(a) * (ry + 2)]);
  }
  brush.set("techNib", "#7c96b0", 0.35);
  brush.spline(specPts, 0.4);
  brush.set("rotring", "#05070a", 0.4);
  brush.spline(outerPts, 0.4);
  brush.spline(innerPts, 0.4);

  // Chipped paint flecks on fender
  brush.set("techNib", "#9cb0c2", 0.28);
  for (let a = aStart + 15; a < aEnd - 15; a += 22) {
    let px = cx + cos(a) * (rx + 1);
    let py = cy + sin(a) * (ry + 1);
    brush.line(px, py, px + 3, py + 1);
  }

  // Fresh white snow settled along the top crest of the mudguard (angles 232 to 308)
  let sMin = max(aStart + 15, 232);
  let sMax = min(aEnd - 15, 308);
  if (sMax > sMin) {
    let snowTop = [], snowBot = [];
    for (let a = sMin; a <= sMax; a += 5) {
      let env = sin(map(a, sMin, sMax, 0, 180));
      let sh = 6.5 * env + 1.5;
      snowTop.push([cx + cos(a) * (rx + 5 + sh), cy + sin(a) * (ry + 5 + sh)]);
      snowBot.unshift([cx + cos(a) * (rx + 3.5), cy + sin(a) * (ry + 3.5)]);
    }
    brush.noStroke();
    brush.wash("#ffffff", 252);
    drawShapePoly(snowTop.concat(snowBot), 0.2);
    brush.noWash();
    brush.set("techNib", "#8ea7c2", 0.26);
    brush.spline(snowBot, 0.35);
  }
}

// ============================================================================
// 8.5 HYPERREAL FROZEN CHAIN, CHAINRING, HALF-CHAINCASE & NEAR PEDAL
// ============================================================================
function drawFrozenDrivetrain(BB, RWC) {
  const rChainring = 33;
  const rCog = 15;

  // --- 1. Exposed Lower Chain Run & Sprocket Teeth ---
  // Chainring lower half at BB (725, 875)
  brush.noStroke();
  brush.wash("#1c242e", 250);
  brush.circle(BB.x, BB.y, rChainring, 0.03);
  // Cutouts in steel chainring spider
  brush.wash("#dce7f2", 210);
  for (let a = 0; a < 360; a += 72) {
    let hx = BB.x + cos(a) * 19;
    let hy = BB.y + sin(a) * 19;
    brush.circle(hx, hy, 7.5, 0.05);
  }
  brush.noWash();

  // Chainring teeth around lower circumference
  brush.set("rotring", "#0b0e13", 0.45);
  brush.circle(BB.x, BB.y, rChainring, 0.03);
  for (let a = 0; a < 360; a += 10) {
    let tx1 = BB.x + cos(a) * rChainring;
    let ty1 = BB.y + sin(a) * rChainring;
    let tx2 = BB.x + cos(a) * (rChainring + 3.5);
    let ty2 = BB.y + sin(a) * (rChainring + 3.5);
    brush.line(tx1, ty1, tx2, ty2);
  }

  // Individual articulated chain links along lower run from (BB.x, BB.y + rChainring) to (RWC.x, RWC.y + rCog)
  const numLinks = 21;
  const x1 = BB.x + 2, y1 = BB.y + rChainring - 1;
  const x2 = RWC.x - 2, y2 = RWC.y + rCog - 1;

  for (let i = 0; i <= numLinks; i++) {
    let t = i / numLinks;
    let lx = lerp(x1, x2, t);
    // Realistic slight catenary sag of the chain
    let sag = 4.5 * sin(t * 180);
    let ly = lerp(y1, y2, t) + sag;

    // Link side plate (figure-8 capsule)
    brush.noStroke();
    brush.wash(i % 2 === 0 ? "#12171f" : "#2a3542", 250);
    drawShapePoly([
      [lx - 4, ly - 2.6], [lx + 4, ly - 2.6], [lx + 4, ly + 2.6], [lx - 4, ly + 2.6]
    ], 0.2);
    brush.noWash();

    // Link contour, roller & pin
    brush.set("rotring", "#07090d", 0.32);
    drawShapePoly([
      [lx - 4, ly - 2.6], [lx + 4, ly - 2.6], [lx + 4, ly + 2.6], [lx - 4, ly + 2.6]
    ], 0.2);
    brush.set("techNib", "#9cb2c9", 0.25);
    brush.line(lx - 3, ly - 2.2, lx + 3, ly - 2.2);
    brush.set("rotring", "#05070a", 0.45);
    brush.line(lx, ly - 0.5, lx + 0.5, ly + 0.5);

    // Hyperreal frozen slush, hoarfrost & tiny icicles hanging from the chain links!
    if (i % 2 === 0 || i === 5 || i === 12) {
      let iceLen = random(4, 10.5);
      brush.noStroke();
      brush.wash("#d8e8f6", 230);
      drawShapePoly([
        [lx - 2.2, ly + 2], [lx + 2.2, ly + 2], [lx + 0.4, ly + 2 + iceLen]
      ], 0.05);
      brush.wash("#ffffff", 250);
      drawShapePoly([
        [lx - 2.5, ly - 2.8], [lx + 2.5, ly - 2.8], [lx + 1, ly + 1.2], [lx - 1, ly + 1.2]
      ], 0.15);
      brush.noWash();

      brush.set("techNib", "#ffffff", 0.25);
      brush.line(lx, ly + 2, lx, ly + 2 + iceLen);
    }
  }

  // Packed frozen snow & ice crystals on the bottom of the chainring
  brush.noStroke();
  brush.wash("#e6f0fa", 235);
  drawShapePoly([
    [BB.x - 24, BB.y + 18], [BB.x, BB.y + 26], [BB.x + 22, BB.y + 20],
    [BB.x + 14, BB.y + 35], [BB.x - 12, BB.y + 34]
  ], 0.25);
  brush.noWash();

  // --- 2. Vintage Upper Half-Chaincase (Chain Guard) ---
  // Covers upper half of chainring and upper chain run from BB to RWC
  let cgPts = [];
  for (let a = 155; a <= 345; a += 12) {
    cgPts.push([BB.x + cos(a) * (rChainring + 7), BB.y + sin(a) * (rChainring + 7)]);
  }
  cgPts.push([RWC.x + 6, RWC.y - rCog - 6]);
  cgPts.push([RWC.x + 8, RWC.y + 2]);
  cgPts.push([BB.x + rChainring - 4, BB.y + 5]);
  cgPts.push([BB.x - rChainring + 4, BB.y + 8]);

  brush.noStroke();
  brush.wash("#0a0d12", 252);
  drawShapePoly(cgPts, 0.12);
  brush.noWash();

  // Crisp ink border, weathered gold pinstripe & chipped paint on chain guard
  brush.set("rotring", "#05070a", 0.42);
  drawShapePoly(cgPts, 0.12);

  // Worn vintage gold/ochre pinstripe along chain guard
  brush.set("techNib", "#c7a26b", 0.28);
  brush.line(BB.x - 6, BB.y - rChainring - 1, RWC.x - 8, RWC.y - rCog - 2);
  // Paint chips & rust specks on chain guard
  brush.set("techNib", "#9bb0c4", 0.3);
  brush.line(BB.x + 18, BB.y - 24, BB.x + 25, BB.y - 22);
  brush.line(BB.x + 68, BB.y - 18, BB.x + 76, BB.y - 17);
  brush.set("techNib", "#8a4226", 0.3);
  brush.line(BB.x + 20, BB.y - 23, BB.x + 23, BB.y - 21);

  // Settled snow ribbon along top ridge of the chain guard
  brush.noStroke();
  brush.wash("#ffffff", 250);
  drawShapePoly([
    [BB.x - 22, BB.y - rChainring - 6],
    [BB.x + 15, BB.y - rChainring - 11],
    [RWC.x - 10, RWC.y - rCog - 10],
    [RWC.x + 4, RWC.y - rCog - 5],
    [BB.x + 10, BB.y - rChainring - 5],
    [BB.x - 20, BB.y - rChainring - 3]
  ], 0.2);
  brush.noWash();

  // --- 3. Near Crank Arm & Pedal (with snow clump from rider's boot) ---
  // Chrome crank arm from BB (725, 875) down-left to (698, 936)
  drawFrameTube(BB.x, BB.y, 698, 936, 7.5, false, true);
  // Cotter pin & nut at BB
  brush.noStroke();
  brush.wash("#d8e4f0", 250);
  brush.circle(BB.x, BB.y, 6.5, 0.03);
  brush.noWash();
  brush.set("rotring", "#080b10", 0.38);
  brush.circle(BB.x, BB.y, 6.5, 0.03);

  // Near Pedal at (698, 936)
  brush.noStroke();
  brush.wash("#0d1117", 252);
  drawShapePoly([[676, 930], [718, 932], [716, 944], [674, 942]], 0.05);
  // Bright amber reflector strip on near pedal side
  brush.wash("#f58d3d", 245);
  drawShapePoly([[682, 935], [708, 936], [708, 940], [682, 939]], 0);
  // Clump of fresh snow left on top of the near pedal from the rider's boot!
  brush.wash("#ffffff", 252);
  drawShapePoly([[678, 930], [696, 922], [715, 931], [698, 933]], 0.25);
  brush.noWash();

  brush.set("rotring", "#06080b", 0.38);
  drawShapePoly([[676, 930], [718, 932], [716, 944], [674, 942]], 0.05);
}

// ============================================================================
// 8.6 BICYCLE FRAME TUBES (BLACK ENAMEL, CHIPPED PAINT & SETTLED SNOW)
// ============================================================================
function drawBicycleFrame(FWC, RWC, BB, ST, HTB, HTT) {
  // Far-side rear stays (drawn slightly offset and darker behind near stays)
  drawFrameTube(ST.x - 4, ST.y + 16, RWC.x - 4, RWC.y - 4, 6.0, false);
  drawFrameTube(BB.x - 4, BB.y - 3, RWC.x - 4, RWC.y - 3, 7.0, false);

  // Near-side Seatstay: from below seat cluster (765, 698) to rear dropout (885, 870)
  drawFrameTube(765, 698, RWC.x, RWC.y, 7.0, true);

  // Near-side Chainstay: from BB (725, 875) to rear dropout (885, 870)
  drawFrameTube(BB.x, BB.y, RWC.x, RWC.y, 8.5, false);

  // Down Tube: from head tube bottom (578, 710) to bottom bracket (725, 875)
  drawFrameTube(HTB.x, HTB.y, BB.x, BB.y, 12.5, true);

  // Seat Tube: from bottom bracket (725, 875) to seat lug (768, 682)
  drawFrameTube(BB.x, BB.y, ST.x, ST.y, 12.0, false);

  // Classic Double Top-Tube Roadster Geometry:
  // Secondary lower curved brace bar from (583, 688) to (756, 738)
  drawFrameTube(583, 688, 756, 738, 8.5, true);
