// 8.8 FRONT WIRE BASKET WITH SETTLED SNOW & DYNAMO HEADLAMP
// ============================================================================
function drawBasketWithSnowAndLamp(FWC, HTB, HTT) {
  // --- 1. Steel Basket Support Stay from Front Axle (535, 845) to Basket Bottom (505, 712) ---
  drawFrameTube(FWC.x, FWC.y, 505, 712, 5.5, false);
