  drawFrameTube(586, 656, 556, 632, 5.5, false);
  drawFrameTube(580, 696, 548, 696, 5.0, false);

  // --- 2. Bullet-Shaped Chrome Dynamo Headlamp (at 548, 728) & Bottle Dynamo (554, 776) ---
  // Bottle dynamo on front fork blade
  brush.noStroke();
  brush.wash("#4a5d70", 248);
  drawShapePoly([[548, 768], [558, 766], [561, 785], [551, 787]], 0.1);
  brush.wash("#ffffff", 245);
  drawShapePoly([[548, 768], [554, 764], [559, 767], [553, 769]], 0.2);
  // Headlamp body at (532..556, 718..736)
  brush.wash("#1b232e", 250);
  drawShapePoly([[532, 718], [552, 720], [556, 728], [552, 735], [532, 736]], 0.25);
  // Frosted glass headlamp lens catching the warm peach horizon glow
  brush.wash("#f7d6be", 240);
  drawShapePoly([[529, 719], [534, 718], [534, 736], [529, 735]], 0.2);
  // Snow cap on headlamp hood
  brush.wash("#ffffff", 250);
  drawShapePoly([[530, 718], [543, 712], [555, 719], [543, 720]], 0.25);
  brush.noWash();
  brush.set("rotring", "#080b10", 0.38);
  drawShapePoly([[532, 718], [552, 720], [556, 728], [552, 735], [532, 736]], 0.25);

  // --- 3. Front Wire Basket (X = 456..562, Y = 618..708) ---
  // Basket corners (3D trapezoidal wire basket)
  const bTL_front = [456, 624], bTR_front = [546, 628];
  const bTL_back  = [472, 616], bTR_back  = [562, 620];
  const bBL_front = [474, 706], bBR_front = [540, 708];
  const bBL_back  = [486, 698], bBR_back  = [552, 700];

  // Far-side wire mesh (drawn slightly lighter/thinner first)
  brush.set("rotring", "#2b3746", 0.26);
  for (let i = 0; i <= 7; i++) {
    let t = i / 7;
    // Back panel vertical wires
    brush.line(
      lerp(bTL_back[0], bTR_back[0], t), lerp(bTL_back[1], bTR_back[1], t),
      lerp(bBL_back[0], bBR_back[0], t), lerp(bBL_back[1], bBR_back[1], t)
    );
  }
  for (let j = 1; j <= 4; j++) {
    let t = j / 5;
    // Back panel horizontal wires
    brush.line(
      lerp(bTL_back[0], bBL_back[0], t), lerp(bTL_back[1], bBL_back[1], t),
      lerp(bTR_back[0], bBR_back[0], t), lerp(bTR_back[1], bBR_back[1], t)
    );
  }

  // --- 4. Thick Mound of Fresh Snow Settled Inside the Bottom of the Basket! ---
  // Drawn between the back mesh and front mesh so the front wires pass crisply in front of the snow!
  brush.noStroke();
  brush.wash("#8ea7c2", 240);
  drawShapePoly([
    [473, 692], [512, 684], [551, 692], [540, 708], [474, 706]
  ], 0.2);
  brush.wash("#ffffff", 255);
  drawShapePoly([
    [471, 692], [492, 676], [522, 675], [549, 686],
    [544, 699], [508, 701], [474, 699]
  ], 0.3);
  brush.noWash();
  brush.set("techNib", "#728ca8", 0.28);
  brush.spline([[474, 699], [508, 701], [544, 699]], 0.3);

  // Near-side and left-end wire mesh of the basket (crisp dark wire grid)
  brush.set("rotring", "#0d1218", 0.36);
  // Vertical wires on near face
  for (let i = 0; i <= 8; i++) {
    let t = i / 8;
    let vx1 = lerp(bTL_front[0], bTR_front[0], t);
    let vy1 = lerp(bTL_front[1], bTR_front[1], t);
    let vx2 = lerp(bBL_front[0], bBR_front[0], t);
    let vy2 = lerp(bBL_front[1], bBR_front[1], t);
    brush.line(vx1, vy1, vx2, vy2);
    // Cold sky glint on wire
    if (i % 2 === 0) {
      brush.set("techNib", "#8ea5bd", 0.2);
      brush.line(vx1 + 0.6, vy1 + 10, vx2 + 0.6, vy2 - 10);
      brush.set("rotring", "#0d1218", 0.36);
    }
  }
  // Vertical wires on left & right end faces
  for (let i = 1; i <= 3; i++) {
    let t = i / 4;
    brush.line(
      lerp(bTL_back[0], bTL_front[0], t), lerp(bTL_back[1], bTL_front[1], t),
      lerp(bBL_back[0], bBL_front[0], t), lerp(bBL_back[1], bBL_front[1], t)
    );
    brush.line(
      lerp(bTR_back[0], bTR_front[0], t), lerp(bTR_back[1], bTR_front[1], t),
      lerp(bBR_back[0], bBR_front[0], t), lerp(bBR_back[1], bBR_front[1], t)
    );
  }
  // Horizontal rib wires around the basket
  for (let j = 1; j <= 5; j++) {
    let t = j / 5;
    let lxF = lerp(bTL_front[0], bBL_front[0], t);
    let lyF = lerp(bTL_front[1], bBL_front[1], t);
    let rxF = lerp(bTR_front[0], bBR_front[0], t);
    let ryF = lerp(bTR_front[1], bBR_front[1], t);
    let lxB = lerp(bTL_back[0], bBL_back[0], t);
    let lyB = lerp(bTL_back[1], bBL_back[1], t);
    let rxB = lerp(bTR_back[0], bBR_back[0], t);
    let ryB = lerp(bTR_back[1], bBR_back[1], t);

    brush.set("rotring", "#0d1218", j === 5 ? 0.55 : 0.36);
    brush.line(lxB, lyB, lxF, lyF);
    brush.line(lxF, lyF, rxF, ryF);
    brush.line(rxF, ryF, rxB, ryB);

    // Tiny snow flecks caught on wire intersections
    if (j === 2 || j === 3) {
      brush.set("cpencil", "#ffffff", 0.55);
      for (let k = 0.2; k <= 0.8; k += 0.3) {
        let sx = lerp(lxF, rxF, k);
        let sy = lerp(lyF, ryF, k);
        brush.line(sx - 2, sy - 1, sx + 2, sy - 1);
      }
    }
  }

  // --- 5. Fluffy Rim of Fresh White Snow Settled Around the Entire Upper Lip of the Basket! ---
  // Back & right rim snow
  brush.noStroke();
  brush.wash("#dce8f4", 245);
  drawShapePoly([
    [468, 616], [515, 608], [565, 614], [563, 623], [515, 619], [470, 621]
  ], 0.25);
  // Front & left rim snow (plump white pillow)
  brush.wash("#8ea7c2", 240);
  drawShapePoly([
    [452, 625], [472, 616], [548, 627], [564, 620],
    [548, 633], [498, 632], [454, 630]
  ], 0.2);
  brush.wash("#ffffff", 255);
  drawShapePoly([
    [451, 623], [468, 610], [498, 615], [528, 616], [552, 619], [565, 614],
    [548, 629], [502, 628], [454, 627]
  ], 0.3);
  brush.noWash();

  brush.set("techNib", "#6b85a1", 0.28);
  brush.spline([[454, 628], [502, 630], [548, 631], [563, 622]], 0.3);
}

