function evalRawField(x, y) {
  // Subtle domain warping for organic fluid and radar reflectivity contours
  let wx = x + (noise(x * 0.004, y * 0.004, 1.2) - 0.5) * 34;
  let wy = y + (noise(x * 0.004, y * 0.004, 5.7) - 0.5) * 34;

  let sum = 0;

  for (let i = 0; i < capsules.length; i++) {
    let c = capsules[i];
    let vx = c.bx - c.ax;
    let vy = c.by - c.ay;
    let l2 = vx * vx + vy * vy;
    let t = constrain(((wx - c.ax) * vx + (wy - c.ay) * vy) / l2, 0, 1);
    let px = c.ax + t * vx;
    let py = c.ay + t * vy;
    let d2 = (wx - px) * (wx - px) + (wy - py) * (wy - py);
    let r2 = c.r * c.r;
    if (d2 < r2 * 3.2) {
      sum += c.w * Math.exp(-d2 / r2);
    }
  }

  for (let i = 0; i < metaballs.length; i++) {
    let m = metaballs[i];
    let d2 = (wx - m.x) * (wx - m.x) + (wy - m.y) * (wy - m.y);
    let r2 = m.r * m.r;
    if (d2 < r2 * 3.5) {
      sum += m.w * Math.exp(-d2 / r2);
    }
  }

  // Fine radar-edge scalloping where liquid is present
  if (sum > 0.35) {
    let n1 = noise(x * 0.011, y * 0.011, 9.1) - 0.5;
    let n2 = noise(x * 0.026, y * 0.026, 3.4) - 0.5;
    sum += (n1 * 0.14 + n2 * 0.05) * constrain(sum, 0, 1.5);
  }

  return sum;
}

function sampleField(x, y) {
  let gx = constrain(x / GRID_STEP, 0, GRID_N - 1.001);
  let gy = constrain(y / GRID_STEP, 0, GRID_N - 1.001);
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  let fx = gx - ix;
  let fy = gy - iy;
  let v00 = gridF[ix][iy];
  let v10 = gridF[ix + 1][iy];
  let v01 = gridF[ix][iy + 1];
  let v11 = gridF[ix + 1][iy + 1];
  return (v00 * (1 - fx) + v10 * fx) * (1 - fy) + (v01 * (1 - fx) + v11 * fx) * fy;
}

function sampleGrad(x, y) {
  let ix = constrain(Math.round(x / GRID_STEP), 1, GRID_N - 1);
  let iy = constrain(Math.round(y / GRID_STEP), 1, GRID_N - 1);
  return { gx: gradX[ix][iy], gy: gradY[ix][iy] };
}

// Marching Squares contour extractor returning closed, smoothed polygon loops
function extractContours(threshold, smoothPasses = 2) {
  let segments = [];
  let edgeMap = new Map();

  function edgePoint(ix, iy, edge) {
    let x0, y0, x1, y1, v0, v1, key;
    if (edge === 0) {
      x0 = ix; y0 = iy; x1 = ix + 1; y1 = iy;
      v0 = gridF[ix][iy]; v1 = gridF[ix + 1][iy];
      key = `H_${ix}_${iy}`;
    } else if (edge === 1) {
      x0 = ix + 1; y0 = iy; x1 = ix + 1; y1 = iy + 1;
      v0 = gridF[ix + 1][iy]; v1 = gridF[ix + 1][iy + 1];
      key = `V_${ix + 1}_${iy}`;
    } else if (edge === 2) {
      x0 = ix; y0 = iy + 1; x1 = ix + 1; y1 = iy + 1;
      v0 = gridF[ix][iy + 1]; v1 = gridF[ix + 1][iy + 1];
      key = `H_${ix}_${iy + 1}`;
    } else {
      x0 = ix; y0 = iy; x1 = ix; y1 = iy + 1;
      v0 = gridF[ix][iy]; v1 = gridF[ix][iy + 1];
      key = `V_${ix}_${iy}`;
    }
    let denom = v1 - v0;
    let t = Math.abs(denom) < 1e-6 ? 0.5 : constrain((threshold - v0) / denom, 0.001, 0.999);
    return {
      x: (x0 + t * (x1 - x0)) * GRID_STEP,
      y: (y0 + t * (y1 - y0)) * GRID_STEP,
      key: key
    };
  }

  for (let ix = 0; ix < GRID_N; ix++) {
    for (let iy = 0; iy < GRID_N; iy++) {
      let b0 = gridF[ix][iy] >= threshold ? 1 : 0;
      let b1 = gridF[ix + 1][iy] >= threshold ? 2 : 0;
      let b2 = gridF[ix + 1][iy + 1] >= threshold ? 4 : 0;
      let b3 = gridF[ix][iy + 1] >= threshold ? 8 : 0;
      let code = b0 | b1 | b2 | b3;
      if (code === 0 || code === 15) continue;

      let pairs = [];
      switch (code) {
        case 1:  pairs.push([3, 0]); break;
        case 2:  pairs.push([0, 1]); break;
        case 3:  pairs.push([3, 1]); break;
        case 4:  pairs.push([1, 2]); break;
        case 5:  pairs.push([3, 2], [1, 0]); break;
        case 6:  pairs.push([0, 2]); break;
        case 7:  pairs.push([3, 2]); break;
        case 8:  pairs.push([2, 3]); break;
        case 9:  pairs.push([2, 0]); break;
        case 10: pairs.push([0, 3], [2, 1]); break;
        case 11: pairs.push([2, 1]); break;
        case 12: pairs.push([1, 3]); break;
        case 13: pairs.push([1, 0]); break;
        case 14: pairs.push([0, 3]); break;
      }

      for (let p of pairs) {
        let pA = edgePoint(ix, iy, p[0]);
        let pB = edgePoint(ix, iy, p[1]);
        let seg = { a: pA, b: pB, used: false };
        segments.push(seg);
        if (!edgeMap.has(pA.key)) edgeMap.set(pA.key, []);
        edgeMap.get(pA.key).push(seg);
      }
    }
  }

  // Stitch segments into closed loops
  let loops = [];
  for (let seg of segments) {
    if (seg.used) continue;
    seg.used = true;
    let pts = [[seg.a.x, seg.a.y], [seg.b.x, seg.b.y]];
    let currKey = seg.b.key;
    let guard = 0;
    while (guard++ < 4000) {
      let candidates = edgeMap.get(currKey);
      if (!candidates) break;
      let nextSeg = null;
      for (let c of candidates) {
        if (!c.used) { nextSeg = c; break; }
      }
      if (!nextSeg) break;
      nextSeg.used = true;
      pts.push([nextSeg.b.x, nextSeg.b.y]);
      currKey = nextSeg.b.key;
      if (currKey === seg.a.key) break;
    }
    if (pts.length >= 6) {
      loops.push(smoothLoop(pts, smoothPasses));
    }
  }
  return loops;
}

function smoothLoop(pts, passes) {
  let curr = pts;
  for (let p = 0; p < passes; p++) {
    let next = [];
    let n = curr.length;
    for (let i = 0; i < n; i++) {
      let prev = curr[(i - 1 + n) % n];
      let me = curr[i];
      let nxt = curr[(i + 1) % n];
      next.push([
        0.25 * prev[0] + 0.5 * me[0] + 0.25 * nxt[0],
        0.25 * prev[1] + 0.5 * me[1] + 0.25 * nxt[1]
      ]);
    }
    curr = next;
  }
  return curr;
}

function decimateLoop(pts, stride = 3) {
  let out = [];
  for (let i = 0; i < pts.length; i += stride) {
    out.push([pts[i][0], pts[i][1]]);
  }
  return out;
}

function safeSpline(pts, curvature = 0.4) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 7.5) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

// ============================================================================
// LAYER 1: SPECKLED BLACK GRANITE COUNTERTOP (PHOTOGRAPHIC & COOL)
// ============================================================================

function drawGraniteCountertop() {
  brush.noField();
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base cool obsidian-slate ground wash
  brush.wash("#0d1016", 240);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Subtle mineral mottling across the stone slab
  let slabTones = [
    { col: "#141922", op: 45, count: 14 },
    { col: "#07090d", op: 55, count: 16 },
    { col: "#1c2432", op: 32, count: 12 }
  ];
  for (let st of slabTones) {
    for (let i = 0; i < st.count; i++) {
      let cx = random(40, 1160);
      let cy = random(40, 1160);
      let rx = random(90, 240);
      let ry = random(70, 210);
      let pts = [];
      let nVerts = 9;
      let rot = random(360);
      for (let k = 0; k < nVerts; k++) {
        let a = rot + (k * 360) / nVerts;
        let rMod = random(0.75, 1.25);
        pts.push([cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod]);
      }
      let poly = new brush.Polygon(pts);
      poly.wash(st.col, st.op);
    }
  }

  // Photographic cool granite crystal patches (quartz, plagioclase, biotite, hornblende)
  let crystalBatches = [
    { col: "#050609", op: 195, count: 95, rMin: 4, rMax: 13 },
    { col: "#1f2735", op: 170, count: 95, rMin: 5, rMax: 15 },
    { col: "#364457", op: 160, count: 90, rMin: 4, rMax: 12 },
    { col: "#53657d", op: 150, count: 80, rMin: 3.5, rMax: 10 },
    { col: "#788da6", op: 145, count: 70, rMin: 3, rMax: 8.5 },
    { col: "#a4b8cf", op: 150, count: 55, rMin: 2.5, rMax: 7 },
    { col: "#c7d3e8", op: 140, count: 40, rMin: 2, rMax: 5.5 }
  ];

  for (let batch of crystalBatches) {
    for (let i = 0; i < batch.count; i++) {
      let cx = random(10, 1190);
      let cy = random(10, 1190);
      if (sampleField(cx, cy) > 1.75) continue;

      let sides = Math.floor(random(4, 7));
      let baseR = random(batch.rMin, batch.rMax);
      let rot = random(360);
      let stretch = random(0.55, 1.45);
      let pts = [];
      for (let s = 0; s < sides; s++) {
        let a = rot + (s * 360) / sides + random(-18, 18);
        let rad = baseR * random(0.65, 1.25);
        pts.push([
          cx + cos(a) * rad * stretch,
          cy + sin(a) * rad / stretch
        ]);
      }
      let poly = new brush.Polygon(pts);
      poly.wash(batch.col, batch.op);
    }
  }

  // Fine photographic mineral stipple and cleavage micro-flecks
  let sprayPalette = [
    { col: "#040507", w: 1.3, n: 120 },
    { col: "#2a3546", w: 1.1, n: 120 },
    { col: "#4a5c73", w: 0.9, n: 110 },
    { col: "#7f94ad", w: 0.75, n: 95 },
    { col: "#b6c8de", w: 0.6, n: 75 }
  ];

  for (let sp of sprayPalette) {
    brush.set("fineMist", sp.col, sp.w);
    for (let i = 0; i < sp.n; i++) {
      let x = random(15, 1185);
      let y = random(15, 1185);
      if (sampleField(x, y) > 1.65) continue;
      let len = random(14, 42);
      let ang = random(360);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }

  // Crisp micro-crystalline flecks with rotring & cpencil for photographic sharpness
  let fleckColors = ["#06080c", "#3e4d63", "#697e99", "#9cb2cc", "#dce7f5"];
  for (let fc of fleckColors) {
    brush.set("cpencil", fc, 0.75);
    for (let i = 0; i < 220; i++) {
      let x = random(8, 1192);
      let y = random(8, 1192);
      if (sampleField(x, y) > 1.55) continue;
      let l = random(2.5, 6.5);
      let a = random(360);
      brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
    }
  }

  // Faint overhead studio light reflection across the polished stone
  let sheenPoly = new brush.Polygon([
    [0, 0], [820, 0], [1200, 380], [1200, 760], [380, 1200], [0, 1200]
  ]);
  sheenPoly.wash("#64748b", 12);
}

// ============================================================================
// LAYER 2: GLASS UNDERLAY (SHADOW & CAUSTICS ON GRANITE) + SPILL UNDERTONE
// ============================================================================

function getGlassFrame() {
  let dx = GLASS.bx - GLASS.mx;
  let dy = GLASS.by - GLASS.my;
  let len = Math.hypot(dx, dy);
  let ux = dx / len;
  let uy = dy / len;
  let vx = -uy; // points down-right
  let vy = ux;
  return { ux, uy, vx, vy, len };
}

function glassEllipsePoints(t, rScale = 1.0, nPts = 48, shiftX = 0, shiftY = 0) {
  let gf = getGlassFrame();
  let cx = lerp(GLASS.mx, GLASS.bx, t) + shiftX;
  let cy = lerp(GLASS.my, GLASS.by, t) + shiftY;
  let rMaj = lerp(GLASS.rm, GLASS.rb, t) * rScale;
  let rMin = rMaj * GLASS.aspect;
  let pts = [];
  for (let i = 0; i < nPts; i++) {
    let a = (i * 360) / nPts;
    let ca = cos(a);
    let sa = sin(a);
    pts.push([
      cx + gf.ux * (ca * rMin) + gf.vx * (sa * rMaj),
      cy + gf.uy * (ca * rMin) + gf.vy * (sa * rMaj)
    ]);
  }
  return pts;
}

function drawGlassUnderlay() {
  let gf = getGlassFrame();

  // Cast shadow of the glass cylinder on the granite (shifted down-right along +v)
  let shadowPts = [];
  let mPts = glassEllipsePoints(0.02, 1.02, 36, gf.vx * 18 + 8, gf.vy * 18 + 12);
  let bPts = glassEllipsePoints(1.02, 1.05, 36, gf.vx * 22 + 10, gf.vy * 22 + 14);
  for (let i = 18; i <= 35; i++) shadowPts.push(mPts[i]);
  for (let i = 0; i <= 18; i++) shadowPts.push(bPts[i]);
  let shPoly = new brush.Polygon(shadowPts);
  shPoly.wash("#040609", 165);

  // Refracted pastel caustics cast through the heavy glass base onto the black stone
  let causticColors = [
    { t: 1.08, r: 0.92, col: "#38bdf8", op: 36, sx: 26, sy: 22 },
    { t: 1.12, r: 0.78, col: "#6ee7b7", op: 42, sx: 34, sy: 28 },
    { t: 1.15, r: 0.62, col: "#fef08a", op: 45, sx: 42, sy: 34 },
    { t: 1.04, r: 0.85, col: "#f9a8d4", op: 30, sx: 18, sy: 16 }
  ];
  for (let cc of causticColors) {
    let cPts = glassEllipsePoints(cc.t, cc.r, 36, cc.sx, cc.sy);
    let poly = new brush.Polygon(cPts);
    poly.wash(cc.col, cc.op);
  }

  // Crisp caustic light filaments on the stone near the base
  brush.set("glossMarker", "#bae6fd", 0.65);
  let arc1 = glassEllipsePoints(1.11, 0.74, 40, 32, 26).slice(4, 17);
  safeSpline(arc1, 0.4);
  brush.set("microPen", "#fef9c3", 0.85);
  let arc2 = glassEllipsePoints(1.14, 0.58, 40, 38, 31).slice(5, 16);
  safeSpline(arc2, 0.4);
}

function drawSpillUndertone() {
  // 1. Outer meniscus cast shadow on the granite (shifted slightly down-right)
  let outerLoops = extractContours(0.96, 2);
  for (let loop of outerLoops) {
    let dec = decimateLoop(loop, 2);
    let shifted1 = dec.map(p => [p[0] + 4.5, p[1] + 5.5]);
    let shifted2 = dec.map(p => [p[0] + 2.0, p[1] + 2.5]);
    new brush.Polygon(shifted1).wash("#030407", 150);
    new brush.Polygon(shifted2).wash("#020305", 195);
  }

  // 2. Dark cola-obsidian base body at F = 1.00 so the liquid has deep physical mass
  let edgeLoops = extractContours(1.00, 2);
  for (let loop of edgeLoops) {
    let dec = decimateLoop(loop, 2);
    new brush.Polygon(dec).wash("#0c1412", 230);
  }

  // 3. Faint refracted stone flecks inside the thin outer meniscus (1.01 < F < 1.52)
  let refractedColors = ["#1c3830", "#2d594b", "#48826e", "#76b59f"];
  for (let rc of refractedColors) {
    brush.set("cpencil", rc, 0.7);
    for (let i = 0; i < 140; i++) {
      let x = random(90, 960);
      let y = random(280, 1080);
      let f = sampleField(x, y);
      if (f > 1.02 && f < 1.52) {
        let l = random(2.5, 5.5);
        let a = random(360);
        brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
      }
    }
  }
}

// ============================================================================
// LAYER 3: PRECIPITATION-RADAR BANDING & CONCENTRIC SPRAY-MIST ZONES
// ============================================================================

function getRadarColor(f) {
  const stops = [
    { t: 1.00, r: 22,  g: 78,  b: 63  }, // Dark meniscus emerald rim
    { t: 1.08, r: 52,  g: 211, b: 153 }, // Radar emerald-mint
    { t: 1.24, r: 110, g: 231, b: 183 }, // Soft pastel radar green
    { t: 1.42, r: 167, g: 243, b: 208 }, // Luminous pastel seafoam-mint
    { t: 1.56, r: 190, g: 242, b: 100 }, // Pastel chartreuse-lime
    { t: 1.72, r: 254, g: 240, b: 138 }, // Soft pastel radar yellow
    { t: 1.90, r: 253, g: 224, b: 71  }, // Warm butter-gold yellow
    { t: 2.08, r: 253, g: 186, b: 116 }, // Soft pastel apricot-orange
    { t: 2.26, r: 251, g: 146, b: 60  }, // Radar tangerine-orange
    { t: 2.44, r: 252, g: 165, b: 165 }, // Pastel coral-salmon
    { t: 2.62, r: 251, g: 113, b: 133 }, // Soft rose-crimson
    { t: 2.82, r: 225, g: 29,  b: 72  }, // Vivid radar crimson
    { t: 3.08, r: 159, g: 18,  b: 57  }, // Dense carmine-crimson core
    { t: 3.38, r: 88,  g: 10,  b: 31  }  // Deepest cola-crimson abyss
  ];

  if (f <= stops[0].t) return rgbToHex(stops[0].r, stops[0].g, stops[0].b);
  for (let i = 0; i < stops.length - 1; i++) {
    let s0 = stops[i];
    let s1 = stops[i + 1];
    if (f <= s1.t) {
      let u = (f - s0.t) / (s1.t - s0.t);
      return rgbToHex(
        Math.round(lerp(s0.r, s1.r, u)),
        Math.round(lerp(s0.g, s1.g, u)),
        Math.round(lerp(s0.b, s1.b, u))
      );
    }
  }
  let last = stops[stops.length - 1];
  return rgbToHex(last.r, last.g, last.b);
}

function rgbToHex(r, g, b) {
  return "#" + [r, g, b].map(x => constrain(x, 0, 255).toString(16).padStart(2, "0")).join("");
}

function drawRadarBanding() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Concentric Radar Zone Washes following the exact meniscus iso-contours
  let washLevels = [
    { t: 1.02, op: 115 },
    { t: 1.07, op: 125 },
    { t: 1.14, op: 130 },
    { t: 1.22, op: 130 },
    { t: 1.32, op: 125 },
    { t: 1.42, op: 125 },
    { t: 1.52, op: 135 },
    { t: 1.63, op: 140 },
    { t: 1.74, op: 145 },
    { t: 1.86, op: 145 },
    { t: 1.98, op: 150 },
    { t: 2.11, op: 150 },
    { t: 2.24, op: 155 },
    { t: 2.38, op: 160 },
    { t: 2.52, op: 165 },
    { t: 2.66, op: 175 },
    { t: 2.80, op: 185 },
    { t: 2.95, op: 195 },
    { t: 3.10, op: 205 },
    { t: 3.26, op: 215 }
  ];

  for (let wl of washLevels) {
    let col = getRadarColor(wl.t);
    let loops = extractContours(wl.t, 2);
    for (let loop of loops) {
      let dec = decimateLoop(loop, 2);
      if (dec.length >= 5) {
        new brush.Polygon(dec).wash(col, wl.op);
      }
    }
  }

  // Selective watercolor bleed passes on key zone transitions for organic pigment fusion
  let bleedLevels = [
    { t: 1.18, col: "#6ee7b7", op: 55, bleed: 0.14 },
    { t: 1.68, col: "#fef08a", op: 50, bleed: 0.12 },
    { t: 2.18, col: "#fdba74", op: 55, bleed: 0.12 },
    { t: 2.65, col: "#f43f5e", op: 65, bleed: 0.15 },
    { t: 3.05, col: "#881337", op: 75, bleed: 0.16 }
  ];
  for (let bl of bleedLevels) {
    let loops = extractContours(bl.t, 2);
    for (let loop of loops) {
      let dec = decimateLoop(loop, 4);
      if (dec.length >= 5) {
        new brush.Polygon(dec).fill(bl.col, bl.op, bl.bleed, 0.25);
      }
    }
  }
  brush.noFill();
  brush.noWash();

  // 2. Concentric Spray-Mist Zones along dense intermediate meniscus contours
  for (let t = 1.03; t <= 3.32; t += 0.042) {
    let col = getRadarColor(t + 0.03);
    let loops = extractContours(t, 2);
    let useFine = (Math.round(t * 100) % 2 === 0);
    brush.set(useFine ? "fineMist" : "radarMist", col, useFine ? 1.05 : 1.15);

    for (let loop of loops) {
      let dec = decimateLoop(loop, 3);
      if (dec.length >= 4) {
        dec.push(dec[0]);
        safeSpline(dec, 0.35);
      }
    }
  }

  // 3. Delicate Radar Iso-dBZ Contour Rings & Meniscus Topographic Lines
  let isoRings = [
    { t: 1.09, col: "#a7f3d0", w: 0.65 },
    { t: 1.28, col: "#d1fae5", w: 0.60 },
    { t: 1.50, col: "#ecfccb", w: 0.65 },
    { t: 1.72, col: "#fef9c3", w: 0.70 },
    { t: 1.98, col: "#ffedd5", w: 0.65 },
    { t: 2.25, col: "#fee2e2", w: 0.65 },
    { t: 2.54, col: "#fecdd3", w: 0.75 },
    { t: 2.84, col: "#fda4af", w: 0.70 },
    { t: 3.14, col: "#f43f5e", w: 0.65 }
  ];

  for (let ir of isoRings) {
    brush.set("cpencil", ir.col, ir.w);
    let loops = extractContours(ir.t, 2);
    for (let loop of loops) {
      let dec = decimateLoop(loop, 2);
      if (dec.length >= 4) {
        dec.push(dec[0]);
        safeSpline(dec, 0.35);
      }
    }
  }

  // 4. Syrupy internal flow currents streaming from the glass mouth into the crimson pool
  let streamCount = 28;
  for (let s = 0; s < streamCount; s++) {
    let spread = map(s, 0, streamCount - 1, -0.65, 0.65);
    let x = 775 + spread * 42;
    let y = 372 + spread * 36;
    let pts = [[x, y]];
    for (let step = 0; step < 26; step++) {
      let dx = 485 - x;
      let dy = 635 - y;
      let d = Math.hypot(dx, dy);
      if (d < 25) break;
      let ang = atan2(dy, dx) + (noise(x * 0.008, y * 0.008, s * 0.3) - 0.5) * 65;
      x += cos(ang) * 14;
      y += sin(ang) * 14;
      if (sampleField(x, y) < 1.15) break;
      pts.push([x, y]);
    }
    if (pts.length >= 4) {
      let midPt = pts[Math.floor(pts.length / 2)];
      let fVal = sampleField(midPt[0], midPt[1]);
      let col = getRadarColor(fVal + (s % 2 === 0 ? 0.22 : -0.18));
      brush.set("cpencil", col, 0.55);
      safeSpline(pts, 0.45);
    }
  }
}

// ============================================================================
// LAYER 4: TRUE MENISCUS 3D SPECULAR REFLECTIONS & STUDIO SOFTBOX GLARE
// ============================================================================

function drawMeniscusReflections() {
  // 1. Broad overhead diffused softbox window reflection warped across the pool surface
  let glarePoly1 = new brush.Polygon([
    [355, 515], [565, 445], [645, 535], [445, 635]
  ]);
  glarePoly1.wash("#e0f2fe", 20);

  let glarePoly2 = new brush.Polygon([
    [385, 675], [595, 595], [655, 675], [455, 765]
  ]);
  glarePoly2.wash("#fce7f3", 18);

  // 2. Dark surface-tension inner rim at F = 1.015 to anchor the 3D meniscus curve
  let rimLoops = extractContours(1.012, 2);
  brush.set("cpencil", "#071712", 1.15);
  for (let loop of rimLoops) {
    let dec = decimateLoop(loop, 2);
    if (dec.length >= 4) {
      dec.push(dec[0]);
      safeSpline(dec, 0.35);
    }
  }

  // 3. True normal-mapped meniscus specular highlights along the curved liquid edge
  const L1x = -0.60, L1y = -0.80;
  const L2x = 0.68,  L2y = 0.73;

  let meniscusLevels = [
    { t: 1.045, thresh: 0.32, bName: "glossMarker", col: "#a7f3d0", w: 1.45 },
    { t: 1.065, thresh: 0.42, bName: "glossMarker", col: "#ecfdf5", w: 1.25 },
    { t: 1.080, thresh: 0.54, bName: "glossMarker", col: "#ffffff", w: 0.95 },
    { t: 1.095, thresh: 0.64, bName: "microPen",    col: "#ffffff", w: 1.15 },
    { t: 1.145, thresh: 0.58, bName: "glossMarker", col: "#d1fae5", w: 0.80 },
    { t: 1.155, thresh: 0.68, bName: "microPen",    col: "#ffffff", w: 0.95 },
    { t: 1.540, thresh: 0.74, bName: "glossMarker", col: "#fef9c3", w: 0.75 },
    { t: 2.120, thresh: 0.76, bName: "glossMarker", col: "#ffedd5", w: 0.75 },
    { t: 2.680, thresh: 0.76, bName: "glossMarker", col: "#ffe4e6", w: 0.75 }
  ];

  for (let ml of meniscusLevels) {
    let loops = extractContours(ml.t, 2);
    brush.set(ml.bName, ml.col, ml.w);

    for (let loop of loops) {
      let currentArc = [];
      let n = loop.length;
      for (let i = 0; i <= n; i++) {
        let pt = loop[i % n];
        let g = sampleGrad(pt[0], pt[1]);
        let mag = Math.hypot(g.gx, g.gy);
        if (mag < 1e-5) continue;
        let nx = -g.gx / mag;
        let ny = -g.gy / mag;
        let dot1 = Math.max(0, nx * L1x + ny * L1y);
        let dot2 = Math.max(0, nx * L2x + ny * L2y) * 0.82;
        let spec = Math.max(dot1, dot2);

        if (spec >= ml.thresh) {
          let pressure = map(spec, ml.thresh, 1.0, 0.35, 1.45, true);
          currentArc.push([pt[0], pt[1], pressure]);
        } else {
          if (currentArc.length >= 3) {
            safeSpline(currentArc, 0.35);
          }
          currentArc = [];
        }
      }
      if (currentArc.length >= 3) {
        safeSpline(currentArc, 0.35);
      }
    }
  }
}

// ============================================================================
// LAYER 5: HYPERREAL CARBONATION BUBBLES (PEN & WHITE MARKER SPHERES)
// ============================================================================

function drawCarbonationBubbles() {
  let bubbles = [];

  function tryAddBubble(x, y, r, fVal) {
    for (let i = 0; i < bubbles.length; i++) {
      let b = bubbles[i];
      let dx = x - b.x;
      let dy = y - b.y;
      let minD = (r + b.r) * 0.92;
      if (dx * dx + dy * dy < minD * minD) return false;
    }
    bubbles.push({ x, y, r, f: fVal });
    return true;
  }

  // 1. Place hero & medium bubbles along the leading edge meniscus contours (F = 1.04 to 1.32)
  let bubbleContourLevels = [1.055, 1.085, 1.12, 1.16, 1.21, 1.27];
  for (let lvl of bubbleContourLevels) {
    let loops = extractContours(lvl, 2);
    for (let loop of loops) {
      for (let i = 0; i < loop.length; i++) {
        let pt = loop[i];
        let x = pt[0] + random(-3.5, 3.5);
        let y = pt[1] + random(-3.5, 3.5);
        let f = sampleField(x, y);
        if (f < 1.025 || f > 1.38) continue;

        let clusterNoise = noise(x * 0.015, y * 0.015, 7.7);
        if (clusterNoise < 0.41 && random() < 0.78) continue;

        let r;
        let roll = random();
        if (roll < 0.07 && f > 1.07) {
          r = random(7.5, 12.5);
        } else if (roll < 0.32) {
          r = random(4.0, 7.4);
        } else {
          r = random(1.6, 3.9);
        }
        tryAddBubble(x, y, r, f);
      }
    }
  }

  // 2. Agitated pouring-stream foam plume from glass mouth (755, 385) into the pool (530, 590)
  for (let i = 0; i < 360; i++) {
    let u = Math.pow(random(), 1.35);
    let cx = lerp(765, 515, u);
    let cy = lerp(385, 605, u);
    let spread = lerp(24, 95, u);
    let a = random(360);
    let rad = randomGaussian(0, spread * 0.45);
    let x = cx + cos(a) * rad;
    let y = cy + sin(a) * rad;
    let f = sampleField(x, y);
    if (f < 1.05) continue;

    let r = random() < 0.12 ? random(6.5, 11.5) : (random() < 0.45 ? random(3.2, 6.2) : random(1.5, 3.1));
    tryAddBubble(x, y, r, f);
  }

  // 3. Dense micro-bubble collar satellites around existing larger bubbles
  let baseCount = bubbles.length;
  for (let i = 0; i < baseCount; i++) {
    let parent = bubbles[i];
    if (parent.r < 3.8) continue;
    let nSat = Math.floor(random(3, 8));
    for (let k = 0; k < nSat; k++) {
      let ang = random(360);
      let sr = random(1.4, 3.2);
      let dist = parent.r + sr + random(0.2, 1.8);
      let sx = parent.x + cos(ang) * dist;
      let sy = parent.y + sin(ang) * dist;
      let sf = sampleField(sx, sy);
      if (sf >= 1.02) {
        tryAddBubble(sx, sy, sr, sf);
      }
    }
  }

  // Sort bubbles large-to-small so smaller collar bubbles sit crisply around large domes
  bubbles.sort((a, b) => b.r - a.r);

  // Capture exact frame-0 bubbles without touching random/noise state
  if (frameCount === 1) {
    initialBubbles = bubbles.map((b, idx) => ({
      x: b.x, y: b.y, r: b.r, f: b.f, seed: 70000 + idx * 17
    }));
  }

  // PASS A: Dark spherical shadow base & translucent dome interior for r >= 3.0
  brush.noStroke();
  for (let b of bubbles) {
    if (b.r < 3.0) continue;
    let nPts = 14;
    let shPts = [];
    let domPts = [];
    for (let k = 0; k < nPts; k++) {
      let a = (k * 360) / nPts;
      shPts.push([
        b.x + b.r * 0.22 + cos(a) * b.r * 1.05,
        b.y + b.r * 0.25 + sin(a) * b.r * 1.05
      ]);
      domPts.push([
        b.x + cos(a) * b.r * 0.92,
        b.y + sin(a) * b.r * 0.92
      ]);
    }
    new brush.Polygon(shPts).wash("#081210", 175);
    new brush.Polygon(domPts).wash("#132620", 125);
  }

  // PASS B: Subsurface radar-colored bounce refraction in the lower-right crescent of larger spheres
  for (let b of bubbles) {
    if (b.r < 3.6) continue;
    let col = getRadarColor(b.f + 0.25);
    brush.set("glossMarker", col, constrain(b.r * 0.09, 0.35, 0.95));
    let refPts = [];
    for (let a = -15; a <= 105; a += 30) {
      refPts.push([
        b.x + cos(a) * b.r * 0.68,
        b.y + sin(a) * b.r * 0.68
      ]);
    }
    safeSpline(refPts, 0.4);
  }

  // PASS C: Crisp pen outer contour rings & shared foam cell walls
  brush.set("microPen", "#06110e", 0.95);
  for (let b of bubbles) {
    if (b.r >= 2.6) {
      brush.circle(b.x, b.y, b.r, 0.05);
    } else {
      brush.line(b.x, b.y, b.x + b.r * 0.65, b.y + b.r * 0.65);
    }
  }

  // Shared white-ink polygonal foam webbing between adjacent bubbles
  brush.set("microPen", "#e2f8ee", 0.65);
  for (let i = 0; i < bubbles.length; i++) {
    let b1 = bubbles[i];
    if (b1.r < 2.5) continue;
    for (let j = i + 1; j < bubbles.length; j++) {
      let b2 = bubbles[j];
      if (b2.r < 2.5) continue;
      let dx = b2.x - b1.x;
      let dy = b2.y - b1.y;
      let d = Math.hypot(dx, dy);
      if (d < b1.r + b2.r + 2.4 && d > 1.0) {
        let mx = b1.x + (dx * b1.r) / (b1.r + b2.r);
        let my = b1.y + (dy * b1.r) / (b1.r + b2.r);
        let px = -dy / d;
        let py = dx / d;
        let chord = Math.min(b1.r, b2.r) * 0.52;
        brush.line(mx - px * chord, my - py * chord, mx + px * chord, my + py * chord);
      }
    }
  }

  // PASS D: White Marker & Micro-Pen Specular Highlights (the signature hyperreal detail)
  for (let b of bubbles) {
    if (b.r >= 4.2) {
      brush.set("glossMarker", "#ffffff", constrain(b.r * 0.11, 0.45, 1.15));
      let arcPts = [];
      for (let a = 190; a <= 265; a += 25) {
        let p = (a === 215 || a === 240) ? 1.35 : 0.45;
        arcPts.push([
          b.x + cos(a) * b.r * 0.64,
          b.y + sin(a) * b.r * 0.64,
          p
        ]);
      }
      safeSpline(arcPts, 0.4);

      brush.set("microPen", "#ffffff", 1.15);
      let hx = b.x - b.r * 0.42;
      let hy = b.y - b.r * 0.42;
      brush.line(hx - 0.8, hy + 0.8, hx + 1.2, hy - 1.0);

      let bx2 = b.x + b.r * 0.48;
      let by2 = b.y + b.r * 0.48;
      brush.line(bx2 - 0.5, by2 + 0.5, bx2 + 0.6, by2 - 0.5);
    } else if (b.r >= 2.3) {
      brush.set("glossMarker", "#ffffff", 0.55);
      let hx = b.x - b.r * 0.36;
      let hy = b.y - b.r * 0.36;
      brush.line(hx - 0.6, hy + 0.5, hx + 0.9, hy - 0.7);

      brush.set("microPen", "#ffffff", 0.95);
      brush.line(hx, hy, hx + 0.8, hy - 0.6);
      brush.line(b.x + b.r * 0.38, b.y + b.r * 0.38, b.x + b.r * 0.45, b.y + b.r * 0.32);
    } else {
      brush.set("microPen", "#ffffff", 0.9);
      let hx = b.x - b.r * 0.32;
      let hy = b.y - b.r * 0.32;
      brush.line(hx, hy, hx + 0.9, hy - 0.7);
    }
  }
}

// ============================================================================
// LAYER 6: TIPPED GLASS TUMBLER (SEEN FROM ABOVE)
// ============================================================================

function drawTippedGlass() {
  let gf = getGlassFrame();

  // 1. Translucent glass cylinder body wash (soft pastel ice-blue & lavender tint)
  let mPts = glassEllipsePoints(0.0, 1.0, 48);
  let bPts = glassEllipsePoints(1.0, 1.0, 48);
  let bodyPoly = [];
  for (let i = 24; i < 48; i++) bodyPoly.push(mPts[i]);
  bodyPoly.push(mPts[0]);
  for (let i = 0; i <= 24; i++) bodyPoly.push(bPts[i]);
  new brush.Polygon(bodyPoly).wash("#bae6fd", 22);

  // 2. Thick solid glass sham (base puck from t = 0.84 to t = 1.00)
  let shamRings = [
    { t: 1.00, r: 1.00, col: "#090d14", op: 165 },
    { t: 0.97, r: 0.94, col: "#7dd3fc", op: 52 },
    { t: 0.93, r: 0.86, col: "#0f172a", op: 150 },
    { t: 0.89, r: 0.82, col: "#c4b5fd", op: 48 },
    { t: 0.85, r: 0.88, col: "#6ee7b7", op: 40 },
    { t: 0.84, r: 0.76, col: "#090d14", op: 120 }
  ];
  for (let sr of shamRings) {
    let pts = glassEllipsePoints(sr.t, sr.r, 40);
    new brush.Polygon(pts).wash(sr.col, sr.op);
  }

  // 3. Refractive longitudinal facets / fluted ridges along the tumbler wall
  let facetOffsets = [-0.94, -0.78, -0.56, -0.28, 0.05, 0.36, 0.64, 0.86, 0.95];
  for (let s of facetOffsets) {
    let p0 = glassWallPoint(0.0, s);
    let p1 = glassWallPoint(0.42, s * 0.99);
    let p2 = glassWallPoint(0.84, s);
    let p3 = glassWallPoint(1.00, s * 0.95);

    let isEdge = Math.abs(s) > 0.88;
    let isUpperHighlight = (s > -0.82 && s < -0.45);

    if (isEdge) {
      brush.set("cpencil", "#05080c", 1.35);
      safeSpline([p0, p1, p2, p3], 0.25);
      brush.set("glossMarker", "#e0f2fe", 0.95);
      safeSpline([p0, p1, p2, p3], 0.25);
    } else if (isUpperHighlight) {
      brush.set("glossMarker", "#ffffff", 1.45);
      safeSpline([p0, p1, p2], 0.2);
      brush.set("microPen", "#ffffff", 1.1);
      safeSpline([p0, p1, p2], 0.2);
    } else {
      brush.set("cpencil", s < 0 ? "#bae6fd" : "#a7f3d0", 0.65);
      safeSpline([p0, p1, p2], 0.25);
    }
  }

  // Broad studio softbox reflection strip along the upper-left glass barrel
  let stripA0 = glassWallPoint(0.04, -0.74);
  let stripA1 = glassWallPoint(0.82, -0.74);
  let stripB1 = glassWallPoint(0.82, -0.50);
  let stripB0 = glassWallPoint(0.04, -0.50);
  new brush.Polygon([stripA0, stripA1, stripB1, stripB0]).wash("#ffffff", 58);

  // Secondary warm radar-bounce reflection along the lower-right glass barrel
  let stripC0 = glassWallPoint(0.06, 0.55);
  let stripC1 = glassWallPoint(0.80, 0.55);
  let stripD1 = glassWallPoint(0.80, 0.78);
  let stripD0 = glassWallPoint(0.06, 0.78);
  new brush.Polygon([stripC0, stripC1, stripD1, stripD0]).wash("#fde047", 28);

  // 4. Internal meniscus ring where the pouring cola clings to the inside of the glass
  brush.set("glossMarker", "#6ee7b7", 0.85);
  let clingPts = [
    glassWallPoint(0.02, -0.36),
    glassWallPoint(0.22, -0.22),
    glassWallPoint(0.40, 0.02),
    glassWallPoint(0.46, 0.34),
    glassWallPoint(0.28, 0.52),
    glassWallPoint(0.02, 0.48)
  ];
  safeSpline(clingPts, 0.45);
  brush.set("microPen", "#ffffff", 0.9);
  safeSpline(clingPts.slice(0, 4), 0.45);

  // 5. Heavy Glass Base Rim & Internal Refraction Rings (t = 0.84 to 1.00)
  let baseRingStyles = [
    { t: 1.00, r: 1.00, b: "cpencil",     col: "#05070b", w: 1.3 },
    { t: 0.99, r: 0.98, b: "glossMarker", col: "#e0f2fe", w: 1.1 },
    { t: 0.98, r: 0.96, b: "microPen",    col: "#ffffff", w: 1.2 },
    { t: 0.92, r: 0.86, b: "glossMarker", col: "#a7f3d0", w: 0.95 },
    { t: 0.86, r: 0.89, b: "glossMarker", col: "#f5d0fe", w: 0.85 },
    { t: 0.84, r: 0.88, b: "microPen",    col: "#ffffff", w: 1.05 }
  ];

  for (let br of baseRingStyles) {
    let pts = glassEllipsePoints(br.t, br.r, 48);
    pts.push(pts[0]);
    brush.set(br.b, br.col, br.w);
    safeSpline(pts, 0.35);
  }

  // Intense white specular arcs on the upper-left and lower-right edges of the heavy glass base
  brush.set("glossMarker", "#ffffff", 1.65);
  let baseHi1 = glassEllipsePoints(0.98, 0.97, 48).slice(26, 42);
  safeSpline(baseHi1, 0.35);
  let baseHi2 = glassEllipsePoints(0.85, 0.89, 48).slice(28, 40);
  safeSpline(baseHi2, 0.35);

  // 6. The Elliptical Glass Mouth Rim at (760, 382)
  let outerLip = glassEllipsePoints(0.0, 1.015, 60);
  let midLip   = glassEllipsePoints(0.0, 0.995, 60);
  let innerLip = glassEllipsePoints(0.0, 0.968, 60);

  outerLip.push(outerLip[0]);
  midLip.push(midLip[0]);
  innerLip.push(innerLip[0]);

  brush.set("cpencil", "#070b10", 1.25);
  safeSpline(outerLip, 0.35);
  safeSpline(innerLip, 0.35);

  brush.set("glossMarker", "#6ee7b7", 1.15);
  safeSpline(midLip, 0.35);
  brush.set("glossMarker", "#bae6fd", 0.95);
  safeSpline(outerLip, 0.35);

  brush.set("glossMarker", "#ffffff", 1.55);
  safeSpline(outerLip.slice(22, 46), 0.35);
  safeSpline(innerLip.slice(24, 44), 0.35);
  safeSpline(outerLip.slice(52, 60), 0.35);
  safeSpline(outerLip.slice(0, 10), 0.35);

  brush.set("microPen", "#ffffff", 1.25);
  safeSpline(outerLip.slice(20, 48), 0.35);
  safeSpline(innerLip.slice(22, 46), 0.35);
  safeSpline(midLip.slice(50, 60), 0.35);
  safeSpline(midLip.slice(0, 12), 0.35);
}

function glassWallPoint(t, s) {
  let gf = getGlassFrame();
  let cx = lerp(GLASS.mx, GLASS.bx, t);
  let cy = lerp(GLASS.my, GLASS.by, t);
  let rMaj = lerp(GLASS.rm, GLASS.rb, t);
  return [
    cx + gf.vx * (s * rMaj),
    cy + gf.vy * (s * rMaj)
  ];
}

// ============================================================================
// ANIMATION ENGINE (INITIALIZED AFTER FRAME 1 COMPLETES)
// ============================================================================

function initMotionData() {
  randomSeed(91827);
  noiseSeed(8472);

  // 1. Cache static base field & domain-warp noise tables for sub-millisecond updates
  for (let ix = 0; ix <= GRID_N; ix++) {
    baseGridF[ix] = new Float32Array(gridF[ix]);
    warpXGrid[ix] = new Float32Array(GRID_N + 1);
    warpYGrid[ix] = new Float32Array(GRID_N + 1);
    scallopGrid[ix] = new Float32Array(GRID_N + 1);
    let x = ix * GRID_STEP;
    for (let iy = 0; iy <= GRID_N; iy++) {
      let y = iy * GRID_STEP;
      warpXGrid[ix][iy] = x + (noise(x * 0.004, y * 0.004, 1.2) - 0.5) * 34;
      warpYGrid[ix][iy] = y + (noise(x * 0.004, y * 0.004, 5.7) - 0.5) * 34;
      let n1 = noise(x * 0.011, y * 0.011, 9.1) - 0.5;
      let n2 = noise(x * 0.026, y * 0.026, 3.4) - 0.5;
      scallopGrid[ix][iy] = n1 * 0.14 + n2 * 0.05;
    }
  }

  // 2. Classify initial bubbles into pouring-plume vs leading-edge meniscus bubbles
  animBubbles = initialBubbles.map((b, idx) => {
    let ax = 775, ay = 380, bx = 490, by = 635;
    let vx = bx - ax, vy = by - ay;
    let l2 = vx * vx + vy * vy;
    let proj = constrain(((b.x - ax) * vx + (b.y - ay) * vy) / l2, 0, 1);
    let px = ax + proj * vx;
    let py = ay + proj * vy;
    let dAxis = Math.hypot(b.x - px, b.y - py);

    let isPlume = (b.f > 1.37) || (dAxis < 88 && b.f > 1.15 && b.x > 420 && b.y < 685);
    return {
      x: b.x,
      y: b.y,
      x0: b.x,
      y0: b.y,
      r: b.r,
      r0: b.r,
      f: b.f,
      f0: constrain(b.f, 1.035, 1.36),
      seed: b.seed,
      isPlume: isPlume,
      driftDir: ((idx % 2 === 0) ? 1 : -1) * (0.35 + (idx % 7) * 0.08),
      birthU: -1
    };
  });

  // 3. Pre-generate new bubbles pouring from inside the tipped glass mouth & nucleating on expanding lobes
  spawnedBubbles = [];
  for (let i = 0; i < 64; i++) {
    let birthU = map(i, 0, 63, 0.02, 0.88);
    let spread = random(-0.75, 0.75);
    let x0 = 815 + spread * 28 + random(-10, 10);
    let y0 = 342 + spread * 24 + random(-10, 10);
    let roll = random();
    let r0 = roll < 0.14 ? random(6.2, 10.6) : (roll < 0.50 ? random(3.2, 6.0) : random(1.6, 3.1));
    spawnedBubbles.push({
      x: x0, y: y0, x0: x0, y0: y0,
      r: 0, r0: r0, f: 1.85, f0: 1.85,
      seed: 95000 + i * 23,
      isPlume: true,
      driftDir: random(-0.6, 0.6),
      birthU: birthU
    });
  }

  let lobeAnchors = [
    { x: 172, y: 438 }, { x: 180, y: 660 }, { x: 155, y: 585 },
    { x: 205, y: 975 }, { x: 205, y: 865 }, { x: 590, y: 1030 },
    { x: 445, y: 980 }, { x: 862, y: 785 }, { x: 695, y: 895 }
  ];
  for (let i = 0; i < 54; i++) {
    let la = lobeAnchors[i % lobeAnchors.length];
    let birthU = map(i, 0, 53, 0.06, 0.78);
    let x0 = la.x + random(-28, 28);
    let y0 = la.y + random(-28, 28);
    let r0 = random() < 0.25 ? random(4.0, 6.8) : random(1.8, 3.8);
    spawnedBubbles.push({
      x: x0, y: y0, x0: x0, y0: y0,
      r: 0, r0: r0, f: 1.12, f0: random(1.055, 1.24),
      seed: 105000 + i * 29,
      isPlume: false,
      driftDir: random(-0.5, 0.5),
      birthU: birthU
    });
  }

  // 4. Pre-generate refracted stone flecks for the thin outer meniscus
  let refractedColors = ["#1c3830", "#2d594b", "#48826e", "#76b59f"];
  for (let cIdx = 0; cIdx < refractedColors.length; cIdx++) {
    let rc = refractedColors[cIdx];
    for (let i = 0; i < 165; i++) {
      refractedEdgeFlecks.push({
        x: random(65, 1020),
        y: random(260, 1140),
        l: random(2.5, 5.5),
        a: random(360),
        col: rc,
        seed: 120000 + cIdx * 500 + i
      });
    }
  }
}

function updateSpillField(u) {
  // Reset gridF to baseGridF (the still's exact field)
  for (let ix = 0; ix <= GRID_N; ix++) {
    gridF[ix].set(baseGridF[ix]);
  }

  // Advancing fluid capsules: pouring neck surge + 6 spreading lobes + droplet bridges
  let uLobe = Math.pow(u, 0.92);
  let uBridge1 = constrain((u - 0.08) / 0.65, 0, 1); // Bridge to (118, 548)
  let uBridge2 = constrain((u - 0.14) / 0.70, 0, 1); // Bridge to (142, 828) & (112, 878)
  let uBridge3 = constrain((u - 0.18) / 0.72, 0, 1); // Bridge to (418, 1068)
  let uBridge4 = constrain((u - 0.12) / 0.68, 0, 1); // Bridge to (702, 952)

  let dynCapsules = [
    // Pouring stream surge from glass mouth into crimson core
    { ax: 785, ay: 368, bx: 485, by: 640, r: 138, w: 0.52 * u },
    // Central basin radial expansion into lobe necks
    { ax: 545, ay: 560, bx: 235, by: 452, r: 108, w: 0.55 * u },
    { ax: 460, ay: 635, bx: 205, by: 662, r: 106, w: 0.58 * u },
    { ax: 455, ay: 675, bx: 245, by: 935, r: 116, w: 0.62 * u },
    { ax: 495, ay: 675, bx: 565, by: 985, r: 110, w: 0.56 * u },
    { ax: 565, ay: 630, bx: 815, by: 762, r: 102, w: 0.54 * u },

    // Lobe 1 (Upper-Left) advancing from (188, 442) to (104, 414)
    { ax: 215, ay: 452, bx: lerp(188, 104, uLobe), by: lerp(442, 414, uLobe), r: 68, w: 1.18 * u },

    // Lobe 2 (Far-Left) advancing from (195, 662) to (106, 672)
    { ax: 220, ay: 660, bx: lerp(195, 106, uLobe), by: lerp(662, 672, uLobe), r: 78, w: 1.24 * u },

    // Coalescing bridge from Upper/Mid-Left bay across droplet (118, 548) to (92, 538)
    { ax: 215, ay: 585, bx: lerp(185, 92, uBridge1), by: lerp(572, 538, uBridge1), r: 58, w: 1.15 * uBridge1 },

    // Lobe 3 (Bottom-Left) sweeping from (222, 962) to (138, 1056)
    { ax: 250, ay: 930, bx: lerp(222, 138, uLobe), by: lerp(962, 1056, uLobe), r: 75, w: 1.28 * u },

    // Coalescing bridge from Bottom-Left flank across droplets (142, 828) & (112, 878)
    { ax: 255, ay: 845, bx: lerp(215, 94, uBridge2), by: lerp(838, 882, uBridge2), r: 62, w: 1.18 * uBridge2 },

    // Lobe 4 (Bottom-Center) advancing from (582, 1018) to (626, 1106)
    { ax: 560, ay: 980, bx: lerp(582, 626, uLobe), by: lerp(1018, 1106, uLobe), r: 70, w: 1.22 * u },

    // Coalescing finger toward bottom droplet (418, 1068) -> (406, 1094)
    { ax: 468, ay: 910, bx: lerp(452, 406, uBridge3), by: lerp(935, 1094, uBridge3), r: 56, w: 1.12 * uBridge3 },

    // Lobe 5 (Right-Side) curling from (848, 778) to (942, 822)
    { ax: 810, ay: 760, bx: lerp(848, 942, uLobe), by: lerp(778, 822, uLobe), r: 65, w: 1.20 * u },

    // Lower-Right lobe advancing across droplet (702, 952) to (726, 992)
    { ax: 678, ay: 845, bx: lerp(685, 726, uBridge4), by: lerp(860, 992, uBridge4), r: 64, w: 1.18 * uBridge4 }
  ];

  // Advancing bulbous lobe heads & central crimson surge peaks
  let dynMetaballs = [
    // Central crimson core surge
    { x: lerp(540, 472, u), y: lerp(585, 650, u), r: 195, w: 0.56 * u },
    { x: lerp(488, 395, u), y: lerp(635, 735, u), r: 165, w: 0.48 * u },
    // Advancing rounded surface-tension lobe heads
    { x: lerp(188, 100, uLobe), y: lerp(442, 412, uLobe), r: 66, w: 0.72 * u },
    { x: lerp(195, 102, uLobe), y: lerp(662, 672, uLobe), r: 74, w: 0.76 * u },
    { x: lerp(222, 134, uLobe), y: lerp(962, 1060, uLobe), r: 74, w: 0.78 * u },
    { x: lerp(582, 628, uLobe), y: lerp(1018, 1110, uLobe), r: 68, w: 0.74 * u },
    { x: lerp(848, 946, uLobe), y: lerp(778, 824, uLobe), r: 64, w: 0.72 * u },
    // Swelling shoulder near upper-right glass pour
    { x: lerp(665, 705, u), y: lerp(525, 555, u), r: 92, w: 0.44 * u },
    // Engulfed satellite droplets swelling outward as lobes coalesce
    { x: lerp(118, 92, uBridge1),  y: lerp(548, 536, uBridge1),  r: 44, w: 0.65 * uBridge1 },
    { x: lerp(112, 86, uBridge2),  y: lerp(878, 892, uBridge2),  r: 36, w: 0.72 * uBridge2 },
    { x: lerp(918, 944, u),        y: lerp(692, 704, u),         r: 36, w: 0.55 * u }
  ];

  // Fast bounding-box splatting for dynamic capsules
  for (let i = 0; i < dynCapsules.length; i++) {
    let c = dynCapsules[i];
    if (c.w <= 1e-4) continue;
    let rCut = c.r * 1.80;
    let minX = Math.min(c.ax, c.bx) - rCut - 20;
    let maxX = Math.max(c.ax, c.bx) + rCut + 20;
    let minY = Math.min(c.ay, c.by) - rCut - 20;
    let maxY = Math.max(c.ay, c.by) + rCut + 20;
    let ix0 = Math.max(0, Math.floor(minX / GRID_STEP));
    let ix1 = Math.min(GRID_N, Math.ceil(maxX / GRID_STEP));
    let iy0 = Math.max(0, Math.floor(minY / GRID_STEP));
    let iy1 = Math.min(GRID_N, Math.ceil(maxY / GRID_STEP));

    let vx = c.bx - c.ax;
    let vy = c.by - c.ay;
    let l2 = vx * vx + vy * vy + 1e-6;
    let r2 = c.r * c.r;
    let maxD2 = r2 * 3.2;

    for (let ix = ix0; ix <= ix1; ix++) {
      let wxCol = warpXGrid[ix];
      let wyCol = warpYGrid[ix];
      let fCol = gridF[ix];
      let scCol = scallopGrid[ix];
      for (let iy = iy0; iy <= iy1; iy++) {
        let wx = wxCol[iy];
        let wy = wyCol[iy];
        let t = constrain(((wx - c.ax) * vx + (wy - c.ay) * vy) / l2, 0, 1);
        let px = c.ax + t * vx;
        let py = c.ay + t * vy;
        let d2 = (wx - px) * (wx - px) + (wy - py) * (wy - py);
        if (d2 < maxD2) {
          let add = c.w * Math.exp(-d2 / r2);
          fCol[iy] += add * (1 + scCol[iy] * 0.65);
        }
      }
    }
  }

  // Fast bounding-box splatting for dynamic metaballs
  for (let i = 0; i < dynMetaballs.length; i++) {
    let m = dynMetaballs[i];
    if (m.w <= 1e-4) continue;
    let rCut = m.r * 1.88;
    let ix0 = Math.max(0, Math.floor((m.x - rCut - 20) / GRID_STEP));
    let ix1 = Math.min(GRID_N, Math.ceil((m.x + rCut + 20) / GRID_STEP));
    let iy0 = Math.max(0, Math.floor((m.y - rCut - 20) / GRID_STEP));
    let iy1 = Math.min(GRID_N, Math.ceil((m.y + rCut + 20) / GRID_STEP));
    let r2 = m.r * m.r;
    let maxD2 = r2 * 3.5;

    for (let ix = ix0; ix <= ix1; ix++) {
      let wxCol = warpXGrid[ix];
      let wyCol = warpYGrid[ix];
      let fCol = gridF[ix];
      let scCol = scallopGrid[ix];
      for (let iy = iy0; iy <= iy1; iy++) {
        let wx = wxCol[iy];
        let wy = wyCol[iy];
        let d2 = (wx - m.x) * (wx - m.x) + (wy - m.y) * (wy - m.y);
        if (d2 < maxD2) {
          let add = m.w * Math.exp(-d2 / r2);
          fCol[iy] += add * (1 + scCol[iy] * 0.65);
        }
      }
    }
  }

  // Recompute central-difference gradients
  for (let ix = 1; ix < GRID_N; ix++) {
    for (let iy = 1; iy < GRID_N; iy++) {
      gradX[ix][iy] = (gridF[ix + 1][iy] - gridF[ix - 1][iy]) / (2 * GRID_STEP);
      gradY[ix][iy] = (gridF[ix][iy + 1] - gridF[ix][iy - 1]) / (2 * GRID_STEP);
    }
  }
}

// ============================================================================
// STABILIZED CONTOUR RESAMPLING & BUBBLE ADVECTION
// ============================================================================

function stabilizeLoop(pts, keyId, stride = 3, closeLoop = true) {
  let n = pts.length;
  if (n < 6) return [];

  let cx = 0, cy = 0;
  for (let i = 0; i < n; i++) {
    cx += pts[i][0];
    cy += pts[i][1];
  }
  cx /= n;
  cy /= n;

  // Fixed anchor near stationary pouring neck (880, 260) for main loop, or top-left for droplets
  let anchorX = n > 45 ? 880 : (cx - 100);
  let anchorY = n > 45 ? 260 : (cy - 100);

  let bestIdx = 0;
  let bestD2 = Infinity;
  for (let i = 0; i < n; i++) {
    let dx = pts[i][0] - anchorX;
    let dy = pts[i][1] - anchorY;
    let d2 = dx * dx + dy * dy;
    if (d2 < bestD2) {
      bestD2 = d2;
      bestIdx = i;
    }
  }

  let ordered = [];
  let cumLen = [0];
  let totalLen = 0;
  for (let i = 0; i <= n; i++) {
    let pt = pts[(bestIdx + i) % n];
    ordered.push(pt);
    if (i > 0) {
      let prev = ordered[i - 1];
      let segLen = Math.hypot(pt[0] - prev[0], pt[1] - prev[1]);
      totalLen += segLen;
      cumLen.push(totalLen);
    }
  }
  if (totalLen < 22) return [];

  // Lock target vertex count per loop key so spline/fill random consumption stays constant
  let fullKey = `${keyId}_${n > 45 ? "M" : Math.round(cx / 60) + "_" + Math.round(cy / 60)}`;
  let targetN = loopTargetCounts.get(fullKey);
  if (!targetN) {
    targetN = Math.max(8, Math.round(n / stride));
    loopTargetCounts.set(fullKey, targetN);
  }

  let out = [];
  let step = totalLen / targetN;
  let segIdx = 0;
  for (let k = 0; k < targetN; k++) {
    let d = k * step;
    while (segIdx < n - 1 && cumLen[segIdx + 1] < d) {
      segIdx++;
    }
    let l0 = cumLen[segIdx];
    let l1 = cumLen[segIdx + 1];
    let f = (l1 - l0) > 1e-6 ? (d - l0) / (l1 - l0) : 0;
    let p0 = ordered[segIdx];
    let p1 = ordered[segIdx + 1];
    out.push([
      p0[0] + f * (p1[0] - p0[0]),
      p0[1] + f * (p1[1] - p0[1])
    ]);
  }
  if (closeLoop) {
    out.push([out[0][0], out[0][1]]);
  }
  return out;
}

function getPlumeVelocity(x, y) {
  let ax = 795, ay = 362;
  let bx = 505, by = 620;
  let jx = bx - ax, jy = by - ay;
  let jl = Math.hypot(jx, jy);
  let ux = jx / jl, uy = jy / jl;

  let proj = ((x - ax) * ux + (y - ay) * uy) / jl;
  let px = ax + constrain(proj, 0, 1) * jx;
  let py = ay + constrain(proj, 0, 1) * jy;
  let dJet = Math.hypot(x - px, y - py);

  let jetW = Math.exp(-(dJet * dJet) / (115 * 115)) * constrain(1.25 - proj * 0.65, 0.15, 1.2);
  let speedJet = 128 * jetW;

  let rx = x - 535;
  let ry = y - 595;
  let rl = Math.hypot(rx, ry) + 1e-4;
  let radW = constrain(proj, 0.1, 1.0) * (1.0 - jetW * 0.55);
  let speedRad = 68 * radW;

  let swirl = (noise(x * 0.007, y * 0.007, 4.2) - 0.5) * 42;

  return {
    vx: ux * speedJet + (rx / rl) * speedRad - (ry / rl) * swirl,
    vy: uy * speedJet + (ry / rl) * speedRad + (rx / rl) * swirl
  };
}

function stepAnimatedBubbles(u) {
  let dt = 1.0 / (TOTAL_FRAMES - 1);

  function updateSingleBubble(b) {
    if (b.isPlume) {
      let v = getPlumeVelocity(b.x, b.y);
      b.x += v.vx * dt;
      b.y += v.vy * dt;
      b.f = sampleField(b.x, b.y);
      if (b.f < 1.08) {
        let g = sampleGrad(b.x, b.y);
        let gm = Math.hypot(g.gx, g.gy) + 1e-5;
        b.x += (g.gx / gm) * 2.5;
        b.y += (g.gy / gm) * 2.5;
        b.f = sampleField(b.x, b.y);
      }
    } else {
      let fv = sampleField(b.x, b.y);
      if (fv > b.f0 + 0.16) {
        let rx = b.x - 488;
        let ry = b.y - 635;
        let rl = Math.hypot(rx, ry) + 1e-4;
        b.x += (rx / rl) * 2.4;
        b.y += (ry / rl) * 2.4;
      }

      for (let k = 0; k < 4; k++) {
        let val = sampleField(b.x, b.y);
        let g = sampleGrad(b.x, b.y);
        let g2 = g.gx * g.gx + g.gy * g.gy;
        if (g2 > 1e-5) {
          let step = constrain((val - b.f0) / g2, -4.5, 4.5);
          b.x -= step * g.gx;
          b.y -= step * g.gy;
        }
      }

      let g = sampleGrad(b.x, b.y);
      let gm = Math.hypot(g.gx, g.gy);
      if (gm > 1e-5) {
        let tx = -g.gy / gm;
        let ty = g.gx / gm;
        b.x += tx * b.driftDir * 0.45;
        b.y += ty * b.driftDir * 0.45;
      }
      b.f = sampleField(b.x, b.y);
    }
  }

  for (let b of animBubbles) {
    updateSingleBubble(b);
    let swell = 1.0 + 0.08 * Math.sin(u * 180 + (b.seed % 90));
    b.r = b.r0 * swell;
  }

  for (let sb of spawnedBubbles) {
    if (u <= sb.birthU) {
      sb.r = 0;
      continue;
    }
    let age = constrain((u - sb.birthU) / 0.14, 0, 1);
    sb.r = sb.r0 * (age * age * (3 - 2 * age));
    updateSingleBubble(sb);
  }

  let active = [];
  for (let b of animBubbles) active.push(b);
  for (let sb of spawnedBubbles) if (sb.r > 0.8) active.push(sb);

  let nAct = active.length;
  for (let i = 0; i < nAct; i++) {
    let b1 = active[i];
    for (let j = i + 1; j < nAct; j++) {
      let b2 = active[j];
      let dx = b2.x - b1.x;
      let dy = b2.y - b1.y;
      let minD = (b1.r + b2.r) * 0.88;
      if (Math.abs(dx) < minD && Math.abs(dy) < minD) {
        let d2 = dx * dx + dy * dy;
        if (d2 < minD * minD && d2 > 1e-4) {
          let d = Math.sqrt(d2);
          let push = (minD - d) * 0.35;
          let nx = dx / d;
          let ny = dy / d;
          let w1 = b2.r / (b1.r + b2.r);
          let w2 = b1.r / (b1.r + b2.r);
          b1.x -= nx * push * w1;
          b1.y -= ny * push * w1;
          b2.x += nx * push * w2;
          b2.y += ny * push * w2;
        }
      }
    }
  }
}

// ============================================================================
// ANIMATED SCENE RENDERER (FRAMES 2..48 — EXACT SAME SHADING AS STILL)
// ============================================================================

function drawAnimatedScene(u) {
  brush.noField();
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();

  // 1. Expanding Spill Cast Shadow & Dark Cola-Obsidian Base Body (exact still opacities)
  let outerLoops = extractContours(0.96, 2);
  for (let loop of outerLoops) {
    let dec = decimateLoop(loop, 2);
    if (dec.length >= 5) {
      let shifted1 = dec.map(p => [p[0] + 4.5, p[1] + 5.5]);
      let shifted2 = dec.map(p => [p[0] + 2.0, p[1] + 2.5]);
      new brush.Polygon(shifted1).wash("#030407", 150);
      new brush.Polygon(shifted2).wash("#020305", 195);
    }
  }

  let edgeLoops = extractContours(1.00, 2);
  for (let loop of edgeLoops) {
    let dec = decimateLoop(loop, 2);
    if (dec.length >= 5) {
      new brush.Polygon(dec).wash("#0c1412", 230);
    }
  }

  // Refracted cool seafoam stone flecks inside the thin outer meniscus (seeded per fleck)
  for (let rf of refractedEdgeFlecks) {
    let f = sampleField(rf.x, rf.y);
    if (f > 1.02 && f < 1.52) {
      randomSeed(rf.seed);
      noiseSeed(rf.seed);
      brush.set("cpencil", rf.col, 0.7);
      brush.line(rf.x, rf.y, rf.x + cos(rf.a) * rf.l, rf.y + sin(rf.a) * rf.l);
    }
  }
  brush.noStroke();

  // 2. Concentric Radar Zone Washes (exact still levels & opacities)
  let washLevels = [
    { t: 1.02, op: 115 },
    { t: 1.07, op: 125 },
    { t: 1.14, op: 130 },
    { t: 1.22, op: 130 },
    { t: 1.32, op: 125 },
    { t: 1.42, op: 125 },
    { t: 1.52, op: 135 },
    { t: 1.63, op: 140 },
    { t: 1.74, op: 145 },
    { t: 1.86, op: 145 },
    { t: 1.98, op: 150 },
    { t: 2.11, op: 150 },
    { t: 2.24, op: 155 },
    { t: 2.38, op: 160 },
    { t: 2.52, op: 165 },
    { t: 2.66, op: 175 },
    { t: 2.80, op: 185 },
    { t: 2.95, op: 195 },
    { t: 3.10, op: 205 },
    { t: 3.26, op: 215 }
  ];

  for (let wl of washLevels) {
    let col = getRadarColor(wl.t);
    let loops = extractContours(wl.t, 2);
    for (let loop of loops) {
      let dec = decimateLoop(loop, 2);
      if (dec.length >= 5) {
        new brush.Polygon(dec).wash(col, wl.op);
      }
    }
  }

  // Selective watercolor bleed passes on key zone transitions (exact still .fill() passes)
  let bleedLevels = [
    { t: 1.18, col: "#6ee7b7", op: 55, bleed: 0.14 },
    { t: 1.68, col: "#fef08a", op: 50, bleed: 0.12 },
    { t: 2.18, col: "#fdba74", op: 55, bleed: 0.12 },
    { t: 2.65, col: "#f43f5e", op: 65, bleed: 0.15 },
    { t: 3.05, col: "#881337", op: 75, bleed: 0.16 }
  ];
  for (let bIdx = 0; bIdx < bleedLevels.length; bIdx++) {
    let bl = bleedLevels[bIdx];
    let loops = extractContours(bl.t, 2);
    for (let lIdx = 0; lIdx < loops.length; lIdx++) {
      let stab = stabilizeLoop(loops[lIdx], `BLEED_${bIdx}`, 4, false);
      if (stab.length >= 5) {
        randomSeed(25000 + bIdx * 97 + lIdx * 19);
        noiseSeed(25000 + bIdx * 97 + lIdx * 19);
        new brush.Polygon(stab).fill(bl.col, bl.op, bl.bleed, 0.25);
      }
    }
  }
  brush.noFill();
  brush.noWash();

  // 3. Stabilized Concentric Spray-Mist Zones (all 55 levels at t += 0.042, exact still weights)
  let mistIdx = 0;
  for (let t = 1.03; t <= 3.32; t += 0.042) {
    let col = getRadarColor(t + 0.03);
    let loops = extractContours(t, 2);
    let useFine = (Math.round(t * 100) % 2 === 0);
    brush.set(useFine ? "fineMist" : "radarMist", col, useFine ? 1.05 : 1.15);

    for (let lIdx = 0; lIdx < loops.length; lIdx++) {
      let stab = stabilizeLoop(loops[lIdx], `MIST_${mistIdx}`, 3, true);
      if (stab.length >= 5) {
        randomSeed(30000 + mistIdx * 131 + lIdx * 17);
        noiseSeed(30000 + mistIdx * 131 + lIdx * 17);
        safeSpline(stab, 0.35);
      }
    }
    mistIdx++;
  }

  // 4. Stabilized Radar Iso-dBZ Contour Rings
  let isoRings = [
    { t: 1.09, col: "#a7f3d0", w: 0.65 },
    { t: 1.28, col: "#d1fae5", w: 0.60 },
    { t: 1.50, col: "#ecfccb", w: 0.65 },
    { t: 1.72, col: "#fef9c3", w: 0.70 },
    { t: 1.98, col: "#ffedd5", w: 0.65 },
    { t: 2.25, col: "#fee2e2", w: 0.65 },
    { t: 2.54, col: "#fecdd3", w: 0.75 },
    { t: 2.84, col: "#fda4af", w: 0.70 },
    { t: 3.14, col: "#f43f5e", w: 0.65 }
  ];

  for (let rIdx = 0; rIdx < isoRings.length; rIdx++) {
    let ir = isoRings[rIdx];
    brush.set("cpencil", ir.col, ir.w);
    let loops = extractContours(ir.t, 2);
    for (let lIdx = 0; lIdx < loops.length; lIdx++) {
      let stab = stabilizeLoop(loops[lIdx], `ISO_${rIdx}`, 2, true);
      if (stab.length >= 5) {
        randomSeed(40000 + rIdx * 97 + lIdx * 13);
        noiseSeed(40000 + rIdx * 97 + lIdx * 13);
        safeSpline(stab, 0.35);
      }
    }
  }

  // 5. Animated Syrupy Internal Flow Currents pouring from glass mouth into crimson pool
  let streamCount = 28;
  let targetPoolX = lerp(485, 442, u);
  let targetPoolY = lerp(635, 672, u);
  let stepLen = lerp(14, 16.8, u);

  for (let s = 0; s < streamCount; s++) {
    randomSeed(50000 + s * 37);
    noiseSeed(8472);
    let spread = map(s, 0, streamCount - 1, -0.65, 0.65);
    let x = 775 + spread * 42;
    let y = 372 + spread * 36;
    let pts = [[x, y]];
    for (let step = 0; step < 26; step++) {
      let dx = targetPoolX - x;
      let dy = targetPoolY - y;
      let d = Math.hypot(dx, dy);
      if (d < 25) break;
      let ang = atan2(dy, dx) + (noise(x * 0.008 + u * 0.65, y * 0.008 - u * 0.65, s * 0.3) - 0.5) * 65;
      x += cos(ang) * stepLen;
      y += sin(ang) * stepLen;
      if (sampleField(x, y) < 1.15) break;
      pts.push([x, y]);
    }
    if (pts.length >= 4) {
      let midPt = pts[Math.floor(pts.length / 2)];
      let fVal = sampleField(midPt[0], midPt[1]);
      let col = getRadarColor(fVal + (s % 2 === 0 ? 0.22 : -0.18));
      randomSeed(51000 + s * 41);
      noiseSeed(51000 + s * 41);
      brush.set("cpencil", col, 0.55);
      safeSpline(pts, 0.45);
    }
  }

  // 6. Meniscus 3D Specular Reflections & Softbox Glare
  drawAnimatedMeniscusReflections(u);

  // 7. Advancing & Pouring Carbonation Bubbles
  drawAnimatedBubbles();

  // 8. Tipped Glass Tumbler (seeded per stroke so glass never boils)
  drawAnimatedTippedGlass(u);
}

function drawAnimatedMeniscusReflections(u) {
  brush.noStroke();
  let shiftX = -16 * u;
  let shiftY = 12 * u;

  let glarePoly1 = new brush.Polygon([
    [355 + shiftX, 515 + shiftY],
    [565 + shiftX * 0.5, 445 + shiftY * 0.5],
    [645 + shiftX * 0.5, 535 + shiftY * 0.5],
    [445 + shiftX, 635 + shiftY]
  ]);
  glarePoly1.wash("#e0f2fe", 20);

  let glarePoly2 = new brush.Polygon([
    [385 + shiftX, 675 + shiftY],
    [595 + shiftX * 0.6, 595 + shiftY * 0.6],
    [655 + shiftX * 0.6, 675 + shiftY * 0.6],
    [455 + shiftX, 765 + shiftY]
  ]);
  glarePoly2.wash("#fce7f3", 18);

  // Dark surface-tension inner rim at F = 1.012
  let rimLoops = extractContours(1.012, 2);
  brush.set("cpencil", "#071712", 1.15);
  for (let lIdx = 0; lIdx < rimLoops.length; lIdx++) {
    let stab = stabilizeLoop(rimLoops[lIdx], "RIM_1012", 2, true);
    if (stab.length >= 5) {
      randomSeed(55000 + lIdx * 19);
      noiseSeed(55000 + lIdx * 19);
      safeSpline(stab, 0.35);
    }
  }

  // Normal-mapped meniscus specular highlights along the advancing liquid edge
  const L1x = -0.60, L1y = -0.80;
  const L2x = 0.68,  L2y = 0.73;

  let meniscusLevels = [
    { t: 1.045, thresh: 0.32, bName: "glossMarker", col: "#a7f3d0", w: 1.45 },
    { t: 1.065, thresh: 0.42, bName: "glossMarker", col: "#ecfdf5", w: 1.25 },
    { t: 1.080, thresh: 0.54, bName: "glossMarker", col: "#ffffff", w: 0.95 },
    { t: 1.095, thresh: 0.64, bName: "microPen",    col: "#ffffff", w: 1.15 },
    { t: 1.145, thresh: 0.58, bName: "glossMarker", col: "#d1fae5", w: 0.80 },
    { t: 1.155, thresh: 0.68, bName: "microPen",    col: "#ffffff", w: 0.95 },
    { t: 1.540, thresh: 0.74, bName: "glossMarker", col: "#fef9c3", w: 0.75 },
    { t: 2.120, thresh: 0.76, bName: "glossMarker", col: "#ffedd5", w: 0.75 },
    { t: 2.680, thresh: 0.76, bName: "glossMarker", col: "#ffe4e6", w: 0.75 }
  ];

  for (let mIdx = 0; mIdx < meniscusLevels.length; mIdx++) {
    let ml = meniscusLevels[mIdx];
    let loops = extractContours(ml.t, 2);
    brush.set(ml.bName, ml.col, ml.w);

    for (let lIdx = 0; lIdx < loops.length; lIdx++) {
      let stab = stabilizeLoop(loops[lIdx], `MEN_${mIdx}`, 1, true);
      if (stab.length < 6) continue;
      let currentArc = [];
      let arcStartIdx = 0;
      let n = stab.length - 1;

      for (let i = 0; i <= n; i++) {
        let pt = stab[i % n];
        let g = sampleGrad(pt[0], pt[1]);
        let mag = Math.hypot(g.gx, g.gy);
        if (mag < 1e-5) continue;
        let nx = -g.gx / mag;
        let ny = -g.gy / mag;
        let dot1 = Math.max(0, nx * L1x + ny * L1y);
        let dot2 = Math.max(0, nx * L2x + ny * L2y) * 0.82;
        let spec = Math.max(dot1, dot2);

        if (spec >= ml.thresh) {
          if (currentArc.length === 0) arcStartIdx = i;
          let pressure = map(spec, ml.thresh, 1.0, 0.35, 1.45, true);
          currentArc.push([pt[0], pt[1], pressure]);
        } else {
          if (currentArc.length >= 3) {
            let seed = 60000 + mIdx * 700 + lIdx * 53 + Math.floor(arcStartIdx / 5);
            randomSeed(seed);
            noiseSeed(seed);
            safeSpline(currentArc, 0.35);
          }
          currentArc = [];
        }
      }
      if (currentArc.length >= 3) {
        let seed = 60000 + mIdx * 700 + lIdx * 53 + Math.floor(arcStartIdx / 5);
        randomSeed(seed);
        noiseSeed(seed);
        safeSpline(currentArc, 0.35);
      }
    }
  }
}

function drawAnimatedBubbles() {
  let allBubbles = [];
  for (let b of animBubbles) allBubbles.push(b);
  for (let sb of spawnedBubbles) {
    if (sb.r >= 1.1) allBubbles.push(sb);
  }
  allBubbles.sort((a, b) => b.r - a.r);

  // PASS A: Dark spherical shadow base & translucent dome interior
  brush.noStroke();
  for (let b of allBubbles) {
    if (b.r < 3.0) continue;
    let nPts = 14;
    let shPts = [];
    let domPts = [];
    for (let k = 0; k < nPts; k++) {
      let a = (k * 360) / nPts;
      shPts.push([
        b.x + b.r * 0.22 + cos(a) * b.r * 1.05,
        b.y + b.r * 0.25 + sin(a) * b.r * 1.05
      ]);
      domPts.push([
        b.x + cos(a) * b.r * 0.92,
        b.y + sin(a) * b.r * 0.92
      ]);
    }
    new brush.Polygon(shPts).wash("#081210", 175);
    new brush.Polygon(domPts).wash("#132620", 125);
  }

  // PASS B: Subsurface radar-colored bounce refraction in the lower-right crescent
  for (let b of allBubbles) {
    if (b.r < 3.6) continue;
    randomSeed(b.seed + 1);
    noiseSeed(b.seed + 1);
    let col = getRadarColor(b.f + 0.25);
    brush.set("glossMarker", col, constrain(b.r * 0.09, 0.35, 0.95));
    let refPts = [];
    for (let a = -15; a <= 105; a += 30) {
      refPts.push([
        b.x + cos(a) * b.r * 0.68,
        b.y + sin(a) * b.r * 0.68
      ]);
    }
    safeSpline(refPts, 0.4);
  }

  // PASS C: Crisp pen outer contour rings
  brush.set("microPen", "#06110e", 0.95);
  for (let b of allBubbles) {
    randomSeed(b.seed + 2);
    noiseSeed(b.seed + 2);
    if (b.r >= 2.6) {
      brush.circle(b.x, b.y, b.r, 0.05);
    } else {
      brush.line(b.x, b.y, b.x + b.r * 0.65, b.y + b.r * 0.65);
    }
  }

  // Shared white-ink polygonal foam webbing between adjacent bubbles
  brush.set("microPen", "#e2f8ee", 0.65);
  for (let i = 0; i < allBubbles.length; i++) {
    let b1 = allBubbles[i];
    if (b1.r < 2.5) continue;
    for (let j = i + 1; j < allBubbles.length; j++) {
      let b2 = allBubbles[j];
      if (b2.r < 2.5) continue;
      let dx = b2.x - b1.x;
      let dy = b2.y - b1.y;
      let d = Math.hypot(dx, dy);
      if (d < b1.r + b2.r + 2.4 && d > 1.0) {
        randomSeed(b1.seed + b2.seed);
        noiseSeed(b1.seed + b2.seed);
        let mx = b1.x + (dx * b1.r) / (b1.r + b2.r);
        let my = b1.y + (dy * b1.r) / (b1.r + b2.r);
        let px = -dy / d;
        let py = dx / d;
        let chord = Math.min(b1.r, b2.r) * 0.52;
        brush.line(mx - px * chord, my - py * chord, mx + px * chord, my + py * chord);
      }
    }
  }

  // PASS D: White Marker & Micro-Pen Specular Highlights
  for (let b of allBubbles) {
    randomSeed(b.seed + 3);
    noiseSeed(b.seed + 3);
    if (b.r >= 4.2) {
      brush.set("glossMarker", "#ffffff", constrain(b.r * 0.11, 0.45, 1.15));
      let arcPts = [];
      for (let a = 190; a <= 265; a += 25) {
        let p = (a === 215 || a === 240) ? 1.35 : 0.45;
        arcPts.push([
          b.x + cos(a) * b.r * 0.64,
          b.y + sin(a) * b.r * 0.64,
          p
        ]);
      }
      safeSpline(arcPts, 0.4);

      brush.set("microPen", "#ffffff", 1.15);
      let hx = b.x - b.r * 0.42;
      let hy = b.y - b.r * 0.42;
      brush.line(hx - 0.8, hy + 0.8, hx + 1.2, hy - 1.0);

      let bx2 = b.x + b.r * 0.48;
      let by2 = b.y + b.r * 0.48;
      brush.line(bx2 - 0.5, by2 + 0.5, bx2 + 0.6, by2 - 0.5);
    } else if (b.r >= 2.3) {
      brush.set("glossMarker", "#ffffff", 0.55);
      let hx = b.x - b.r * 0.36;
      let hy = b.y - b.r * 0.36;
      brush.line(hx - 0.6, hy + 0.5, hx + 0.9, hy - 0.7);

      brush.set("microPen", "#ffffff", 0.95);
      brush.line(hx, hy, hx + 0.8, hy - 0.6);
      brush.line(b.x + b.r * 0.38, b.y + b.r * 0.38, b.x + b.r * 0.45, b.y + b.r * 0.32);
    } else {
      brush.set("microPen", "#ffffff", 0.9);
      let hx = b.x - b.r * 0.32;
      let hy = b.y - b.r * 0.32;
      brush.line(hx, hy, hx + 0.9, hy - 0.7);
    }
  }
}

function drawAnimatedTippedGlass(u) {
  brush.noStroke();

  // 1. Translucent glass cylinder body wash
  let mPts = glassEllipsePoints(0.0, 1.0, 48);
  let bPts = glassEllipsePoints(1.0, 1.0, 48);
  let bodyPoly = [];
  for (let i = 24; i < 48; i++) bodyPoly.push(mPts[i]);
  bodyPoly.push(mPts[0]);
  for (let i = 0; i <= 24; i++) bodyPoly.push(bPts[i]);
  new brush.Polygon(bodyPoly).wash("#bae6fd", 22);

  // 2. Thick solid glass sham
  let shamRings = [
    { t: 1.00, r: 1.00, col: "#090d14", op: 165 },
    { t: 0.97, r: 0.94, col: "#7dd3fc", op: 52 },
    { t: 0.93, r: 0.86, col: "#0f172a", op: 150 },
    { t: 0.89, r: 0.82, col: "#c4b5fd", op: 48 },
    { t: 0.85, r: 0.88, col: "#6ee7b7", op: 40 },
    { t: 0.84, r: 0.76, col: "#090d14", op: 120 }
  ];
  for (let sr of shamRings) {
    let pts = glassEllipsePoints(sr.t, sr.r, 40);
    new brush.Polygon(pts).wash(sr.col, sr.op);
  }

  // 3. Refractive longitudinal facets (seeded per facet)
  let facetOffsets = [-0.94, -0.78, -0.56, -0.28, 0.05, 0.36, 0.64, 0.86, 0.95];
  for (let idx = 0; idx < facetOffsets.length; idx++) {
    let s = facetOffsets[idx];
    randomSeed(81000 + idx * 31);
    noiseSeed(81000 + idx * 31);

    let p0 = glassWallPoint(0.0, s);
    let p1 = glassWallPoint(0.42, s * 0.99);
    let p2 = glassWallPoint(0.84, s);
    let p3 = glassWallPoint(1.00, s * 0.95);

    let isEdge = Math.abs(s) > 0.88;
    let isUpperHighlight = (s > -0.82 && s < -0.45);

    if (isEdge) {
      brush.set("cpencil", "#05080c", 1.35);
      safeSpline([p0, p1, p2, p3], 0.25);
      brush.set("glossMarker", "#e0f2fe", 0.95);
      safeSpline([p0, p1, p2, p3], 0.25);
    } else if (isUpperHighlight) {
      brush.set("glossMarker", "#ffffff", 1.45);
      safeSpline([p0, p1, p2], 0.2);
      brush.set("microPen", "#ffffff", 1.1);
      safeSpline([p0, p1, p2], 0.2);
    } else {
      brush.set("cpencil", s < 0 ? "#bae6fd" : "#a7f3d0", 0.65);
      safeSpline([p0, p1, p2], 0.25);
