// MOTION: Both cassette reels spin fast, the spilled tape ribbon flutters and spools out, the wireframe floor scrolls forward, and the warped grid reflection slides across the chrome label.
window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

let stillImg = null;
const hubImgs = [null, null];
const rollerImgs = [null, null];
const savedScratches = [];
const savedCreaseSegs = [];

const PAL = {
  paper: "#dfd2bf",       // Warm muted earth flyer paper
  paperLight: "#f4ece0",  // Highlighted paper crease
  paperDark: "#bfa98e",   // Aged pocket-worn paper shadow
  earthUmber: "#2e1c14",  // Deep burnt umber (tape oxide / dark ink)
  earthBlack: "#170e0b",  // Richest iron-oxide shadow
  earthRust: "#6e3b24",   // Warm oxide midtone
  earthOchre: "#b88752",  // Muted golden ochre reflection
  earthSand: "#caa87e",   // Dusty tan
  violetDeep: "#1d0c2e",  // Deep xerox violet
  violetMid: "#3c1b54",   // Bruised duotone plum
  violetSoft: "#6b4668",  // Muted violet-earth transition
  cyanElec: "#00cfe3",    // Electric duotone cyan
  cyanBright: "#6bf4ff",  // High-energy cyan tint
  cyanMuted: "#2e8896",   // Muted teal-cyan
  chromeWhite: "#ffffff", // Pure specular glint
  chromeGrey: "#78848c"   // Cool metallic neutral
};

// Horizon geometry (tilted at -9 degrees for dynamic flyer energy)
const horAngle = -9;
const horRad = horAngle * Math.PI / 180;
const horCos = Math.cos(horRad);
const horSin = Math.sin(horRad);
const vpX = 545;
const vpY = 565;

function horizonY(x) {
  return vpY + (x - vpX) * Math.tan(horRad);
}

// Cassette local-to-world transform (centred on starburst, tilted at -18 deg)
const casCX = 600;
const casCY = 510;
const casAngle = -18;
const casRad = casAngle * Math.PI / 180;
const casCos = Math.cos(casRad);
const casSin = Math.sin(casRad);

function cPt(lx, ly) {
  return [
    casCX + lx * casCos - ly * casSin,
    casCY + lx * casSin + ly * casCos
  ];
}

function worldToCas(wx, wy) {
  let dx = wx - casCX;
  let dy = wy - casCY;
  return [
    dx * casCos + dy * casSin,
    -dx * casSin + dy * casCos
  ];
}

function drawPolyWash(pts, col, opacity) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawCassetteCircle(lx, ly, r, col, weight, bName = "rotring", steps = 36) {
  brush.set(bName, col, weight);
  for (let i = 0; i < steps; i++) {
    let a1 = (i / steps) * 360;
    let a2 = ((i + 1) / steps) * 360;
    let p1 = cPt(lx + cos(a1) * r, ly + sin(a1) * r);
    let p2 = cPt(lx + cos(a2) * r, ly + sin(a2) * r);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function fillCassetteCircle(lx, ly, r, col, opacity, steps = 32) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push(cPt(lx + cos(a) * r, ly + sin(a) * r));
  }
  drawPolyWash(pts, col, opacity);
}

function isInsideLabel(lx, ly) {
  if (lx < -294 || lx > 294 || ly < -174 || ly > 84) return false;
  if (lx + 294 + (-174 - ly) < -26) return false;
  if ((294 - lx) + (-174 - ly) < -26) return false;
  if (lx > -212 && lx < 212 && ly > -70 && ly < 44) return false;
  return true;
}

function warpLabelPt(u, v) {
  let r2 = u * u + v * v;
  let factor = 1 + 0.38 * r2 + 0.12 * Math.sin(u * 4.5) * Math.cos(v * 3.5);
  let lx = u * 310 / factor;
  let ly = -45 + v * 155 / factor + 14 * Math.sin(u * 3.2);
  return [lx, ly];
}

function evalCatmullRom(pts, tGlobal) {
  let n = pts.length - 3;
  let scaled = constrain(tGlobal, 0, 0.999999) * n;
  let idx = Math.floor(scaled);
  let t = scaled - idx;
  let p0 = pts[idx], p1 = pts[idx + 1], p2 = pts[idx + 2], p3 = pts[idx + 3];
  let t2 = t * t, t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

// Lift a circular region of pixels from srcImg with a soft 1.5px anti-aliased edge
function extractCircularPatch(srcImg, cx, cy, r) {
  let d = Math.ceil(r * 2);
  let x0 = Math.round(cx - r);
  let y0 = Math.round(cy - r);
  let patch = srcImg.get(x0, y0, d, d);
  patch.loadPixels();
  let radSq = r * r;
  let innerSq = (r - 1.5) * (r - 1.5);
  for (let py = 0; py < d; py++) {
    for (let px = 0; px < d; px++) {
      let dx = (px + 0.5) - r;
      let dy = (py + 0.5) - r;
      let distSq = dx * dx + dy * dy;
      let idx = (py * d + px) * 4;
      if (distSq > radSq) {
        patch.pixels[idx + 3] = 0;
      } else if (distSq > innerSq) {
        let alpha = map(Math.sqrt(distSq), r - 1.5, r, 255, 0);
        patch.pixels[idx + 3] = Math.round(constrain(alpha, 0, 255));
      }
    }
  }
  patch.updatePixels();
  return patch;
}

// Clip a world-space line segment (p1 -> p2) to the exterior of the cassette body box in local coords
function drawLineOutsideCassette(x1, y1, x2, y2, minLx = -348, maxLx = 332, minLy = -212, maxLy = 246) {
  let c1 = worldToCas(x1, y1);
  let c2 = worldToCas(x2, y2);
  let dx = c2[0] - c1[0];
  let dy = c2[1] - c1[1];

  let t0 = 0, t1 = 1;
  let p = [-dx, dx, -dy, dy];
  let q = [c1[0] - minLx, maxLx - c1[0], c1[1] - minLy, maxLy - c1[1]];
  let intersectsBox = true;

  for (let i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-6) {
      if (q[i] < 0) {
        intersectsBox = false;
        break;
      }
    } else {
      let t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) { intersectsBox = false; break; }
        if (t > t0) t0 = t;
      } else {
        if (t < t0) { intersectsBox = false; break; }
        if (t < t1) t1 = t;
      }
    }
  }

  if (!intersectsBox || t0 >= t1) {
    brush.line(x1, y1, x2, y2);
    return;
  }

  if (t0 > 0.005) {
    brush.line(x1, y1, lerp(x1, x2, t0), lerp(y1, y2, t0));
  }
  if (t1 < 0.995) {
    brush.line(lerp(x1, x2, t1), lerp(y1, y2, t1), x2, y2);
  }
}

