  // 5B. Hyperreal Shiny Magnetic Tape Ribbon
  const baseHalfWidth = 17.5;
  let prevEdgeA = null;
  let prevEdgeB = null;

  for (let i = 0; i <= ribbonSteps; i++) {
    let t = i / ribbonSteps;
    let p = rPts[i];
    let pPrev = rPts[Math.max(0, i - 1)];
    let pNext = rPts[Math.min(ribbonSteps, i + 1)];

    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let tLen = Math.hypot(tx, ty) || 1;
    tx /= tLen;
    ty /= tLen;

    let nx = -ty;
    let ny = tx;

    let twist = t * Math.PI * 7.4 + 0.85 * Math.sin(t * Math.PI * 11) + 0.4 * Math.cos(t * Math.PI * 19);
    let endTaper = (t < 0.04) ? map(t, 0, 0.04, 0.45, 1) : ((t > 0.96) ? map(t, 0.96, 1, 1, 0.45) : 1);
    let hw = baseHalfWidth * endTaper;

    let cosTw = Math.cos(twist);
    let sinTw = Math.sin(twist);

    let wx = (nx * cosTw + tx * 0.24 * sinTw) * hw;
    let wy = (ny * cosTw + ty * 0.24 * sinTw) * hw;

    let edgeA = [p[0] - wx, p[1] - wy];
    let edgeB = [p[0] + wx, p[1] + wy];

    let surfAngle = Math.atan2(ny, nx) + twist * 0.85;
    let spec1 = Math.pow(0.5 + 0.5 * Math.cos(surfAngle * 2.0 - 0.9), 4);
    let spec2 = Math.pow(0.5 + 0.5 * Math.sin(surfAngle * 3.0 + 1.4), 8);

    let bodyCol, highlightCol;
    if (spec2 > 0.72) {
      bodyCol = PAL.cyanBright;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.78) {
      bodyCol = PAL.earthOchre;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.52) {
      bodyCol = PAL.earthRust;
      highlightCol = PAL.cyanElec;
    } else if (spec1 < 0.16) {
      bodyCol = PAL.earthBlack;
      highlightCol = PAL.violetMid;
    } else {
      bodyCol = PAL.earthUmber;
      highlightCol = PAL.earthOchre;
    }

    brush.set("marker", bodyCol, 1.35);
    brush.line(edgeA[0], edgeA[1], edgeB[0], edgeB[1]);

    if (spec2 > 0.55 || spec1 > 0.65 || i % 2 === 0) {
      let hFrac1 = (spec2 > 0.6) ? 0.1 : 0.25;
      let hFrac2 = (spec2 > 0.6) ? 0.9 : 0.75;
      let hx1 = lerp(edgeA[0], edgeB[0], hFrac1);
      let hy1 = lerp(edgeA[1], edgeB[1], hFrac1);
      let hx2 = lerp(edgeA[0], edgeB[0], hFrac2);
      let hy2 = lerp(edgeA[1], edgeB[1], hFrac2);
      brush.set("rotring", highlightCol, (spec2 > 0.72 || spec1 > 0.82) ? 0.9 : 0.5);
      brush.line(hx1, hy1, hx2, hy2);
    }

    if (prevEdgeA && prevEdgeB) {
      let isPinch = Math.abs(cosTw) < 0.35;
      let edgeColA = (isPinch || spec2 > 0.55) ? PAL.chromeWhite : (cosTw > 0 ? PAL.cyanBright : PAL.earthBlack);
      let edgeColB = (isPinch || spec1 > 0.7) ? PAL.chromeWhite : (cosTw < 0 ? PAL.earthOchre : PAL.earthBlack);

      brush.set("rotring", edgeColA, isPinch ? 0.85 : 0.6);
      brush.line(prevEdgeA[0], prevEdgeA[1], edgeA[0], edgeA[1]);

      brush.set("rotring", edgeColB, isPinch ? 0.85 : 0.6);
      brush.line(prevEdgeB[0], prevEdgeB[1], edgeB[0], edgeB[1]);
    }

    prevEdgeA = edgeA;
    prevEdgeB = edgeB;
  }

  const crinkleCtrl = [
    cPt(-35, 204),
    cPt(-38, 222),
    [545, 705],
    [605, 765],
    [655, 705],
    cPt(38, 222),
    cPt(35, 204)
  ];
  let prevCrA = null, prevCrB = null;
  for (let i = 0; i <= 110; i++) {
    let t = i / 110;
    let p = evalCatmullRom(crinkleCtrl, t);
    let pNext = evalCatmullRom(crinkleCtrl, Math.min(1, t + 0.01));
    let tx = pNext[0] - p[0], ty = pNext[1] - p[1];
    let tl = Math.hypot(tx, ty) || 1;
    let nx = -ty / tl, ny = tx / tl;
    let tw = t * Math.PI * 3.2;
    let hw = 13 * Math.cos(tw);
    let eA = [p[0] - nx * hw, p[1] - ny * hw];
    let eB = [p[0] + nx * hw, p[1] + ny * hw];

    brush.set("marker", Math.abs(Math.cos(tw)) < 0.35 ? PAL.cyanBright : PAL.earthUmber, 1.2);
    brush.line(eA[0], eA[1], eB[0], eB[1]);
    if (prevCrA) {
      brush.set("rotring", Math.sin(t * 18) > 0.3 ? PAL.chromeWhite : PAL.earthBlack, 0.55);
      brush.line(prevCrA[0], prevCrA[1], eA[0], eA[1]);
      brush.line(prevCrB[0], prevCrB[1], eB[0], eB[1]);
    }
    prevCrA = eA;
    prevCrB = eB;
  }

  // =========================================================================
  // 6. CRUMPLED PHOTOCOPIED FLYER TEXTURE, POCKET FOLDS & GRAINY SPRAY NOISE
  // =========================================================================
  function drawPaperCrease(x1, y1, x2, y2, strength = 1.0) {
    let segs = Math.max(6, Math.floor(Math.hypot(x2 - x1, y2 - y1) / 45));
    let pts = [[x1, y1]];
    for (let i = 1; i < segs; i++) {
      let t = i / segs;
      pts.push([
        lerp(x1, x2, t) + random(-9, 9) * strength,
        lerp(y1, y2, t) + random(-9, 9) * strength
      ]);
    }
    pts.push([x2, y2]);

    for (let i = 0; i < pts.length - 1; i++) {
      let a = pts[i], b = pts[i + 1];
      savedCreaseSegs.push({ a, b, strength });

      brush.set("charcoal", PAL.paperDark, 1.3 * strength);
      brush.line(a[0] + 3, a[1] + 4, b[0] + 3, b[1] + 4);
      brush.set("HB", PAL.earthUmber, 0.7 * strength);
      brush.line(a[0] + 2, a[1] + 2, b[0] + 2, b[1] + 2);

      brush.set("rotring", PAL.paperLight, 0.85 * strength);
      brush.line(a[0], a[1], b[0], b[1]);
      brush.set("2H", PAL.chromeWhite, 0.55 * strength);
      brush.line(a[0] - 1, a[1] - 1, b[0] - 1, b[1] - 1);
    }
  }

  drawPaperCrease(0, 612, 605, 592, 1.25);
  drawPaperCrease(605, 592, 1200, 624, 1.25);
  drawPaperCrease(588, 0, 605, 592, 1.15);
  drawPaperCrease(605, 592, 578, 1200, 1.15);

  const crumples = [
    [0, 210, 390, 410, 0.85],
    [390, 410, 605, 592, 0.75],
    [1200, 140, 810, 385, 0.9],
    [810, 385, 605, 592, 0.7],
    [0, 960, 410, 775, 0.9],
    [410, 775, 588, 880, 0.75],
    [1200, 940, 845, 790, 0.85],
    [845, 790, 578, 1200, 0.8],
    [210, 0, 390, 410, 0.65],
    [940, 0, 810, 385, 0.65],
    [140, 1200, 410, 775, 0.7],
    [0, 460, 265, 602, 0.65],
    [920, 610, 1200, 470, 0.65]
  ];
  for (let cr of crumples) {
    drawPaperCrease(cr[0], cr[1], cr[2], cr[3], cr[4]);
  }

  for (let i = 0; i < 190; i++) {
    let gx = random(20, 1180);
    let gy = random(20, 1180);
    let gLen = random(15, 75);
    let gAng = random(360);
    let nCol = (i % 3 === 0) ? PAL.violetDeep : (i % 3 === 1 ? PAL.paperLight : PAL.earthUmber);
    brush.set("spray", nCol, random(0.9, 1.9));
    brush.line(gx, gy, gx + cos(gAng) * gLen, gy + sin(gAng) * gLen);
  }

  const m = 22;
  drawPolyWash([[0, 0], [1200, 0], [1200, m], [0, m]], PAL.paper, 235);
  drawPolyWash([[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[0, 0], [m, 0], [m, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[1200 - m, 0], [1200, 0], [1200, 1200], [1200 - m, 1200]], PAL.paper, 235);

  brush.set("rotring", PAL.cyanElec, 0.75);
  brush.rect(m + 4, m - 3, 1200 - 2 * m, 1200 - 2 * m, "corner");
  brush.set("rotring", PAL.violetDeep, 0.95);
  brush.rect(m, m, 1200 - 2 * m, 1200 - 2 * m, "corner");

  for (let i = 0; i < 45; i++) {
    let edge = i % 4;
    let ex = edge === 0 ? random(m, 1200 - m) : (edge === 1 ? 1200 - m : (edge === 2 ? random(m, 1200 - m) : m));
    let ey = edge === 0 ? m : (edge === 1 ? random(m, 1200 - m) : (edge === 2 ? 1200 - m : random(m, 1200 - m)));
    brush.set("charcoal", i % 2 === 0 ? PAL.violetDeep : PAL.paperDark, random(0.8, 1.8));
    brush.line(ex + random(-12, 12), ey + random(-12, 12), ex + random(-25, 25), ey + random(-25, 25));
  }
}

function drawAnimatedFrame(f) {
  // Fast, bold motion underway immediately within the first 6 frames
  const motEase = Math.min(1.0, f / 2.0);
  const rotAngles = [
    -f * 13.5, // Left hub spins fast counter-clockwise (~81 deg in 6 frames, 324 deg by 1 s)
    -f * 19.0  // Right hub spins even faster (~114 deg in 6 frames, 456 deg by 1 s)
  ];

  const reels = [
    { lx: -146, ly: -14, packR: 134 },
    { lx: 146, ly: -14, packR: 94 }
  ];
  const rollers = [[-285, 162], [285, 162]];

  // =========================================================================
  // 0. STAMP ROTATED LIFTED REEL HUB & ROLLER PIXELS ON MAIN CANVAS
  // =========================================================================
  push();
  noStroke();
  imageMode(CENTER);
  for (let rIdx = 0; rIdx < 2; rIdx++) {
    let hc = cPt(reels[rIdx].lx, reels[rIdx].ly);
    push();
    translate(hc[0], hc[1]);
    rotate(rotAngles[rIdx]);
    image(hubImgs[rIdx], 0, 0);
    pop();

    let rc = cPt(rollers[rIdx][0], rollers[rIdx][1]);
    push();
    translate(rc[0], rc[1]);
    rotate(rotAngles[rIdx] * 1.6);
    image(rollerImgs[rIdx], 0, 0);
    pop();
  }
  pop();

  // =========================================================================
  // 1. WIREFRAME FLOOR SCROLLING TOWARD THE VIEWER (Covers Lower Half)
  // =========================================================================
  randomSeed(10200);
  noiseSeed(10200);

  // Scrolling marker bands across the floor (outside the cassette body)
  const floorScroll = (f * 0.14) % 1.0;
  for (let i = 0; i < 42; i++) {
    let t = ((i + f * 0.45) % 42) / 41;
    let d = Math.pow(t, 1.5) * 720;
    if (d < 16) continue;
    let x1 = 22, y1 = horizonY(x1) + d;
    let x2 = 1178, y2 = horizonY(x2) + d;
    let col = lerpColor(color(PAL.violetMid), color(PAL.earthUmber), t);
    brush.set("marker", col, 3.1);
    drawLineOutsideCassette(x1, y1, x2, y2);
  }

  // Receding perspective rays clipped outside the cassette body
  const numFloorRays = 54;
  for (let i = -numFloorRays; i <= numFloorRays; i++) {
    let u = i * 68;
    let bx = vpX + u * horCos - 650 * horSin;
    let by = vpY + u * horSin + 650 * horCos;
    let distFromCenter = Math.abs(i) / numFloorRays;
    let rayCol = distFromCenter < 0.45 ? PAL.cyanElec : lerpColor(color(PAL.cyanMuted), color(PAL.earthOchre), 0.5);
    brush.set("pen", rayCol, 0.55);
    drawLineOutsideCassette(vpX, vpY, bx, by);
    if (i % 2 === 0) {
      brush.set("rotring", PAL.cyanBright, 0.34);
      drawLineOutsideCassette(vpX, vpY, bx, by);
    }
  }

  // Scrolling horizontal depth grid lines moving toward the viewer
  const numDepthLines = 38;
  for (let i = 1; i <= numDepthLines; i++) {
    let t = ((i - 1 + floorScroll) % numDepthLines + 0.05) / numDepthLines;
    let d = Math.pow(t, 2.15) * 740;
    let x1 = 22;
    let y1 = horizonY(x1) + d / horCos;
    let x2 = 1178;
    let y2 = horizonY(x2) + d / horCos;

    let isPulse = (i % 5 === 0);
    let lineCol = isPulse
      ? PAL.chromeWhite
      : (t < 0.5
        ? lerpColor(color(PAL.cyanBright), color(PAL.cyanElec), t * 2)
        : lerpColor(color(PAL.cyanElec), color(PAL.earthSand), (t - 0.5) * 1.6));

    brush.set("rotring", lineCol, map(t, 0, 1, 0.4, isPulse ? 1.05 : 0.82));
    drawLineOutsideCassette(x1, y1, x2, y2);
  }

  // Restore cassette bottom drop-shadow smudge over the scrolling floor
  const extX = -16, extY = 38;
  let shadowBand = [
    cPt(-335 + extX * 1.0, 210 + extY * 1.0),
    cPt(335 + extX * 1.0, 210 + extY * 1.0),
    cPt(335 + extX * 2.2, 215 + extY * 2.2),
    cPt(-335 + extX * 2.2, 215 + extY * 2.2)
  ];
  drawPolyWash(shadowBand, PAL.violetDeep, 175);

  // =========================================================================
  // 2. WARPED GRID REFLECTION SLIDING ACROSS THE CHROME LABEL
  // =========================================================================
  randomSeed(14000);
  noiseSeed(14000);

  const labelPhaseX = f * 0.24;
  const labelPhaseY = f * 0.19;

  for (let ly = -172; ly <= 82; ly += 3.2) {
    let xLeft = -294;
    let xRight = 294;
    if (ly < -148) {
      let cut = -148 - ly;
      xLeft = -294 + cut;
      xRight = 294 - cut;
    }

    let spans = (ly > -70 && ly < 44) ? [[xLeft, -212], [212, xRight]] : [[xLeft, xRight]];

    for (let sp of spans) {
      let segs = 10;
      let dx = (sp[1] - sp[0]) / segs;
      for (let s = 0; s < segs; s++) {
        let lx1 = sp[0] + s * dx;
        let lx2 = lx1 + dx;
        let lxMid = (lx1 + lx2) * 0.5;

        // Sliding & undulating chrome horizon reflection
        let warpHorY = -42 + 16 * Math.sin(labelPhaseY) + 24 * Math.sin(lxMid * 0.009 + 0.4 + labelPhaseX) + 10 * Math.cos(lxMid * 0.021 - labelPhaseX * 1.3);
        let d = ly - warpHorY;

        let col, w = 1.25, bType = "marker";
        if (d < -75) {
          col = PAL.violetDeep;
        } else if (d < -38) {
          col = lerpColor(color(PAL.violetMid), color(PAL.cyanElec), (d + 75) / 37);
        } else if (d < -10) {
          col = lerpColor(color(PAL.cyanElec), color(PAL.cyanBright), (d + 38) / 28);
        } else if (d < 5) {
          col = PAL.chromeWhite;
          bType = "rotring";
          w = 1.05;
        } else if (d < 22) {
          col = d < 12 ? PAL.earthBlack : PAL.earthUmber;
        } else if (d < 55) {
          col = lerpColor(color(PAL.earthRust), color(PAL.earthOchre), (d - 22) / 33);
        } else if (d < 92) {
          col = lerpColor(color(PAL.earthOchre), color(PAL.paperLight), (d - 55) / 37);
        } else {
          col = lerpColor(color(PAL.paperLight), color(PAL.cyanMuted), Math.min(1, (d - 92) / 45));
        }

        let p1 = cPt(lx1, ly);
        let p2 = cPt(lx2, ly);
        brush.set(bType, col, w);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Sliding warped longitudinal & latitudinal grid curves on the chrome label
  const uSlide = (f * 0.032) % (2 / 14);
  const vSlide = (f * 0.045) % (2 / 9);

  for (let uIdx = -14; uIdx <= 14; uIdx++) {
    let u = uIdx / 14 + uSlide;
    if (u < -1 || u > 1) continue;
    let steps = 24;
    for (let s = 0; s < steps; s++) {
      let v1 = -1.1 + (s / steps) * 2.2;
      let v2 = -1.1 + ((s + 1) / steps) * 2.2;
      let a = warpLabelPt(u, v1);
      let b = warpLabelPt(u, v2);
      if (isInsideLabel(a[0], a[1]) && isInsideLabel(b[0], b[1])) {
        let p1 = cPt(a[0], a[1]);
        let p2 = cPt(b[0], b[1]);
        let gCol = a[1] < -40 ? PAL.chromeWhite : (uIdx % 2 === 0 ? PAL.cyanBright : PAL.violetDeep);
        brush.set("rotring", gCol, 0.52);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  for (let vIdx = -9; vIdx <= 9; vIdx++) {
    let v = vIdx / 9 + vSlide;
    if (v < -1 || v > 1) continue;
    let steps = 32;
    for (let s = 0; s < steps; s++) {
      let u1 = -1.1 + (s / steps) * 2.2;
      let u2 = -1.1 + ((s + 1) / steps) * 2.2;
      let a = warpLabelPt(u1, v);
      let b = warpLabelPt(u2, v);
      if (isInsideLabel(a[0], a[1]) && isInsideLabel(b[0], b[1])) {
        let p1 = cPt(a[0], a[1]);
        let p2 = cPt(b[0], b[1]);
        let gCol = v < 0 ? PAL.cyanBright : PAL.earthUmber;
        brush.set("rotring", gCol, 0.54);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // =========================================================================
  // 3. FAST-SPINNING REEL HUBS, TURNING SPOKES & ROTATING TAPE PACKS
  // =========================================================================
  for (let rIdx = 0; rIdx < 2; rIdx++) {
    let reel = reels[rIdx];
    let rotAngle = rotAngles[rIdx];
    randomSeed(18000 + rIdx * 500);
    noiseSeed(18000 + rIdx * 500);

    // Rotating concentric tape pack windings & bright specular wedges inside window
    for (let r = 56; r <= reel.packR; r += 3.2) {
      for (let s = 0; s < 48; s++) {
        let a1 = (s / 48) * 360;
        let a2 = ((s + 1) / 48) * 360;
        let lx1 = reel.lx + cos(a1) * r;
        let ly1 = reel.ly + sin(a1) * r;
        let lx2 = reel.lx + cos(a2) * r;
        let ly2 = reel.ly + sin(a2) * r;

        if (lx1 < -210 || lx1 > 210 || ly1 < -68 || ly1 > 42) continue;
        if (lx2 < -210 || lx2 > 210 || ly2 < -68 || ly2 > 42) continue;

        let rotA = a1 - rotAngle;
        let sheen = Math.pow(Math.abs(Math.cos((rotA - 38) * Math.PI / 180)), 4);
        let sheen2 = Math.pow(Math.abs(Math.cos((rotA - 128) * Math.PI / 180)), 6);
        let col = PAL.earthUmber;
        let w = 0.68;
        if (sheen > 0.58) {
          col = sheen > 0.84 ? PAL.chromeWhite : (sheen > 0.72 ? PAL.earthOchre : PAL.earthRust);
          w = 0.92;
        } else if (sheen2 > 0.68) {
          col = sheen2 > 0.86 ? PAL.cyanBright : PAL.cyanMuted;
          w = 0.75;
        } else if (Math.sin(rotA * 2 * Math.PI / 180) < -0.5) {
          col = PAL.earthBlack;
          w = 0.75;
        }
        let p1 = cPt(lx1, ly1);
        let p2 = cPt(lx2, ly2);
        brush.set("rotring", col, w);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // Crisp hub rings over the rotated lifted hub patch
    drawCassetteCircle(reel.lx, reel.ly, 55, PAL.chromeWhite, 0.75, "rotring", 36);
    drawCassetteCircle(reel.lx, reel.ly, 42, PAL.paperDark, 0.65, "rotring", 36);

    // 3 slotted flange cutouts + bold turning radial spokes on the white flange
    for (let k = 0; k < 3; k++) {
      let ka = k * 120 + 25 + rotAngle;
      let hx = reel.lx + cos(ka) * 48.5;
      let hy = reel.ly + sin(ka) * 48.5;
      fillCassetteCircle(hx, hy, 4.2, PAL.earthBlack, 240, 12);

      // Bold spoke bars across the flange so rotation reads unmistakably at a glance
      let spA1 = ka + 60;
      let s1 = cPt(reel.lx + cos(spA1) * 31, reel.ly + sin(spA1) * 31);
      let s2 = cPt(reel.lx + cos(spA1) * 54, reel.ly + sin(spA1) * 54);
      brush.set("marker", k === 0 ? PAL.cyanBright : PAL.earthUmber, 1.45);
      brush.line(s1[0], s1[1], s2[0], s2[1]);
      brush.set("rotring", PAL.chromeWhite, 0.75);
      brush.line(s1[0], s1[1], s2[0], s2[1]);
    }

    // 6 inward drive sprocket teeth turning with rotAngle
    for (let t = 0; t < 6; t++) {
      let ta = t * 60 + 12 + rotAngle;
      let t1 = cPt(reel.lx + cos(ta - 6) * 42, reel.ly + sin(ta - 6) * 42);
      let t2 = cPt(reel.lx + cos(ta + 6) * 42, reel.ly + sin(ta + 6) * 42);
      let t3 = cPt(reel.lx + cos(ta + 4) * 29, reel.ly + sin(ta + 4) * 29);
      let t4 = cPt(reel.lx + cos(ta - 4) * 29, reel.ly + sin(ta - 4) * 29);
      drawPolyWash([t1, t2, t3, t4], PAL.chromeWhite, 245);
      brush.set("rotring", PAL.earthBlack, 0.55);
      brush.line(t1[0], t1[1], t4[0], t4[1]);
      brush.line(t4[0], t4[1], t3[0], t3[1]);
      brush.line(t3[0], t3[1], t2[0], t2[1]);
    }
  }

  // Restore label outline, window outline, gauge ticks, and glass reflection bands over cassette
  let labelOutline = [cPt(-268, -174), cPt(268, -174), cPt(294, -148), cPt(294, 84), cPt(-294, 84), cPt(-294, -148)];
  for (let i = 0; i < labelOutline.length; i++) {
    let p1 = labelOutline[i];
    let p2 = labelOutline[(i + 1) % labelOutline.length];
    brush.set("rotring", PAL.earthBlack, 0.9);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  let winOutline = [cPt(-212, -70), cPt(212, -70), cPt(212, 44), cPt(-212, 44)];
  for (let i = 0; i < 4; i++) {
    let p1 = winOutline[i];
    let p2 = winOutline[(i + 1) % 4];
    brush.set("rotring", PAL.earthBlack, 1.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let p1In = cPt(i === 1 || i === 2 ? 210 : -210, i < 2 ? -68 : 42);
    let p2In = cPt((i + 1) % 4 === 1 || (i + 1) % 4 === 2 ? 210 : -210, (i + 1) % 4 < 2 ? -68 : 42);
    brush.set("rotring", PAL.chromeWhite, 0.65);
    brush.line(p1In[0], p1In[1], p2In[0], p2In[1]);
  }

  let scaleL = cPt(-65, -13), scaleR = cPt(65, -13);
  brush.set("rotring", PAL.chromeWhite, 0.55);
  brush.line(scaleL[0], scaleL[1], scaleR[0], scaleR[1]);
  for (let tx = -65; tx <= 65; tx += 13) {
    let th = (tx % 26 === 0) ? 9 : 5;
    let t1 = cPt(tx, -13 - th), t2 = cPt(tx, -13 + th);
    brush.set("rotring", PAL.chromeWhite, 0.5);
    brush.line(t1[0], t1[1], t2[0], t2[1]);
  }

  const glassBands = [
    [-250, -210, -330, -80, 3.2],
    [-110, -210, -290, 120, 4.0],
    [-95, -210, -275, 120, 2.2],
    [80, -70, -35, 110, 3.5],
    [220, -210, 40, 100, 2.8],
    [310, -140, 160, 210, 3.2]
  ];
  for (let gb of glassBands) {
    let p1 = cPt(gb[0], gb[1]), p2 = cPt(gb[2], gb[3]);
    brush.set("marker", PAL.chromeWhite, gb[4]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("rotring", PAL.cyanBright, 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // =========================================================================
  // 4. SPILLED TAPE RIBBON FLUTTERING & SPOOLING OUT WITH SLIDING HIGHLIGHTS
  // =========================================================================
  const exitLeft = cPt(-105, 208);
  const exitLeftOut = cPt(-115, 255);
  const enterRightOut = cPt(115, 255);
  const enterRight = cPt(105, 208);

  const baseTapeCtrl = [
    cPt(-105, 190),
    exitLeft,
    exitLeftOut,
    [430, 690],
    [230, 740],
    [145, 895],
    [265, 1055],
    [515, 1025],
    [685, 845],
    [520, 705],
    [355, 815],
    [465, 985],
    [765, 1085],
    [1035, 995],
    [1065, 805],
    [875, 695],
    [720, 785],
    [825, 920],
    [945, 835],
    [805, 635],
    enterRightOut,
    enterRight,
    cPt(105, 190)
  ];

  // Displace control points 3..19 so the ribbon loops flutter and spool outward
  const animTapeCtrl = [];
  const spoolAmount = f * 1.45;
  for (let k = 0; k < baseTapeCtrl.length; k++) {
    let pt = baseTapeCtrl[k];
    if (k < 3 || k > 19) {
      animTapeCtrl.push([pt[0], pt[1]]);
    } else {
      let rx = pt[0] - 600;
      let ry = pt[1] - 650;
      let rLen = Math.hypot(rx, ry) || 1;
      let env = Math.sin(((k - 2) / 18) * Math.PI);
      // Spooling expansion outward/downward + fast travelling flutter wave
      let expandX = (rx / rLen) * spoolAmount * (0.55 + 0.45 * env);
      let expandY = (ry / rLen) * spoolAmount * (0.65 + 0.35 * env) + spoolAmount * 0.25;
      let flutX = 24 * motEase * Math.sin(f * 0.36 - k * 0.75);
      let flutY = 20 * motEase * Math.cos(f * 0.42 - k * 0.65);
      animTapeCtrl.push([
        constrain(pt[0] + expandX + flutX, 55, 1145),
        constrain(pt[1] + expandY + flutY, 610, 1150)
      ]);
    }
  }

  const ribbonSteps = 560;
  const rPts = [];
  for (let i = 0; i <= ribbonSteps; i++) {
    let t = i / ribbonSteps;
    rPts.push(evalCatmullRom(animTapeCtrl, t));
  }

  // Smudgy spray & charcoal halo moving with the fluttering ribbon
  randomSeed(25000);
  noiseSeed(25000);
  for (let i = 0; i < ribbonSteps; i += 4) {
    let p = rPts[i];
    let pNext = rPts[Math.min(ribbonSteps, i + 4)];
    brush.set("spray", i % 8 === 0 ? PAL.violetDeep : PAL.earthBlack, random(1.8, 2.8));
    let ang = random(360);
    let rad = random(18, 44);
    brush.line(p[0] - cos(ang) * rad * 0.5, p[1] - sin(ang) * rad * 0.5, p[0] + cos(ang) * rad, p[1] + sin(ang) * rad);

    if (i % 8 === 0) {
      brush.set("spray", (i % 16 === 0) ? PAL.cyanElec : PAL.earthOchre, 1.5);
      brush.line(p[0] + random(-16, 16), p[1] + random(-16, 16), pNext[0] + random(-16, 16), pNext[1] + random(-16, 16));
    }
    brush.set("charcoal", PAL.violetDeep, 2.4);
    brush.line(p[0] + 6, p[1] + 10, pNext[0] + 6, pNext[1] + 10);
  }

  // Shiny magnetic tape ribbon with fast-sliding highlights & turning 3D twists
  const baseHalfWidth = 17.5;
  const twistFlow = f * 0.16;
  const highlightSlide = f * 0.32;
  let prevEdgeA = null;
  let prevEdgeB = null;

  randomSeed(28000);
  noiseSeed(28000);
  for (let i = 0; i <= ribbonSteps; i++) {
    let t = i / ribbonSteps;
    let p = rPts[i];
    let pPrev = rPts[Math.max(0, i - 1)];
    let pNext = rPts[Math.min(ribbonSteps, i + 1)];

    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let tLen = Math.hypot(tx, ty) || 1;
    tx /= tLen;
    ty /= tLen;

    let nx = -ty;
    let ny = tx;

    let twist = t * Math.PI * 7.4 - twistFlow + 0.85 * Math.sin(t * Math.PI * 11 - twistFlow * 0.7) + 0.4 * Math.cos(t * Math.PI * 19);
    let endTaper = (t < 0.04) ? map(t, 0, 0.04, 0.45, 1) : ((t > 0.96) ? map(t, 0.96, 1, 1, 0.45) : 1);
    let hw = baseHalfWidth * endTaper;

    let cosTw = Math.cos(twist);
    let sinTw = Math.sin(twist);

    let wx = (nx * cosTw + tx * 0.24 * sinTw) * hw;
    let wy = (ny * cosTw + ty * 0.24 * sinTw) * hw;

    let edgeA = [p[0] - wx, p[1] - wy];
    let edgeB = [p[0] + wx, p[1] + wy];

    let surfAngle = Math.atan2(ny, nx) + twist * 0.85 - highlightSlide;
    let spec1 = Math.pow(0.5 + 0.5 * Math.cos(surfAngle * 2.0 - 0.9), 4);
    let spec2 = Math.pow(0.5 + 0.5 * Math.sin(surfAngle * 3.0 + 1.4), 8);

    let bodyCol, highlightCol;
    if (spec2 > 0.72) {
      bodyCol = PAL.cyanBright;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.78) {
      bodyCol = PAL.earthOchre;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.52) {
      bodyCol = PAL.earthRust;
      highlightCol = PAL.cyanElec;
    } else if (spec1 < 0.16) {
      bodyCol = PAL.earthBlack;
      highlightCol = PAL.violetMid;
    } else {
      bodyCol = PAL.earthUmber;
      highlightCol = PAL.earthOchre;
    }

    brush.set("marker", bodyCol, 1.45);
    brush.line(edgeA[0], edgeA[1], edgeB[0], edgeB[1]);

    if (spec2 > 0.55 || spec1 > 0.65 || i % 2 === 0) {
      let hFrac1 = (spec2 > 0.6) ? 0.1 : 0.25;
      let hFrac2 = (spec2 > 0.6) ? 0.9 : 0.75;
      let hx1 = lerp(edgeA[0], edgeB[0], hFrac1);
      let hy1 = lerp(edgeA[1], edgeB[1], hFrac1);
      let hx2 = lerp(edgeA[0], edgeB[0], hFrac2);
      let hy2 = lerp(edgeA[1], edgeB[1], hFrac2);
      brush.set("rotring", highlightCol, (spec2 > 0.72 || spec1 > 0.82) ? 0.95 : 0.55);
      brush.line(hx1, hy1, hx2, hy2);
    }

    if (prevEdgeA && prevEdgeB) {
      let isPinch = Math.abs(cosTw) < 0.35;
      let edgeColA = (isPinch || spec2 > 0.55) ? PAL.chromeWhite : (cosTw > 0 ? PAL.cyanBright : PAL.earthBlack);
      let edgeColB = (isPinch || spec1 > 0.7) ? PAL.chromeWhite : (cosTw < 0 ? PAL.earthOchre : PAL.earthBlack);

      brush.set("rotring", edgeColA, isPinch ? 0.9 : 0.65);
      brush.line(prevEdgeA[0], prevEdgeA[1], edgeA[0], edgeA[1]);

      brush.set("rotring", edgeColB, isPinch ? 0.9 : 0.65);
      brush.line(prevEdgeB[0], prevEdgeB[1], edgeB[0], edgeB[1]);
    }

    prevEdgeA = edgeA;
    prevEdgeB = edgeB;
  }

  // Secondary center crinkle loop fluttering & spooling out
  const crinkleCtrl = [
    cPt(-35, 204),
    cPt(-38, 222),
    [545 + 16 * Math.sin(f * 0.4), 705 + f * 0.95],
    [605 + 20 * Math.cos(f * 0.36), 765 + f * 1.25],
    [655 - 16 * Math.sin(f * 0.42), 705 + f * 0.95],
    cPt(38, 222),
    cPt(35, 204)
  ];
  let prevCrA = null, prevCrB = null;
  for (let i = 0; i <= 90; i++) {
    let t = i / 90;
    let p = evalCatmullRom(crinkleCtrl, t);
    let pNext = evalCatmullRom(crinkleCtrl, Math.min(1, t + 0.01));
    let tx = pNext[0] - p[0], ty = pNext[1] - p[1];
    let tl = Math.hypot(tx, ty) || 1;
    let nx = -ty / tl, ny = tx / tl;
    let tw = t * Math.PI * 3.2 - twistFlow * 1.2;
    let hw = 13 * Math.cos(tw);
    let eA = [p[0] - nx * hw, p[1] - ny * hw];
    let eB = [p[0] + nx * hw, p[1] + ny * hw];

    brush.set("marker", Math.abs(Math.cos(tw)) < 0.35 ? PAL.cyanBright : PAL.earthUmber, 1.25);
    brush.line(eA[0], eA[1], eB[0], eB[1]);
    if (prevCrA) {
      brush.set("rotring", Math.sin(t * 18 - highlightSlide * 1.5) > 0.3 ? PAL.chromeWhite : PAL.earthBlack, 0.6);
      brush.line(prevCrA[0], prevCrA[1], eA[0], eA[1]);
      brush.line(prevCrB[0], prevCrB[1], eB[0], eB[1]);
    }
    prevCrA = eA;
    prevCrB = eB;
  }

  // =========================================================================
  // 5. RESTORE FOREGROUND PAPER CREASES & BORDER OVER ANIMATED REGIONS
  // =========================================================================
  randomSeed(35000);
  noiseSeed(35000);
  for (let cIdx = 0; cIdx < savedCreaseSegs.length; cIdx++) {
    let seg = savedCreaseSegs[cIdx];
    let a = seg.a, b = seg.b, strength = seg.strength;
    let midY = (a[1] + b[1]) * 0.5;
    let midC = worldToCas((a[0] + b[0]) * 0.5, midY);
    let onFloor = midY > horizonY((a[0] + b[0]) * 0.5) - 15;
    let onCas = Math.abs(midC[0]) < 320 && midC[1] > -190 && midC[1] < 220;
    if (!onFloor && !onCas) continue;

    brush.set("charcoal", PAL.paperDark, 1.3 * strength);
    brush.line(a[0] + 3, a[1] + 4, b[0] + 3, b[1] + 4);
    brush.set("HB", PAL.earthUmber, 0.7 * strength);
    brush.line(a[0] + 2, a[1] + 2, b[0] + 2, b[1] + 2);
    brush.set("rotring", PAL.paperLight, 0.85 * strength);
    brush.line(a[0], a[1], b[0], b[1]);
    brush.set("2H", PAL.chromeWhite, 0.55 * strength);
    brush.line(a[0] - 1, a[1] - 1, b[0] - 1, b[1] - 1);
  }

  // Restore lower flyer border over scrolling floor & expanding tape loops
  const m = 22;
  drawPolyWash([[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[0, 450], [m, 450], [m, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[1200 - m, 450], [1200, 450], [1200, 1200], [1200 - m, 1200]], PAL.paper, 235);
  brush.set("rotring", PAL.cyanElec, 0.75);
  brush.line(m + 4, 1200 - m - 3, 1200 - m + 4, 1200 - m - 3);
  brush.set("rotring", PAL.violetDeep, 0.95);
  brush.line(m, 1200 - m, 1200 - m, 1200 - m);
}

function draw() {
  translate(-width / 2, -height / 2);
  if (frameCount > TOTAL_FRAMES) return;

  if (frameCount === 1) {
    paintStill();
    stillImg = get();

    // Lift circular pixel patches for the two reel hubs and two corner rollers
    let hc0 = cPt(-146, -14);
    let hc1 = cPt(146, -14);
    hubImgs[0] = extractCircularPatch(stillImg, hc0[0], hc0[1], 56);
    hubImgs[1] = extractCircularPatch(stillImg, hc1[0], hc1[1], 56);

    let rc0 = cPt(-285, 162);
    let rc1 = cPt(285, 162);
    rollerImgs[0] = extractCircularPatch(stillImg, rc0[0], rc0[1], 24);
    rollerImgs[1] = extractCircularPatch(stillImg, rc1[0], rc1[1], 24);
    return;
  }

  background(PAL.paper);
  push();
  noStroke();
  image(stillImg, 0, 0, width, height);
  pop();

  drawAnimatedFrame(frameCount - 1);
}

