// Color interpolation with warmth & specular boost
function getTintedHex(lum, warmth, spec, tint, quantSteps = 0) {
  let l = constrain(lum, 0, 1);
  if (quantSteps > 0) {
    l = Math.round(l * quantSteps) / quantSteps;
  }
  // Specular boost pushes toward highest stops
  l = constrain(l + spec * 0.16, 0, 1);

  let ramp = PALETTES[tint] || PALETTES.white;
  let scaled = l * (ramp.length - 1);
  let idx = Math.floor(scaled);
  let frac = scaled - idx;
  if (idx >= ramp.length - 1) {
    idx = ramp.length - 2;
    frac = 1.0;
  }
  let c0 = ramp[idx];
  let c1 = ramp[idx + 1];
  let r = c0[0] + (c1[0] - c0[0]) * frac;
  let g = c0[1] + (c1[1] - c0[1]) * frac;
  let b = c0[2] + (c1[2] - c0[2]) * frac;

  // Warmth adjustment (subtle golden-ochre warmth in table reflections, cool crispness in sky)
  if (tint === "white") {
    r = constrain(r + warmth * 12, 0, 255);
    g = constrain(g + warmth * 4, 0, 255);
    b = constrain(b - warmth * 10, 0, 255);
  } else if (tint === "blue") {
    r = constrain(r + warmth * 8, 0, 255);
    g = constrain(g + warmth * 6, 0, 255);
  }

  let ri = Math.round(constrain(r, 0, 255));
  let gi = Math.round(constrain(g, 0, 255));
  let bi = Math.round(constrain(b, 0, 255));
  return (
    "#" +
    ri.toString(16).padStart(2, "0") +
    gi.toString(16).padStart(2, "0") +
    bi.toString(16).padStart(2, "0")
  );
}

