// Room reflection environment lookup given 3D unit surface normal (Nx, Ny, Nz)
function sampleRoomEnvironment(Nx, Ny, Nz, wx, wy, isSpout = false) {
  // Reflected ray with subtle perspective offset
  let vx = (wx - 720) * 0.00022;
  let vy = (wy - 680) * 0.00022;
  let rx = vx - 2 * Nz * Nx;
  let ry = vy - 2 * Nz * Ny;
  let rz = 1 - 2 * Nz * Nz;

  // Spherical coordinates in virtual studio room
  let theta = Math.atan2(rx, -rz); // -PI..PI horizontal azimuth
  let phi = -Ny + 0.12 * (1 - Nz) * (Nx * 0.3); // vertical elevation (+ is up toward windows/ceiling, - is down)

  // Liquid distortion ripple characteristic of hand-spun polished metal
  let liquidWave =
    0.016 * Math.sin(theta * 4.0 + phi * 5.0) +
    0.007 * Math.cos(theta * 9.0 - phi * 6.0);
  let pW = phi + liquidWave;
  let tW = theta + liquidWave * 0.6;

  let lum = 0.5;
  let warmth = 0.0;
  let spec = 0.0;

  // 1. UPPER HEMISPHERE: STUDIO WINDOWS, MULLIONS & CEILING (pW > 0.05)
  if (pW > 0.05) {
    // Base studio ceiling & upper wall gradient
    lum = 0.56 + 0.22 * Math.sin(constrain((pW - 0.05) / 0.85, 0, 1) * Math.PI);
    warmth = -0.15;

    // MAIN UPPER-LEFT 6-PANE STUDIO WINDOW: theta in [-1.42, -0.16], phi in [0.08, 0.66]
    if (tW > -1.42 && tW < -0.16 && pW > 0.08 && pW < 0.66) {
      // Soft window frame edge
      let dFrame = Math.min(tW - -1.42, -0.16 - tW, (pW - 0.08) * 1.6, (0.66 - pW) * 1.6);
      if (dFrame < 0.032) {
        lum = 0.18; // Outer dark window frame
      } else {
        // Intense studio sky / softbox glow
        lum = 0.95 + 0.05 * Math.sin(((tW + 1.42) / 1.26) * Math.PI);
        spec = 0.92;
        warmth = -0.25;

        // Venetian blind slats near top of window (pW > 0.52)
        if (pW > 0.52) {
          let slat = Math.sin((pW - 0.52) * 145);
          if (slat > 0.25) {
            lum = 0.24;
            spec = 0.0;
          }
        }

        // 2 Vertical mullions at tW = -0.98 and tW = -0.56
        let dm1 = Math.abs(tW - -0.98);
        let dm2 = Math.abs(tW - -0.56);
        // 1 Horizontal crossbar at pW = 0.34
        let dmH = Math.abs(pW - 0.34);

        if (dm1 < 0.024 || dm2 < 0.024 || dmH < 0.017) {
          lum = 0.14;
          spec = 0.0;
          warmth = 0.1;
        } else if (dm1 < 0.042 || dm2 < 0.042 || dmH < 0.030) {
          // Bright grazing diffraction edge right beside mullion
          lum = 1.0;
          spec = 1.0;
        }
      }
    }

    // SECONDARY UPPER-RIGHT STUDIO WINDOW: theta in [0.34, 1.06], phi in [0.15, 0.56]
    if (tW > 0.34 && tW < 1.06 && pW > 0.15 && pW < 0.56) {
      let dFrame = Math.min(tW - 0.34, 1.06 - tW, (pW - 0.15) * 1.6, (0.56 - pW) * 1.6);
      if (dFrame < 0.028) {
        lum = 0.20;
      } else {
        lum = 0.90;
        spec = 0.78;
        warmth = -0.1;
        let dmV = Math.abs(tW - 0.70);
        let dmH = Math.abs(pW - 0.35);
        if (dmV < 0.022 || dmH < 0.016) {
          lum = 0.18;
          spec = 0.0;
        } else if (dmV < 0.038 || dmH < 0.028) {
          lum = 0.98;
          spec = 0.95;
        }
      }
    }

    // Self-reflection of overhead arched handle & central knob on upper lid/shoulder (pW > 0.62)
    if (!isSpout && pW > 0.62 && Math.abs(tW) < 0.95) {
      let handleBand = Math.abs(pW - (0.74 - 0.12 * tW * tW));
      if (handleBand < 0.055) {
        lum = 0.11;
        spec = 0.0;
      }
    }
  }

  // 2. EQUATORIAL ROOM INTERIOR BAND: pW in [-0.23, 0.05]
  else if (pW >= -0.23) {
    // Deep architectural interior shadow band
    let bandPos = (pW - -0.23) / 0.28; // 0 at table horizon, 1 at ceiling edge
    lum = 0.06 + 0.07 * Math.sin(bandPos * Math.PI);
    warmth = 0.25;

    // Reflected doorway / warm recessed alcove near center-left (tW in [-0.26, 0.22])
    if (tW > -0.26 && tW < 0.22 && bandPos < 0.85) {
      lum = 0.26 + 0.08 * Math.cos(((tW + 0.02) / 0.24) * Math.PI * 0.5);
      warmth = 0.65;
      // Dark doorframe verticals
      if (Math.abs(tW - -0.24) < 0.025 || Math.abs(tW - 0.20) < 0.025) {
        lum = 0.04;
      }
    }

    // Reflected vertical studio light stand / easel masts
    if (Math.abs(tW - -0.64) < 0.028 || Math.abs(tW - 0.56) < 0.026) {
      lum = 0.03;
    } else if (Math.abs(tW - -0.605) < 0.016 || Math.abs(tW - 0.59) < 0.016) {
      lum = 0.62; // metallic mast highlight in reflection
      spec = 0.4;
    }

    // Reflected framed canvas on right studio wall (tW in [0.72, 1.18], bandPos in [0.22, 0.78])
    if (tW > 0.72 && tW < 1.18 && bandPos > 0.22 && bandPos > 0.78) {
      lum = 0.34;
      warmth = 0.7;
      if (tW < 0.76 || tW > 1.14 || bandPos < 0.28 || bandPos > 0.72) {
        lum = 0.07; // picture frame
      }
    }

    // Self-reflection of the gooseneck spout on the left cheek of the kettle!
    if (!isSpout && tW < -0.88 && tW > -1.48) {
      let spoutRefCurve = -0.18 + 0.38 * Math.pow((-tW - 0.88) / 0.6, 1.2);
      let dSpoutRef = Math.abs(pW - spoutRefCurve);
      if (dSpoutRef < 0.065) {
        lum = dSpoutRef < 0.025 ? 0.82 : 0.05;
        spec = dSpoutRef < 0.025 ? 0.6 : 0.0;
      }
    }
  }

  // 3. LOWER HEMISPHERE: ILLUMINATED STUDIO TABLETOP & CONTACT SHADOW (pW < -0.23)
  else if (pW >= -0.64) {
    // Sharp jump at pW = -0.23 where the studio tabletop meets the dark room wall!
    let tablePos = (-0.23 - pW) / 0.41; // 0 at far table edge, 1 near base under kettle
    lum = 0.84 - 0.34 * Math.pow(tablePos, 0.85);
    warmth = 0.75;
    spec = 0.22 * (1 - tablePos);

    // Secondary reflection of the bright left studio window on the tabletop surface
    if (tW > -1.05 && tW < -0.20 && tablePos > 0.06 && tablePos < 0.58) {
      lum = Math.min(0.95, lum + 0.16);
      spec = 0.55;
    }

    // Subtle tabletop wood/linen grain lines in reflection
    let grain = 0.035 * Math.sin(pW * 95 + tW * 12);
    lum += grain;
  }

  // 4. DEEPEST BELLY TUCK: REFLECTION OF DARK CONTACT SHADOW UNDER KETTLE (pW < -0.64)
  else {
    let underPos = constrain((-0.64 - pW) / 0.25, 0, 1);
    lum = 0.14 - 0.09 * underPos;
    warmth = 0.2;
  }

  // Grazing Fresnel rim sheen near silhouette edge (Nz -> 0)
  if (Nz < 0.34) {
    let fresnel = (0.34 - Nz) / 0.34;
    let rimStripe = Math.sin(fresnel * Math.PI * 3.0);
    lum = constrain(lum + 0.28 * rimStripe * fresnel, 0.05, 0.99);
    if (rimStripe > 0.4) spec = Math.max(spec, 0.65);
  }

  return { lum: constrain(lum, 0, 1), warmth, spec };
}

// Master scene evaluator at any canvas coordinate (x, y)
function evaluateScene(x, y) {
  // 1. FINIAL KNOB AT TOP OF LID (cx = K_CX, cy = 464)
  let kdx = (x - K_CX) / 62;
  let kdyTop = (y - 455) / 14;
  let kdyDisk = (y - 466) / 21;
  if (Math.abs(x - K_CX) < 66 && y >= 438 && y <= 504) {
    // Top polished chrome cap disc on knob
    let rCap = Math.hypot((x - K_CX) / 34, (y - 454) / 10.5);
    if (rCap <= 1.0) {
      let nx = ((x - K_CX) / 34) * 0.55;
      let ny = -0.78 + ((y - 454) / 10.5) * 0.25;
      let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y);
      if (rCap > 0.85) env.lum = 0.96; // bright bevel rim
      return { part: "knob_cap", ...env };
    }
    // Satin-black sculpted phenolic knob disk
    let rDisk = Math.hypot(kdx, kdyDisk);
    if (rDisk <= 1.0 && y <= 487) {
      let angle = Math.atan2(kdyDisk, kdx);
      // Smooth studio highlight on left curve of satin black knob
      let sheen = Math.exp(-Math.pow(( kdx + 0.48 ) / 0.32, 2)) * (1 - Math.abs(kdyDisk) * 0.5);
      let rimLight = rDisk > 0.88 && kdyDisk < 0 ? 0.28 : 0.0;
      let lum = constrain(0.06 + 0.34 * sheen + rimLight, 0.04, 0.55);
      return { part: "knob_disk", lum, warmth: 0.1, spec: sheen * 0.3 };
    }
    // Chrome stem neck below knob disk
    if (Math.abs(x - K_CX) <= 27 && y >= 480 && y <= 503) {
      let uStem = (x - K_CX) / 27;
      let nx = uStem;
      let ny = 0.1;
      let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y);
      return { part: "knob_stem", ...env };
    }
  }

  // 2. ARCHED HANDLE & CHROME SHOULDER BRACKETS (upper region y < 565)
  if (y >= 225 && y <= 565 && x >= 490 && x <= 1005) {
    // Check arch handle curve t in [0, 1]
    let bestT = -1;
    let bestDist = 999;
    let steps = 48;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = getHandleArchPoint(t);
      let d = Math.hypot(x - p.x, y - p.y);
      if (d < bestDist) {
        bestDist = d;
        bestT = t;
      }
    }
    // Refine t locally
    for (let step = 0.01; step >= 0.0015; step *= 0.4) {
      for (let dir of [-1, 1]) {
        let tc = constrain(bestT + dir * step, 0, 1);
        let p = getHandleArchPoint(tc);
        let d = Math.hypot(x - p.x, y - p.y);
        if (d < bestDist) {
          bestDist = d;
          bestT = tc;
        }
      }
    }
    let hRad = getHandleRadius(bestT);
    if (bestDist <= hRad) {
      let hp = getHandleArchPoint(bestT);
      let ht = getHandleArchTangent(bestT);
      // Signed cross-sectional position s in [-1, 1] (-1 is top/outer arch, +1 is bottom/inner arch)
      let s = ((x - hp.x) * ht.nx + (y - hp.y) * ht.ny) / hRad;
      s = constrain(s, -1, 1);

      // Chrome ferrule rings at ends of central grip (bestT near 0.21 or 0.79)
      let isFerrule = Math.abs(bestT - 0.21) < 0.018 || Math.abs(bestT - 0.79) < 0.018;
      let isGrip = bestT > 0.21 && bestT < 0.79 && !isFerrule;

      if (isGrip) {
        // Contoured dark ergonomic handle grip with crisp studio top-edge highlight
        let topSheen = Math.exp(-Math.pow((s + 0.56) / 0.24, 2));
        let underRef = s > 0.55 ? 0.16 * ((s - 0.55) / 0.45) : 0;
        let lum = constrain(0.05 + 0.52 * topSheen + underRef, 0.04, 0.68);
        return { part: "handle_grip", lum, warmth: 0.05, spec: topSheen * 0.45 };
      } else {
        // Mirror-polished chrome handle struts & ferrules
        let nx = ht.nx * s + ht.tx * 0.15;
        let ny = ht.ny * s + ht.ty * 0.15;
        let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
        let env = sampleRoomEnvironment(nx, ny, nz, x, y);
        if (isFerrule) env.lum = constrain(env.lum + 0.18, 0.1, 1.0);
        return { part: "handle_chrome", ...env };
      }
    }

    // Check Left & Right Chrome Mounting Brackets on shoulders
    // Left bracket: from (536, 495) to (568, 544)
    // Right bracket: from (960, 495) to (928, 544)
    for (let side of [-1, 1]) {
      let bx0 = side < 0 ? 536 : 960;
      let by0 = 492;
      let bx1 = side < 0 ? 570 : 926;
      let by1 = 544;
      let dxB = bx1 - bx0;
      let dyB = by1 - by0;
      let lenB = Math.hypot(dxB, dyB);
      let proj = ((x - bx0) * dxB + (y - by0) * dyB) / (lenB * lenB);
      if (proj >= 0 && proj <= 1) {
        let cxB = bx0 + proj * dxB;
        let cyB = by0 + proj * dyB;
        let radB = 15 + 9 * proj + (proj > 0.82 ? 5 : 0); // flanged base collar
        let perp = ((x - cxB) * (dyB / lenB) - (y - cyB) * (dxB / lenB)) / radB;
        if (Math.abs(perp) <= 1.0) {
          let nx = perp * 0.85;
          let ny = -0.35 + 0.3 * proj;
          let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
          let env = sampleRoomEnvironment(nx, ny, nz, x, y);
          return { part: "bracket", ...env };
        }
      }
    }
  }

  // 3. STEPPED CHROME LID AT TOP OF KETTLE BODY (cx = K_CX, cy = K_TOP_Y = 516)
  let ldx = (x - K_CX) / 214;
  let ldy = (y - K_TOP_Y) / 46;
  let rLid = Math.hypot(ldx, ldy);
  if (rLid <= 1.02) {
    // Recessed dark lid seam at rLid in [0.83, 0.87]
    if (rLid >= 0.83 && rLid <= 0.87) {
      return { part: "lid_seam", lum: 0.05, warmth: 0.1, spec: 0.0 };
    }
    // Outer body collar torus bevel (rLid in [0.87, 1.02])
    if (rLid > 0.87) {
      let bevel = (rLid - 0.945) / 0.075; // -1 inner edge to +1 outer shoulder edge
      let nx = ldx * (0.45 + 0.35 * bevel);
      let ny = -0.72 * Math.cos(bevel * 1.3) + ldy * 0.35;
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y);
      return { part: "lid_rim", ...env };
    }
    // Inner stepped lid ring (rLid in [0.71, 0.83])
    if (rLid >= 0.71) {
      let stepWave = Math.sin(((rLid - 0.71) / 0.12) * Math.PI * 2.0);
      let nx = ldx * 0.5 + 0.25 * stepWave * ldx;
      let ny = -0.70 + 0.45 * stepWave;
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y);
      return { part: "lid_step", ...env };
    }
    // Central domed chrome lid surface (rLid < 0.71)
    let nx = ldx * 0.42;
    let ny = -0.78 + ldy * 0.24;
    let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
    let env = sampleRoomEnvironment(nx, ny, nz, x, y);
    // Reflection of black phenolic knob on the lid surface directly below knob
    let rKnobRef = Math.hypot((x - K_CX) / 56, (y - 504) / 18);
    if (rKnobRef < 1.0) {
      env.lum = lerp(0.08, env.lum, Math.pow(rKnobRef, 1.6));
      env.spec *= rKnobRef;
    }
    return { part: "lid_dome", ...env };
  }

  // 4. GOOSENECK SPOUT (left side of kettle: x in [185, 505], y in [470, 865])
  if (x >= 185 && x <= 495 && y >= 470 && y <= 865) {
    // Check elliptical beveled spout mouth opening at tip (220, 496)
    let tipAngle = -34 * (Math.PI / 180);
    let tx = (x - 221) * Math.cos(tipAngle) - (y - 496) * Math.sin(tipAngle);
    let ty = (x - 221) * Math.sin(tipAngle) + (y - 496) * Math.cos(tipAngle);
    let rMouth = Math.hypot(tx / 23, ty / 8.5);
    if (rMouth <= 1.16) {
      if (rMouth >= 0.86) {
        // Gleaming beveled chrome lip rim of spout mouth
        return { part: "spout_lip", lum: 0.97, warmth: -0.1, spec: 0.95 };
      } else {
        // Deep dark interior throat of spout
        let throatLum = 0.04 + 0.14 * (1 - rMouth) + (tx > 0 ? 0.08 : 0);
        return { part: "spout_throat", lum: throatLum, warmth: 0.2, spec: 0.0 };
      }
    }

    // Closest point on gooseneck Bezier spine
    let bestT = -1;
    let bestDist = 999;
    let steps = 42;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = getSpoutPoint(t);
      let d = Math.hypot(x - p.x, y - p.y);
      if (d < bestDist) {
        bestDist = d;
        bestT = t;
      }
    }
    for (let step = 0.012; step >= 0.0015; step *= 0.4) {
      for (let dir of [-1, 1]) {
        let tc = constrain(bestT + dir * step, 0, 1);
        let p = getSpoutPoint(tc);
        let d = Math.hypot(x - p.x, y - p.y);
        if (d < bestDist) {
          bestDist = d;
          bestT = tc;
        }
      }
    }
    let sRad = getSpoutRadius(bestT);
    if (bestDist <= sRad && bestT <= 0.985) {
      let sp = getSpoutPoint(bestT);
      let st = getSpoutTangent(bestT);
      let s = ((x - sp.x) * st.nx + (y - sp.y) * st.ny) / sRad;
      s = constrain(s, -1, 1);

      // Welded chrome collar bead where spout joins kettle body (bestT < 0.085)
      let collarWave = bestT < 0.09 ? 0.32 * Math.sin((bestT / 0.09) * Math.PI * 2.0) : 0;

      // Cylindrical tube normal mapped to world space
      let nx = st.nx * s * 0.88 + st.tx * (0.18 + collarWave);
      let ny = st.ny * s * 0.88 + st.ty * (0.18 + collarWave);
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y, true);

      // Accentuate the liquid S-curve tubular highlight & core contrast along the spout
      if (s > -0.68 && s < -0.34) {
        let ridge = Math.exp(-Math.pow((s + 0.51) / 0.12, 2));
        env.lum = Math.max(env.lum, 0.92 + 0.08 * ridge);
        env.spec = Math.max(env.spec, 0.9 * ridge);
      } else if (s > -0.18 && s < 0.22) {
        let core = Math.exp(-Math.pow((s - 0.02) / 0.14, 2));
        env.lum = lerp(env.lum, 0.07, 0.78 * core);
        env.spec *= 1 - core;
      } else if (s > 0.35 && s < 0.78) {
        let underGlow = Math.exp(-Math.pow((s - 0.56) / 0.16, 2));
        env.lum = Math.max(env.lum, 0.74 * underGlow);
        env.warmth = 0.65;
      }
      return { part: "spout", ...env };
    }
  }

  // 5. MAIN BULBOUS CHROME KETTLE BODY
  if (y >= K_TOP_Y - 10 && y <= 1060 && x >= 360 && x <= 1135) {
    // Iterative inverse mapping to find parametric (u, v) on the kettle dome
    let v = constrain((y - K_TOP_Y) / K_SPAN_Y, 0, 1);
    let u = 0;
    for (let iter = 0; iter < 4; iter++) {
      let rx = getBodyRx(v);
      u = (x - K_CX) / rx;
      if (Math.abs(u) <= 1.05) {
        let sag = getBodySag(v) * Math.sqrt(Math.max(0, 1 - constrain(u * u, 0, 1)));
        v = (y - sag - K_TOP_Y) / K_SPAN_Y;
      }
    }
    let rxFinal = getBodyRx(v);
    u = (x - K_CX) / rxFinal;

    if (v >= 0.0 && v <= 1.0 && Math.abs(u) <= 1.0) {
      let ny = getBodySlopeNy(v);
      let horizScale = Math.sqrt(Math.max(0.08, 1 - ny * ny));
      let nx = u * horizScale;
      let nz = Math.sqrt(Math.max(0.04, 1 - constrain(nx * nx + ny * ny, 0, 0.96)));
      let env = sampleRoomEnvironment(nx, ny, nz, x, y, false);
      return { part: "kettle_body", u, v, ...env };
    }
  }

  // 6. STUDIO BACKGROUND WALL & TABLETOP SURFACE
  if (y < TABLE_Y) {
    // Studio background wall with subtle upper-left softbox glow and architectural corner at x = 445
    let gx = (x - 260) / 940;
    let gy = y / TABLE_Y;
    let studioGlow = Math.exp(-Math.pow(gx - 0.15, 2) * 1.4 - Math.pow(gy - 0.35, 2) * 1.2);
    let cornerStep = x < 445 ? 0.05 : -0.03 * ((x - 445) / 755);
    let lum = constrain(0.75 + 0.16 * studioGlow + cornerStep - 0.08 * gy, 0.52, 0.93);
    return { part: "bg_wall", lum, warmth: 0.15, spec: 0.0 };
  } else {
    // Studio tabletop plane (y >= TABLE_Y)
    let ty = (y - TABLE_Y) / (1200 - TABLE_Y);
    let baseTable = 0.85 - 0.16 * Math.pow(ty, 0.75) - 0.06 * ((x - 600) / 600);

    // Crisp horizon bevel line at TABLE_Y
    if (y - TABLE_Y < 5) {
      baseTable = 0.94;
    } else if (y - TABLE_Y < 11) {
      baseTable = 0.56;
    }

    // Cast shadow beneath and slightly to the right of the kettle base
    let sdx = (x - (K_CX + 34)) / 385;
    let sdy = (y - 1018) / 74;
    let rShadow = Math.hypot(sdx, sdy);
    if (rShadow < 1.15) {
      // Tight contact shadow directly under base rim + softer cast penumbra
      let contactDist = Math.hypot((x - K_CX) / 338, (y - 1012) / 56);
      if (contactDist < 1.04) {
        let cFactor = Math.pow(constrain(1 - (contactDist - 0.88) / 0.16, 0, 1), 1.5);
        baseTable = lerp(baseTable, 0.06, cFactor * 0.92);
      } else {
        let pFactor = Math.pow(constrain(1 - (rShadow - 0.75) / 0.4, 0, 1), 1.8);
        baseTable = lerp(baseTable, 0.24, pFactor * 0.68);
      }
    }

    // Blurred vertical reflection of the glowing kettle belly on the glossy studio tabletop!
    if (x > 410 && x < 1085 && y > 1020) {
      let rxNorm = (x - K_CX) / 335;
      if (Math.abs(rxNorm) < 1.0) {
        let fadeY = Math.exp(-Math.pow((y - 1065) / 95, 2));
        // Echo of left window highlight & dark belly core on tabletop
        let tableEcho =
          rxNorm < -0.15
            ? 0.92 // bright window reflection echo
            : rxNorm < 0.35
            ? 0.32 // dark room core echo
            : 0.78;
        let ripple = 0.04 * Math.sin(y * 0.45 + x * 0.05);
        baseTable = lerp(baseTable, tableEcho + ripple, 0.42 * fadeY * (1 - rxNorm * rxNorm));
      }
    }

    return { part: "table", lum: constrain(baseTable, 0.05, 0.96), warmth: 0.35, spec: 0.08 };
  }
}

// ============================================================================
// ANIMATED SCENE EVALUATORS FOR SLIDING CHROME REFLECTIONS
// ============================================================================

function sampleRoomEnvironmentAnim(Nx, Ny, Nz, wx, wy, isSpout = false) {
  let vx = (wx - 720) * 0.00022;
  let vy = (wy - 680) * 0.00022;
  let rx = vx - 2 * Nz * Nx;
  let ry = vy - 2 * Nz * Ny;
  let rz = 1 - 2 * Nz * Nz;

  let theta = Math.atan2(rx, -rz);
  let phi = -Ny + 0.12 * (1 - Nz) * (Nx * 0.3);

  // Exact same amplitude coefficients (0.016, 0.007) as the still so azShift=0 is identical
  let liquidWave =
    0.016 * Math.sin(theta * 4.0 + phi * 5.0 + wavePhase) +
    0.007 * Math.cos(theta * 9.0 - phi * 6.0 - wavePhase * 0.7);
  let pW = phi + elShift + liquidWave;
  let tW = theta + azShift + liquidWave * 0.6;
  let tSelf = theta + liquidWave * 0.6;
  let inFade = constrain((azShift - 0.02) / 0.12, 0, 1);

  let lum = 0.5;
  let warmth = 0.0;
  let spec = 0.0;

  // 1. UPPER HEMISPHERE: STUDIO WINDOWS, MULLIONS & CEILING (pW > 0.05)
  if (pW > 0.05) {
    lum = 0.56 + 0.22 * Math.sin(constrain((pW - 0.05) / 0.85, 0, 1) * Math.PI);
    warmth = -0.15;

    // MAIN 6-PANE STUDIO WINDOW: slides across the red, yellow, and right white panels
    if (tW > -1.42 && tW < -0.16 && pW > 0.08 && pW < 0.66) {
      let dFrame = Math.min(tW - -1.42, -0.16 - tW, (pW - 0.08) * 1.6, (0.66 - pW) * 1.6);
      if (dFrame < 0.032) {
        lum = 0.18;
      } else {
        lum = 0.95 + 0.05 * Math.sin(((tW + 1.42) / 1.26) * Math.PI);
        spec = 0.92;
        warmth = -0.25;

        if (pW > 0.52) {
          let slat = Math.sin((pW - 0.52) * 145);
          if (slat > 0.25) {
            lum = 0.24;
            spec = 0.0;
          }
        }

        let dm1 = Math.abs(tW - -0.98);
        let dm2 = Math.abs(tW - -0.56);
        let dmH = Math.abs(pW - 0.34);

        if (dm1 < 0.024 || dm2 < 0.024 || dmH < 0.017) {
          lum = 0.14;
          spec = 0.0;
          warmth = 0.1;
        } else if (dm1 < 0.042 || dm2 < 0.042 || dmH < 0.030) {
          lum = 1.0;
          spec = 1.0;
        }
      }
    }

    // SECONDARY 4-PANE STUDIO WINDOW: slides from white/red boundary across center red into yellow panel
    if (tW > 0.34 && tW < 1.06 && pW > 0.15 && pW < 0.56) {
      let dFrame = Math.min(tW - 0.34, 1.06 - tW, (pW - 0.15) * 1.6, (0.56 - pW) * 1.6);
      if (dFrame < 0.028) {
        lum = 0.20;
      } else {
        lum = 0.90;
        spec = 0.78;
        warmth = -0.1;
        let dmV = Math.abs(tW - 0.70);
        let dmH = Math.abs(pW - 0.35);
        if (dmV < 0.022 || dmH < 0.016) {
          lum = 0.18;
          spec = 0.0;
        } else if (dmV < 0.038 || dmH < 0.028) {
          lum = 0.98;
          spec = 0.95;
        }
      }
    }

    // INCOMING LEFT STUDIO SKYLIGHT WINDOW: rolls around left cheek & spout as room pans
    if (inFade > 0 && tW > 1.44 && tW < 2.32 && pW > 0.11 && pW < 0.62) {
      let winLum = lum;
      let winSpec = spec;
      let winWarmth = warmth;
      let dFrame = Math.min(tW - 1.44, 2.32 - tW, (pW - 0.11) * 1.6, (0.62 - pW) * 1.6);
      if (dFrame < 0.030) {
        winLum = 0.18;
        winSpec = 0.0;
      } else {
        winLum = 0.94;
        winSpec = 0.88;
        winWarmth = -0.2;
        let dm1 = Math.abs(tW - 1.73);
        let dm2 = Math.abs(tW - 2.02);
        let dmH = Math.abs(pW - 0.36);
        if (dm1 < 0.023 || dm2 < 0.023 || dmH < 0.016) {
          winLum = 0.15;
          winSpec = 0.0;
          winWarmth = 0.1;
        } else if (dm1 < 0.040 || dm2 < 0.040 || dmH < 0.028) {
          winLum = 1.0;
          winSpec = 0.98;
        }
      }
      lum = lerp(lum, winLum, inFade);
      spec = lerp(spec, winSpec, inFade);
      warmth = lerp(warmth, winWarmth, inFade);
    }

    // Self-reflection of overhead arched handle & central knob on upper lid/shoulder
    let tHandle = tSelf + 0.18 * azShift;
    if (!isSpout && pW > 0.62 && Math.abs(tHandle) < 0.95) {
      let handleBand = Math.abs(pW - (0.74 - 0.12 * tHandle * tHandle));
      if (handleBand < 0.055) {
        lum = 0.11;
        spec = 0.0;
      }
    }
  }

  // 2. EQUATORIAL ROOM INTERIOR BAND: pW in [-0.23, 0.05]
  else if (pW >= -0.23) {
    let bandPos = (pW - -0.23) / 0.28;
    lum = 0.06 + 0.07 * Math.sin(bandPos * Math.PI);
    warmth = 0.25;

    // Reflected doorway / warm recessed alcove sliding across lower belly
    if (tW > -0.26 && tW < 0.22 && bandPos < 0.85) {
      lum = 0.26 + 0.08 * Math.cos(((tW + 0.02) / 0.24) * Math.PI * 0.5);
      warmth = 0.65;
      if (Math.abs(tW - -0.24) < 0.025 || Math.abs(tW - 0.20) < 0.025) {
        lum = 0.04;
      }
    }

    // Reflected vertical studio light stand / easel masts
    if (
      Math.abs(tW - -0.64) < 0.028 ||
      Math.abs(tW - 0.56) < 0.026 ||
      (inFade > 0 && Math.abs(tW - 1.38) < 0.026)
    ) {
      lum = 0.03;
    } else if (
      Math.abs(tW - -0.605) < 0.016 ||
      Math.abs(tW - 0.59) < 0.016 ||
      (inFade > 0 && Math.abs(tW - 1.41) < 0.018)
    ) {
      lum = 0.62;
      spec = 0.4;
    }

    // Reflected framed canvas on studio wall
    if (tW > 0.72 && tW < 1.18 && bandPos > 0.22 && bandPos > 0.78) {
      lum = 0.34;
      warmth = 0.7;
      if (tW < 0.76 || tW > 1.14 || bandPos < 0.28 || bandPos > 0.72) {
        lum = 0.07;
      }
    }

    // Incoming warm studio doorway / cabinet reflection on left cheek
    if (inFade > 0 && tW > 1.54 && tW < 2.04 && bandPos < 0.88) {
      let cabLum = 0.29 + 0.07 * Math.cos(((tW - 1.79) / 0.25) * Math.PI * 0.5);
      if (Math.abs(tW - 1.56) < 0.025 || Math.abs(tW - 2.02) < 0.025) {
        cabLum = 0.04;
      }
      lum = lerp(lum, cabLum, inFade);
      warmth = lerp(warmth, 0.65, inFade);
    }

    // Self-reflection of the gooseneck spout on the left cheek of the kettle
    if (!isSpout && tSelf < -0.88 && tSelf > -1.48) {
      let spoutRefCurve = -0.18 + 0.38 * Math.pow((-tSelf - 0.88) / 0.6, 1.2);
      let dSpoutRef = Math.abs(pW - spoutRefCurve);
      if (dSpoutRef < 0.065) {
        lum = dSpoutRef < 0.025 ? 0.82 : 0.05;
        spec = dSpoutRef < 0.025 ? 0.6 : 0.0;
      }
    }
  }

  // 3. LOWER HEMISPHERE: ILLUMINATED STUDIO TABLETOP & CONTACT SHADOW (pW < -0.23)
  else if (pW >= -0.64) {
    let tablePos = (-0.23 - pW) / 0.41;
    lum = 0.84 - 0.34 * Math.pow(tablePos, 0.85);
    warmth = 0.75;
    spec = 0.22 * (1 - tablePos);

    // Secondary reflection of the bright left studio window on the tabletop surface
    if (tW > -1.05 && tW < -0.20 && tablePos > 0.06 && tablePos < 0.58) {
      lum = Math.min(0.95, lum + 0.16);
      spec = 0.55;
    }

    let grain = 0.035 * Math.sin(pW * 95 + tW * 12);
    lum += grain;
  }

  // 4. DEEPEST BELLY TUCK: REFLECTION OF DARK CONTACT SHADOW UNDER KETTLE (pW < -0.64)
  else {
    let underPos = constrain((-0.64 - pW) / 0.25, 0, 1);
    lum = 0.14 - 0.09 * underPos;
    warmth = 0.2;
  }

  // Grazing Fresnel rim sheen near silhouette edge (Nz -> 0)
  if (Nz < 0.34) {
    let fresnel = (0.34 - Nz) / 0.34;
    let rimStripe = Math.sin(fresnel * Math.PI * 3.0);
    lum = constrain(lum + 0.28 * rimStripe * fresnel, 0.05, 0.99);
    if (rimStripe > 0.4) spec = Math.max(spec, 0.65);
  }

  return { lum: constrain(lum, 0, 1), warmth, spec };
}

function evaluateSceneAnim(x, y) {
  // 1. FINIAL KNOB AT TOP OF LID (cx = K_CX, cy = 464)
  let kdx = (x - K_CX) / 62;
  let kdyDisk = (y - 466) / 21;
  if (Math.abs(x - K_CX) < 66 && y >= 438 && y <= 504) {
    let rCap = Math.hypot((x - K_CX) / 34, (y - 454) / 10.5);
    if (rCap <= 1.0) {
      let nx = ((x - K_CX) / 34) * 0.55;
      let ny = -0.78 + ((y - 454) / 10.5) * 0.25;
      let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
      if (rCap > 0.85) env.lum = 0.96;
      return { part: "knob_cap", ...env };
    }
    let rDisk = Math.hypot(kdx, kdyDisk);
    if (rDisk <= 1.0 && y <= 487) {
      let sheenCenter = -0.48 + 0.52 * azShift;
      let sheen = Math.exp(-Math.pow((kdx - sheenCenter) / 0.32, 2)) * (1 - Math.abs(kdyDisk) * 0.5);
      let rimLight = rDisk > 0.88 && kdyDisk < 0 ? 0.28 : 0.0;
      let lum = constrain(0.06 + 0.34 * sheen + rimLight, 0.04, 0.55);
      return { part: "knob_disk", lum, warmth: 0.1, spec: sheen * 0.3 };
    }
    if (Math.abs(x - K_CX) <= 27 && y >= 480 && y <= 503) {
      let uStem = (x - K_CX) / 27;
      let nx = uStem;
      let ny = 0.1;
      let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
      return { part: "knob_stem", ...env };
    }
  }

  // 2. ARCHED HANDLE & CHROME SHOULDER BRACKETS
  if (y >= 225 && y <= 565 && x >= 490 && x <= 1005) {
    let bestT = -1;
    let bestDist = 999;
    let steps = 48;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = getHandleArchPoint(t);
      let d = Math.hypot(x - p.x, y - p.y);
      if (d < bestDist) {
        bestDist = d;
        bestT = t;
      }
    }
    for (let step = 0.01; step >= 0.0015; step *= 0.4) {
      for (let dir of [-1, 1]) {
        let tc = constrain(bestT + dir * step, 0, 1);
        let p = getHandleArchPoint(tc);
        let d = Math.hypot(x - p.x, y - p.y);
        if (d < bestDist) {
          bestDist = d;
          bestT = tc;
        }
      }
    }
    let hRad = getHandleRadius(bestT);
    if (bestDist <= hRad) {
      let hp = getHandleArchPoint(bestT);
      let ht = getHandleArchTangent(bestT);
      let s = ((x - hp.x) * ht.nx + (y - hp.y) * ht.ny) / hRad;
      s = constrain(s, -1, 1);

      let isFerrule = Math.abs(bestT - 0.21) < 0.018 || Math.abs(bestT - 0.79) < 0.018;
      let isGrip = bestT > 0.21 && bestT < 0.79 && !isFerrule;

      if (isGrip) {
        let sheenShift = 0.18 * Math.sin((bestT - 0.5) * 5.0 - azShift * 2.2) * constrain(azShift / 0.15, 0, 1);
        let topSheen = Math.exp(-Math.pow((s + 0.56 - sheenShift) / 0.24, 2));
        let underRef = s > 0.55 ? 0.16 * ((s - 0.55) / 0.45) : 0;
        let lum = constrain(0.05 + 0.52 * topSheen + underRef, 0.04, 0.68);
        return { part: "handle_grip", lum, warmth: 0.05, spec: topSheen * 0.45 };
      } else {
        let nx = ht.nx * s + ht.tx * 0.15;
        let ny = ht.ny * s + ht.ty * 0.15;
        let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
        let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
        if (isFerrule) env.lum = constrain(env.lum + 0.18, 0.1, 1.0);
        return { part: "handle_chrome", ...env };
      }
    }

    for (let side of [-1, 1]) {
      let bx0 = side < 0 ? 536 : 960;
      let by0 = 492;
      let bx1 = side < 0 ? 570 : 926;
      let by1 = 544;
      let dxB = bx1 - bx0;
      let dyB = by1 - by0;
      let lenB = Math.hypot(dxB, dyB);
      let proj = ((x - bx0) * dxB + (y - by0) * dyB) / (lenB * lenB);
      if (proj >= 0 && proj <= 1) {
        let cxB = bx0 + proj * dxB;
        let cyB = by0 + proj * dyB;
        let radB = 15 + 9 * proj + (proj > 0.82 ? 5 : 0);
        let perp = ((x - cxB) * (dyB / lenB) - (y - cyB) * (dxB / lenB)) / radB;
        if (Math.abs(perp) <= 1.0) {
          let nx = perp * 0.85;
          let ny = -0.35 + 0.3 * proj;
          let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));
          let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
          return { part: "bracket", ...env };
        }
      }
    }
  }

  // 3. STEPPED CHROME LID AT TOP OF KETTLE BODY
  let ldx = (x - K_CX) / 214;
  let ldy = (y - K_TOP_Y) / 46;
  let rLid = Math.hypot(ldx, ldy);
  if (rLid <= 1.02) {
    if (rLid >= 0.83 && rLid <= 0.87) {
      return { part: "lid_seam", lum: 0.05, warmth: 0.1, spec: 0.0 };
    }
    if (rLid > 0.87) {
      let bevel = (rLid - 0.945) / 0.075;
      let nx = ldx * (0.45 + 0.35 * bevel);
      let ny = -0.72 * Math.cos(bevel * 1.3) + ldy * 0.35;
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
      return { part: "lid_rim", ...env };
    }
    if (rLid >= 0.71) {
      let stepWave = Math.sin(((rLid - 0.71) / 0.12) * Math.PI * 2.0);
      let nx = ldx * 0.5 + 0.25 * stepWave * ldx;
      let ny = -0.70 + 0.45 * stepWave;
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
      return { part: "lid_step", ...env };
    }
    let nx = ldx * 0.42;
    let ny = -0.78 + ldy * 0.24;
    let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
    let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y);
    let rKnobRef = Math.hypot((x - K_CX) / 56, (y - 504) / 18);
    if (rKnobRef < 1.0) {
      env.lum = lerp(0.08, env.lum, Math.pow(rKnobRef, 1.6));
      env.spec *= rKnobRef;
    }
    return { part: "lid_dome", ...env };
  }

  // 4. GOOSENECK SPOUT
  if (x >= 185 && x <= 495 && y >= 470 && y <= 865) {
    let tipAngle = -34 * (Math.PI / 180);
    let tx = (x - 221) * Math.cos(tipAngle) - (y - 496) * Math.sin(tipAngle);
    let ty = (x - 221) * Math.sin(tipAngle) + (y - 496) * Math.cos(tipAngle);
    let rMouth = Math.hypot(tx / 23, ty / 8.5);
    if (rMouth <= 1.16) {
      if (rMouth >= 0.86) {
        return { part: "spout_lip", lum: 0.97, warmth: -0.1, spec: 0.95 };
      } else {
        let throatLum = 0.04 + 0.14 * (1 - rMouth) + (tx > 0 ? 0.08 : 0);
        return { part: "spout_throat", lum: throatLum, warmth: 0.2, spec: 0.0 };
      }
    }

    let bestT = -1;
    let bestDist = 999;
    let steps = 42;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = getSpoutPoint(t);
      let d = Math.hypot(x - p.x, y - p.y);
      if (d < bestDist) {
        bestDist = d;
        bestT = t;
      }
    }
    for (let step = 0.012; step >= 0.0015; step *= 0.4) {
      for (let dir of [-1, 1]) {
        let tc = constrain(bestT + dir * step, 0, 1);
        let p = getSpoutPoint(tc);
        let d = Math.hypot(x - p.x, y - p.y);
        if (d < bestDist) {
          bestDist = d;
          bestT = tc;
        }
      }
    }
    let sRad = getSpoutRadius(bestT);
    if (bestDist <= sRad && bestT <= 0.985) {
      let sp = getSpoutPoint(bestT);
      let st = getSpoutTangent(bestT);
      let s = ((x - sp.x) * st.nx + (y - sp.y) * st.ny) / sRad;
      s = constrain(s, -1, 1);

      let collarWave = bestT < 0.09 ? 0.32 * Math.sin((bestT / 0.09) * Math.PI * 2.0) : 0;
      let nx = st.nx * s * 0.88 + st.tx * (0.18 + collarWave);
      let ny = st.ny * s * 0.88 + st.ty * (0.18 + collarWave);
      let nz = Math.sqrt(Math.max(0.05, 1 - constrain(nx * nx + ny * ny, 0, 0.95)));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y, true);

      let sShift = 0.16 * Math.sin(azShift * 1.5);
      let sRel = s - sShift;
      if (sRel > -0.68 && sRel < -0.34) {
        let ridge = Math.exp(-Math.pow((sRel + 0.51) / 0.12, 2));
        env.lum = Math.max(env.lum, 0.92 + 0.08 * ridge);
        env.spec = Math.max(env.spec, 0.9 * ridge);
      } else if (sRel > -0.18 && sRel < 0.22) {
        let core = Math.exp(-Math.pow((sRel - 0.02) / 0.14, 2));
        env.lum = lerp(env.lum, 0.07, 0.78 * core);
        env.spec *= 1 - core;
      } else if (sRel > 0.35 && sRel < 0.78) {
        let underGlow = Math.exp(-Math.pow((sRel - 0.56) / 0.16, 2));
        env.lum = Math.max(env.lum, 0.74 * underGlow);
        env.warmth = 0.65;
      }
      return { part: "spout", ...env };
    }
  }

  // 5. MAIN BULBOUS CHROME KETTLE BODY
  if (y >= K_TOP_Y - 10 && y <= 1060 && x >= 360 && x <= 1135) {
    let v = constrain((y - K_TOP_Y) / K_SPAN_Y, 0, 1);
    let u = 0;
    for (let iter = 0; iter < 4; iter++) {
      let rx = getBodyRx(v);
      u = (x - K_CX) / rx;
      if (Math.abs(u) <= 1.05) {
        let sag = getBodySag(v) * Math.sqrt(Math.max(0, 1 - constrain(u * u, 0, 1)));
        v = (y - sag - K_TOP_Y) / K_SPAN_Y;
      }
    }
    let rxFinal = getBodyRx(v);
    u = (x - K_CX) / rxFinal;

    if (v >= 0.0 && v <= 1.0 && Math.abs(u) <= 1.0) {
      let ny = getBodySlopeNy(v);
      let horizScale = Math.sqrt(Math.max(0.08, 1 - ny * ny));
      let nx = u * horizScale;
      let nz = Math.sqrt(Math.max(0.04, 1 - constrain(nx * nx + ny * ny, 0, 0.96)));
      let env = sampleRoomEnvironmentAnim(nx, ny, nz, x, y, false);
      return { part: "kettle_body", u, v, ...env };
    }
  }

  // 6. STUDIO BACKGROUND WALL & TABLETOP SURFACE
  if (y < TABLE_Y) {
    let gx = (x - 260) / 940;
    let gy = y / TABLE_Y;
    let studioGlow = Math.exp(-Math.pow(gx - 0.15, 2) * 1.4 - Math.pow(gy - 0.35, 2) * 1.2);
    let cornerStep = x < 445 ? 0.05 : -0.03 * ((x - 445) / 755);
    let lum = constrain(0.75 + 0.16 * studioGlow + cornerStep - 0.08 * gy, 0.52, 0.93);
    return { part: "bg_wall", lum, warmth: 0.15, spec: 0.0 };
  } else {
    let ty = (y - TABLE_Y) / (1200 - TABLE_Y);
    let baseTable = 0.85 - 0.16 * Math.pow(ty, 0.75) - 0.06 * ((x - 600) / 600);

    if (y - TABLE_Y < 5) {
      baseTable = 0.94;
    } else if (y - TABLE_Y < 11) {
      baseTable = 0.56;
    }

    let sdx = (x - (K_CX + 34)) / 385;
    let sdy = (y - 1018) / 74;
    let rShadow = Math.hypot(sdx, sdy);
    if (rShadow < 1.15) {
      let contactDist = Math.hypot((x - K_CX) / 338, (y - 1012) / 56);
      if (contactDist < 1.04) {
        let cFactor = Math.pow(constrain(1 - (contactDist - 0.88) / 0.16, 0, 1), 1.5);
        baseTable = lerp(baseTable, 0.06, cFactor * 0.92);
      } else {
        let pFactor = Math.pow(constrain(1 - (rShadow - 0.75) / 0.4, 0, 1), 1.8);
        baseTable = lerp(baseTable, 0.24, pFactor * 0.68);
      }
    }

    // Blurred vertical reflection of the glowing kettle belly on the glossy studio tabletop
    // At azShift = 0, rxShifted === rxNorm and -1.02 is outside (-1, 1), matching evaluateScene identically
    if (x > 410 && x < 1085 && y > 1020) {
      let rxNorm = (x - K_CX) / 335;
      if (Math.abs(rxNorm) < 1.0) {
        let fadeY = Math.exp(-Math.pow((y - 1065) / 95, 2));
        let rxShifted = rxNorm - 0.52 * azShift;
        let tableEcho =
          rxShifted < -1.02
            ? 0.36
            : rxShifted < -0.15
            ? 0.92
            : rxShifted < 0.35
            ? 0.32
            : 0.78;
        let ripple = 0.04 * Math.sin(y * 0.45 + x * 0.05 - wavePhase * 1.4);
        baseTable = lerp(baseTable, tableEcho + ripple, 0.42 * fadeY * (1 - rxNorm * rxNorm));
      }
    }

    return { part: "table", lum: constrain(baseTable, 0.05, 0.96), warmth: 0.35, spec: 0.08 };
  }
}

// ============================================================================
// POLYGON CLIPPING (SUTHERLAND-HODGMAN) FOR PANEL UNDER-WASHES
// ============================================================================

function clipPolyToRect(poly, x1, y1, x2, y2) {
  let clipEdge = (pts, insideFn, intersectFn) => {
    let out = [];
    if (pts.length === 0) return out;
    for (let i = 0; i < pts.length; i++) {
      let curr = pts[i];
      let prev = pts[(i + pts.length - 1) % pts.length];
      let currIn = insideFn(curr);
      let prevIn = insideFn(prev);
      if (currIn) {
        if (!prevIn) out.push(intersectFn(prev, curr));
        out.push(curr);
      } else if (prevIn) {
        out.push(intersectFn(prev, curr));
      }
    }
    return out;
  };

  let res = poly;
  res = clipEdge(res, p => p[0] >= x1, (a, b) => [x1, a[1] + (b[1] - a[1]) * ((x1 - a[0]) / (b[0] - a[0]))]);
  res = clipEdge(res, p => p[0] <= x2, (a, b) => [x2, a[1] + (b[1] - a[1]) * ((x2 - a[0]) / (b[0] - a[0]))]);
  res = clipEdge(res, p => p[1] >= y1, (a, b) => [a[0] + (b[0] - a[0]) * ((y1 - a[1]) / (b[1] - a[1])), y1]);
  res = clipEdge(res, p => p[1] <= y2, (a, b) => [a[0] + (b[0] - a[0]) * ((y2 - a[1]) / (b[1] - a[1])), y2]);
  return res;
}

function washPolygonInPanels(poly, lum, warmth, spec, opacity = 225) {
  brush.noStroke();
  brush.noHatch();
  for (let p of panels) {
    let clipped = clipPolyToRect(poly, p.x1, p.y1, p.x2, p.y2);
    if (clipped.length >= 3) {
      let col = getTintedHex(lum, warmth, spec, p.tint, 0);
      let bPoly = new brush.Polygon(clipped);
      bPoly.wash(col, opacity);
    }
  }
}

function washPolygonInPanelsSeeded(poly, lum, warmth, spec, opacity, baseSeed) {
  brush.noStroke();
  brush.noHatch();
  for (let i = 0; i < panels.length; i++) {
    let p = panels[i];
    let clipped = clipPolyToRect(poly, p.x1, p.y1, p.x2, p.y2);
    if (clipped.length >= 3) {
      randomSeed(baseSeed + i * 29);
      noiseSeed(baseSeed + i * 29);
      let col = getTintedHex(lum, warmth, spec, p.tint, 0);
      let bPoly = new brush.Polygon(clipped);
      bPoly.wash(col, opacity);
    }
  }
}

// ============================================================================
// SEGMENTED CURVE MARKER RENDERERS (STILL & SEEDED ANIMATED)
// ============================================================================

function drawSegmentedPath(pts, brushName, weightMult, quantSteps = 22) {
  if (pts.length < 2) return;

  let currentChain = [];
  let currentPanel = null;
  let currentHex = null;

  let flushChain = () => {
    if (currentChain.length < 2 || !currentHex) {
      currentChain = [];
      return;
    }
    brush.set(brushName, currentHex, weightMult);
    if (currentChain.length === 2) {
      brush.line(currentChain[0][0], currentChain[0][1], currentChain[1][0], currentChain[1][1]);
    } else {
      // Sub-sample chain to ~12px spacing for silky smooth p5.brush splines
      let splinePts = [currentChain[0]];
      let lastPt = currentChain[0];
      for (let i = 1; i < currentChain.length - 1; i++) {
        let d = Math.hypot(currentChain[i][0] - lastPt[0], currentChain[i][1] - lastPt[1]);
        if (d >= 11.5) {
          splinePts.push(currentChain[i]);
          lastPt = currentChain[i];
        }
      }
      let endPt = currentChain[currentChain.length - 1];
      if (Math.hypot(endPt[0] - lastPt[0], endPt[1] - lastPt[1]) < 4 && splinePts.length > 1) {
        splinePts[splinePts.length - 1] = endPt;
      } else {
        splinePts.push(endPt);
      }

      if (splinePts.length === 2) {
        brush.line(splinePts[0][0], splinePts[0][1], splinePts[1][0], splinePts[1][1]);
      } else {
        brush.spline(splinePts, 0.32);
      }
    }
    currentChain = [];
  };

  for (let i = 0; i < pts.length; i++) {
    let pt = pts[i];
    let x = pt[0];
    let y = pt[1];
    let panel = getPanelAt(x, y);

    if (!panel) {
      flushChain();
      currentPanel = null;
      currentHex = null;
      continue;
    }

    let sc = pt.length >= 5
      ? { lum: pt[2], warmth: pt[3], spec: pt[4] }
      : evaluateScene(x, y);
    let hex = getTintedHex(sc.lum, sc.warmth, sc.spec, panel.tint, quantSteps);

    if (panel !== currentPanel || hex !== currentHex) {
      if (currentChain.length > 0 && panel === currentPanel) {
        // Overlap by 1 point so marker transitions blend seamlessly without micro-gaps
        currentChain.push([x, y]);
      }
      flushChain();
      currentPanel = panel;
      currentHex = hex;
    }
    currentChain.push([x, y]);
  }
  flushChain();
}

function drawSegmentedPathAnim(pts, brushName, weightMult, quantSteps, baseSeed) {
  if (pts.length < 2) return;

  let currentChain = [];
  let currentPanel = null;
  let currentHex = null;
  let panelStrokeCount = 0;

  let flushChain = () => {
    if (currentChain.length < 2 || !currentHex) {
      currentChain = [];
      return;
    }
    let pIdx = currentPanel ? panels.indexOf(currentPanel) : 0;
    let strokeSeed = baseSeed + pIdx * 193 + panelStrokeCount * 17;
    panelStrokeCount++;
    randomSeed(strokeSeed);
    noiseSeed(strokeSeed);

    brush.set(brushName, currentHex, weightMult);
    if (currentChain.length === 2) {
      brush.line(currentChain[0][0], currentChain[0][1], currentChain[1][0], currentChain[1][1]);
    } else {
      let splinePts = [currentChain[0]];
      let lastPt = currentChain[0];
      for (let i = 1; i < currentChain.length - 1; i++) {
        let d = Math.hypot(currentChain[i][0] - lastPt[0], currentChain[i][1] - lastPt[1]);
        if (d >= 11.5) {
          splinePts.push(currentChain[i]);
          lastPt = currentChain[i];
        }
      }
      let endPt = currentChain[currentChain.length - 1];
      if (Math.hypot(endPt[0] - lastPt[0], endPt[1] - lastPt[1]) < 4 && splinePts.length > 1) {
        splinePts[splinePts.length - 1] = endPt;
      } else {
        splinePts.push(endPt);
      }

      if (splinePts.length === 2) {
        brush.line(splinePts[0][0], splinePts[0][1], splinePts[1][0], splinePts[1][1]);
      } else {
        brush.spline(splinePts, 0.32);
      }
    }
    currentChain = [];
  };

  for (let i = 0; i < pts.length; i++) {
    let pt = pts[i];
    let x = pt[0];
    let y = pt[1];
    let panel = getPanelAt(x, y);

    if (!panel) {
      flushChain();
      currentPanel = null;
      currentHex = null;
      continue;
    }

    let sc = pt.length >= 5
      ? { lum: pt[2], warmth: pt[3], spec: pt[4] }
      : evaluateSceneAnim(x, y);
    let hex = getTintedHex(sc.lum, sc.warmth, sc.spec, panel.tint, quantSteps);

    if (panel !== currentPanel || hex !== currentHex) {
      if (currentChain.length > 0 && panel === currentPanel) {
        currentChain.push([x, y]);
      }
      flushChain();
      if (panel !== currentPanel) {
        panelStrokeCount = 0;
      }
      currentPanel = panel;
      currentHex = hex;
    }
    currentChain.push([x, y]);
  }
  flushChain();
}

// ============================================================================
// EXACT STILL RENDER PIPELINE (COMPLETELY UNCHANGED)
// ============================================================================

function paintStill() {
  translate(-width / 2, -height / 2);

  // --------------------------------------------------------------------------
  // LAYER 1: FLAT TINTED PANEL BASE WASHES
  // --------------------------------------------------------------------------
  brush.noStroke();
  brush.noHatch();
  for (let p of panels) {
    let baseCol = getTintedHex(0.76, 0.15, 0.0, p.tint, 0);
    brush.wash(baseCol, 245);
    brush.rect(p.x1, p.y1, p.x2 - p.x1, p.y2 - p.y1, "corner");
  }
  brush.noWash();

  // --------------------------------------------------------------------------
  // LAYER 2: SOLID TONAL UNDER-WASHES (CLIPPED TO EACH PANEL)
  // --------------------------------------------------------------------------
  // 2A. Tabletop under-wash
  washPolygonInPanels(
    [[18, TABLE_Y], [1182, TABLE_Y], [1182, 1182], [18, 1182]],
    0.82, 0.35, 0.05, 220
  );

  // 2B. Cast shadow ellipse under kettle
  let shadowPoly = [];
  for (let a = 0; a < 360; a += 10) {
    let rad = (a * Math.PI) / 180;
    shadowPoly.push([K_CX + 30 + 365 * Math.cos(rad), 1016 + 64 * Math.sin(rad)]);
  }
  washPolygonInPanels(shadowPoly, 0.14, 0.2, 0.0, 230);

  // 2C. Kettle main body silhouette under-wash
  let bodyPoly = [];
  for (let i = 0; i <= 32; i++) {
    let v = i / 32;
    bodyPoly.push([K_CX - getBodyRx(v), K_TOP_Y + v * K_SPAN_Y]);
  }
  for (let i = -16; i <= 16; i++) {
    let u = i / 16;
    let rx = getBodyRx(1.0);
    let sag = getBodySag(1.0) * Math.sqrt(Math.max(0, 1 - u * u));
    bodyPoly.push([K_CX + u * rx, K_TOP_Y + K_SPAN_Y + sag]);
  }
  for (let i = 32; i >= 0; i--) {
    let v = i / 32;
    bodyPoly.push([K_CX + getBodyRx(v), K_TOP_Y + v * K_SPAN_Y]);
  }
  washPolygonInPanels(bodyPoly, 0.56, 0.2, 0.1, 245);

  // 2D. Dark equatorial room reflection band on kettle body
  let eqPoly = [];
  for (let i = -24; i <= 24; i++) {
    let u = i / 24;
    let vTop = 0.44 + 0.06 * u * u;
    let rx = getBodyRx(vTop);
    let sag = getBodySag(vTop) * Math.sqrt(Math.max(0, 1 - u * u));
    eqPoly.push([K_CX + u * rx, K_TOP_Y + vTop * K_SPAN_Y + sag]);
  }
  for (let i = 24; i >= -24; i--) {
    let u = i / 24;
    let vBot = 0.68 + 0.05 * u * u;
    let rx = getBodyRx(vBot);
    let sag = getBodySag(vBot) * Math.sqrt(Math.max(0, 1 - u * u));
    eqPoly.push([K_CX + u * rx, K_TOP_Y + vBot * K_SPAN_Y + sag]);
  }
  washPolygonInPanels(eqPoly, 0.09, 0.25, 0.0, 235);

  // 2E. Lower belly bright tabletop reflection zone
  let bellyTablePoly = [];
  for (let i = -22; i <= 22; i++) {
    let u = i / 24;
    let vTop = 0.68 + 0.05 * u * u;
    let rx = getBodyRx(vTop);
    let sag = getBodySag(vTop) * Math.sqrt(Math.max(0, 1 - u * u));
    bellyTablePoly.push([K_CX + u * rx, K_TOP_Y + vTop * K_SPAN_Y + sag]);
  }
  for (let i = 22; i >= -22; i--) {
    let u = i / 24;
    let vBot = 0.93;
    let rx = getBodyRx(vBot);
    let sag = getBodySag(vBot) * Math.sqrt(Math.max(0, 1 - u * u));
    bellyTablePoly.push([K_CX + u * rx, K_TOP_Y + vBot * K_SPAN_Y + sag]);
  }
  washPolygonInPanels(bellyTablePoly, 0.76, 0.75, 0.25, 225);

  // 2F. Gooseneck spout silhouette under-wash
  let spoutPoly = [];
  for (let i = 0; i <= 28; i++) {
    let t = i / 28;
    let p = getSpoutPoint(t);
    let st = getSpoutTangent(t);
    let r = getSpoutRadius(t);
    spoutPoly.push([p.x - st.nx * r, p.y - st.ny * r]);
  }
  for (let i = 28; i >= 0; i--) {
    let t = i / 28;
    let p = getSpoutPoint(t);
    let st = getSpoutTangent(t);
    let r = getSpoutRadius(t);
    spoutPoly.push([p.x + st.nx * r, p.y + st.ny * r]);
  }
  washPolygonInPanels(spoutPoly, 0.52, 0.15, 0.2, 240);

  // --------------------------------------------------------------------------
  // LAYER 3: STUDIO BACKGROUND WALL & TABLETOP SMOOTH MARKER BLENDING
  // --------------------------------------------------------------------------
  for (let y = 22; y < 1180; y += 6.5) {
    let rowPts = [];
    for (let x = 20; x <= 1180; x += 6) {
      let sc = evaluateScene(x, y);
      if (sc.part === "bg_wall" || sc.part === "table") {
        rowPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (rowPts.length >= 2) {
          drawSegmentedPath(rowPts, "chisel_marker", 1.0, 20);
        }
        rowPts = [];
      }
    }
    if (rowPts.length >= 2) {
      drawSegmentedPath(rowPts, "chisel_marker", 1.0, 20);
    }
  }

  // Crisp studio tabletop horizon bevel ruling across panels
  for (let dy of [-2, 1.5, 5]) {
    let hPts = [];
    let y = TABLE_Y + dy;
    for (let x = 20; x <= 1180; x += 5) {
      let sc = evaluateScene(x, y);
      if (sc.part === "bg_wall" || sc.part === "table") {
        hPts.push([x, y, dy < 0 ? 0.62 : dy < 3 ? 0.96 : 0.54, 0.25, 0.2]);
      } else {
        if (hPts.length >= 2) drawSegmentedPath(hPts, "fine_marker", 0.85, 24);
        hPts = [];
      }
    }
    if (hPts.length >= 2) drawSegmentedPath(hPts, "fine_marker", 0.85, 24);
  }

  // --------------------------------------------------------------------------
  // LAYER 4: HYPERREAL CHROME KETTLE BODY — CURVILINEAR MARKER BLENDING
  // --------------------------------------------------------------------------
  // 4A. Dense Latitude Reflection Ribbons (following the 3D elliptical cross-sections)
  let latCount = 128;
  for (let i = 0; i <= latCount; i++) {
    let v = i / latCount;
    let rx = getBodyRx(v);
    let sag = getBodySag(v);
    let yBase = K_TOP_Y + v * K_SPAN_Y;

    let latPts = [];
    let uSteps = Math.round((rx * 2) / 4.2);
    for (let j = 0; j <= uSteps; j++) {
      let u = -0.996 + (1.992 * j) / uSteps;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let sc = evaluateScene(x, y);
      if (sc.part === "kettle_body") {
        latPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (latPts.length >= 2) drawSegmentedPath(latPts, "chisel_marker", 0.92, 26);
        latPts = [];
      }
    }
    if (latPts.length >= 2) {
      drawSegmentedPath(latPts, "chisel_marker", 0.92, 26);
    }
  }

  // 4B. Cross-Contour Meridian Blending Sweeps (fusing vertical metallic transitions)
  let merCount = 86;
  for (let i = 0; i <= merCount; i++) {
    let u = -0.985 + (1.97 * i) / merCount;
    let merPts = [];
    let vSteps = 96;
    for (let j = 0; j <= vSteps; j++) {
      let v = j / vSteps;
      let rx = getBodyRx(v);
      let sag = getBodySag(v);
      let x = K_CX + u * rx;
      let y = K_TOP_Y + v * K_SPAN_Y + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let sc = evaluateScene(x, y);
      if (sc.part === "kettle_body") {
        merPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (merPts.length >= 2) drawSegmentedPath(merPts, "glaze_brush", 0.85, 24);
        merPts = [];
      }
    }
    if (merPts.length >= 2) {
      drawSegmentedPath(merPts, "glaze_brush", 0.85, 24);
    }
  }

  // 4C. Fine High-Definition Latitude Pass over High-Contrast Reflection Zones
  for (let i = 0; i <= 150; i++) {
    let v = i / 150;
    let rx = getBodyRx(v);
    let sag = getBodySag(v);
    let yBase = K_TOP_Y + v * K_SPAN_Y;

    let detailPts = [];
    let uSteps = Math.round((rx * 2) / 3.8);
    for (let j = 0; j <= uSteps; j++) {
      let u = -0.995 + (1.99 * j) / uSteps;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let sc = evaluateScene(x, y);
      // Focus fine marker pass on windows, horizon edges, and base rim bead
      if (sc.part === "kettle_body" && (sc.spec > 0.3 || sc.lum < 0.22 || v > 0.88 || v < 0.48)) {
        detailPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (detailPts.length >= 2) drawSegmentedPath(detailPts, "fine_marker", 0.88, 30);
        detailPts = [];
      }
    }
    if (detailPts.length >= 2) {
      drawSegmentedPath(detailPts, "fine_marker", 0.88, 30);
    }
  }

  // --------------------------------------------------------------------------
  // LAYER 5: GOOSENECK SPOUT, STEPPED LID, FINIAL KNOB & ARCHED HANDLE
  // --------------------------------------------------------------------------
  // 5A. Gooseneck Spout Longitudinal Flow Curves
  let spoutStrips = 34;
  for (let i = 0; i <= spoutStrips; i++) {
    let s = -0.97 + (1.94 * i) / spoutStrips;
    let sPts = [];
    for (let j = 0; j <= 85; j++) {
      let t = (j / 85) * 0.98;
      let sp = getSpoutPoint(t);
      let st = getSpoutTangent(t);
      let r = getSpoutRadius(t);
      let x = sp.x + st.nx * s * r;
      let y = sp.y + st.ny * s * r;
      let sc = evaluateScene(x, y);
      if (sc.part === "spout" || sc.part === "spout_lip") {
        sPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (sPts.length >= 2) drawSegmentedPath(sPts, "fine_marker", 0.82, 28);
        sPts = [];
      }
    }
    if (sPts.length >= 2) {
      drawSegmentedPath(sPts, "fine_marker", 0.82, 28);
    }
  }

  // Spout elliptical mouth opening & beveled chrome lip at tip (221, 496)
  let tipAngle = -34 * (Math.PI / 180);
  for (let rFrac = 0.1; rFrac <= 1.12; rFrac += 0.12) {
    let mPts = [];
    for (let a = 0; a <= 360; a += 8) {
      let rad = (a * Math.PI) / 180;
      let lx = 23 * rFrac * Math.cos(rad);
      let ly = 8.5 * rFrac * Math.sin(rad);
      let x = 221 + lx * Math.cos(tipAngle) + ly * Math.sin(tipAngle);
      let y = 496 - lx * Math.sin(tipAngle) + ly * Math.cos(tipAngle);
      let isLip = rFrac >= 0.85;
      mPts.push([x, y, isLip ? 0.98 : 0.06, isLip ? -0.1 : 0.2, isLip ? 0.95 : 0.0]);
    }
    drawSegmentedPath(mPts, "micro_marker", 0.95, 30);
  }

  // 5B. Concentric Stepped Chrome Lid Rings (cx = K_CX, cy = K_TOP_Y)
  for (let rFrac = 0.06; rFrac <= 1.02; rFrac += 0.032) {
    let lidPts = [];
    for (let a = 0; a <= 360; a += 4) {
      let rad = (a * Math.PI) / 180;
      let x = K_CX + 214 * rFrac * Math.cos(rad);
      let y = K_TOP_Y + 46 * rFrac * Math.sin(rad);
      let sc = evaluateScene(x, y);
      if (sc.part && sc.part.startsWith("lid")) {
        lidPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (lidPts.length >= 2) drawSegmentedPath(lidPts, "fine_marker", 0.78, 28);
        lidPts = [];
      }
    }
    if (lidPts.length >= 2) {
      drawSegmentedPath(lidPts, "fine_marker", 0.78, 28);
    }
  }

  // 5C. Chrome Shoulder Mounting Brackets
  for (let side of [-1, 1]) {
    let bx0 = side < 0 ? 536 : 960;
    let by0 = 492;
    let bx1 = side < 0 ? 570 : 926;
    let by1 = 544;
    let dxB = bx1 - bx0;
    let dyB = by1 - by0;
    let lenB = Math.hypot(dxB, dyB);
    let nxB = dyB / lenB;
    let nyB = -dxB / lenB;

    for (let s = -0.95; s <= 0.95; s += 0.14) {
      let bPts = [];
      for (let k = 0; k <= 24; k++) {
        let proj = k / 24;
        let radB = 15 + 9 * proj + (proj > 0.82 ? 5 : 0);
        let x = bx0 + proj * dxB + nxB * s * radB;
        let y = by0 + proj * dyB + nyB * s * radB;
        let sc = evaluateScene(x, y);
        bPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      }
      drawSegmentedPath(bPts, "fine_marker", 0.75, 28);
    }
  }

  // 5D. Sculpted Arched Handle & Chrome Struts
  let handleStrips = 22;
  for (let i = 0; i <= handleStrips; i++) {
    let s = -0.94 + (1.88 * i) / handleStrips;
    let hPts = [];
    for (let j = 0; j <= 90; j++) {
      let t = j / 90;
      let hp = getHandleArchPoint(t);
      let ht = getHandleArchTangent(t);
      let r = getHandleRadius(t);
      let x = hp.x + ht.nx * s * r;
      let y = hp.y + ht.ny * s * r;
      let sc = evaluateScene(x, y);
      if (sc.part === "handle_grip" || sc.part === "handle_chrome") {
        hPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (hPts.length >= 2) drawSegmentedPath(hPts, "fine_marker", 0.78, 28);
        hPts = [];
      }
    }
    if (hPts.length >= 2) {
      drawSegmentedPath(hPts, "fine_marker", 0.78, 28);
    }
  }

  // 5E. Finial Knob on Lid (Stem, Satin-Black Disk & Chrome Top Cap)
  for (let y = 442; y <= 502; y += 2.2) {
    let kPts = [];
    for (let x = K_CX - 64; x <= K_CX + 64; x += 2.5) {
      let sc = evaluateScene(x, y);
      if (sc.part && sc.part.startsWith("knob")) {
        kPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (kPts.length >= 2) drawSegmentedPath(kPts, "micro_marker", 1.0, 28);
        kPts = [];
      }
    }
    if (kPts.length >= 2) {
      drawSegmentedPath(kPts, "micro_marker", 1.0, 28);
    }
  }

  // --------------------------------------------------------------------------
  // LAYER 6: RAZOR-SHARP HYPERREAL REFLECTION EDGES, MULLIONS & SPECULARS
  // --------------------------------------------------------------------------
  // 6A. Micro-marker pass over brightest specular window highlights & spout spine
  for (let i = 0; i <= 110; i++) {
    let v = (i / 110) * 0.58; // upper dome where studio windows reflect
    let rx = getBodyRx(v);
    let sag = getBodySag(v);
    let yBase = K_TOP_Y + v * K_SPAN_Y;

    let specPts = [];
    for (let j = 0; j <= 130; j++) {
      let u = -0.96 + (1.92 * j) / 130;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let sc = evaluateScene(x, y);
      if (sc.part === "kettle_body" && (sc.spec > 0.65 || sc.lum < 0.19)) {
        specPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (specPts.length >= 2) drawSegmentedPath(specPts, "micro_marker", 0.95, 32);
        specPts = [];
      }
    }
    if (specPts.length >= 2) {
      drawSegmentedPath(specPts, "micro_marker", 0.95, 32);
    }
  }

  // 6B. Blazing specular ridge along the gooseneck spout S-curve
  for (let s of [-0.54, -0.50, -0.46, 0.02]) {
    let rPts = [];
    for (let j = 0; j <= 90; j++) {
      let t = (j / 90) * 0.97;
      let sp = getSpoutPoint(t);
      let st = getSpoutTangent(t);
      let r = getSpoutRadius(t);
      let x = sp.x + st.nx * s * r;
      let y = sp.y + st.ny * s * r;
      let isSpec = s < -0.2;
      rPts.push([x, y, isSpec ? 0.99 : 0.05, isSpec ? -0.2 : 0.2, isSpec ? 1.0 : 0.0]);
    }
    drawSegmentedPath(rPts, "micro_marker", 0.9, 32);
  }

  // 6C. Crisp silhouette contour definition on kettle, spout, lid & handle
  // Left & right kettle silhouettes
  for (let side of [-1, 1]) {
    let silPts = [];
    for (let i = 0; i <= 80; i++) {
      let v = i / 80;
      let rx = getBodyRx(v);
      let x = K_CX + side * (rx - 1.5);
      let y = K_TOP_Y + v * K_SPAN_Y;
      silPts.push([x, y, 0.14, 0.1, 0.0]);
    }
    drawSegmentedPath(silPts, "micro_marker", 0.85, 30);
  }

  // Base rim contour & bright rolled rim highlight
  for (let dv of [-0.042, -0.015, 0.0]) {
    let basePts = [];
    let v = 1.0 + dv;
    let rx = getBodyRx(constrain(v, 0, 1));
    let sag = getBodySag(constrain(v, 0, 1));
    let yBase = K_TOP_Y + constrain(v, 0, 1) * K_SPAN_Y;
    for (let i = -40; i <= 40; i++) {
      let u = i / 40;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let isRim = Math.abs(dv + 0.042) < 0.01;
      basePts.push([x, y, isRim ? 0.92 : 0.06, 0.3, isRim ? 0.8 : 0.0]);
    }
    drawSegmentedPath(basePts, "micro_marker", 0.9, 30);
  }

  // --------------------------------------------------------------------------
  // LAYER 7: THICK BLACK ORTHOGONAL GRID BARS & HARD RULED INK LINES
  // --------------------------------------------------------------------------
  brush.noClip();
  brush.noHatch();
  brush.noStroke();

  // 7A. Solid velvety black ink wash across all orthogonal grid bars
  for (let b of blackBars) {
    brush.wash("#100d0c", 252);
    brush.rect(b.x1, b.y1, b.x2 - b.x1, b.y2 - b.y1, "corner");
  }
  brush.noWash();

  // 7B. Dense marker fill along the interior of every black bar for physical ink opacity
  for (let b of blackBars) {
    let w = b.x2 - b.x1;
    let h = b.y2 - b.y1;
    brush.set("chisel_marker", "#0d0b0a", 1.05);
    if (w >= h) {
      // Horizontal bar
      for (let y = b.y1 + 4; y <= b.y2 - 4; y += 5) {
        brush.line(b.x1 + 2, y, b.x2 - 2, y);
      }
    } else {
      // Vertical bar
      for (let x = b.x1 + 4; x <= b.x2 - 4; x += 5) {
        brush.line(x, b.y1 + 2, x, b.y2 - 2);
      }
    }
  }

  // 7C. Hard ruled technical ink lines framing every rectangular panel
  for (let p of panels) {
    // Crisp dark India ink outer ruling on the bar edge
    brush.set("rotring", "#050404", 0.85);
    brush.line(p.x1, p.y1, p.x2, p.y1);
    brush.line(p.x2, p.y1, p.x2, p.y2);
    brush.line(p.x2, p.y2, p.x1, p.y2);
    brush.line(p.x1, p.y2, p.x1, p.y1);

    // Second pass slightly inset (-1px into the bar) for razor-sharp architectural weight
    brush.set("pen", "#090707", 0.65);
    brush.line(p.x1 - 1, p.y1 - 1, p.x2 + 1, p.y1 - 1);
    brush.line(p.x2 + 1, p.y1 - 1, p.x2 + 1, p.y2 + 1);
    brush.line(p.x2 + 1, p.y2 + 1, p.x1 - 1, p.y2 + 1);
    brush.line(p.x1 - 1, p.y2 + 1, p.x1 - 1, p.y1 - 1);
  }
}

