          drawSegmentedPathAnim(kPts, "micro_marker", 1.0, 28, 330000 + knobRowIdx * 389);
        }
        kPts = [];
      }
    }
    if (kPts.length >= 2) {
      drawSegmentedPathAnim(kPts, "micro_marker", 1.0, 28, 330000 + knobRowIdx * 389);
    }
  }

  // 5. RAZOR-SHARP HYPERREAL REFLECTION EDGES, MULLIONS & SPECULARS
  for (let i = 0; i <= 110; i++) {
    let v = (i / 110) * 0.58;
    let rx = getBodyRx(v);
    let sag = getBodySag(v);
    let yBase = K_TOP_Y + v * K_SPAN_Y;

    let specPts = [];
    for (let j = 0; j <= 130; j++) {
      let u = -0.96 + (1.92 * j) / 130;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let sc = evaluateSceneAnim(x, y);
      if (sc.part === "kettle_body" && (sc.spec > 0.65 || sc.lum < 0.19)) {
        specPts.push([x, y, sc.lum, sc.warmth, sc.spec]);
      } else {
        if (specPts.length >= 2) {
          drawSegmentedPathAnim(specPts, "micro_marker", 0.95, 32, 350000 + i * 487);
        }
        specPts = [];
      }
    }
    if (specPts.length >= 2) {
      drawSegmentedPathAnim(specPts, "micro_marker", 0.95, 32, 350000 + i * 487);
    }
  }

  // Spout specular ridge shifts smoothly across the gooseneck
  let sShift = 0.16 * Math.sin(azShift * 1.5);
  let spSpecIdx = 0;
  for (let sBase of [-0.54, -0.50, -0.46, 0.02]) {
    spSpecIdx++;
    let s = sBase + sShift;
    let rPts = [];
    for (let j = 0; j <= 90; j++) {
      let t = (j / 90) * 0.97;
      let sp = getSpoutPoint(t);
      let st = getSpoutTangent(t);
      let r = getSpoutRadius(t);
      let x = sp.x + st.nx * s * r;
      let y = sp.y + st.ny * s * r;
      let isSpec = sBase < -0.2;
      rPts.push([x, y, isSpec ? 0.99 : 0.05, isSpec ? -0.2 : 0.2, isSpec ? 1.0 : 0.0]);
    }
    drawSegmentedPathAnim(rPts, "micro_marker", 0.9, 32, 400000 + spSpecIdx * 353);
  }

  // Left & right kettle silhouettes
  for (let side of [-1, 1]) {
    let silPts = [];
    for (let i = 0; i <= 80; i++) {
      let v = i / 80;
      let rx = getBodyRx(v);
      let x = K_CX + side * (rx - 1.5);
      let y = K_TOP_Y + v * K_SPAN_Y;
      silPts.push([x, y, 0.14, 0.1, 0.0]);
    }
    drawSegmentedPathAnim(silPts, "micro_marker", 0.85, 30, 410000 + (side < 0 ? 100 : 200));
  }

  // Base rim contour & bright rolled rim highlight
  let rimIdx = 0;
  for (let dv of [-0.042, -0.015, 0.0]) {
    rimIdx++;
    let basePts = [];
    let v = 1.0 + dv;
    let rx = getBodyRx(constrain(v, 0, 1));
    let sag = getBodySag(constrain(v, 0, 1));
    let yBase = K_TOP_Y + constrain(v, 0, 1) * K_SPAN_Y;
    for (let i = -40; i <= 40; i++) {
      let u = i / 40;
      let x = K_CX + u * rx;
      let y = yBase + sag * Math.sqrt(Math.max(0, 1 - u * u));
      let isRim = Math.abs(dv + 0.042) < 0.01;
      basePts.push([x, y, isRim ? 0.92 : 0.06, 0.3, isRim ? 0.8 : 0.0]);
    }
    drawSegmentedPathAnim(basePts, "micro_marker", 0.9, 30, 420000 + rimIdx * 271);
  }

  // Soft ease-in blend with the exact still on the first two moving frames
  if (frameCount <= 4) {
    let blendAlpha = frameCount === 3 ? 115 : 48;
    push();
    tint(255, blendAlpha);
    image(stillImg, 0, 0);
    pop();
  }

  // 6. THICK BLACK ORTHOGONAL GRID BARS & HARD RULED INK LINES (SEEDED)
  brush.noClip();
  brush.noHatch();
  brush.noStroke();

  for (let i = 0; i < blackBars.length; i++) {
    let b = blackBars[i];
    randomSeed(500000 + i * 31);
    noiseSeed(500000 + i * 31);
    brush.wash("#100d0c", 252);
    brush.rect(b.x1, b.y1, b.x2 - b.x1, b.y2 - b.y1, "corner");
  }
  brush.noWash();

  for (let i = 0; i < blackBars.length; i++) {
    let b = blackBars[i];
    let w = b.x2 - b.x1;
    let h = b.y2 - b.y1;
    randomSeed(510000 + i * 43);
    noiseSeed(510000 + i * 43);
    brush.set("chisel_marker", "#0d0b0a", 1.05);
    if (w >= h) {
      for (let y = b.y1 + 4; y <= b.y2 - 4; y += 5) {
        brush.line(b.x1 + 2, y, b.x2 - 2, y);
      }
    } else {
      for (let x = b.x1 + 4; x <= b.x2 - 4; x += 5) {
        brush.line(x, b.y1 + 2, x, b.y2 - 2);
      }
    }
  }

  for (let i = 0; i < panels.length; i++) {
    let p = panels[i];
    randomSeed(520000 + i * 59);
    noiseSeed(520000 + i * 59);
    brush.set("rotring", "#050404", 0.85);
    brush.line(p.x1, p.y1, p.x2, p.y1);
    brush.line(p.x2, p.y1, p.x2, p.y2);
    brush.line(p.x2, p.y2, p.x1, p.y2);
    brush.line(p.x1, p.y2, p.x1, p.y1);

    brush.set("pen", "#090707", 0.65);
    brush.line(p.x1 - 1, p.y1 - 1, p.x2 + 1, p.y1 - 1);
    brush.line(p.x2 + 1, p.y1 - 1, p.x2 + 1, p.y2 + 1);
    brush.line(p.x2 + 1, p.y2 + 1, p.x1 - 1, p.y2 + 1);
    brush.line(p.x1 - 1, p.y2 + 1, p.x1 - 1, p.y1 - 1);
  }
}

// ============================================================================
// FILM LOOP
// ============================================================================

function draw() {
  if (frameCount > TOTAL_FRAMES + 2) return;

  // Frame 1: exact original draw() call with zero additions
  if (frameCount === 1) {
    paintStill();
    return;
  }

  // Frame 2: re-run exact seeded still so whether the harness captures frameCount 1 or 2 as frame 0,
  // it is 100% pixel-for-pixel identical to the still without any get() call during the frame
  if (frameCount === 2) {
    randomSeed(4271);
    noiseSeed(4271);
    background("#f6efe2");
    paintStill();
    return;
  }

  // Capture the finished still canvas at the start of frameCount 3 before painting motion
  if (!stillImg) {
    stillImg = get();
  }

  // Normalized film progress u in (0, 1] starting from zero offset
  let u = constrain((frameCount - 2) / (TOTAL_FRAMES - 1), 0, 1);
  let ease = 0.38 * u + 0.62 * (u * u * (3 - 2 * u));

  // Studio environment slides across the 3D chrome surfaces
  azShift = 0.88 * ease;
  elShift = 0.032 * Math.sin(ease * Math.PI);
  wavePhase = 2.6 * ease;

  paintAnimatedReflections();
}

