// ============================================================================
// DRAWING HELPERS
// ============================================================================

function fillPoly(pts, col, opacity, bleed = 0.2, tex = 0.5, border = 0.35, curv = 0.15, dir = "out") {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washPoly(pts, col, opacity, curv = 0.05) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokeSpline(pts, bName, col, weight = 1, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

function strokeLine(x1, y1, x2, y2, bName, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function wavyRibbon(yTop, yBot, amp = 14, steps = 16, seedOff = 0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = -40 + t * 1280;
    let n = (noise(t * 3.2 + seedOff, yTop * 0.01) - 0.5) * 2 * amp;
    pts.push([x, yTop + n]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let x = -40 + t * 1280;
    let n = (noise(t * 3.2 + seedOff + 9.7, yBot * 0.01) - 0.5) * 2 * amp;
    pts.push([x, yBot + n]);
  }
  return pts;
}

