      [w.x + w.w, w.y + w.h], [w.x, w.y + w.h]
    ], "#080f1c", 230, 0.01);
    // Faint sky reflection on upper glass pane
    washPoly([
      [w.x + 2, w.y + 2], [w.x + w.w - 2, w.y + 2],
      [w.x + w.w - 2, w.y + w.h * 0.45], [w.x + 2, w.y + w.h * 0.45]
    ], "#1d2f4a", 120, 0.01);
    strokeLine(w.x, w.y + w.h, w.x + w.w, w.y + w.h, "cpencil", "#2a3e5c", 0.5);
  }

  // Fine architectural hatching over building shadows
  brush.noFill();
  brush.noWash();
  brush.noStroke();
  brush.hatchStyle("2B", "#080d17", 0.7);
  brush.hatch(9, 90, { rand: 0.08 });
  brush.rect(335, 745, 257, 170, "corner");
  brush.rect(625, 756, 240, 120, "corner");
  brush.noHatch();

  // ==========================================================================
  // THE SINGLE WARM TUNGSTEN WINDOW (x = 420, y = 838, w = 34, h = 52)
  // ==========================================================================
  let wx = 420, wy = 838, ww = 34, wh = 52;

  // 1. Soft atmospheric tungsten bloom radiating into the dark blue facade
  let haloOuter = [];
  let haloMid = [];
  let haloInner = [];
  for (let a = 0; a < 360; a += 24) {
    let cx = wx + ww * 0.5;
    let cy = wy + wh * 0.5;
    haloOuter.push([cx + cos(a) * 82, cy + sin(a) * 76]);
    haloMid.push([cx + cos(a) * 48, cy + sin(a) * 46]);
    haloInner.push([cx + cos(a) * 28, cy + sin(a) * 34]);
  }
  fillPoly(haloOuter, "#ff841a", 28, 0.45, 0.4, 0.15, 0.3);
  fillPoly(haloMid, "#ff9e2c", 48, 0.38, 0.35, 0.2, 0.3);
  fillPoly(haloInner, "#ffbe4f", 75, 0.3, 0.3, 0.2, 0.25);

  // 2. Warm tungsten spill onto window recess, sill, and adjacent courtyard roof below
  washPoly([
    [wx - 4, wy + wh], [wx + ww + 4, wy + wh],
    [wx + ww + 8, wy + wh + 6], [wx - 8, wy + wh + 6]
  ], "#e87a1c", 210, 0.02);
  fillPoly([
    [wx - 22, wy + wh + 25], [wx + ww + 22, wy + wh + 25],
    [wx + ww + 38, wy + wh + 42], [wx - 38, wy + wh + 42]
  ], "#d46b19", 45, 0.35, 0.4, 0.2, 0.2);

  // 3. Window interior planes (warm amber wall, bright incandescent upper core)
  washPoly([
    [wx, wy], [wx + ww, wy], [wx + ww, wy + wh], [wx, wy + wh]
  ], "#f58c1f", 250, 0.01);

  washPoly([
    [wx + 2, wy + 2], [wx + ww - 2, wy + 2],
    [wx + ww - 2, wy + wh * 0.68], [wx + 2, wy + wh * 0.68]
  ], "#ffb73b", 245, 0.01);

  washPoly([
    [wx + 4, wy + 3], [wx + ww - 4, wy + 3],
    [wx + ww - 5, wy + wh * 0.42], [wx + 5, wy + wh * 0.42]
  ], "#ffdc73", 245, 0.02);

  // Incandescent ceiling/lamp core inside upper room
  washPoly([
    [wx + 9, wy + 5], [wx + ww - 9, wy + 5],
    [wx + ww - 10, wy + 18], [wx + 10, wy + 18]
  ], "#fff5cc", 250, 0.05);

  // Subtle warm interior curtain/wall edge on left side of window
  washPoly([
    [wx + 1, wy + 2], [wx + 7, wy + 2],
    [wx + 5, wy + wh - 2], [wx + 1, wy + wh - 2]
  ], "#c95b12", 215, 0.02);

  // 4. Crisp window frame, sash meeting rail, and vertical muntin bar
  // Masonry reveal illuminated on right & bottom
  strokeLine(wx + ww + 1, wy, wx + ww + 1, wy + wh + 1, "cpencil", "#ffae42", 0.9);
  strokeLine(wx - 2, wy + wh + 1, wx + ww + 2, wy + wh + 1, "cpencil", "#ffcf70", 1.1);
  strokeLine(wx, wy, wx + ww, wy, "pen", "#241205", 0.9);
  strokeLine(wx, wy, wx, wy + wh, "pen", "#241205", 0.9);
  strokeLine(wx + ww, wy, wx + ww, wy + wh, "pen", "#241205", 0.8);
  // Horizontal sash meeting rail
  strokeLine(wx, wy + wh * 0.48, wx + ww, wy + wh * 0.48, "rotring", "#2b1506", 1.35);
  strokeLine(wx + 1, wy + wh * 0.48 + 2, wx + ww - 1, wy + wh * 0.48 + 2, "cpencil", "#ffdf85", 0.65);
  // Vertical muntin
  strokeLine(wx + ww * 0.5, wy, wx + ww * 0.5, wy + wh, "rotring", "#2b1506", 0.95);
}

function drawWaterTower(cx, topY) {
