function drawAntenna(x, baseY, h) {
  let topY = baseY - h;
  strokeLine(x, baseY, x, topY, "rotring", "#1b283d", 0.75);
  for (let i = 0; i < 4; i++) {
    let y = topY + 6 + i * 11;
    let w = 16 - i * 2.2;
    strokeLine(x - w, y, x + w, y, "rotring", "#24334d", 0.55);
