  // Main shirt silhouette: left sleeve, torso, curved front hem, right sleeve
  let shirtBody = [
    // Left shoulder at Pin 0
    [205, 252],
    // Upper chest catenary into collar
    [238, 268], [268, 278],
    // Open V at throat
    [310, 292], [335, 314], [360, 294],
    // Right neck to Pin 1
    [398, 282], [434, 277], [465, 272],
