    [488, 535], [476, 445], [466, 392],
    // Right torso side seam down to shirttail slit
    [464, 485], [465, 595], [468, 722],
    // Curved front shirttail hem
    [428, 762], [382, 779], [335, 784], [285, 776], [235, 754], [190, 714],
    // Left torso side seam up to left armpit
    [195, 595], [198, 485], [202, 382],
    // Left inner sleeve down to left cuff
    [188, 440], [176, 535], [168, 616],
    // Left barrel cuff
    [164, 662], [114, 650], [120, 602],
    // Left sleeve outer edge up to Pin 0
    [126, 540], [136, 448], [154, 355], [180, 296]
  ];

  // Solid base wash in luminous twilight cerulean-slate
  washPoly(shirtBody, "#78a1c7", 242, 0.08);

  // Watercolor tonal zones on the shirt:
  // 1. Bright ice-cerulean zenith light on upper shoulders, yoke, and upper sleeve ridges
  fillPoly([
    [180, 296], [205, 252], [268, 278], [335, 314], [398, 282],
    [465, 272], [495, 312], [466, 415], [335, 435], [202, 405]
  ], "#cae6fa", 135, 0.28, 0.45, 0.25, 0.2);

  // 2. Warm apricot subsurface translucency filtering through single-layer lower hem & cuffs
  fillPoly([
    [192, 655], [335, 675], [466, 665], [468, 722],
    [415, 768], [335, 784], [245, 758], [190, 714]
  ], "#ebb391", 118, 0.34, 0.45, 0.25, 0.22);

  fillPoly([
    [116, 580], [170, 590], [164, 662], [114, 650]
  ], "#dea485", 85, 0.28, 0.4, 0.25, 0.15);

  fillPoly([
    [496, 590], [550, 582], [554, 666], [504, 676]
  ], "#dea485", 85, 0.28, 0.4, 0.25, 0.15);

  // 3. Deep slate-cerulean shadow masses in the lower-mid torso valleys and inner sleeves
  fillPoly([
    [202, 382], [258, 410], [252, 685], [192, 680]
  ], "#395a82", 125, 0.28, 0.55, 0.35, 0.2);

  fillPoly([
    [405, 415], [466, 392], [466, 685], [412, 688]
  ], "#35557d", 130, 0.28, 0.55, 0.35, 0.2);

  // ==========================================================================
  // SCULPTING EXACT DRAPERY FOLDS ON THE SHIRT TORSO
  // ==========================================================================
  // 8 vertical/catenary fold columns across the torso from x = 200 to 464
  let foldCols = [
    { xTop: 212, xMid: 206, xBot: 202, w: 22, light: "#bfe0f7", dark: "#2d4b70", apricot: "#dba488" },
    { xTop: 242, xMid: 236, xBot: 228, w: 28, light: "#d4ecfc", dark: "#264266", apricot: "#e6b497" },
    { xTop: 278, xMid: 272, xBot: 264, w: 30, light: "#e0f2ff", dark: "#2b486e", apricot: "#ecc0a4" },
    { xTop: 312, xMid: 308, xBot: 302, w: 26, light: "#d2ebfc", dark: "#315078", apricot: "#e3b093" },
    { xTop: 356, xMid: 358, xBot: 354, w: 28, light: "#daf0ff", dark: "#29466b", apricot: "#ebb99c" },
    { xTop: 392, xMid: 396, xBot: 394, w: 30, light: "#cbe6fa", dark: "#243f63", apricot: "#e0ad90" },
    { xTop: 426, xMid: 432, xBot: 430, w: 26, light: "#d6eeff", dark: "#2b486e", apricot: "#e6b496" },
    { xTop: 452, xMid: 456, xBot: 456, w: 20, light: "#b8daf2", dark: "#223b5c", apricot: "#d49c80" }
  ];

  for (let f of foldCols) {
    let yStart = 290;
    let yEnd = 768 - abs(f.xBot - 335) * 0.38;
    // Across each fold column (-1 to +1), interpolate shadow trough -> lit ridge -> terminator
    for (let s = -4; s <= 4; s++) {
      let u = s / 4; // -1 to 1
      let dxTop = u * f.w * 0.38;
      let dxMid = u * f.w * 0.52;
      let dxBot = u * f.w * 0.58;

      let p1 = [f.xTop + dxTop, yStart + abs(u) * 8, 0.5];
      let p2 = [f.xMid + dxMid, (yStart + yEnd) * 0.48, 0.95];
      let p3 = [f.xBot + dxBot, yEnd - 45, 0.85];
      let p4 = [f.xBot + dxBot * 1.04, yEnd, 0.4];

      if (s <= -2) {
        // Deep fold trough
        strokeSpline([p1, p2, p3, p4], "drapery", f.dark, 1.15, 0.45);
      } else if (s >= -1 && s <= 1) {
        // Sky-lit cerulean ridge on upper/mid shirt
        strokeSpline([p1, p2, p3], "drapery", f.light, 1.25 - abs(s) * 0.25, 0.45);
        // Warm apricot translucency near bottom hem
        strokeSpline([p2, p3, p4], "drapery", f.apricot, 1.0, 0.45);
      } else {
        // Cool cerulean midtone transition
        strokeSpline([p1, p2, p3, p4], "drapery", "#5680ab", 0.95, 0.45);
      }
    }
    // Fine graphite contour crease in the deepest trough
    strokeSpline([
      [f.xTop - f.w * 0.36, yStart + 15, 0.6],
      [f.xMid - f.w * 0.48, (yStart + yEnd) * 0.5, 1.0],
      [f.xBot - f.w * 0.52, yEnd - 12, 0.3]
    ], "crease", "#1e3554", 0.85, 0.45);
  }

  // Sweeping catenary tension folds between Pin 0 and Pin 1 across the upper chest
  for (let k = 0; k < 5; k++) {
    let sag = 315 + k * 28;
    strokeSpline([
      [210 + k * 8, 262 + k * 12, 0.9],
      [275, sag - 6, 0.8],
      [335, sag + 14, 1.1],
      [395, sag - 2, 0.8],
      [460 - k * 8, 280 + k * 12, 0.9]
    ], "drapery", k % 2 === 0 ? "#def1ff" : "#34557d", 0.95, 0.5);
  }

  // ==========================================================================
  // CLOTHESPIN PRESSURE CREASES (Radiating from Pin 0 and Pin 1)
  // ==========================================================================
  drawPinchCreases(205, 252, [
    [162, 345], [178, 375], [198, 410], [218, 425], [242, 395], [268, 355], [285, 315]
  ], "#eaf6ff", "#1c3352");

  drawPinchCreases(465, 272, [
    [390, 325], [412, 365], [435, 410], [456, 430], [478, 415], [498, 380], [514, 345]
  ], "#eaf6ff", "#1c3352");

  // ==========================================================================
  // LEFT AND RIGHT SLEEVES (Cylindrical folds, armhole seams, buttoned cuffs)
  // ==========================================================================
  // Left sleeve folds
  for (let i = 0; i < 5; i++) {
    let t = i / 4;
    let sx1 = lerp(182, 204, t);
    let sy1 = lerp(290, 375, t);
    let sx2 = lerp(132, 182, t);
    let sy2 = 475;
    let sx3 = lerp(120, 166, t);
    let sy3 = 605;
    let col = i < 2 ? "#d8effc" : (i === 2 ? "#6e99c2" : "#274366");
    strokeSpline([[sx1, sy1, 0.7], [sx2, sy2, 1.0], [sx3, sy3, 0.8]], "drapery", col, 1.1, 0.45);
  }
  // Left sleeve crease lines
  strokeSpline([[195, 275, 1.0], [156, 455, 0.9], [142, 605, 0.5]], "crease", "#213a59", 0.9, 0.45);
  strokeSpline([[184, 295, 0.9], [142, 455, 1.0], [128, 602, 0.6]], "crease", "#e8f6ff", 0.95, 0.45);
  // Left armhole double-stitched seam
  strokeSpline([[205, 254], [206, 322], [202, 382]], "cpencil", "#2b476b", 0.85, 0.35);
  strokeSpline([[208, 255], [209, 322], [205, 382]], "cpencil", "#d8eefc", 0.65, 0.35);

  // Left barrel cuff (x = 114..168, y = 602..662)
  washPoly([[120, 602], [168, 616], [164, 662], [114, 650]], "#678fb8", 240, 0.04);
  // Cuff interior dark oval opening
  washPoly([[114, 650], [139, 646], [164, 662], [138, 666]], "#1a2d47", 245, 0.2);
