function drawSingleSock(s) {
  let poly = s.heelSide === "left" ? [
    s.cuffL, s.cuffR, s.ankleR, s.instep, s.toeTop, s.toeTip, s.toeBot, s.heelBot, s.heelApex, s.ankleL
  ] : [
    s.cuffL, s.cuffR, s.ankleR, s.heelApex, s.heelBot, s.toeBot, s.toeTip, s.toeTop, s.instep, s.ankleL
  ];

  // Base cerulean-white knit wash
  washPoly(poly, "#86afd4", 244, 0.18);

  // Sky-lit highlight on upper cuff and instep ridge
  fillPoly([
    s.cuffL, s.cuffR, s.instep, s.ankleL
  ], "#d8effc", 135, 0.25, 0.45, 0.25, 0.2);

  // Shadow core along underside of foot and lower heel
  fillPoly([
    s.ankleL, s.heelApex, s.heelBot, s.toeBot, s.toeTip, s.instep
  ], "#34547a", 125, 0.25, 0.5, 0.3, 0.2);

  // Contrasting slate-blue heel pouch & toe cap (classic children's sock design)
  let heelPatch = [
    [lerp(s.ankleL[0], s.ankleR[0], s.heelSide === "left" ? 0.35 : 0.65),
     lerp(s.ankleL[1], s.heelBot[1], 0.45)],
    s.heelSide === "left" ? s.ankleL : s.ankleR,
    s.heelApex,
    s.heelBot
  ];
  washPoly(heelPatch, "#2c486b", 230, 0.25);

  let toePatch = [
    [lerp(s.instep[0], s.toeTop[0], 0.68), lerp(s.instep[1], s.toeTop[1], 0.68)],
    s.toeTop, s.toeTip, s.toeBot,
    [lerp(s.heelBot[0], s.toeBot[0], 0.68), lerp(s.heelBot[1], s.toeBot[1], 0.68)]
  ];
  washPoly(toePatch, "#2c486b", 230, 0.25);

  // Two woven sport stripes below the cuff edge
  for (let st = 0; st < 2; st++) {
    let t1 = 0.22 + st * 0.16;
    let t2 = t1 + 0.09;
    let p1 = [lerp(s.cuffL[0], s.ankleL[0], t1), lerp(s.cuffL[1], s.ankleL[1], t1)];
    let p2 = [lerp(s.cuffR[0], s.ankleR[0], t1), lerp(s.cuffR[1], s.ankleR[1], t1)];
    let p3 = [lerp(s.cuffR[0], s.ankleR[0], t2), lerp(s.cuffR[1], s.ankleR[1], t2)];
    let p4 = [lerp(s.cuffL[0], s.ankleL[0], t2), lerp(s.cuffL[1], s.ankleL[1], t2)];
    washPoly([p1, p2, p3, p4], st === 0 ? s.stripe1 : s.stripe2, 225, 0.05);
  }

  // Vertical elastic knit ribbing on the cuff (top 55% of ankle tube)
  let ribs = s.isTiny ? 7 : 10;
  for (let r = 0; r <= ribs; r++) {
    let u = r / ribs;
    let x1 = lerp(s.cuffL[0], s.cuffR[0], u);
    let y1 = lerp(s.cuffL[1], s.cuffR[1], u);
    let x2 = lerp(s.ankleL[0], s.ankleR[0], u);
    let y2 = lerp(s.ankleL[1], s.ankleR[1], u);
    let xm = lerp(x1, x2, 0.58);
    let ym = lerp(y1, y2, 0.58);
    let col = r % 2 === 0 ? "#243d5e" : "#e3f4ff";
    strokeLine(x1, y1, xm, ym, "cpencil", col, 0.72);
  }

  // Clothespin radial pinch creases from (pinX, pinY)
  for (let k = -2; k <= 2; k++) {
    let tx = lerp(s.ankleL[0], s.ankleR[0], 0.5) + k * 6;
    let ty = lerp(s.ankleL[1], s.ankleR[1], 0.5) + abs(k) * 4;
    strokeSpline([
      [s.pinX, s.pinY + 3, 1.1],
      [lerp(s.pinX, tx, 0.5), lerp(s.pinY, ty, 0.5), 0.8],
      [tx, ty, 0.2]
    ], "crease", k % 2 === 0 ? "#1f3654" : "#eaf6ff", 0.85, 0.35);
  }

  // Soft cylindrical modeling & fuzzy cotton grain on foot
  strokeSpline([
    s.cuffL, s.ankleL,
    s.heelSide === "left" ? s.heelApex : s.instep,
    s.toeTop
  ], "drapery", "#dff1ff", 0.95, 0.45);

  strokeSpline([
    s.cuffR, s.ankleR,
    s.heelSide === "right" ? s.heelApex : s.instep,
    s.toeBot
  ], "drapery", "#213857", 0.95, 0.45);

  // Warm apricot horizon rim light along the bottom curve of the sole and heel
  strokeSpline([s.heelBot, s.toeBot, s.toeTip], "cpencil", "#ebad88", 0.9, 0.4);
  // Crisp sky-lit top cuff rim
  strokeLine(s.cuffL[0], s.cuffL[1], s.cuffR[0], s.cuffR[1], "cpencil", "#f2faff", 1.0);
}

