function drawCtxPoly(ctx, pts, ox = 0, oy = 0) {
  ctx.beginPath();
  for (let i = 0; i < pts.length; i++) {
    if (i === 0) ctx.moveTo(pts[i][0] - ox, pts[i][1] - oy);
    else ctx.lineTo(pts[i][0] - ox, pts[i][1] - oy);
  }
  ctx.closePath();
}

function extractGarmentLayer(stCanvas, box, poly, pins) {
  let pg = createGraphics(box.w, box.h);
  let ctx = pg.drawingContext;

  let mG = createGraphics(box.w, box.h);
  let mCtx = mG.drawingContext;
  mCtx.fillStyle = "#ffffff";
  mCtx.strokeStyle = "#ffffff";
  mCtx.lineJoin = "round";
  mCtx.lineCap = "round";
  for (let lw of [7, 4, 1.5]) {
    mCtx.globalAlpha = lw === 1.5 ? 1.0 : 0.45;
    mCtx.lineWidth = lw;
    drawCtxPoly(mCtx, poly, box.x, box.y);
    mCtx.fill();
    mCtx.stroke();
  }

  ctx.drawImage(stCanvas, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);
  // Soften static pin lower prongs on the cloth layer so tilting pins never show double edges
  for (let p of pins) {
    ctx.drawImage(stCanvas, p.x + 8, p.y + 4, 6, 16, p.x - box.x - 6, p.y - box.y, 12, 17);
  }
  ctx.globalCompositeOperation = "destination-in";
  ctx.drawImage(mG.canvas || mG.elt, 0, 0);
  ctx.globalCompositeOperation = "source-over";
  return pg;
}

// Piecewise-linear static clothesline Y for any X
function ropeStaticY(x) {
  let nodes = [
    [58, 206], [130, 232], [205, 252], [335, 267], [465, 272],
    [530, 279], [595, 278], [715, 282], [835, 274], [885, 273],
    [935, 266], [985, 264], [1035, 258], [1078, 256], [1120, 251], [1220, 238]
  ];
  for (let i = 0; i < nodes.length - 1; i++) {
    if (x <= nodes[i + 1][0]) {
      let u = constrain((x - nodes[i][0]) / (nodes[i + 1][0] - nodes[i][0]), 0, 1);
      return lerp(nodes[i][1], nodes[i + 1][1], u);
    }
  }
  return 238;
}

function lineDisp(x, t, env) {
  let u = constrain((x - 58) / (1220 - 58), 0, 1);
  let span = sin(u * 180);
  let dy = env * span * (4.2 * sin(t * 420 - u * 240) + 2.2 * cos(t * 780 + u * 160));
  let dx = env * span * (2.2 * sin(t * 420 - u * 180 + 40));
  return { dx, dy };
}

function shirtDisp(x, v, t, env) {
  let ld = lineDisp(x, t, env);
  let vf = pow(v, 1.32);

  // Travelling wind waves across torso and sleeves
  let w1 = sin(t * 450 - (x - 115) * 0.85 - v * 155);
  let w2 = cos(t * 820 - (x - 115) * 1.5 - v * 210);
  let dx = ld.dx + env * vf * (13.5 + 14.5 * w1 + 5.0 * w2);
  let dy = ld.dy + env * pow(v, 1.18) * (-7.5 - 5.0 * sin(t * 380) + 10.5 * sin(t * 480 - (x - 180) * 1.1 - v * 95) + 4.0 * cos(t * 860 - x * 1.7));

  // Extra free-sleeve whip below the armpits (v > 0.24)
  let vArm = pow(max(0, (v - 0.24) / 0.76), 1.25);
  if (x < 192 && vArm > 0) {
    let wL = constrain((192 - x) / 22, 0, 1) * vArm;
    dx += env * wL * (8.5 * sin(t * 540 - v * 120 + 35));
    dy += env * wL * (-5.5 * abs(sin(t * 270 + 20)) - 4.5 * cos(t * 540 - v * 120));
  } else if (x > 468 && vArm > 0) {
    let wR = constrain((x - 468) / 22, 0, 1) * vArm;
    dx += env * wR * (9.0 + 9.5 * sin(t * 510 - v * 130 - 45));
    dy += env * wR * (-6.5 * abs(sin(t * 255 - 25)) + 4.5 * sin(t * 510 - v * 130));
  }
  return { x: x + dx, y: lerp(ropeStaticY(x) - 3, 798, v) + dy, w1 };
}

function towelDisp(x, v, t, env) {
  let ld = lineDisp(x, t, env);
  let uCat = constrain((x - 595) / 240, 0, 1);
  let catSag = env * 3.2 * sin(uCat * 180) * (0.5 + 0.5 * sin(t * 460 - 30));
  let vf = pow(v, 1.28);

  let w1 = sin(t * 420 - (x - 575) * 1.05 - v * 165);
  let w2 = sin(t * 790 - (x - 575) * 1.85 - v * 220);
  let dx = ld.dx + env * vf * (14.5 + 15.5 * w1 + 5.5 * w2);
  let dy = ld.dy + catSag * (1 - v * 0.4) + env * pow(v, 1.15) * (-8.5 - 4.5 * sin(t * 370 + 40) + 11.5 * cos(t * 470 - (x - 575) * 1.25 - v * 105) + 4.2 * sin(t * 880 - (x - 575) * 2.1));
  return { x: x + dx, y: lerp(ropeStaticY(x) - 4, 828, v) + dy, w1 };
}

function sockDisp(k, x, v, t, env) {
  let p = PINS[4 + k];
  let ld = lineDisp(p.x, t, env);
  let yTop = p.y - 6;
  let yBot = k === 2 ? 408 : 492;
  let yOrig = lerp(yTop, yBot, v);

  // Pendulum swing around single clothespin + soft foot/toe curl
  let freq = 490 + k * 65;
  let swing = -env * (9.5 + k * 1.2 + (8.5 + k * 1.0) * sin(t * freq - k * 55) + 3.0 * cos(t * (freq * 1.85) + k * 30));
  let flex = -env * pow(v, 1.45) * 6.5 * sin(t * (freq * 1.15) - v * 140 - k * 40);
  let ang = swing + flex;

  let rx = x - p.x;
  let ry = yOrig - p.y;
  let ripple = env * pow(v, 1.2) * 3.2 * sin(t * 720 - v * 180 + k * 50);

  let X = p.x + ld.dx + rx * cos(ang) - ry * sin(ang) + ripple;
  let Y = p.y + ld.dy + rx * sin(ang) + ry * cos(ang);
  return { x: X, y: Y, w1: sin(ang * 3 + v * 90) };
}

function motionDraw(t, still) {
  // Smooth ease-in envelope reaching full strength by t = 0.36s
  let uEnv = constrain(t / 0.36, 0, 1);
  let env = uEnv * uEnv * (3 - 2 * uEnv);

  // 1. Stamp clean sky + city plate over the laundry & clothesline region
  tint(255);
  image(cleanBg, 0, 190, 1200, 650, 0, 190, 1200, 650);

  // 2. Drift sky & cloud bands sideways with the evening breeze
  let skyDrift = env * t * 14;
  // Upper sky horizontal slices (y = 14..195)
  for (let y = 14; y < 194; y += 12) {
    let shift = skyDrift * (0.7 + 0.35 * sin(y * 2.2));
    let s = shift % 1200;
    tint(255, 255, 255, 190);
    image(still, s, y, 1200 - s, 12, 0, y, 1200 - s, 12);
    if (s > 0.5) image(still, 0, y, s, 12, 1200 - s, y, s, 12);
  }
  // Open mid-lower sky right of towel & below socks (x = 865..1200, y = 495..688)
  for (let y = 495; y < 685; y += 12) {
    let shift = constrain(skyDrift * (0.8 + 0.25 * cos(y * 1.8)), 0, 28);
    tint(255, 255, 255, 180);
    image(still, 868 + shift, y, 332 - shift, 12, 868, y, 332 - shift, 12);
  }
  // Soft drifting stratocumulus glaze layer behind the laundry
  tint(255, 255, 255, round(215 * env));
  image(cloudG, skyDrift * 1.15, 0);

  // Restore crisp left iron post top and distant rooftop details over drifting clouds
  tint(255);
  image(still, 22, 184, 62, 70, 22, 184, 62, 70);
  image(still, 94, 718, 48, 50, 94, 718, 48, 50);
  image(still, 950, 668, 120, 65, 950, 668, 120, 65);

  // 3. Draw swaying clothesline from still's rope pixels
  for (let x = 58; x < 1194; x += 6) {
    let yr = ropeStaticY(x);
    let ld = lineDisp(x + 3, t, env);
    image(still, x + ld.dx, yr - 5 + ld.dy, 6.8, 10, x, yr - 5, 6, 10);
  }

  // 4A. Render billowing White Shirt (strip-spine warp)
  let vSegs = [0, 0.24, 0.50, 0.75, 1.0];
  let swShirt = 5;
  for (let sx = 8; sx < SHIRT_BOX.w - 8; sx += swShirt) {
    let worldX = SHIRT_BOX.x + sx + swShirt * 0.5;
    let yTop = ropeStaticY(worldX) - 3;
    let yBot = 798;
    for (let s = 0; s < 4; s++) {
      let v1 = vSegs[s], v2 = vSegs[s + 1];
      let p1 = shirtDisp(worldX, v1, t, env);
      let p2 = shirtDisp(worldX, v2, t, env);
      let sy1 = lerp(yTop, yBot, v1) - SHIRT_BOX.y;
      let sy2 = lerp(yTop, yBot, v2) - SHIRT_BOX.y;
      let dX = p2.x - p1.x, dY = p2.y - p1.y;
      let segLen = sqrt(dX * dX + dY * dY);
      let ang = atan2(-dX, dY);

      // Subtle dynamic sky-light / fold-trough modulation
      let shd = p1.w1 * env * ((v1 + v2) * 0.5);
      tint(constrain(255 + shd * 10, 232, 255), constrain(255 + shd * 8, 238, 255), constrain(255 + shd * 4, 245, 255));

      push();
      translate(p1.x, p1.y);
      rotate(ang);
      image(shirtG, -swShirt * 0.5 - 0.6, -0.6, swShirt + 1.2, segLen + 1.2, sx, sy1, swShirt, sy2 - sy1);
      pop();
    }
  }

  // 4B. Render billowing Striped Towel (strip-spine warp)
  let swTowel = 5;
  for (let sx = 6; sx < TOWEL_BOX.w - 6; sx += swTowel) {
    let worldX = TOWEL_BOX.x + sx + swTowel * 0.5;
    let yTop = ropeStaticY(worldX) - 4;
    let yBot = 828;
    for (let s = 0; s < 4; s++) {
      let v1 = vSegs[s], v2 = vSegs[s + 1];
      let p1 = towelDisp(worldX, v1, t, env);
      let p2 = towelDisp(worldX, v2, t, env);
      let sy1 = lerp(yTop, yBot, v1) - TOWEL_BOX.y;
      let sy2 = lerp(yTop, yBot, v2) - TOWEL_BOX.y;
      let dX = p2.x - p1.x, dY = p2.y - p1.y;
      let segLen = sqrt(dX * dX + dY * dY);
      let ang = atan2(-dX, dY);

      let shd = p1.w1 * env * ((v1 + v2) * 0.5);
      tint(constrain(255 + shd * 12, 230, 255), constrain(255 + shd * 9, 236, 255), constrain(255 + shd * 4, 244, 255));

      push();
      translate(p1.x, p1.y);
      rotate(ang);
      image(towelG, -swTowel * 0.5 - 0.6, -0.6, swTowel + 1.2, segLen + 1.2, sx, sy1, swTowel, sy2 - sy1);
      pop();
    }
  }

  // 4C. Render swinging & flexing Children's Socks
  let sockSegs = [0, 0.35, 0.70, 1.0];
  let swSock = 4;
  for (let k = 0; k < 3; k++) {
    let box = SOCK_CFG[k].box;
    let p = PINS[4 + k];
    let yTop = p.y - 6;
    let yBot = k === 2 ? 408 : 492;
    for (let sx = 4; sx < box.w - 4; sx += swSock) {
      let worldX = box.x + sx + swSock * 0.5;
      for (let s = 0; s < 3; s++) {
        let v1 = sockSegs[s], v2 = sockSegs[s + 1];
        let p1 = sockDisp(k, worldX, v1, t, env);
        let p2 = sockDisp(k, worldX, v2, t, env);
        let sy1 = lerp(yTop, yBot, v1) - box.y;
        let sy2 = lerp(yTop, yBot, v2) - box.y;
        let dX = p2.x - p1.x, dY = p2.y - p1.y;
        let segLen = sqrt(dX * dX + dY * dY);
        let ang = atan2(-dX, dY);

        tint(255);
        push();
        translate(p1.x, p1.y);
        rotate(ang);
        image(sockG[k], -swSock * 0.5 - 0.6, -0.6, swSock + 1.2, segLen + 1.2, sx, sy1, swSock, sy2 - sy1);
        pop();
      }
    }
  }

  // 5. Render the 7 wooden clothespins riding & tilting on the clothesline
  tint(255);
  for (let i = 0; i < PINS.length; i++) {
    let p = PINS[i];
    let ld = lineDisp(p.x, t, env);
    let dAng = 0;
    if (i < 4) {
      dAng = -env * (2.5 + 3.5 * sin(t * 440 - i * 50));
    } else {
      let k = i - 4;
      dAng = -env * (4.5 + 4.5 * sin(t * (490 + k * 65) - k * 55));
    }
    push();
    translate(p.x + ld.dx, p.y + ld.dy);
    rotate(dAng);
    image(pinG[i], -14, -28);
    pop();
  }

  // 6. Pulsing and flickering warm tungsten window glow & parapet reflection
  let pulse = 0.55 + 0.45 * sin(t * 320 - 40);
  let flicker = 0.6 + 0.25 * sin(t * 890) + 0.15 * cos(t * 1620 + 25);
  let glowAmt = env * (0.55 * pulse + 0.45 * flicker);

  let wx = 420, wy = 838, ww = 34, wh = 52;
  let wcx = wx + ww * 0.5, wcy = wy + wh * 0.5;

  push();
  noStroke();
  blendMode(ADD);

  // Concentric warm atmospheric tungsten bloom
  for (let r = 5; r >= 1; r--) {
    let rad = r * 20 * (0.92 + 0.14 * glowAmt);
    fill(255, 145 + r * 12, 35, (14 - r * 2.1) * glowAmt);
    ellipse(wcx, wcy, rad * 2, rad * 1.85);
  }

  // Warm incandescent interior window pulse
  fill(255, 195, 75, 58 * glowAmt);
  rect(wx + 2, wy + 2, ww - 4, wh - 4, 1);
  fill(255, 238, 165, 80 * glowAmt);
  rect(wx + 5, wy + 4, ww - 10, wh * 0.44, 1);

  // Sill spill, courtyard bounce & parapet stone coping reflection
  fill(255, 165, 55, 55 * glowAmt);
  rect(wx - 4, wy + wh, ww + 8, 4, 1);
  fill(235, 130, 38, 22 * glowAmt);
  ellipse(wcx, wy + wh + 32, 74, 16);
  fill(235, 150, 68, 28 * glowAmt);
  ellipse(435, 965, 110, 14);

  blendMode(BLEND);

  // Keep the window sash meeting rail and vertical muntin bar crisp
  fill(43, 21, 6, 215 * env);
  rect(wx, wy + wh * 0.48 - 0.8, ww, 1.8);
  rect(wx + ww * 0.5 - 0.6, wy, 1.3, wh);
  pop();

  tint(255);
}
// ---- harness glue ----
let __still = null;
async function setup() { await __origSetup(); }
function draw() {
  if (frameCount > 48) return;
  if (frameCount === 1) { __origDraw(); __still = get(); if (typeof motionSetup === "function") motionSetup(__still); return; }
  push(); resetMatrix(); image(__still, -width / 2, -height / 2, width, height); pop();
  push(); translate(-width / 2, -height / 2); motionDraw((frameCount - 1) / 24, __still); pop();
}

18-eye:
// MOTION: Iridescent soap-film interference ribbons swirl around Marangoni vortices and drain into billowing black-film plumes across the eye.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

// Hyperrealism in p5.brush:
// Soap film stretched across a bubble wand held right up to a child's eye.
// Marbled marker thin-film interference bands (magenta, brass gold, cyan, sea green)
// pooling into black film at the bottom; crisp coloured-pencil eye distorted behind;
// faint spray of window reflections; out-of-focus kitchen beige background.

const W_CX = 590;
const W_CY = 585;
const W_R_IN = 398;
const W_R_OUT = 452;

const E_CX = 605;
const E_CY = 505;
const I_CX = 608;
const I_CY = 492;
const I_R = 174;
const P_R = 64;

let vortices = [];

// Cached layers & recorded Frame-0 stroke geometry for zero-pop, non-boiling fluid motion
let stillImg = null;
let eyeBackdrop = null;
let savedPoolSwirls = [];
let savedStreamlines = [];
let savedVortexRings = [];
let savedIridescentGlints = [];
let savedTearSparkles = [];
let savedWindowRefl1 = [];
let savedWindowRefl2 = [];
let savedWandShadow = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom translucent marker brushes for marbled soap-film flows (no endpoint blobs)
  brush.add("marbled_marker", {
    type: "marker",
    weight: 9,
    scatter: 0.12,
    opacity: 24,
    spacing: 0.28,
    pressure: [0.3, 1.15, 0.3],
    markerTip: false,
    noise: 0.35
  });

  brush.add("pool_marker", {
    type: "marker",
    weight: 16,
    scatter: 0.18,
    opacity: 38,
    spacing: 0.32,
    pressure: [0.4, 1.25, 0.4],
    markerTip: false,
    noise: 0.45
  });

  brush.add("ribbon_marker", {
    type: "marker",
    weight: 4.5,
    scatter: 0.06,
    opacity: 34,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    markerTip: false,
    noise: 0.25
  });

  brush.add("mist_spray", {
    type: "spray",
    weight: 14,
    scatter: 2.8,
    opacity: 22,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4]
  });

  // Define Marangoni soap-film vortices (concentrated around edges & lower pooling zone)
  vortices = [
    { x: 380, y: 690, r: 165, str: 1.6, dir: 1 },
    { x: 790, y: 670, r: 175, str: 1.7, dir: -1 },
    { x: 580, y: 780, r: 190, str: 1.9, dir: 1 },
    { x: 325, y: 460, r: 140, str: 1.2, dir: -1 },
    { x: 845, y: 440, r: 145, str: 1.25, dir: 1 },
    { x: 470, y: 300, r: 130, str: 0.95, dir: 1 },
    { x: 710, y: 310, r: 135, str: 1.0, dir: -1 },
    { x: 505, y: 655, r: 115, str: 1.3, dir: -1 },
    { x: 695, y: 645, r: 120, str: 1.35, dir: 1 }
  ];
}

// Optical meniscus distortion of the soap film inside the wand
function distortEye(x, y) {
  let dx = x - W_CX;
  let dy = y - W_CY;
  let d = sqrt(dx * dx + dy * dy);
  if (d < W_R_IN) {
    let u = d / W_R_IN;
    // Spherical meniscus magnification + slight rim inflection
    let lensShift = sin(u * 180) * 18 - pow(u, 3) * 14;
    // Subtle fluid thickness wave at the bottom where soap pools
    let poolWave = exp(-pow((y - 760) / 140, 2)) * sin((x - W_CX) * 0.8) * 6;
    let ang = atan2(dy, dx);
    return [
      x + cos(ang) * lensShift + poolWave * 0.4,
      y + sin(ang) * lensShift + abs(poolWave) * 0.7
    ];
  }
  return [x, y];
}

// Upper eyelid margin curve (child's wide open eye)
function upperLidY(x) {
  let t = (x - E_CX) / 310;
  let base = E_CY - 122 + 128 * pow(t, 2) - 18 * pow(t, 3) + 12 * pow(t, 4);
  return base;
}

// Lower eyelid margin curve
function lowerLidY(x) {
  let t = (x - E_CX) / 310;
  let base = E_CY + 78 - 62 * pow(t, 2) - 14 * t + 10 * pow(t, 4);
  return base;
}

// Upper supratarsal eyelid crease
function upperCreaseY(x) {
  let t = (x - E_CX) / 335;
  return E_CY - 178 + 135 * pow(t, 2) - 22 * pow(t, 3);
}

// Scalar field representing soap film thickness / interference order
function filmThickness(x, y) {
  let wx = x;
  let wy = y;

  // Apply rotational displacement from Marangoni vortices
  for (let i = 0; i < vortices.length; i++) {
    let v = vortices[i];
    let dx = wx - v.x;
    let dy = wy - v.y;
    let d2 = dx * dx + dy * dy;
    let r2 = v.r * v.r;
    if (d2 < r2 * 2.8) {
      let factor = v.str * exp(-d2 / (r2 * 0.75)) * 85 * v.dir;
      let a = atan2(dy, dx) + factor;
      let dist = sqrt(d2);
      wx = v.x + cos(a) * dist;
      wy = v.y + sin(a) * dist;
    }
  }

  // Domain-warped Perlin noise for liquid marbling
  let n1 = noise(wx * 0.0032, wy * 0.0032, 1.7);
  let n2 = noise(wx * 0.0065 + n1 * 2.4, wy * 0.0065 - n1 * 2.1, 4.3);
  let n3 = noise(wx * 0.014 - n2 * 1.8, wy * 0.014 + n2 * 1.8, 8.1);

  // Radial distance from wand center (meniscus climbs along rim)
  let rx = x - W_CX;
  let ry = y - W_CY;
  let rNorm = sqrt(rx * rx + ry * ry) / W_R_IN;
  let rimSag = pow(constrain(rNorm, 0, 1), 2.6) * 0.38;

  // Vertical drainage gradient (pooling toward bottom y ~ 980)
  let vGrad = (y - (W_CY - W_R_IN)) / (2 * W_R_IN);

  return vGrad * 1.35 + (n1 - 0.5) * 0.55 + (n2 - 0.5) * 0.32 + (n3 - 0.5) * 0.14 - rimSag;
}

function paintStill() {
  // 1. SOFT OUT-OF-FOCUS KITCHEN BEIGE BACKGROUND & PERIPHERAL SKIN
  background("#e8dec9");
  drawKitchenBackground();

  // 2. CHILD'S EYE & SURROUNDING ORBIT (Crisp Coloured Pencil, Distorted Inside Wand)
  drawEyeUnderpainting();
  drawOrbitalSkinAndCreases();
  drawScleraAndCaruncle();
  drawWetIrisAndPupil();
  drawEyelashes();

  // 3. SOAP FILM: BLACK POOLING ZONE & MARBLED MARKER INTERFERENCE FLOWS
  drawBlackFilmPool();
  drawMarbledMarkerInterference();

  // 4. CRISP RE-EMPHASIS OF EYE HIGHLIGHTS & LASH TIPS SEEN THROUGH FILM
  drawCrispEyeSpeculars();

  // 5. FAINT SPRAY OF WINDOW REFLECTIONS ON THE SOAP FILM
  drawFilmWindowReflections();

  // 6. PLASTIC BUBBLE WAND, WET MENISCUS TEETH & GLOSSY HANDLE
  drawBubbleWand();
}

function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  translate(-width / 2, -height / 2);

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // On Frame 2, build and cache the clean eye backdrop (steps 1 & 2, before soap film) once
  if (!eyeBackdrop) {
    randomSeed(8472);
    noiseSeed(8472);
    background("#e8dec9");
    drawKitchenBackground();
    drawEyeUnderpainting();
    drawOrbitalSkinAndCreases();
    drawScleraAndCaruncle();
    drawWetIrisAndPupil();
    drawEyelashes();
    eyeBackdrop = get();
  }

  // Smooth elapsed fluid time t in [0, ~2.0]: eases in over first 4 frames, then flows steadily
  let f = frameCount - 1;
  let u = f / (TOTAL_FRAMES - 1);
  let t = u * 2.0 * (f / (f + 1.15));

  // Stamp cached background + coloured-pencil eye backdrop
  background("#e8dec9");
  image(eyeBackdrop, 0, 0);

  // Paint living, swirling soap film, speculars, flexing window reflection, and meniscus
  drawBlackFilmPoolAnimated(t);
  drawMarbledMarkerInterferenceAnimated(t);
  drawCrispEyeSpecularsAnimated(t);
  drawFilmWindowReflectionsAnimated(t);
  drawBubbleWandAnimated(t);
}

// =========================================================================
// INCOMPRESSIBLE SOAP-FILM STREAMFUNCTION & ADVECTION INTEGRATOR
// =========================================================================
function soapStreamFunction(x, y, tau) {
  let R = W_R_IN - 5;
  let dx = x - W_CX;
  let dy = y - W_CY;
  let r2 = dx * dx + dy * dy;
  if (r2 >= R * R) return 0;

  let u2 = r2 / (R * R);
  // Boundary factor vanishes quadratically on the circular rim so flow stays inside the wand
  let rimFactor = (1 - u2) * (1 - u2);

  // Soft deflection dome over the central pupil so downward ribbons part around the pupil
  let px = x - I_CX;
  let py = y - I_CY;
  let pDist2 = (px * px + py * py) / ((P_R * 1.32) * (P_R * 1.32));
  let pupilShield = 1 - 0.78 * exp(-pDist2);

  // 1. Gravity drainage down center (vy = -dPsi/dx > 0) + upward return flow along outer rims
  let psiDrain = -58.0 * dx * pupilShield;

  // 2. Swirling Marangoni vortices around the wand
  let psiVort = 0;
  for (let i = 0; i < vortices.length; i++) {
    let v = vortices[i];
    // Subtle orbital breathing of vortex cores
    let vx = v.x + cos(tau * 65 + i * 47) * 14 * v.dir;
    let vy = v.y + sin(tau * 65 + i * 47) * 11;
    let vdx = x - vx;
    let vdy = y - vy;
    let d2 = vdx * vdx + vdy * vdy;
    let vr2 = v.r * v.r * 0.72;
    if (d2 < vr2 * 3.5) {
      let omega = 0.95 * v.str * v.dir;
      psiVort += 0.5 * omega * vr2 * exp(-d2 / vr2);
    }
  }

  // 3. Traveling Marangoni thickness wave across the membrane
  let psiWave = 1450 * sin(x * 1.05 + tau * 95) * cos(y * 0.95 - tau * 80) * pupilShield;

  return rimFactor * (psiDrain + psiVort + psiWave);
}

function fluidVelocity(x, y, tau) {
  let eps = 2.0;
  let vx = (soapStreamFunction(x, y + eps, tau) - soapStreamFunction(x, y - eps, tau)) / (2 * eps);
  let vy = -(soapStreamFunction(x + eps, y, tau) - soapStreamFunction(x - eps, y, tau)) / (2 * eps);
  return [vx, vy];
}

// Advect a point (x0, y0) from tau = 0 to tau = t using 6-step midpoint (RK2) integration
function advectPoint(x0, y0, t) {
  let steps = 6;
  let dt = t / steps;
  let x = x0;
  let y = y0;
  let maxR = W_R_IN - 6;

  for (let s = 0; s < steps; s++) {
    let tau = (s + 0.5) * dt;
    let v1 = fluidVelocity(x, y, tau);
    let mx = x + v1[0] * dt * 0.5;
    let my = y + v1[1] * dt * 0.5;
    let v2 = fluidVelocity(mx, my, tau);
    x += v2[0] * dt;
    y += v2[1] * dt;

    // Safety clamp inside wand rim
    let dx = x - W_CX;
    let dy = y - W_CY;
    let d = sqrt(dx * dx + dy * dy);
    if (d > maxR) {
      x = W_CX + (dx / d) * maxR;
      y = W_CY + (dy / d) * maxR;
    }
  }
  return [x, y];
}

// =========================================================================
// 1. OUT-OF-FOCUS KITCHEN BEIGE BACKGROUND
// =========================================================================
function drawKitchenBackground() {
  brush.noStroke();

  // Soft warm window light patches (upper left & top)
  brush.fill("#f7f1e1", 95);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.35, 0.15);
  brush.circle(190, 180, 260, 0.25);
  brush.circle(470, 110, 210, 0.25);
  brush.circle(110, 480, 190, 0.25);

  // Mid-tone oatmeal and biscuit bokeh (kitchen tiles / cabinets out of focus)
  brush.fill("#d6c5ad", 85);
  brush.fillBleed(0.4, "out");
  brush.circle(980, 220, 280, 0.3);
  brush.circle(150, 880, 260, 0.3);
  brush.circle(1050, 960, 290, 0.3);

  // Deeper warm taupe kitchen shadows for high-contrast backdrop
  brush.fill("#a89379", 80);
  brush.fillBleed(0.45, "out");
  brush.circle(1080, 140, 220, 0.3);
  brush.circle(85, 1080, 240, 0.3);
  brush.circle(960, 1080, 250, 0.3);

  // Out-of-focus child's forehead, temple and cheek extending outside the wand on the right
  brush.fill("#e8c3ac", 105);
  brush.fillBleed(0.38, "out");
  brush.circle(860, 420, 340, 0.22);
  brush.circle(830, 740, 310, 0.22);

  brush.fill("#c99277", 85);
  brush.fillBleed(0.35, "out");
  brush.circle(980, 560, 240, 0.25);
  brush.circle(420, 860, 250, 0.25);

  brush.noFill();

  // Soft out-of-focus atmospheric grain in background
  brush.set("mist_spray", "#fcf7eb", 1.3);
  for (let i = 0; i < 24; i++) {
    let ang = random(360);
    let rad = random(480, 680);
    let x = W_CX + cos(ang) * rad;
    let y = W_CY + sin(ang) * rad;
    brush.line(x - 40, y - 20, x + 40, y + 20);
  }

  // Soft out-of-focus eyebrow arch above the wand rim (top right)
  for (let i = 0; i < 85; i++) {
    let t = i / 85;
    let bx = lerp(430, 980, t);
    let by = 185 - sin(t * 170) * 58 + (t - 0.5) * 40 + random(-14, 14);
    let d = dist(bx, by, W_CX, W_CY);
    if (d > W_R_OUT - 10) {
      brush.set("charcoal", i % 2 === 0 ? "#4a3326" : "#6e4f3d", random(0.35, 0.75));
      let hairAng = -18 + t * 48 + random(-8, 8);
      let len = random(35, 65);
      brush.line(bx, by, bx + cos(hairAng) * len, by + sin(hairAng) * len);
    }
  }
}

// =========================================================================
// 2. CHILD'S EYE (CRISP COLOURED PENCIL)
// =========================================================================
function drawEyeUnderpainting() {
  brush.noStroke();

  // Warm skin tone base inside the wand
  brush.fill("#f0cbb4", 90);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.3, 0.15);
  brush.circle(E_CX, E_CY, 370, 0.12);

  // Orbital shadow under brow & nasal bridge (left side)
  brush.fill("#b57359", 95);
  brush.fillBleed(0.28, "out");
  brush.circle(340, 430, 175, 0.2);
  brush.circle(865, 495, 150, 0.2);
  brush.circle(590, 325, 190, 0.2);

  // Sclera porcelain-ivory wash
  brush.fill("#faf6f0", 180);
  brush.fillBleed(0.08, "in");
  brush.beginShape(0.3);
  for (let x = 300; x <= 900; x += 30) {
    let p = distortEye(x, upperLidY(x));
    brush.vertex(p[0], p[1]);
  }
  for (let x = 900; x >= 300; x -= 30) {
    let p = distortEye(x, lowerLidY(x));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // Iris dark base wash for high contrast
  let ic = distortEye(I_CX, I_CY);
  brush.fill("#1c120c", 210);
  brush.fillBleed(0.04, "in");
  brush.circle(ic[0], ic[1], I_R, 0.04);

  brush.noFill();
}

function drawOrbitalSkinAndCreases() {
  // Contour-following coloured pencil strokes across upper & lower eyelids
  const skinPalette = [
    "#f7dccb", "#ecc6b0", "#dfa185", "#c77b61", "#9e503b", "#63291b"
  ];

  // Upper eyelid & supratarsal fold hatching
  for (let row = 0; row < 48; row++) {
    let v = row / 47; // 0 = lid margin, 1 = high above crease
    for (let seg = 0; seg < 14; seg++) {
      let xStart = lerp(255, 925, seg / 14) + random(-8, 8);
      let xEnd = xStart + random(45, 78);
      let pts = [];
      let steps = 6;
      for (let s = 0; s <= steps; s++) {
        let x = lerp(xStart, xEnd, s / steps);
        let yMargin = upperLidY(x);
        let yCrease = upperCreaseY(x);
        let y = lerp(yMargin - 4, yCrease - 95, v) + sin(s * 45) * 1.5;
        pts.push(distortEye(x, y));
      }

      // Determine tonal value: dark in the crease (v ~ 0.36) and near medial corner
      let creaseDist = abs(v - 0.36);
      let colIdx = 1;
      if (creaseDist < 0.05) colIdx = 5;
      else if (creaseDist < 0.11) colIdx = 4;
      else if (creaseDist < 0.20) colIdx = 3;
      else if (v < 0.18) colIdx = 0; // Plump illuminated tarsal fold
      else colIdx = 2;

      if (xStart < 370 && colIdx < 4) colIdx++; // Nasal shadow

      brush.set("cpencil", skinPalette[colIdx], random(0.35, 0.65));
      brush.spline(pts, 0.4);
    }
  }

  // Crisp dark supratarsal crease line
  for (let pass = 0; pass < 6; pass++) {
    let pts = [];
    for (let x = 275; x <= 905; x += 22) {
      let y = upperCreaseY(x) + random(-2.5, 2.5) + (pass - 2.5) * 1.8;
      pts.push(distortEye(x, y));
    }
    brush.set("cpencil", pass < 3 ? "#2b0f08" : "#5e2518", random(0.45, 0.75));
    brush.spline(pts, 0.5);
  }

  // Lower eyelid & tear trough contour hatching
  for (let row = 0; row < 42; row++) {
    let v = row / 41;
    for (let seg = 0; seg < 13; seg++) {
      let xStart = lerp(275, 910, seg / 13) + random(-8, 8);
      let xEnd = xStart + random(48, 82);
      let pts = [];
      for (let s = 0; s <= 5; s++) {
        let x = lerp(xStart, xEnd, s / 5);
        let yMargin = lowerLidY(x) + 12; // Below wet waterline
        let y = yMargin + v * 195 + pow((x - E_CX) / 320, 2) * v * 45;
        pts.push(distortEye(x, y));
      }

      let col = "#e6b39a";
      if (v < 0.08) col = "#c9746b"; // Pinkish lower lid rim
      else if (v < 0.22) col = "#f5d5c3"; // Illuminated lower lid puff (aegyo-sal)
      else if (v > 0.34 && v < 0.48) col = "#a66356"; // Subtle infraorbital crease
      else if (v >= 0.48) col = "#dfab94";

      brush.set("cpencil", col, random(0.35, 0.6));
      brush.spline(pts, 0.4);
    }
  }

  // Wet lower waterline (mucocutaneous junction)
  for (let pass = 0; pass < 5; pass++) {
    let pts = [];
    for (let x = 305; x <= 885; x += 20) {
      let y = lowerLidY(x) + pass * 2.2;
      pts.push(distortEye(x, y));
    }
    let col = pass === 0 ? "#ffffff" : (pass < 3 ? "#f5b8b8" : "#c76b6d");
    brush.set("cpencil", col, pass === 0 ? 0.55 : 0.45);
    brush.spline(pts, 0.45);
  }
}

function drawScleraAndCaruncle() {
  // Spherical shading of the sclera (porcelain white center, cool blue-violet/rose corners & upper lid shadow)
  for (let i = 0; i < 320; i++) {
    let x = random(310, 885);
    let yTop = upperLidY(x);
    let yBot = lowerLidY(x);
    if (yBot <= yTop + 6) continue;

    let v = random(0.02, 0.98);
    let y = lerp(yTop, yBot, v);

    // Skip inside iris
    if (dist(x, y, I_CX, I_CY) < I_R - 4) continue;

    let ang = atan2(y - E_CY, (x - E_CX) * 0.45);
    let len = random(16, 36);
    let p1 = distortEye(x, y);
    let p2 = distortEye(x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.25);
    let p3 = distortEye(x + cos(ang) * len, y + sin(ang) * len * 0.5);

    // Pick sclera color based on position
    let col = "#fcf9f2";
    let cornerDist = abs(x - E_CX) / 290;
    if (v < 0.16) col = "#635870"; // Cast shadow of upper lid
    else if (v < 0.28) col = "#9c92a8";
    else if (cornerDist > 0.78) col = "#d4afb5"; // Vascular pink at corners
    else if (cornerDist > 0.62) col = "#dfd6e0"; // Cool blue-grey turn of eyeball
    else if (v > 0.86) col = "#e8d5d8";

    brush.set("cpencil", col, random(0.3, 0.55));
    brush.spline([p1, p2, p3], 0.35);
  }

  // Delicate episcleral capillaries at medial & lateral corners
  const veins = [
    [[345, 535], [375, 522], [405, 518], [428, 510]],
    [[375, 522], [398, 534], [420, 538]],
    [[355, 552], [390, 548], [422, 542]],
    [[865, 502], [830, 496], [798, 490], [778, 482]],
    [[830, 496], [805, 512], [785, 518]],
    [[855, 518], [822, 526], [792, 528]]
  ];
  for (let v of veins) {
    let pts = v.map(pt => distortEye(pt[0], pt[1]));
    brush.set("cpencil", "#c95b65", 0.22);
    brush.spline(pts, 0.45);
  }

  // Medial canthus & lacrimal caruncle (fleshy pink tear-duct at left corner)
  for (let i = 0; i < 45; i++) {
    let cx = random(292, 352);
    let cy = random(525, 562);
    let p1 = distortEye(cx, cy);
    let p2 = distortEye(cx + random(8, 18), cy + random(-6, 6));
    let col = i < 15 ? "#8c2b32" : (i < 32 ? "#d46368" : "#f7b2b5");
    brush.set("cpencil", col, random(0.3, 0.55));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Wet glint on caruncle
  for (let i = 0; i < 8; i++) {
    let p = distortEye(random(305, 338), random(536, 550));
    brush.set("cpencil", "#ffffff", 0.45);
    brush.line(p[0], p[1], p[0] + 5, p[1] - 2);
  }
}

function drawWetIrisAndPupil() {
  // Clip iris helper: only draw inside eyelid aperture
  function inAperture(x, y) {
    return y >= upperLidY(x) - 3 && y <= lowerLidY(x) + 3;
  }

  // 1. Deep Limbal Ring & Outer Ciliary Zone
  for (let i = 0; i < 420; i++) {
    let ang = random(360);
    let r1 = random(I_R - 36, I_R - 14);
    let r2 = I_R + random(-3, 2);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang + random(-3, 3)) * r2;
    let y2 = I_CY + sin(ang + random(-3, 3)) * r2;
    if (!inAperture(x1, y1) && !inAperture(x2, y2)) continue;

    let p1 = distortEye(x1, constrain(y1, upperLidY(x1), lowerLidY(x1)));
    let p2 = distortEye(x2, constrain(y2, upperLidY(x2), lowerLidY(x2)));
    let col = i % 3 === 0 ? "#0d0912" : (i % 3 === 1 ? "#1f130d" : "#132629");
    brush.set("cpencil", col, random(0.35, 0.65));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Radial Stroma Fibers (Rich Chestnut, Brass Gold, Honey Amber, Sea-Slate)
  const stromaColors = [
    "#29150b", "#472512", "#6e3d19", "#9c6221",
    "#c98b27", "#ebb644", "#2c4a47", "#436e66", "#f7d56e"
  ];

  for (let i = 0; i < 680; i++) {
    let ang = (i / 680) * 360 + random(-0.6, 0.6);
    let rStart = P_R + random(-2, 18);
    let rEnd = I_R - random(8, 32);

    // Create wavy radial trabeculae curving around crypts
    let waveFreq = random(2, 4);
    let waveAmp = random(-3.5, 3.5);
    let pts = [];
    let valid = true;
    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let r = lerp(rStart, rEnd, t);
      let a = ang + sin(t * 180 * waveFreq) * waveAmp;
      let x = I_CX + cos(a) * r;
      let y = I_CY + sin(a) * r;
      if (!inAperture(x, y)) {
        y = constrain(y, upperLidY(x), lowerLidY(x));
      }
      pts.push(distortEye(x, y));
    }

    // Color distribution: darker at top (under lid shadow), glowing gold/amber in lower half
    let col;
    let isBottom = sin(ang) > -0.15;
    if (!isBottom && sin(ang) < -0.55) {
      col = random(["#140b08", "#26150d", "#1b282b"]);
    } else {
      let pick = random(1);
      if (pick < 0.25) col = "#29150b";
      else if (pick < 0.48) col = "#5c3314";
      else if (pick < 0.68) col = "#9c6221";
      else if (pick < 0.84) col = "#d99b2e";
      else if (pick < 0.93) col = "#355954";
      else col = "#f7d56e";
    }

    brush.set("cpencil", col, random(0.22, 0.45));
    brush.spline(pts, 0.4);
  }

  // 3. Iris Collarette (Jagged luminous golden/amber ring around pupil at r ~ 88..108)
  for (let i = 0; i < 220; i++) {
    let ang = (i / 220) * 360 + random(-1.5, 1.5);
    let rMid = 94 + sin(ang * 14) * 7 + cos(ang * 9) * 5;
    let r1 = rMid - random(8, 22);
    let r2 = rMid + random(8, 24);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang + random(-4, 4)) * r2;
    let y2 = I_CY + sin(ang + random(-4, 4)) * r2;
    if (!inAperture(x1, y1) || !inAperture(x2, y2)) continue;

    let p1 = distortEye(x1, y1);
    let p2 = distortEye(x2, y2);
    let col = sin(ang) < -0.45 ? "#593416" : random(["#e09f2b", "#f7c948", "#ffdf7a", "#b8611a"]);
    brush.set("cpencil", col, random(0.28, 0.48));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 4. Pupillary Ruff (Dark rust-umber inner border around pupil)
  for (let i = 0; i < 140; i++) {
    let ang = (i / 140) * 360;
    let r1 = P_R - 2;
    let r2 = P_R + random(10, 22);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang) * r2;
    let y2 = I_CY + sin(ang) * r2;
    if (!inAperture(x1, y1)) continue;
    let p1 = distortEye(x1, y1);
    let p2 = distortEye(x2, y2);
    brush.set("cpencil", i % 2 === 0 ? "#240d04" : "#4a1f0a", 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5. Velvet-Black Pupil (Dense multi-angle 2B & cpencil hatching)
  let pc = distortEye(I_CX, I_CY);
  brush.noStroke();
  brush.fill("#050408", 245);
  brush.fillBleed(0.01, "in");
  brush.circle(pc[0], pc[1], P_R, 0.02);
  brush.noFill();

  for (let i = 0; i < 160; i++) {
    let a1 = random(360);
    let a2 = a1 + random(130, 230);
    let r = P_R * random(0.75, 1.02);
    let p1 = distortEye(I_CX + cos(a1) * r, I_CY + sin(a1) * r);
    let p2 = distortEye(I_CX + cos(a2) * r, I_CY + sin(a2) * r);
    brush.set("2B", "#07050a", random(0.35, 0.6));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 6. Upper Eyelid Cast Shadow Across Top of Iris & Sclera
  for (let x = 315; x <= 880; x += 4) {
    let yTop = upperLidY(x);
    let shadowDepth = 34 - pow((x - E_CX) / 280, 2) * 18;
    if (shadowDepth > 4) {
      let p1 = distortEye(x, yTop);
      let p2 = distortEye(x + random(-3, 3), yTop + shadowDepth);
      brush.set("cpencil", "#120c18", random(0.35, 0.55));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

function drawEyelashes() {
  // Upper eyelid margin dark tightline
  for (let pass = 0; pass < 5; pass++) {
    let pts = [];
    for (let x = 295; x <= 895; x += 18) {
      pts.push(distortEye(x, upperLidY(x) + (pass - 2) * 1.3));
    }
    brush.set("cpencil", "#120a07", 0.55);
    brush.spline(pts, 0.45);
  }

  // UPPER EYELASHES: Long, curved, slightly wet-clumped child's lashes
  const numUpperClusters = 46;
  for (let c = 0; c < numUpperClusters; c++) {
    let t = c / (numUpperClusters - 1); // 0 = left (medial), 1 = right (lateral)
    let rootX = lerp(318, 888, t) + random(-3, 3);
    let rootY = upperLidY(rootX) + random(-2, 2);

    // Lash length & sweep angle across the eye
    let len = (72 + sin(t * 180) * 58) * random(0.88, 1.12);
    if (t < 0.12) len *= 0.65;
    let baseAng = lerp(-152, -22, t); // Sweeps left on left, straight up in center, right on right

    // Tip target where wet hairs in a cluster converge slightly
    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len - sin(t * 180) * 18;

    // Subtle cast shadow of each lash on the sclera/iris below
    if (t > 0.15 && t < 0.88) {
      let sh1 = distortEye(rootX, rootY + 3);
      let sh2 = distortEye(rootX + cos(baseAng + 18) * (len * 0.32), rootY + 24);
      brush.set("cpencil", "#211829", 0.25);
      brush.line(sh1[0], sh1[1], sh2[0], sh2[1]);
    }

    // 3 to 5 individual hairs per cluster
    let hairs = floor(random(3, 6));
    for (let h = 0; h < hairs; h++) {
      let hOffset = (h - (hairs - 1) / 2) * random(2.8, 4.5);
      let rx = rootX + hOffset;
      let ry = rootY + abs(hOffset) * 0.3;

      // Control points for natural downward-then-upward curl of eyelashes
      let mid1X = lerp(rx, tipX, 0.32) + hOffset * 0.6;
      let mid1Y = lerp(ry, tipY, 0.22) + 14; // dips slightly before curling up
      let mid2X = lerp(rx, tipX, 0.68) + hOffset * 0.25;
      let mid2Y = lerp(ry, tipY, 0.65) + 5;
      let tx = tipX + random(-2.5, 2.5);
      let ty = tipY + random(-2.5, 2.5);

      let pts = [
        distortEye(rx, ry),
        distortEye(mid1X, mid1Y),
        distortEye(mid2X, mid2Y),
        distortEye(tx, ty)
      ];

      let col = h === 0 ? "#0a0605" : (h === 1 ? "#1c110d" : "#2e1c14");
      brush.set("cpencil", col, random(0.32, 0.58));
      brush.spline(pts, 0.5);
    }
  }

  // LOWER EYELASHES: Shorter, delicate downward-sweeping clusters
  const numLowerClusters = 34;
  for (let c = 0; c < numLowerClusters; c++) {
    let t = c / (numLowerClusters - 1);
    let rootX = lerp(335, 875, t) + random(-3, 3);
    let rootY = lowerLidY(rootX) + 9 + random(-1.5, 1.5);

    let len = (32 + sin(t * 180) * 34) * random(0.85, 1.15);
    if (t < 0.12 || t > 0.9) len *= 0.6;
    let baseAng = lerp(138, 42, t);

    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len;

    // Faint shadow on lower lid skin
    let s1 = distortEye(rootX, rootY + 2);
    let s2 = distortEye(tipX + 4, tipY + 6);
    brush.set("cpencil", "#9e6356", 0.2);
    brush.line(s1[0], s1[1], s2[0], s2[1]);

    let hairs = floor(random(2, 4));
    for (let h = 0; h < hairs; h++) {
      let hOff = (h - 1) * 3.2;
      let rx = rootX + hOff;
      let ry = rootY;
      let mx = lerp(rx, tipX, 0.5) + hOff * 0.4;
      let my = lerp(ry, tipY, 0.45) - 5;
      let pts = [
        distortEye(rx, ry),
        distortEye(mx, my),
        distortEye(tipX + random(-2, 2), tipY + random(-2, 2))
      ];
      brush.set("cpencil", h === 0 ? "#170e0b" : "#38231b", random(0.24, 0.42));
      brush.spline(pts, 0.45);
    }
  }
}

// =========================================================================
// 3. SOAP FILM: BLACK POOLING ZONE & MARBLED MARKER INTERFERENCE FLOWS
// =========================================================================
function blackBoundaryYAt(x, t) {
  let dx = (x - W_CX) / W_R_IN;
  let rimClimb = pow(constrain(abs(dx), 0, 1), 2.2) * (195 + t * 22);
  let p1x = 420 - t * 18;
  let p2x = 755 + t * 18;
  let p3x = 585 + sin(t * 85) * 14;
  let plume1 = exp(-pow((x - p1x) / (52 + t * 5), 2)) * (75 + t * 34);
  let plume2 = exp(-pow((x - p2x) / (58 + t * 5), 2)) * (82 + t * 36);
  let plume3 = exp(-pow((x - p3x) / 45, 2)) * (42 + sin(t * 110) * 16);
  let ripple = sin(x * 1.4 - t * 95) * 12 + cos(x * 2.3 + t * 115) * 8;
  return 825 - t * 10 - rimClimb - plume1 - plume2 - plume3 + ripple;
}

function drawBlackFilmPool() {
  savedPoolSwirls = [];

  function blackBoundaryY(x) {
    let dx = (x - W_CX) / W_R_IN;
    let rimClimb = pow(constrain(abs(dx), 0, 1), 2.2) * 195;
    let plume1 = exp(-pow((x - 420) / 52, 2)) * 75;
    let plume2 = exp(-pow((x - 755) / 58, 2)) * 82;
    let plume3 = exp(-pow((x - 585) / 45, 2)) * 42;
    let ripple = sin(x * 1.4) * 12 + cos(x * 2.3) * 8;
    return 825 - rimClimb - plume1 - plume2 - plume3 + ripple;
  }

  // Deep obsidian-black wash at the bottom crescent inside the wand
  brush.noStroke();
  brush.fill("#07060c", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.25, 0.2);
  brush.beginShape(0.35);
  for (let a = 18; a <= 162; a += 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = blackBoundaryY(x);
    let maxY = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, min(y, maxY));
  }
  for (let a = 162; a >= 18; a -= 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noFill();

  // Dense black and midnight-indigo marker swirls pooling in the bottom crescent
  for (let i = 0; i < 145; i++) {
    let aStart = random(20, 160);
    let r = random(W_R_IN - 165, W_R_IN - 6);
    let x = W_CX + cos(aStart) * r;
    let y = W_CY + sin(aStart) * r;
    if (y < blackBoundaryY(x) - 18) continue;

    let pts = [];
    let cx = x;
    let cy = y;
    for (let s = 0; s < 7; s++) {
      pts.push([cx, cy]);
      let tang = atan2(cy - W_CY, cx - W_CX) + 90 + sin(s * 50 + i) * 22;
      cx += cos(tang) * 24;
      cy += sin(tang) * 24;
      if (dist(cx, cy, W_CX, W_CY) > W_R_IN - 4) break;
    }
    if (pts.length >= 3) {
      let col = i % 3 === 0 ? "#050408" : (i % 3 === 1 ? "#110a1c" : "#071a21");
      let w = random(0.7, 1.35);
      brush.set("pool_marker", col, w);
      brush.spline(pts, 0.5);
      savedPoolSwirls.push({
        pts: pts,
        col: col,
        w: w,
        idx: i,
        seed: 11000 + i * 37
      });
    }
  }
}

function drawBlackFilmPoolAnimated(t) {
  randomSeed(9001);
  noiseSeed(9001);
  brush.noStroke();
  brush.fill("#07060c", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.25, 0.2);
  brush.beginShape(0.35);
  for (let a = 18; a <= 162; a += 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = blackBoundaryYAt(x, t);
    let maxY = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, min(y, maxY));
  }
  for (let a = 162; a >= 18; a -= 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noFill();

  for (let k = 0; k < savedPoolSwirls.length; k++) {
    let sw = savedPoolSwirls[k];
    randomSeed(sw.seed);
    noiseSeed(sw.seed);
    let movedPts = [];
    for (let s = 0; s < sw.pts.length; s++) {
      let p = advectPoint(sw.pts[s][0], sw.pts[s][1], t * 0.65);
      movedPts.push(p);
    }
    brush.set("pool_marker", sw.col, sw.w);
    brush.spline(movedPts, 0.5);
  }
}

function drawMarbledMarkerInterference() {
  savedStreamlines = [];
  savedVortexRings = [];

  // Thin-film interference palette: Magenta, Brass Gold, Cyan, Sea Green
  const interferenceBands = [
    { col: "#f2c12e", name: "brass_gold" },
    { col: "#e61973", name: "magenta" },
    { col: "#00b8e6", name: "cyan" },
    { col: "#17b890", name: "sea_green" },
    { col: "#ff5ca8", name: "bright_magenta" },
    { col: "#d49b1a", name: "deep_brass" },
    { col: "#4ce6ff", name: "ice_cyan" },
    { col: "#42e3b8", name: "bright_seagreen" },
    { col: "#9e0b52", name: "deep_magenta" }
  ];

  const numStreamlines = 540;

  for (let i = 0; i < numStreamlines; i++) {
    let ang = random(360);
    let u = random(1);
    let r = W_R_IN * (0.15 + 0.83 * pow(u, 0.68));
    let sx = W_CX + cos(ang) * r;
    let sy = W_CY + sin(ang) * r;

    let eyeDist = dist(sx, sy, I_CX, I_CY);
    if (eyeDist < I_R * 0.82 && random(1) > 0.18) continue;

    let pts = [];
    let cx = sx;
    let cy = sy;
    let steps = floor(random(10, 22));
    let stepLen = random(14, 22);
    let dirSign = random(1) < 0.5 ? 1 : -1;

    for (let s = 0; s < steps; s++) {
      if (dist(cx, cy, W_CX, W_CY) > W_R_IN - 6) break;
      if (dist(cx, cy, I_CX, I_CY) < P_R * 0.75 && s > 2) break;

      pts.push([cx, cy]);

      let eps = 4.0;
      let dfdx = (filmThickness(cx + eps, cy) - filmThickness(cx - eps, cy)) / (2 * eps);
      let dfdy = (filmThickness(cx, cy + eps) - filmThickness(cx, cy - eps)) / (2 * eps);

      let tx = -dfdy * dirSign;
      let ty = dfdx * dirSign;
      let mag = sqrt(tx * tx + ty * ty) + 0.00001;
      tx /= mag;
      ty /= mag;

      let rDist = dist(cx, cy, W_CX, W_CY);
      if (rDist > W_R_IN - 65) {
        let rimAng = atan2(cy - W_CY, cx - W_CX) + 90 * dirSign;
        tx = lerp(tx, cos(rimAng), 0.55);
        ty = lerp(ty, sin(rimAng), 0.55);
      }

      cx += tx * stepLen;
      cy += ty * stepLen + 1.4;
    }

    if (pts.length < 4) continue;

    let midPt = pts[floor(pts.length / 2)];
    let thick = filmThickness(midPt[0], midPt[1]);

    let phase = ((thick * 7.5) % 1.0 + 1.0) % 1.0;
    let bandIdx = floor(phase * interferenceBands.length);
    let col = interferenceBands[bandIdx].col;

    let inPoolZone = midPt[1] > 665;
    let overEye = dist(midPt[0], midPt[1], I_CX, I_CY) < I_R * 1.15;

    let bName;
    let w;
    if (overEye) {
      bName = "ribbon_marker";
      w = random(0.45, 0.85);
    } else if (inPoolZone) {
      bName = "pool_marker";
      w = random(0.65, 1.25);
    } else {
      bName = "marbled_marker";
      w = random(0.55, 1.15);
    }

    brush.set(bName, col, w);
    brush.spline(pts, 0.55);

    savedStreamlines.push({
      pts: pts,
      brushName: bName,
      col: col,
      w: w,
      dirSign: dirSign,
      seed: 21000 + i * 41
    });
  }

  // Add tight vortex eye rings (concentric marbled marker loops inside the main soap eddies)
  const vortexLoops = [
    { x: 380, y: 690, maxR: 72, dir: 1, vIdx: 0 },
    { x: 790, y: 670, maxR: 78, dir: -1, vIdx: 1 },
    { x: 505, y: 655, maxR: 52, dir: -1, vIdx: 7 },
    { x: 695, y: 645, maxR: 55, dir: 1, vIdx: 8 },
    { x: 325, y: 460, maxR: 58, dir: -1, vIdx: 3 },
    { x: 845, y: 440, maxR: 60, dir: 1, vIdx: 4 }
  ];
  const ringCols = ["#e61973", "#f2c12e", "#00b8e6", "#17b890", "#ff5ca8", "#07050a"];

  for (let vIdx = 0; vIdx < vortexLoops.length; vIdx++) {
    let v = vortexLoops[vIdx];
    for (let ring = 0; ring < 9; ring++) {
      let rad = map(ring, 0, 8, 10, v.maxR);
      let pts = [];
      let aStart = random(360);
      let aSpan = random(200, 310);
      for (let s = 0; s <= 12; s++) {
        let a = aStart + (s / 12) * aSpan;
        let rWobble = rad + sin(a * 3 + ring * 40) * (rad * 0.16);
        let px = v.x + cos(a) * (rWobble * 1.15);
        let py = v.y + sin(a) * (rWobble * 0.88);
        if (dist(px, py, W_CX, W_CY) < W_R_IN - 6) {
          pts.push([px, py]);
        }
      }
      if (pts.length >= 4) {
        let col = ringCols[ring % ringCols.length];
        let w = random(0.5, 0.95);
        brush.set("ribbon_marker", col, w);
        brush.spline(pts, 0.55);

        savedVortexRings.push({
          vx: v.x,
          vy: v.y,
          dir: v.dir,
          vortIdx: v.vIdx,
          ring: ring,
          rad: rad,
          aStart: aStart,
          aSpan: aSpan,
          col: col,
          w: w,
          count: pts.length,
          seed: 51000 + vIdx * 100 + ring * 7
        });
      }
    }
  }
}

function drawMarbledMarkerInterferenceAnimated(t) {
  // 1. Advect all marbled soap-film streamlines through the incompressible Marangoni flow
  for (let i = 0; i < savedStreamlines.length; i++) {
    let sl = savedStreamlines[i];
    randomSeed(sl.seed);
    noiseSeed(sl.seed);

    let movedPts = [];
    let n = sl.pts.length;
    for (let s = 0; s < n; s++) {
      let p0 = sl.pts[s];
      let p = advectPoint(p0[0], p0[1], t);

      // Subtle traveling capillary wave along the ribbon
      let wave = sin(s * 38 - t * 140 * sl.dirSign + i * 19) * 3.2 * min(1, t * 2.5);
      p[0] += wave * 0.7;
      p[1] += wave * 0.5;

      movedPts.push(p);
    }

    brush.set(sl.brushName, sl.col, sl.w);
    brush.spline(movedPts, 0.55);
  }

  // 2. Spin and drift the concentric vortex eye rings inside the 6 main eddies
  for (let k = 0; k < savedVortexRings.length; k++) {
    let vr = savedVortexRings[k];
    randomSeed(vr.seed);
    noiseSeed(vr.seed);

    // Inner rings spin faster than outer rings (whirlpool differential rotation)
    let spinRate = map(vr.ring, 0, 8, 92, 46) * vr.dir;
    let rotAngle = spinRate * t;

    // Vortex center also drifts with the orbital breathing of its parent eddy
    let shiftX = (cos(t * 65 + vr.vortIdx * 47) - cos(vr.vortIdx * 47)) * 14 * vr.dir;
    let shiftY = (sin(t * 65 + vr.vortIdx * 47) - sin(vr.vortIdx * 47)) * 11 + t * 8;
    let cx = vr.vx + shiftX;
    let cy = vr.vy + shiftY;

    let pts = [];
    let maxR = W_R_IN - 6;
    for (let s = 0; s < vr.count; s++) {
      let a0 = vr.aStart + (s / 12) * vr.aSpan;
      let a = a0 + rotAngle;
      let rWobble = vr.rad + sin(a0 * 3 + vr.ring * 40 - t * 110 * vr.dir) * (vr.rad * 0.16);
      let px = cx + cos(a) * (rWobble * 1.15);
      let py = cy + sin(a) * (rWobble * 0.88);
      let d = dist(px, py, W_CX, W_CY);
      if (d > maxR) {
        px = W_CX + ((px - W_CX) / d) * maxR;
        py = W_CY + ((py - W_CY) / d) * maxR;
      }
      pts.push([px, py]);
    }

    brush.set("ribbon_marker", vr.col, vr.w);
    brush.spline(pts, 0.55);
  }
}

