// 4. CRISP RE-EMPHASIS OF EYE SPECULARS & CHROMATIC LASH TIPS
// =========================================================================
function drawCrispEyeSpeculars() {
  savedIridescentGlints = [];
  savedTearSparkles = [];

  // Razor-sharp corneal window reflection on the wet iris/pupil (upper-left of pupil)
  const panes = [
    { x1: 528, y1: 432, x2: 562, y2: 426, x3: 565, y3: 458, x4: 532, y4: 465 },
    { x1: 569, y1: 425, x2: 602, y2: 424, x3: 602, y3: 455, x4: 571, y4: 457 },
    { x1: 534, y1: 472, x2: 566, y2: 465, x3: 569, y3: 492, x4: 539, y4: 498 },
    { x1: 573, y1: 464, x2: 602, y2: 462, x3: 603, y3: 488, x4: 575, y4: 491 }
  ];

  for (let p of panes) {
    for (let row = 0; row <= 9; row++) {
      let v = row / 9;
      let lx = lerp(p.x1, p.x4, v);
      let ly = lerp(p.y1, p.y4, v);
      let rx = lerp(p.x2, p.x3, v);
      let ry = lerp(p.y2, p.y3, v);
      let pStart = distortEye(lx, ly);
      let pEnd = distortEye(rx, ry);
      brush.set("cpencil", row % 2 === 0 ? "#ffffff" : "#e3f8ff", 0.55);
      brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
    }
  }

  // Secondary wet glint on lower-right iris & tear meniscus along lower lid
  for (let i = 0; i < 16; i++) {
    let x = random(645, 682);
    let y = random(538, 556);
    let p1 = distortEye(x, y);
    let p2 = distortEye(x + random(8, 16), y - random(3, 8));
    brush.set("cpencil", "#ffffff", 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    savedIridescentGlints.push({ p1: p1, p2: p2, seed: 61000 + i * 19 });
  }

  // Wet tear-meniscus sparkle line where lower lid meets the eyeball
  for (let x = 355; x <= 845; x += 14) {
    if (random(1) < 0.72) {
      let y = lowerLidY(x) - 1;
      let p1 = distortEye(x, y);
      let p2 = distortEye(x + random(8, 15), lowerLidY(x + 10) - 1);
      let w = random(0.38, 0.6);
      brush.set("cpencil", "#ffffff", w);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      savedTearSparkles.push({ p1: p1, p2: p2, w: w, seed: 62000 + x * 13 });
    }
  }

  // Re-sharpen selected foreground eyelash tips & add thin-film chromatic glints on lashes
  const glintCols = ["#ff4da6", "#4ce6ff", "#ffdf66", "#120a07"];
  for (let i = 0; i < 28; i++) {
    let t = map(i, 0, 27, 0.14, 0.88);
    let rootX = lerp(318, 888, t);
    let rootY = upperLidY(rootX);
    let len = 76 + sin(t * 180) * 56;
    let baseAng = lerp(-152, -22, t);
    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len - sin(t * 180) * 18;

    let pts = [
      distortEye(rootX, rootY),
      distortEye(lerp(rootX, tipX, 0.45), lerp(rootY, tipY, 0.35) + 11),
      distortEye(tipX, tipY)
    ];
    brush.set("cpencil", "#0d0705", 0.45);
    brush.spline(pts, 0.5);

    // Chromatic diffraction glint along the side of the lash
    if (i % 2 === 0) {
      let gPts = [
        distortEye(lerp(rootX, tipX, 0.35) + 2, lerp(rootY, tipY, 0.28) + 9),
        distortEye(tipX + 2, tipY)
      ];
      brush.set("cpencil", glintCols[i % 3], 0.28);
      brush.line(gPts[0][0], gPts[0][1], gPts[1][0], gPts[1][1]);
    }
  }
}

