// =========================================================================
// 5. FAINT SPRAY OF WINDOW REFLECTIONS ON THE SOAP FILM
// =========================================================================
function windowQuadPointAt(u, v, t) {
  // Breath bowing of the elastic soap membrane shifts and curves the window reflection
  let a = lerp(-165, -98, u) + t * 4.5;
  let r = lerp(195, 355, v) + sin(t * 80) * 18;
  let bow = sin(u * 180) * sin(v * 180) * (24 + sin(t * 95) * 10);
  return [
    W_CX + cos(a) * (r + bow),
    W_CY + sin(a) * (r + bow)
  ];
}

function drawFilmWindowReflections() {
  savedWindowRefl1 = [];
  savedWindowRefl2 = [];

  function windowQuadPoint(u, v) {
    let a = lerp(-165, -98, u);
    let r = lerp(195, 355, v);
    let bow = sin(u * 180) * sin(v * 180) * 24;
    return [
      W_CX + cos(a) * (r + bow),
      W_CY + sin(a) * (r + bow)
    ];
  }

  for (let i = 0; i < 290; i++) {
    let u = random(0, 1);
    let v = random(0, 1);
    if (abs(u - 0.51) < 0.045 || abs(v - 0.50) < 0.045) continue;

    let dv = random(-0.02, 0.02);
    let p1 = windowQuadPoint(u, v);
    let p2 = windowQuadPoint(constrain(u + 0.08, 0, 1), constrain(v + dv, 0, 1));

    let col = random(1) < 0.65 ? "#ffffff" : (random(1) < 0.5 ? "#e0f7ff" : "#fff7e0");
    let w = random(0.65, 1.25);
    brush.set("mist_spray", col, w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    savedWindowRefl1.push({
      u: u,
      v: v,
      dv: dv,
      col: col,
      w: w,
      seed: 71000 + i * 31
    });
  }

  // Secondary faint inverted window reflection arc in lower-right of the film
  for (let i = 0; i < 130; i++) {
    let u = random(0, 1);
    let v = random(0, 1);
    if (abs(u - 0.5) < 0.055 || abs(v - 0.5) < 0.055) continue;

    let a = lerp(12, 68, u);
    let r = lerp(240, 358, v);
    let p1 = [W_CX + cos(a) * r, W_CY + sin(a) * r];
    let p2 = [W_CX + cos(a + 4) * r, W_CY + sin(a + 4) * r];

    let col = i % 2 === 0 ? "#ffffff" : "#d9f5ff";
    let w = random(0.5, 0.95);
    brush.set("mist_spray", col, w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    savedWindowRefl2.push({
      u: u,
      v: v,
      col: col,
      w: w,
      seed: 75000 + i * 37
    });
  }
}

function drawFilmWindowReflectionsAnimated(t) {
  for (let item of savedWindowRefl1) {
    randomSeed(item.seed);
    noiseSeed(item.seed);
    let p1 = windowQuadPointAt(item.u, item.v, t);
    let p2 = windowQuadPointAt(constrain(item.u + 0.08, 0, 1), constrain(item.v + item.dv, 0, 1), t);
    brush.set("mist_spray", item.col, item.w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  for (let item of savedWindowRefl2) {
    randomSeed(item.seed);
    noiseSeed(item.seed);
    let a = lerp(12, 68, item.u) - t * 4.0;
    let r = lerp(240, 358, item.v) - sin(t * 80) * 14;
    let p1 = [W_CX + cos(a) * r, W_CY + sin(a) * r];
    let p2 = [W_CX + cos(a + 4) * r, W_CY + sin(a + 4) * r];
    brush.set("mist_spray", item.col, item.w);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// =========================================================================
// 6. PLASTIC BUBBLE WAND, WET MENISCUS TEETH & GLOSSY HANDLE
// =========================================================================
function drawBubbleWand() {
  savedWandShadow = [];

  const hAngle = 116;
  const hx0 = W_CX + cos(hAngle) * (W_R_OUT - 8);
  const hy0 = W_CY + sin(hAngle) * (W_R_OUT - 8);
  const hx1 = hx0 + cos(hAngle) * 320;
  const hy1 = hy0 + sin(hAngle) * 320;
  const perpX = cos(hAngle - 90);
  const perpY = sin(hAngle - 90);

  // Cast shadow of wand handle & ring onto the out-of-focus background
  for (let i = 0; i < 45; i++) {
    let a = random(-35, 145);
    let r = W_R_OUT + random(8, 28);
    let sx = W_CX + 18 + cos(a) * r;
    let sy = W_CY + 24 + sin(a) * r;
    let w = random(0.45, 0.85);
    brush.set("charcoal", "#7a6450", w);
    brush.line(sx, sy, sx + cos(a + 90) * 35, sy + sin(a + 90) * 35);
    savedWandShadow.push({ a: a, sx: sx, sy: sy, w: w, seed: 81000 + i * 23 });
  }

  drawBubbleWandBodyAndMeniscus(0, false);
}

