function drawBubbleWandBodyAndMeniscus(t, seeded) {
  const hAngle = 116;
  const hx0 = W_CX + cos(hAngle) * (W_R_OUT - 8);
  const hy0 = W_CY + sin(hAngle) * (W_R_OUT - 8);
  const hx1 = hx0 + cos(hAngle) * 320;
  const hy1 = hy0 + sin(hAngle) * 320;
  const perpX = cos(hAngle - 90);
  const perpY = sin(hAngle - 90);

  if (seeded) {
    randomSeed(82000);
    noiseSeed(82000);
  }

  // Handle plastic body (translucent coral-ruby red with dark refraction core & bright speculars)
  for (let w = -34; w <= 34; w += 2.5) {
    let col = "#d92b21";
    if (w < -24 || w > 24) col = "#4a0805";
    else if (w > -8 && w < 4) col = "#ff6e4a";
    else if (w >= -18 && w <= -12) col = "#ffffff";

    brush.set("pool_marker", col, 0.55);
    brush.line(hx0 + perpX * w, hy0 + perpY * w, hx1 + perpX * (w * 1.15), hy1 + perpY * (w * 1.15));
  }

  // Moulded horizontal grip notches on the wand handle
  for (let d = 35; d < 260; d += 26) {
    let cx = hx0 + cos(hAngle) * d;
    let cy = hy0 + sin(hAngle) * d;
    brush.set("cpencil", "#380503", 0.55);
    brush.line(cx - perpX * 26, cy - perpY * 26, cx + perpX * 26, cy + perpY * 26);
    brush.set("cpencil", "#ff9e85", 0.45);
    brush.line(cx - perpX * 24 + 2, cy - perpY * 24 + 2, cx + perpX * 24 + 2, cy + perpY * 24 + 2);
  }

  if (seeded) {
    randomSeed(83000);
    noiseSeed(83000);
  }

  // 2. Circular Plastic Wand Ring (Translucent Coral-Ruby with High-Contrast Rim Refraction)
  const ringBands = [
    { rOff: 0.04, col: "#360503", brushName: "cpencil", w: 0.65 },
    { rOff: 0.14, col: "#8f1610", brushName: "marbled_marker", w: 0.65 },
    { rOff: 0.28, col: "#d92b21", brushName: "pool_marker", w: 0.85 },
    { rOff: 0.46, col: "#ff5c3b", brushName: "pool_marker", w: 0.90 },
    { rOff: 0.62, col: "#ff8559", brushName: "marbled_marker", w: 0.70 },
    { rOff: 0.78, col: "#b51c14", brushName: "marbled_marker", w: 0.75 },
    { rOff: 0.92, col: "#4a0906", brushName: "ribbon_marker", w: 0.65 },
    { rOff: 0.98, col: "#240302", brushName: "cpencil", w: 0.60 }
  ];

  for (let b of ringBands) {
    let rad = lerp(W_R_IN, W_R_OUT, b.rOff);
    for (let seg = 0; seg < 12; seg++) {
      let aStart = seg * 30;
      let aEnd = (seg + 1) * 30 + 2;
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 5) {
        pts.push([W_CX + cos(a) * rad, W_CY + sin(a) * rad]);
      }
      brush.set(b.brushName, b.col, b.w);
      brush.spline(pts, 0.5);
    }
  }

  // Crisp glossy white plastic specular arcs along the wand bevel
  let specArcs = [
    { a1: -165, a2: -55, rFrac: 0.36 },
    { a1: -40, a2: 25, rFrac: 0.38 },
    { a1: 35, a2: 102, rFrac: 0.68 },
    { a1: 132, a2: 185, rFrac: 0.42 }
  ];
  for (let sa of specArcs) {
    let rad = lerp(W_R_IN, W_R_OUT, sa.rFrac);
    let pts = [];
    for (let a = sa.a1; a <= sa.a2; a += 4) {
      pts.push([W_CX + cos(a) * rad, W_CY + sin(a) * rad]);
    }
    brush.set("cpencil", "#ffffff", 0.7);
    brush.spline(pts, 0.5);
    brush.set("cpencil", "#ffd6cc", 0.45);
    brush.spline(pts.map(p => [p[0] + 2, p[1] + 2]), 0.5);
  }

  if (seeded) {
    randomSeed(84000);
    noiseSeed(84000);
  }

  // 3. Moulded Inner Flutes / Ridges (Classic bubble wand teeth that hold liquid soap)
  const numTeeth = 84;
  for (let i = 0; i < numTeeth; i++) {
    let a = (i / numTeeth) * 360;
    let rOuter = W_R_IN + 5;
    let rInner = W_R_IN - 9;
    let x1 = W_CX + cos(a) * rOuter;
    let y1 = W_CY + sin(a) * rOuter;
    let x2 = W_CX + cos(a) * rInner;
    let y2 = W_CY + sin(a) * rInner;

    brush.set("cpencil", "#3b0604", 0.5);
    brush.line(x1, y1, x2, y2);

    let x3 = W_CX + cos(a + 0.8) * (rInner + 2);
    let y3 = W_CY + sin(a + 0.8) * (rInner + 2);
    brush.set("cpencil", i % 2 === 0 ? "#ffffff" : "#ff9b85", 0.4);
    brush.line(x1, y1, x3, y3);
  }

  // Wet soap meniscus ring clinging to the inner teeth (Plateau border ripples with flow)
  const meniscusColors = ["#ffffff", "#4ce6ff", "#ff4da6", "#ffdf66", "#42e3b8"];
  for (let i = 0; i < 60; i++) {
    if (seeded) {
      randomSeed(85000 + i * 19);
      noiseSeed(85000 + i * 19);
    }
    let a1 = i * 6 + t * 18;
    let a2 = a1 + 7;
    let rMeniscus = W_R_IN - 7 + sin(a1 * 6 - t * 120) * 2.5;
    let p1 = [W_CX + cos(a1) * rMeniscus, W_CY + sin(a1) * rMeniscus];
    let p2 = [W_CX + cos((a1 + a2) * 0.5) * (rMeniscus - 2), W_CY + sin((a1 + a2) * 0.5) * (rMeniscus - 2)];
    let p3 = [W_CX + cos(a2) * rMeniscus, W_CY + sin(a2) * rMeniscus];

    let col = meniscusColors[i % meniscusColors.length];
    brush.set("cpencil", col, i % 5 === 0 ? 0.65 : 0.45);
    brush.spline([p1, p2, p3], 0.45);
  }
}

19-accordion:
// MOTION: A musical ripple cascades down and back up the pearloid and black keys while the bellows gently breathe
window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;

const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;
let stillImg;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88314);
}

// ===========================================================================
// SHARED 3D-TO-2D PROJECTION & GEOMETRY CONSTANTS
// ===========================================================================
const TILT_ANG = 25.5;
const KEY_PITCH = 86;
const KEY_GAP = 4.6;
const KEY_W = KEY_PITCH - KEY_GAP;
const U_KEY_START = 0;
const U_KEY_END = 462;
const U_TIP_START = 434;
const U_BLACK_END = 256;
const U_BLACK_SLOPE_START = 212;
const BLACK_W = 45;

function proj3D(u, v, z = 0) {
  const cosT = cos(TILT_ANG);
  const sinT = sin(TILT_ANG);
  const cx = 515;
  const cy = 595;
  let sc = 1.09 * (1 + 0.00014 * v + 0.00006 * u);
  let x0 = u * cosT - v * sinT;
  let y0 = u * sinT + v * cosT;
  let x = cx + (x0 - z * 0.39) * sc;
  let y = cy + (y0 - z * 0.43) * sc;
  return [x, y];
}

function hasBlackKeyAfterIndex(k) {
  let mod = ((k % 7) + 7) % 7;
  return mod === 0 || mod === 1 || mod === 3 || mod === 4 || mod === 5;
}

function getBlackKeyBounds(k) {
  let vBoundary = (k + 1) * KEY_PITCH - KEY_GAP * 0.5;
  let mod = ((k % 7) + 7) % 7;
  let vShift = mod === 0 || mod === 3 ? -3.5 : mod === 1 || mod === 5 ? 3.5 : 0;
  let vB1 = vBoundary - BLACK_W * 0.5 + vShift;
  let vB2 = vBoundary + BLACK_W * 0.5 + vShift;
  return [vB1, vB2];
}

function getWhiteKeyRestZ(k) {
  return 22.0 + sin(k * 73) * 0.9 - (k === 2 || k === 5 ? 1.6 : 0);
}

// ===========================================================================
// EXACT STILL PAINTING (FRAME 0)
// ===========================================================================
function paintStill() {
  translate(-width / 2, -height / 2);

  // Warm archival cotton paper base for luminous pearloid highlights
  background("#f3eee3");

  // -------------------------------------------------------------------------
  // 3D-TO-2D TILTED MACRO PROJECTION
  // u: across accordion (-850..0 bellows & frame, 0..465 keys, 465..750 rail)
  // v: along keyboard axis (-750 top-right to +850 bottom-left)
  // z: height above keybed (0 keybed, 22 white keys, 50 black keys, 38..58 frame)
  // -------------------------------------------------------------------------
  const tilt = 25.5;
  const cosT = cos(tilt);
  const sinT = sin(tilt);
  const cx = 515;
  const cy = 595;

  function proj(u, v, z = 0) {
    let sc = 1.09 * (1 + 0.00014 * v + 0.00006 * u);
    let x0 = u * cosT - v * sinT;
    let y0 = u * sinT + v * cosT;
    let x = cx + (x0 - z * 0.39) * sc;
    let y = cy + (y0 - z * 0.43) * sc;
    return [x, y];
  }

  // Helper: Draw a washed/filled 3D polygon
  function fillPoly3D(pts3D, col, alpha = 255, useBleed = false, bleedAmt = 0.05) {
    brush.noStroke();
    brush.noHatch();
    if (useBleed) {
      brush.noWash();
      brush.fill(col, alpha);
      brush.fillBleed(bleedAmt, "out");
      brush.fillTexture(0.35, 0.25);
    } else {
      brush.noFill();
      brush.wash(col, alpha);
    }
    brush.beginShape(0);
    for (let i = 0; i < pts3D.length; i++) {
      let [x, y] = proj(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
      brush.vertex(x, y);
    }
    brush.endShape(true);
    brush.noFill();
    brush.noWash();
  }

  // Helper: Draw a 3D line
  function line3D(p1, p2, bName, col, w) {
    let [x1, y1] = proj(p1[0], p1[1], p1[2] || 0);
    let [x2, y2] = proj(p2[0], p2[1], p2[2] || 0);
    brush.set(bName, col, w);
    brush.line(x1, y1, x2, y2);
  }

  // Helper: Draw a 3D spline with optional pressure array [u, v, z, pressure]
  function spline3D(pts3D, curv, bName, col, w) {
    if (pts3D.length < 2) return;
    let pts2D = [];
    for (let i = 0; i < pts3D.length; i++) {
      let [x, y] = proj(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
      let pr = pts3D[i][3] !== undefined ? pts3D[i][3] : 1.0;
      pts2D.push([x, y, pr]);
    }
    brush.set(bName, col, w);
    brush.spline(pts2D, curv);
  }

  // Helper: Interpolate directional hatching across a 3D quad [A, B, C, D]
  function hatchQuad3D(pA, pB, pC, pD, steps, bName, col, w, jitter = 0) {
    brush.set(bName, col, w);
    for (let i = 0; i <= steps; i++) {
      let t = i / max(1, steps);
      let u1 = lerp(pA[0], pD[0], t) + (jitter ? random(-jitter, jitter) : 0);
      let v1 = lerp(pA[1], pD[1], t) + (jitter ? random(-jitter, jitter) : 0);
      let z1 = lerp(pA[2] || 0, pD[2] || 0, t);
      let u2 = lerp(pB[0], pC[0], t) + (jitter ? random(-jitter, jitter) : 0);
      let v2 = lerp(pB[1], pC[1], t) + (jitter ? random(-jitter, jitter) : 0);
      let z2 = lerp(pB[2] || 0, pC[2] || 0, t);
      let [x1, y1] = proj(u1, v1, z1);
      let [x2, y2] = proj(u2, v2, z2);
      brush.line(x1, y1, x2, y2);
    }
  }

  // =========================================================================
  // 1. BELLOWS (FIRST 5 FOLDS, V-GUSSETS & WORN BLACK BELLOWS CORNERS)
  // u in [-860, -135], v in [-820, 880]
  // =========================================================================
  const numFolds = 5;
  const foldSpan = 138;
  const bellowsStartU = -135;

  // Deep studio shadow backdrop under bellows & keyboard
  fillPoly3D(
    [[-900, -900, -60], [50, -900, -60], [50, 950, -60], [-900, 950, -60]],
    "#101217", 245, false
  );

  for (let f = numFolds - 1; f >= 0; f--) {
    let uRight = bellowsStartU - f * foldSpan;       // Valley (inner crease)
    let uPeak  = uRight - foldSpan * 0.52;           // Peak (outer ridge)
    let uLeft  = uRight - foldSpan;                  // Next valley
    let zVal   = -52;
    let zPeak  = 34 - f * 2.5;

    // Corner position along v where the front pleat meets the top gusset fold
    let vCorner = -165 + f * 48;
    let vTop = -850;
    let vBot = 920;

    // Valley gusset indent at the corner
    let uGussetIn = uPeak + 46;
    let zGussetIn = -18;

    // --- A. TOP END-FACE OF BELLOWS (above vCorner: vTop .. vCorner) ---
    // Left-sloping top pleat facet (from uLeft valley up to uPeak ridge)
    fillPoly3D(
      [
        [uLeft, vTop, zVal],
        [uPeak, vTop, zPeak],
        [uPeak, vCorner - 36, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uLeft, vCorner, zVal]
      ],
      "#232730", 235, false
    );
    hatchQuad3D(
      [uLeft, vTop, zVal], [uPeak, vTop, zPeak],
      [uPeak, vCorner - 36, zPeak], [uLeft, vCorner, zVal],
      34, "2B", "#14171d", 0.55, 1.5
    );
    // Subtle raking light across the upper gusset slope
    hatchQuad3D(
      [uLeft + 15, vTop, zVal + 12], [uPeak, vTop, zPeak],
      [uPeak, vCorner - 36, zPeak], [uLeft + 15, vCorner, zVal + 12],
      22, "cpencil", "#4b5260", 0.42, 1.0
    );

    // Right-sloping top pleat facet (plunging into deep shadow toward uRight)
    fillPoly3D(
      [
        [uPeak, vTop, zPeak],
        [uRight, vTop, zVal],
        [uRight, vCorner, zVal],
        [uGussetIn, vCorner, zGussetIn],
        [uPeak, vCorner - 36, zPeak]
      ],
      "#0d0f14", 245, false
    );
    hatchQuad3D(
      [uPeak, vTop, zPeak], [uRight, vTop, zVal],
      [uRight, vCorner, zVal], [uPeak, vCorner - 36, zPeak],
      38, "charcoal", "#07080b", 0.65, 1.2
    );

    // --- B. V-GUSSET DIAMOND FOLD AT vCorner ---
    // Upper gusset triangle (catches oblique raking light)
    fillPoly3D(
      [
        [uPeak, vCorner - 36, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uPeak, vCorner + 38, zPeak]
      ],
      "#1b1e26", 240, false
    );
    hatchQuad3D(
      [uPeak, vCorner - 36, zPeak], [uGussetIn, vCorner, zGussetIn],
      [uGussetIn, vCorner, zGussetIn], [uPeak, vCorner + 38, zPeak],
      18, "2B", "#0c0e13", 0.45, 0.8
    );

    // --- C. MAIN FRONT PLEATS (below vCorner: vCorner .. vBot) ---
    // 1. Left-facing slope of pleat (uLeft valley -> uPeak ridge): Lit by lateral light
    let litCol = f === 0 ? "#2f3542" : f === 1 ? "#282d38" : "#212630";
    fillPoly3D(
      [
        [uLeft, vCorner, zVal],
        [uPeak, vCorner + 38, zPeak],
        [uPeak, vBot, zPeak],
        [uLeft, vBot, zVal]
      ],
      litCol, 235, false
    );

    // Woven black cloth cross-hatching on lit bellows facet
    hatchQuad3D(
      [uLeft, vCorner, zVal], [uPeak, vCorner + 38, zPeak],
      [uPeak, vBot, zPeak], [uLeft, vBot, zVal],
      68, "2B", "#181b22", 0.5, 1.5
    );
    // Raking light sheen near the peak ridge
    hatchQuad3D(
      [lerp(uLeft, uPeak, 0.45), vCorner + 20, lerp(zVal, zPeak, 0.45)],
      [uPeak, vCorner + 38, zPeak],
      [uPeak, vBot, zPeak],
      [lerp(uLeft, uPeak, 0.45), vBot, lerp(zVal, zPeak, 0.45)],
      45, "HB", "#586070", 0.4, 1.2
    );
    // Fine linen weave diagonal grain
    for (let vLine = vCorner + 20; vLine < vBot; vLine += 26) {
      line3D(
        [uLeft + 8, vLine - 18, zVal + 6],
        [uPeak - 4, vLine + 24, zPeak - 3],
        "2H", "#464d5c", 0.32
      );
      if (random() < 0.55) {
        line3D(
          [lerp(uLeft, uPeak, 0.6), vLine, lerp(zVal, zPeak, 0.6)],
          [uPeak - 2, vLine + 14, zPeak - 1],
          "cpencil", "#7b8496", 0.28
        );
      }
    }

    // 2. Right-facing slope of pleat (uPeak ridge -> uRight valley): Deep velvet shadow
    fillPoly3D(
      [
        [uPeak, vCorner + 38, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uRight, vCorner, zVal],
        [uRight, vBot, zVal],
        [uPeak, vBot, zPeak]
      ],
      "#0e1015", 248, false
    );
    hatchQuad3D(
      [uPeak, vCorner + 38, zPeak], [uRight, vCorner, zVal],
      [uRight, vBot, zVal], [uPeak, vBot, zPeak],
      72, "charcoal", "#07080c", 0.7, 1.4
    );
    // Faint reflected light deep inside the valley crease from adjacent lit ridge
    for (let vLine = vCorner + 30; vLine < vBot; vLine += 35) {
      line3D(
        [lerp(uPeak, uRight, 0.25), vLine, lerp(zPeak, zVal, 0.25)],
        [lerp(uPeak, uRight, 0.75), vLine + 12, lerp(zPeak, zVal, 0.75)],
        "2H", "#282d38", 0.3
      );
    }

    // Deep valley crease line at uRight
    line3D([uRight, vTop, zVal], [uRight, vBot, zVal], "charcoal", "#050608", 0.9);

    // --- D. WORN BLACK CLOTH TAPE ALONG PLEAT RIDGE ---
    let tapeW = 13;
    // Left tape lip
    fillPoly3D(
      [
        [uPeak - tapeW, vCorner + 38, zPeak - 6],
        [uPeak, vCorner + 38, zPeak],
        [uPeak, vBot, zPeak],
        [uPeak - tapeW, vBot, zPeak - 6]
      ],
      "#3a414f", 220, false
    );
    // Scuffed graphite highlights along the worn black cloth tape ridge
    for (let vS = vCorner + 44; vS < vBot; vS += 9) {
      let scuff = noise(f * 10, vS * 0.03);
      let col = scuff > 0.58 ? "#b8c2d1" : scuff > 0.4 ? "#788294" : "#49505e";
      let w = scuff > 0.58 ? 0.52 : 0.35;
      line3D(
        [uPeak - tapeW * random(0.3, 0.9), vS, zPeak - 3],
        [uPeak + random(-2, 3), vS + random(-2, 4), zPeak + 0.5],
        "HB", col, w
      );
      // Tiny frayed thread marks on worn ridge
      if (scuff > 0.64) {
        line3D(
          [uPeak - 3, vS, zPeak],
          [uPeak + 2, vS + 5, zPeak],
          "2H", "#e3e8f0", 0.28
        );
      }
    }

    // --- E. WORN BLACK / CHROME STAMPED BELLOWS CORNER PROTECTOR ---
    // Rendered in dense graphite with worn black lacquer and exposed steel highlights
    let cLen = 44;
    let cWidth = 24;
    let pTip = [uPeak + 5, vCorner + 2, zPeak + 3];
    let pTopL = [uPeak - cWidth, vCorner - cLen, zPeak - 9];
    let pTopR = [uPeak + cWidth * 0.75, vCorner - cLen * 0.75, zPeak - 11];
    let pBotL = [uPeak - cWidth, vCorner + cLen + 14, zPeak - 9];
    let pBotR = [uPeak + cWidth * 0.75, vCorner + cLen + 8, zPeak - 11];
    let pMidRidge = [uPeak, vCorner + 4, zPeak + 4.5];

    // Dark oxidized metal base of the corner cap
    fillPoly3D([pTopL, pMidRidge, pBotL], "#222730", 245, false);
    fillPoly3D([pMidRidge, pTopR, pTip, pBotR], "#11141a", 250, false);

    // Dense graphite modelling across the stamped metal corner
    hatchQuad3D(pTopL, pMidRidge, pMidRidge, pBotL, 24, "2B", "#151820", 0.45, 0.5);
    hatchQuad3D(pMidRidge, pTopR, pBotR, pMidRidge, 24, "charcoal", "#090b0f", 0.55, 0.5);

    // Crimped perimeter lip & rivets
    spline3D([pTopL, [uPeak - cWidth * 0.85, vCorner + 4, zPeak - 6], pBotL], 0.4, "2B", "#0a0c10", 0.75);
    spline3D([pTopL, [uPeak - cWidth * 0.8, vCorner + 4, zPeak - 5.5], pBotL], 0.4, "2H", "#8d96a6", 0.35);

    // Embossed reinforcement ribs on the metal corner cap (catching lateral raking light)
    for (let rib = -1; rib <= 1; rib++) {
      let rv = vCorner + 4 + rib * 13;
      let ribPts = [
        [uPeak - cWidth * 0.75, rv - 3, zPeak - 6],
        [uPeak - 4, rv, zPeak + 4],
        [uPeak + 4, rv + 1, zPeak + 3.5],
        [uPeak + cWidth * 0.55, rv - 2, zPeak - 7]
      ];
      // Dark shadow beneath rib
      spline3D(
        ribPts.map(p => [p[0], p[1] + 2.2, p[2] - 0.5]),
        0.5, "2B", "#080a0e", 0.65
      );
      // Worn silver-graphite highlight on top of rib
      spline3D(ribPts, 0.5, "HB", "#c4cddb", 0.5);
      // Specular raw steel glint where black lacquer wore off the knuckle
      line3D(
        [uPeak - 7, rv - 0.5, zPeak + 3.5],
        [uPeak + 3, rv + 0.5, zPeak + 4.2],
        "cpencil", "#ffffff", 0.55
      );
    }

    // Scratches and burnished graphite wear on the corner knuckle
    for (let s = 0; s < 16; s++) {
      let sv = vCorner + random(-24, 34);
      let su = uPeak + random(-14, 6);
      let col = random() < 0.4 ? "#f5f8fc" : "#95a0b2";
      line3D(
        [su, sv, zPeak + 2],
        [su + random(-5, 5), sv + random(4, 12), zPeak + 2],
        "2H", col, random(0.25, 0.45)
      );
    }
  }

  // =========================================================================
  // 2. KEYBED UNDER-SHADOW & FRONT KEYBOARD RAIL (BOTTOM-RIGHT CORNER)
  // =========================================================================
  // Deep shadow recess directly beneath all white keys (u in [0, 485], z = 0)
  fillPoly3D(
    [[0, -850, 0], [490, -850, 0], [490, 920, 0], [0, 920, 0]],
    "#0a0c10", 252, false
  );

  // Molded black celluloid front rail beyond the key tips (u in [472, 760], z = -12..10)
  fillPoly3D(
    [[472, -850, 8], [535, -850, 10], [535, 920, 10], [472, 920, 8]],
    "#1e222b", 245, false
  );
  fillPoly3D(
    [[535, -850, 10], [780, -850, -25], [780, 920, -25], [535, 920, 10]],
    "#0e1015", 250, false
  );
  hatchQuad3D(
    [472, -750, 8], [535, -750, 10], [535, 850, 10], [472, 850, 8],
    60, "2B", "#12151c", 0.5, 1.0
  );
  // Raking highlight along the moulded keyboard rail lip at u = 476
  for (let vR = -700; vR < 800; vR += 35) {
    line3D([475, vR, 9.5], [475, vR + 28, 9.5], "HB", "#697282", 0.42);
    line3D([532, vR, 10.5], [532, vR + 25, 10.5], "2H", "#8d96a6", 0.35);
  }

  // =========================================================================
  // 3. PEARLOID WHITE KEYS
  // Drawn back-to-front (k = -7 to +10) for true 3D occlusion
  // =========================================================================
  const keyPitch = 86;
  const keyGap = 4.6;
  const keyW = keyPitch - keyGap;
  const uKeyStart = 0;
  const uKeyEnd = 462;
  const uTipStart = 434;

  // Musical pattern: which inter-key boundaries have a Black Key (2 - 3 - 2 - 3 pattern)
  function hasBlackKeyAfter(k) {
    let mod = ((k % 7) + 7) % 7;
    // C D E F G A B -> sharps after C(0), D(1), F(3), G(4), A(5)
    return mod === 0 || mod === 1 || mod === 3 || mod === 4 || mod === 5;
  }

  // Which keys have tiny celluloid chips or fingerprint smudges
  const chippedKeys = new Set([-2, 1, 3, 5, 7]);
  const smudgedKeys = new Set([0, 2, 3, 5, 6]);

  for (let k = -7; k <= 10; k++) {
    let v1 = k * keyPitch;
    let v2 = v1 + keyW;

    // Slight mechanical variation in key rest height sells the vintage realism
    let zTop = 22.0 + sin(k * 73) * 0.9 - (k === 2 || k === 5 ? 1.6 : 0);
    let zLaminateBot = zTop - 7.5;
    let zWoodBot = 0;

    // --- A. 3D WOOD LEVER & PEARLOID SIDE WALL (+v face at v = v2) ---
    // Dark wood/felt under-wall (z = 0 .. zLaminateBot)
    fillPoly3D(
      [
        [uKeyStart, v2, zWoodBot],
        [uTipStart, v2, zWoodBot],
        [uTipStart, v2, zLaminateBot],
        [uKeyStart, v2, zLaminateBot]
      ],
      "#181514", 248, false
    );
    // Pearloid celluloid side wall (z = zLaminateBot .. zTop) in core shadow
    fillPoly3D(
      [
        [uKeyStart, v2, zLaminateBot],
        [uTipStart, v2, zLaminateBot],
        [uTipStart + 18, v2 - 4, zTop - 1],
        [uKeyStart, v2, zTop]
      ],
      "#6f7684", 240, false
    );
    hatchQuad3D(
      [uKeyStart, v2, zLaminateBot], [uTipStart, v2, zLaminateBot],
      [uTipStart, v2, zTop], [uKeyStart, v2, zTop],
      12, "HB", "#4b515e", 0.36, 0.3
    );
    // Subtle warm bounce-light reflected near bottom of pearloid side wall
    line3D(
      [uKeyStart + 25, v2, zLaminateBot + 1.8],
      [uTipStart - 10, v2, zLaminateBot + 1.8],
      "cpencil", "#b8b4be", 0.35
    );

    // --- B. ROUNDED WATERFALL FRONT NOSE OF KEY (u = uTipStart .. uKeyEnd) ---
    let noseSteps = 8;
    let noseTopPts = [];
    let noseBotPts = [];
    for (let s = 0; s <= noseSteps; s++) {
      let t = s / noseSteps;
      // Rounded corner in (u, v) and waterfall droop in z
      let uN = lerp(uTipStart, uKeyEnd, sin(t * 90));
      let vN1 = v1 + (1 - cos(t * 90)) * 7;
      let vN2 = v2 - (1 - cos(t * 90)) * 7;
      let zN = zTop - (1 - cos(t * 90)) * 4.5;
      noseTopPts.push([uN, vN1, zN]);
      noseBotPts.unshift([uN, vN2, zN]);
    }
    // Front vertical waterfall face at uKeyEnd (z = 2 .. zTop - 4.5)
    fillPoly3D(
      [
        [uKeyEnd, v1 + 7, 3],
        [uKeyEnd, v2 - 7, 3],
        [uKeyEnd, v2 - 7, zTop - 4.5],
        [uKeyEnd, v1 + 7, zTop - 4.5]
      ],
      "#8b919e", 235, false
    );
    // Side corner wrap of the nose
    fillPoly3D(
      [
        [uTipStart, v2, zLaminateBot],
        [uKeyEnd, v2 - 7, 4],
        [uKeyEnd, v2 - 7, zTop - 4.5],
        [uTipStart, v2, zTop]
      ],
      "#5c6270", 240, false
    );
    hatchQuad3D(
      [uKeyEnd, v1 + 7, 4], [uKeyEnd, v2 - 7, 4],
      [uKeyEnd, v2 - 7, zTop - 4.5], [uKeyEnd, v1 + 7, zTop - 4.5],
      10, "HB", "#626875", 0.35, 0.2
    );

    // --- C. TOP SURFACE OF WHITE KEY: BASE WASH ---
    let keyOutline = [
      [uKeyStart, v1, zTop],
      ...noseTopPts,
      ...noseBotPts,
      [uKeyStart, v2, zTop]
    ];
    // Warm cream base wash
    fillPoly3D(keyOutline, "#f6f0e4", 240, false);

    // Subtle lateral light gradient across the key width (cooler pearl toward +v edge)
    fillPoly3D(
      [
        [uKeyStart, lerp(v1, v2, 0.58), zTop],
        [uKeyEnd - 4, lerp(v1, v2, 0.58), zTop - 2],
        [uKeyEnd - 6, v2 - 6, zTop - 3],
        [uKeyStart, v2, zTop]
      ],
      "#dfe3ea", 130, true, 0.04
    );

    // --- D. MOTHER-OF-PEARL (PEARLOID) SWIRL & DIRECTIONAL NACRE HATCHING ---
    // Each key has its own cut of swirled pearloid celluloid sheet
    let seedOff = k * 37.4 + 100;

    // 1. Soft underlying nacre color clouds (pale pink, celadon, lavender, cream)
    let numLobes = 11;
    let lobeStep = (uKeyEnd - 14 - uKeyStart) / numLobes;
    for (let l = 0; l < numLobes; l++) {
      let uL1 = uKeyStart + l * lobeStep;
      let uL2 = uL1 + lobeStep * 1.15;
      let nVal = noise(seedOff + l * 0.45, k * 1.7);
      let nVal2 = noise(seedOff + l * 0.45 + 9.2, k * 1.7 + 3.1);

      // Select nacre tint: pale pink, celadon, lavender, or champagne cream
      let lobeColA, lobeColB;
      if (nVal < 0.28) {
        lobeColA = "#f2d3dc"; // pale rose pink
        lobeColB = "#cfe2db"; // celadon
      } else if (nVal < 0.54) {
        lobeColA = "#cce0d8"; // celadon green-grey
        lobeColB = "#dad2eb"; // soft lavender
      } else if (nVal < 0.78) {
        lobeColA = "#d8d0ea"; // pale lavender
        lobeColB = "#f4d7df"; // blush pink
      } else {
        lobeColA = "#f7eedb"; // warm champagne cream
        lobeColB = "#d2deea"; // cool silver-pearl
      }

      let vMidWave1 = lerp(v1 + 6, v2 - 6, constrain(0.25 + 0.55 * sin(l * 52 + k * 40), 0.15, 0.85));
      let vMidWave2 = lerp(v1 + 6, v2 - 6, constrain(0.25 + 0.55 * sin((l + 1) * 52 + k * 40), 0.15, 0.85));

      // Upper nacre ribbon lobe
      fillPoly3D(
        [
          [uL1, v1 + 3, zTop],
          [uL2, v1 + 3, zTop],
          [uL2, vMidWave2, zTop],
          [uL1, vMidWave1, zTop]
        ],
        lobeColA, 105, true, 0.05
      );
      // Lower nacre ribbon lobe
      fillPoly3D(
        [
          [uL1, vMidWave1, zTop],
          [uL2, vMidWave2, zTop],
          [uL2, v2 - 4, zTop],
          [uL1, v2 - 4, zTop]
        ],
        lobeColB, 110, true, 0.05
      );

      // Chatoyant silver-pearl pocket in the curl of the swirl
      if (nVal2 > 0.46) {
        let uC = (uL1 + uL2) * 0.5;
        let vC = vMidWave1;
        fillPoly3D(
          [
            [uC - 16, vC - 10, zTop],
            [uC + 14, vC - 6, zTop],
            [uC + 18, vC + 11, zTop],
            [uC - 12, vC + 8, zTop]
          ],
          "#bbc3d1", 90, true, 0.04
        );
      }
    }

    // 2. Directional Colored-Pencil Hatching following the Flaming Grain of the Nacre
    // Flaming grain angle waves organically along u and v
    let nacreStreams = 78;
    for (let s = 0; s < nacreStreams; s++) {
      let u0 = random(uKeyStart + 6, uKeyEnd - 16);
      let v0 = random(v1 + 4, v2 - 5);

      // Evaluate local nacre wave phase to pick burnished colored pencil shade
      let wave = sin((u0 * 0.048) * 57.3 + k * 45 + 2.2 * sin(v0 * 0.07 * 57.3));
      let cellNoise = noise(u0 * 0.018 + seedOff, v0 * 0.028);

      let pCol, bType, pWeight;
      if (wave > 0.55) {
        // Burnished white / warm cream specular nacre crest
        pCol = cellNoise > 0.5 ? "#ffffff" : "#fcf6e8";
        bType = "cpencil";
        pWeight = 0.52;
      } else if (wave > 0.12) {
        // Pale blush pink nacre band
        pCol = cellNoise > 0.52 ? "#ebbecb" : "#f5d8e0";
        bType = "cpencil";
        pWeight = 0.44;
      } else if (wave > -0.32) {
        // Celadon green-grey nacre band
        pCol = cellNoise > 0.5 ? "#b6d1c7" : "#cfe4dc";
        bType = "cpencil";
        pWeight = 0.44;
      } else if (wave > -0.72) {
        // Soft lavender nacre band
        pCol = cellNoise > 0.5 ? "#c2b6dc" : "#dad2ec";
        bType = "cpencil";
        pWeight = 0.44;
      } else {
        // Chatoyant silver-graphite fold boundary between nacre lobes
        pCol = cellNoise > 0.5 ? "#8790a0" : "#a5aebe";
        bType = "2H";
        pWeight = 0.34;
      }

      // Trace a 4-point curved streamline along the flaming grain field
      let curvePts = [];
      let curU = u0;
      let curV = v0;
      let stepLen = random(9, 15);
      for (let step = 0; step < 4; step++) {
        // Local flaming grain orientation (swirling ribbons across the key)
        let grainAng =
          58 * sin((curU * 0.035 + k * 0.8) * 57.3) +
          36 * cos((curV * 0.055 - k * 0.5) * 57.3) +
          25 * (noise(curU * 0.02 + seedOff, curV * 0.02) - 0.5);

        let curZ = curU > uTipStart
          ? zTop - pow((curU - uTipStart) / (uKeyEnd - uTipStart), 1.6) * 4.2
          : zTop;
        let pr = step === 0 || step === 3 ? 0.55 : 1.15;
        curvePts.push([curU, curV, curZ, pr]);

        curU += cos(grainAng) * stepLen;
        curV += sin(grainAng) * stepLen * 0.72;
        curU = constrain(curU, uKeyStart + 3, uKeyEnd - 5);
        curV = constrain(curV, v1 + 3.5, v2 - 3.5);
      }
      spline3D(curvePts, 0.55, bType, pCol, pWeight);
    }

    // 3. Crisp Silver-Graphite Chatoyant Veins & Burnished Shimmer Accents
    for (let vIdx = 0; vIdx < 14; vIdx++) {
      let uVein = uKeyStart + 22 + vIdx * 31 + random(-8, 8);
      if (uVein > uKeyEnd - 18) continue;
      let vA = v1 + random(5, 22);
      let vM1 = lerp(v1, v2, random(0.3, 0.5));
      let vM2 = lerp(v1, v2, random(0.55, 0.78));
      let vB = v2 - random(5, 20);
      let uShift1 = random(-18, 18);
      let uShift2 = random(-18, 18);

      // Dark chatoyant vein line where nacre crystal orientation flips
      spline3D(
        [
          [uVein, vA, zTop, 0.4],
          [uVein + uShift1, vM1, zTop, 1.0],
          [uVein + uShift2, vM2, zTop, 0.9],
          [uVein + uShift1 * 0.5, vB, zTop, 0.3]
        ],
        0.65, "2H", "#8e96a6", 0.3
      );
      // Immediate adjacent burnished white pearl flash
      spline3D(
        [
          [uVein + 3.5, vA + 2, zTop, 0.5],
          [uVein + uShift1 + 4, vM1, zTop, 1.2],
          [uVein + uShift2 + 4, vM2, zTop, 1.1],
          [uVein + uShift1 * 0.5 + 3.5, vB - 2, zTop, 0.4]
        ],
        0.65, "cpencil", "#ffffff", 0.55
      );
    }

    // --- E. RAKING LATERAL LIGHT ACROSS KEY EDGES ---
    // 1. Brilliant raking highlight along the upper (-v) bevel of the key
    spline3D(
      [
        [uKeyStart + 4, v1 + 1.2, zTop + 0.3, 0.7],
        [uTipStart * 0.5, v1 + 1.2, zTop + 0.3, 1.2],
        [uTipStart, v1 + 1.5, zTop + 0.3, 1.3],
        [uKeyEnd - 3, v1 + 7.5, zTop - 3.5, 0.8]
      ],
      0.35, "cpencil", "#ffffff", 0.78
    );
    line3D(
      [uKeyStart + 8, v1 + 3.0, zTop],
      [uTipStart, v1 + 3.0, zTop],
      "cpencil", "#fdf9f0", 0.52
    );

    // 2. Curved waterfall highlight across the rounded front nose
    spline3D(
      [
        [uTipStart + 10, v1 + 4, zTop - 0.8, 0.9],
        [uTipStart + 16, (v1 + v2) * 0.5, zTop - 1.1, 1.3],
        [uTipStart + 10, v2 - 5, zTop - 1.2, 0.6]
      ],
      0.5, "cpencil", "#ffffff", 0.68
    );

    // 3. Lower (+v) bevel core shadow turning down into the key gap
    line3D(
      [uKeyStart + 4, v2 - 1.5, zTop - 0.3],
      [uTipStart + 6, v2 - 2.2, zTop - 0.6],
      "HB", "#7b8391", 0.45
    );
    line3D(
      [uKeyStart + 4, v2, zTop - 0.8],
      [uTipStart + 4, v2 - 1, zTop - 1.0],
      "2B", "#313640", 0.42
    );

    // --- F. TINY CHIPS IN THE CELLULOID ---
    if (chippedKeys.has(k)) {
      // Chip 1: Along the front nose or upper/lower bevel edge
      let isFrontChip = (k % 2 !== 0);
      let uChip = isFrontChip ? uTipStart + 12 : random(275, 405);
      let vChip = isFrontChip ? lerp(v1 + 14, v2 - 14, 0.35 + 0.2 * (k % 3)) : (k > 2 ? v1 + 2.5 : v2 - 3.5);
      let zChip = isFrontChip ? zTop - 1.2 : zTop;
      let cw = random(7, 13);
      let ch = random(5, 9);

      // Exposed dark porous wood/core inside the broken celluloid notch
      fillPoly3D(
        [
          [uChip - cw * 0.5, vChip - ch * 0.4, zChip - 1.5],
          [uChip + cw * 0.6, vChip - ch * 0.2, zChip - 1.5],
          [uChip + cw * 0.3, vChip + ch * 0.6, zChip - 1.5],
          [uChip - cw * 0.4, vChip + ch * 0.4, zChip - 1.5]
        ],
        "#2a231e", 245, false
      );
      // Micro-shadow at upper rim of chip
      line3D(
        [uChip - cw * 0.5, vChip - ch * 0.4, zChip - 0.5],
        [uChip + cw * 0.6, vChip - ch * 0.2, zChip - 0.5],
        "2B", "#0d0b0a", 0.42
      );
      // Bright fractured celluloid thickness catch-light on lower rim of chip
      spline3D(
        [
          [uChip - cw * 0.4, vChip + ch * 0.4, zChip, 0.7],
          [uChip + cw * 0.3, vChip + ch * 0.6, zChip, 1.2],
          [uChip + cw * 0.6, vChip - ch * 0.2, zChip, 0.6]
        ],
        0.3, "cpencil", "#ffffff", 0.5
      );
    }

    // --- G. FINGERPRINT SMUDGES & MICRO SURFACE WEAR ON KEYS ---
    if (smudgedKeys.has(k)) {
      let uSmudge = random(315, 395);
      let vSmudge = (v1 + v2) * 0.5 + random(-8, 8);
      let tiltSmudge = random(-22, 18);

      // Subtle warm oily halo that slightly mutes the nacre contrast
      let haloPts = [];
      for (let a = 0; a < 360; a += 45) {
        let du = cos(a) * 28;
        let dv = sin(a) * 19;
        haloPts.push([uSmudge + du, vSmudge + dv, zTop]);
      }
      fillPoly3D(haloPts, "#e3dccb", 65, true, 0.06);

      // Concentric fingerprint whorl ridges in ultra-fine 2H graphite & cream pencil
      for (let r = 3.5; r <= 24; r += 2.4) {
        let aStart = random(-150, -40);
        let aEnd = aStart + random(110, 210);
        let ridgePts = [];
        for (let a = aStart; a <= aEnd; a += 28) {
          let radU = r * 1.35;
          let radV = r * 0.92;
          let du0 = cos(a) * radU;
          let dv0 = sin(a) * radV;
          let du = du0 * cos(tiltSmudge) - dv0 * sin(tiltSmudge);
          let dv = du0 * sin(tiltSmudge) + dv0 * cos(tiltSmudge);
          ridgePts.push([
            constrain(uSmudge + du, uKeyStart + 10, uTipStart + 8),
            constrain(vSmudge + dv, v1 + 5, v2 - 5),
            zTop,
            0.75
          ]);
        }
        let ridgeCol = r % 4.8 < 2.4 ? "#9ca3b0" : "#f7f1e3";
        spline3D(ridgePts, 0.5, "2H", ridgeCol, 0.24);
      }
    }
  }

  // =========================================================================
  // 4. RAKING CAST SHADOWS FROM BLACK KEYS & TREBLE CASING ONTO WHITE KEYS
  // =========================================================================
  const uBlackEnd = 256;
  const uBlackSlopeStart = 212;
  const blackW = 45;

  // A. Long shadow cast by the treble casing overhang (u = 0..24) across all keys
  fillPoly3D(
    [[0, -820, 22.5], [26, -820, 22.5], [26, 900, 22.5], [0, 900, 22.5]],
    "#1b2029", 165, true, 0.05
  );
  hatchQuad3D(
    [0, -750, 22.5], [22, -750, 22.5], [22, 850, 22.5], [0, 850, 22.5],
    95, "2B", "#11141b", 0.42, 0.8
  );

  // B. Raking diagonal cast shadows of each Black Key onto the White Keys below
  for (let k = -7; k <= 9; k++) {
    if (!hasBlackKeyAfter(k)) continue;

    let vBoundary = (k + 1) * keyPitch - keyGap * 0.5;
    let mod = ((k % 7) + 7) % 7;
    let vShift = mod === 0 || mod === 3 ? -3.5 : mod === 1 || mod === 5 ? 3.5 : 0;
    let vB1 = vBoundary - blackW * 0.5 + vShift;
    let vB2 = vBoundary + blackW * 0.5 + vShift;

    // Raking light from upper-left (-v, -u) casts shadow toward (+v, +u)
    let duShadow = 32;
    let dvShadow = 42;
    let zShadow = 22.2;

    let shadowPoly = [
      [0, vB2, zShadow],
      [uBlackSlopeStart, vB2, zShadow],
      [uBlackEnd + duShadow * 0.65, vB2 + dvShadow * 0.72, zShadow],
      [uBlackSlopeStart + duShadow, vB2 + dvShadow, zShadow],
      [0, vB2 + dvShadow, zShadow]
    ];

    // Cool translucent slate-violet shadow wash (preserving nacre texture underneath)
    fillPoly3D(shadowPoly, "#2b313f", 145, true, 0.05);

    // Directional graphite hatching inside the cast shadow
    hatchQuad3D(
      [4, vB2 + 1, zShadow],
      [uBlackSlopeStart + 10, vB2 + 4, zShadow],
      [uBlackSlopeStart + duShadow - 4, vB2 + dvShadow - 2, zShadow],
      [4, vB2 + dvShadow - 2, zShadow],
      32, "HB", "#1e232e", 0.36, 0.6
    );
    // Crisp dark umbra core right against the base of the black key
    hatchQuad3D(
      [2, vB2, zShadow],
      [uBlackEnd - 8, vB2, zShadow],
      [uBlackEnd + 4, vB2 + 11, zShadow],
      [2, vB2 + 11, zShadow],
      14, "2B", "#0f1218", 0.42, 0.3
    );
  }

  // =========================================================================
  // 5. BLACK KEYS (SHARPS/FLATS) IN DENSE GRAPHITE
  // Drawn back-to-front (k = -7 to +9), elevated at z = 22 .. 50
  // =========================================================================
  for (let k = -7; k <= 9; k++) {
    if (!hasBlackKeyAfter(k)) continue;

    let vBoundary = (k + 1) * keyPitch - keyGap * 0.5;
    let mod = ((k % 7) + 7) % 7;
    let vShift = mod === 0 || mod === 3 ? -3.5 : mod === 1 || mod === 5 ? 3.5 : 0;
    let vB1 = vBoundary - blackW * 0.5 + vShift;
    let vB2 = vBoundary + blackW * 0.5 + vShift;

    let zBase = 22.0;
    let zCrown = 50.0;
    let taper = 5.0; // Top of black key is slightly narrower than its base

    // --- A. +V SIDE WALL OF BLACK KEY (glossy ebony reflecting adjacent pearloid) ---
    let sideWall = [
      [0, vB2, zBase],
      [uBlackEnd, vB2 - 2, zBase],
      [uBlackEnd - 8, vB2 - taper, zBase + 10],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [0, vB2 - taper, zCrown]
    ];
    fillPoly3D(sideWall, "#101319", 252, false);

    // Dense graphite hatching on side wall
    hatchQuad3D(
      [0, vB2, zBase], [uBlackSlopeStart, vB2, zBase],
      [uBlackSlopeStart, vB2 - taper, zCrown], [0, vB2 - taper, zCrown],
      22, "charcoal", "#07090d", 0.55, 0.5
    );

    // Reflected pearloid bounce-light band along the middle-lower glossy side wall
    fillPoly3D(
      [
        [12, vB2 - 1.5, zBase + 5],
        [uBlackSlopeStart + 10, vB2 - 2, zBase + 5],
        [uBlackSlopeStart + 4, vB2 - 3.2, zBase + 15],
        [12, vB2 - 3.0, zBase + 15]
      ],
      "#6e6b78", 130, true, 0.04
    );
    for (let bLine = 0; bLine < 7; bLine++) {
      let zB = zBase + 6 + bLine * 1.4;
      let colB = bLine % 2 === 0 ? "#8d8998" : "#788886"; // faint pink & celadon bounce
      line3D(
        [14, vB2 - 2, zB],
        [uBlackSlopeStart + 8 - bLine * 2, vB2 - 2.5, zB],
        "cpencil", colB, 0.34
      );
    }
    // Jet-black base crease where black key meets the white key slot
    line3D([0, vB2, zBase], [uBlackEnd, vB2 - 2, zBase], "2B", "#040507", 0.65);

    // --- B. SLOPED & ROUNDED FRONT NOSE OF BLACK KEY (u = uBlackSlopeStart .. uBlackEnd) ---
    let frontNose = [
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackEnd - 6, vB1 + taper + 3, zBase + 11],
      [uBlackEnd, (vB1 + vB2) * 0.5, zBase + 2],
      [uBlackEnd - 2, vB2 - 2, zBase],
      [uBlackEnd - 8, vB2 - taper, zBase + 10],
      [uBlackSlopeStart, vB2 - taper, zCrown]
    ];
    fillPoly3D(frontNose, "#1c2029", 248, false);
    hatchQuad3D(
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [uBlackEnd - 4, vB2 - 4, zBase + 4],
      [uBlackEnd - 4, vB1 + 4, zBase + 4],
      18, "2B", "#101319", 0.45, 0.4
    );

    // --- C. CROWNED TOP SURFACE OF BLACK KEY (z = zCrown) ---
    let topFace = [
      [0, vB1 + taper, zCrown],
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackSlopeStart + 10, (vB1 + vB2) * 0.5, zCrown - 2],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [0, vB2 - taper, zCrown]
    ];
    fillPoly3D(topFace, "#242934", 248, false);

    // Lengthwise dense graphite burnishing on black key crown
    hatchQuad3D(
      [0, vB1 + taper + 2, zCrown],
      [uBlackSlopeStart, vB1 + taper + 2, zCrown],
      [uBlackSlopeStart, vB2 - taper - 2, zCrown],
      [0, vB2 - taper - 2, zCrown],
      24, "2B", "#151921", 0.46, 0.5
    );
    // Soft satin sheen along the upper-center of the crowned top
    for (let s = 0; s < 10; s++) {
      let vS = lerp(vB1 + taper + 2, (vB1 + vB2) * 0.52, s / 9);
      line3D(
        [8, vS, zCrown + 0.5],
        [uBlackSlopeStart - 4, vS, zCrown + 0.5],
        "HB", s < 4 ? "#6d7687" : "#444b59", 0.36
      );
    }

    // --- D. RAZOR-SHARP RAKING SPECULAR HIGHLIGHT ON UPPER (-V) BEVEL & NOSE ---
    spline3D(
      [
        [4, vB1 + taper + 0.8, zCrown + 0.4, 0.7],
        [uBlackSlopeStart * 0.55, vB1 + taper + 0.8, zCrown + 0.5, 1.2],
        [uBlackSlopeStart, vB1 + taper + 1.2, zCrown + 0.4, 1.3],
        [uBlackEnd - 8, vB1 + taper + 5, zBase + 11, 1.0],
        [uBlackEnd - 2, (vB1 + vB2) * 0.5, zBase + 4, 0.5]
      ],
      0.4, "cpencil", "#ffffff", 0.65
    );
    // Secondary silver-blue edge sheen beside the main specular highlight
    spline3D(
      [
        [8, vB1 + taper + 2.8, zCrown, 0.6],
        [uBlackSlopeStart, vB1 + taper + 3.0, zCrown, 1.0],
        [uBlackEnd - 10, (vB1 + vB2) * 0.46, zBase + 12, 0.7]
      ],
      0.4, "2H", "#b8c4d6", 0.4
    );

    // --- E. FINGERPRINT SMUDGE & FINE CELLULOID SCRATCHES ON CENTRAL BLACK KEYS ---
    if (k >= 0 && k <= 5) {
      let uSm = random(135, 195);
      let vSm = (vB1 + vB2) * 0.5;
      for (let r = 3; r <= 12; r += 2.6) {
        spline3D(
          [
            [uSm - r * 1.4, vSm - r * 0.5, zCrown + 0.5, 0.5],
            [uSm, vSm - r * 0.8, zCrown + 0.5, 0.9],
            [uSm + r * 1.4, vSm - r * 0.3, zCrown + 0.5, 0.6],
            [uSm + r * 0.9, vSm + r * 0.6, zCrown + 0.5, 0.4]
          ],
          0.55, "2H", "#7c8596", 0.24
        );
      }
    }
  }

  // =========================================================================
  // 6. TREBLE CASING, CELLULOID HOUSING, GRILLE SLOTS & CHROME GRILLE BOLTS
  // u in [-138, 6], v in [-820, 880], z = 22 .. 56
  // =========================================================================
  const uFrameLeft = -138;
  const uFrameRight = 6;
  const zFrameTop = 41;

  // --- A. STEPPED BLACK CELLULOID KEYBOARD LIP (u = -12 .. 6, z = 22 .. 41) ---
  fillPoly3D(
    [
      [-10, -820, zFrameTop],
      [6, -820, 24],
      [6, 890, 24],
      [-10, 890, zFrameTop]
    ],
    "#0f1218", 252, false
  );
  hatchQuad3D(
    [-10, -760, zFrameTop], [6, -760, 24],
    [6, 840, 24], [-10, 840, zFrameTop],
    95, "charcoal", "#07090d", 0.55, 0.6
  );

  // --- B. MAIN BLACK CELLULOID TREBLE CASING DECK (u = -138 .. -10, z = 41) ---
  fillPoly3D(
    [
      [uFrameLeft, -820, zFrameTop - 3],
      [-10, -820, zFrameTop],
      [-10, 890, zFrameTop],
      [uFrameLeft, 890, zFrameTop - 3]
    ],
    "#181c24", 250, false
  );

  // Dense directional graphite toning across the black celluloid casing
  hatchQuad3D(
    [uFrameLeft, -760, zFrameTop - 3], [-10, -760, zFrameTop],
    [-10, 840, zFrameTop], [uFrameLeft, 840, zFrameTop - 3],
    140, "2B", "#10131a", 0.52, 1.0
  );

  // Broad soft lateral specular sheen along the rounded celluloid ridge (u = -22 .. -8)
  for (let s = 0; s < 9; s++) {
    let uS = lerp(-24, -9, s / 8);
    let col = s === 5 || s === 6 ? "#c6d0df" : s > 3 ? "#7b8596" : "#404754";
    let w = s === 5 || s === 6 ? 0.52 : 0.38;
    line3D([uS, -760, zFrameTop + 0.5], [uS, 840, zFrameTop + 0.5], "HB", col, w);
  }
  // Secondary highlight along the bellows-side bezel (u = -134)
  line3D([uFrameLeft + 4, -760, zFrameTop - 2], [uFrameLeft + 4, 840, zFrameTop - 2], "HB", "#6b7485", 0.45);
  line3D([uFrameLeft, -760, zFrameTop - 4], [uFrameLeft, 840, zFrameTop - 4], "charcoal", "#06070a", 0.85);

  // --- C. DECORATIVE ART-DECO GRILLE FRETWORK SLOTS (u in [-118, -56]) ---
  for (let g = -6; g <= 7; g++) {
    let vG1 = g * 104 - 34;
    let vG2 = vG1 + 66;
    let uG1 = -116;
    let uG2 = -58;

    // Stepped slot cutout revealing deep black grille cloth underneath
    let slotPoly = [
      [uG1, vG1 + 8, zFrameTop - 1],
      [uG2, vG1, zFrameTop - 1],
      [uG2, vG2 - 8, zFrameTop - 1],
      [uG1, vG2, zFrameTop - 1]
    ];
    fillPoly3D(slotPoly, "#07080c", 252, false);

    // Woven metal mesh texture deep inside the grille slot
    for (let m = vG1 + 8; m < vG2 - 6; m += 9) {
      line3D([uG1 + 6, m, zFrameTop - 4], [uG2 - 6, m - 5, zFrameTop - 4], "2H", "#2a303c", 0.28);
      line3D([uG1 + 8, m - 4, zFrameTop - 4], [uG2 - 8, m + 5, zFrameTop - 4], "2H", "#1f242e", 0.28);
    }

    // Lit lower-right celluloid inner thickness rim of the cutout
    line3D([uG1, vG2, zFrameTop], [uG2, vG2 - 8, zFrameTop], "cpencil", "#b4bfd0", 0.44);
    line3D([uG2, vG1, zFrameTop], [uG2, vG2 - 8, zFrameTop], "HB", "#788294", 0.38);
    // Dark shadow rim on upper edge of cutout
    line3D([uG1, vG1 + 8, zFrameTop], [uG2, vG1, zFrameTop], "2B", "#040507", 0.55);
  }

  // --- D. TINY CELLULOID CHIPS & FINGERPRINT SMUDGES ON THE BLACK CASING ---
  const casingChips = [-285, -35, 215, 485];
  for (let vc of casingChips) {
    // Small jagged chip along the right casing edge (u ~ -10) exposing pale wood/core
    fillPoly3D(
      [
        [-15, vc - 6, zFrameTop - 1],
        [-8, vc - 4, zFrameTop - 2],
        [-8, vc + 7, zFrameTop - 2],
        [-16, vc + 4, zFrameTop - 1]
      ],
      "#6e6256", 240, false
    );
    line3D([-15, vc - 6, zFrameTop], [-8, vc - 4, zFrameTop - 1], "2B", "#050608", 0.45);
    line3D([-16, vc + 4, zFrameTop], [-8, vc + 7, zFrameTop - 1], "cpencil", "#ffffff", 0.48);
  }

  // --- E. HYPERREALIST CHROME GRILLE BOLTS (KNURLED THUMBSCREWS) ---
  const boltPositions = [-410, -110, 190, 490];
  for (let bIdx = 0; bIdx < boltPositions.length; bIdx++) {
    let uB = -33;
    let vB = boltPositions[bIdx];
    let rWasher = 25;
    let rCollar = 20;
    let rDome = 17.5;
    let zBaseB = zFrameTop;

    // 1. Oily fingerprint smudge halo on the black celluloid around the bolt
    for (let r = rWasher + 4; r <= rWasher + 20; r += 3.2) {
      let smPts = [];
      for (let a = -60; a <= 150; a += 30) {
        smPts.push([uB + cos(a) * r * 0.9, vB + sin(a) * r * 1.15, zBaseB + 0.2, 0.6]);
      }
      spline3D(smPts, 0.5, "2H", r % 6 < 3 ? "#4c5464" : "#252a35", 0.26);
    }

    // 2. Cast shadow of the bolt onto the celluloid deck (shifted toward +u, +v)
    let shPts = [];
    for (let a = 0; a < 360; a += 20) {
      shPts.push([uB + 7 + cos(a) * (rWasher + 2), vB + 11 + sin(a) * (rWasher + 3), zBaseB + 0.3]);
    }
    fillPoly3D(shPts, "#050609", 235, false);

    // 3. Recessed Chrome Washer Seat (z = zBaseB + 1.5)
    let washerPts = [];
    for (let a = 0; a < 360; a += 18) {
      washerPts.push([uB + cos(a) * rWasher, vB + sin(a) * rWasher, zBaseB + 1.5]);
    }
    fillPoly3D(washerPts, "#495160", 248, false);
    // High-contrast chrome reflection sectors on washer rim
    for (let a = 0; a < 360; a += 8) {
      let cW = (a > 190 && a < 310) ? "#ffffff" : (a > 20 && a < 130) ? "#11141c" : "#8b95a6";
      line3D(
        [uB + cos(a) * (rCollar + 1), vB + sin(a) * (rCollar + 1), zBaseB + 1.8],
        [uB + cos(a) * rWasher, vB + sin(a) * rWasher, zBaseB + 1.5],
        "2H", cW, 0.36
      );
    }

    // 4. Knurled Cylindrical Collar (z = zBaseB + 2 .. zBaseB + 9)
    let zColTop = zBaseB + 9.5;
    for (let a = 0; a < 360; a += 10) {
      let uK1 = uB + cos(a) * rCollar;
      let vK1 = vB + sin(a) * rCollar;
      let uK2 = uB + cos(a + 8) * rCollar;
      let vK2 = vB + sin(a + 8) * rCollar;

      // Alternating high-contrast knurl grooves
      let knurlLight = sin(a * 2.5) + cos(a - 235);
      let kCol = knurlLight > 0.75 ? "#ffffff" : knurlLight > 0.0 ? "#9aa4b5" : knurlLight > -0.7 ? "#39404d" : "#0b0d12";
      fillPoly3D(
        [
          [uK1, vK1, zBaseB + 2],
          [uK2, vK2, zBaseB + 2],
          [uK2, vK2, zColTop],
          [uK1, vK1, zColTop]
        ],
        kCol, 248, false
      );
      line3D([uK1, vK1, zBaseB + 2], [uK1, vK1, zColTop], "2B", "#0d1016", 0.35);
      if (knurlLight > 0.4) {
        line3D(
          [(uK1 + uK2) * 0.5, (vK1 + vK2) * 0.5, zBaseB + 2.5],
          [(uK1 + uK2) * 0.5, (vK1 + vK2) * 0.5, zColTop - 0.5],
          "cpencil", "#ffffff", 0.38
        );
      }
    }

    // 5. Mirror-Chrome Domed Head (z = zColTop .. zBaseB + 15.5)
    let zDomeApex = zBaseB + 15.5;
    let domeOutline = [];
    for (let a = 0; a < 360; a += 15) {
      domeOutline.push([uB + cos(a) * rDome, vB + sin(a) * rDome, zColTop + 0.5]);
    }
    fillPoly3D(domeOutline, "#cdd5e3", 250, false);

    // Dark warped horizon reflection across the lower-right hemisphere of the chrome dome
    fillPoly3D(
      [
        [uB - rDome * 0.85, vB + rDome * 0.1, zColTop + 2],
        [uB, vB - rDome * 0.15, zDomeApex],
        [uB + rDome * 0.92, vB - rDome * 0.2, zColTop + 2],
        [uB + rDome * 0.85, vB + rDome * 0.55, zColTop + 1.5],
        [uB, vB + rDome * 0.85, zColTop + 1.5],
        [uB - rDome * 0.65, vB + rDome * 0.6, zColTop + 1.5]
      ],
      "#0d1017", 245, false
    );

    // Secondary reflection of the pearloid keys (pale pink & celadon band) in lower rim of dome
    for (let a = 15; a <= 145; a += 12) {
      let cRef = a < 75 ? "#ebccd5" : "#c5ded6";
      line3D(
        [uB + cos(a) * (rDome * 0.58), vB + sin(a) * (rDome * 0.58), zColTop + 3],
        [uB + cos(a + 12) * (rDome * 0.78), vB + sin(a + 12) * (rDome * 0.78), zColTop + 2],
        "cpencil", cRef, 0.45
      );
    }

    // Concentric lathe-turned graphite rings on the dome
    for (let ringR = 4; ringR <= rDome; ringR += 2.8) {
      let ringZ = lerp(zDomeApex, zColTop + 0.5, pow(ringR / rDome, 1.4));
      let ringPts = [];
      for (let a = 0; a <= 360; a += 30) {
        ringPts.push([uB + cos(a) * ringR, vB + sin(a) * ringR, ringZ, 0.7]);
      }
      let ringCol = ringR < 9 ? "#eef3fa" : "#5a6373";
      spline3D(ringPts, 0.5, "2H", ringCol, 0.28);
    }

    // Blinding white studio light reflection on upper-left quadrant of chrome dome
    fillPoly3D(
      [
        [uB - rDome * 0.75, vB - rDome * 0.2, zColTop + 2.5],
        [uB - rDome * 0.2, vB - rDome * 0.8, zColTop + 2.5],
        [uB + rDome * 0.15, vB - rDome * 0.35, zDomeApex - 1],
        [uB - rDome * 0.25, vB + rDome * 0.05, zDomeApex]
      ],
      "#ffffff", 250, false
    );
    for (let h = 0; h < 8; h++) {
      let ang = 200 + h * 11;
      line3D(
        [uB + cos(ang) * 3, vB + sin(ang) * 3, zDomeApex],
        [uB + cos(ang) * (rDome - 1.5), vB + sin(ang) * (rDome - 1.5), zColTop + 1.5],
        "cpencil", "#ffffff", 0.58
      );
    }

    // 6. Machined Screwdriver Slot across the Chrome Dome
    let slotAng = 32 + bIdx * 23;
    let dxS = cos(slotAng) * (rDome - 1.5);
    let dyS = sin(slotAng) * (rDome - 1.5);
    let nxS = -sin(slotAng) * 2.4;
    let nyS = cos(slotAng) * 2.4;

    fillPoly3D(
      [
        [uB - dxS - nxS, vB - dyS - nyS, zColTop + 3],
        [uB + dxS - nxS, vB + dyS - nyS, zColTop + 3],
        [uB + dxS + nxS, vB + dyS + nyS, zColTop + 3],
        [uB - dxS + nxS, vB - dyS + nyS, zColTop + 3]
      ],
      "#080a0f", 252, false
    );
    // Razor-sharp specular catch-light along the lower-right lip of the machined slot
    line3D(
      [uB - dxS + nxS, vB - dyS + nyS, zColTop + 3.5],
      [uB + dxS + nxS, vB + dyS + nyS, zColTop + 3.5],
      "cpencil", "#ffffff", 0.62
    );
  }

  // =========================================================================
  // 7. FINAL HYPERREALIST GRAPHITE GRAIN & MICRO-DUST POLISH
  // =========================================================================
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Subtle graphite dust & paper tooth across the dark bellows and casing shadows
  for (let i = 0; i < 180; i++) {
    let uG = random(-750, 450);
    let vG = random(-700, 800);
    let zG = uG < 0 ? 35 : 22;
    let [x, y] = proj(uG, vG, zG);
    if (x < 0 || x > width || y < 0 || y > height) continue;

    if (uG < -20) {
      // Micro-graphite stipple and hairline scratches on bellows & casing
      brush.set("2H", random() < 0.35 ? "#697282" : "#141820", 0.24);
      let ang = random(360);
      let len = random(4, 14);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    } else {
      // Faint playing micro-scratches on the glossy pearloid celluloid keys
      brush.set("cpencil", random() < 0.5 ? "#ffffff" : "#b8c0ce", 0.22);
      let len = random(6, 18);
      brush.line(x, y, x + cos(25) * len, y + sin(25) * len);
    }
  }
}

// ===========================================================================
// ANIMATION CHOREOGRAPHY & HELPERS (FRAMES 2 .. 48)
// ===========================================================================

// Smoothstep helper
function smoothStep(edge0, edge1, x) {
  let u = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return u * u * (3 - 2 * u);
}

// White key depression depth (in 3D z-units at the front nose, 0 .. 20.5)
function getWhiteKeyDrop(k, t) {
  if (t <= 0) return 0;
  // Immediate smooth ramp-in from 0 on frame 1 so frame 2 has no pop, full strength by frame 5
  let env = smoothStep(0.0, 0.12, t);

  // Wave 1: Bold cascading downward glissando + parallel sixths/tenths (t = 0 .. 1.35s)
  let w1Env = 1.0 - smoothStep(1.05, 1.48, t);
  let c1 = -4.2 + t * 10.4;
  let f1a = exp(-pow(k - c1, 2) * 1.18);
  let f1b = exp(-pow(k - (c1 - 2.4), 2) * 1.18) * 0.92;
  let f1c = exp(-pow(k - (c1 + 2.9), 2) * 1.18) * 0.88;
  let f1d = exp(-pow(k - (c1 + 5.6), 2) * 1.18) * 0.82 * (1.0 - smoothStep(0.55, 0.95, t));
  let wave1 = max(max(f1a, f1b), max(f1c, f1d)) * w1Env;

  // Wave 2: Expressive upward counter-run & chordal trill (t = 0.62 .. 2.0s)
  let w2Env = smoothStep(0.58, 0.88, t);
  let c2 = 5.6 - (t - 0.65) * 9.0;
  let f2a = exp(-pow(k - c2, 2) * 1.18);
  let f2b = exp(-pow(k - (c2 + 2.4), 2) * 1.18) * 0.92;
  let f2c = exp(-pow(k - (c2 - 2.6), 2) * 1.18) * 0.86;
  let f2d = exp(-pow(k - (c2 - 5.2), 2) * 1.18) * 0.78;
  let wave2 = max(max(f2a, f2b), max(f2c, f2d)) * w2Env;

  // Strong finger articulation contrast between adjacent keys so step-shadows pop
  let artic = 0.84 + 0.16 * sin(k * 135 + t * 720);
  return 20.5 * env * max(wave1, wave2) * artic;
}

// Black key depression depth (in 3D z-units at the front nose, 0 .. 17.5)
function getBlackKeyDrop(k, t) {
  if (t <= 0 || !hasBlackKeyAfterIndex(k)) return 0;
  let env = smoothStep(0.0, 0.12, t);
  let kb = k + 0.5;

  let w1Env = 1.0 - smoothStep(1.05, 1.48, t);
  let c1 = -3.5 + t * 10.4;
  let b1a = exp(-pow(kb - c1, 2) * 1.35);
  let b1b = exp(-pow(kb - (c1 - 2.4), 2) * 1.35) * 0.9;
  let b1c = exp(-pow(kb - (c1 + 2.8), 2) * 1.35) * 0.85;
  let wave1 = max(b1a, max(b1b, b1c)) * w1Env;

  let w2Env = smoothStep(0.58, 0.88, t);
  let c2 = 5.1 - (t - 0.65) * 9.0;
  let b2a = exp(-pow(kb - c2, 2) * 1.35);
  let b2b = exp(-pow(kb - (c2 + 2.3), 2) * 1.35) * 0.88;
  let b2c = exp(-pow(kb - (c2 - 2.7), 2) * 1.35) * 0.82;
  let wave2 = max(b2a, max(b2b, b2c)) * w2Env;

  return 17.5 * env * max(wave1, wave2);
}

// Bellows breathing expansion (in 3D u-units, anchored at u = -135)
function getBellowsBreath(t) {
  if (t <= 0) return 0;
  let env = smoothStep(0.0, 0.12, t);
  return env * (sin(t * 170) * 21.0 + sin(t * 340) * 6.5);
}

// Helper: Push a textured quad (two triangles) into a vertex buffer array
function pushTexQuad(tris, pA_new, pB_new, pC_new, pD_new, pA_uv, pB_uv, pC_uv, pD_uv) {
  tris.push([pA_new[0], pA_new[1], pA_uv[0], pA_uv[1]]);
  tris.push([pB_new[0], pB_new[1], pB_uv[0], pB_uv[1]]);
  tris.push([pC_new[0], pC_new[1], pC_uv[0], pC_uv[1]]);

  tris.push([pA_new[0], pA_new[1], pA_uv[0], pA_uv[1]]);
  tris.push([pC_new[0], pC_new[1], pC_uv[0], pC_uv[1]]);
  tris.push([pD_new[0], pD_new[1], pD_uv[0], pD_uv[1]]);
}

// Helper: Render an array of textured triangle vertices from stillImg
function flushTexTriangles(tris) {
  if (tris.length === 0) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  push();
  noStroke();
  fill(255);
  tint(255);
  textureMode(IMAGE);
  texture(stillImg);
  beginShape(TRIANGLES);
  for (let i = 0; i < tris.length; i++) {
    let v = tris[i];
    vertex(v[0], v[1], 0, v[2], v[3]);
  }
  endShape();
  pop();
}

// Helper: 3D polygon wash/fill for dynamic shadows & highlights
function animFillPoly3D(pts3D, col, alpha = 255) {
  brush.noStroke();
  brush.noHatch();
  brush.noFill();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts3D.length; i++) {
    let [x, y] = proj3D(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noWash();
}

function animLine3D(p1, p2, bName, col, w) {
  let [x1, y1] = proj3D(p1[0], p1[1], p1[2] || 0);
  let [x2, y2] = proj3D(p2[0], p2[1], p2[2] || 0);
  brush.set(bName, col, w);
  brush.line(x1, y1, x2, y2);
}

function animSpline3D(pts3D, curv, bName, col, w) {
  if (pts3D.length < 2) return;
  let pts2D = [];
  for (let i = 0; i < pts3D.length; i++) {
    let [x, y] = proj3D(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
    let pr = pts3D[i][3] !== undefined ? pts3D[i][3] : 1.0;
    pts2D.push([x, y, pr]);
  }
  brush.set(bName, col, w);
  brush.spline(pts2D, curv);
}

function animHatchQuad3D(pA, pB, pC, pD, steps, bName, col, w, jitter = 0) {
  brush.set(bName, col, w);
  for (let i = 0; i <= steps; i++) {
    let s = i / max(1, steps);
    let u1 = lerp(pA[0], pD[0], s) + (jitter ? random(-jitter, jitter) : 0);
    let v1 = lerp(pA[1], pD[1], s) + (jitter ? random(-jitter, jitter) : 0);
    let z1 = lerp(pA[2] || 0, pD[2] || 0, s);
    let u2 = lerp(pB[0], pC[0], s) + (jitter ? random(-jitter, jitter) : 0);
    let v2 = lerp(pB[1], pC[1], s) + (jitter ? random(-jitter, jitter) : 0);
    let z2 = lerp(pB[2] || 0, pC[2] || 0, s);
    let [x1, y1] = proj3D(u1, v1, z1);
    let [x2, y2] = proj3D(u2, v2, z2);
    brush.line(x1, y1, x2, y2);
  }
}

// ===========================================================================
// MAIN FILM LOOP
// ===========================================================================
function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  // Frame 0: Exact pixel-for-pixel still painting
  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  const t = (frameCount - 1) / window.PIECE_FPS;

  // Base canvas setup in top-left coordinates
  background("#f3eee3");
  translate(-width / 2, -height / 2);

  // Stamp the cached still backdrop
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  push();
  noStroke();
  fill(255);
  tint(255);
  image(stillImg, 0, 0);
  pop();

  // =========================================================================
  // 1. ANIMATED BELLOWS BREATHING (u in [-860, -135])
  // =========================================================================
  const breath = getBellowsBreath(t);
  const bellowsStartU = -135;
  const foldSpan = 138;
  const numFolds = 5;

  // Clear under-bellows studio shadow before drawing breathing pleats
  animFillPoly3D(
    [[-890, -880, -60], [-132, -880, -60], [-132, 940, -60], [-890, 940, -60]],
    "#101217", 252
  );

  function bellowsDisp(uOrig, zOrig, isPeak = false) {
    let distFactor = constrain((bellowsStartU - uOrig) / 520, 0, 1.45);
    let uNew = uOrig - breath * distFactor;
    let zNew = zOrig + (isPeak ? -breath * 0.24 * distFactor : breath * 0.06 * distFactor);
    return [uNew, zNew];
  }

  let bellowsTris = [];
  let vBands = [-850, -350, -165, 60, 380, 920];

  for (let f = numFolds - 1; f >= 0; f--) {
    let uRight = bellowsStartU - f * foldSpan;
    let uPeak = uRight - foldSpan * 0.52;
    let uLeft = uRight - foldSpan;
    let zVal = -52;
    let zPeak = 34 - f * 2.5;

    let [uLeftN, zLeftN] = bellowsDisp(uLeft, zVal, false);
    let [uPeakN, zPeakN] = bellowsDisp(uPeak, zPeak, true);
    let [uRightN, zRightN] = bellowsDisp(uRight, zVal, false);

    for (let vb = 0; vb < vBands.length - 1; vb++) {
      let vA = vBands[vb];
      let vB = vBands[vb + 1];

      // Left-sloping pleat facet (uLeft .. uPeak)
      pushTexQuad(
        bellowsTris,
        proj3D(uLeftN, vA, zLeftN),
        proj3D(uPeakN, vA, zPeakN),
        proj3D(uPeakN, vB, zPeakN),
        proj3D(uLeftN, vB, zLeftN),
        proj3D(uLeft, vA, zVal),
        proj3D(uPeak, vA, zPeak),
        proj3D(uPeak, vB, zPeak),
        proj3D(uLeft, vB, zVal)
      );

      // Right-sloping pleat facet (uPeak .. uRight)
      pushTexQuad(
        bellowsTris,
        proj3D(uPeakN, vA, zPeakN),
        proj3D(uRightN, vA, zRightN),
        proj3D(uRightN, vB, zRightN),
        proj3D(uPeakN, vB, zPeakN),
        proj3D(uPeak, vA, zPeak),
        proj3D(uRight, vA, zVal),
        proj3D(uRight, vB, zVal),
        proj3D(uPeak, vB, zPeak)
      );
    }
  }
  flushTexTriangles(bellowsTris);

  // Dynamic raking glints on the breathing bellows corners & ridges
  for (let f = numFolds - 1; f >= 0; f--) {
    randomSeed(51000 + f * 521);
    noiseSeed(61000 + f * 521);

    let uRight = bellowsStartU - f * foldSpan;
    let uPeak = uRight - foldSpan * 0.52;
    let zPeak = 34 - f * 2.5;
    let vCorner = -165 + f * 48;
    let [uPeakN, zPeakN] = bellowsDisp(uPeak, zPeak, true);

    let glintAmt = constrain(abs(breath) / 20.0, 0, 1);
    if (glintAmt > 0.03) {
      // Specular glints on the embossed metal corner ribs
      for (let rib = -1; rib <= 1; rib++) {
        let rv = vCorner + 4 + rib * 13;
        let shiftU = sin(t * 240 + f * 40 + rib * 30) * 3.0;
        animLine3D(
          [uPeakN - 8 + shiftU, rv - 0.5, zPeakN + 3.6],
          [uPeakN + 5 + shiftU, rv + 0.5, zPeakN + 4.3],
          "cpencil", "#ffffff", 0.42 + 0.45 * glintAmt
        );
      }
      // Shifting raking light along the worn black cloth pleat ridge
      for (let vS = vCorner + 65; vS < 860; vS += 64) {
        animLine3D(
          [uPeakN - 4, vS, zPeakN + 0.5],
          [uPeakN + 1, vS + 26, zPeakN + 0.5],
          "HB", "#c6d0df", 0.35 * glintAmt
        );
      }
    }
  }

  // =========================================================================
  // 2. RIPPLING PEARLOID WHITE KEYS & BLACK KEYS
  // =========================================================================
  // Clear the keybed under-shadow beneath the moving keys so depressed keys
  // reveal dark keybed space instead of ghosts of their unpressed positions
  animFillPoly3D(
    [[0, -780, 0], [468, -780, 0], [468, 920, 0], [0, 920, 0]],
    "#0a0c10", 255
  );

  // Lever drop along u for a given tip depression D (pivoting around u = -45)
  function leverDrop(u, tipDrop) {
    return tipDrop * ((u + 45) / (U_KEY_END + 45));
  }

  // --- A. WHITE KEYS (BACK-TO-FRONT: k = -7 .. +10) ---
  const uGrid = [0, 125, 232, 258, 348, 434, 446, 456, 462];
  const vFracs = [0.0, 0.24, 0.5, 0.76, 1.0];

  for (let k = -7; k <= 10; k++) {
    let v1 = k * KEY_PITCH;
    let v2 = v1 + KEY_W;
    let zTop = getWhiteKeyRestZ(k);
    let zLaminateBot = zTop - 7.5;

    let dropCurr = getWhiteKeyDrop(k, t);
    let dropPrev = getWhiteKeyDrop(k - 1, t);

    // Determine adjacent black key UV-safety bounds for u < 258
    let hasPrevBlack = hasBlackKeyAfterIndex(k - 1);
    let vB2_prev = hasPrevBlack ? getBlackKeyBounds(k - 1)[1] : v1 - 10;
    let hasCurrBlack = hasBlackKeyAfterIndex(k);
    let vB1_curr = hasCurrBlack ? getBlackKeyBounds(k)[0] : v2 + 10;

    // 1. Dark wood lever under-wall at v = v2 (z = 0 .. zLaminateBot - drop)
    let dStart = leverDrop(U_KEY_START, dropCurr);
    let dTipS = leverDrop(U_TIP_START, dropCurr);
    let zLamStart = max(0.5, zLaminateBot - dStart);
    let zLamTip = max(0.5, zLaminateBot - dTipS);

    animFillPoly3D(
      [
        [U_KEY_START, v2, 0],
        [U_TIP_START, v2, 0],
        [U_TIP_START, v2, zLamTip],
        [U_KEY_START, v2, zLamStart]
      ],
      "#181514", 252
    );

    let keyTris = [];

    // 2. Textured +v pearloid side wall & nose corner wrap from stillImg
    for (let iu = 0; iu < 5; iu++) {
      let uA = uGrid[iu];
      let uB = uGrid[iu + 1];
      let dA = leverDrop(uA, dropCurr);
      let dB = leverDrop(uB, dropCurr);

      let zBotA_new = max(0, zLaminateBot - dA);
      let zTopA_new = zTop - dA;
      let zBotB_new = max(0, zLaminateBot - dB);
      let zTopB_new = zTop - dB;

      pushTexQuad(
        keyTris,
        proj3D(uA, v2, zBotA_new),
        proj3D(uB, v2, zBotB_new),
        proj3D(uB, v2, zTopB_new),
        proj3D(uA, v2, zTopA_new),
        proj3D(uA, v2, zLaminateBot),
        proj3D(uB, v2, zLaminateBot),
        proj3D(uB, v2, zTop),
        proj3D(uA, v2, zTop)
      );
    }

    // 3. Textured front vertical waterfall face at uKeyEnd (u = 462)
    let dEnd = leverDrop(U_KEY_END, dropCurr);
    let zNoseTopOrig = zTop - 4.5;
    let zNoseTopNew = zNoseTopOrig - dEnd;
    let zNoseBotNew = max(0.5, 3.0 - dEnd * 0.25);

    pushTexQuad(
      keyTris,
      proj3D(U_KEY_END, v1 + 7, zNoseBotNew),
      proj3D(U_KEY_END, v2 - 7, zNoseBotNew),
      proj3D(U_KEY_END, v2 - 7, zNoseTopNew),
      proj3D(U_KEY_END, v1 + 7, zNoseTopNew),
      proj3D(U_KEY_END, v1 + 7, 3.0),
      proj3D(U_KEY_END, v2 - 7, 3.0),
      proj3D(U_KEY_END, v2 - 7, zNoseTopOrig),
      proj3D(U_KEY_END, v1 + 7, zNoseTopOrig)
    );

    // Side corner wrap of the rounded waterfall nose
    pushTexQuad(
      keyTris,
      proj3D(U_TIP_START, v2, zLamTip),
      proj3D(U_KEY_END, v2 - 7, max(1.0, 4.0 - dEnd * 0.3)),
      proj3D(U_KEY_END, v2 - 7, zNoseTopNew),
      proj3D(U_TIP_START, v2, zTop - dTipS),
      proj3D(U_TIP_START, v2, zLaminateBot),
      proj3D(U_KEY_END, v2 - 7, 4.0),
      proj3D(U_KEY_END, v2 - 7, zNoseTopOrig),
      proj3D(U_TIP_START, v2, zTop)
    );

    // 4. Textured Top Surface & Waterfall Nose Mesh of White Key k
    function evalKeyVert(u, vf) {
      let zDroop = 0;
      let vInset = 0;
      if (u > U_TIP_START) {
        let nt = constrain((u - U_TIP_START) / (U_KEY_END - U_TIP_START), 0, 1);
        zDroop = pow(nt, 1.5) * 4.5;
        vInset = pow(nt, 1.5) * 7.0;
      }
      let v = lerp(v1 + vInset, v2 - vInset, vf);
      let zOrig = zTop - zDroop;
      let zNew = zOrig - leverDrop(u, dropCurr);

      // Clamp UV coordinates strictly outside adjacent black key footprints in stillImg
      let uTex = u;
      let vTex = v;
      if (u < 258.5) {
        if (hasPrevBlack && v < vB2_prev + 1.6) {
          if (u > 236) {
            uTex = 259.0;
          } else {
            vTex = vB2_prev + 1.6;
          }
        }
        if (hasCurrBlack && v > vB1_curr - 2.2) {
          if (u > 236) {
            uTex = 259.0;
          } else {
            vTex = vB1_curr - 2.2;
          }
        }
      }
      let zOrigTex = uTex > U_TIP_START
        ? zTop - pow(constrain((uTex - U_TIP_START) / (U_KEY_END - U_TIP_START), 0, 1), 1.5) * 4.5
        : zTop;

      return {
        pos: proj3D(u, v, zNew),
        uv: proj3D(uTex, vTex, zOrigTex)
      };
    }

    for (let iu = 0; iu < uGrid.length - 1; iu++) {
      let uA = uGrid[iu];
      let uB = uGrid[iu + 1];
      for (let iv = 0; iv < vFracs.length - 1; iv++) {
        let vf1 = vFracs[iv];
        let vf2 = vFracs[iv + 1];

        let A = evalKeyVert(uA, vf1);
        let B = evalKeyVert(uB, vf1);
        let C = evalKeyVert(uB, vf2);
        let D = evalKeyVert(uA, vf2);

        pushTexQuad(keyTris, A.pos, B.pos, C.pos, D.pos, A.uv, B.uv, C.uv, D.uv);
      }
    }

    flushTexTriangles(keyTris);

    // 5. Dynamic p5.brush Overlays on Depressed White Key (Seeded per key!)
    randomSeed(71000 + k * 313);
    noiseSeed(81000 + k * 313);

    // A. Raking step-shadow cast by higher key (k - 1) onto depressed key k
    let stepDiff = dropCurr - dropPrev;
    if (stepDiff > 0.3) {
      let shWidth = constrain(stepDiff * 2.25, 3, 38);
      let shAlpha = constrain(stepDiff * 15, 35, 215);
      let uShStart = hasPrevBlack ? U_BLACK_END - 6 : 6;
      let zA = zTop - leverDrop(uShStart, dropCurr) + 0.2;
      let zB = zTop - leverDrop(U_TIP_START, dropCurr) + 0.2;

      animFillPoly3D(
        [
          [uShStart, v1, zA],
          [U_TIP_START + 10, v1 + 2, zB],
          [U_TIP_START + 6, v1 + shWidth, zB],
          [uShStart, v1 + shWidth * 0.88, zA]
        ],
        "#181d28", shAlpha
      );

      let hSteps = floor(constrain(stepDiff * 2.4, 8, 30));
      animHatchQuad3D(
        [uShStart + 4, v1 + 0.8, zA],
        [U_TIP_START + 4, v1 + 2, zB],
        [U_TIP_START, v1 + shWidth * 0.9, zB],
        [uShStart + 4, v1 + shWidth * 0.8, zA],
        hSteps, "2B", "#0d1017", 0.42, 0.4
      );
    }

    // B. Mother-of-Pearl (Nacre) Chatoyant Iridescence & Nose Glint when Tilted
    if (dropCurr > 0.25) {
      let normD = constrain(dropCurr / 19.0, 0, 1);

      // Grazing shadow veil near rear of depressed key, contrasting with bright nacre flash
      let zMid = zTop - leverDrop(235, dropCurr) + 0.2;
      animFillPoly3D(
        [
          [10, v1 + 2, zTop - dStart + 0.2],
          [245, v1 + 2, zMid],
          [245, v2 - 2, zMid],
          [10, v2 - 2, zTop - dStart + 0.2]
        ],
        "#222836", normD * 72
      );

      // Luminous sliding mother-of-pearl band sweeping along the front half of the key
      let uBandCenter = 285 + normD * 125;
      let zBandA = zTop - leverDrop(uBandCenter - 32, dropCurr) + 0.25;
      let zBandB = zTop - leverDrop(uBandCenter + 32, dropCurr) + 0.25;
      let bandCol = (k % 3 === 0) ? "#fae1ea" : (k % 3 === 1 || k % 3 === -2) ? "#d6f2e8" : "#e3dbf7";
      animFillPoly3D(
        [
          [uBandCenter - 32, v1 + 4, zBandA],
          [uBandCenter + 32, v1 + 4, zBandB],
          [uBandCenter + 26, v2 - 4, zBandB],
          [uBandCenter - 26, v2 - 4, zBandA]
        ],
        bandCol, normD * 95
      );

      // Travelling chatoyant colored-pencil shimmer lines along the swirling nacre grain
      let numGlints = 16;
      for (let g = 0; g < numGlints; g++) {
        let uBase = 262 + ((g * 16 + dropCurr * 6.4) % 178);
        let vCenter = lerp(v1 + 9, v2 - 9, (g + 0.5) / numGlints);
        let zG = zTop - leverDrop(uBase, dropCurr) + 0.35;

        let waveAng = 34 * sin(uBase * 2.1 + k * 45) + 18 * cos(vCenter * 3.0);
        let du = cos(waveAng) * 24;
        let dv = sin(waveAng) * 15;

        let gCol = g % 4 === 0 ? "#ffffff"
          : g % 4 === 1 ? "#fce2ea"
          : g % 4 === 2 ? "#d4f2e8"
          : "#e4dcf7";
        let gW = (g % 4 === 0 ? 0.68 : 0.52) * normD;

        animSpline3D(
          [
            [uBase - du, constrain(vCenter - dv, v1 + 5, v2 - 5), zG, 0.5],
            [uBase, vCenter, zG, 1.3],
            [constrain(uBase + du, 260, U_TIP_START + 8), constrain(vCenter + dv, v1 + 5, v2 - 5), zG, 0.5]
          ],
          0.55, "cpencil", gCol, gW
        );
      }

      // Specular catch-light rolling across the rounded waterfall nose as the key tips down
      let uNoseH = U_TIP_START + 10 + normD * 7.5;
      let zNoseH = zTop - 1.2 - normD * 1.6 - leverDrop(uNoseH, dropCurr);
      animSpline3D(
        [
          [uNoseH - 3, v1 + 5, zNoseH + 0.4, 0.8],
          [uNoseH + 3, (v1 + v2) * 0.5, zNoseH, 1.45],
          [uNoseH - 3, v2 - 6, zNoseH - 0.2, 0.7]
        ],
        0.5, "cpencil", "#ffffff", 0.6 + 0.5 * normD
      );
    }

    // C. Long shadow cast by the treble casing overhang (u = 0 .. 26 + 0.75*drop)
    let uCasSh = 26 + dropCurr * 0.75;
    let zCasA = zTop - leverDrop(0, dropCurr) + 0.3;
    let zCasB = zTop - leverDrop(uCasSh, dropCurr) + 0.3;
    animFillPoly3D(
      [
        [0, v1, zCasA],
        [uCasSh, v1, zCasB],
        [uCasSh, v2, zCasB],
        [0, v2, zCasA]
      ],
      "#161a22", 155
    );
  }

  // --- B. BLACK KEYS & DYNAMIC CAST SHADOWS (BACK-TO-FRONT: k = -7 .. +9) ---
  for (let k = -7; k <= 9; k++) {
    if (!hasBlackKeyAfterIndex(k)) continue;

    randomSeed(91000 + k * 409);
    noiseSeed(95000 + k * 409);

    let [vB1, vB2] = getBlackKeyBounds(k);
    let dropBlack = getBlackKeyDrop(k, t);
    let dropWhiteBelow = getWhiteKeyDrop(k + 1, t);
    let zWhiteBelowRest = getWhiteKeyRestZ(k + 1);

    // 1. Dynamic Cast Shadow of Black Key k onto White Key k + 1
    let relHeightDiff = dropWhiteBelow - dropBlack;
    if (abs(relHeightDiff) > 0.25 || dropWhiteBelow > 0.25) {
      let duSh = constrain(32 + relHeightDiff * 1.5, 12, 58);
      let dvSh = constrain(42 + relHeightDiff * 1.9, 16, 72);
      let zShStart = zWhiteBelowRest - leverDrop(4, dropWhiteBelow) + 0.35;
      let zShEnd = zWhiteBelowRest - leverDrop(U_BLACK_END, dropWhiteBelow) + 0.35;

      if (relHeightDiff > 0.3) {
        // White key dropped lower than black key -> cast shadow stretches wider
        let extraAlpha = constrain(relHeightDiff * 12, 35, 165);
        animFillPoly3D(
          [
            [4, vB2, zShStart],
            [U_BLACK_SLOPE_START, vB2, zShEnd],
            [U_BLACK_END + duSh * 0.65, vB2 + dvSh * 0.72, zShEnd],
            [U_BLACK_SLOPE_START + duSh, vB2 + dvSh, zShEnd],
            [4, vB2 + dvSh, zShStart]
          ],
          "#212633", extraAlpha
        );
        animHatchQuad3D(
          [6, vB2 + 2, zShStart],
          [U_BLACK_SLOPE_START + 8, vB2 + 4, zShEnd],
          [U_BLACK_SLOPE_START + duSh - 4, vB2 + dvSh - 2, zShEnd],
          [6, vB2 + dvSh - 2, zShStart],
          20, "HB", "#171b24", 0.38, 0.5
        );
      } else if (relHeightDiff < -0.3) {
        // Black key pressed down toward white key -> shadow narrows & outer edge brightens
        let retract = constrain(-relHeightDiff * 1.55, 2, 24);
        animHatchQuad3D(
          [12, vB2 + 41 - retract, zShStart],
          [U_BLACK_SLOPE_START + 16, vB2 + 41 - retract, zShEnd],
          [U_BLACK_SLOPE_START + 28, vB2 + 42, zShEnd],
          [12, vB2 + 42, zShStart],
          12, "cpencil", "#ece6da", 0.45, 0.3
        );
      }
    }

    // 2. Textured Mesh of Black Key k (sideWall, frontNose, topFace)
    let zBase = 22.0;
    let zCrown = 50.0;
    let taper = 5.0;
    let blackTris = [];

    let uBkSegs = [0, 75, 145, U_BLACK_SLOPE_START];
    for (let s = 0; s < uBkSegs.length - 1; s++) {
      let uA = uBkSegs[s];
      let uB = uBkSegs[s + 1];
      let dBA = leverDrop(uA, dropBlack);
      let dBB = leverDrop(uB, dropBlack);
      let dWA = leverDrop(uA, dropWhiteBelow);
      let dWB = leverDrop(uB, dropWhiteBelow);

      // Base of black key side wall meets white key k+1 slot
      let zBaseNewA = zBase - min(dBA, dWA);
      let zBaseNewB = zBase - min(dBB, dWB);
      let zCrownNewA = zCrown - dBA;
      let zCrownNewB = zCrown - dBB;

      // +v Side Wall quad
      pushTexQuad(
        blackTris,
        proj3D(uA, vB2, zBaseNewA),
        proj3D(uB, vB2, zBaseNewB),
        proj3D(uB, vB2 - taper, zCrownNewB),
        proj3D(uA, vB2 - taper, zCrownNewA),
        proj3D(uA, vB2, zBase),
        proj3D(uB, vB2, zBase),
        proj3D(uB, vB2 - taper, zCrown),
        proj3D(uA, vB2 - taper, zCrown)
      );

      // Crowned Top Face quad
      pushTexQuad(
        blackTris,
        proj3D(uA, vB1 + taper, zCrownNewA),
        proj3D(uB, vB1 + taper, zCrownNewB),
        proj3D(uB, vB2 - taper, zCrownNewB),
        proj3D(uA, vB2 - taper, zCrownNewA),
        proj3D(uA, vB1 + taper, zCrown),
        proj3D(uB, vB1 + taper, zCrown),
        proj3D(uB, vB2 - taper, zCrown),
        proj3D(uA, vB2 - taper, zCrown)
      );
    }

    // Sloped & Rounded Front Nose + Side Wall Nose (u = uBlackSlopeStart .. uBlackEnd)
    let dBS = leverDrop(U_BLACK_SLOPE_START, dropBlack);
    let dBE = leverDrop(U_BLACK_END, dropBlack);
    let dWS = leverDrop(U_BLACK_SLOPE_START, dropWhiteBelow);
    let dWE = leverDrop(U_BLACK_END, dropWhiteBelow);

    let zBaseS = zBase - min(dBS, dWS);
    let zBaseE = zBase - min(dBE, dWE);

    // Side wall nose quad
    pushTexQuad(
      blackTris,
      proj3D(U_BLACK_SLOPE_START, vB2, zBaseS),
      proj3D(U_BLACK_END, vB2 - 2, zBaseE),
      proj3D(U_BLACK_END - 8, vB2 - taper, zBase + 10 - dBE),
