      blackTris,
      proj3D(U_BLACK_SLOPE_START, vB1 + taper, zCrown - dBS),
      proj3D(U_BLACK_END - 6, vB1 + taper + 3, zBase + 11 - dBE),
      proj3D(U_BLACK_END - 8, vB2 - taper, zBase + 10 - dBE),
      proj3D(U_BLACK_SLOPE_START, vB2 - taper, zCrown - dBS),
