      proj3D(U_BLACK_END - 2, vB2 - 2, zBaseE),
      proj3D(U_BLACK_END - 8, vB2 - taper, zBase + 10 - dBE),
      proj3D(U_BLACK_END - 6, vB1 + taper + 3, zBase + 11),
      proj3D(U_BLACK_END, (vB1 + vB2) * 0.5, zBase + 2),
      proj3D(U_BLACK_END - 2, vB2 - 2, zBase),
      proj3D(U_BLACK_END - 8, vB2 - taper, zBase + 10)
    );

    flushTexTriangles(blackTris);

    // 3. Dynamic Specular Glints & Reflected Pearloid Bounce on Moving Black Key
    if (dropBlack > 0.25 || dropWhiteBelow > 0.25) {
      let normB = constrain(dropBlack / 16.0, 0, 1);

      // Shifting pearloid bounce-light reflection on glossy +v side wall of black key
      let zRefShift = (dropWhiteBelow - dropBlack) * 0.35;
      for (let bLine = 0; bLine < 4; bLine++) {
        let zB = zBase + 7 + bLine * 1.8 - leverDrop(110, dropBlack) - zRefShift;
        let colB = bLine % 2 === 0 ? "#c0b4cc" : "#a4c4be";
        animLine3D(
          [18, vB2 - 2.2, zB],
          [U_BLACK_SLOPE_START - 6, vB2 - 2.8, zB],
          "cpencil", colB, 0.38
