      }

      // Razor-sharp raking white highlight flaring along the black key crown & nose
      if (normB > 0.04) {
        animSpline3D(
          [
            [6, vB1 + taper + 0.8, zCrown + 0.5 - leverDrop(6, dropBlack), 0.7],
            [U_BLACK_SLOPE_START * 0.55, vB1 + taper + 0.8, zCrown + 0.6 - leverDrop(115, dropBlack), 1.35],
            [U_BLACK_SLOPE_START, vB1 + taper + 1.2, zCrown + 0.5 - dBS, 1.45],
            [U_BLACK_END - 8, vB1 + taper + 5, zBase + 11.2 - dBE, 1.15],
            [U_BLACK_END - 2, (vB1 + vB2) * 0.5, zBase + 4.2 - dBE, 0.6]
          ],
          0.4, "cpencil", "#ffffff", 0.58 + 0.48 * normB
        );
      }
