  }

  // =========================================================================
  // 3. RE-STAMP FRONT RAIL & TREBLE CASING OVERHANG + CHROME BOLT GLINTS
  // =========================================================================
  let frameTris = [];

  // A. Front keyboard rail (u in [470, 780]) cleanly framing the key tips
  pushTexQuad(
    frameTris,
    proj3D(470, -850, 8),
    proj3D(780, -850, -25),
    proj3D(780, 920, -25),
    proj3D(470, 920, 8),
    proj3D(470, -850, 8),
    proj3D(780, -850, -25),
    proj3D(780, 920, -25),
    proj3D(470, 920, 8)
  );

  // B. Stepped black celluloid keyboard lip & treble casing (u in [-138, 6], z = 24 .. 41)
  // Cleanly overlaps the rear hinges (u = 0) of all keys and the bellows seam (u = -135)
  pushTexQuad(
    frameTris,
    proj3D(-138, -820, 38),
    proj3D(-10, -820, 41),
    proj3D(-10, 890, 41),
    proj3D(-138, 890, 38),
    proj3D(-138, -820, 38),
    proj3D(-10, -820, 41),
    proj3D(-10, 890, 41),
    proj3D(-138, 890, 38)
  );
  pushTexQuad(
    frameTris,
    proj3D(-10, -820, 41),
    proj3D(6, -820, 24),
    proj3D(6, 890, 24),
    proj3D(-10, 890, 41),
    proj3D(-10, -820, 41),
    proj3D(6, -820, 24),
    proj3D(6, 890, 24),
    proj3D(-10, 890, 41)
  );

  flushTexTriangles(frameTris);

  // C. Animated Pearloid Reflections in the 4 Mirror-Chrome Grille Bolts
  const boltPositions = [-410, -110, 190, 490];
  const zFrameTop = 41;
  const zColTop = zFrameTop + 9.5;
  const rDome = 17.5;

  for (let bIdx = 0; bIdx < boltPositions.length; bIdx++) {
    randomSeed(41000 + bIdx * 617);
    noiseSeed(45000 + bIdx * 617);

    let uB = -33;
    let vB = boltPositions[bIdx];
    let nearK = round(vB / KEY_PITCH);
    let localActivity =
      getWhiteKeyDrop(nearK, t) +
      0.7 * getWhiteKeyDrop(nearK + 1, t) +
      0.7 * getWhiteKeyDrop(nearK - 1, t);

    if (localActivity > 0.35) {
      let glintShift = constrain(localActivity * 1.4, 0, 28);
      for (let a = 20; a <= 135; a += 18) {
        let ang = a + sin(t * 360 + bIdx * 50) * 10;
        let cRef = ang < 78 ? "#fae2ea" : "#d4f0e6";
        animLine3D(
          [uB + cos(ang) * (rDome * 0.56), vB + sin(ang) * (rDome * 0.56), zColTop + 3.2],
          [uB + cos(ang + 14) * (rDome * 0.78), vB + sin(ang + 14) * (rDome * 0.78), zColTop + 2.2],
          "cpencil", cRef, 0.42 + 0.01 * glintShift
        );
      }
      // Crisp specular star glint on upper-left of chrome dome
      let angH = 222 + sin(t * 300 + bIdx * 70) * 8;
      animLine3D(
        [uB + cos(angH) * 2.5, vB + sin(angH) * 2.5, zFrameTop + 15.6],
        [uB + cos(angH) * (rDome - 1.2), vB + sin(angH) * (rDome - 1.2), zColTop + 1.8],
        "cpencil", "#ffffff", 0.68
      );
    }
  }
}

20-microwaves:
// MOTION: Microwave windows flicker with magnetron power waves as LED timers count down and turntables revolve.

window.PIECE_SECONDS = 2;
window.PIECE_FPS = 24;
const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;

// Hyperreal Worm's-Eye Megastructure of Stacked Microwaves
// Technical pen ("rotring"), cool grey marker layers, and warm amber colored pencil vignettes

let camPos, lookAt, camRight, camUp, camFwd;
let focalLength = 980;
let screenCX = 575;
let screenCY = 650;
let stillImg = null;
let cachedCapsules = null;

// Palette
const PAL = {
  paper: "#f4ecdc",
  paperWarm: "#efe2c8",
  inkDark: "#1a1715",
  inkMid: "#332e2a",
  inkFaint: "#6e675f",
  draftLine: "#9e9588",
  draftBlue: "#8a98a4",

  // Cool grey marker scale (brushed steel)
  steel1: "#e6eaee",
  steel2: "#cdd4dc",
  steel3: "#b2bcc6",
  steel4: "#94a0ac",
  steel5: "#778390",
  steel6: "#5b6672",
  steel7: "#414a54",
  steel8: "#2a313a",
  steel9: "#181d23",

  // Warm bounce & ambient tones on steel
  warmSteel1: "#f5e6cf",
  warmSteel2: "#dfc39d",
  warmSteel3: "#c79a6b",
  warmSteel4: "#9e7248",

  // Incandescent amber pencil & glow palette
  glowWhite: "#fffbe6",
  glowPale: "#ffeaa0",
  glowGold: "#ffca52",
  glowAmber: "#f59b23",
  glowOrange: "#df6e12",
  glowRust: "#b5460c",
  glowUmber: "#782808",
  glowDeep: "#3d1204",

  // Dead unit cold tones
  deadGlass1: "#14181e",
  deadGlass2: "#222932",
  deadGlass3: "#353f4c",
  deadHighlight: "#7c8b99",

  // LEDs
  ledAmber: "#ff9e22",
  ledBright: "#ffe699",
  ledGreen: "#5cd67a"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);
  setupCamera();
}

function setupCamera() {
  // Worm's-eye camera looking steeply upward at the megastructure wall
  camPos = { x: -1.42, y: -2.25, z: 8.85 };
  lookAt = { x: 0.18, y: 4.55, z: 0.80 };

  let fx = lookAt.x - camPos.x;
  let fy = lookAt.y - camPos.y;
  let fz = lookAt.z - camPos.z;
  let fl = Math.hypot(fx, fy, fz);
  camFwd = { x: fx / fl, y: fy / fl, z: fz / fl };

  // World up = (0, 1, 0)
  // Right = normalize(cross(Fwd, Up))
  let rx = -camFwd.z;
  let ry = 0;
  let rz = camFwd.x;
  let rl = Math.hypot(rx, ry, rz);
  camRight = { x: rx / rl, y: ry / rl, z: rz / rl };

  // Up = cross(Right, Fwd)
  camUp = {
    x: camRight.y * camFwd.z - camRight.z * camFwd.y,
    y: camRight.z * camFwd.x - camRight.x * camFwd.z,
    z: camRight.x * camFwd.y - camRight.y * camFwd.x
  };
}

// Project 3D world coordinate to 2D canvas coordinate
function proj(x, y, z) {
  let vx = x - camPos.x;
  let vy = y - camPos.y;
  let vz = z - camPos.z;

  let cx = vx * camRight.x + vy * camRight.y + vz * camRight.z;
  let cy = vx * camUp.x + vy * camUp.y + vz * camUp.z;
  let cz = vx * camFwd.x + vy * camFwd.y + vz * camFwd.z;

  if (cz < 0.2) cz = 0.2;
  return {
    x: screenCX + (cx / cz) * focalLength,
    y: screenCY - (cy / cz) * focalLength,
    z: cz
  };
}

function projPt(p) {
  return proj(p.x, p.y, p.z);
}

// Interpolate in 2D
function lerpPt(a, b, t) {
  return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
}

// Interpolate in 3D
function lerp3(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    z: a.z + (b.z - a.z) * t
  };
}

// Bilinear interpolation on a 2D quad [TL, TR, BR, BL]
// u in [0,1] left-to-right, v in [0,1] bottom-to-top
function quadUV(q, u, v) {
  // q[0]=TL, q[1]=TR, q[2]=BR, q[3]=BL
  let bot = lerpPt(q[3], q[2], u);
  let top = lerpPt(q[0], q[1], u);
  return lerpPt(bot, top, v);
}

// ---------------------------------------------------------------------------
// Geometry Clipping Helpers (clips 2D lines & polygons to a convex 2D quad)
// ---------------------------------------------------------------------------
function quadCentroid(quad) {
  let sx = 0, sy = 0;
  for (let i = 0; i < quad.length; i++) {
    sx += quad[i].x;
    sy += quad[i].y;
  }
  return { x: sx / quad.length, y: sy / quad.length };
}

function clipPolyToQuad(poly, quad) {
  if (!poly || poly.length < 3) return [];
  let c = quadCentroid(quad);
  let out = poly.slice();

  for (let i = 0; i < quad.length; i++) {
    let A = quad[i];
    let B = quad[(i + 1) % quad.length];
    let ex = B.x - A.x;
    let ey = B.y - A.y;
    let refSign = ex * (c.y - A.y) - ey * (c.x - A.x) >= 0 ? 1 : -1;

    let inp = out;
    out = [];
    if (inp.length === 0) break;

    for (let j = 0; j < inp.length; j++) {
      let P = inp[j];
      let Q = inp[(j + 1) % inp.length];
      let pVal = (ex * (P.y - A.y) - ey * (P.x - A.x)) * refSign;
      let qVal = (ex * (Q.y - A.y) - ey * (Q.x - A.x)) * refSign;

      if (pVal >= -1e-5) {
        out.push(P);
        if (qVal < -1e-5) {
          let t = pVal / (pVal - qVal);
          out.push(lerpPt(P, Q, t));
        }
      } else if (qVal >= -1e-5) {
        let t = pVal / (pVal - qVal);
        out.push(lerpPt(P, Q, t));
      }
    }
  }
  return out;
}

function clipSegToQuad(p1, p2, quad) {
  let c = quadCentroid(quad);
  let a = { x: p1.x, y: p1.y };
  let b = { x: p2.x, y: p2.y };

  for (let i = 0; i < quad.length; i++) {
    let A = quad[i];
    let B = quad[(i + 1) % quad.length];
    let ex = B.x - A.x;
    let ey = B.y - A.y;
    let refSign = ex * (c.y - A.y) - ey * (c.x - A.x) >= 0 ? 1 : -1;

    let va = (ex * (a.y - A.y) - ey * (a.x - A.x)) * refSign;
    let vb = (ex * (b.y - A.y) - ey * (b.x - A.x)) * refSign;

    if (va < 0 && vb < 0) return null;
    if (va < 0 || vb < 0) {
      let t = va / (va - vb);
      let m = lerpPt(a, b, t);
      if (va < 0) a = m;
      else b = m;
    }
  }
  return [a, b];
}

// ---------------------------------------------------------------------------
// Safe p5.brush Drawing Wrappers (Guarantees brush.set before strokes)
// ---------------------------------------------------------------------------
function drawLine2D(p1, p2, bName, col, weight, overrun = 0) {
  if (!p1 || !p2) return;
  let dx = p2.x - p1.x;
  let dy = p2.y - p1.y;
  let d = Math.hypot(dx, dy);
  if (d < 0.5) return;
  let x1 = p1.x, y1 = p1.y, x2 = p2.x, y2 = p2.y;
  if (overrun !== 0) {
    let ux = (dx / d) * overrun;
    let uy = (dy / d) * overrun;
    x1 -= ux; y1 -= uy;
    x2 += ux; y2 += uy;
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function drawLineClipped(p1, p2, quad, bName, col, weight) {
  let seg = clipSegToQuad(p1, p2, quad);
  if (seg) drawLine2D(seg[0], seg[1], bName, col, weight, 0);
}

function washPoly(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noWash();
}

function washPolyClipped(pts, quad, col, opacity) {
  let cPts = clipPolyToQuad(pts, quad);
  if (cPts.length >= 3) washPoly(cPts, col, opacity);
}

function watercolorPoly(pts, col, opacity, bleed = 0.12, tex = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.25);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noFill();
}

function hatchPoly(pts, bName, col, weight, dist, angleDeg, opts = { rand: 0.03 }) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(dist, angleDeg, opts);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noHatch();
}

function strokePoly(pts, closeShape, bName, col, weight, overrun = 0) {
  if (!pts || pts.length < 2) return;
  let n = closeShape ? pts.length : pts.length - 1;
  for (let i = 0; i < n; i++) {
    drawLine2D(pts[i], pts[(i + 1) % pts.length], bName, col, weight, overrun);
  }
}

function drawSpline2D(pts, bName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  if (pts.length === 2) {
    drawLine2D(pts[0], pts[1], bName, col, weight, 0);
    return;
  }
  let arr = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (p.p !== undefined) arr.push([p.x, p.y, p.p]);
    else arr.push([p.x, p.y]);
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.spline(arr, curvature);
}

function drawSplineClipped(pts, quad, bName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  // Filter/clip spline segments into contiguous runs inside quad
  let run = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let seg = clipSegToQuad(pts[i], pts[i + 1], quad);
    if (seg) {
      if (run.length === 0) run.push(seg[0]);
      run.push(seg[1]);
    } else {
      if (run.length >= 2) drawSpline2D(run, bName, col, weight, curvature);
      run = [];
    }
  }
  if (run.length >= 2) drawSpline2D(run, bName, col, weight, curvature);
}

// Generate projected 2D polygon of a horizontal 3D ellipse (lying in XZ plane at height y)
function ellipse3D_XZ(cx, y, cz, rx, rz, steps = 28, rotDeg = 0) {
  let pts = [];
  let rad = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rad);
  let sr = Math.sin(rad);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let lx = Math.cos(a) * rx;
    let lz = Math.sin(a) * rz;
    let wx = cx + lx * cr - lz * sr;
    let wz = cz + lx * sr + lz * cr;
    pts.push(proj(wx, y, wz));
  }
  return pts;
}

// Fill a 2D quad with realistic layered industrial marker strokes
function markerBandQuad(q, dir, col, weight, count, u0 = 0, u1 = 1, v0 = 0, v1 = 1) {
  for (let i = 0; i < count; i++) {
    let t = count === 1 ? 0.5 : i / (count - 1);
    let p1, p2;
    if (dir === "h") {
      let v = v0 + (v1 - v0) * t;
      p1 = quadUV(q, u0, v);
      p2 = quadUV(q, u1, v);
    } else if (dir === "v") {
      let u = u0 + (u1 - u0) * t;
      p1 = quadUV(q, u, v0);
      p2 = quadUV(q, u, v1);
    } else {
      // diagonal specular streak
      let s = (i / count) * 0.7;
      p1 = quadUV(q, Math.max(0, s), Math.min(1, v0 + s * 0.4));
      p2 = quadUV(q, Math.min(1, s + 0.45), Math.min(1, v1));
    }
    drawLine2D(p1, p2, "marker", col, weight, 0);
  }
}

// ---------------------------------------------------------------------------
// Exact Still Painting (Unchanged for Frame 0)
// ---------------------------------------------------------------------------
function paintStill() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Warm paper ground & atmospheric hum
  drawBackgroundAndAtmosphere();

  // 2. Megastructure core columns, service channels & drafting construction lines
  drawMegastructureCore();

  // 3. Build and sort all microwave capsule modules in 3D
  let capsules = buildCapsuleList();

  // Sort back-to-front from camera position (Painter's Algorithm)
  capsules.sort((a, b) => b.camDistSq - a.camDistSq);
  cachedCapsules = capsules;

  // 4. Render each microwave capsule (housing, soffit, controls, window vignette)
  for (let i = 0; i < capsules.length; i++) {
    drawMicrowaveCapsule(capsules[i]);
  }

  // 5. Final atmospheric hum, drafting annotations, and foreground framing
  drawForegroundPolish();
}

// ---------------------------------------------------------------------------
// Main Film Loop (24 fps, 48 frames)
// ---------------------------------------------------------------------------
function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  // Normalized time t in seconds (starts near 0 on frame 2, reaches ~1.96s on frame 48)
  const t = (frameCount - 1) / window.PIECE_FPS;
  // Smooth ease-in envelope over the first 3 frames so frame 1 continues frame 0 seamlessly
  const env = Math.min(1, (frameCount - 1) / 3);

  translate(-width / 2, -height / 2);
  brush.noField();

  // Stamp the exact cached still image as backdrop
  image(stillImg, 0, 0, width, height);

  if (!cachedCapsules) {
    cachedCapsules = buildCapsuleList();
    cachedCapsules.sort((a, b) => b.camDistSq - a.camDistSq);
  }

  // Render animated windows, rotating turntables, magnetron flicker & countdown LEDs
  for (let i = 0; i < cachedCapsules.length; i++) {
    drawAnimatedCapsuleOverlay(cachedCapsules[i], t, env);
  }

  // Re-establish foreground hum spray lines & rising hero steam plumes
  drawAnimatedForegroundHum(t, env);

  // Smooth cross-dissolve on frames 2 & 3 to guarantee zero texture pop from frame 1
  if (frameCount === 2) {
    push();
    tint(255, 130);
    image(stillImg, 0, 0, width, height);
    noTint();
    pop();
  } else if (frameCount === 3) {
    push();
    tint(255, 45);
    image(stillImg, 0, 0, width, height);
    noTint();
    pop();
  }
}

// ---------------------------------------------------------------------------
// Animated Overlay Per Microwave Capsule (Seeded to prevent boiling)
// ---------------------------------------------------------------------------
function getCapsuleSeed(cap) {
  return 10000 + (cap.r + 5) * 313 + (cap.c + 5) * 79;
}

// Compute magnetron power wave & flicker value in [-1, 1] for a capsule at time t
function getWindowFlicker(cap, t) {
  // Upward-travelling megastructure voltage wave + unit-specific harmonic flicker
  let phase = cap.c * 58 + cap.r * 74;
  let wave1 = Math.sin((t * 480 - cap.r * 62 + cap.c * 44) * (Math.PI / 180));
  let wave2 = Math.sin((t * 1120 + phase * 2.3) * (Math.PI / 180));
  let wave3 = Math.cos((t * 1960 - phase * 1.7) * (Math.PI / 180));

  let val = wave1 * 0.52 + wave2 * 0.30 + wave3 * 0.18;

  // Periodic sharp brownout dips & bright power surges on specific phases
  let surgeCycle = ((t * 1.85 + (Math.abs(cap.c * 3 + cap.r * 7) % 5) * 0.23) % 1.0);
  if (surgeCycle > 0.78 && surgeCycle < 0.88) {
    val -= 0.65; // sharp magnetron load dip
  } else if (surgeCycle >= 0.88 && surgeCycle < 0.96) {
    val += 0.62; // bright incandescent recovery flare
  }

  return Math.max(-1, Math.min(1, val));
}

// Compute updated countdown timer string & colon state at time t
function getCountdownState(cap, t) {
  let baseMins = Math.abs(cap.c + cap.r * 2) % 4;
  let baseSecs = (Math.abs(cap.c * 17 + cap.r * 29) % 52) + 7;
  let totalStartSecs = baseMins * 60 + baseSecs;

  // Staggered phase so timers across the wall tick down continuously (4 ticks/sec)
  let unitPhase = ((Math.abs(cap.c * 11 + cap.r * 19) % 8) / 8) * 0.22;
  let ticks = Math.max(0, Math.floor((t + unitPhase) * 4.5));
  let rem = Math.max(0, totalStartSecs - ticks);

  let m = Math.floor(rem / 60);
  let s = rem % 60;
  let str = "0" + m + ":" + (s < 10 ? "0" + s : s);

  // Blinking colon at 3 Hz with unit offset
  let colonOn = Math.sin((t * 1080 + cap.c * 45 + cap.r * 60) * (Math.PI / 180)) > -0.15;
  let justTicked = (((t + unitPhase) * 4.5) % 1.0) < 0.28;
  let isZero = (rem === 0);

  return { str, colonOn, justTicked, isZero };
}

function drawAnimatedCapsuleOverlay(cap, t, env) {
  let { x0, x1, y0, y1, zBack, zFront, isOpenDoor, isDead, r, c } = cap;

  // Quick off-screen cull
  let pTestTop = proj((x0 + x1) * 0.5, y1, zFront);
  let pTestBot = proj((x0 + x1) * 0.5, y0, zBack);
  if (pTestTop.y > 1300 || pTestBot.y < -120) return;
  if (pTestTop.x < -220 || pTestTop.x > 1420) return;

  let seed = getCapsuleSeed(cap);
  randomSeed(seed);
  noiseSeed(seed);

  let xSplit = x0 + (x1 - x0) * 0.735;
  let flicker = getWindowFlicker(cap, t) * env;
  let cd = getCountdownState(cap, t);

  // Turntable rotation delta in degrees (smoothly revolves ~105 deg/sec)
  let dir = ((c + r) % 2 === 0) ? 1 : -1;
  let deltaDeg = t * 108 * dir;
  if (isOpenDoor) deltaDeg = t * 125; // Hero noodle bowl turns prominently

  // 1. Underside Soffit Warm Flicker Bounce (pulses with window flicker)
  if (y0 > camPos.y && !isDead && !(c === -1 && r === 4)) {
    let qBot = [
      proj(x0, y0, zFront),
      proj(x1, y0, zFront),
      proj(x1, y0, zBack),
      proj(x0, y0, zBack)
    ];
    let qWarmLip = [
      quadUV(qBot, 0.04, 0.96),
      quadUV(qBot, 0.71, 0.96),
      quadUV(qBot, 0.71, 0.70),
      quadUV(qBot, 0.04, 0.70)
    ];
    if (flicker > 0.15) {
      washPoly(qWarmLip, PAL.glowGold, Math.min(150, flicker * 115));
    } else if (flicker < -0.15) {
      washPoly(qWarmLip, PAL.steel8, Math.min(140, -flicker * 110));
    }
  }

  // 2. Control Panel LED Countdown Readout & Rotating Timer Dial
  let qCtrl = [
    proj(xSplit, y1, zFront),
    proj(x1, y1, zFront),
    proj(x1, y0, zFront),
    proj(xSplit, y0, zFront)
  ];

  let qLed = [
    quadUV(qCtrl, 0.12, 0.90),
    quadUV(qCtrl, 0.88, 0.90),
    quadUV(qCtrl, 0.88, 0.75),
    quadUV(qCtrl, 0.12, 0.75)
  ];

  if (!isDead) {
    randomSeed(seed + 17);
    noiseSeed(seed + 17);
    washPoly(qLed, "#1c1612", 248);
    strokePoly(qLed, true, "rotring", PAL.inkDark, 0.34, 0);
    drawLine2D(qLed[3], qLed[2], "cpencil", PAL.steel1, 0.38, 0);
    drawAnimatedLedReadout(qLed, cd, flicker);

    // Slowly turning rotary timer dial notch
    if (r <= 6 && (cap.panelStyle === 0 || cap.panelStyle === 2)) {
      randomSeed(seed + 31);
      noiseSeed(seed + 31);
      let dialX = xSplit + (x1 - xSplit) * 0.5;
      let dialY = y0 + (y1 - y0) * 0.30;
      let dialR = (x1 - xSplit) * 0.23;
      drawAnimatedDialFace(dialX, dialY, zFront, dialR, t);
    }
  } else {
    // Dead unit (c = -1, r = 3): intermittent electrical short-circuit stutter!
    let deadSpark = getDeadUnitSpark(t);
    if (deadSpark > 0.05) {
      randomSeed(seed + 99);
      noiseSeed(seed + 99);
      washPoly(qLed, "#1c1612", 240);
      strokePoly(qLed, true, "rotring", PAL.inkDark, 0.34, 0);
      drawAnimatedLedReadout(
        qLed,
        { str: "88:88", colonOn: true, justTicked: true, isZero: false },
        deadSpark
      );
    }
  }

  // 3. Animated Window Interior, Rotating Vignette, Flicker & Open Door
  randomSeed(seed + 53);
  noiseSeed(seed + 53);

  if (isOpenDoor) {
    drawAnimatedOpenDoorHeroUnit(cap, xSplit, t, deltaDeg, flicker);
  } else {
    drawAnimatedClosedWindow(cap, xSplit, t, deltaDeg, flicker, cd.isZero);
  }
}

function getDeadUnitSpark(t) {
  // Two brief electrical arc stutters at t ~ 0.42..0.72s and t ~ 1.38..1.62s
  if (t > 0.38 && t < 0.72) {
    let s = Math.sin((t - 0.38) * 32);
    return s > 0.1 ? s * 0.85 : 0;
  }
  if (t > 1.36 && t < 1.66) {
    let s = Math.sin((t - 1.36) * 38);
    return s > 0.0 ? s * 0.95 : 0;
  }
  return 0;
}

function drawAnimatedDialFace(cx, cy, zBase, rad, t) {
  let zTip = zBase + 0.08;
  let steps = 14;
  let ptsTip = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let dx = Math.cos(a) * rad * 0.88;
    let dy = Math.sin(a) * rad * 0.88;
    ptsTip.push(proj(cx + dx, cy + dy, zTip));
  }
  washPoly(ptsTip, PAL.steel2, 240);
  strokePoly(ptsTip, true, "rotring", PAL.inkDark, 0.32, 0);

  // At t=0, angle is 45 deg with radius rad * 0.55 * sqrt(2) = rad * 0.7778
  let ang = ((45 - t * 48) * Math.PI) / 180;
  let rNotch = rad * 0.7778;
  let pC = proj(cx, cy, zTip);
  let pEdge = proj(cx + Math.cos(ang) * rNotch, cy + Math.sin(ang) * rNotch, zTip);
  drawLine2D(pC, pEdge, "rotring", PAL.glowOrange, 0.40, 0);
}

function drawAnimatedLedReadout(qLed, cd, flicker) {
  let { str, colonOn, justTicked, isZero } = cd;

  // Inner LED glow box pulses on tick or completion
  let qInner = [
    quadUV(qLed, 0.18, 0.82),
    quadUV(qLed, 0.86, 0.82),
    quadUV(qLed, 0.86, 0.18),
    quadUV(qLed, 0.18, 0.18)
  ];
  let glowAlpha = isZero ? 145 : justTicked ? 95 : 65 + flicker * 25;
  washPoly(qInner, isZero ? PAL.glowGold : PAL.glowOrange, Math.max(30, glowAlpha));

  // Status LED dot on left pulses between emerald green and bright lime-gold
  let pDot = quadUV(qLed, 0.12, 0.52);
  drawLine2D(
    { x: pDot.x - 1.6, y: pDot.y },
    { x: pDot.x + 1.6, y: pDot.y },
    "pen",
    justTicked ? "#a8ffbe" : PAL.ledGreen,
    justTicked ? 0.78 : 0.65,
    0
  );

  let segColMain = isZero ? PAL.glowWhite : justTicked ? PAL.ledBright : PAL.ledAmber;
  let segColHi = isZero ? PAL.glowWhite : PAL.ledBright;
  let segW = (justTicked || isZero) ? 0.42 : 0.36;

  // Draw 4 7-segment characters
  for (let d = 0; d < 4; d++) {
    let u0 = 0.24 + d * 0.15 + (d >= 2 ? 0.05 : 0);
    let u1 = u0 + 0.10;
    let v0 = 0.25;
    let v1 = 0.76;
    let vm = 0.50;

    let tl = quadUV(qLed, u0, v1);
    let tr = quadUV(qLed, u1, v1);
    let ml = quadUV(qLed, u0, vm);
    let mr = quadUV(qLed, u1, vm);
    let bl = quadUV(qLed, u0, v0);
    let br = quadUV(qLed, u1, v0);

    let ch = str.charAt(d >= 2 ? d + 1 : d);
    // Top bar
    if (ch !== "1" && ch !== "4") drawLine2D(tl, tr, "pen", segColMain, segW, 0);
    // Mid bar
    if (ch !== "0" && ch !== "1" && ch !== "7") drawLine2D(ml, mr, "pen", segColMain, segW, 0);
    // Bot bar
    if (ch !== "1" && ch !== "4" && ch !== "7") drawLine2D(bl, br, "pen", segColMain, segW, 0);
    // Right verticals
    if (ch !== "2") drawLine2D(mr, br, "pen", segColHi, segW, 0);
    if (ch !== "5" && ch !== "6") drawLine2D(tr, mr, "pen", segColHi, segW, 0);
    // Left verticals
    if (ch === "0" || ch === "4" || ch === "5" || ch === "6" || ch === "8" || ch === "9") {
      drawLine2D(tl, ml, "pen", segColMain, segW, 0);
    }
    if (ch === "0" || ch === "2" || ch === "6" || ch === "8") {
      drawLine2D(ml, bl, "pen", segColMain, segW, 0);
    }
  }

  // Blinking colon dots
  if (colonOn || isZero) {
    let cTop = quadUV(qLed, 0.54, 0.62);
    let cBot = quadUV(qLed, 0.54, 0.36);
    drawLine2D(cTop, { x: cTop.x + 1.2, y: cTop.y }, "pen", PAL.ledBright, 0.52, 0);
    drawLine2D(cBot, { x: cBot.x + 1.2, y: cBot.y }, "pen", PAL.ledBright, 0.52, 0);
  }
}

function drawAnimatedClosedWindow(cap, xSplit, t, deltaDeg, flicker, isZero) {
  let { x0, y0, y1, zFront, isDead } = cap;
  let zDoor = zFront + 0.075;
  let dx0 = x0 + 0.02;
  let dx1 = xSplit - 0.02;
  let dy0 = y0 + 0.02;
  let dy1 = y1 - 0.02;

  let xW0 = dx0 + (dx1 - dx0) * 0.13;
  let xW1 = dx0 + (dx1 - dx0) * 0.81;
  let yW0 = dy0 + (dy1 - dy0) * 0.17;
  let yW1 = dy0 + (dy1 - dy0) * 0.83;

  let qWinOuter = [
    proj(xW0 - 0.03, yW1 + 0.03, zDoor),
    proj(xW1 + 0.03, yW1 + 0.03, zDoor),
    proj(xW1 + 0.03, yW0 - 0.03, zDoor),
    proj(xW0 - 0.03, yW0 - 0.03, zDoor)
  ];

  let qWin = [
    proj(xW0, yW1, zDoor),
    proj(xW1, yW1, zDoor),
    proj(xW1, yW0, zDoor),
    proj(xW0, yW0, zDoor)
  ];

  if (isDead) {
    // Dead unit short-circuit flash
    let spark = getDeadUnitSpark(t);
    if (spark > 0.05) {
      drawDeadWindowShortCircuit(cap, qWin, xW0, xW1, yW0, yW1, zDoor, spark);
      strokePoly(qWinOuter, true, "rotring", PAL.inkDark, 0.35, 0);
      strokePoly(qWin, true, "rotring", PAL.inkDark, 0.46, 0);
      drawLine2D(qWinOuter[3], qWinOuter[2], "cpencil", PAL.glowPale, 0.58, 0);
    }
    return;
  }

  let effFlicker = isZero ? 0.85 : flicker;

  // Render animated interior with rotating turntable & magnetron flicker
  drawLitWindowInteriorAnimated(
    cap,
    qWin,
    xW0,
    xW1,
    yW0,
    yW1,
    zDoor,
    false,
    t,
    deltaDeg,
    effFlicker
  );

  // Re-stroke crisp window bezel and bottom catchlight
  strokePoly(qWinOuter, true, "rotring", PAL.inkDark, 0.35, 0);
  strokePoly(qWin, true, "rotring", PAL.inkDark, 0.46, 0);
  drawLine2D(
    qWinOuter[3],
    qWinOuter[2],
    "cpencil",
    effFlicker > 0.25 ? PAL.glowWhite : PAL.glowGold,
    0.58,
    0
  );

  // Warm reflection glint on tubular door handle when window surges
  if (effFlicker > 0.2) {
    let xHandle = dx0 + (dx1 - dx0) * 0.90;
    let yH0 = dy0 + (dy1 - dy0) * 0.14;
    let yH1 = dy0 + (dy1 - dy0) * 0.86;
    let hw = 0.038;
    let zBar = zDoor + 0.12;
    let pHTop = proj(xHandle - hw, yH1, zBar);
    let pHBot = proj(xHandle - hw, yH0, zBar);
    drawLine2D(pHTop, pHBot, "cpencil", PAL.glowWhite, 0.62, 0);
  }
}

function drawDeadWindowShortCircuit(cap, qWin, xW0, xW1, yW0, yW1, zWin, spark) {
  washPoly(qWin, "#1e2229", 245);
  let qFlash = [
    quadUV(qWin, 0.15, 0.92),
    quadUV(qWin, 0.92, 0.92),
    quadUV(qWin, 0.90, 0.15),
    quadUV(qWin, 0.15, 0.15)
  ];
  washPoly(qFlash, PAL.glowAmber, Math.floor(spark * 155));

  // Briefly illuminated mug silhouette inside the dead chamber
  let cx = (xW0 + xW1) * 0.50;
  let cz = zWin - 0.44;
  let yTurn = yW0 + (yW1 - yW0) * 0.12;
  let rTurn = (xW1 - xW0) * 0.42;

  let turnEll = ellipse3D_XZ(cx, yTurn, cz, rTurn, rTurn * 0.78, 20);
  drawSplineClipped(turnEll.concat([turnEll[0]]), qWin, "cpencil", PAL.glowPale, 0.42, 0.4);

  let rMug = rTurn * 0.33;
  let hMug = 0.50;
  let mugBot = ellipse3D_XZ(cx, yTurn + 0.04, cz, rMug, rMug * 0.78, 16);
  let mugTop = ellipse3D_XZ(cx, yTurn + hMug, cz, rMug, rMug * 0.78, 16);
  let mugHull = mugTop.slice(0, 9).concat(mugBot.slice(0, 9).reverse());
  washPolyClipped(mugHull, qWin, "#12161c", 235);
  drawSplineClipped(mugTop.concat([mugTop[0]]), qWin, "cpencil", PAL.glowWhite, 0.48, 0.4);

  // Electrical arc rays from upper-right dead bulb socket
  let pBulb = proj(xW1 - 0.18, yW1 - 0.04, zWin - 0.28);
  for (let i = 0; i < 6; i++) {
    let a = (i / 6) * Math.PI * 2 + spark * 2;
    let pRay = { x: pBulb.x + Math.cos(a) * 22, y: pBulb.y + Math.sin(a) * 16 };
    drawLineClipped(pBulb, pRay, qWin, "cpencil", PAL.glowWhite, 0.65);
  }

  hatchPoly(qWin, "rotring", "#0c0f14", 0.22, 6, 45, { rand: 0.01 });
  hatchPoly(qWin, "rotring", "#0c0f14", 0.20, 6, -45, { rand: 0.01 });
}

function drawAnimatedOpenDoorHeroUnit(cap, xSplit, t, deltaDeg, flicker) {
  let { x0, y0, y1, zFront } = cap;

  let dx0 = x0 + 0.02;
  let dx1 = xSplit - 0.02;
  let dy0 = y0 + 0.02;
  let dy1 = y1 - 0.02;

  let xW0 = dx0 + (dx1 - dx0) * 0.10;
  let xW1 = dx0 + (dx1 - dx0) * 0.84;
  let yW0 = dy0 + (dy1 - dy0) * 0.14;
  let yW1 = dy0 + (dy1 - dy0) * 0.86;

  let qCavity = [
    proj(xW0, yW1, zFront),
    proj(xW1, yW1, zFront),
    proj(xW1, yW0, zFront),
    proj(xW0, yW0, zFront)
  ];

  // Render the open cavity with rotating hero noodles & pulsing bulb glow
  drawLitWindowInteriorAnimated(
    cap,
    qCavity,
    xW0,
    xW1,
    yW0,
    yW1,
    zFront,
    true,
    t,
    deltaDeg,
    flicker
  );

  // Rounded inner cavity rim bevel in glowing gold & technical pen
  strokePoly(qCavity, true, "cpencil", PAL.glowPale, 0.75, 0);
  strokePoly(qCavity, true, "rotring", PAL.inkDark, 0.52, 0);

  // Re-establish the 3D Swung-Open Door so it cleanly overlaps the left side of the cavity
  let doorW = dx1 - dx0;
  let doorThick = 0.085;
  let openDeg = 66;
  let rad = (openDeg * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);

  function doorPt(u, y, th) {
    return proj(
      dx0 + u * ca - th * sa,
      y,
      zFront + u * sa + th * ca
    );
  }

  let qSwungBot = [
    doorPt(0, dy0, 0),
    doorPt(doorW, dy0, 0),
    doorPt(doorW, dy0, doorThick),
    doorPt(0, dy0, doorThick)
  ];
  washPoly(qSwungBot, PAL.steel6, 240);
  strokePoly(qSwungBot, true, "rotring", PAL.inkDark, 0.38, 0);

  let qSwungEdge = [
    doorPt(doorW, dy1, 0),
    doorPt(doorW, dy1, doorThick),
    doorPt(doorW, dy0, doorThick),
    doorPt(doorW, dy0, 0)
  ];
  washPoly(qSwungEdge, PAL.steel4, 240);
  strokePoly(qSwungEdge, true, "rotring", PAL.inkDark, 0.40, 0);

  let qSwungInner = [
    doorPt(0, dy1, 0),
    doorPt(doorW, dy1, 0),
    doorPt(doorW, dy0, 0),
    doorPt(0, dy0, 0)
  ];
  washPoly(qSwungInner, PAL.steel4, 245);
  markerBandQuad(qSwungInner, "v", PAL.warmSteel2, 0.65, 5, 0.05, 0.95, 0.04, 0.96);

  let qChoke = [
    doorPt(doorW * 0.08, dy0 + (dy1 - dy0) * 0.92, 0),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.92, 0),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.08, 0),
    doorPt(doorW * 0.08, dy0 + (dy1 - dy0) * 0.08, 0)
  ];
  washPoly(qChoke, PAL.steel8, 240);
  strokePoly(qChoke, true, "rotring", PAL.inkDark, 0.35, 0);

  // Inner Glass Shield of Open Door with shimmering reflection driven by cavity flicker
  let qInnerGlass = [
    doorPt(doorW * 0.15, dy0 + (dy1 - dy0) * 0.83, 0),
    doorPt(doorW * 0.81, dy0 + (dy1 - dy0) * 0.83, 0),
    doorPt(doorW * 0.81, dy0 + (dy1 - dy0) * 0.17, 0),
    doorPt(doorW * 0.15, dy0 + (dy1 - dy0) * 0.17, 0)
  ];
  washPoly(qInnerGlass, "#2a1e14", 235);

  let shift = Math.sin(t * 7.5) * 0.06;
  let qRefl = [
    quadUV(qInnerGlass, 0.15 + shift, 0.88),
    quadUV(qInnerGlass, 0.75 + shift, 0.88),
    quadUV(qInnerGlass, 0.55 - shift, 0.15),
    quadUV(qInnerGlass, 0.08 - shift, 0.15)
  ];
  washPoly(qRefl, flicker > 0.15 ? PAL.glowGold : PAL.glowAmber, Math.floor(120 + flicker * 45));
  hatchPoly(qInnerGlass, "rotring", PAL.inkDark, 0.20, 7, 72, { rand: 0.01 });
  drawLine2D(
    quadUV(qInnerGlass, 0.20 + shift * 0.5, 0.12),
    quadUV(qInnerGlass, 0.82 + shift * 0.5, 0.88),
    "cpencil",
    PAL.glowWhite,
    0.58,
    0
  );
  strokePoly(qInnerGlass, true, "rotring", PAL.inkDark, 0.38, 0);

  // Two Hooked Metal Latch Prongs
  for (let vf of [0.30, 0.70]) {
    let yL = dy0 + (dy1 - dy0) * vf;
    let pBase1 = doorPt(doorW * 0.91, yL + 0.035, 0);
    let pBase2 = doorPt(doorW * 0.91, yL - 0.035, 0);
    let pTip1 = doorPt(doorW * 0.91, yL + 0.03, -0.16);
    let pTip2 = doorPt(doorW * 0.91, yL - 0.045, -0.14);
    let qProng = [pBase1, pTip1, pTip2, pBase2];
    washPoly(qProng, PAL.warmSteel1, 245);
    strokePoly(qProng, true, "rotring", PAL.inkDark, 0.36, 0);
  }

  let qExtHandle = [
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.84, doorThick + 0.10),
    doorPt(doorW * 0.93, dy0 + (dy1 - dy0) * 0.84, doorThick + 0.10),
    doorPt(doorW * 0.93, dy0 + (dy1 - dy0) * 0.16, doorThick + 0.10),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.16, doorThick + 0.10)
  ];
  washPoly(qExtHandle, PAL.steel2, 235);
  strokePoly(qExtHandle, true, "rotring", PAL.inkDark, 0.35, 0);

  strokePoly(qSwungInner, true, "rotring", PAL.inkDark, 0.58, 1.5);
}

// ---------------------------------------------------------------------------
// Animated Lit Window Interior & Rotating Vignettes
// ---------------------------------------------------------------------------
function drawLitWindowInteriorAnimated(
  cap,
  qWin,
  xW0,
  xW1,
  yW0,
  yW1,
  zWin,
  isOpenCavity,
  t,
  deltaDeg,
  flicker
) {
  let { r, vignette, turnAngle } = cap;
  let zCavityBack = zWin - 0.88;

  // 1. Base incandescent amber/gold washes modulated by magnetron flicker
  let baseCol = flicker < -0.35 ? PAL.glowUmber : PAL.glowRust;
  washPoly(qWin, baseCol, 244);

  let qMidGlow = [
    quadUV(qWin, 0.06, 0.96),
    quadUV(qWin, 0.96, 0.96),
    quadUV(qWin, 0.94, 0.10),
    quadUV(qWin, 0.08, 0.10)
  ];
  let midCol = flicker > 0.3 ? PAL.glowGold : flicker < -0.3 ? PAL.glowOrange : PAL.glowAmber;
  let midAlpha = Math.max(115, Math.min(245, Math.floor(210 + flicker * 55)));
  washPoly(qMidGlow, midCol, midAlpha);

  let qHotspot = [
    quadUV(qWin, 0.25, 0.98),
    quadUV(qWin, 0.98, 0.98),
    quadUV(qWin, 0.96, 0.28),
    quadUV(qWin, 0.18, 0.22)
  ];
  let hotCol = flicker > 0.25 ? PAL.glowPale : PAL.glowGold;
  let hotAlpha = Math.max(85, Math.min(245, Math.floor(195 + flicker * 70)));
  washPoly(qHotspot, hotCol, hotAlpha);

  let qBulbCore = [
    quadUV(qWin, 0.58, 0.98),
    quadUV(qWin, 0.96, 0.98),
    quadUV(qWin, 0.94, 0.58),
    quadUV(qWin, 0.52, 0.62)
  ];
  let coreCol = flicker > 0.15 ? PAL.glowWhite : PAL.glowPale;
  let coreAlpha = Math.max(90, Math.min(250, Math.floor((isOpenCavity ? 235 : 195) + flicker * 65)));
  washPoly(qBulbCore, coreCol, coreAlpha);

  // 2. 3D Interior Cavity Walls
  let qCeil3D = [
    proj(xW0 - 0.06, yW1 + 0.04, zWin),
    proj(xW1 + 0.06, yW1 + 0.04, zWin),
    proj(xW1 + 0.06, yW1 + 0.04, zCavityBack),
    proj(xW0 - 0.06, yW1 + 0.04, zCavityBack)
  ];
  let qBack3D = [
    proj(xW0 - 0.06, yW1 + 0.04, zCavityBack),
    proj(xW1 + 0.06, yW1 + 0.04, zCavityBack),
    proj(xW1 + 0.06, yW0 - 0.08, zCavityBack),
    proj(xW0 - 0.06, yW0 - 0.08, zCavityBack)
  ];

  washPolyClipped(qCeil3D, qWin, PAL.glowOrange, 95);
  drawLineClipped(qBack3D[0], qBack3D[1], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qBack3D[0], qBack3D[3], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qBack3D[1], qBack3D[2], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qCeil3D[0], qCeil3D[3], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qCeil3D[1], qCeil3D[2], qWin, "cpencil", PAL.glowUmber, 0.42);

  let stepsBack = r <= 4 ? 7 : 4;
  for (let i = 0; i < stepsBack; i++) {
    let v = 0.15 + (i / stepsBack) * 0.72;
    let p1 = quadUV(qBack3D, 0.08, v);
    let p2 = quadUV(qBack3D, 0.92, v);
    drawLineClipped(p1, p2, qWin, "cpencil", PAL.glowOrange, 0.35);
  }

  // Pulsing incandescent oven bulb rays in upper right of ceiling
  let pBulb = proj(xW1 - 0.18, yW1 - 0.04, zWin - 0.28);
  let bulbRays = 6;
  let rayScale = Math.max(0.45, 1.0 + flicker * 0.65);
  let rayWeight = Math.max(0.35, 0.55 + flicker * 0.25);
  for (let i = 0; i < bulbRays; i++) {
    let a = (i / bulbRays) * Math.PI * 2 + t * 0.6;
    let pRay = {
      x: pBulb.x + Math.cos(a) * 14 * rayScale,
      y: pBulb.y + Math.sin(a) * 10 * rayScale
    };
    drawLineClipped(pBulb, pRay, qWin, "cpencil", PAL.glowWhite, rayWeight);
  }

  // 3. Rotating Glass Turntable at bottom of cavity
  let cx = (xW0 + xW1) * 0.50;
  let cz = zWin - 0.44;
  let yTurn = yW0 + (yW1 - yW0) * 0.12;
  let rTurn = (xW1 - xW0) * 0.43;

  let turnShadow = ellipse3D_XZ(cx, yTurn - 0.04, cz, rTurn * 0.92, rTurn * 0.72, 20);
  washPolyClipped(turnShadow, qWin, PAL.glowUmber, 115);

  let curTurnAngle = turnAngle + deltaDeg;
  let turnBot = ellipse3D_XZ(cx, yTurn, cz, rTurn, rTurn * 0.78, 24);
  let turnTop = ellipse3D_XZ(cx, yTurn + 0.03, cz, rTurn, rTurn * 0.78, 24);
  let turnHub = ellipse3D_XZ(cx, yTurn + 0.03, cz, rTurn * 0.22, rTurn * 0.17, 14);

  washPolyClipped(turnTop, qWin, PAL.glowGold, 110);
  drawSplineClipped(turnBot.concat([turnBot[0]]), qWin, "cpencil", PAL.glowUmber, 0.42, 0.4);
  drawSplineClipped(turnTop.concat([turnTop[0]]), qWin, "cpencil", PAL.glowWhite, 0.52, 0.4);
  drawSplineClipped(turnHub.concat([turnHub[0]]), qWin, "cpencil", PAL.glowRust, 0.35, 0.4);

  // Rotating glass roller-ring spokes under turntable so rotation reads even on round dishes
  for (let sp = 0; sp < 3; sp++) {
    let sa = ((curTurnAngle + sp * 120) * Math.PI) / 180;
    let pIn = proj(cx + Math.cos(sa) * rTurn * 0.20, yTurn + 0.02, cz + Math.sin(sa) * rTurn * 0.15);
    let pOut = proj(cx + Math.cos(sa) * rTurn * 0.88, yTurn + 0.02, cz + Math.sin(sa) * rTurn * 0.68);
    drawLineClipped(pIn, pOut, qWin, "cpencil", PAL.glowPale, 0.36);
  }

  // 4. Draw the Specific Hyperreal Vignette (Animated rotation & rising steam)
  let yPlateBase = yTurn + 0.035;
  if (vignette === "noodles") {
    drawVignetteNoodlesAnimated(cx, yPlateBase, cz, rTurn, turnAngle, deltaDeg, t, qWin, r);
  } else if (vignette === "mug") {
    drawVignetteMugAnimated(cx, yPlateBase, cz, rTurn, turnAngle, deltaDeg, t, qWin, r);
  } else if (vignette === "butter") {
    drawVignetteButterAnimated(cx, yPlateBase, cz, rTurn, turnAngle, deltaDeg, t, qWin, r);
  } else if (vignette === "dome") {
    drawVignetteDomeAnimated(cx, yPlateBase, cz, rTurn, turnAngle, deltaDeg, t, qWin, r);
  } else {
    drawVignetteSoupAnimated(cx, yPlateBase, cz, rTurn, turnAngle, deltaDeg, t, qWin, r);
  }

  // Brownout shadow veil or surge highlight veil across window cavity
  if (flicker < -0.22) {
    let veilAlpha = Math.min(135, Math.floor((-flicker - 0.22) * 190));
    washPoly(qWin, PAL.glowDeep, veilAlpha);
  } else if (flicker > 0.28) {
    let flareAlpha = Math.min(95, Math.floor((flicker - 0.28) * 140));
    washPoly(qHotspot, PAL.glowWhite, flareAlpha);
  }

  // 5. Faraday Shield Mesh & Window Glass Reflections (only if closed door)
  if (!isOpenCavity) {
    let qScreenBorder = [
      quadUV(qWin, 0.06, 0.92),
      quadUV(qWin, 0.94, 0.92),
      quadUV(qWin, 0.94, 0.08),
      quadUV(qWin, 0.06, 0.08)
    ];
    strokePoly(qScreenBorder, true, "rotring", PAL.glowUmber, 0.24, 0);

    if (r <= 5) {
      for (let i = 1; i <= 3; i++) {
        let vt = 0.86 + i * 0.032;
        let vb = 0.14 - i * 0.032;
        drawLine2D(quadUV(qWin, 0.04, vt), quadUV(qWin, 0.96, vt), "rotring", PAL.glowDeep, 0.18, 0);
        drawLine2D(quadUV(qWin, 0.04, vb), quadUV(qWin, 0.96, vb), "rotring", PAL.glowDeep, 0.18, 0);
      }
    }

    // Crisp diagonal glass reflection streaks
    drawLine2D(
      quadUV(qWin, 0.12, 0.14),
      quadUV(qWin, 0.42, 0.86),
      "cpencil",
      PAL.glowWhite,
      0.52 + Math.max(0, flicker * 0.18),
      0
    );
    drawLine2D(
      quadUV(qWin, 0.18, 0.14),
      quadUV(qWin, 0.46, 0.82),
      "cpencil",
      PAL.glowPale,
      0.35,
      0
    );
  }
}

function drawVignetteNoodlesAnimated(cx, yBase, cz, rTurn, turnAngle, deltaDeg, animT, qWin, rowIdx) {
  let rFoot = rTurn * 0.34;
  let rBelly = rTurn * 0.56;
  let rRim = rTurn * 0.66;
  let hBowl = 0.40;

  let shadowEll = ellipse3D_XZ(cx - 0.04, yBase, cz + 0.03, rBelly * 1.05, rBelly * 0.82, 18);
  washPolyClipped(shadowEll, qWin, PAL.glowDeep, 145);

  let ellFoot = ellipse3D_XZ(cx, yBase + 0.02, cz, rFoot, rFoot * 0.78, 18);
  let ellBelly = ellipse3D_XZ(cx, yBase + hBowl * 0.48, cz, rBelly, rBelly * 0.78, 20);
  let ellStripe = ellipse3D_XZ(cx, yBase + hBowl * 0.82, cz, rRim * 0.95, rRim * 0.74, 20);
  let ellRim = ellipse3D_XZ(cx, yBase + hBowl, cz, rRim, rRim * 0.78, 22);

  let bowlHull = [];
  for (let i = 0; i <= 11; i++) bowlHull.push(ellRim[i]);
  for (let i = 10; i >= 0; i--) bowlHull.push(ellFoot[i]);
  washPolyClipped(bowlHull, qWin, PAL.glowOrange, 225);

  let bowlShadowHull = [];
  for (let i = 0; i <= 7; i++) bowlShadowHull.push(ellBelly[i]);
  for (let i = 7; i >= 0; i--) bowlShadowHull.push(ellFoot[i]);
  washPolyClipped(bowlShadowHull, qWin, PAL.glowUmber, 190);

  washPolyClipped(ellRim, qWin, PAL.glowAmber, 225);

  // Rotating Mound of Golden Noodles
  let rotAngle = turnAngle + deltaDeg;
  let nStrands = rowIdx <= 3 ? 24 : 13;
  for (let s = 0; s < nStrands; s++) {
    let seedA = (s * 47 + rotAngle) * 0.01745;
    let strandPts = [];
    let segs = 5;
    for (let k = 0; k <= segs; k++) {
      let kt = k / segs;
      let ang = seedA + kt * 2.8 + Math.sin(s * 1.7 + k) * 0.7;
      let rad = rRim * (0.15 + 0.68 * Math.sin(kt * Math.PI) * ((s % 3) * 0.22 + 0.45));
      let nx = cx + Math.cos(ang) * rad;
      let nz = cz + Math.sin(ang) * rad * 0.75;
      let ny = yBase + hBowl + Math.sin(kt * Math.PI) * 0.16 * (1 - (rad / rRim) * 0.5);
      strandPts.push(proj(nx, ny, nz));
    }
    let colChoice =
      s % 4 === 0
        ? PAL.glowWhite
        : s % 4 === 1
        ? PAL.glowPale
        : s % 4 === 2
        ? PAL.glowGold
        : PAL.glowRust;
    let wChoice = s % 4 === 0 ? 0.46 : 0.38;
    drawSplineClipped(strandPts, qWin, "cpencil", colChoice, wChoice, 0.65);
  }

  drawSplineClipped(ellFoot.slice(0, 12), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
  drawSplineClipped(ellBelly.slice(0, 13), qWin, "cpencil", PAL.glowPale, 0.44, 0.4);
  drawSplineClipped(ellStripe.slice(0, 13), qWin, "rotring", PAL.glowDeep, 0.34, 0.4);
  drawSplineClipped(ellRim.concat([ellRim[0]]), qWin, "rotring", PAL.glowDeep, 0.40, 0.4);
  drawSplineClipped(ellRim.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.62, 0.4);

  // Pair of Wooden Chopsticks rotating in 3D with the bowl (exact match at deltaDeg = 0)
  let csRad = ((turnAngle * 0.4 + 28 + deltaDeg) * Math.PI) / 180;
  let dx = Math.cos(csRad);
  let dz = Math.sin(csRad);
  for (let stick = 0; stick < 2; stick++) {
    let off = (stick - 0.5) * 0.07;
    let pTip = proj(
      cx - dx * rRim * 0.75 + off,
      yBase + hBowl + 0.05,
      cz - dz * rRim * 0.55
    );
    let pTail = proj(
      cx + dx * rRim * 1.18 + off * 1.8,
      yBase + hBowl + 0.24,
      cz + dz * rRim * 0.85
    );
    drawLineClipped(pTip, pTail, qWin, "rotring", PAL.glowDeep, 0.48);
    drawLineClipped(
      { x: pTip.x, y: pTip.y - 1.2 },
      { x: pTail.x, y: pTail.y - 1.5 },
      qWin,
      "cpencil",
      PAL.glowWhite,
      0.42
    );
  }

  drawSteamWispsAnimated(cx, yBase + hBowl + 0.14, cz, rRim * 0.5, 0.42, qWin, 4, animT);
}

function drawVignetteMugAnimated(cx, yBase, cz, rTurn, turnAngle, deltaDeg, animT, qWin, rowIdx) {
  let rSaucer = rTurn * 0.56;
  let rMug = rTurn * 0.34;
  let hMug = 0.52;

  let shadowEll = ellipse3D_XZ(cx - 0.05, yBase, cz + 0.03, rSaucer * 1.05, rSaucer * 0.80, 18);
  washPolyClipped(shadowEll, qWin, PAL.glowDeep, 145);

  let saucerBot = ellipse3D_XZ(cx, yBase + 0.02, cz, rSaucer * 0.72, rSaucer * 0.56, 18);
  let saucerRim = ellipse3D_XZ(cx, yBase + 0.07, cz, rSaucer, rSaucer * 0.78, 22);
  washPolyClipped(saucerRim, qWin, PAL.glowGold, 215);
  drawSplineClipped(saucerBot.slice(0, 12), qWin, "rotring", PAL.glowDeep, 0.32, 0.4);
  drawSplineClipped(saucerRim.concat([saucerRim[0]]), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
  drawSplineClipped(saucerRim.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.55, 0.4);

  let mugBot = ellipse3D_XZ(cx, yBase + 0.06, cz, rMug, rMug * 0.78, 20);
  let mugMid = ellipse3D_XZ(cx, yBase + hMug * 0.52, cz, rMug, rMug * 0.78, 20);
  let mugTop = ellipse3D_XZ(cx, yBase + hMug, cz, rMug * 1.03, rMug * 0.80, 20);
  let mugLiquid = ellipse3D_XZ(cx, yBase + hMug - 0.04, cz, rMug * 0.92, rMug * 0.72, 18);

  let mugHull = [];
  for (let i = 0; i <= 10; i++) mugHull.push(mugTop[i]);
  for (let i = 10; i >= 0; i--) mugHull.push(mugBot[i]);
  washPolyClipped(mugHull, qWin, PAL.glowAmber, 235);

  let mugShadow = [];
  for (let i = 5; i <= 10; i++) mugShadow.push(mugTop[i]);
  for (let i = 10; i >= 5; i--) mugShadow.push(mugBot[i]);
  washPolyClipped(mugShadow, qWin, PAL.glowUmber, 195);

  for (let idx of [2, 3]) {
    drawLineClipped(mugBot[idx], mugTop[idx], qWin, "cpencil", PAL.glowWhite, 0.65);
  }
  for (let idx of [4, 5]) {
    drawLineClipped(mugBot[idx], mugTop[idx], qWin, "cpencil", PAL.glowGold, 0.48);
  }

  // Smooth 3D revolving mug handle (matches hSide * rMug at deltaDeg = 0)
  let hSide = (turnAngle % 180) < 90 ? 1 : -1;
  let rotRad = (deltaDeg * Math.PI) / 180;
  let hx = hSide * Math.cos(rotRad);
  let hz = hSide * Math.sin(rotRad) * 0.78;

  let handlePtsOuter = [
    proj(cx + hx * rMug * 0.95, yBase + hMug * 0.82, cz + hz * rMug * 0.95),
    proj(cx + hx * rMug * 1.58, yBase + hMug * 0.76, cz + hz * rMug * 1.58),
    proj(cx + hx * rMug * 1.62, yBase + hMug * 0.34, cz + hz * rMug * 1.62),
    proj(cx + hx * rMug * 0.95, yBase + hMug * 0.24, cz + hz * rMug * 0.95)
  ];
  let handlePtsInner = [
    proj(cx + hx * rMug * 0.98, yBase + hMug * 0.72, cz + hz * rMug * 0.98),
    proj(cx + hx * rMug * 1.38, yBase + hMug * 0.66, cz + hz * rMug * 1.38),
    proj(cx + hx * rMug * 1.40, yBase + hMug * 0.40, cz + hz * rMug * 1.40),
    proj(cx + hx * rMug * 0.98, yBase + hMug * 0.34, cz + hz * rMug * 0.98)
  ];
  drawSplineClipped(handlePtsOuter, qWin, "cpencil", PAL.glowWhite, 0.62, 0.55);
  drawSplineClipped(handlePtsOuter, qWin, "rotring", PAL.glowDeep, 0.42, 0.55);
  drawSplineClipped(handlePtsInner, qWin, "rotring", PAL.glowDeep, 0.36, 0.55);

  washPolyClipped(mugTop, qWin, PAL.glowPale, 225);
  washPolyClipped(mugLiquid, qWin, PAL.glowDeep, 225);
  drawSplineClipped(mugLiquid.slice(1, 9), qWin, "cpencil", PAL.glowGold, 0.45, 0.4);
  drawSplineClipped(mugTop.concat([mugTop[0]]), qWin, "rotring", PAL.glowDeep, 0.40, 0.4);
  drawSplineClipped(mugBot.slice(0, 11), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);
  drawSplineClipped(mugMid.slice(1, 9), qWin, "cpencil", PAL.glowPale, 0.32, 0.4);

  // Teaspoon handle orbiting smoothly opposite the handle
  let pSpoonIn = proj(cx - hx * rMug * 0.35, yBase + hMug - 0.02, cz - hz * rMug * 0.35);
  let pSpoonOut = proj(
    cx - hx * rMug * 0.85,
    yBase + hMug + 0.16,
    cz - hz * rMug * 0.85 + 0.06 * Math.cos(rotRad)
  );
  drawLineClipped(pSpoonIn, pSpoonOut, qWin, "rotring", PAL.glowDeep, 0.44);
  drawLineClipped(
    { x: pSpoonIn.x, y: pSpoonIn.y - 1 },
    { x: pSpoonOut.x, y: pSpoonOut.y - 1.2 },
    qWin,
    "cpencil",
    PAL.glowWhite,
    0.45
  );

  drawSteamWispsAnimated(cx, yBase + hMug + 0.08, cz, rMug * 0.55, 0.36, qWin, 3, animT);
}

function drawVignetteButterAnimated(cx, yBase, cz, rTurn, turnAngle, deltaDeg, animT, qWin, rowIdx) {
  let ang = ((turnAngle * 0.5 + 18 + deltaDeg) * Math.PI) / 180;
  let ca = Math.cos(ang);
  let sa = Math.sin(ang);

  function dishPt(lx, dy, lz) {
    return proj(
      cx + lx * ca - lz * sa,
      yBase + dy,
      cz + lx * sa + lz * ca
    );
  }

  let dw = rTurn * 0.68;
  let dd = rTurn * 0.46;

  let qShadow = [
    dishPt(-dw * 1.04, 0.01, -dd * 1.04),
    dishPt(dw * 1.04, 0.01, -dd * 1.04),
    dishPt(dw * 1.04, 0.01, dd * 1.04),
    dishPt(-dw * 1.04, 0.01, dd * 1.04)
  ];
  washPolyClipped(qShadow, qWin, PAL.glowDeep, 155);

  let qTrayOuter = [
    dishPt(-dw, 0.07, -dd),
    dishPt(dw, 0.07, -dd),
    dishPt(dw, 0.07, dd),
    dishPt(-dw, 0.07, dd)
  ];
  let qTrayInner = [
    dishPt(-dw * 0.78, 0.08, -dd * 0.76),
    dishPt(dw * 0.78, 0.08, -dd * 0.76),
    dishPt(dw * 0.78, 0.08, dd * 0.76),
    dishPt(-dw * 0.78, 0.08, dd * 0.76)
  ];
  washPolyClipped(qTrayOuter, qWin, PAL.glowGold, 225);
  washPolyClipped(qTrayInner, qWin, PAL.glowAmber, 220);

  for (let i = 0; i < 4; i++) {
    drawLineClipped(qTrayOuter[i], qTrayOuter[(i + 1) % 4], qWin, "rotring", PAL.glowDeep, 0.40);
    drawLineClipped(qTrayInner[i], qTrayInner[(i + 1) % 4], qWin, "rotring", PAL.glowRust, 0.30);
  }
  drawLineClipped(qTrayOuter[2], qTrayOuter[3], qWin, "cpencil", PAL.glowWhite, 0.62);
  drawLineClipped(qTrayOuter[1], qTrayOuter[2], qWin, "cpencil", PAL.glowWhite, 0.55);

  // Melted butter puddle spreads slightly as it heats and turns
  let spread = 1.0 + Math.min(0.16, animT * 0.08);
  let puddlePts = [];
  let pSteps = 16;
  for (let i = 0; i < pSteps; i++) {
    let a = (i / pSteps) * Math.PI * 2;
    let lobe = 1 + 0.22 * Math.sin(a * 3 + 0.8) + 0.14 * Math.cos(a * 2);
    let px = (Math.cos(a) * dw * 0.62 + dw * 0.08) * lobe * spread;
    let pz = (Math.sin(a) * dd * 0.58 + dd * 0.06) * lobe * spread;
    puddlePts.push(dishPt(px, 0.09, pz));
  }
  washPolyClipped(puddlePts, qWin, PAL.glowPale, 235);
  drawSplineClipped(puddlePts.concat([puddlePts[0]]), qWin, "cpencil", PAL.glowRust, 0.38, 0.5);
  drawSplineClipped(puddlePts.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.65, 0.5);

  // Butter stick slumps slightly as it melts
  let meltFactor = Math.max(0.76, 1.0 - animT * 0.10);
  let bw = dw * 0.46;
  let bd = dd * 0.36;
  let bhLeft = 0.28 * meltFactor;
  let bhRight = 0.14 * meltFactor;

  let bBotFL = dishPt(-bw, 0.09, bd);
  let bBotFR = dishPt(bw * 0.92, 0.09, bd * 1.05);
  let bBotBR = dishPt(bw * 0.88, 0.09, -bd * 0.92);
  let bBotBL = dishPt(-bw, 0.09, -bd);

  let bTopFL = dishPt(-bw * 0.92, 0.09 + bhLeft, bd * 0.86);
  let bTopMid = dishPt(0, 0.09 + bhLeft * 0.88, bd * 0.88);
  let bTopFR = dishPt(bw * 0.78, 0.09 + bhRight, bd * 0.82);
  let bTopBR = dishPt(bw * 0.75, 0.09 + bhRight, -bd * 0.78);
  let bTopBL = dishPt(-bw * 0.92, 0.09 + bhLeft, -bd * 0.84);

  let qButterFront = [bTopFL, bTopMid, bTopFR, bBotFR, bBotFL];
  washPolyClipped(qButterFront, qWin, PAL.glowAmber, 235);

  let qButterSide = [bTopFR, bTopBR, bBotBR, bBotFR];
  washPolyClipped(qButterSide, qWin, PAL.glowRust, 215);

  let qButterTop = [bTopBL, bTopBR, bTopFR, bTopMid, bTopFL];
  washPolyClipped(qButterTop, qWin, PAL.glowPale, 245);

  for (let d = -0.5; d <= 0.6; d += 0.35) {
    let pDripTop = dishPt(bw * d, 0.09 + bhLeft * (0.78 - d * 0.25), bd * 0.86);
    let pDripBot = dishPt(bw * (d + 0.06), 0.09, bd * 1.02);
    drawLineClipped(pDripTop, pDripBot, qWin, "cpencil", PAL.glowWhite, 0.48);
  }

  drawSplineClipped([bBotFL, bTopFL, bTopMid, bTopFR, bBotFR], qWin, "rotring", PAL.glowDeep, 0.38, 0.45);
  drawSplineClipped([bTopFL, bTopBL, bTopBR, bTopFR], qWin, "rotring", PAL.glowDeep, 0.34, 0.4);
  drawSplineClipped([bTopFL, bTopMid, bTopFR], qWin, "cpencil", PAL.glowWhite, 0.65, 0.45);

  let k1 = dishPt(dw * 0.35, 0.10, dd * 0.25);
  let k2 = dishPt(dw * 1.08, 0.15, dd * 0.78);
  drawLineClipped(k1, k2, qWin, "rotring", PAL.glowDeep, 0.42);
  drawLineClipped(
    { x: k1.x, y: k1.y - 1.2 },
    { x: k2.x, y: k2.y - 1.2 },
    qWin,
    "cpencil",
    PAL.glowWhite,
    0.48
  );
}

function drawVignetteDomeAnimated(cx, yBase, cz, rTurn, turnAngle, deltaDeg, animT, qWin, rowIdx) {
  let rPlate = rTurn * 0.68;
  let rDome = rTurn * 0.56;
  let hDome = 0.44;

  let plateRim = ellipse3D_XZ(cx, yBase + 0.05, cz, rPlate, rPlate * 0.78, 20);
  washPolyClipped(plateRim, qWin, PAL.glowGold, 220);
  drawSplineClipped(plateRim.concat([plateRim[0]]), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);

  let domeBase = ellipse3D_XZ(cx, yBase + 0.06, cz, rDome, rDome * 0.76, 18);
  let domeArch = [];
  for (let i = 0; i <= 12; i++) {
    let a = (i / 12) * Math.PI;
    let dx = Math.cos(a) * rDome;
    let dy = Math.sin(a) * hDome;
    domeArch.push(proj(cx + dx, yBase + 0.06 + dy, cz));
  }
  let domePoly = domeArch.concat(domeBase.slice(0, 10));
  washPolyClipped(domePoly, qWin, PAL.glowPale, 155);
  drawSplineClipped(domeArch, qWin, "rotring", PAL.glowDeep, 0.38, 0.5);
  drawSplineClipped(domeArch.slice(2, 9), qWin, "cpencil", PAL.glowWhite, 0.62, 0.5);

  // Revolving specular rib on glass dome
  let ribAng = ((turnAngle + deltaDeg) * Math.PI) / 180;
  let ribPts = [];
  for (let i = 0; i <= 6; i++) {
    let s = (i / 6) * (Math.PI * 0.5);
    let rr = Math.cos(s) * rDome;
    let ry = Math.sin(s) * hDome;
    ribPts.push(proj(cx + Math.cos(ribAng) * rr, yBase + 0.06 + ry, cz + Math.sin(ribAng) * rr * 0.76));
  }
  drawSplineClipped(ribPts, qWin, "cpencil", PAL.glowWhite, 0.50, 0.5);

  let knobEll = ellipse3D_XZ(cx, yBase + 0.08 + hDome, cz, rDome * 0.22, rDome * 0.16, 12);
  drawSplineClipped(knobEll.concat([knobEll[0]]), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
}

function drawVignetteSoupAnimated(cx, yBase, cz, rTurn, turnAngle, deltaDeg, animT, qWin, rowIdx) {
  let rBowl = rTurn * 0.62;
  let hBowl = 0.28;
  let ellBot = ellipse3D_XZ(cx, yBase + 0.02, cz, rBowl * 0.55, rBowl * 0.44, 16);
  let ellTop = ellipse3D_XZ(cx, yBase + hBowl, cz, rBowl, rBowl * 0.78, 20);

  let hull = ellTop.slice(0, 11).concat(ellBot.slice(0, 10).reverse());
  washPolyClipped(hull, qWin, PAL.glowOrange, 225);
  washPolyClipped(ellTop, qWin, PAL.glowGold, 225);
  drawSplineClipped(ellTop.concat([ellTop[0]]), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);
  drawSplineClipped(ellTop.slice(2, 9), qWin, "cpencil", PAL.glowWhite, 0.58, 0.4);

  // Ladle handle rotating in 3D with the bowl (exact match at deltaDeg = 0)
  let rotRad = (deltaDeg * Math.PI) / 180;
  let lx = rBowl * 0.88 * Math.cos(rotRad) - 0.08 * Math.sin(rotRad);
  let lz = (rBowl * 0.88 * Math.sin(rotRad) + 0.08 * Math.cos(rotRad)) * 0.78;
  let p1 = proj(cx, yBase + hBowl, cz);
  let p2 = proj(cx + lx, yBase + hBowl + 0.18, cz + lz);
  drawLineClipped(p1, p2, qWin, "rotring", PAL.glowDeep, 0.44);
  drawSteamWispsAnimated(cx, yBase + hBowl + 0.06, cz, rBowl * 0.45, 0.34, qWin, 3, animT);
}

function drawSteamWispsAnimated(cx, y0, cz, spread, height, qWin, count, animT) {
  for (let i = 0; i < count; i++) {
    let ox = (i / (count - 1) - 0.5) * spread * 1.4;
    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let kt = k / 4;
      let wx = cx + ox + Math.sin(kt * Math.PI * 2 + i * 1.6 - animT * 5.2) * 0.085;
      let wy = y0 + kt * height;
      let wz = cz + Math.cos(kt * Math.PI + i - animT * 4.0) * 0.05;
      pts.push(proj(wx, wy, wz));
    }
    drawSplineClipped(pts, qWin, "cpencil", PAL.glowWhite, 0.42, 0.6);
  }
}

function drawAnimatedForegroundHum(t, env) {
  randomSeed(42999);
  noiseSeed(42999);
