  for (let s = 0; s < 4; s++) {
    let ox = -0.55 + s * 0.28;
    let pts = [];
    for (let k = 0; k <= 5; k++) {
      let kt = k / 5;
      let wx = ox + Math.sin(kt * Math.PI * 2 + s * 1.4 - t * 4.8) * 0.11 * env;
      let wy = yHeroTop + kt * 0.95 * env;
      let wz = zHeroFront + kt * 0.25;
      pts.push(proj(wx, wy, wz));
    }
    drawSpline2D(pts, "cpencil", s % 2 === 0 ? PAL.glowWhite : PAL.glowPale, 0.44 * env, 0.6);
