  // Re-establish the two foreground warm amber spray hum lines so they stay on top of the redrawn windows
  randomSeed(88421);
  noiseSeed(88421);
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("spray", PAL.glowGold, 0.45);
  brush.line(320, 560, 780, 520);
  brush.line(340, 760, 760, 740);
}

