// ---------------------------------------------------------------------------
// 2. Megastructure Core Spine & Perspective Construction Grid
// ---------------------------------------------------------------------------
const PITCH_X = 2.86;
const PITCH_Y = 1.94;
const UNIT_W = 2.48;
const UNIT_H = 1.60;

function drawMegastructureCore() {
  brush.noField();

  // Architectural perspective construction rays in faint technical pencil
  for (let c = -3; c <= 3; c++) {
    let x = c * PITCH_X - PITCH_X * 0.5;
    let pBot = proj(x, -4.0, 0.2);
    let pTop = proj(x, 22.0, 0.2);
    drawLine2D(pBot, pTop, "2H", PAL.draftLine, 0.28, 0);
  }
  for (let r = -1; r <= 9; r++) {
    let y = r * PITCH_Y - 0.16;
    let pL = proj(-10.5, y, 0.2);
    let pR = proj(10.5, y, 0.2);
    drawLine2D(pL, pR, "2H", PAL.draftLine, 0.25, 0);
  }

  // Deep recessed shadow channels between megastructure core shafts (z = -0.15)
  for (let c = -2; c <= 2; c++) {
    let xc = c * PITCH_X;
    let qBack = [
      proj(xc - 1.15, 19.5, -0.15),
      proj(xc + 1.15, 19.5, -0.15),
      proj(xc + 1.15, -3.5, -0.15),
      proj(xc - 1.15, -3.5, -0.15)
    ];
    washPoly(qBack, PAL.steel9, 215);
  }

  // Vertical Megastructure Core Steel Pilasters / Service Towers between columns
  for (let c = -2; c <= 3; c++) {
    let xPilaster = (c - 0.5) * PITCH_X;
    let pw = 0.22; // half-width of steel core column
    let zCoreFront = 0.42;
    let zCoreBack = -0.15;

    // Front face of core column
    let qFront = [
      proj(xPilaster - pw, 19.5, zCoreFront),
      proj(xPilaster + pw, 19.5, zCoreFront),
      proj(xPilaster + pw, -3.5, zCoreFront),
      proj(xPilaster - pw, -3.5, zCoreFront)
    ];
    washPoly(qFront, PAL.steel6, 210);
    markerBandQuad(qFront, "v", PAL.steel5, 0.55, 3, 0.15, 0.85, 0, 1);
    markerBandQuad(qFront, "v", PAL.steel7, 0.45, 2, 0.05, 0.3, 0, 1);

    // Side face of core column
    if (xPilaster - pw > camPos.x) {
      let qLeft = [
        proj(xPilaster - pw, 19.5, zCoreBack),
        proj(xPilaster - pw, 19.5, zCoreFront),
        proj(xPilaster - pw, -3.5, zCoreFront),
        proj(xPilaster - pw, -3.5, zCoreBack)
      ];
      washPoly(qLeft, PAL.steel8, 225);
      strokePoly(qLeft, true, "rotring", PAL.inkDark, 0.3, 0);
    } else if (xPilaster + pw < camPos.x) {
      let qRight = [
        proj(xPilaster + pw, 19.5, zCoreFront),
        proj(xPilaster + pw, 19.5, zCoreBack),
        proj(xPilaster + pw, -3.5, zCoreBack),
        proj(xPilaster + pw, -3.5, zCoreFront)
      ];
      washPoly(qRight, PAL.steel8, 225);
      strokePoly(qRight, true, "rotring", PAL.inkDark, 0.3, 0);
    }

    strokePoly(qFront, true, "rotring", PAL.inkDark, 0.38, 0);

    // Vertical electrical conduit pipes running up the core column
    for (let k = -1; k <= 1; k += 2) {
      let xPipe = xPilaster + k * 0.09;
      let p1 = proj(xPipe, -3.5, zCoreFront + 0.04);
      let p2 = proj(xPipe, 19.5, zCoreFront + 0.04);
      drawLine2D(p1, p2, "rotring", PAL.inkDark, 0.32, 0);
      let p1h = proj(xPipe + 0.02, -3.5, zCoreFront + 0.05);
      let p2h = proj(xPipe + 0.02, 19.5, zCoreFront + 0.05);
      drawLine2D(p1h, p2h, "2H", PAL.steel2, 0.25, 0);
    }

    // Horizontal structural tie-plates & bolt nodes at each level
    for (let r = 0; r <= 8; r++) {
      let yNode = r * PITCH_Y - 0.18;
      let qNode = [
        proj(xPilaster - pw - 0.04, yNode + 0.14, zCoreFront + 0.06),
        proj(xPilaster + pw + 0.04, yNode + 0.14, zCoreFront + 0.06),
        proj(xPilaster + pw + 0.04, yNode - 0.14, zCoreFront + 0.06),
        proj(xPilaster - pw - 0.04, yNode - 0.14, zCoreFront + 0.06)
      ];
      washPoly(qNode, PAL.steel4, 220);
      strokePoly(qNode, true, "rotring", PAL.inkDark, 0.35, 1.5);

      // 4 bolt rivets on gusset plate
      for (let bx of [-0.14, 0.14]) {
        for (let by of [-0.07, 0.07]) {
          let bp = proj(xPilaster + bx, yNode + by, zCoreFront + 0.07);
          drawLine2D(
            { x: bp.x - 1.8, y: bp.y },
            { x: bp.x + 1.8, y: bp.y },
            "rotring",
            PAL.inkDark,
            0.45,
            0
          );
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 3. Build List of 3D Microwave Capsule Modules
// ---------------------------------------------------------------------------
function buildCapsuleList() {
  let list = [];

  // Vignette types:
  // "noodles", "mug", "butter", "dome", "soup"
  for (let r = -1; r <= 7; r++) {
    for (let c = -2; c <= 2; c++) {
      let xc = c * PITCH_X;
      let x0 = xc - UNIT_W * 0.5;
      let x1 = xc + UNIT_W * 0.5;
      let y0 = r * PITCH_Y;
      let y1 = y0 + UNIT_H;

      // Plug-in capsule cantilever depth (varies slightly like Nakagin capsules)
      let depthPattern = ((c * 7 + r * 13 + 50) % 5);
      let zFront = 1.72 + depthPattern * 0.085;
      if (c === 0 && r === 2) zFront = 1.92; // Open door hero unit slightly proud
      if (c === 0 && r === 1) zFront = 1.88; // Butter dish hero unit
      if (c === -1 && r === 2) zFront = 1.84; // Mug hero unit
      if (c === 1 && r === 2) zFront = 1.82; // Noodles hero unit
      if (c === -1 && r === 3) zFront = 1.68; // Dead unit slightly recessed

      let isOpenDoor = (c === 0 && r === 2);
      let isDead = (c === -1 && r === 3);

      // Assign vignette carefully so noodles, mug, and melting butter dish dominate
      let vignette = "noodles";
      if (c === 0 && r === 2) vignette = "noodles";      // Open door hero: steaming noodles!
      else if (c === 0 && r === 1) vignette = "butter";  // Hero below open door: melting butter dish!
      else if (c === -1 && r === 2) vignette = "mug";    // Hero left of open door: ceramic mug!
      else if (c === 1 && r === 2) vignette = "noodles"; // Hero right of open door: noodles!
      else if (c === -1 && r === 1) vignette = "butter"; // Lower-left hero: melting butter dish!
      else if (c === 1 && r === 1) vignette = "mug";     // Lower-right hero: mug!
      else if (c === 0 && r === 3) vignette = "mug";     // Above open door: mug!
      else if (c === 1 && r === 3) vignette = "butter";  // Upper-right: melting butter dish!
      else if (c === -1 && r === 3) vignette = "mug";    // Dead unit: cold unlit mug
      else {
        let cycle = Math.abs(c * 3 + r * 5) % 5;
        if (cycle === 0) vignette = "noodles";
        else if (cycle === 1) vignette = "mug";
        else if (cycle === 2) vignette = "butter";
        else if (cycle === 3) vignette = "dome";
        else vignette = "soup";
      }

      // Turntable rotation angle (each plate slowly turning at a different phase)
      let turnAngle = ((c * 53 + r * 97 + 360) % 360);

      // Control panel style variation (0: dial + buttons, 1: keypad + pushbar, 2: dual dials)
      let panelStyle = Math.abs(c * 2 + r * 3) % 3;

      // Timer digits string
      let mins = Math.abs(c + r * 2) % 4;
      let secs = (Math.abs(c * 17 + r * 29) % 52) + 7;
      let timerStr = "0" + mins + ":" + (secs < 10 ? "0" + secs : secs);

      // Distance from camera to capsule center for Painter's Algorithm sorting
      let mx = (x0 + x1) * 0.5;
      let my = (y0 + y1) * 0.5;
      let mz = zFront * 0.55;
      let camDistSq =
        Math.pow(mx - camPos.x, 2) +
        Math.pow(my - camPos.y, 2) +
        Math.pow(mz - camPos.z, 2);

      list.push({
        c, r,
        x0, x1, y0, y1,
        zBack: 0.28,
        zFront,
        isOpenDoor,
        isDead,
        vignette,
        turnAngle,
        panelStyle,
        timerStr,
        camDistSq
      });
    }
  }
  return list;
}

// ---------------------------------------------------------------------------
// 4. Draw Individual Microwave Capsule (3D Housing, Soffit, Controls, Window)
// ---------------------------------------------------------------------------
function drawMicrowaveCapsule(cap) {
  let { x0, x1, y0, y1, zBack, zFront, isOpenDoor, isDead } = cap;

  // Quick off-screen check
  let pTestTop = proj((x0 + x1) * 0.5, y1, zFront);
  let pTestBot = proj((x0 + x1) * 0.5, y0, zBack);
  if (pTestTop.y > 1300 || pTestBot.y < -120) return;
  if (pTestTop.x < -220 || pTestTop.x > 1420) return;

  // A. Cantilever Steel Support Brackets & Coiled Power Cord underneath (if y0 > camPos.y)
  if (y0 > camPos.y + 0.15) {
    drawUndersideBracketsAndCord(cap);
  }

  // B. Bottom Face (Underside Soffit of the Microwave Housing)
  if (y0 > camPos.y) {
    drawCapsuleBottomSoffit(cap);
  }

  // C. Visible Side Face (Left face if x0 > camPos.x, Right face if x1 < camPos.x)
  if (x0 > camPos.x) {
    drawCapsuleSideFace(cap, "left");
  } else if (x1 < camPos.x) {
    drawCapsuleSideFace(cap, "right");
  }

  // D. Front Housing Chassis & Control Panel (Right 26% of front face)
  let xSplit = x0 + (x1 - x0) * 0.735;
  drawCapsuleFrontChassisAndControls(cap, xSplit);

  // E. Door & Glowing Window Vignette (Left 73.5% of front face)
  if (isOpenDoor) {
    drawOpenDoorHeroUnit(cap, xSplit);
  } else {
    drawClosedDoorAndWindow(cap, xSplit);
  }
}

function drawUndersideBracketsAndCord(cap) {
  let { x0, x1, y0, zBack, zFront, isDead, c, r } = cap;
  let yShelf = y0 - 0.15;

  // Two cantilevered steel I-brackets under the left and right sides of the capsule
  for (let s of [0.16, 0.84]) {
    let xb = x0 + (x1 - x0) * s;
    let bw = 0.06;
    let qArm = [
      proj(xb - bw, y0, zFront - 0.22),
      proj(xb + bw, y0, zFront - 0.22),
      proj(xb + bw, yShelf, zBack),
      proj(xb - bw, yShelf, zBack)
    ];
    washPoly(qArm, PAL.steel7, 225);
    strokePoly(qArm, true, "rotring", PAL.inkDark, 0.32, 0);
  }

  // Coiled/looped power cord hanging below unit and plugging into megastructure core
  let xCordStart = x0 + (x1 - x0) * 0.78;
  let xCordEnd = x1 + 0.16;
  let cordPts = [];
  if (isDead) {
    // Dead unit has a limp, unplugged cord dangling down!
    cordPts = [
      proj(xCordStart, y0, zBack + 0.35),
      proj(xCordStart + 0.12, y0 - 0.28, zBack + 0.45),
      proj(xCordStart + 0.06, y0 - 0.58, zBack + 0.52),
      proj(xCordStart + 0.15, y0 - 0.82, zBack + 0.48)
    ];
    drawSpline2D(cordPts, "rotring", PAL.inkDark, 0.55, 0.5);
    // Plug prongs at dangling end
    let pEnd = cordPts[cordPts.length - 1];
    drawLine2D(pEnd, { x: pEnd.x - 3, y: pEnd.y + 6 }, "rotring", PAL.inkDark, 0.35, 0);
    drawLine2D(pEnd, { x: pEnd.x + 2, y: pEnd.y + 6 }, "rotring", PAL.inkDark, 0.35, 0);
  } else {
    cordPts = [
      proj(xCordStart, y0, zBack + 0.35),
      proj(xCordStart + 0.18, y0 - 0.24, zBack + 0.30),
      proj(xCordEnd, y0 - 0.14, zBack + 0.12)
    ];
    drawSpline2D(cordPts, "rotring", PAL.inkDark, 0.48, 0.5);
  }
}

function drawCapsuleBottomSoffit(cap) {
  let { x0, x1, y0, zBack, zFront, isDead, c, r } = cap;

  // Quad of bottom underside [FrontLeft, FrontRight, BackRight, BackLeft]
  let qBot = [
    proj(x0, y0, zFront),
    proj(x1, y0, zFront),
    proj(x1, y0, zBack),
    proj(x0, y0, zBack)
  ];

  // Base cool dark steel wash on underside
  washPoly(qBot, PAL.steel7, 235);

  // Layered cool grey marker bands along underside depth
  markerBandQuad(qBot, "h", PAL.steel8, 0.65, 4, 0.04, 0.96, 0.08, 0.55);
  markerBandQuad(qBot, "h", PAL.steel6, 0.55, 3, 0.04, 0.96, 0.62, 0.92);

  // Warm amber bounce light on the front underside lip from glowing units below!
  let hasWarmBounce = !isDead && !(c === -1 && r === 4);
  if (hasWarmBounce) {
    let qWarmLip = [
      quadUV(qBot, 0.03, 0.98),
      quadUV(qBot, 0.72, 0.98),
      quadUV(qBot, 0.72, 0.68),
      quadUV(qBot, 0.03, 0.68)
    ];
    // Extra bright warm bounce if directly above the Open Door unit (c===0, r===3)
    let bounceAlpha = (c === 0 && r === 3) ? 145 : 75;
    washPoly(qWarmLip, PAL.glowAmber, bounceAlpha);
    markerBandQuad(qBot, "h", PAL.warmSteel3, 0.45, 2, 0.05, 0.72, 0.82, 0.96);
  }

  // Recessed stamped maintenance panel on underside
  let qPan = [
    quadUV(qBot, 0.14, 0.78),
    quadUV(qBot, 0.68, 0.78),
    quadUV(qBot, 0.68, 0.25),
    quadUV(qBot, 0.14, 0.25)
  ];
  strokePoly(qPan, true, "rotring", PAL.inkDark, 0.26, 0);

  // Louvered underside cooling vents in technical pen
  for (let i = 0; i < 6; i++) {
    let v = 0.32 + (i / 5) * 0.38;
    let p1 = quadUV(qBot, 0.74, v);
    let p2 = quadUV(qBot, 0.92, v);
    drawLine2D(p1, p2, "rotring", PAL.inkDark, 0.24, 0);
  }

  // Four cylindrical rubber/steel isolation feet protruding from underside corners
  let footCoords = [
    { u: 0.09, v: 0.84 },
    { u: 0.89, v: 0.84 },
    { u: 0.09, v: 0.18 },
    { u: 0.89, v: 0.18 }
  ];
  for (let fc of footCoords) {
    let fx = x0 + (x1 - x0) * fc.u;
    let fz = zBack + (zFront - zBack) * fc.v;
    let footTop = ellipse3D_XZ(fx, y0, fz, 0.09, 0.09, 10);
    let footBot = ellipse3D_XZ(fx, y0 - 0.09, fz, 0.08, 0.08, 10);
    washPoly(footBot, PAL.steel9, 240);
    strokePoly(footTop, true, "rotring", PAL.inkDark, 0.26, 0);
    strokePoly(footBot, true, "rotring", PAL.inkDark, 0.30, 0);
  }

  // Crisp ruled perimeter of bottom soffit
  strokePoly(qBot, true, "rotring", PAL.inkDark, 0.42, 1.2);
}

function drawCapsuleSideFace(cap, side) {
  let { x0, x1, y0, y1, zBack, zFront } = cap;
  let xs = side === "left" ? x0 : x1;

  // Quad [TopBack, TopFront, BotFront, BotBack]
  let qSide = [
    proj(xs, y1, zBack),
    proj(xs, y1, zFront),
    proj(xs, y0, zFront),
    proj(xs, y0, zBack)
  ];

  // Brushed stainless steel side housing in cool grey marker layers
  washPoly(qSide, PAL.steel5, 235);
  markerBandQuad(qSide, "h", PAL.steel4, 0.65, 6, 0.04, 0.96, 0.12, 0.88);
  markerBandQuad(qSide, "h", PAL.steel3, 0.50, 3, 0.08, 0.92, 0.52, 0.76);
  markerBandQuad(qSide, "h", PAL.steel6, 0.55, 4, 0.04, 0.96, 0.04, 0.32);

  // Fine brushed metal grain lines
  hatchPoly(qSide, "2H", PAL.steel2, 0.25, 7, 12, { rand: 0.02 });

  // Stamped side ventilation louver banks (two vertical columns of horizontal slits)
  for (let colBank of [0.22, 0.52]) {
    for (let i = 0; i < 9; i++) {
      let v = 0.25 + (i / 8) * 0.52;
      let p1 = quadUV(qSide, colBank, v);
      let p2 = quadUV(qSide, colBank + 0.18, v);
      drawLine2D(p1, p2, "rotring", PAL.inkDark, 0.24, 0);
    }
  }

  // Sheet metal seam & screws near back edge
  let pSeamTop = quadUV(qSide, 0.12, 0.98);
  let pSeamBot = quadUV(qSide, 0.12, 0.02);
  drawLine2D(pSeamTop, pSeamBot, "rotring", PAL.inkMid, 0.24, 0);

  strokePoly(qSide, true, "rotring", PAL.inkDark, 0.44, 1.2);
}

function drawCapsuleFrontChassisAndControls(cap, xSplit) {
  let { x0, x1, y0, y1, zFront, isDead, panelStyle, timerStr, r, c } = cap;

  // Full front chassis perimeter quad at z = zFront
  let qChassis = [
    proj(x0, y1, zFront),
    proj(x1, y1, zFront),
    proj(x1, y0, zFront),
    proj(x0, y0, zFront)
  ];

  // Base brushed-steel wash
  washPoly(qChassis, PAL.steel3, 240);

  // Control panel quad (xSplit to x1)
  let qCtrl = [
    proj(xSplit, y1, zFront),
    proj(x1, y1, zFront),
    proj(x1, y0, zFront),
    proj(xSplit, y0, zFront)
  ];

  // Layered cool grey marker strokes for brushed stainless steel control panel
  washPoly(qCtrl, PAL.steel3, 235);
  markerBandQuad(qCtrl, "h", PAL.steel2, 0.55, 5, 0.05, 0.95, 0.55, 0.92);
  markerBandQuad(qCtrl, "h", PAL.steel4, 0.55, 5, 0.05, 0.95, 0.12, 0.48);
  markerBandQuad(qCtrl, "d", PAL.steel1, 0.45, 3, 0.1, 0.9, 0.3, 0.85);

  // Brushed horizontal steel micro-grain
  hatchPoly(qCtrl, "2H", PAL.steel5, 0.22, 6, 4, { rand: 0.02 });

  // Outer stainless bevel highlight along top and right edge
  drawLine2D(qChassis[0], qChassis[1], "cpencil", PAL.warmSteel1, 0.55, 0);
  drawLine2D(qCtrl[0], qCtrl[3], "rotring", PAL.inkDark, 0.42, 0);

  // 1. Recessed Digital LED Timer Display Window (top of control panel)
  let qLed = [
    quadUV(qCtrl, 0.12, 0.90),
    quadUV(qCtrl, 0.88, 0.90),
    quadUV(qCtrl, 0.88, 0.75),
    quadUV(qCtrl, 0.12, 0.75)
  ];
  washPoly(qLed, isDead ? PAL.deadGlass1 : "#1c1612", 245);
  strokePoly(qLed, true, "rotring", PAL.inkDark, 0.34, 0);
  // Bottom bevel of recessed LED bezel
  drawLine2D(qLed[3], qLed[2], "cpencil", PAL.steel1, 0.38, 0);

  if (!isDead) {
    // Glowing 7-segment style digital timer readout + indicator dot
    drawLedReadout(qLed, timerStr);
  }

  // 2. Control Panel Buttons & Rotary Dial (only draw fine details if not tiny at very top)
  if (r <= 6) {
    if (panelStyle === 0 || panelStyle === 2) {
      // Tactile membrane button rows in middle
      let rows = 3, cols = 2;
      for (let br = 0; br < rows; br++) {
        for (let bc = 0; bc < cols; bc++) {
          let uA = 0.14 + bc * 0.39;
          let uB = uA + 0.33;
          let vB = 0.68 - br * 0.095;
          let vA = vB - 0.065;
          let qBtn = [
            quadUV(qCtrl, uA, vB),
            quadUV(qCtrl, uB, vB),
            quadUV(qCtrl, uB, vA),
            quadUV(qCtrl, uA, vA)
          ];
          washPoly(qBtn, PAL.steel2, 180);
          strokePoly(qBtn, true, "rotring", PAL.inkMid, 0.22, 0);
        }
      }

      // 3D Protruding Chrome Rotary Timer Dial below buttons
      let dialX = xSplit + (x1 - xSplit) * 0.5;
      let dialY = y0 + (y1 - y0) * 0.30;
      let dialR = (x1 - xSplit) * 0.23;
      drawProtrudingDial(dialX, dialY, zFront, dialR, isDead);
    } else {
      // 10-key numeric pad grid
      for (let br = 0; br < 4; br++) {
        for (let bc = 0; bc < 3; bc++) {
          let uA = 0.13 + bc * 0.26;
          let uB = uA + 0.21;
          let vB = 0.68 - br * 0.09;
          let vA = vB - 0.062;
          let qBtn = [
            quadUV(qCtrl, uA, vB),
            quadUV(qCtrl, uB, vB),
            quadUV(qCtrl, uB, vA),
            quadUV(qCtrl, uA, vA)
          ];
          strokePoly(qBtn, true, "rotring", PAL.inkMid, 0.20, 0);
        }
      }
    }

    // 3. Large Mechanical Door Release Push-Bar at bottom of control panel
    let qPush = [
      quadUV(qCtrl, 0.10, 0.15),
      quadUV(qCtrl, 0.90, 0.15),
      quadUV(qCtrl, 0.90, 0.05),
      quadUV(qCtrl, 0.10, 0.05)
    ];
    washPoly(qPush, PAL.steel4, 220);
    drawLine2D(qPush[3], qPush[2], "rotring", PAL.inkDark, 0.38, 0);
    drawLine2D(qPush[0], qPush[1], "cpencil", PAL.steel1, 0.38, 0);
    strokePoly(qPush, true, "rotring", PAL.inkDark, 0.30, 0);
  }

  // Crisp ruled technical pen frame of chassis
  strokePoly(qChassis, true, "rotring", PAL.inkDark, 0.50, 1.5);
}

function drawLedReadout(qLed, timerStr) {
  // Subtle warm glow inside LED box
  let qInner = [
    quadUV(qLed, 0.18, 0.82),
    quadUV(qLed, 0.86, 0.82),
    quadUV(qLed, 0.86, 0.18),
    quadUV(qLed, 0.18, 0.18)
  ];
  washPoly(qInner, PAL.glowOrange, 65);

  // Small emerald status LED dot on left
  let pDot = quadUV(qLed, 0.12, 0.52);
  drawLine2D(
    { x: pDot.x - 1.5, y: pDot.y },
    { x: pDot.x + 1.5, y: pDot.y },
    "pen",
    PAL.ledGreen,
    0.65,
    0
  );

  // Draw 4 stylized 7-segment characters + colon
  for (let d = 0; d < 4; d++) {
    let u0 = 0.24 + d * 0.15 + (d >= 2 ? 0.05 : 0);
    let u1 = u0 + 0.10;
    let v0 = 0.25;
    let v1 = 0.76;
    let vm = 0.50;

    let tl = quadUV(qLed, u0, v1);
    let tr = quadUV(qLed, u1, v1);
    let ml = quadUV(qLed, u0, vm);
    let mr = quadUV(qLed, u1, vm);
    let bl = quadUV(qLed, u0, v0);
    let br = quadUV(qLed, u1, v0);

    let ch = timerStr.charAt(d >= 2 ? d + 1 : d);
    // Top bar
    if (ch !== "1" && ch !== "4") drawLine2D(tl, tr, "pen", PAL.ledAmber, 0.36, 0);
    // Mid bar
    if (ch !== "0" && ch !== "1" && ch !== "7") drawLine2D(ml, mr, "pen", PAL.ledAmber, 0.34, 0);
    // Bot bar
    if (ch !== "1" && ch !== "4" && ch !== "7") drawLine2D(bl, br, "pen", PAL.ledAmber, 0.36, 0);
    // Right verticals
    if (ch !== "2") drawLine2D(mr, br, "pen", PAL.ledBright, 0.36, 0);
    if (ch !== "5" && ch !== "6") drawLine2D(tr, mr, "pen", PAL.ledBright, 0.36, 0);
    // Left verticals
    if (ch === "0" || ch === "4" || ch === "5" || ch === "6" || ch === "8" || ch === "9") {
      drawLine2D(tl, ml, "pen", PAL.ledAmber, 0.34, 0);
    }
    if (ch === "0" || ch === "2" || ch === "6" || ch === "8") {
      drawLine2D(ml, bl, "pen", PAL.ledAmber, 0.34, 0);
    }
  }

  // Colon dots
  let cTop = quadUV(qLed, 0.54, 0.62);
  let cBot = quadUV(qLed, 0.54, 0.36);
  drawLine2D(cTop, { x: cTop.x + 1, y: cTop.y }, "pen", PAL.ledBright, 0.45, 0);
  drawLine2D(cBot, { x: cBot.x + 1, y: cBot.y }, "pen", PAL.ledBright, 0.45, 0);
}

function drawProtrudingDial(cx, cy, zBase, rad, isDead) {
  let zTip = zBase + 0.08;
  let steps = 14;
  let ptsBase = [];
  let ptsTip = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let dx = Math.cos(a) * rad;
    let dy = Math.sin(a) * rad;
    ptsBase.push(proj(cx + dx, cy + dy, zBase));
    ptsTip.push(proj(cx + dx * 0.88, cy + dy * 0.88, zTip));
  }
  washPoly(ptsBase, PAL.steel6, 225);
  strokePoly(ptsBase, true, "rotring", PAL.inkDark, 0.28, 0);

  washPoly(ptsTip, PAL.steel2, 235);
  strokePoly(ptsTip, true, "rotring", PAL.inkDark, 0.32, 0);

  // Indicator notch on dial face
  let pC = proj(cx, cy, zTip);
  let pEdge = proj(cx + rad * 0.55, cy + rad * 0.55, zTip);
  drawLine2D(pC, pEdge, "rotring", isDead ? PAL.inkDark : PAL.glowOrange, 0.38, 0);
}

// ---------------------------------------------------------------------------
// 5. Closed Door, Brushed Frame, Protruding Handle & Glowing Window Vignettes
// ---------------------------------------------------------------------------
function drawClosedDoorAndWindow(cap, xSplit) {
  let { x0, x1, y0, y1, zFront, isDead, r, c } = cap;

  let zDoor = zFront + 0.075;
  let dx0 = x0 + 0.02;
  let dx1 = xSplit - 0.02;
  let dy0 = y0 + 0.02;
  let dy1 = y1 - 0.02;

  // 1. Door underside thickness lip (visible from worm's-eye view!)
  if (dy0 > camPos.y) {
    let qDoorBot = [
      proj(dx0, dy0, zDoor),
      proj(dx1, dy0, zDoor),
      proj(dx1, dy0, zFront),
      proj(dx0, dy0, zFront)
    ];
    washPoly(qDoorBot, PAL.steel6, 235);
    strokePoly(qDoorBot, true, "rotring", PAL.inkDark, 0.34, 0);
  }

  // 2. Door side thickness lip
  if (dx0 > camPos.x) {
    let qDoorLeft = [
      proj(dx0, dy1, zFront),
      proj(dx0, dy1, zDoor),
      proj(dx0, dy0, zDoor),
      proj(dx0, dy0, zFront)
    ];
    washPoly(qDoorLeft, PAL.steel5, 235);
    strokePoly(qDoorLeft, true, "rotring", PAL.inkDark, 0.34, 0);
  } else if (dx1 < camPos.x) {
    let qDoorRight = [
      proj(dx1, dy1, zDoor),
      proj(dx1, dy1, zFront),
      proj(dx1, dy0, zFront),
      proj(dx1, dy0, zDoor)
    ];
    washPoly(qDoorRight, PAL.steel5, 235);
    strokePoly(qDoorRight, true, "rotring", PAL.inkDark, 0.34, 0);
  }

  // 3. Door Front Face Quad at z = zDoor
  let qDoor = [
    proj(dx0, dy1, zDoor),
    proj(dx1, dy1, zDoor),
    proj(dx1, dy0, zDoor),
    proj(dx0, dy0, zDoor)
  ];
  washPoly(qDoor, PAL.steel3, 240);

  // Cool grey marker brushed-steel layering on door frame
  markerBandQuad(qDoor, "h", PAL.steel2, 0.65, 5, 0.02, 0.98, 0.82, 0.97);
  markerBandQuad(qDoor, "h", PAL.steel4, 0.65, 5, 0.02, 0.98, 0.03, 0.18);
  markerBandQuad(qDoor, "v", PAL.steel2, 0.55, 3, 0.02, 0.14, 0.15, 0.85);
  markerBandQuad(qDoor, "v", PAL.steel4, 0.55, 3, 0.82, 0.97, 0.15, 0.85);

  // Diagonal metallic sheen across door frame
  markerBandQuad(qDoor, "d", PAL.steel1, 0.50, 3, 0.05, 0.95, 0.1, 0.9);
  hatchPoly(qDoor, "2H", PAL.steel5, 0.22, 6, 4, { rand: 0.02 });

  // Warm amber bounce light on door bevels for lit units
  if (!isDead) {
    markerBandQuad(qDoor, "h", PAL.warmSteel2, 0.45, 2, 0.12, 0.82, 0.14, 0.19);
    markerBandQuad(qDoor, "v", PAL.warmSteel2, 0.45, 2, 0.80, 0.85, 0.18, 0.82);
  }

  // 4. Window Opening Coordinates (xW0..xW1, yW0..yW1)
  let xW0 = dx0 + (dx1 - dx0) * 0.13;
  let xW1 = dx0 + (dx1 - dx0) * 0.81; // Leave space on right of door for tubular handle
  let yW0 = dy0 + (dy1 - dy0) * 0.17;
  let yW1 = dy0 + (dy1 - dy0) * 0.83;

  let qWinOuter = [
    proj(xW0 - 0.03, yW1 + 0.03, zDoor),
    proj(xW1 + 0.03, yW1 + 0.03, zDoor),
    proj(xW1 + 0.03, yW0 - 0.03, zDoor),
    proj(xW0 - 0.03, yW0 - 0.03, zDoor)
  ];
  // Dark rubber/metal bezel around window
  washPoly(qWinOuter, PAL.steel8, 240);

  let qWin = [
    proj(xW0, yW1, zDoor),
    proj(xW1, yW1, zDoor),
    proj(xW1, yW0, zDoor),
    proj(xW0, yW0, zDoor)
  ];

  // 5. Render the Window Interior & Hyperreal Vignette!
  if (isDead) {
    drawDeadWindowInterior(cap, qWin, xW0, xW1, yW0, yW1, zDoor);
  } else {
    drawLitWindowInterior(cap, qWin, xW0, xW1, yW0, yW1, zDoor, false);
  }

  // Window bezel crisp technical pen rules & bottom specular catchlight
  strokePoly(qWinOuter, true, "rotring", PAL.inkDark, 0.35, 0);
  strokePoly(qWin, true, "rotring", PAL.inkDark, 0.46, 0);
  drawLine2D(
    qWinOuter[3],
    qWinOuter[2],
    "cpencil",
    isDead ? PAL.steel2 : PAL.glowGold,
    0.55,
    0
  );

  // 6. Protruding Tubular Stainless-Steel Door Handle on right side of door
  let xHandle = dx0 + (dx1 - dx0) * 0.90;
  let yH0 = dy0 + (dy1 - dy0) * 0.14;
  let yH1 = dy0 + (dy1 - dy0) * 0.86;
  drawTubularDoorHandle(xHandle, yH0, yH1, zDoor, zDoor + 0.12, !isDead);

  // Outer door frame ruled outline
  strokePoly(qDoor, true, "rotring", PAL.inkDark, 0.48, 1.2);
}

function drawTubularDoorHandle(xh, yh0, yh1, zBase, zBar, isLit) {
  let hw = 0.038;
  // Top and bottom mounting standoffs
  for (let yh of [yh0 + 0.06, yh1 - 0.06]) {
    let qPost = [
      proj(xh - hw, yh + 0.04, zBar),
      proj(xh + hw, yh + 0.04, zBar),
      proj(xh + hw, yh - 0.04, zBase),
      proj(xh - hw, yh - 0.04, zBase)
    ];
    washPoly(qPost, PAL.steel6, 235);
    strokePoly(qPost, true, "rotring", PAL.inkDark, 0.30, 0);
  }

  // Vertical tubular bar
  let qBar = [
    proj(xh - hw, yh1, zBar),
    proj(xh + hw, yh1, zBar),
    proj(xh + hw, yh0, zBar),
    proj(xh - hw, yh0, zBar)
  ];
  washPoly(qBar, PAL.steel2, 245);
  // Warm amber reflection on left side of handle facing the window
  if (isLit) {
    drawLine2D(qBar[0], qBar[3], "cpencil", PAL.glowGold, 0.55, 0);
  }
  // Bright chrome highlight down center of handle
  drawLine2D(
    lerpPt(qBar[0], qBar[1], 0.55),
    lerpPt(qBar[3], qBar[2], 0.55),
    "cpencil",
    PAL.glowWhite,
    0.48,
    0
  );
  strokePoly(qBar, true, "rotring", PAL.inkDark, 0.36, 0);
}

// ---------------------------------------------------------------------------
// 6. The Open Door Hero Unit (c = 0, r = 2)
// ---------------------------------------------------------------------------
function drawOpenDoorHeroUnit(cap, xSplit) {
  let { x0, x1, y0, y1, zFront } = cap;

  let dx0 = x0 + 0.02;
  let dx1 = xSplit - 0.02;
  let dy0 = y0 + 0.02;
  let dy1 = y1 - 0.02;

  // 1. Exposed Stainless Front Cavity Flange at z = zFront
  let qFlange = [
    proj(dx0, dy1, zFront),
    proj(dx1, dy1, zFront),
    proj(dx1, dy0, zFront),
    proj(dx0, dy0, zFront)
  ];
  washPoly(qFlange, PAL.steel3, 240);
  markerBandQuad(qFlange, "h", PAL.warmSteel2, 0.65, 4, 0.02, 0.98, 0.03, 0.16);
  markerBandQuad(qFlange, "h", PAL.warmSteel2, 0.65, 4, 0.02, 0.98, 0.84, 0.97);
  markerBandQuad(qFlange, "v", PAL.warmSteel3, 0.65, 3, 0.82, 0.97, 0.12, 0.88);
  strokePoly(qFlange, true, "rotring", PAL.inkDark, 0.45, 0);

  // Two rectangular safety interlock latch slots on the right cavity flange
  for (let vf of [0.30, 0.70]) {
    let qSlot = [
      quadUV(qFlange, 0.88, vf + 0.045),
      quadUV(qFlange, 0.94, vf + 0.045),
      quadUV(qFlange, 0.94, vf - 0.045),
      quadUV(qFlange, 0.88, vf - 0.045)
    ];
    washPoly(qSlot, PAL.inkDark, 245);
    strokePoly(qSlot, true, "rotring", PAL.inkDark, 0.30, 0);
  }

  // 2. Exposed Oven Cavity Opening (wider & unobstructed!)
  let xW0 = dx0 + (dx1 - dx0) * 0.10;
  let xW1 = dx0 + (dx1 - dx0) * 0.84;
  let yW0 = dy0 + (dy1 - dy0) * 0.14;
  let yW1 = dy0 + (dy1 - dy0) * 0.86;

  let qCavity = [
    proj(xW0, yW1, zFront),
    proj(xW1, yW1, zFront),
    proj(xW1, yW0, zFront),
    proj(xW0, yW0, zFront)
  ];

  // Warm radiant halo spilling out of the open oven cavity!
  let qHalo = [
    proj(xW0 - 0.18, yW1 + 0.18, zFront + 0.05),
    proj(xW1 + 0.22, yW1 + 0.18, zFront + 0.05),
    proj(xW1 + 0.22, yW0 - 0.18, zFront + 0.05),
    proj(xW0 - 0.18, yW0 - 0.18, zFront + 0.05)
  ];
  watercolorPoly(qHalo, PAL.glowAmber, 52, 0.28, 0.3);

  // Draw the brilliantly lit open cavity & hero steaming noodles vignette!
  drawLitWindowInterior(cap, qCavity, xW0, xW1, yW0, yW1, zFront, true);

  // Rounded inner cavity rim bevel in glowing gold & technical pen
  strokePoly(qCavity, true, "cpencil", PAL.glowPale, 0.75, 0);
  strokePoly(qCavity, true, "rotring", PAL.inkDark, 0.52, 0);

  // 3. Construct the 3D Swung-Open Door (hinged at x = dx0, z = zFront, swung outward 66 degrees!)
  let doorW = dx1 - dx0;
  let doorThick = 0.085;
  let openDeg = 66;
  let rad = (openDeg * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);

  // Helper to map local door coordinates (u in [0, doorW], y, t in [0, doorThick]) to 3D world
  function doorPt(u, y, t) {
    return proj(
      dx0 + u * ca - t * sa,
      y,
      zFront + u * sa + t * ca
    );
  }

  // Bottom edge thickness of swung door (visible from worm's-eye view!)
  let qSwungBot = [
    doorPt(0, dy0, 0),
    doorPt(doorW, dy0, 0),
    doorPt(doorW, dy0, doorThick),
    doorPt(0, dy0, doorThick)
  ];
  washPoly(qSwungBot, PAL.steel6, 240);
  strokePoly(qSwungBot, true, "rotring", PAL.inkDark, 0.38, 0);

  // Outer edge thickness of swung door (at u = doorW)
  let qSwungEdge = [
    doorPt(doorW, dy1, 0),
    doorPt(doorW, dy1, doorThick),
    doorPt(doorW, dy0, doorThick),
    doorPt(doorW, dy0, 0)
  ];
  washPoly(qSwungEdge, PAL.steel4, 240);
  strokePoly(qSwungEdge, true, "rotring", PAL.inkDark, 0.40, 0);

  // Inner Face of Swung Door (t = 0, facing right/toward viewer!)
  let qSwungInner = [
    doorPt(0, dy1, 0),
    doorPt(doorW, dy1, 0),
    doorPt(doorW, dy0, 0),
    doorPt(0, dy0, 0)
  ];
  washPoly(qSwungInner, PAL.steel4, 245);
  markerBandQuad(qSwungInner, "v", PAL.warmSteel2, 0.65, 5, 0.05, 0.95, 0.04, 0.96);

  // Black choke-seal gasket frame on inner face of open door
  let qChoke = [
    doorPt(doorW * 0.08, dy0 + (dy1 - dy0) * 0.92, 0),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.92, 0),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.08, 0),
    doorPt(doorW * 0.08, dy0 + (dy1 - dy0) * 0.08, 0)
  ];
  washPoly(qChoke, PAL.steel8, 240);
  strokePoly(qChoke, true, "rotring", PAL.inkDark, 0.35, 0);

  // Inner Glass Shield of Open Door (reflecting warm amber glow from the open cavity!)
  let qInnerGlass = [
    doorPt(doorW * 0.15, dy0 + (dy1 - dy0) * 0.83, 0),
    doorPt(doorW * 0.81, dy0 + (dy1 - dy0) * 0.83, 0),
    doorPt(doorW * 0.81, dy0 + (dy1 - dy0) * 0.17, 0),
    doorPt(doorW * 0.15, dy0 + (dy1 - dy0) * 0.17, 0)
  ];
  washPoly(qInnerGlass, "#2a1e14", 235);
  // Warm amber reflection streaks on the angled open door glass
  let qRefl = [
    quadUV(qInnerGlass, 0.15, 0.88),
    quadUV(qInnerGlass, 0.75, 0.88),
    quadUV(qInnerGlass, 0.55, 0.15),
    quadUV(qInnerGlass, 0.08, 0.15)
  ];
  washPoly(qRefl, PAL.glowAmber, 110);
  hatchPoly(qInnerGlass, "rotring", PAL.inkDark, 0.20, 7, 72, { rand: 0.01 });
  drawLine2D(
    quadUV(qInnerGlass, 0.20, 0.12),
    quadUV(qInnerGlass, 0.82, 0.88),
    "cpencil",
    PAL.glowPale,
    0.55,
    0
  );
  strokePoly(qInnerGlass, true, "rotring", PAL.inkDark, 0.38, 0);

  // Two Hooked Metal Latch Prongs protruding inward from the swinging door edge!
  for (let vf of [0.30, 0.70]) {
    let yL = dy0 + (dy1 - dy0) * vf;
    let pBase1 = doorPt(doorW * 0.91, yL + 0.035, 0);
    let pBase2 = doorPt(doorW * 0.91, yL - 0.035, 0);
    let pTip1 = doorPt(doorW * 0.91, yL + 0.03, -0.16);
    let pTip2 = doorPt(doorW * 0.91, yL - 0.045, -0.14);
    let qProng = [pBase1, pTip1, pTip2, pBase2];
    washPoly(qProng, PAL.warmSteel1, 245);
    strokePoly(qProng, true, "rotring", PAL.inkDark, 0.36, 0);
  }

  // Protruding exterior handle glimpsed on the outside of the swung door
  let qExtHandle = [
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.84, doorThick + 0.10),
    doorPt(doorW * 0.93, dy0 + (dy1 - dy0) * 0.84, doorThick + 0.10),
    doorPt(doorW * 0.93, dy0 + (dy1 - dy0) * 0.16, doorThick + 0.10),
    doorPt(doorW * 0.88, dy0 + (dy1 - dy0) * 0.16, doorThick + 0.10)
  ];
  washPoly(qExtHandle, PAL.steel2, 235);
  strokePoly(qExtHandle, true, "rotring", PAL.inkDark, 0.35, 0);

  // Heavy profile technical pen outline around the swung open door
  strokePoly(qSwungInner, true, "rotring", PAL.inkDark, 0.58, 1.5);
}

// ---------------------------------------------------------------------------
// 7. Lit Window Interior, 3D Cavity & Hyperreal Amber Pencil Vignettes
// ---------------------------------------------------------------------------
function drawLitWindowInterior(cap, qWin, xW0, xW1, yW0, yW1, zWin, isOpenCavity) {
  let { c, r, vignette, turnAngle } = cap;
  let zCavityBack = zWin - 0.88;

  // 1. Base incandescent amber/gold washes inside the window
  washPoly(qWin, PAL.glowRust, 240);

  let qMidGlow = [
    quadUV(qWin, 0.06, 0.96),
    quadUV(qWin, 0.96, 0.96),
    quadUV(qWin, 0.94, 0.10),
    quadUV(qWin, 0.08, 0.10)
  ];
  washPoly(qMidGlow, PAL.glowAmber, 210);

  // Bright golden hotspot from the interior oven bulb (top-right of cavity)
  let qHotspot = [
    quadUV(qWin, 0.25, 0.98),
    quadUV(qWin, 0.98, 0.98),
    quadUV(qWin, 0.96, 0.28),
    quadUV(qWin, 0.18, 0.22)
  ];
  washPoly(qHotspot, PAL.glowGold, 195);

  let qBulbCore = [
    quadUV(qWin, 0.58, 0.98),
    quadUV(qWin, 0.96, 0.98),
    quadUV(qWin, 0.94, 0.58),
    quadUV(qWin, 0.52, 0.62)
  ];
  washPoly(qBulbCore, PAL.glowPale, isOpenCavity ? 235 : 195);

  // 2. 3D Interior Cavity Walls (Ceiling, Back Wall, Side Wall, Floor) clipped to qWin!
  let qCeil3D = [
    proj(xW0 - 0.06, yW1 + 0.04, zWin),
    proj(xW1 + 0.06, yW1 + 0.04, zWin),
    proj(xW1 + 0.06, yW1 + 0.04, zCavityBack),
    proj(xW0 - 0.06, yW1 + 0.04, zCavityBack)
  ];
  let qBack3D = [
    proj(xW0 - 0.06, yW1 + 0.04, zCavityBack),
    proj(xW1 + 0.06, yW1 + 0.04, zCavityBack),
    proj(xW1 + 0.06, yW0 - 0.08, zCavityBack),
    proj(xW0 - 0.06, yW0 - 0.08, zCavityBack)
  ];

  // Shade interior ceiling & back wall with warm amber/umber colored pencil
  washPolyClipped(qCeil3D, qWin, PAL.glowOrange, 95);
  // Cavity corner edges in warm umber pencil & technical pen
  drawLineClipped(qBack3D[0], qBack3D[1], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qBack3D[0], qBack3D[3], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qBack3D[1], qBack3D[2], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qCeil3D[0], qCeil3D[3], qWin, "cpencil", PAL.glowUmber, 0.42);
  drawLineClipped(qCeil3D[1], qCeil3D[2], qWin, "cpencil", PAL.glowUmber, 0.42);

  // Back wall perforated waveguide cover & amber pencil shading
  let stepsBack = r <= 4 ? 7 : 4;
  for (let i = 0; i < stepsBack; i++) {
    let v = 0.15 + (i / stepsBack) * 0.72;
    let p1 = quadUV(qBack3D, 0.08, v);
    let p2 = quadUV(qBack3D, 0.92, v);
    drawLineClipped(p1, p2, qWin, "cpencil", PAL.glowOrange, 0.35);
  }

  // Incandescent oven bulb in upper right of ceiling
  let pBulb = proj(xW1 - 0.18, yW1 - 0.04, zWin - 0.28);
  let bulbRays = 6;
  for (let i = 0; i < bulbRays; i++) {
    let a = (i / bulbRays) * Math.PI * 2;
    let pRay = { x: pBulb.x + Math.cos(a) * 14, y: pBulb.y + Math.sin(a) * 10 };
    drawLineClipped(pBulb, pRay, qWin, "cpencil", PAL.glowWhite, 0.55);
  }

  // 3. Rotating Glass Turntable at bottom of cavity
  let cx = (xW0 + xW1) * 0.50;
  let cz = zWin - 0.44;
  let yTurn = yW0 + (yW1 - yW0) * 0.12;
  let rTurn = (xW1 - xW0) * 0.43;

  // Cast shadow under glass turntable
  let turnShadow = ellipse3D_XZ(cx, yTurn - 0.04, cz, rTurn * 0.92, rTurn * 0.72, 20);
  washPolyClipped(turnShadow, qWin, PAL.glowUmber, 115);

  // Glass turntable body & raised rim
  let turnBot = ellipse3D_XZ(cx, yTurn, cz, rTurn, rTurn * 0.78, 24);
  let turnTop = ellipse3D_XZ(cx, yTurn + 0.03, cz, rTurn, rTurn * 0.78, 24);
  let turnHub = ellipse3D_XZ(cx, yTurn + 0.03, cz, rTurn * 0.22, rTurn * 0.17, 14);

  washPolyClipped(turnTop, qWin, PAL.glowGold, 110);
  drawSplineClipped(turnBot.concat([turnBot[0]]), qWin, "cpencil", PAL.glowUmber, 0.42, 0.4);
  drawSplineClipped(turnTop.concat([turnTop[0]]), qWin, "cpencil", PAL.glowWhite, 0.52, 0.4);
  drawSplineClipped(turnHub.concat([turnHub[0]]), qWin, "cpencil", PAL.glowRust, 0.35, 0.4);

  // 4. Draw the Specific Hyperreal Vignette in Warm Amber Pencil!
  let yPlateBase = yTurn + 0.035;
  if (vignette === "noodles") {
    drawVignetteNoodles(cx, yPlateBase, cz, rTurn, turnAngle, qWin, r);
  } else if (vignette === "mug") {
    drawVignetteMug(cx, yPlateBase, cz, rTurn, turnAngle, qWin, r);
  } else if (vignette === "butter") {
    drawVignetteButter(cx, yPlateBase, cz, rTurn, turnAngle, qWin, r);
  } else if (vignette === "dome") {
    drawVignetteDome(cx, yPlateBase, cz, rTurn, turnAngle, qWin, r);
  } else {
    drawVignetteSoup(cx, yPlateBase, cz, rTurn, turnAngle, qWin, r);
  }

  // 5. Faraday Shield Mesh & Window Glass Reflections (only if closed door!)
  if (!isOpenCavity) {
    // Subtle dark perimeter frame of the Faraday screen inside window
    let qScreenBorder = [
      quadUV(qWin, 0.06, 0.92),
      quadUV(qWin, 0.94, 0.92),
      quadUV(qWin, 0.94, 0.08),
      quadUV(qWin, 0.06, 0.08)
    ];
    strokePoly(qScreenBorder, true, "rotring", PAL.glowUmber, 0.24, 0);

    // Fine Faraday mesh lines near top and bottom margins of window
    if (r <= 5) {
      for (let i = 1; i <= 3; i++) {
        let vt = 0.86 + i * 0.032;
        let vb = 0.14 - i * 0.032;
        drawLine2D(quadUV(qWin, 0.04, vt), quadUV(qWin, 0.96, vt), "rotring", PAL.glowDeep, 0.18, 0);
        drawLine2D(quadUV(qWin, 0.04, vb), quadUV(qWin, 0.96, vb), "rotring", PAL.glowDeep, 0.18, 0);
      }
    }

    // Crisp diagonal glass reflection streaks
    drawLine2D(
      quadUV(qWin, 0.12, 0.14),
      quadUV(qWin, 0.42, 0.86),
      "cpencil",
      PAL.glowWhite,
      0.52,
      0
    );
    drawLine2D(
      quadUV(qWin, 0.18, 0.14),
      quadUV(qWin, 0.46, 0.82),
      "cpencil",
      PAL.glowPale,
      0.35,
      0
    );
  }
}

// ---------------------------------------------------------------------------
// Vignette 1: Steaming Bowl of Noodles with Chopsticks (Warm Amber Pencil)
// ---------------------------------------------------------------------------
function drawVignetteNoodles(cx, yBase, cz, rTurn, turnAngle, qWin, rowIdx) {
  let rFoot = rTurn * 0.34;
  let rBelly = rTurn * 0.56;
  let rRim = rTurn * 0.66;
  let hBowl = 0.40;

  // Cast shadow on turntable
  let shadowEll = ellipse3D_XZ(cx - 0.04, yBase, cz + 0.03, rBelly * 1.05, rBelly * 0.82, 18);
  washPolyClipped(shadowEll, qWin, PAL.glowDeep, 145);

  // Bowl silhouette built from foot, belly, and rim ellipses
  let ellFoot = ellipse3D_XZ(cx, yBase + 0.02, cz, rFoot, rFoot * 0.78, 18);
  let ellBelly = ellipse3D_XZ(cx, yBase + hBowl * 0.48, cz, rBelly, rBelly * 0.78, 20);
  let ellStripe = ellipse3D_XZ(cx, yBase + hBowl * 0.82, cz, rRim * 0.95, rRim * 0.74, 20);
  let ellRim = ellipse3D_XZ(cx, yBase + hBowl, cz, rRim, rRim * 0.78, 22);

  // Build bowl body hull polygon from front half of foot to full rim
  let bowlHull = [];
  for (let i = 0; i <= 11; i++) bowlHull.push(ellRim[i]);
  for (let i = 10; i >= 0; i--) bowlHull.push(ellFoot[i]);
  washPolyClipped(bowlHull, qWin, PAL.glowOrange, 225);

  // Shaded lower belly of bowl in deep burnt umber pencil
  let bowlShadowHull = [];
  for (let i = 0; i <= 7; i++) bowlShadowHull.push(ellBelly[i]);
  for (let i = 7; i >= 0; i--) bowlShadowHull.push(ellFoot[i]);
  washPolyClipped(bowlShadowHull, qWin, PAL.glowUmber, 190);

  // Bowl interior opening
  washPolyClipped(ellRim, qWin, PAL.glowAmber, 225);

  // Tangled Mound of Golden Noodles heaped in and above the bowl!
  let nStrands = rowIdx <= 3 ? 24 : 13;
  for (let s = 0; s < nStrands; s++) {
    let seedA = (s * 47 + turnAngle) * 0.01745;
    let strandPts = [];
    let segs = 5;
    for (let k = 0; k <= segs; k++) {
      let t = k / segs;
      let ang = seedA + t * 2.8 + Math.sin(s * 1.7 + k) * 0.7;
      let rad = rRim * (0.15 + 0.68 * Math.sin(t * Math.PI) * ((s % 3) * 0.22 + 0.45));
      let nx = cx + Math.cos(ang) * rad;
      let nz = cz + Math.sin(ang) * rad * 0.75;
      // Mound rises in center
      let ny = yBase + hBowl + Math.sin(t * Math.PI) * 0.16 * (1 - (rad / rRim) * 0.5);
      strandPts.push(proj(nx, ny, nz));
    }
    let colChoice =
      s % 4 === 0
        ? PAL.glowWhite
        : s % 4 === 1
        ? PAL.glowPale
        : s % 4 === 2
        ? PAL.glowGold
        : PAL.glowRust;
    let wChoice = s % 4 === 0 ? 0.46 : 0.38;
    drawSplineClipped(strandPts, qWin, "cpencil", colChoice, wChoice, 0.65);
  }

  // Rim decorative stripe & bowl contour lines in warm pencil + rotring pen
  drawSplineClipped(ellFoot.slice(0, 12), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
  drawSplineClipped(ellBelly.slice(0, 13), qWin, "cpencil", PAL.glowPale, 0.44, 0.4);
  drawSplineClipped(ellStripe.slice(0, 13), qWin, "rotring", PAL.glowDeep, 0.34, 0.4);
  drawSplineClipped(ellRim.concat([ellRim[0]]), qWin, "rotring", PAL.glowDeep, 0.40, 0.4);
  // Specular highlight along front bowl rim
  drawSplineClipped(ellRim.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.62, 0.4);

  // Pair of Wooden Chopsticks resting diagonally across the bowl rim!
  let csRad = ((turnAngle * 0.4 + 28) * Math.PI) / 180;
  let dx = Math.cos(csRad);
  let dz = Math.sin(csRad);
  for (let stick = 0; stick < 2; stick++) {
    let off = (stick - 0.5) * 0.07;
    let pTip = proj(
      cx - dx * rRim * 0.75 + off,
      yBase + hBowl + 0.05,
      cz - dz * rRim * 0.55
    );
    let pTail = proj(
      cx + dx * rRim * 1.18 + off * 1.8,
      yBase + hBowl + 0.24,
      cz + dz * rRim * 0.85
    );
    drawLineClipped(pTip, pTail, qWin, "rotring", PAL.glowDeep, 0.48);
    drawLineClipped(
      { x: pTip.x, y: pTip.y - 1.2 },
      { x: pTail.x, y: pTail.y - 1.5 },
      qWin,
      "cpencil",
      PAL.glowWhite,
      0.42
    );
  }

  // Curling wisps of amber steam rising from the hot noodles
  drawSteamWisps(cx, yBase + hBowl + 0.14, cz, rRim * 0.5, 0.42, qWin, 4);
}

// ---------------------------------------------------------------------------
// Vignette 2: Ceramic Mug on Saucer with Spoon & Steam (Warm Amber Pencil)
// ---------------------------------------------------------------------------
function drawVignetteMug(cx, yBase, cz, rTurn, turnAngle, qWin, rowIdx) {
  let rSaucer = rTurn * 0.56;
  let rMug = rTurn * 0.34;
  let hMug = 0.52;

  // Cast shadow on turntable
  let shadowEll = ellipse3D_XZ(cx - 0.05, yBase, cz + 0.03, rSaucer * 1.05, rSaucer * 0.80, 18);
  washPolyClipped(shadowEll, qWin, PAL.glowDeep, 145);

  // Porcelain Saucer
  let saucerBot = ellipse3D_XZ(cx, yBase + 0.02, cz, rSaucer * 0.72, rSaucer * 0.56, 18);
  let saucerRim = ellipse3D_XZ(cx, yBase + 0.07, cz, rSaucer, rSaucer * 0.78, 22);
  washPolyClipped(saucerRim, qWin, PAL.glowGold, 215);
  drawSplineClipped(saucerBot.slice(0, 12), qWin, "rotring", PAL.glowDeep, 0.32, 0.4);
  drawSplineClipped(saucerRim.concat([saucerRim[0]]), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
  drawSplineClipped(saucerRim.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.55, 0.4);

  // Cylindrical Ceramic Mug Body
  let mugBot = ellipse3D_XZ(cx, yBase + 0.06, cz, rMug, rMug * 0.78, 20);
  let mugMid = ellipse3D_XZ(cx, yBase + hMug * 0.52, cz, rMug, rMug * 0.78, 20);
  let mugTop = ellipse3D_XZ(cx, yBase + hMug, cz, rMug * 1.03, rMug * 0.80, 20);
  let mugLiquid = ellipse3D_XZ(cx, yBase + hMug - 0.04, cz, rMug * 0.92, rMug * 0.72, 18);

  // Mug cylinder silhouette polygon
  let mugHull = [];
  for (let i = 0; i <= 10; i++) mugHull.push(mugTop[i]);
  for (let i = 10; i >= 0; i--) mugHull.push(mugBot[i]);
  washPolyClipped(mugHull, qWin, PAL.glowAmber, 235);

  // Shaded left side of mug cylinder (core shadow in burnt umber/rust pencil)
  let mugShadow = [];
  for (let i = 5; i <= 10; i++) mugShadow.push(mugTop[i]);
  for (let i = 10; i >= 5; i--) mugShadow.push(mugBot[i]);
  washPolyClipped(mugShadow, qWin, PAL.glowUmber, 195);

  // Bright vertical specular highlight strip on right side of mug facing oven lamp
  for (let idx of [2, 3]) {
    drawLineClipped(mugBot[idx], mugTop[idx], qWin, "cpencil", PAL.glowWhite, 0.65);
  }
  for (let idx of [4, 5]) {
    drawLineClipped(mugBot[idx], mugTop[idx], qWin, "cpencil", PAL.glowGold, 0.48);
  }

  // Curved D-shaped Mug Handle on side
  let hSide = (turnAngle % 180) < 90 ? 1 : -1;
  let handlePtsOuter = [
    proj(cx + hSide * rMug * 0.95, yBase + hMug * 0.82, cz),
    proj(cx + hSide * rMug * 1.58, yBase + hMug * 0.76, cz),
    proj(cx + hSide * rMug * 1.62, yBase + hMug * 0.34, cz),
    proj(cx + hSide * rMug * 0.95, yBase + hMug * 0.24, cz)
  ];
  let handlePtsInner = [
    proj(cx + hSide * rMug * 0.98, yBase + hMug * 0.72, cz),
    proj(cx + hSide * rMug * 1.38, yBase + hMug * 0.66, cz),
    proj(cx + hSide * rMug * 1.40, yBase + hMug * 0.40, cz),
    proj(cx + hSide * rMug * 0.98, yBase + hMug * 0.34, cz)
  ];
  drawSplineClipped(handlePtsOuter, qWin, "cpencil", PAL.glowWhite, 0.62, 0.55);
  drawSplineClipped(handlePtsOuter, qWin, "rotring", PAL.glowDeep, 0.42, 0.55);
  drawSplineClipped(handlePtsInner, qWin, "rotring", PAL.glowDeep, 0.36, 0.55);

  // Mug Rim & Dark Hot Coffee/Tea Meniscus inside
  washPolyClipped(mugTop, qWin, PAL.glowPale, 225);
  washPolyClipped(mugLiquid, qWin, PAL.glowDeep, 225);
  drawSplineClipped(mugLiquid.slice(1, 9), qWin, "cpencil", PAL.glowGold, 0.45, 0.4);
  drawSplineClipped(mugTop.concat([mugTop[0]]), qWin, "rotring", PAL.glowDeep, 0.40, 0.4);
  drawSplineClipped(mugBot.slice(0, 11), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);
  drawSplineClipped(mugMid.slice(1, 9), qWin, "cpencil", PAL.glowPale, 0.32, 0.4);

  // Small teaspoon handle sticking out of the mug
  let pSpoonIn = proj(cx - hSide * rMug * 0.35, yBase + hMug - 0.02, cz);
  let pSpoonOut = proj(cx - hSide * rMug * 0.85, yBase + hMug + 0.16, cz + 0.06);
  drawLineClipped(pSpoonIn, pSpoonOut, qWin, "rotring", PAL.glowDeep, 0.44);
  drawLineClipped(
    { x: pSpoonIn.x, y: pSpoonIn.y - 1 },
    { x: pSpoonOut.x, y: pSpoonOut.y - 1.2 },
    qWin,
    "cpencil",
    PAL.glowWhite,
    0.45
  );

  // Rising steam tendrils above mug
  drawSteamWisps(cx, yBase + hMug + 0.08, cz, rMug * 0.55, 0.36, qWin, 3);
}

// ---------------------------------------------------------------------------
// Vignette 3: Melting Butter Dish (Slumping Golden Stick & Liquid Amber Pool)
// ---------------------------------------------------------------------------
function drawVignetteButter(cx, yBase, cz, rTurn, turnAngle, qWin, rowIdx) {
  let ang = ((turnAngle * 0.5 + 18) * Math.PI) / 180;
  let ca = Math.cos(ang);
  let sa = Math.sin(ang);

  function dishPt(lx, dy, lz) {
    return proj(
      cx + lx * ca - lz * sa,
      yBase + dy,
      cz + lx * sa + lz * ca
    );
  }

  let dw = rTurn * 0.68;
  let dd = rTurn * 0.46;

  // 1. Cast shadow under porcelain butter dish
  let qShadow = [
    dishPt(-dw * 1.04, 0.01, -dd * 1.04),
    dishPt(dw * 1.04, 0.01, -dd * 1.04),
    dishPt(dw * 1.04, 0.01, dd * 1.04),
    dishPt(-dw * 1.04, 0.01, dd * 1.04)
  ];
  washPolyClipped(qShadow, qWin, PAL.glowDeep, 155);

  // 2. Stepped Porcelain Butter Dish Tray
  let qTrayOuter = [
    dishPt(-dw, 0.07, -dd),
    dishPt(dw, 0.07, -dd),
    dishPt(dw, 0.07, dd),
    dishPt(-dw, 0.07, dd)
  ];
  let qTrayInner = [
    dishPt(-dw * 0.78, 0.08, -dd * 0.76),
    dishPt(dw * 0.78, 0.08, -dd * 0.76),
    dishPt(dw * 0.78, 0.08, dd * 0.76),
    dishPt(-dw * 0.78, 0.08, dd * 0.76)
  ];
  washPolyClipped(qTrayOuter, qWin, PAL.glowGold, 225);
  washPolyClipped(qTrayInner, qWin, PAL.glowAmber, 220);

  // Tray rim highlights & technical pen edges
  for (let i = 0; i < 4; i++) {
    drawLineClipped(qTrayOuter[i], qTrayOuter[(i + 1) % 4], qWin, "rotring", PAL.glowDeep, 0.40);
    drawLineClipped(qTrayInner[i], qTrayInner[(i + 1) % 4], qWin, "rotring", PAL.glowRust, 0.30);
  }
  drawLineClipped(qTrayOuter[2], qTrayOuter[3], qWin, "cpencil", PAL.glowWhite, 0.62);
  drawLineClipped(qTrayOuter[1], qTrayOuter[2], qWin, "cpencil", PAL.glowWhite, 0.55);

  // 3. Glossy Spreading Puddle of Melted Golden Butter on the tray!
  let puddlePts = [];
  let pSteps = 16;
  for (let i = 0; i < pSteps; i++) {
    let a = (i / pSteps) * Math.PI * 2;
    let lobe = 1 + 0.22 * Math.sin(a * 3 + 0.8) + 0.14 * Math.cos(a * 2);
    let px = (Math.cos(a) * dw * 0.62 + dw * 0.08) * lobe;
    let pz = (Math.sin(a) * dd * 0.58 + dd * 0.06) * lobe;
    puddlePts.push(dishPt(px, 0.09, pz));
  }
  washPolyClipped(puddlePts, qWin, PAL.glowPale, 235);
  drawSplineClipped(puddlePts.concat([puddlePts[0]]), qWin, "cpencil", PAL.glowRust, 0.38, 0.5);
  // Wet liquid specular rim on melted butter puddle
  drawSplineClipped(puddlePts.slice(2, 10), qWin, "cpencil", PAL.glowWhite, 0.65, 0.5);

  // 4. Half-Melted Stick of Butter (slumped and softening at the right end!)
  let bw = dw * 0.46;
  let bd = dd * 0.36;
  let bhLeft = 0.28;  // Taller intact end of butter stick
  let bhRight = 0.14; // Slumped, melting end of butter stick!

  let bBotFL = dishPt(-bw, 0.09, bd);
  let bBotFR = dishPt(bw * 0.92, 0.09, bd * 1.05);
  let bBotBR = dishPt(bw * 0.88, 0.09, -bd * 0.92);
  let bBotBL = dishPt(-bw, 0.09, -bd);

  let bTopFL = dishPt(-bw * 0.92, 0.09 + bhLeft, bd * 0.86);
  let bTopMid = dishPt(0, 0.09 + bhLeft * 0.88, bd * 0.88);
  let bTopFR = dishPt(bw * 0.78, 0.09 + bhRight, bd * 0.82);
  let bTopBR = dishPt(bw * 0.75, 0.09 + bhRight, -bd * 0.78);
  let bTopBL = dishPt(-bw * 0.92, 0.09 + bhLeft, -bd * 0.84);

  // Front face of butter block (warm golden amber)
  let qButterFront = [bTopFL, bTopMid, bTopFR, bBotFR, bBotFL];
  washPolyClipped(qButterFront, qWin, PAL.glowAmber, 235);

  // Side face of butter block (deep golden shadow or highlight)
  let qButterSide = [bTopFR, bTopBR, bBotBR, bBotFR];
  washPolyClipped(qButterSide, qWin, PAL.glowRust, 215);

  // Top slumped face of butter block (brightest creamy yellow-gold!)
  let qButterTop = [bTopBL, bTopBR, bTopFR, bTopMid, bTopFL];
  washPolyClipped(qButterTop, qWin, PAL.glowPale, 245);

  // Melted drips running down the side of the butter stick in colored pencil
  for (let d = -0.5; d <= 0.6; d += 0.35) {
    let pDripTop = dishPt(bw * d, 0.09 + bhLeft * (0.78 - d * 0.25), bd * 0.86);
    let pDripBot = dishPt(bw * (d + 0.06), 0.09, bd * 1.02);
    drawLineClipped(pDripTop, pDripBot, qWin, "cpencil", PAL.glowWhite, 0.48);
  }

  // Softened organic outlines of melting butter block
  drawSplineClipped([bBotFL, bTopFL, bTopMid, bTopFR, bBotFR], qWin, "rotring", PAL.glowDeep, 0.38, 0.45);
  drawSplineClipped([bTopFL, bTopBL, bTopBR, bTopFR], qWin, "rotring", PAL.glowDeep, 0.34, 0.4);
  drawSplineClipped([bTopFL, bTopMid, bTopFR], qWin, "cpencil", PAL.glowWhite, 0.65, 0.45);

  // Small butter knife blade resting on edge of dish
  let k1 = dishPt(dw * 0.35, 0.10, dd * 0.25);
  let k2 = dishPt(dw * 1.08, 0.15, dd * 0.78);
  drawLineClipped(k1, k2, qWin, "rotring", PAL.glowDeep, 0.42);
  drawLineClipped(
    { x: k1.x, y: k1.y - 1.2 },
    { x: k2.x, y: k2.y - 1.2 },
    qWin,
    "cpencil",
    PAL.glowWhite,
    0.48
  );
}

// ---------------------------------------------------------------------------
// Vignette 4 & 5: Covered Glass Dome & Steaming Soup Bowl
// ---------------------------------------------------------------------------
function drawVignetteDome(cx, yBase, cz, rTurn, turnAngle, qWin, rowIdx) {
  let rPlate = rTurn * 0.68;
  let rDome = rTurn * 0.56;
  let hDome = 0.44;

  let plateRim = ellipse3D_XZ(cx, yBase + 0.05, cz, rPlate, rPlate * 0.78, 20);
  washPolyClipped(plateRim, qWin, PAL.glowGold, 220);
  drawSplineClipped(plateRim.concat([plateRim[0]]), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);

  // Hemispherical glass cloche / splatter cover
  let domeBase = ellipse3D_XZ(cx, yBase + 0.06, cz, rDome, rDome * 0.76, 18);
  let domeArch = [];
  for (let i = 0; i <= 12; i++) {
    let a = (i / 12) * Math.PI;
    let dx = Math.cos(a) * rDome;
    let dy = Math.sin(a) * hDome;
    domeArch.push(proj(cx + dx, yBase + 0.06 + dy, cz));
  }
  let domePoly = domeArch.concat(domeBase.slice(0, 10));
  washPolyClipped(domePoly, qWin, PAL.glowPale, 155);
  drawSplineClipped(domeArch, qWin, "rotring", PAL.glowDeep, 0.38, 0.5);
  drawSplineClipped(domeArch.slice(2, 9), qWin, "cpencil", PAL.glowWhite, 0.62, 0.5);

  // Top finger-ring knob on dome
  let knobEll = ellipse3D_XZ(cx, yBase + 0.08 + hDome, cz, rDome * 0.22, rDome * 0.16, 12);
  drawSplineClipped(knobEll.concat([knobEll[0]]), qWin, "rotring", PAL.glowDeep, 0.36, 0.4);
}

function drawVignetteSoup(cx, yBase, cz, rTurn, turnAngle, qWin, rowIdx) {
  let rBowl = rTurn * 0.62;
  let hBowl = 0.28;
  let ellBot = ellipse3D_XZ(cx, yBase + 0.02, cz, rBowl * 0.55, rBowl * 0.44, 16);
  let ellTop = ellipse3D_XZ(cx, yBase + hBowl, cz, rBowl, rBowl * 0.78, 20);

  let hull = ellTop.slice(0, 11).concat(ellBot.slice(0, 10).reverse());
  washPolyClipped(hull, qWin, PAL.glowOrange, 225);
  washPolyClipped(ellTop, qWin, PAL.glowGold, 225);
  drawSplineClipped(ellTop.concat([ellTop[0]]), qWin, "rotring", PAL.glowDeep, 0.38, 0.4);
  drawSplineClipped(ellTop.slice(2, 9), qWin, "cpencil", PAL.glowWhite, 0.58, 0.4);

  // Ladle handle resting in soup bowl
  let p1 = proj(cx, yBase + hBowl, cz);
  let p2 = proj(cx + rBowl * 0.88, yBase + hBowl + 0.18, cz + 0.08);
  drawLineClipped(p1, p2, qWin, "rotring", PAL.glowDeep, 0.44);
  drawSteamWisps(cx, yBase + hBowl + 0.06, cz, rBowl * 0.45, 0.34, qWin, 3);
}

function drawSteamWisps(cx, y0, cz, spread, height, qWin, count) {
  for (let i = 0; i < count; i++) {
    let ox = (i / (count - 1) - 0.5) * spread * 1.4;
    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let t = k / 4;
      let wx = cx + ox + Math.sin(t * Math.PI * 2 + i * 1.6) * 0.08;
      let wy = y0 + t * height;
      let wz = cz + Math.cos(t * Math.PI + i) * 0.05;
      pts.push(proj(wx, wy, wz));
    }
    drawSplineClipped(pts, qWin, "cpencil", PAL.glowWhite, 0.40, 0.6);
  }
}

// ---------------------------------------------------------------------------
// 8. The Dark, Dead Unit Interior (c = -1, r = 3)
// ---------------------------------------------------------------------------
function drawDeadWindowInterior(cap, qWin, xW0, xW1, yW0, yW1, zWin) {
  // Cold, lifeless dark slate-charcoal glass & unlit cavity
  washPoly(qWin, PAL.deadGlass1, 245);

  let qInner = [
    quadUV(qWin, 0.08, 0.92),
    quadUV(qWin, 0.92, 0.92),
    quadUV(qWin, 0.92, 0.08),
    quadUV(qWin, 0.08, 0.08)
  ];
  washPoly(qInner, PAL.deadGlass2, 230);

  // Faint, cold unlit silhouette of a motionless turntable and mug inside the dark chamber
  let cx = (xW0 + xW1) * 0.50;
  let cz = zWin - 0.44;
  let yTurn = yW0 + (yW1 - yW0) * 0.12;
  let rTurn = (xW1 - xW0) * 0.42;

  let turnEll = ellipse3D_XZ(cx, yTurn, cz, rTurn, rTurn * 0.78, 20);
  drawSplineClipped(turnEll.concat([turnEll[0]]), qWin, "2B", "#495462", 0.35, 0.4);

  // Cold unlit mug silhouette in graphite pencil
  let rMug = rTurn * 0.33;
  let hMug = 0.50;
  let mugBot = ellipse3D_XZ(cx, yTurn + 0.04, cz, rMug, rMug * 0.78, 16);
  let mugTop = ellipse3D_XZ(cx, yTurn + hMug, cz, rMug, rMug * 0.78, 16);
  let mugHull = mugTop.slice(0, 9).concat(mugBot.slice(0, 9).reverse());
  washPolyClipped(mugHull, qWin, "#0e1217", 230);
  drawSplineClipped(mugTop.concat([mugTop[0]]), qWin, "2B", "#627080", 0.34, 0.4);

  // Dense cold Faraday mesh across the dead window
  hatchPoly(qWin, "rotring", "#0c0f14", 0.22, 6, 45, { rand: 0.01 });
  hatchPoly(qWin, "rotring", "#0c0f14", 0.20, 6, -45, { rand: 0.01 });

  // Stark cold diagonal reflection across dead glass
  let qColdRefl = [
    quadUV(qWin, 0.18, 0.10),
    quadUV(qWin, 0.34, 0.10),
    quadUV(qWin, 0.74, 0.90),
    quadUV(qWin, 0.58, 0.90)
  ];
  washPoly(qColdRefl, PAL.deadHighlight, 75);
  drawLine2D(
    quadUV(qWin, 0.20, 0.12),
    quadUV(qWin, 0.62, 0.88),
    "cpencil",
    "#b8c4d0",
    0.45,
    0
  );
}

// ---------------------------------------------------------------------------
// 9. Final Atmospheric Hum & Technical Drafting Polish
// ---------------------------------------------------------------------------
function drawForegroundPolish() {
  brush.noField();

  // Subtle humming vibration ticks along the vertical megastructure power conduits
  for (let c = -1; c <= 2; c++) {
    let xPilaster = (c - 0.5) * PITCH_X;
    for (let r = 0; r <= 5; r++) {
      let yMid = (r + 0.5) * PITCH_Y;
      let pC = proj(xPilaster, yMid, 0.48);
      if (pC.x > 40 && pC.x < 1160 && pC.y > 40 && pC.y < 1160) {
        drawLine2D(
          { x: pC.x - 5, y: pC.y - 2 },
          { x: pC.x + 5, y: pC.y + 2 },
          "rotring",
          PAL.inkFaint,
          0.22,
          0
        );
      }
    }
  }

  // Fine warm amber pencil grain over the central hero glow zone to unify the hum
  brush.noFill();
  brush.noWash();
  brush.set("spray", PAL.glowGold, 0.45);
  brush.line(320, 560, 780, 520);
  brush.line(340, 760, 760, 740);
}

