// ---------------------------------------------------------------------------
// Polygon & Drawing Helpers
// ---------------------------------------------------------------------------
function polyWash(pts, col, alpha) {
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  return p;
}

function polyFill(pts, col, alpha, bleed = 0.12, tex = 0.35) {
  let p = new brush.Polygon(pts);
  p.fill(col, alpha, bleed, tex);
  return p;
}

function polyMass(pts, brushName, col, opts) {
  let p = new brush.Polygon(pts);
  brush.mass(brushName, col, opts);
  p.mass();
  brush.noMass();
  return p;
}

function polyHatch(pts, brushName, col, weight, dist, ang, opts) {
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, ang, opts);
  brush.noHatch();
  return p;
}

function strokeLine(bName, col, weight, x1, y1, x2, y2) {
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(bName, col, weight, pts, curv = 0.5) {
  if (pts.length < 2) return;
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

// ---------------------------------------------------------------------------
// Exact Still Painting (Frame 0)
// ---------------------------------------------------------------------------
function paintStill() {
  translate(-width / 2, -height / 2);
  background("#0e1715");

  // 1. Subterranean Ceiling, Fluorescent Light Banks & Tiled Station Wall
  drawStationArchitecture();

  // 2. Arriving Train in Mid-Background (Kinetic Metallic & Window Blur)
  drawArrivingTrain();

  // 3. Background Crowd Echoes & Mid-Ground Atmospheric Smudge
  drawBackgroundCrowdEchoes();

  // 4. Hyperreal Step-Printed Commuters (Stuttering Staggered Echoes)
  drawAllStepPrintedCommuters();

  // 5. Lateral Motion Streaks & Charcoal/Pastel Smears Behind Central Subject
  drawMidgroundMotionTrails();

  // 6. Central Focus: Woman in Mustard Raincoat (Razor-Sharp Hyperrealism)
  drawCentralWomanMustardCoat();
  drawCentralWomanHeadAndFace();

  // 7. Foreground Kinetic Streaks & Step-Print Edge Artifacts (Framing the Subject)
  drawForegroundMotionFraming();
}

// ---------------------------------------------------------------------------
// Main Film Loop
// ---------------------------------------------------------------------------
function draw() {
  if (frameCount > TOTAL_FRAMES) return;

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    return;
  }

  if (!assetsInitialized) {
    initMotionAssets();
    assetsInitialized = true;
  }

  // Normalized time u in [0, 1] starting at 0 on frame 1
  const u = (frameCount - 1) / (TOTAL_FRAMES - 1);
  // Smooth ease-in over the first 5 frames so frame 2 continues frame 1 seamlessly
  const easeIn = constrain(u / 0.10, 0, 1) * constrain(u / 0.10, 0, 1) * (3 - 2 * constrain(u / 0.10, 0, 1));
  const tSec = (frameCount - 1) / window.PIECE_FPS;

  translate(-width / 2, -height / 2);
  background("#0e1715");

  // 1. Stamp the exact still painting as foundation
  image(stillImg, 0, 0, 1200, 1200);

  // 2. Pixel-lifted train & step-printed commuter ghost slices travelling across the flanks
  drawAnimatedImageSlices(tSec, u, easeIn);

  // 3. Restore the razor-sharp central woman cutout over any mid-ground image echoes
  image(womanCutout, 0, 0, 1200, 1200);

  // 4. Animated fluorescent ceiling tube echoes & glazed ox-blood reflections
  drawAnimatedFluorescents(tSec, u, easeIn);

  // 5. Hurtling train windows, crimson/amber livery blur & blazing headlights (clipped around woman)
  drawAnimatedTrainRush(tSec, u, easeIn);

  // 6. Stuttering step-printed commuter echoes & charcoal/pastel dissolution wakes
  drawAnimatedStepPrintedCommuters(tSec, u, easeIn);

  // 7. High-velocity lateral charcoal, pastel & chisel streaks across the platform
  drawAnimatedLateralStreaks(tSec, u, easeIn);

  // 8. Central Woman's hyperreal secondary motion: wind-whipped hair, blinking eyelashes & coat glints
  drawAnimatedWomanDetails(tSec, u, easeIn);
}

// ---------------------------------------------------------------------------
// Offscreen Cutout Extraction (Runs once on Frame 2)
// ---------------------------------------------------------------------------
function initMotionAssets() {
  // 1. Extract clean cutout of the central woman (hair + head + storm collar + mustard coat)
  womanCutout = createGraphics(1200, 1200);
  womanCutout.image(stillImg, 0, 0, 1200, 1200);
  let ctx = womanCutout.drawingContext;
  ctx.globalCompositeOperation = "destination-in";
  womanCutout.noStroke();
  womanCutout.fill(255);

  const womanPolys = [
    // Hair & head outer contour
    [
      [484, 565], [472, 475], [478, 385], [505, 315],
      [552, 282], [600, 276], [648, 282], [695, 315],
      [722, 385], [728, 475], [716, 565], [665, 610], [535, 610]
    ],
    // Left storm collar
    [[495, 535], [546, 552], [568, 668], [495, 692], [468, 622]],
    // Right storm collar
    [[654, 552], [705, 535], [732, 622], [705, 692], [632, 668]],
    // Raincoat body silhouette
    [
      [515, 555], [685, 555], [718, 635], [825, 678],
      [885, 860], [925, 1200], [275, 1200], [315, 860],
      [375, 678], [482, 635]
    ]
  ];

  for (let poly of womanPolys) {
    womanCutout.beginShape();
    for (let pt of poly) womanCutout.vertex(pt[0], pt[1]);
    womanCutout.endShape(CLOSE);
  }
  ctx.globalCompositeOperation = "source-over";

  // 2. Extract soft-feathered hyperreal face & shoulder patches for the 6 step-printed commuters
  for (let i = 0; i < COMMUTER_CONFIGS.length; i++) {
    let cfg = COMMUTER_CONFIGS[i];
    let sc = cfg.scale;
    let pw = Math.ceil(230 * sc);
    let ph = Math.ceil(310 * sc);
    let sx = Math.round(cfg.cx - pw * 0.5);
    let sy = Math.round(cfg.cy - 115 * sc);

    let pg = createGraphics(pw, ph);
    pg.image(stillImg, 0, 0, pw, ph, sx, sy, pw, ph);

    let pctx = pg.drawingContext;
    pctx.globalCompositeOperation = "destination-in";
    let grad = pctx.createRadialGradient(
      pw * 0.5, ph * 0.42, pw * 0.14,
      pw * 0.5, ph * 0.42, pw * 0.50
    );
    grad.addColorStop(0, "rgba(255,255,255,0.92)");
    grad.addColorStop(0.65, "rgba(255,255,255,0.55)");
    grad.addColorStop(1, "rgba(255,255,255,0)");
    pctx.fillStyle = grad;
    pctx.fillRect(0, 0, pw, ph);
    pctx.globalCompositeOperation = "source-over";

    commuterPatches.push({ pg, sx, sy, pw, ph, cfg });
  }
}

// ---------------------------------------------------------------------------
// Silhouette Boundary Helpers (Protects the Central Woman from Background Marks)
// ---------------------------------------------------------------------------
function getWomanLeftEdge(y) {
  if (y < 276) return 1200;
  if (y < 315) return map(y, 276, 315, 575, 502);
  if (y < 385) return map(y, 315, 385, 502, 475);
  if (y < 535) return 470;
  if (y < 635) return 465;
  if (y < 678) return map(y, 635, 678, 480, 372);
  if (y < 860) return map(y, 678, 860, 372, 312);
  return map(y, 860, 1200, 312, 272);
}

function getWomanRightEdge(y) {
  if (y < 276) return 0;
  if (y < 315) return map(y, 276, 315, 625, 698);
  if (y < 385) return map(y, 315, 385, 698, 725);
  if (y < 535) return 730;
  if (y < 635) return 735;
  if (y < 678) return map(y, 635, 678, 720, 828);
  if (y < 860) return map(y, 678, 860, 828, 888);
  return map(y, 860, 1200, 888, 928);
}

// Helper to draw a horizontal line split cleanly around the central woman
function strokeLineAroundWoman(bName, col, weight, x1, y1, x2, y2) {
  let xa = Math.min(x1, x2);
  let xb = Math.max(x1, x2);
  let ym = (y1 + y2) * 0.5;
  let wL = getWomanLeftEdge(ym) - 4;
  let wR = getWomanRightEdge(ym) + 4;

  if (wL >= wR || xb <= wL || xa >= wR) {
    strokeLine(bName, col, weight, x1, y1, x2, y2);
    return;
  }
  if (xa < wL - 8) {
    let tL = (wL - xa) / Math.max(1, xb - xa);
    let yL = lerp(y1, y2, x1 < x2 ? tL : 1 - tL);
    strokeLine(bName, col, weight, xa, x1 < x2 ? y1 : y2, wL, yL);
  }
  if (xb > wR + 8) {
    let tR = (wR - xa) / Math.max(1, xb - xa);
    let yR = lerp(y1, y2, x1 < x2 ? tR : 1 - tR);
    strokeLine(bName, col, weight, wR, yR, xb, x1 < x2 ? y2 : y1);
  }
}

// Helper to draw a rectangular wash clipped around the central woman
function rectWashAroundWoman(x, y, w, h, col, alpha) {
  let ym = y + h * 0.5;
  let wL = getWomanLeftEdge(ym) - 2;
  let wR = getWomanRightEdge(ym) + 2;
  let x2 = x + w;

  if (wL >= wR || x2 <= wL || x >= wR) {
    polyWash([[x, y], [x2, y], [x2, y + h], [x, y + h]], col, alpha);
    return;
  }
  if (x < wL - 6) {
    let rx2 = Math.min(x2, wL);
    polyWash([[x, y], [rx2, y], [rx2, y + h], [x, y + h]], col, alpha);
  }
  if (x2 > wR + 6) {
    let lx1 = Math.max(x, wR);
    polyWash([[lx1, y], [x2, y], [x2, y + h], [lx1, y + h]], col, alpha);
  }
}

// ---------------------------------------------------------------------------
// Animated Layer 2: Pixel-Lifted Step-Print Commuter & Train Slices
// ---------------------------------------------------------------------------
function drawAnimatedImageSlices(tSec, u, easeIn) {
  push();
  // Step-printed shutter cadence: combines smooth drift with a 12Hz step-print pulse
  let stepQuant = Math.floor(tSec * 12) / 12;
  let stepBlend = lerp(tSec, stepQuant, 0.42);

  // 1. Sliding train window strip echoes in the background (y: 252..382)
  let trainShift = (tSec * 680) % 420;
  tint(255, 135 * easeIn);
  // Left track window blur strip
  image(stillImg, trainShift * 0.45, 255, 450, 122, 0, 255, 450, 122);
  // Right track window blur strip
  image(stillImg, 680 + trainShift * 0.45, 255, 520 - trainShift * 0.45, 122, 680, 255, 520 - trainShift * 0.45, 122);

  // 2. Stuttering staggered commuter face echoes lifted from stillImg
  for (let i = 0; i < commuterPatches.length; i++) {
    let cp = commuterPatches[i];
    let cfg = cp.cfg;
    let dir = Math.sign(cfg.dx);

    // Draw 3 travelling step-printed echoes per commuter
    for (let e = 1; e <= 3; e++) {
      let cycle = (stepBlend * 1.65 + e * 0.28 + i * 0.13) % 1.0;
      let travelDist = cycle * 165 * cfg.scale + u * 45 * cfg.scale;
      let ox = cp.sx + dir * travelDist * easeIn;
      let oy = cp.sy + sin(tSec * 220 + e * 95 + i * 60) * 3.5 * easeIn;
      let echoAlpha = (1 - cycle * 0.78) * 165 * easeIn;

      // Slight chromatic tint alternating between warm flesh coral and fluorescent mint
      if (e === 2) {
        tint(180, 255, 230, echoAlpha * 0.85);
      } else {
        tint(255, 235, 230, echoAlpha);
      }
      image(cp.pg, ox, oy, cp.pw, cp.ph);
    }
  }
  noTint();
  pop();
}

// ---------------------------------------------------------------------------
// Animated Layer 4: Overhead Fluorescent Light Banks & Ox-Blood Glints
// ---------------------------------------------------------------------------
function drawAnimatedFluorescents(tSec, u, easeIn) {
  randomSeed(5100);
  noiseSeed(5100);

  let fixtureRows = [
    { y: 46, h: 18, speed: 340 },
    { y: 108, h: 24, speed: -420 }
  ];

  for (let r = 0; r < fixtureRows.length; r++) {
    let row = fixtureRows[r];
    let shift = tSec * row.speed;

    // Travelling step-printed light bars along the fluorescent tubes
    for (let i = 0; i < 6; i++) {
      let bx = ((i * 210 + shift) % 1360 + 1360) % 1360 - 120;
      let bw = 115 + (i % 2) * 25;
      polyWash([
        [bx, row.y + 2],
        [bx + bw, row.y + 2],
        [bx + bw, row.y + row.h - 2],
        [bx, row.y + row.h - 2]
      ], "#ecfdf5", 95 * easeIn);

      strokeLine("motion_chisel", "#ffffff", 0.9 * easeIn, bx - 20, row.y + row.h * 0.45, bx + bw + 30, row.y + row.h * 0.45);
    }
  }

  // Sliding specular reflections on the glazed ox-blood upper cornice (y: 177) & lower wainscot (y: 476)
  let trimShift = tSec * 620;
  for (let i = 0; i < 10; i++) {
    let gx = ((i * 135 + trimShift) % 1320 + 1320) % 1320 - 80;
    let gw = 55 + (i % 3) * 22;
    polyWash([[gx, 176], [gx + gw, 176], [gx + gw, 182], [gx, 182]], "#a7f3d0", 110 * easeIn);
    strokeLine("pen", "#ffffff", 0.65 * easeIn, gx + 6, 178, gx + gw - 6, 178);

    // Lower wainscot reflections split around the central woman
    let lx = ((i * 145 + trimShift * 1.15) % 1320 + 1320) % 1320 - 80;
    rectWashAroundWoman(lx, 474, gw, 6, "#a7f3d0", 95 * easeIn);
  }
}

// ---------------------------------------------------------------------------
// Animated Layer 5: Hurtling Train Windows, Livery Stripes & Blazing Headlights
// ---------------------------------------------------------------------------
function drawAnimatedTrainRush(tSec, u, easeIn) {
  randomSeed(6200);
  noiseSeed(6200);

  // Train barrels left-to-right at 780 px/s
  let trainTravel = tSec * 780 * easeIn;

  // 1. Streaming train windows (y: 280..372)
  let baseWins = [-130, -10, 95, 210, 315, 410, 560, 690, 815, 940, 1065, 1185];
  for (let i = 0; i < baseWins.length; i++) {
    let wx = ((baseWins[i] + trainTravel) % 1440 + 1440) % 1440 - 140;
    let ww = 88 + (i % 3) * 10;
    let wy = 280;
    let wh = 92;

    // Step-printed trailing window echoes
    for (let s = 0; s < 3; s++) {
      let sx = wx - s * 28 * easeIn;
      let a = map(s, 0, 2, 115, 40) * easeIn;
      let col = s % 2 === 0 ? "#a7f3d0" : "#fde68a";
      rectWashAroundWoman(sx, wy, ww, wh, col, a);
    }

    // Crisp fluorescent interior core of passing carriage window
    rectWashAroundWoman(wx + 10, wy + 8, ww - 18, 28, "#ecfdf5", 145 * easeIn);

    // Blurred window mullions
    strokeLineAroundWoman("charcoal", "#0f172a", 1.15 * easeIn, wx - 25, wy, wx + ww + 25, wy);
    strokeLineAroundWoman("charcoal", "#0f172a", 1.15 * easeIn, wx - 25, wy + wh, wx + ww + 25, wy + wh);
  }

  // 2. Kinetic crimson & hazard-amber livery streaks (y: 388..426)
  for (let i = 0; i < 8; i++) {
    let sx = ((i * 175 + trainTravel * 1.15) % 1400 + 1400) % 1400 - 120;
    let sw = 110 + (i % 2) * 45;
    rectWashAroundWoman(sx, 390, sw, 22, "#b91c1c", 130 * easeIn);
    rectWashAroundWoman(sx + 15, 414, sw * 0.85, 10, "#f59e0b", 135 * easeIn);
  }

  // 3. Blazing train headlight beams sweeping across the platform
  let hlPositions = [
    { baseX: 350, y: 394, w: 95, h: 24, c1: "#fef08a", c2: "#ffffff" },
    { baseX: 685, y: 392, w: 115, h: 24, c1: "#6ee7b7", c2: "#ecfdf5" },
    { baseX: 1020, y: 395, w: 90, h: 22, c1: "#fdba74", c2: "#fef9c3" }
  ];

  for (let hl of hlPositions) {
    let hx = ((hl.baseX + trainTravel * 0.92) % 1380 + 1380) % 1380 - 100;
    rectWashAroundWoman(hx - 20, hl.y - 6, hl.w + 40, hl.h + 12, hl.c1, 85 * easeIn);
    rectWashAroundWoman(hx, hl.y + 2, hl.w, hl.h - 4, hl.c2, 165 * easeIn);
    strokeLineAroundWoman("pastel_smudge", hl.c1, 1.35 * easeIn, hx - 75, hl.y + hl.h * 0.5, hx + hl.w + 85, hl.y + hl.h * 0.5);
  }
}

// ---------------------------------------------------------------------------
// Animated Layer 6: Stuttering Step-Printed Commuter Feature Echoes & Trails
// ---------------------------------------------------------------------------
function drawAnimatedStepPrintedCommuters(tSec, u, easeIn) {
  // Stuttered film-printer step time (8 fps step cadence + smooth drift)
  let stepTick = Math.floor(tSec * 10) / 10;
  let motionPhase = lerp(tSec, stepTick, 0.48);

  for (let i = 0; i < COMMUTER_CONFIGS.length; i++) {
    let cfg = COMMUTER_CONFIGS[i];
    randomSeed(cfg.seed);
    noiseSeed(cfg.seed);

    let sc = cfg.scale;
    let dir = Math.sign(cfg.dx);
    let shiftX = cfg.turn * 26 * sc;

    // Outward step-print wave travelling across the echo chain
    let waveOffset = (motionPhase * 92 * sc) * easeIn;

    // Draw 4 animated step-printed echo ghosts per commuter
    for (let s = 1; s <= 4; s++) {
      let stepDist = s * Math.abs(cfg.dx) + (waveOffset % (Math.abs(cfg.dx) * 1.5));
      let sx = cfg.cx + dir * stepDist;
      let sy = cfg.cy + s * cfg.dy + sin(tSec * 240 + s * 75 + i * 45) * 3.0 * easeIn;

      // Keep echoes safely outside the central woman's silhouette
      let wL = getWomanLeftEdge(sy) - 25 * sc;
      let wR = getWomanRightEdge(sy) + 25 * sc;
      if (sx > wL && sx < wR) continue;

      let fade = map(s, 1, 4, 0.85, 0.25) * easeIn;
      let faceCol = s % 2 === 1 ? cfg.skinMid : cfg.skinGhost;

      // Stuttered facial plane echo
      polyWash([
        [sx - 56 * sc, sy - 52 * sc],
        [sx + 56 * sc, sy - 52 * sc],
        [sx + 48 * sc, sy + 50 * sc],
        [sx + shiftX * 0.5, sy + 96 * sc],
        [sx - 48 * sc, sy + 50 * sc]
      ], faceCol, 78 * fade);

      // Stuttered eye echoes (sclera + iris + catchlight)
      let eyeY = sy - 14 * sc;
      let eyeLX = sx + shiftX - 30 * sc;
      let eyeRX = sx + shiftX + 30 * sc;
      let eyeW = 16 * sc;
      let eyeH = 7 * sc;

      for (let ex of [eyeLX, eyeRX]) {
        polyWash([
          [ex - eyeW * 0.8, eyeY],
          [ex, eyeY - eyeH * 0.8],
          [ex + eyeW * 0.8, eyeY],
          [ex, eyeY + eyeH * 0.7]
        ], "#e2f1ec", 135 * fade);

        let ix = ex + cfg.turn * 4 * sc;
        polyWash([
          [ix - eyeH * 0.7, eyeY - eyeH * 0.65],
          [ix + eyeH * 0.7, eyeY - eyeH * 0.65],
          [ix + eyeH * 0.7, eyeY + eyeH * 0.65],
          [ix - eyeH * 0.7, eyeY + eyeH * 0.65]
        ], s === 1 ? cfg.irisCol : "#18131a", 155 * fade);

        strokeLine("rotring", "#ffffff", 0.9 * sc * fade, ix - 2 * sc, eyeY - 2 * sc, ix + 2 * sc, eyeY - 2 * sc);
      }

      // Stuttered vermilion lip echo
      let mouthX = sx + shiftX * 1.15;
      let mouthY = sy + 64 * sc;
      let mouthW = 22 * sc;
      polyWash([
        [mouthX - mouthW, mouthY],
        [mouthX, mouthY - 6 * sc],
        [mouthX + mouthW, mouthY],
        [mouthX, mouthY + 8 * sc]
      ], cfg.lipCol, 145 * fade);

      // Horizontal charcoal & pastel dissolution streaks linking the moving echoes
      let prevX = sx - dir * Math.abs(cfg.dx) * 0.85;
      strokeLineAroundWoman("charcoal", "#141016", 0.75 * sc * fade, eyeLX, eyeY, prevX + shiftX - 30 * sc, eyeY);
      strokeLineAroundWoman("cpencil", cfg.lipCol, 0.85 * sc * fade, mouthX, mouthY, prevX + shiftX * 1.15, mouthY);
      strokeLineAroundWoman("pastel_smudge", s % 2 === 0 ? cfg.skinGhost : cfg.skinMid, 0.8 * sc * fade, sx, sy + 10 * sc, prevX, sy + 10 * sc);
    }

    // Trailing charcoal & spray wake flying off the outer edge of each commuter
    let tailBaseX = cfg.cx + (cfg.steps - 1) * cfg.dx;
    let tailBaseY = cfg.cy + (cfg.steps - 1) * cfg.dy;
    for (let k = 0; k < 7; k++) {
      let ky = tailBaseY + map(k, 0, 6, -75 * sc, 155 * sc);
      let shiftStreak = ((tSec * 460 + k * 55) % 180) * dir * easeIn;
      let xStart = cfg.cx + dir * 25 * sc + shiftStreak * 0.4;
      let xEnd = tailBaseX + shiftStreak + dir * (50 + k * 14) * sc * easeIn;
      let col = k % 3 === 0 ? cfg.skinGhost : (k % 3 === 1 ? cfg.lipCol : "#141117");
      let bName = k % 2 === 0 ? "charcoal" : "cpencil";
      strokeLineAroundWoman(bName, col, 0.75 * easeIn, xStart, ky, xEnd, ky);
    }
  }
}

// ---------------------------------------------------------------------------
// Animated Layer 7: High-Velocity Lateral Motion Streaks & Film Gate Weave
// ---------------------------------------------------------------------------
function drawAnimatedLateralStreaks(tSec, u, easeIn) {
  randomSeed(7300);
  noiseSeed(7300);

  const streakPalette = [
    "#6ee7b7", "#a7f3d0", "#991b1b", "#f59e0b",
    "#111827", "#f43f5e", "#eab308", "#0f172a"
  ];

  // 34 fast horizontal charcoal, pastel & marker streaks shooting across left & right flanks
  for (let i = 0; i < 34; i++) {
    let baseY = random(195, 1165);
    let baseX = random(0, 1200);
    let len = random(110, 290);
    let speed = random(580, 1050) * (i % 2 === 0 ? -1 : 1);
    let col = streakPalette[i % streakPalette.length];
    let bName = i % 4 === 0 ? "pastel_smudge" : (i % 3 === 0 ? "motion_chisel" : "charcoal");
    let wt = (bName === "pastel_smudge" ? random(0.55, 1.1) : random(0.5, 1.25)) * easeIn;

    let curX = ((baseX + tSec * speed) % 1500 + 1500) % 1500 - 150;
    let x2 = curX + len * Math.sign(speed) * easeIn;

    strokeLineAroundWoman(bName, col, wt, curX, baseY, x2, baseY);
  }

  // Animated 35mm step-printed vertical shutter-gate lines at the far left & right margins
  let gateJitter = sin(tSec * 520) * 6 * easeIn;
  let gateLines = [38, 76, 118, 1082, 1124, 1162];
  for (let i = 0; i < gateLines.length; i++) {
    let vx = gateLines[i] + (i < 3 ? -1 : 1) * (gateJitter + (i % 2) * 4 * sin(tSec * 340) * easeIn);
    strokeLine("2H", "#6ee7b7", 0.45 * easeIn, vx, 0, vx, 1200);
    strokeLine("charcoal", "#090d16", 0.55 * easeIn, vx + 3, 180, vx + 3, 1180);
  }
}

// ---------------------------------------------------------------------------
// Animated Layer 8: Central Woman's Wind-Blown Hair, Blink & Coat Reflections
// ---------------------------------------------------------------------------
function drawAnimatedWomanDetails(tSec, u, easeIn) {
  randomSeed(8800);
  noiseSeed(8800);

  // 1. Wind-whipped flyaway hair strands & fluorescent highlights (lagging from roots to tips)
  let windGust = (sin(tSec * 260 - 25) * 0.65 + sin(tSec * 520) * 0.35 + 0.35) * easeIn;

  // Dynamic glossy hair sheen strands rooted at the center part (x = 600)
  for (let i = 0; i < 24; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let startX = 600 + side * random(4, 26);
    let startY = random(288, 334);
    let baseMidX = 600 + side * random(58, 106);
    let baseMidY = startY + random(55, 112);
    let baseEndX = 600 + side * random(72, 114);
    let baseEndY = baseMidY + random(75, 150);

    // Phase-lagged wind displacement: root is fixed, mid sways, tip whips in the train draft
    let midWind = (windGust * 5.5 + sin(tSec * 310 + i * 35) * 3.2 * easeIn);
    let tipWind = (windGust * 13.5 + sin(tSec * 310 + i * 35 - 45) * 7.5 * easeIn);

    let hCol = i % 3 === 0 ? "#6ee7b7" : (i % 3 === 1 ? "#d1fae5" : (i % 4 === 0 ? "#facc15" : "#120c14"));
    let wt = (hCol === "#120c14" ? 0.85 : 0.68) * easeIn;

    strokeSpline("fine_lash", hCol, wt, [
      [startX, startY],
      [baseMidX + midWind, baseMidY],
      [baseEndX + tipWind, baseEndY - Math.abs(tipWind) * 0.2]
    ], 0.55);
  }

  // Delicate flyaway strands whipping across her forehead and cheekbones
  const strayBase = [
    [[568, 336], [542, 368], [524, 405], [516, 438]],
    [[582, 335], [564, 362], [558, 392], [552, 412]],
    [[624, 335], [648, 365], [666, 398], [674, 428]],
    [[518, 442], [528, 478], [522, 515], [534, 542]],
    [[682, 442], [672, 482], [678, 518], [666, 545]]
  ];

  for (let s = 0; s < strayBase.length; s++) {
    let pts = strayBase[s];
    let animPts = [];
    let lightPts = [];
    for (let k = 0; k < pts.length; k++) {
      let lag = k / (pts.length - 1);
      let sway = pow(lag, 1.5) * (windGust * 11 + sin(tSec * 360 + s * 50 - k * 30) * 5.5 * easeIn);
      let px = pts[k][0] + sway;
      let py = pts[k][1] - Math.abs(sway) * 0.15;
      animPts.push([px, py]);
      lightPts.push([px + 0.9, py]);
    }
    strokeSpline("fine_lash", "#0f0b12", 0.78 * easeIn, animPts, 0.55);
    strokeSpline("fine_lash", "#a7f3d0", 0.42 * easeIn, lightPts, 0.55);
  }

  // 2. Hyperreal Eye Blink & Moving Train-Window Corneal Catchlights
  // Primary natural blink peaks at t = 0.42s (frame 11), with a subtle flutter at t = 1.48s
  let blink1 = exp(-pow((tSec - 0.42) / 0.085, 2));
  let blink2 = 0.32 * exp(-pow((tSec - 1.48) / 0.09, 2));
  let blinkAmt = constrain(blink1 + blink2, 0, 1) * easeIn;

  drawAnimatedWomanEye(556, 437, -1, tSec, easeIn, blinkAmt);
  drawAnimatedWomanEye(644, 437, 1, tSec, easeIn, blinkAmt);

  // Subtle wet lower-lip specular shimmer as train windows pass
  let lipGlintShift = sin(tSec * 360) * 2.5 * easeIn;
  strokeLine("rotring", "#ffffff", 1.05 * easeIn, 586 + lipGlintShift, 536.5, 595 + lipGlintShift, 536.5);
  strokeLine("rotring", "#d1fae5", 0.95 * easeIn, 604 + lipGlintShift, 536.5, 612 + lipGlintShift, 536.5);

  // 3. Passing Train Light Sweeping Across Mustard Raincoat, Buttons & Sliding Raindrops
  let lightWaveX = ((tSec * 720) % 700) + 250;

  // Travelling greenish-mint & lemon-gold specular highlights on waterproof shoulder & chest ridges
  let leftGlow = exp(-pow((lightWaveX - 460) / 130, 2)) * easeIn;
  let rightGlow = exp(-pow((lightWaveX - 740) / 130, 2)) * easeIn;

  if (leftGlow > 0.05) {
    polyWash([[378, 678], [505, 648], [512, 662], [385, 694]], "#ecfdf5", 130 * leftGlow);
    polyWash([[435, 720], [545, 705], [542, 745], [430, 775]], "#fef08a", 115 * leftGlow);
  }
  if (rightGlow > 0.05) {
    polyWash([[695, 648], [822, 678], [815, 694], [688, 662]], "#ecfdf5", 130 * rightGlow);
    polyWash([[655, 705], [765, 720], [770, 775], [658, 745]], "#fef08a", 115 * rightGlow);
  }

  // Rotating specular rim glints on the main center placket buttons as the train light sweeps past
  let placketButtonY = [738, 846, 958, 1072, 1178];
  let glintSweep = tSec * 140 * easeIn;
  for (let i = 0; i < placketButtonY.length; i++) {
    let by = placketButtonY[i];
    let angStart = 200 + glintSweep * 0.45 + i * 12;
    brush.set("rotring", "#ffffff", 1.1 * easeIn);
    brush.arc(600, by, 18.5 * 0.86, angStart, angStart + 55);
  }

  // Animated raindrops beading & slowly sliding down the slick waterproof coat
  const slidingDrops = [
    [458, 712, 3.8, 11],
    [512, 745, 4.5, 14],
    [718, 735, 5.0, 13],
    [692, 875, 4.6, 12],
    [472, 865, 4.4, 10],
    [582, 792, 3.9, 9]
  ];

  for (let [dx, dyBase, dr, slideDist] of slidingDrops) {
    let slideY = u * slideDist * easeIn;
    let dy = dyBase + slideY;

    // Faint wet trail left behind the sliding droplet
    if (slideY > 1.2) {
      strokeLine("fine_lash", "#fef08a", 0.75 * easeIn, dx, dyBase, dx, dy - dr * 0.5);
    }
    // Lower shadow & refracted golden belly of moving droplet
    polyWash([[dx - dr, dy], [dx + dr, dy], [dx + dr * 0.7, dy + dr * 1.3], [dx - dr * 0.7, dy + dr * 1.3]], "#78350f", 175 * easeIn);
    polyWash([[dx - dr * 0.8, dy - dr * 0.5], [dx + dr * 0.8, dy - dr * 0.5], [dx + dr * 0.85, dy + dr * 0.6], [dx - dr * 0.85, dy + dr * 0.6]], "#fde047", 205 * easeIn);
    strokeLine("rotring", "#ffffff", 1.35 * easeIn, dx - dr * 0.35, dy - dr * 0.4, dx + dr * 0.2, dy - dr * 0.4);
  }
}

function drawAnimatedWomanEye(cx, cy, side, tSec, easeIn, blinkAmt) {
  let innerX = cx - side * 22;
  let outerX = cx + side * 23;
  let irisY = cy - 0.8;

  // When eyes are open, animate the corneal catchlights responding to the passing train windows
  if (blinkAmt < 0.65) {
    let glintShift = sin(tSec * 360) * 1.6 * easeIn;
    let openFade = (1 - blinkAmt / 0.65) * easeIn;
    polyWash([
      [cx - 4.8 + glintShift, irisY - 4.6],
      [cx - 1.2 + glintShift, irisY - 4.6],
      [cx - 1.6 + glintShift, irisY - 1.8],
      [cx - 5.2 + glintShift, irisY - 1.8]
    ], "#ffffff", 240 * openFade);

    polyWash([
      [cx + 1.8 + glintShift * 1.2, irisY + 1.5],
      [cx + 4.6 + glintShift * 1.2, irisY + 1.5],
      [cx + 4.3 + glintShift * 1.2, irisY + 3.4],
      [cx + 1.5 + glintShift * 1.2, irisY + 3.4]
    ], "#6ee7b7", 220 * openFade);
  }

  // If blinking, paint the descending upper eyelid and pivoting hyperreal eyelashes
  if (blinkAmt > 0.02) {
    let lidEdgeY = lerp(cy - 8.5, cy + 7.2, blinkAmt);

    // Descending moveable eyelid skin plane covering the open eye
    polyWash([
      [innerX, cy + 2],
      [cx - side * 9, cy - 11],
      [cx + side * 8, cy - 11],
      [outerX, cy + 1],
      [cx + side * 8, lidEdgeY],
      [cx - side * 9, lidEdgeY]
    ], "#f5c6ae", 252);

    // Warm rose-terracotta lid shading
    polyWash([
      [innerX + side * 2, cy],
      [cx - side * 8, cy - 10],
      [cx + side * 8, cy - 10],
      [outerX - side * 2, cy],
      [cx, lerp(cy - 6, cy + 2, blinkAmt)]
    ], "#e57c68", 150 * blinkAmt);

    // Moving upper lid margin line
    strokeSpline("rotring", "#090608", 1.45, [
      [innerX, cy + 2],
      [cx - side * 9, lidEdgeY],
      [cx + side * 7, lidEdgeY],
      [outerX + side * 1, cy + 1.5]
    ], 0.48);

    // 26 individual curved upper eyelashes pivoting downward with the blinking lid
    let numUpperLashes = 26;
    for (let i = 0; i < numUpperLashes; i++) {
      let u = i / (numUpperLashes - 1);
      let lx = lerp(innerX + side * 3, outerX, u);
      let arch = sin(u * 180);
      let openLy = (cy + 1.5) - arch * 10.2;
      let closedLy = (cy + 1.8) + arch * 5.6;
      let ly = lerp(openLy, closedLy, blinkAmt);

      let lashLen = lerp(5.5, 13.5, pow(u, 0.7)) * (0.85 + 0.25 * sin(i * 73));
      let openAng = -90 + side * lerp(-18, 48, u);
      let closedAng = 88 + side * lerp(-10, 32, u);
      let fanAngle = lerp(openAng, closedAng, blinkAmt);

      let midX = lx + cos(fanAngle) * (lashLen * 0.55);
      let midY = ly + sin(fanAngle) * (lashLen * 0.55);
      let tipAngle = fanAngle + side * 14 - lerp(8, -6, blinkAmt);
      let tipX = midX + cos(tipAngle) * (lashLen * 0.55);
      let tipY = midY + sin(tipAngle) * (lashLen * 0.55);

      strokeSpline("fine_lash", "#080609", lerp(0.65, 0.98, u), [
        [lx, ly], [midX, midY], [tipX, tipY]
      ], 0.55);
    }
  }
}

