// ---------------------------------------------------------------------------
// 1. Station Architecture: Ceiling, Greenish-White Fluorescents, Cream & Ox-Blood Tiles
// ---------------------------------------------------------------------------
function drawStationArchitecture() {
  // Base atmospheric washes
  polyWash([[0, 0], [1200, 0], [1200, 190], [0, 190]], "#0c1b18", 255);
  polyWash([[0, 175], [1200, 175], [1200, 620], [0, 620]], "#efe5ce", 255);
  polyWash([[0, 600], [1200, 600], [1200, 1200], [0, 1200]], "#141216", 255);

  // Ceiling concrete ribs & greenish-emerald ambient glow
  for (let i = 0; i < 16; i++) {
    let y1 = i * 11;
    let col = i % 2 === 0 ? "#112923" : "#183b32";
    polyWash([[0, y1], [1200, y1], [1200, y1 + 14], [0, y1 + 14]], col, 160);
  }

  // Greenish-white fluorescent light wash across ceiling and upper tiles
  polyFill([[0, 10], [1200, 10], [1200, 210], [0, 210]], "#4ade80", 42, 0.35, 0.5);
  polyFill([[80, 20], [1120, 20], [1180, 165], [20, 165]], "#a7f3d0", 65, 0.4, 0.4);

  // Two perspective/horizontal rows of fluorescent light fixtures
  let fixtureRows = [
    { y: 46, h: 18, glowH: 52 },
    { y: 108, h: 24, glowH: 68 }
  ];

  for (let row of fixtureRows) {
    // Dark metal housing
    polyWash([[0, row.y - 10], [1200, row.y - 10], [1200, row.y + row.h + 8], [0, row.y + row.h + 8]], "#0f241f", 210);
    // Emerald-mint outer aura
    polyWash([[0, row.y - row.glowH * 0.5], [1200, row.y - row.glowH * 0.5], [1200, row.y + row.h + row.glowH * 0.5], [0, row.y + row.h + row.glowH * 0.5]], "#34d399", 55);
    polyWash([[0, row.y - 12], [1200, row.y - 12], [1200, row.y + row.h + 12], [0, row.y + row.h + 12]], "#6ee7b7", 95);

    // Individual fluorescent tube segments with step-printed horizontal overlap
    for (let x = -20; x < 1220; x += 155) {
      let w = 132;
      polyWash([[x, row.y], [x + w, row.y], [x + w, row.y + row.h], [x, row.y + row.h]], "#d1fae5", 220);
      polyWash([[x + 6, row.y + 3], [x + w - 6, row.y + 3], [x + w - 6, row.y + row.h - 3], [x + 6, row.y + row.h - 3]], "#f0fdf4", 245);
      // Stuttered step-print light echo
      polyWash([[x + 24, row.y + 2], [x + w + 24, row.y + 2], [x + w + 24, row.y + row.h - 2], [x + 24, row.y + row.h - 2]], "#a7f3d0", 120);

      // Fixture bracket dividers
      polyWash([[x - 14, row.y - 8], [x + 2, row.y - 8], [x + 2, row.y + row.h + 6], [x - 14, row.y + row.h + 6]], "#091714", 230);
    }

    // Crisp core tube streaks
    strokeLine("motion_chisel", "#ffffff", 1.2, 0, row.y + row.h * 0.4, 1200, row.y + row.h * 0.4);
    strokeLine("pastel_smudge", "#6ee7b7", 1.5, 0, row.y + row.h * 0.7, 1200, row.y + row.h * 0.7);
  }

  // --- OX-BLOOD UPPER CORNICE TRIM (y: 166 to 216) ---
  drawOxBloodTrimBand(166, 50, true);

  // --- CREAM SUBWAY TILED WALL (y: 216 to 456) ---
  let tileW = 60;
  let tileH = 26;
  let creamPalette = ["#fbf6e9", "#f4ebd4", "#efe2c4", "#e6d6b5", "#e2f2e8", "#f7f0dd", "#dfd1b4"];

  for (let r = 0; r < 10; r++) {
    let ty = 216 + r * tileH;
    let offset = (r % 2) * (tileW * 0.5);

    // Row 3 & 4 form a decorative ox-blood & cream station border band
    let isTrimRow = (r === 3);

    for (let c = -1; c < 22; c++) {
      let tx = c * tileW + offset;
      if (isTrimRow) {
        let trimCol = (c % 3 === 0) ? "#6e0b19" : "#8f1424";
        polyWash([[tx + 1, ty + 1], [tx + tileW - 1, ty + 1], [tx + tileW - 1, ty + tileH - 1], [tx + 1, ty + tileH - 1]], trimCol, 235);
        // Glazed tile specular highlight
        strokeLine("HB", "#a7f3d0", 0.6, tx + 4, ty + 5, tx + tileW - 6, ty + 5);
      } else {
        let baseCol = random(creamPalette);
        polyWash([[tx + 1, ty + 1], [tx + tileW - 1, ty + 1], [tx + tileW - 1, ty + tileH - 1], [tx + 1, ty + tileH - 1]], baseCol, 225);

        // Subtle greenish-white fluorescent reflection on upper tiles
        if (r < 3 || random() < 0.35) {
          polyWash([[tx + 3, ty + 2], [tx + tileW - 3, ty + 2], [tx + tileW - 3, ty + 9], [tx + 3, ty + 9]], "#d1fae5", random(50, 110));
        }
        // Warm shadow along bottom bevel of ceramic tile
        polyWash([[tx + 2, ty + tileH - 6], [tx + tileW - 2, ty + tileH - 6], [tx + tileW - 2, ty + tileH - 1], [tx + 2, ty + tileH - 1]], "#cbb997", 120);
      }

      // Vertical mortar joint
      strokeLine("2H", "#7c6f5b", 0.55, tx, ty, tx, ty + tileH);
    }
    // Horizontal mortar joint
    strokeLine("HB", "#6b5d4d", 0.65, 0, ty, 1200, ty);
  }

  // --- OX-BLOOD LOWER WAINSCOT BAND (y: 462 to 522) ---
  drawOxBloodTrimBand(462, 60, false);

  // Lower dark cream & soot-stained tiles below wainscot (y: 522 to 640)
  for (let r = 0; r < 4; r++) {
    let ty = 522 + r * 28;
    let offset = (r % 2) * 30;
    for (let c = -1; c < 21; c++) {
      let tx = c * 60 + offset;
      let col = r < 2 ? "#cfc2a9" : "#9c8e78";
      polyWash([[tx + 1, ty + 1], [tx + 59, ty + 1], [tx + 59, ty + 27], [tx + 1, ty + 27]], col, 200);
      strokeLine("2H", "#4a4035", 0.5, tx, ty, tx, ty + 28);
    }
    strokeLine("HB", "#3d332a", 0.6, 0, ty, 1200, ty);
  }

  // Aged station grime & water seepage streaks down the tiles
  for (let i = 0; i < 38; i++) {
    let gx = random(20, 1180);
    let gy1 = random(170, 320);
    let gy2 = gy1 + random(50, 180);
    strokeLine("2B", "#574c3f", random(0.3, 0.7), gx, gy1, gx + random(-4, 4), gy2);
  }
}

function drawOxBloodTrimBand(yStart, h, isUpper) {
  // Rich ox-blood ceramic base
  polyWash([[0, yStart], [1200, yStart], [1200, yStart + h], [0, yStart + h]], "#590711", 250);
  polyWash([[0, yStart + 4], [1200, yStart + 4], [1200, yStart + h - 4], [0, yStart + h - 4]], "#800e1d", 235);
  polyFill([[0, yStart + 6], [1200, yStart + 6], [1200, yStart + h * 0.65], [0, yStart + h * 0.65]], "#a61729", 140, 0.15, 0.4);

  // Tile divisions within the ox-blood band
  let tw = 48;
  for (let x = 0; x < 1200; x += tw) {
    let shade = (int(x / tw) % 2 === 0) ? "#961425" : "#700a17";
    polyWash([[x + 2, yStart + 5], [x + tw - 2, yStart + 5], [x + tw - 2, yStart + h - 5], [x + 2, yStart + h - 5]], shade, 150);
    strokeLine("HB", "#2b0206", 0.65, x, yStart, x, yStart + h);
  }

  // Moulded architectural relief lines & glossy greenish-white fluorescent highlights
  strokeLine("rotring", "#2b0206", 1.2, 0, yStart, 1200, yStart);
  strokeLine("rotring", "#2b0206", 1.2, 0, yStart + h, 1200, yStart + h);
  strokeLine("motion_chisel", "#b91c1c", 0.9, 0, yStart + h * 0.35, 1200, yStart + h * 0.35);

  // Specular green-mint reflections on the curved ox-blood glaze
  for (let i = 0; i < 24; i++) {
    let rx = random(0, 1120);
    let rw = random(35, 130);
    let ry = yStart + (isUpper ? 11 : 14);
    polyWash([[rx, ry], [rx + rw, ry], [rx + rw, ry + 5], [rx, ry + 5]], "#a7f3d0", random(90, 170));
    strokeLine("pen", "#ecfdf5", 0.7, rx + 4, ry + 2, rx + rw - 4, ry + 2);
  }
}

