function drawHyperrealEye(cx, cy, side) {
  // side: -1 for left eye (inner corner at right), +1 for right eye (inner corner at left)
  let innerX = cx - side * 22;
  let outerX = cx + side * 23;

  // 1. Orbital Socket & Upper Eyelid Fold Shadow
  polyWash([
    [innerX, cy + 2],
    [cx - side * 10, cy - 18],
    [cx + side * 12, cy - 17],
    [outerX + side * 6, cy - 2],
    [outerX, cy + 12],
    [innerX, cy + 11]
  ], "#6e2930", 165);

  // Lit moveable upper eyelid plane
  polyWash([
    [innerX + side * 3, cy - 1],
    [cx - side * 6, cy - 13],
    [cx + side * 8, cy - 12],
    [outerX - side * 2, cy - 1],
    [cx, cy - 7]
  ], "#f5c6ae", 215);

  // Crisp upper eyelid crease (supratarsal fold)
  strokeSpline("rotring", "#2b0a10", 0.95, [
    [innerX + side * 2, cy - 3],
    [cx - side * 7, cy - 14.5],
    [cx + side * 8, cy - 13.5],
    [outerX + side * 3, cy - 3]
  ], 0.5);

  // Subtle lower eyelid tear-trough / orbicularis roll
  strokeSpline("HB", "#8f3d43", 0.65, [
    [innerX + side * 2, cy + 8],
    [cx, cy + 13.5],
    [outerX, cy + 9]
  ], 0.5);
  // Lower eyelid rim highlight (wet waterline)
  strokeSpline("fine_lash", "#fde2e4", 0.85, [
    [innerX + side * 4, cy + 3],
    [cx, cy + 8.2],
    [outerX - side * 2, cy + 2.5]
  ], 0.45);

  // 2. Sclera (Shaded eyeball sphere, never flat white)
  let scleraPts = [
    [innerX, cy + 2],
    [cx - side * 9, cy - 8.5],
    [cx + side * 7, cy - 8.5],
    [outerX, cy + 1],
    [cx + side * 7, cy + 7.5],
    [cx - side * 8, cy + 7.5]
  ];
  polyWash(scleraPts, "#cadbd6", 252);
  // Brighter central sclera around iris
  polyWash([
    [cx - 14, cy], [cx - 8, cy - 7], [cx + 8, cy - 7],
    [cx + 14, cy], [cx + 8, cy + 6.5], [cx - 8, cy + 6.5]
  ], "#eef7f4", 240);
  // Upper lid cast shadow across top of sclera & iris
  polyWash([
    [innerX + side * 2, cy - 1],
    [cx - side * 9, cy - 8.5],
    [cx + side * 7, cy - 8.5],
    [outerX - side * 2, cy - 1],
    [cx + side * 8, cy - 4.5],
    [cx - side * 8, cy - 4.5]
  ], "#64748b", 155);

  // Pinkish lacrimal caruncle (inner tear duct)
  polyWash([
    [innerX, cy + 2],
    [innerX + side * 5.5, cy - 1.5],
    [innerX + side * 6.5, cy + 2],
    [innerX + side * 4.5, cy + 4.5]
  ], "#e11d48", 215);
  strokeLine("rotring", "#ffffff", 1.1, innerX + side * 2.5, cy + 1.5, innerX + side * 4, cy + 1.5);

  // 3. Detailed Iris & Pupil (Amber-Hazel & Emerald-Mint Radial Fibers)
  let irisR = 8.4;
  let irisY = cy - 0.8;
  let irisPts = [];
  for (let a = 0; a < 360; a += 18) {
    let px = cx + cos(a) * irisR;
    let py = constrain(irisY + sin(a) * irisR, cy - 8.2, cy + 7.2);
    irisPts.push([px, py]);
  }
  // Dark outer limbal ring
  polyWash(irisPts, "#17110e", 255);

  // Inner iris body
  let innerIrisPts = [];
  for (let a = 0; a < 360; a += 20) {
    let px = cx + cos(a) * (irisR * 0.82);
    let py = constrain(irisY + sin(a) * (irisR * 0.82), cy - 7.8, cy + 6.8);
    innerIrisPts.push([px, py]);
  }
  polyWash(innerIrisPts, "#92400e", 248);

  // Radial iris stroma fibers (Amber gold, honey, and emerald-green reflections)
  for (let a = 0; a < 360; a += 12) {
    let r1 = 3.2;
    let r2 = irisR * 0.84;
    let x1 = cx + cos(a) * r1;
    let y1 = irisY + sin(a) * r1;
    let x2 = cx + cos(a) * r2;
    let y2 = constrain(irisY + sin(a) * r2, cy - 7.6, cy + 6.6);
    let fCol = (a > 20 && a < 160) ? (a % 24 === 0 ? "#fde047" : "#f59e0b") : (a % 36 === 0 ? "#34d399" : "#b45309");
    strokeLine("fine_lash", fCol, 0.55, x1, y1, x2, y2);
  }

  // Jet-black pupil
  let pupilR = 3.4;
  let pupilPts = [];
  for (let a = 0; a < 360; a += 30) {
    pupilPts.push([cx + cos(a) * pupilR, irisY + sin(a) * pupilR]);
  }
  polyWash(pupilPts, "#030304", 255);

  // Crisp Fluorescent Tube Catchlights on the Cornea
  polyWash([[cx - 4.8, irisY - 4.6], [cx - 1.2, irisY - 4.6], [cx - 1.6, irisY - 1.8], [cx - 5.2, irisY - 1.8]], "#ffffff", 255);
  polyWash([[cx + 1.8, irisY + 1.5], [cx + 4.5, irisY + 1.5], [cx + 4.2, irisY + 3.4], [cx + 1.5, irisY + 3.4]], "#a7f3d0", 220);

  // 4. Upper Lash Line & Every Individual Eyelash in Focus
  strokeSpline("rotring", "#090608", 1.5, [
    [innerX, cy + 2],
    [cx - side * 9, cy - 8.5],
    [cx + side * 7, cy - 8.5],
    [outerX + side * 1, cy + 1.5]
  ], 0.48);

  // 26 individual curved upper eyelashes fanning across the upper eyelid
  let numUpperLashes = 26;
  for (let i = 0; i < numUpperLashes; i++) {
    let u = i / (numUpperLashes - 1); // 0 = inner corner, 1 = outer corner
    let lx = lerp(innerX + side * 3, outerX, u);
    // Arch y along the upper lid parabola
    let arch = sin(u * 180);
    let ly = (cy + 1.5) - arch * 10.2;

    // Lash length & sweep angle
    let lashLen = lerp(5.5, 13.5, pow(u, 0.7)) * (0.85 + 0.25 * sin(i * 73));
    let fanAngle = -90 + side * lerp(-18, 48, u);
    let midX = lx + cos(fanAngle) * (lashLen * 0.55);
    let midY = ly + sin(fanAngle) * (lashLen * 0.55);
    let tipAngle = fanAngle + side * 14 - 8;
    let tipX = midX + cos(tipAngle) * (lashLen * 0.55);
    let tipY = midY + sin(tipAngle) * (lashLen * 0.55);

    strokeSpline("fine_lash", "#080609", lerp(0.65, 0.98, u), [
      [lx, ly], [midX, midY], [tipX, tipY]
    ], 0.55);
  }

  // 18 delicate individual lower eyelashes emerging below the lower waterline
  let numLowerLashes = 18;
  for (let i = 0; i < numLowerLashes; i++) {
    let u = i / (numLowerLashes - 1);
    let lx = lerp(innerX + side * 5, outerX - side * 1, u);
    let arch = sin(u * 180);
    let ly = (cy + 2.8) + arch * 6.2;

    let lashLen = lerp(3.5, 7.8, sin(u * 150)) * (0.8 + 0.3 * cos(i * 97));
    let fanAngle = 90 + side * lerp(-12, 36, u);
    let midX = lx + cos(fanAngle) * (lashLen * 0.5);
    let midY = ly + sin(fanAngle) * (lashLen * 0.5);
    let tipX = midX + cos(fanAngle + side * 12) * (lashLen * 0.55);
    let tipY = midY + sin(fanAngle + side * 12) * (lashLen * 0.55);

    strokeSpline("fine_lash", "#1c1217", 0.52, [
      [lx, ly], [midX, midY], [tipX, tipY]
    ], 0.5);
  }
}

function drawHyperrealEyebrow(cx, cy, side) {
  let innerX = cx - side * 24;
  let archX = cx + side * 9;
  let tailX = cx + side * 32;

  // Soft brow shadow underlay
  polyWash([
    [innerX, cy + 3],
    [archX, cy - 6],
    [tailX, cy + 4],
    [archX, cy + 1],
    [innerX, cy + 9]
  ], "#3d2528", 125);

  // 65 individual eyebrow hairs following natural anatomical growth direction
  let numHairs = 65;
  for (let i = 0; i < numHairs; i++) {
    let u = i / (numHairs - 1);
    let bx, by;
    if (u < 0.62) {
      let t = u / 0.62;
      bx = lerp(innerX, archX, t);
      by = lerp(cy + 5, cy - 4, t) + random(-2.5, 2.5);
    } else {
      let t = (u - 0.62) / 0.38;
      bx = lerp(archX, tailX, t);
      by = lerp(cy - 4, cy + 4, t) + random(-1.8, 1.8);
    }

    // Brow hairs grow more upward near the glabella and sweep laterally toward the tail
    let hairAng = (side === -1)
      ? lerp(-115, -168, pow(u, 0.65))
      : lerp(-65, -12, pow(u, 0.65));
    let hairLen = lerp(9, 13, sin(u * 160)) * random(0.8, 1.15);

    let ex = bx + cos(hairAng) * hairLen;
    let ey = by + sin(hairAng) * hairLen;
    let hCol = i % 5 === 0 ? "#3b282c" : "#120c10";
    strokeLine("fine_lash", hCol, random(0.48, 0.78), bx, by, ex, ey);
  }
}

// ---------------------------------------------------------------------------
// 7. Foreground Kinetic Streaks & Step-Printed Film Edge Details
// ---------------------------------------------------------------------------
function drawForegroundMotionFraming() {
  // Dramatic horizontal streaks driving across the outer edges and bottom foreground,
  // leaving the central woman's face and raincoat buttons completely sharp and unobstructed
  let fgStreaks = [
    // Left flank streaks
    { x1: 0, x2: 455, y: 310, col: "#a7f3d0", b: "motion_chisel", w: 1.1 },
