  }

  // Fine charcoal & spray grain in the peripheral motion zones
  for (let i = 0; i < 48; i++) {
    let isLeft = i % 2 === 0;
    let y = random(60, 1180);
    let x1 = isLeft ? random(0, 310) : random(870, 1150);
    let x2 = x1 + (isLeft ? random(60, 160) : random(-160, -60));
    let col = i % 3 === 0 ? "#d1fae5" : (i % 3 === 1 ? "#18181b" : "#fb7185");
    strokeLine("spray", col, random(0.45, 0.95), x1, y, x2, y);
