// MOTION DATA INITIALIZATION & HEADLIGHT WAVE ANIMATION
// =========================================================================

function buildBandPrecomp(x1, y1, x2, y2, x3, y3, x4, y4, isVertical, baseSeed) {
  randomSeed(baseSeed);
  noiseSeed(baseSeed);

  let s1, s2, s3, s4;
  if (isVertical) {
    s1 = [lerp(x1, x2, 0.21), lerp(y1, y2, 0.21)];
    s2 = [lerp(x1, x2, 0.79), lerp(y1, y2, 0.79)];
    s3 = [lerp(x4, x3, 0.79), lerp(y4, y3, 0.79)];
    s4 = [lerp(x4, x3, 0.21), lerp(y4, y3, 0.21)];
  } else {
    s1 = [lerp(x1, x4, 0.21), lerp(y1, y4, 0.21)];
    s2 = [lerp(x2, x3, 0.21), lerp(y2, y3, 0.21)];
    s3 = [lerp(x2, x3, 0.79), lerp(y2, y3, 0.79)];
    s4 = [lerp(x1, x4, 0.79), lerp(y1, y4, 0.79)];
  }

  let segCount = 24;
  let segs = [];
  for (let i = 0; i < segCount; i++) {
    let tA = i / segCount;
    let tB = (i + 1) / segCount;
    let tMid = (tA + tB) * 0.5;
    let pA, pB, pC, pD, oA1, oB1, oC1, oD1, oA2, oB2, oC2, oD2;
    if (isVertical) {
      pA = [lerp(s1[0], s4[0], tA), lerp(s1[1], s4[1], tA)];
      pB = [lerp(s2[0], s3[0], tA), lerp(s2[1], s3[1], tA)];
      pC = [lerp(s2[0], s3[0], tB), lerp(s2[1], s3[1], tB)];
      pD = [lerp(s1[0], s4[0], tB), lerp(s1[1], s4[1], tB)];

      oA1 = [lerp(x1, x4, tA), lerp(y1, y4, tA)];
      oB1 = pA;
      oC1 = pD;
      oD1 = [lerp(x1, x4, tB), lerp(y1, y4, tB)];

      oA2 = pB;
      oB2 = [lerp(x2, x3, tA), lerp(y2, y3, tA)];
      oC2 = [lerp(x2, x3, tB), lerp(y2, y3, tB)];
      oD2 = pC;
    } else {
      pA = [lerp(s1[0], s2[0], tA), lerp(s1[1], s2[1], tA)];
      pB = [lerp(s1[0], s2[0], tB), lerp(s1[1], s2[1], tB)];
      pC = [lerp(s4[0], s3[0], tB), lerp(s4[1], s3[1], tB)];
      pD = [lerp(s4[0], s3[0], tA), lerp(s4[1], s3[1], tA)];

      oA1 = [lerp(x1, x2, tA), lerp(y1, y2, tA)];
      oB1 = [lerp(x1, x2, tB), lerp(y1, y2, tB)];
      oC1 = pB;
      oD1 = pA;

      oA2 = pD;
      oB2 = pC;
      oC2 = [lerp(x4, x3, tB), lerp(y4, y3, tB)];
      oD2 = [lerp(x4, x3, tA), lerp(y4, y3, tA)];
    }
    let cx = (pA[0] + pB[0] + pC[0] + pD[0]) * 0.25;
    let cy = (pA[1] + pB[1] + pC[1] + pD[1]) * 0.25;
    let foldWave = sin(tMid * 540 + (isVertical ? 30 : 110)) * 0.5 + 0.5;
    segs.push({
      pA, pB, pC, pD,
      oA1, oB1, oC1, oD1,
      oA2, oB2, oC2, oD2,
      cx, cy, foldWave,
      seed: baseSeed + i * 17
    });
  }

  // Prismatic diamond grid lines
  let gridSteps = isVertical ? 28 : 22;
  let gridLines = [];
  for (let i = 0; i <= gridSteps; i++) {
    let u = i / gridSteps;
    let uNext = min(1, (i + 3.5) / gridSteps);
    let uPrev = max(0, (i - 3.5) / gridSteps);
    if (isVertical) {
      let lx1 = lerp(s1[0], s4[0], u), ly1 = lerp(s1[1], s4[1], u);
      let rx2 = lerp(s2[0], s3[0], uNext), ry2 = lerp(s2[1], s3[1], uNext);
      let rx3 = lerp(s2[0], s3[0], uPrev), ry3 = lerp(s2[1], s3[1], uPrev);
      gridLines.push({
        x1: lx1, y1: ly1, x2: rx2, y2: ry2,
        x3: rx3, y3: ry3,
        cx: (lx1 + rx2) * 0.5, cy: (ly1 + ry2) * 0.5,
        seed: baseSeed + 500 + i * 13
      });
    } else {
      let tx1 = lerp(s1[0], s2[0], u), ty1 = lerp(s1[1], s2[1], u);
      let bx2 = lerp(s4[0], s3[0], uNext), by2 = lerp(s4[1], s3[1], uNext);
      let bx3 = lerp(s4[0], s3[0], uPrev), by3 = lerp(s4[1], s3[1], uPrev);
      gridLines.push({
        x1: tx1, y1: ty1, x2: bx2, y2: by2,
        x3: bx3, y3: by3,
        cx: (tx1 + bx2) * 0.5, cy: (ty1 + by2) * 0.5,
        seed: baseSeed + 500 + i * 13
      });
    }
  }

  // Spray sparkle clouds
  let sprays = [];
  let sprayCount = isVertical ? 44 : 34;
  for (let i = 0; i < sprayCount; i++) {
    let u = random(0.04, 0.96);
    let v = random(0.08, 0.92);
    let gx = lerp(lerp(s1[0], s2[0], u), lerp(s4[0], s3[0], u), v);
    let gy = lerp(lerp(s1[1], s2[1], u), lerp(s4[1], s3[1], u), v);
    let col = random(["#ffffff", "#ffffff", "#f5ffad", "#e0f7ff"]);
    sprays.push({
      x: gx, y: gy, col,
      phase: random(0, 360),
      seed: baseSeed + 1000 + i * 19
    });
  }

  // Glass-bead micro-dots and star-bursts
  let beads = [];
  let beadCount = isVertical ? 175 : 140;
  for (let i = 0; i < beadCount; i++) {
    let u = random(0.02, 0.98);
    let v = random(0.03, 0.97);
    let gx = lerp(lerp(s1[0], s2[0], u), lerp(s4[0], s3[0], u), v);
    let gy = lerp(lerp(s1[1], s2[1], u), lerp(s4[1], s3[1], u), v);
    let isStar = random(1) < 0.30;
    let col = random(["#ffffff", "#ffffff", "#f4ff99", "#d9f7ff"]);
    beads.push({
      x: gx, y: gy,
      dx: random(1.2, 2.8),
      dy: random(-0.7, 0.7),
      isStar,
      starR: random(7.0, 17.5),
      col,
      facetPhase: random(0, 360),
      seed: baseSeed + 2000 + i * 23
    });
  }

  return { x1, y1, x2, y2, x3, y3, x4, y4, s1, s2, s3, s4, isVertical, segs, gridLines, sprays, beads, baseSeed };
}

function initMotionData() {
  let bands = [
    // 0: Left Horizontal Band
    buildBandPrecomp(-20, 922, 582, 932, 582, 1068, -20, 1058, false, 11000),
    // 1: Right Horizontal Band
    buildBandPrecomp(618, 932, 1220, 922, 1220, 1058, 618, 1068, false, 22000),
    // 2: Left Vertical Band
    buildBandPrecomp(195, 538, 338, 518, 318, 1200, 172, 1200, true, 33000),
    // 3: Right Vertical Band
    buildBandPrecomp(862, 518, 1005, 538, 1028, 1200, 882, 1200, true, 44000)
  ];

  // Sub-panels of the fluorescent yellow-green vest (outside the reflective bands)
  // so the vest fabric itself blazes with a sweeping wave of chartreuse headlight illumination
  let vestZones = [
    // Left outer shoulder & upper arm (x = -25..190, y = 558..920)
    { p1: [-25, 625], p2: [188, 542], p3: [176, 920], p4: [-25, 918], cx: 80, cy: 735, seed: 51001 },
    // Left outer lower waist (x = -25..170, y = 1062..1200)
    { p1: [-25, 1062], p2: [172, 1066], p3: [170, 1200], p4: [-25, 1200], cx: 75, cy: 1130, seed: 51002 },
    // Left inner chest between vertical band and V-neck (x = 338..575, y = 518..928)
    { p1: [340, 518], p2: [385, 510], p3: [576, 892], p4: [324, 925], cx: 430, cy: 720, seed: 51003 },
    // Left inner lower waist between vertical band and zipper (x = 320..578, y = 1068..1200)
    { p1: [322, 1068], p2: [578, 1070], p3: [578, 1200], p4: [318, 1200], cx: 450, cy: 1135, seed: 51004 },
    // Right inner chest between V-neck and vertical band (x = 624..860, y = 518..928)
    { p1: [815, 510], p2: [860, 518], p3: [876, 925], p4: [624, 892], cx: 770, cy: 720, seed: 51005 },
    // Right inner lower waist between zipper and vertical band (x = 622..880, y = 1068..1200)
    { p1: [622, 1070], p2: [878, 1068], p3: [882, 1200], p4: [622, 1200], cx: 750, cy: 1135, seed: 51006 },
    // Right outer shoulder & upper arm (x = 1008..1225, y = 542..920)
    { p1: [1012, 542], p2: [1225, 625], p3: [1225, 918], p4: [1024, 920], cx: 1120, cy: 735, seed: 51007 },
    // Right outer lower waist (x = 1028..1225, y = 1062..1200)
    { p1: [1028, 1066], p2: [1225, 1062], p3: [1225, 1200], p4: [1030, 1200], cx: 1125, cy: 1130, seed: 51008 }
  ];

  // Precomputed breathable mesh pores on the vest so they stay crisp & glint inside lit vest zones
  let vestPores = [];
  randomSeed(52000);
  for (let y = 539; y < 1185; y += 22) {
    let rowShift = (floor(y / 11) % 2) * 5.5;
    for (let x = 26; x < 1175; x += 22) {
      let mx = x + rowShift;
      let vNeckEdgeX = map(y, 508, 892, 208, 0, true);
      if (abs(mx - 600) < vNeckEdgeX + 22) continue;
      let shoulderY = map(abs(mx - 600), 208, 640, 508, 622, true);
      if (y < shoulderY + 14) continue;
      if (y > 912 && y < 1072) continue;
      if (mx > 170 && mx < 345) continue;
      if (mx > 855 && mx < 1030) continue;
      vestPores.push({ x: mx, y, seed: 52100 + vestPores.length * 7 });
    }
  }

  // Helmet forehead retroreflective decal (x = 295..905)
  randomSeed(55000);
  noiseSeed(55000);
  let helmSegs = [];
  let hSteps = 24;
  for (let i = 0; i < hSteps; i++) {
    let tA = i / hSteps;
    let tB = (i + 1) / hSteps;
    let xA = lerp(295, 905, tA);
    let xB = lerp(295, 905, tB);
    let cA = sin(tA * 180) * 26;
    let cB = sin(tB * 180) * 26;
    helmSegs.push({
      topPin: [[xA, 168 - cA], [xB, 168 - cB], [xB, 178 - cB], [xA, 178 - cA]],
      silver: [[xA, 178 - cA], [xB, 178 - cB], [xB, 204 - cB], [xA, 204 - cA]],
      botPin: [[xA, 204 - cA], [xB, 204 - cB], [xB, 214 - cB], [xA, 214 - cA]],
      cx: (xA + xB) * 0.5,
      cy: 191 - (cA + cB) * 0.5,
      seed: 55100 + i * 17
    });
  }

  let helmBeads = [];
  for (let i = 0; i < 140; i++) {
    let t = random(0.02, 0.98);
    let x = lerp(300, 900, t);
    let curve = sin(t * 180) * 26;
    let y = random(179 - curve, 203 - curve);
    let isStar = random(1) < 0.32;
    helmBeads.push({
      x, y,
      isStar,
      starR: random(6.5, 15.0),
      col: random(["#ffffff", "#ffffff", "#f5ff9e", "#d9f7ff"]),
      facetPhase: random(0, 360),
      seed: 56000 + i * 19
    });
  }

  let helmSprays = [];
  for (let i = 0; i < 30; i++) {
    let t = random(0.05, 0.95);
    let x = lerp(305, 895, t);
    let y = 191 - sin(t * 180) * 26 + random(-4, 4);
    helmSprays.push({
      x, y,
      seed: 57500 + i * 23
    });
