// Helper to transform local head coordinates to canvas coordinates
function headPt(lx, ly) {
  const cx = 562, cy = 315, rot = -4.5;
  let c = cos(rot), s = sin(rot);
  return [cx + lx * c - ly * s, cy + lx * s + ly * c];
}

