function drawFacialPencilModeling() {
  // Forehead curved frontalis contour lines
  for (let i = 0; i < 160; i++) {
    let t = map(i, 0, 159, -172, -52);
    let span = map(abs(t + 110), 0, 65, 112, 82);
    let x1 = random(-span, 10);
    let x2 = min(span, x1 + random(28, 78));
    let xm = (x1 + x2) * 0.5;
    let arch = -8 * (1 - sq(xm / 120));
    let isShadow = xm > 25 || t < -150;
    let col = isShadow ? PALETTE.skinUmber : (xm < -15 ? PALETTE.skinMid : PALETTE.skinSienna);
    let w = isShadow ? random(0.45, 0.75) : random(0.28, 0.5);
    brush.set(i % 3 === 0 ? "2B" : "HB", col, w);
    let p1 = headPt(x1, t + sq(x1 / 90) * 10);
    let p2 = headPt(xm, t + arch + sq(xm / 90) * 10);
    let p3 = headPt(x2, t + sq(x2 / 90) * 10);
    brush.spline([p1, p2, p3], 0.5);
  }

  // Glabellar frown lines (vertical tension creases between eyebrows)
  for (let i = 0; i < 42; i++) {
    let lx = random(-24, 24);
    let ly1 = random(-78, -55);
    let ly2 = ly1 + random(18, 34);
    let col = abs(lx) < 10 ? PALETTE.skinDarkUmber : PALETTE.skinUmber;
    brush.set("rotring", col, random(0.35, 0.65));
    let p1 = headPt(lx, ly1);
    let p2 = headPt(lx * 0.85, (ly1 + ly2) * 0.5);
    let p3 = headPt(lx * 0.75, ly2);
    brush.spline([p1, p2, p3], 0.4);
  }

  // Cheekbone & Gaunt Cheek Cross-Hatching (Left and Right)
  for (let side of [-1, 1]) {
    for (let i = 0; i < 190; i++) {
      let u = random(0, 1);
      let v = random(0, 1);
      let lx = side * map(u, 0, 1, 32, 116);
      let ly = map(v, 0, 1, -8, 125);
      // Skip outside jaw contour
      if (abs(lx) > map(ly, -8, 125, 120, 88)) continue;

      // Determine tone by anatomical zone
      let inHollow = ly > 36 && ly < 110 && abs(lx) > 46;
      let onZygoma = ly >= -5 && ly <= 32 && abs(lx) > 42;
      if (onZygoma && side === -1 && random() < 0.7) continue; // Keep left cheekbone bright

      let col = PALETTE.skinMid;
      let bName = "HB";
      let w = random(0.3, 0.55);

      if (inHollow) {
        col = (side === 1 || random() < 0.6) ? PALETTE.skinDarkUmber : PALETTE.skinUmber;
        bName = "2B";
        w = random(0.45, 0.8);
      } else if (side === 1) {
        col = random() < 0.5 ? PALETTE.skinUmber : PALETTE.skinSienna;
      }

      brush.set(bName, col, w);
      let len = random(16, 36);
      // Primary contour angle sweeps from ear toward mouth/chin
      let ang = side === -1 ? random(28, 62) : random(118, 152);
      if (i % 3 === 0) ang += random(-35, 35); // Cross-hatch pass
      let p1 = headPt(lx, ly);
      let p2 = headPt(lx + cos(ang) * len * 0.5, ly + sin(ang) * len * 0.5 + 3);
      let p3 = headPt(lx + cos(ang) * len, ly + sin(ang) * len);
      brush.spline([p1, p2, p3], 0.4);
    }
  }

  // Chin & Jawline sculptural hatching
  for (let i = 0; i < 140; i++) {
    let lx = random(-85, 85);
    let jawY = 182 - sq(lx / 92) * 68;
    let ly = jawY - random(2, 42);
    let col = (ly > jawY - 16 || lx > 15) ? PALETTE.skinDarkUmber : PALETTE.skinUmber;
    brush.set(i % 2 === 0 ? "2B" : "HB", col, random(0.35, 0.7));
    let p1 = headPt(lx - 10, ly - 4);
    let p2 = headPt(lx, ly + 3);
    let p3 = headPt(lx + 10, ly - 2);
    brush.spline([p1, p2, p3], 0.5);
  }
}

function drawEyesAndBrows() {
  for (let side of [-1, 1]) {
    let ex = side * 56;
    let ey = -26;

    // Deep shadow under brow ridge
    for (let i = 0; i < 55; i++) {
      let x = ex + random(-38, 38);
      let y = ey + random(-24, -6);
      brush.set("2B", side === 1 ? PALETTE.skinDeepSepia : PALETTE.skinDarkUmber, random(0.4, 0.8));
      let p1 = headPt(x - 8, y);
      let p2 = headPt(x + 8, y + side * 2);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Eyebrow hairs (sweat-clumped, coarse sepia/umber strokes)
    for (let i = 0; i < 85; i++) {
      let t = random(0, 1);
      let bx = ex + side * map(t, 0, 1, -34, 38);
      let by = ey - 24 - sin(t * 180) * 7 + random(-4, 4);
      let ang = side === -1 ? map(t, 0, 1, -145, -195) : map(t, 0, 1, -35, 15);
      let len = random(9, 17);
      brush.set(i % 4 === 0 ? "rotring" : "2B", PALETTE.skinDeepSepia, random(0.4, 0.75));
      let p1 = headPt(bx, by);
      let p2 = headPt(bx + cos(ang) * len, by + sin(ang) * len);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Sclera (warm shaded eyeball, squinting against harsh midday sun)
    let eyeShape = [
      headPt(ex - side * 26, ey + 2),
      headPt(ex - side * 10, ey - 7),
      headPt(ex + side * 12, ey - 6),
      headPt(ex + side * 28, ey + 3),
      headPt(ex + side * 10, ey + 9),
      headPt(ex - side * 10, ey + 8)
    ];
    brush.noStroke();
    brush.wash(PALETTE.skinSalt, 210);
    drawBrushPoly(eyeShape, 0.3);

    // Iris (deep umber-amber)
    let irisPts = [];
    for (let a = 0; a < 360; a += 30) {
      irisPts.push(headPt(ex + cos(a) * 9.5, ey + 0.5 + sin(a) * 7.5));
    }
    brush.wash(PALETTE.skinDarkUmber, 235);
    drawBrushPoly(irisPts, 0.3);
    brush.noWash();

    // Pupil & iris radial striations
    for (let a = 0; a < 360; a += 18) {
      let p1 = headPt(ex + cos(a) * 2, ey + 0.5 + sin(a) * 2);
      let p2 = headPt(ex + cos(a) * 9, ey + 0.5 + sin(a) * 7);
      brush.set("rotring", a % 36 === 0 ? PALETTE.skinDeepSepia : PALETTE.skinSienna, 0.45);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Upper eyelid heavy fold & lash line
    brush.set("rotring", PALETTE.skinDeepSepia, 0.95);
    brush.spline([
      headPt(ex - side * 28, ey + 3),
      headPt(ex - side * 8, ey - 8),
      headPt(ex + side * 12, ey - 7),
      headPt(ex + side * 29, ey + 4)
    ], 0.5);

    // Upper eyelid crease
    brush.set("2B", PALETTE.skinDarkUmber, 0.65);
    brush.spline([
      headPt(ex - side * 26, ey - 4),
      headPt(ex, ey - 14),
      headPt(ex + side * 27, ey - 2)
    ], 0.5);

    // Exhausted lower eyelid bags & tear trough creases
    for (let bag = 1; bag <= 3; bag++) {
      let offY = bag * 5.5;
      brush.set(bag === 1 ? "rotring" : "HB", bag === 1 ? PALETTE.skinDarkUmber : PALETTE.skinUmber, 0.55 - bag * 0.1);
      brush.spline([
        headPt(ex - side * 25, ey + 3 + offY * 0.6),
