// Draws a full-height bread slice extending down by zExtend below zSlot for emerging lower-slice texture
function drawFullSliceBody(pMin, pMax, index, zExtend) {
  const sp = getSliceParams(pMin, pMax, index);
  const { u0, u1, vFront, vBack, zSlot, zShoulder, zPeak, frontArch, backArch } = sp;
  const zBot = zSlot - zExtend;

  const crustStrip = [
    proj(u0, vFront, zBot),
    proj(u0, vBack, zBot),
    proj(u0, vBack, zSlot),
    proj(u0 - 5, vBack, zShoulder - 12),
    ...backArch,
    ...frontArch.slice().reverse(),
    proj(u0 - 5, vFront, zShoulder - 12),
    proj(u0, vFront, zSlot)
  ];
  drawPoly(crustStrip, {
    wash: PAL.tomatoDeep,
    washOpacity: 230,
    fill: PAL.tomatoDark,
    fillOpacity: 145,
    bleed: 0.04,
    texture: 0.85,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardDeep,
    hatchWeight: 1.0,
    hatchDist: 5,
    hatchAngle: -32,
    hatch2Brush: "fine_crayon",
    hatch2Color: PAL.tomatoDark,
    hatch2Weight: 0.9,
    hatch2Dist: 6,
    hatch2Angle: 45,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealNight,
    strokeWeight: 0.95
  });

  for (let i = 3; i < frontArch.length - 2; i++) {
    brush.set("fine_crayon", PAL.mustardLight, 1.35);
    brush.line(
      lerp(frontArch[i][0], backArch[i][0], 0.35),
      lerp(frontArch[i][1], backArch[i][1], 0.35),
      lerp(frontArch[i + 1][0], backArch[i + 1][0], 0.35),
      lerp(frontArch[i + 1][1], backArch[i + 1][1], 0.35)
    );
  }

  const breadFacePts = [
    proj(u0, vFront, zBot),
    proj(u0, vFront, zSlot),
    proj(u0 - 5, vFront, zShoulder - 12),
    ...frontArch,
    proj(u1 + 5, vFront, zShoulder - 12),
    proj(u1, vFront, zSlot),
    proj(u1, vFront, zBot)
  ];
  drawPoly(breadFacePts, {
    wash: PAL.creamWarm,
    washOpacity: 225,
    fill: PAL.mustardLight,
    fillOpacity: 145,
    bleed: 0.05,
    texture: 0.88,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardBright,
    hatchWeight: 1.0,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.creamBright,
    hatch2Weight: 0.85,
    hatch2Dist: 7,
    hatch2Angle: -68,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tomatoDeep,
    strokeWeight: 1.15
  });

  const innerArch = [];
  for (let i = 1; i <= 15; i++) {
    const t = i / 16;
    const u = lerp(u0 + 22, u1 - 22, t);
    const swell = Math.pow(Math.sin(t * Math.PI), 0.7);
    const z = (zShoulder - 10) + (zPeak - 22 - (zShoulder - 10)) * swell;
    innerArch.push(proj(u, vFront - 0.5, z));
  }
  const toastedCenterPts = [
    proj(u0 + 20, vFront - 0.5, zBot + 10),
    ...innerArch,
    proj(u1 - 20, vFront - 0.5, zBot + 10)
  ];
  drawPoly(toastedCenterPts, {
    fill: PAL.mustardMid,
    fillOpacity: 175,
    bleed: 0.14,
    texture: 0.9,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.tomatoMid,
    hatchWeight: 0.95,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.mustardDeep,
    hatch2Weight: 0.9,
    hatch2Dist: 7,
    hatch2Angle: -68
  });

  const charCenterPts = [
    proj(u0 + 48, vFront - 1, zBot + 16),
    proj(u0 + 55, vFront - 1, zPeak - 38),
    proj((u0 + u1) * 0.5, vFront - 1, zPeak - 28),
    proj(u1 - 55, vFront - 1, zPeak - 38),
    proj(u1 - 48, vFront - 1, zBot + 16)
  ];
  drawPoly(charCenterPts, {
    fill: PAL.tomatoMid,
    fillOpacity: 115,
    bleed: 0.2,
    texture: 0.9,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDeep,
    hatchWeight: 0.85,
    hatchDist: 6,
    hatchAngle: -68
  });

  for (const wf of [0.28, 0.50, 0.72]) {
    const uw = lerp(u0, u1, wf);
    const pBot = proj(uw, vFront - 1, zBot + 8);
