    brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
    brush.set("fine_crayon", PAL.creamWarm, 0.8);
    brush.line(pBot[0] + 1, pBot[1], pTop[0] + 1, pTop[1]);
  }

  for (let k = 0; k < 220; k++) {
    const tu = random(0.06, 0.94);
    const u = lerp(u0, u1, tu);
    const maxZ = zShoulder - 8 + (zPeak - 16 - (zShoulder - 8)) * Math.pow(Math.sin(tu * Math.PI), 0.7);
    const z = random(zBot + 8, maxZ);
    const pt = proj(u, vFront - 1, z);
    const distCenter = Math.abs(tu - 0.5) * 2;
    const poreCol = distCenter < 0.55
      ? (random() < 0.55 ? PAL.tomatoDeep : PAL.mustardDeep)
      : (random() < 0.6 ? PAL.mustardMid : PAL.creamBright);
    brush.set("crumb_crayon", poreCol, random(0.55, 1.15));
    brush.line(pt[0], pt[1], pt[0] + random(-2.5, 2.5), pt[1] + random(-2.0, 2.0));
  }
}

// ============================================================================
// MOTION KINEMATICS (Spring Pop, Free-Flight Hop, Settle, and Lever Coupling)
// ============================================================================
function computeSliceKinematics(t, isFar) {
  // Slight phase lead for the far slice so the two slices feel independent
  const ts = Math.max(0, t * (isFar ? 1.04 : 1.0));
  const restDz = isFar ? 61.0 : 65.0;
  const peakHop = isFar ? 82.0 : 88.0;
  const dipLow = isFar ? 47.0 : 50.0;

  let dz = 0;
  let rot = 0;

  if (ts < 0.34) {
    // Brisk spring launch & upward hop past the carriage stop
    const u = ts / 0.34;
    const ease = u * u * (3 - 2 * u);
    const boost = Math.pow(u, 1.35) * (1 - u) * 0.85 + ease;
    dz = peakHop * Math.min(1, boost);
    rot = (isFar ? 2.6 : -3.4) * Math.sin(u * Math.PI * 0.85);
  } else if (ts < 0.64) {
    // Slices settle down from free-flight hop onto the spring carriage rack
    const u = (ts - 0.34) / 0.30;
    const ease = 0.5 - 0.5 * Math.cos(u * Math.PI);
    dz = lerp(peakHop, dipLow, ease);
    rot = lerp(isFar ? 2.3 : -3.0, isFar ? -0.9 : 1.2, ease);
  } else {
    // Damped spring oscillation on the carriage rack through 2.0s
    const dt = ts - 0.64;
    const env = Math.exp(-3.4 * dt);
    dz = restDz - (restDz - dipLow) * env * Math.cos(dt * 12.5);
    rot = (isFar ? -0.9 : 1.2) * env * Math.cos(dt * 12.5 + 0.3);
  }

  return { dz, rot };
}

function getMotionState(t) {
  const nearK = computeSliceKinematics(t, false);
  const farK = computeSliceKinematics(t, true);

  // Carriage lever shoots up from zLever = 204 to top of channel (z = 250, dLever = +46)
  // and dips slightly when the hopping toast slices land back on the rack around t = 0.62s
  let dLever = 0;
  if (t < 0.25) {
    const u = t / 0.25;
    const ease = u * u * (3 - 2 * u);
    dLever = 47.0 * ease;
  } else if (t < 0.45) {
    const u = (t - 0.25) / 0.20;
    dLever = 45.0 + 2.0 * Math.cos(u * Math.PI * 2);
  } else if (t < 0.74) {
    const u = (t - 0.45) / 0.29;
    // Slight downward impulse when the toast slices land back on the carriage at t = 0.60s
    const dip = Math.sin(u * Math.PI);
    dLever = 45.0 - 8.5 * dip * dip;
  } else {
    const dt = t - 0.74;
    dLever = 44.5 + 2.2 * Math.exp(-4.0 * dt) * Math.sin(dt * 14.0);
  }

  return {
    dzNear: nearK.dz,
    rotNear: nearK.rot,
    dzFar: farK.dz,
    rotFar: farK.rot,
    dLever
  };
}

// ============================================================================
// PER-FRAME COMPOSITING & LIVE P5.BRUSH OVERLAYS
// ============================================================================
function updateCompositeLayer(ms, t) {
  const ctx = compPG.drawingContext;
  ctx.clearRect(0, 0, 1200, 1200);

  // 1. Stamp the clean uncovered patch over Frame 0 toast & lever footprints
  compPG.image(maskedCleanPatchPG, 0, 0, 1200, 1200);

  const farP = getSliceParams(0.045, 0.215, 1);
  const nearP = getSliceParams(-0.215, -0.045, 0);

  // 2. Draw Far Toast Slice clipped strictly above the Far Slot opening
  drawClippedSliceOnComp(ctx, farSliceSprite, farP, ms.dzFar, ms.rotFar);

  // 3. Draw Near Toast Slice clipped strictly above the Near Slot opening
  drawClippedSliceOnComp(ctx, nearSliceSprite, nearP, ms.dzNear, ms.rotNear);
}

function drawClippedSliceOnComp(ctx, spritePG, sp, dz, rotDeg) {
  // Compute screen-space shift from 3D vertical offset dz at slice center
  const p0 = sp.pivot;
  const pShift = proj(0.5 * (sp.u0 + sp.u1), sp.vCenter, sp.zSlot + dz);
  const dx = pShift[0] - p0[0];
  const dy = pShift[1] - p0[1];

  ctx.save();
  // Clip to the half-space above the slot mouth polyline:
  // left of baseLine1 -> baseLine1 -> baseLine0 -> backCorner -> upper-right
  const b1 = sp.baseLine1;
  const b0 = sp.baseLine0;
  const bc = sp.backCorner;
  const dirX = b0[0] - b1[0];
  const dirY = b0[1] - b1[1];

  ctx.beginPath();
  ctx.moveTo(b1[0] - dirX * 0.35, b1[1] - dirY * 0.35 + 1);
  ctx.lineTo(b1[0], b1[1] + 1);
  ctx.lineTo(b0[0], b0[1] + 1);
  ctx.lineTo(bc[0] + 14, bc[1] - 6);
  ctx.lineTo(bc[0] + 80, 0);
  ctx.lineTo(0, 0);
  ctx.closePath();
  ctx.clip();

  // Translate and rotate around the slice pivot at the slot mouth
  ctx.translate(p0[0] + dx, p0[1] + dy);
  ctx.rotate((rotDeg * Math.PI) / 180);
  ctx.translate(-p0[0], -p0[1]);

  compPG.image(spritePG, 0, 0, 1200, 1200);
  ctx.restore();
}

function drawSlotRimsAndGlow(ms, t) {
  const farP = getSliceParams(0.045, 0.215, 1);
  const nearP = getSliceParams(-0.215, -0.045, 0);

  // Warm nichrome heating element flare during the pop
  const glowPulse = Math.sin(constrain(t / 1.4, 0, 1) * Math.PI);

  for (const sp of [farP, nearP]) {
    randomSeed(8100 + sp.index * 77);
    noiseSeed(8100 + sp.index * 77);

    // Glowing nichrome wire glint at front end of slot
    const glowA0 = toasterShellPt(0.14, (sp.pMin + sp.pMax) * 0.5, 0);
    const glowA1 = toasterShellPt(0.19, (sp.pMin + sp.pMax) * 0.5, 0);
    brush.set("fine_crayon", PAL.mustardBright, 1.3 + 0.35 * glowPulse);
    brush.line(glowA0[0], glowA0[1], glowA1[0], glowA1[1]);

    // Crisp dark toasted rim where the slice emerges from the slot mouth
