// ============================================================================
// FLYING & BOUNCING 3D TOASTED CRUMBS
// ============================================================================
function initFlyingCrumbs() {
  randomSeed(6319);
  noiseSeed(6319);
  flyingCrumbs = [];

  const types = ["crust", "toasted", "crumb"];
  for (let i = 0; i < 18; i++) {
    const fromFarSlot = i % 2 === 1;
    const t0 = 0.02 + (i / 18) * 0.24 + random(-0.01, 0.01);
    const uStart = lerp(65, 295, random(0.08, 0.92));
    const vStart = fromFarSlot ? random(132, 162) : random(76, 106);
    const zStart = TOASTER_H + random(8, 52);

    // Target landing zone on the generous sweep of countertop to the front and right
    const landFront = i < 5;
    const uTarget = landFront ? random(-115, 55) : random(-75, 315);
    const vTarget = landFront ? random(45, 255) : random(255, 665);
    const flightDur = random(0.48, 0.72);
    const vz0 = random(230, 390);

    flyingCrumbs.push({
      id: i,
      seed: 12000 + i * 71,
      t0,
      uStart,
      vStart,
      zStart,
      vu: (uTarget - uStart) / flightDur,
      vv: (vTarget - vStart) / flightDur,
      vz0,
      gravity: 1320,
      size: random(3.0, 6.8),
      type: types[i % 3],
      spinRate: random(-320, 320)
    });
  }
}

function getCrumb3DState(c, t) {
  const dt = t - c.t0;
  if (dt <= 0) return null;

  // Compute time of first impact with countertop z = 0:
  // zStart + vz0 * t1 - 0.5 * g * t1^2 = 0
  const g = c.gravity;
  const disc = c.vz0 * c.vz0 + 2 * g * c.zStart;
  const tImpact1 = (c.vz0 + Math.sqrt(disc)) / g;
  const vImpact1 = Math.sqrt(disc);

  // Two subsequent bounces with restitution e = 0.43
  const e1 = 0.43;
  const vz1 = vImpact1 * e1;
  const durB1 = (2 * vz1) / g;

  const e2 = 0.36;
  const vz2 = vz1 * e2;
  const durB2 = (2 * vz2) / g;

  let z = 0;
  let horizTime = dt;
  let activeSpin = dt;

  if (dt < tImpact1) {
    // Primary ballistic arc from toaster slot to countertop
    z = c.zStart + c.vz0 * dt - 0.5 * g * dt * dt;
  } else if (dt < tImpact1 + durB1) {
    // First bounce on the speckled laminate
    const tb = dt - tImpact1;
    z = vz1 * tb - 0.5 * g * tb * tb;
    horizTime = tImpact1 + tb * 0.55;
    activeSpin = tImpact1 + tb * 0.6;
  } else if (dt < tImpact1 + durB1 + durB2) {
    // Second smaller bounce
    const tb = dt - (tImpact1 + durB1);
    z = vz2 * tb - 0.5 * g * tb * tb;
    horizTime = tImpact1 + durB1 * 0.55 + tb * 0.28;
    activeSpin = tImpact1 + durB1 * 0.6 + tb * 0.3;
  } else {
    // Resting on the countertop
    z = 0;
    horizTime = tImpact1 + durB1 * 0.55 + durB2 * 0.28;
    activeSpin = tImpact1 + durB1 * 0.6 + durB2 * 0.3;
  }

  const u = c.uStart + c.vu * horizTime;
  const v = c.vStart + c.vv * horizTime;
  const spin = activeSpin * c.spinRate;
  const fadeIn = constrain(dt / 0.06, 0.25, 1.0);

  return { u, v, z: Math.max(0, z), spin, fadeIn };
}

function drawFlyingCrumbs(t) {
  for (const c of flyingCrumbs) {
    const st = getCrumb3DState(c, t);
    if (!st) continue;

    randomSeed(c.seed);
    noiseSeed(c.seed);

    const ptBody = proj(st.u, st.v, st.z);
    const persp = map(ptBody[1], 520, 1150, 0.68, 1.28, true);
    const r = c.size * persp * st.fadeIn;

    // 1. If crumb is near or on the countertop, draw its shadow on the z = 0 counter plane
    if (st.v > 210 || st.u < 5) {
      const shU = st.u + st.z * 0.08;
      const shV = st.v + st.z * 0.52;
      const ptSh = proj(shU, shV, 0);
      const shScale = map(st.z, 0, 260, 1.0, 0.55, true);
      const shOp = map(st.z, 0, 260, 205, 85, true);
      const sr = r * shScale;

      const shPoly = [
        [ptSh[0] - sr * 0.9, ptSh[1]],
        [ptSh[0] + sr * 1.3, ptSh[1] - sr * 0.35],
        [ptSh[0] + sr * 1.1, ptSh[1] + sr * 0.45],
        [ptSh[0] - sr * 0.6, ptSh[1] + sr * 0.55]
      ];
      drawPoly(shPoly, {
        wash: PAL.tealNight,
        washOpacity: shOp
      });
    }

    // 2. Build 6-vertex craggy 3D crumb silhouette rotated by st.spin while airborne
    const nVerts = 6;
    const basePts = [];
    for (let i = 0; i < nVerts; i++) {
      const ang = (i / nVerts) * 360 + random(-16, 16) + st.spin * 0.35;
      const radX = r * random(0.7, 1.22);
      const radY = r * random(0.48, 0.85);
      basePts.push([
        ptBody[0] + cos(ang) * radX,
        ptBody[1] + sin(ang) * radY
      ]);
    }
    const peakX = ptBody[0] + random(-r * 0.22, r * 0.15);
    const peakY = ptBody[1] - r * random(0.38, 0.68);

    const inShadow = st.z < 25 && st.u > -5 && st.u < 365 && st.v > 225;
    let litCol, midCol, shadeCol, rimCol;
    if (c.type === "crust") {
      litCol = inShadow ? PAL.mustardDeep : PAL.tomatoBright;
      midCol = PAL.tomatoMid;
      shadeCol = PAL.tomatoDark;
      rimCol = PAL.mustardLight;
    } else if (c.type === "toasted") {
      litCol = inShadow ? PAL.mustardMid : PAL.mustardBright;
      midCol = inShadow ? PAL.mustardDeep : PAL.mustardLight;
      shadeCol = PAL.tomatoDeep;
      rimCol = PAL.creamBright;
    } else {
      litCol = inShadow ? PAL.creamMid : PAL.creamBright;
      midCol = inShadow ? PAL.mustardMid : PAL.mustardLight;
      shadeCol = inShadow ? PAL.tealDeep : PAL.mustardDeep;
      rimCol = PAL.creamBright;
    }

    const shadeFacet = [
      [peakX, peakY],
      basePts[5],
      basePts[0],
      basePts[1],
      basePts[2]
    ];
    drawPoly(shadeFacet, {
      wash: shadeCol,
      washOpacity: 235
    });

    const litFacet = [
      [peakX, peakY],
      basePts[1],
      basePts[2],
      basePts[3],
      basePts[4]
    ];
    drawPoly(litFacet, {
      wash: litCol,
      washOpacity: 240,
      hatchBrush: "crumb_crayon",
      hatchColor: midCol,
      hatchWeight: 0.7,
      hatchDist: 3,
      hatchAngle: 25
    });

    brush.set("crumb_crayon", PAL.tealNight, 0.9);
    brush.line(basePts[0][0], basePts[0][1], basePts[1][0], basePts[1][1]);
    brush.set("crumb_crayon", rimCol, 0.95);
    brush.line(basePts[3][0], basePts[3][1], peakX, peakY);
  }
}

// ============================================================================
// CURLING RIBBONS OF EARLY-MORNING TOAST STEAM
// ============================================================================
function drawMorningSteam(ms, t) {
  if (t <= 0.01) return;

  const plumes = [
    { uFrac: 0.34, isFar: false, phase: 0.0, amp: 9.5, col: PAL.creamBright, w: 1.05, seed: 7701 },
    { uFrac: 0.56, isFar: false, phase: 1.4, amp: 11.5, col: PAL.mustardBright, w: 0.95, seed: 7702 },
    { uFrac: 0.73, isFar: false, phase: 2.7, amp: 8.5, col: PAL.creamWarm, w: 0.90, seed: 7703 },
    { uFrac: 0.30, isFar: true,  phase: 0.8, amp: 9.0, col: PAL.creamWarm, w: 0.90, seed: 7704 },
    { uFrac: 0.52, isFar: true,  phase: 2.1, amp: 11.0, col: PAL.creamBright, w: 1.05, seed: 7705 },
    { uFrac: 0.70, isFar: true,  phase: 3.5, amp: 9.5, col: PAL.mustardBright, w: 0.88, seed: 7706 }
  ];

  // Steam grows smoothly from 0 at t=0 up to 135px tall wisps drifting up-right along the morning light beam
  const maxRise = 138 * Math.pow(constrain(t / 1.35, 0, 1), 0.78);
  if (maxRise < 4) return;

  for (const pl of plumes) {
    randomSeed(pl.seed);
    noiseSeed(pl.seed);

    const sp = pl.isFar
      ? getSliceParams(0.045, 0.215, 1)
      : getSliceParams(-0.215, -0.045, 0);
    const dz = pl.isFar ? ms.dzFar : ms.dzNear;

    const u = lerp(sp.u0, sp.u1, pl.uFrac);
    const swell = Math.sin(pl.uFrac * Math.PI);
    const zBase = sp.zShoulder + (sp.zPeak - sp.zShoulder) * swell + dz - 6;
    const startPt = proj(u, sp.vFront, zBase);

    const pts = [];
    const steps = 9;
    for (let i = 0; i <= steps; i++) {
      const f = i / steps;
      const dist = f * maxRise;
      // Drift diagonally up and right (-64 deg from +x, matching the morning sunbeam on the wall)
      const driftX = dist * 0.46;
      const driftY = -dist * 0.92;
      const wave = Math.sin(f * 4.2 - t * 5.2 + pl.phase) * pl.amp * Math.pow(f, 0.75);
      const px = startPt[0] + driftX + wave;
      const py = startPt[1] + driftY + wave * 0.35;
      const press = Math.sin(f * Math.PI) * 0.95 + 0.15;
      pts.push([px, py, press]);
    }

    // Soft dry-crayon outer wisp
    brush.set("dry_crayon", pl.col, pl.w * 0.62);
    brush.spline(pts, 0.55);

    // Crisp fine-crayon inner core filament
    brush.set("fine_crayon", PAL.creamBright, pl.w * 0.58);
    brush.spline(pts.map(p => [p[0] - 1.5, p[1] - 1.0, p[2] * 0.85]), 0.55);
  }
}

