// ============================================================================
// 6. CHROME BODY & WARPED STYLISED KITCHEN WINDOW REFLECTION
// ============================================================================
// Determines the exact color & secondary hatch of the warped reflection at (uFrac, p)
function getChromeReflectionStyle(uFrac, p) {
  // Longitudinal curvature warps the reflection bands downward near the front and back corners
  const endCurve = Math.pow(Math.abs(uFrac - 0.5) * 2, 2.2) * 0.095;
  const pW = p + endCurve;

  // Vertical window mullions warp as they climb the curved chrome flank
  const mullionShift = (p + 0.65) * 0.14 * (uFrac - 0.5);
  const uW = uFrac + mullionShift;
  const nearMullion =
    Math.abs(uW - 0.14) < 0.032 ||
    Math.abs(uW - 0.43) < 0.028 ||
    Math.abs(uW - 0.72) < 0.028 ||
    Math.abs(uW - 0.91) < 0.032;

  // 1. Bottom rim reflecting bakelite & dark counter crevice
  if (pW < -0.91) {
    return {
      wash: PAL.tealNight,
      washOp: 215,
      hatch: PAL.tomatoDark,
      hatch2: PAL.tealDeep,
      weight: 0.85
    };
  }
  // 2. Lower belly reflecting the sunlit speckled laminate counter
  if (pW < -0.80) {
    return {
      wash: PAL.mustardMid,
      washOp: 165,
      hatch: PAL.creamWarm,
      hatch2: PAL.tomatoMid,
      weight: 0.85
    };
  }
  // 3. Reflection of dark teal kitchen wall below the window sill
  if (pW < -0.71) {
    return {
      wash: PAL.tealDeep,
      washOp: 195,
      hatch: PAL.avocadoDeep,
      hatch2: PAL.tealNight,
      weight: 0.9
    };
  }
  // 4. Warped Window Sill Band (Tomato Red & Mustard)
  if (pW < -0.66) {
    return {
      wash: PAL.tomatoMid,
      washOp: 185,
      hatch: PAL.mustardLight,
      hatch2: PAL.tomatoDeep,
      weight: 0.85
    };
  }
  // 5. Lower Window Pane Row: Stylised Avocado Morning Foliage & Mustard Horizon
  if (pW < -0.52) {
    if (nearMullion) {
      return {
        wash: PAL.tealDeep,
        washOp: 190,
        hatch: PAL.tealMid,
        hatch2: PAL.avocadoDark,
        weight: 0.85
      };
    }
    if (pW < -0.59) {
      // Stylised avocado foliage band in lower window
      return {
        wash: PAL.avocadoMid,
        washOp: 175,
        hatch: PAL.avocadoLight,
        hatch2: PAL.mustardMid,
        weight: 0.85
      };
    } else {
      // Golden mustard early-morning sky band
      return {
        wash: PAL.mustardLight,
        washOp: 175,
        hatch: PAL.mustardBright,
        hatch2: PAL.creamWarm,
        weight: 0.85
      };
    }
  }
  // 6. Horizontal Window Sash Bar (Dusty Teal)
  if (pW < -0.47) {
    return {
      wash: PAL.tealMid,
      washOp: 185,
      hatch: PAL.tealDeep,
      hatch2: PAL.creamMid,
      weight: 0.85
    };
  }
  // 7. Upper Window Pane Row: Luminous Warm Cream Sky & Tomato Red Curtain Valance
  if (pW < -0.34) {
    if (nearMullion) {
      return {
        wash: PAL.tealMid,
        washOp: 175,
        hatch: PAL.tealDeep,
        hatch2: PAL.mustardMid,
        weight: 0.8
      };
    }
    // Scalloped wave of the mid-century tomato-red café curtain valance
    const scallop = Math.sin(uW * 360 * 3.5) * 0.018;
    if (pW > -0.39 + scallop) {
      return {
        wash: PAL.tomatoBright,
        washOp: 185,
        hatch: PAL.tomatoMid,
        hatch2: PAL.mustardLight,
        weight: 0.85
      };
    }
    return {
      wash: PAL.creamBright,
      washOp: 195,
      hatch: PAL.mustardBright,
      hatch2: PAL.creamWarm,
      weight: 0.9
    };
  }
  // 8. Tight Shoulder Turn: Razor-bright Cream Specular Band & Deep Teal Ceiling Contrast
  if (pW < -0.28) {
    return {
      wash: PAL.creamBright,
      washOp: 220,
      hatch: PAL.creamBright,
      hatch2: PAL.mustardBright,
      weight: 0.95
    };
  }
  if (pW < -0.19) {
    return {
      wash: PAL.tealDeep,
      washOp: 205,
      hatch: PAL.tealNight,
      hatch2: PAL.tealMid,
      weight: 0.9
    };
  }
  // 9. Top Crown Deck (reflecting dusky ceiling + warm glow near toast slots)
  if (p < 0.25) {
    const nearSlots = Math.abs(p) < 0.22 && uFrac > 0.14 && uFrac < 0.86;
    if (nearSlots) {
      return {
        wash: PAL.mustardMid,
        washOp: 165,
        hatch: PAL.tomatoBright,
        hatch2: PAL.creamWarm,
        weight: 0.85
      };
    }
    return {
      wash: PAL.tealLight,
      washOp: 165,
      hatch: PAL.creamWarm,
      hatch2: PAL.tealMid,
      weight: 0.8
    };
  }
  // 10. Far-right shoulder turn
  return {
    wash: PAL.avocadoMid,
    washOp: 175,
    hatch: PAL.tealDeep,
    hatch2: PAL.mustardMid,
    weight: 0.85
  };
}

function drawChromeBodyAndReflections() {
  // Rear bakelite handle nub peeking out at back-left end (uFrac = 1)
  const rearHandlePts = [
    proj(TOASTER_L + 2, TOASTER_W * 0.36, 175),
    proj(TOASTER_L + 26, TOASTER_W * 0.42, 185),
    proj(TOASTER_L + 24, TOASTER_W * 0.42, 235),
    proj(TOASTER_L - 2, TOASTER_W * 0.38, 255)
  ];
  drawPoly(rearHandlePts, {
    wash: PAL.tealNight,
    washOpacity: 230,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDark,
    hatchWeight: 0.9,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.mustardMid,
    strokeWeight: 0.8
  });

  // A. Render the Main Curved Chrome Shell (uFrac from 0 to 1, p from -1.0 to +0.34)
  const uSteps = 18;
  const pValues = [
    -1.0, -0.91, -0.80, -0.71, -0.66, -0.59, -0.52, -0.47,
    -0.39, -0.34, -0.28, -0.19, -0.08, 0.08, 0.22, 0.34
  ];

  for (let ip = 0; ip < pValues.length - 1; ip++) {
    const p0 = pValues[ip];
    const p1 = pValues[ip + 1];
    const pMid = 0.5 * (p0 + p1);

    for (let iu = 0; iu < uSteps; iu++) {
      const u0 = iu / uSteps;
      const u1 = (iu + 1) / uSteps;
      const uMid = 0.5 * (u0 + u1);

      const quad = [
        toasterShellPt(u0, p0),
        toasterShellPt(u1, p0),
        toasterShellPt(u1, p1),
        toasterShellPt(u0, p1)
      ];

      const st = getChromeReflectionStyle(uMid, pMid);
      drawPoly(quad, {
        wash: st.wash,
        washOpacity: st.washOp,
        fill: st.wash,
        fillOpacity: 65,
        bleed: 0.12,
        texture: 0.78,
        hatchBrush: "dry_crayon",
        hatchColor: st.hatch,
        hatchWeight: st.weight,
        hatchDist: 6,
        hatchAngle: 21,
        hatch2Brush: "fine_crayon",
        hatch2Color: st.hatch2,
        hatch2Weight: st.weight * 0.72,
        hatch2Dist: 9,
        hatch2Angle: -68
      });
    }
  }

  // B. Render the Front Control Chrome End-Cap (uFrac = 0, wrapping across p in [-1, +1])
  // We divide the front end-panel vertically by height zNorm and horizontally across width s
  const zBands = [
    { z0: 0.00, z1: 0.12, wash: PAL.tealNight, hatch: PAL.tomatoDark, hatch2: PAL.tealDeep },
    { z0: 0.12, z1: 0.28, wash: PAL.mustardMid, hatch: PAL.creamWarm, hatch2: PAL.avocadoMid },
    { z0: 0.28, z1: 0.42, wash: PAL.tealDeep, hatch: PAL.tealMid, hatch2: PAL.avocadoDark },
    { z0: 0.42, z1: 0.50, wash: PAL.tomatoMid, hatch: PAL.mustardLight, hatch2: PAL.tomatoDeep },
    { z0: 0.50, z1: 0.67, wash: PAL.avocadoMid, hatch: PAL.mustardLight, hatch2: PAL.tealMid },
    { z0: 0.67, z1: 0.84, wash: PAL.mustardLight, hatch: PAL.creamBright, hatch2: PAL.mustardMid },
    { z0: 0.84, z1: 0.93, wash: PAL.creamBright, hatch: PAL.creamBright, hatch2: PAL.mustardBright },
    { z0: 0.93, z1: 1.00, wash: PAL.tealMid, hatch: PAL.creamWarm, hatch2: PAL.tealDeep }
  ];

  function frontCapPt(sFrac, zNorm) {
    // Profile width narrows along the upper shoulder
    let halfW = 1.0;
    if (zNorm > 0.70) {
      const t = (zNorm - 0.70) / 0.30;
      halfW = Math.cos(t * Math.PI * 0.48) * 0.96 + 0.04;
    } else {
      halfW = 1.0 + 0.04 * Math.sin((zNorm / 0.70) * Math.PI);
    }
    const s = sFrac * halfW;
    const v = (0.5 + 0.5 * s) * TOASTER_W;
    const z = 48 + zNorm * (TOASTER_H - 48);
    const uBulge = -19 * Math.sin(Math.PI * zNorm * 0.9) * Math.cos(s * Math.PI * 0.42);
    return proj(uBulge, v, z);
  }

  const sSlices = 10;
  for (const b of zBands) {
    for (let is = 0; is < sSlices; is++) {
      const s0 = -1 + (2 * is) / sSlices;
      const s1 = -1 + (2 * (is + 1)) / sSlices;
      const sMid = 0.5 * (s0 + s1);
      const quad = [
        frontCapPt(s0, b.z0),
        frontCapPt(s1, b.z0),
        frontCapPt(s1, b.z1),
        frontCapPt(s0, b.z1)
      ];
      // Right side of front cap falls into slightly deeper dusky teal shade
      const isRightSide = sMid > 0.25;
      drawPoly(quad, {
        wash: isRightSide ? PAL.tealDeep : b.wash,
        washOpacity: 185,
        fill: b.wash,
        fillOpacity: 75,
        bleed: 0.1,
        hatchBrush: "dry_crayon",
        hatchColor: b.hatch,
        hatchWeight: 0.85,
        hatchDist: 6,
        hatchAngle: -22,
        hatch2Brush: "fine_crayon",
        hatch2Color: b.hatch2,
        hatch2Weight: 0.65,
        hatch2Dist: 9,
        hatch2Angle: 68
      });
    }
  }

  // C. Sweeping Soft-Band Crayon Overlays to Emphasize the Warped Window Reflection
  // Long continuous crayon splines following the toaster's curved flank
  const splinePBands = [
    { p: -0.84, col: PAL.creamWarm, w: 1.4 },
    { p: -0.68, col: PAL.tomatoBright, w: 1.8 },
    { p: -0.56, col: PAL.mustardBright, w: 1.7 },
    { p: -0.42, col: PAL.creamBright, w: 2.2 },
    { p: -0.37, col: PAL.tomatoBright, w: 1.6 },
    { p: -0.31, col: PAL.creamBright, w: 2.6 },
    { p: -0.24, col: PAL.tealNight, w: 1.9 }
  ];

  for (const sb of splinePBands) {
    const pts = [];
    for (let iu = 0; iu <= 14; iu++) {
      const uF = iu / 14;
      const endCurve = Math.pow(Math.abs(uF - 0.5) * 2, 2.2) * 0.085;
      const pt = toasterShellPt(uF, sb.p - endCurve);
      pts.push([pt[0], pt[1], 0.85 + 0.3 * Math.sin((iu / 14) * Math.PI)]);
    }
    brush.set("dry_crayon", sb.col, sb.w);
    brush.spline(pts, 0.5);
  }

  // Warped Vertical Window Mullions bending over the chrome shoulder
  const mullionUs = [0.15, 0.43, 0.72, 0.90];
  for (const mu of mullionUs) {
    const mPts = [];
    const hlPts = [];
    for (let ip = 0; ip <= 10; ip++) {
      const pVal = lerp(-0.74, -0.30, ip / 10);
      const uShift = mu - (pVal + 0.65) * 0.14 * (mu - 0.5);
      const pt = toasterShellPt(constrain(uShift, 0.03, 0.97), pVal);
      mPts.push([pt[0], pt[1], 1.0]);
      hlPts.push([pt[0] + 4, pt[1] + 2, 0.8]);
    }
    brush.set("dry_crayon", PAL.tealDeep, 1.5);
    brush.spline(mPts, 0.55);
    brush.set("fine_crayon", PAL.creamBright, 1.0);
    brush.spline(hlPts, 0.55);
  }

  // Brilliant specular ridge along the front-left rounded vertical corner (uFrac = 0.02)
  const cornerHl = [];
  for (let ip = 0; ip <= 12; ip++) {
    const pVal = lerp(-0.92, -0.15, ip / 12);
    const pt = toasterShellPt(0.025, pVal);
    cornerHl.push([pt[0], pt[1], 1.1]);
  }
  brush.set("dry_crayon", PAL.creamBright, 1.9);
  brush.spline(cornerHl, 0.5);
  brush.set("fine_crayon", PAL.mustardBright, 1.1);
  brush.spline(cornerHl.map(pt => [pt[0] - 3, pt[1], pt[2]]), 0.5);

  // Crisp exterior silhouette contour lines of the chrome shell
  const leftContour = [];
  for (let ip = 0; ip <= 12; ip++) {
    const pt = toasterShellPt(0.99, lerp(-0.98, 0.0, ip / 12));
    leftContour.push([pt[0], pt[1], 1.0]);
  }
  brush.set("fine_crayon", PAL.tealNight, 1.15);
  brush.spline(leftContour, 0.5);

  const rightContour = [];
  for (let iz = 0; iz <= 12; iz++) {
    const pt = frontCapPt(1.0, iz / 12);
    rightContour.push([pt[0], pt[1], 1.0]);
  }
  brush.set("fine_crayon", PAL.tealNight, 1.2);
  brush.spline(rightContour, 0.5);
}

// ============================================================================
// 7. TOP SLOTS & TWO SLICES OF TOAST POPPED HALFWAY UP
// ============================================================================
function drawTopSlotsAndToast() {
  // Two slots on top deck:
  // Back/Right slot (further from viewer): p in [0.04, 0.21]
  // Front/Left slot (closer to viewer): p in [-0.21, -0.04]
  // Draw back slot & back toast first, then front slot & front toast (Painter's order)
  drawSingleSlotAndToast(0.045, 0.215, 1);  // Far slot + slice
  drawSingleSlotAndToast(-0.215, -0.045, 0); // Near slot + slice
}

function drawSingleSlotAndToast(pMin, pMax, index) {
  const uStart = 0.13;
  const uEnd = 0.87;

  // 1. Rolled Chrome Slot Bezel Rim
  const bezelOuter = [
    toasterShellPt(uStart - 0.02, pMin - 0.025, 2),
    toasterShellPt(uEnd + 0.02, pMin - 0.025, 2),
    toasterShellPt(uEnd + 0.02, pMax + 0.025, 2),
    toasterShellPt(uStart - 0.02, pMax + 0.025, 2)
  ];
  drawPoly(bezelOuter, {
    wash: PAL.creamBright,
    washOpacity: 210,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.mustardLight,
    hatchWeight: 0.85,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealDeep,
    strokeWeight: 0.9
  });

  // 2. Dark Slot Interior with Residual Red-Orange Nichrome Heating Element Glow
  const slotInner = [
    toasterShellPt(uStart, pMin, 0),
    toasterShellPt(uEnd, pMin, 0),
    toasterShellPt(uEnd, pMax, 0),
    toasterShellPt(uStart, pMax, 0)
  ];
  drawPoly(slotInner, {
    wash: PAL.tomatoDark,
    washOpacity: 240,
    fill: PAL.tomatoBright,
    fillOpacity: 130,
    bleed: 0.06,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoMid,
    hatchWeight: 1.0,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealNight,
    strokeWeight: 1.1
  });

  // Glowing mustard/tomato nichrome wire glint at the ends of the slot
  const glowA0 = toasterShellPt(uStart + 0.01, (pMin + pMax) * 0.5, 0);
  const glowA1 = toasterShellPt(uStart + 0.06, (pMin + pMax) * 0.5, 0);
  brush.set("fine_crayon", PAL.mustardBright, 1.3);
  brush.line(glowA0[0], glowA0[1], glowA1[0], glowA1[1]);

  // 3. Toast Slice Popped Halfway Up!
  // Slice spans uFrac in [0.17, 0.83], thickness across v from vFront to vBack
  const uToast0 = 0.175 + index * 0.01;
  const uToast1 = 0.825 + index * 0.01;
  const u0 = uToast0 * TOASTER_L;
  const u1 = uToast1 * TOASTER_L;

  const pMid = 0.5 * (pMin + pMax);
  const vCenter = (0.5 + 0.5 * (pMid / 0.32) * 0.66) * TOASTER_W;
  const sliceThick = 28; // thick slice of mid-century sandwich bread
  const vFront = vCenter - sliceThick * 0.5;
  const vBack = vCenter + sliceThick * 0.5;

  const zSlot = TOASTER_H - 6;
  const zShoulder = zSlot + 74; // side crust indentation where top loaf crown begins
  const zPeak = zSlot + 118 + (index === 0 ? 4 : -2); // popped halfway up!

  // Helper to compute point on the slice profile
  // side = 0 (front-left face at vFront) or 1 (back-right face at vBack)
  function sliceTopArchPts(vPlane, steps = 16) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps; // 0 = front end (u0), 1 = back end (u1)
      const u = lerp(u0, u1, t);
      // Classic pullman/country loaf top crown with slight center dip or double swell
      const arch = Math.sin(t * Math.PI);
      const doubleSwell = Math.sin(t * 2 * Math.PI) * 0.06 + Math.pow(Math.sin(t * Math.PI), 0.65);
      const z = zShoulder + (zPeak - zShoulder) * doubleSwell;
      pts.push(proj(u, vPlane, z));
    }
    return pts;
  }

  const frontArch = sliceTopArchPts(vFront, 16);
  const backArch = sliceTopArchPts(vBack, 16);

  // A. Top & Right Crust Arch Band (between frontArch and backArch, plus right vertical crust edge)
  const crustStrip = [
    proj(u0, vFront, zSlot),
    proj(u0, vBack, zSlot),
    proj(u0 - 5, vBack, zShoulder - 12),
    ...backArch,
    ...frontArch.slice().reverse(),
    proj(u0 - 5, vFront, zShoulder - 12)
  ];

  drawPoly(crustStrip, {
    wash: PAL.tomatoDeep,
    washOpacity: 230,
    fill: PAL.tomatoDark,
    fillOpacity: 145,
    bleed: 0.04,
    texture: 0.85,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardDeep,
    hatchWeight: 1.0,
    hatchDist: 5,
    hatchAngle: -32,
    hatch2Brush: "fine_crayon",
    hatch2Color: PAL.tomatoDark,
    hatch2Weight: 0.9,
    hatch2Dist: 6,
    hatch2Angle: 45,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealNight,
    strokeWeight: 0.95
  });

  // Golden baked highlight along the top crown of the crust
  for (let i = 3; i < frontArch.length - 2; i++) {
    brush.set("fine_crayon", PAL.mustardLight, 1.35);
    brush.line(
      lerp(frontArch[i][0], backArch[i][0], 0.35),
      lerp(frontArch[i][1], backArch[i][1], 0.35),
      lerp(frontArch[i + 1][0], backArch[i + 1][0], 0.35),
      lerp(frontArch[i + 1][1], backArch[i + 1][1], 0.35)
    );
  }

  // B. Broad Front-Left Toasted Bread Face (at v = vFront)
  const breadFacePts = [
    proj(u0, vFront, zSlot),
    proj(u0 - 5, vFront, zShoulder - 12),
    ...frontArch,
    proj(u1 + 5, vFront, zShoulder - 12),
    proj(u1, vFront, zSlot)
  ];

  // Outer pale-golden toasted rim (Warm Cream & Light Mustard)
  drawPoly(breadFacePts, {
    wash: PAL.creamWarm,
    washOpacity: 225,
    fill: PAL.mustardLight,
    fillOpacity: 145,
    bleed: 0.05,
    texture: 0.88,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardBright,
    hatchWeight: 1.0,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.creamBright,
    hatch2Weight: 0.85,
    hatch2Dist: 7,
    hatch2Angle: -68,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tomatoDeep,
    strokeWeight: 1.15
  });

  // Inner richly browned toasted center patch (Mustard Deep & Tomato Mid)
  const innerArch = [];
  for (let i = 1; i <= 15; i++) {
    const t = i / 16;
    const u = lerp(u0 + 22, u1 - 22, t);
    const swell = Math.pow(Math.sin(t * Math.PI), 0.7);
    const z = (zShoulder - 10) + (zPeak - 22 - (zShoulder - 10)) * swell;
    innerArch.push(proj(u, vFront - 0.5, z));
  }
  const toastedCenterPts = [
    proj(u0 + 20, vFront - 0.5, zSlot + 3),
    ...innerArch,
    proj(u1 - 20, vFront - 0.5, zSlot + 3)
  ];

  drawPoly(toastedCenterPts, {
    fill: PAL.mustardMid,
    fillOpacity: 175,
    bleed: 0.14,
    texture: 0.9,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.tomatoMid,
    hatchWeight: 0.95,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.mustardDeep,
    hatch2Weight: 0.9,
    hatch2Dist: 7,
    hatch2Angle: -68
  });

  // Deeper caramelized center toast blush & vertical wire-guard grill stripes
  const charCenterPts = [
    proj(u0 + 48, vFront - 1, zSlot + 8),
    proj(u0 + 55, vFront - 1, zPeak - 38),
    proj((u0 + u1) * 0.5, vFront - 1, zPeak - 28),
    proj(u1 - 55, vFront - 1, zPeak - 38),
    proj(u1 - 48, vFront - 1, zSlot + 8)
  ];
  drawPoly(charCenterPts, {
    fill: PAL.tomatoMid,
    fillOpacity: 115,
    bleed: 0.2,
    texture: 0.9,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDeep,
    hatchWeight: 0.85,
    hatchDist: 6,
    hatchAngle: -68
  });

  // Vertical paler stripes left by the toaster's internal wire rack guards
  for (const wf of [0.28, 0.50, 0.72]) {
    const uw = lerp(u0, u1, wf);
    const pBot = proj(uw, vFront - 1, zSlot + 4);
    const pTop = proj(uw, vFront - 1, zPeak - 22);
    brush.set("dry_crayon", PAL.mustardBright, 1.15);
    brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
    brush.set("fine_crayon", PAL.creamWarm, 0.8);
    brush.line(pBot[0] + 1, pBot[1], pTop[0] + 1, pTop[1]);
  }

  // Hyperrealistic porous bread-crumb cell texture across the toasted slice face
  for (let k = 0; k < 140; k++) {
    const tu = random(0.06, 0.94);
    const u = lerp(u0, u1, tu);
    const maxZ = zShoulder - 8 + (zPeak - 16 - (zShoulder - 8)) * Math.pow(Math.sin(tu * Math.PI), 0.7);
    const z = random(zSlot + 6, maxZ);
    const pt = proj(u, vFront - 1, z);

    // Pores are darker in the toasted center and golden near the rim
    const distCenter = Math.abs(tu - 0.5) * 2;
    const poreCol = distCenter < 0.55
      ? (random() < 0.55 ? PAL.tomatoDeep : PAL.mustardDeep)
      : (random() < 0.6 ? PAL.mustardMid : PAL.creamBright);

    brush.set("crumb_crayon", poreCol, random(0.55, 1.15));
    brush.line(pt[0], pt[1], pt[0] + random(-2.5, 2.5), pt[1] + random(-2.0, 2.0));
  }

  // Crisp dark toasted rim where the slice emerges from the slot
  const baseLine0 = proj(u0 - 2, vFront - 1, zSlot);
  const baseLine1 = proj(u1 + 2, vFront - 1, zSlot);
  brush.set("fine_crayon", PAL.tealNight, 1.3);
  brush.line(baseLine0[0], baseLine0[1], baseLine1[0], baseLine1[1]);
  brush.set("fine_crayon", PAL.tomatoBright, 0.95);
  brush.line(baseLine0[0], baseLine0[1] + 2, baseLine1[0], baseLine1[1] + 2);
}

// ============================================================================
// 8. FRONT CONTROL END-PANEL: BAKELITE CREST, DIAL & HALF-UP LEVER
// ============================================================================
function drawFrontControls() {
  // Helper for placing elements on the curved front end-cap (near u = -14)
  function ctrlPt(vFrac, zHeight, uOut = 0) {
    const v = vFrac * TOASTER_W;
    const s = (vFrac - 0.5) * 2;
    const zNorm = constrain((zHeight - 48) / (TOASTER_H - 48), 0, 1);
    const uBulge = -19 * Math.sin(Math.PI * zNorm * 0.9) * Math.cos(s * Math.PI * 0.42) - uOut;
    return proj(uBulge, v, zHeight);
  }

  // 1. Three Vertical Embossed Chrome Flutes rising above the bakelite shield
  for (const vf of [0.45, 0.50, 0.55]) {
    const fBot = ctrlPt(vf, 125, 2);
    const fTop = ctrlPt(vf, 308, 2);
    brush.set("fine_crayon", PAL.tealDeep, 1.15);
    brush.line(fBot[0], fBot[1], fTop[0], fTop[1]);
    brush.set("crumb_crayon", PAL.creamBright, 1.0);
    brush.line(fBot[0] - 2, fBot[1], fTop[0] - 2, fTop[1]);
  }

  // 2. Sculpted Mid-Century Bakelite Control Escutcheon / Shield (z = 52 to 265)
  const shieldPts = [
    ctrlPt(0.28, 52, 6),
    ctrlPt(0.72, 52, 6),
    ctrlPt(0.68, 128, 8),
    ctrlPt(0.58, 152, 8),
    ctrlPt(0.56, 268, 7),
    ctrlPt(0.44, 268, 7),
    ctrlPt(0.42, 152, 8),
    ctrlPt(0.32, 128, 8)
  ];
  drawPoly(shieldPts, {
    wash: PAL.tealNight,
    washOpacity: 235,
    fill: PAL.tomatoDark,
    fillOpacity: 135,
    bleed: 0.04,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.tealDeep,
    hatchWeight: 0.95,
    hatchDist: 5,
    hatchAngle: -22,
    hatch2Brush: "fine_crayon",
    hatch2Color: PAL.tomatoDeep,
    hatch2Weight: 0.75,
    hatch2Dist: 6,
    hatch2Angle: 68,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.mustardMid,
    strokeWeight: 0.95
  });

  // Left bevel highlight on the sculpted bakelite shield
  const shL0 = ctrlPt(0.30, 56, 8);
  const shL1 = ctrlPt(0.33, 126, 9);
  const shL2 = ctrlPt(0.43, 152, 9);
  const shL3 = ctrlPt(0.45, 264, 8);
  brush.set("fine_crayon", PAL.creamWarm, 1.1);
  brush.line(shL0[0], shL0[1], shL1[0], shL1[1]);
  brush.line(shL1[0], shL1[1], shL2[0], shL2[1]);
  brush.line(shL2[0], shL2[1], shL3[0], shL3[1]);

  // 3. Vertical Carriage Slot Channel (z = 135 to 258 at vFrac = 0.50)
  const slotChPts = [
    ctrlPt(0.482, 134, 9),
    ctrlPt(0.518, 134, 9),
    ctrlPt(0.518, 258, 9),
    ctrlPt(0.482, 258, 9)
  ];
  drawPoly(slotChPts, {
    wash: PAL.tealNight,
    washOpacity: 250,
    strokeBrush: "crumb_crayon",
    strokeColor: PAL.mustardLight,
    strokeWeight: 0.85
  });

  // 4. Browning Control Dial at Lower Center of Shield (vFrac = 0.50, z = 92)
  const dialCenter = ctrlPt(0.50, 92, 12);
  const dialFront = ctrlPt(0.50, 92, 22);

  // Tomato-red and mustard indicator tick marks around dial arc
  for (let a = -140; a <= 40; a += 30) {
    const rad = 24;
    const tx0 = dialCenter[0] + cos(a) * (rad - 3);
    const ty0 = dialCenter[1] + sin(a) * (rad - 3) * 0.85;
    const tx1 = dialCenter[0] + cos(a) * (rad + 4);
    const ty1 = dialCenter[1] + sin(a) * (rad + 4) * 0.85;
    brush.set("crumb_crayon", a > -20 ? PAL.tomatoBright : PAL.mustardBright, 1.0);
    brush.line(tx0, ty0, tx1, ty1);
  }

  // Chrome bezel ring behind dial
  const dialRingPts = [];
  for (let a = 0; a < 360; a += 24) {
    dialRingPts.push([
      dialCenter[0] + cos(a) * 20,
      dialCenter[1] + sin(a) * 17.5
    ]);
  }
  drawPoly(dialRingPts, {
    wash: PAL.mustardLight,
    washOpacity: 210,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.creamBright,
    strokeWeight: 1.0
  });

  // Knurled Bakelite Knob Cylinder
  const knobPts = [];
  for (let a = 0; a < 360; a += 24) {
    knobPts.push([
      dialFront[0] + cos(a) * 15,
      dialFront[1] + sin(a) * 13
    ]);
  }
  drawPoly(knobPts, {
    wash: PAL.tealNight,
    washOpacity: 245,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDark,
    hatchWeight: 0.9,
    hatchDist: 4,
    hatchAngle: 30,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.mustardMid,
    strokeWeight: 0.95
  });

  // Warm cream & tomato pointer bar on knob face
  brush.set("fine_crayon", PAL.creamBright, 1.35);
  brush.line(dialFront[0] - 8, dialFront[1] - 5, dialFront[0] + 6, dialFront[1] + 4);
  brush.set("crumb_crayon", PAL.tomatoBright, 1.1);
  brush.line(dialFront[0] - 8, dialFront[1] - 5, dialFront[0] - 2, dialFront[1] - 1);

  // 5. Toast Carriage Lever Popped Halfway Up (at z = 204!)
  const zLever = 204;
  // Cast shadow of the lever onto the bakelite shield below-right
  const leverShadowPts = [
    ctrlPt(0.49, zLever - 6, 9),
    ctrlPt(0.72, zLever - 26, 9),
    ctrlPt(0.72, zLever - 42, 9),
    ctrlPt(0.49, zLever - 18, 9)
  ];
  drawPoly(leverShadowPts, {
    fill: PAL.tealNight,
    fillOpacity: 165,
    bleed: 0.08
  });

  // Chrome lever shaft emerging from slot
  const shaftPts = [
    ctrlPt(0.48, zLever - 4, 10),
    ctrlPt(0.52, zLever - 4, 10),
    ctrlPt(0.53, zLever + 4, 28),
    ctrlPt(0.47, zLever + 4, 28)
  ];
  drawPoly(shaftPts, {
    wash: PAL.creamBright,
    washOpacity: 230,
    strokeBrush: "crumb_crayon",
    strokeColor: PAL.tealDeep,
    strokeWeight: 0.9
  });

  // Sculpted Bakelite Lever Knob (Halfway up position)
  // Top face of knob (catching bright morning mustard/cream light)
  const knobTop = [
    ctrlPt(0.36, zLever + 7, 24),
    ctrlPt(0.64, zLever + 7, 24),
    ctrlPt(0.66, zLever + 3, 48),
    ctrlPt(0.34, zLever + 3, 48)
  ];
  drawPoly(knobTop, {
    wash: PAL.tealDeep,
    washOpacity: 230,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.mustardLight,
    hatchWeight: 0.95,
    hatchDist: 4,
    hatchAngle: -20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.creamBright,
    strokeWeight: 1.05
  });

  // Front-left face of knob
  const knobFront = [
    ctrlPt(0.34, zLever + 3, 48),
    ctrlPt(0.66, zLever + 3, 48),
    ctrlPt(0.64, zLever - 15, 44),
    ctrlPt(0.36, zLever - 15, 44)
  ];
  drawPoly(knobFront, {
    wash: PAL.tealNight,
    washOpacity: 245,
    fill: PAL.tomatoDark,
    fillOpacity: 130,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDeep,
    hatchWeight: 0.9,
    hatchDist: 4,
    hatchAngle: -22,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.mustardMid,
    strokeWeight: 0.9
  });

  // Chrome & tomato-red trim inlay strip across the front of the bakelite lever knob
  const inlay0 = ctrlPt(0.37, zLever - 4, 47);
  const inlay1 = ctrlPt(0.63, zLever - 4, 47);
  brush.set("fine_crayon", PAL.tomatoBright, 1.35);
  brush.line(inlay0[0], inlay0[1], inlay1[0], inlay1[1]);
  brush.set("crumb_crayon", PAL.creamBright, 1.0);
  brush.line(inlay0[0], inlay0[1] - 2.5, inlay1[0], inlay1[1] - 2.5);
}

// ============================================================================
// 9. EVERY CRUMB ON THE SPECKLED LAMINATE DESCRIBED INDIVIDUALLY
// ============================================================================
function drawIndividualCrumbs() {
  // Collect ~115 distinct, individually sculpted crumbs across the countertop sweep:
  // 1) Near the front and right base of the toaster (where toast pops & is lifted)
  // 2) Trailing out across the generous sweep of counter to the right and foreground
  const crumbs = [];

  // Cluster A: Around front corner and right flank of toaster (38 crumbs)
  for (let i = 0; i < 38; i++) {
    const u = random(-135, 195);
    const v = random(-90, 390);
    // Keep outside toaster base footprint
    if (u > -14 && u < TOASTER_L + 12 && v > -12 && v < TOASTER_W + 14) continue;
    const pt = proj(u, v, 0);
    crumbs.push({
      x: pt[0],
      y: pt[1],
      size: random(3.2, 11.5),
      type: random() < 0.42 ? "crust" : (random() < 0.65 ? "toasted" : "crumb"),
      inShadow: u > -5 && u < 365 && v > 225,
      seed: i * 37
    });
  }

  // Cluster B: Generous sweep of counter to the right & lower-right foreground (78 crumbs)
  for (let i = 0; i < 78; i++) {
    // Spread across the wide counter expanse (x = 420..1150, y = 610..1165)
    const t = Math.pow(random(), 0.85);
    const sx = lerp(430, 1145, t) + random(-35, 35);
    const sy = lerp(630, 1155, random()) + (sx - 600) * 0.08;
    if (sx < 565 && sy < 885) continue;

    // Depth scale: crumbs closer to foreground (bottom) appear larger
    const persp = map(sy, 580, 1170, 0.58, 1.38, true);
    // Check if inside the toaster's morning cast shadow
    const inShadow = sy < 890 && sx > 520 && sx < 1030 && (sy - 690) < (sx - 520) * 0.24 && (sy - 840) > -(sx - 560) * 0.35;

    crumbs.push({
      x: constrain(sx, 80, 1165),
      y: constrain(sy, 600, 1170),
      size: random(2.8, 10.8) * persp,
      type: random() < 0.35 ? "crust" : (random() < 0.62 ? "toasted" : "crumb"),
      inShadow: inShadow,
      seed: 1000 + i * 53
    });
  }

  // Sort crumbs back-to-front by y coordinate for accurate occlusion
  crumbs.sort((a, b) => a.y - b.y);

  for (const c of crumbs) {
    drawSingleHyperrealCrumb(c);
  }
}

function drawSingleHyperrealCrumb(c) {
  const r = c.size;
  const x = c.x;
  const y = c.y;

  // Build an irregular, craggy 6-vertex 3D polyhedron silhouette for this specific crumb
  const nVerts = 6;
  const basePts = [];
  for (let i = 0; i < nVerts; i++) {
    const ang = (i / nVerts) * 360 + random(-18, 18);
    const radX = r * random(0.68, 1.25);
    const radY = r * random(0.45, 0.82); // foreshortened on counter plane
    basePts.push([
      x + cos(ang) * radX,
      y + sin(ang) * radY
    ]);
  }

  // Peak ridge point of the 3D crumb (shifted slightly up and left toward the light)
  const peakX = x + random(-r * 0.25, r * 0.15);
  const peakY = y - r * random(0.38, 0.72);

  // 1. Faint Semi-Gloss Laminate Reflection directly underneath the crumb
  const reflCol = c.type === "crust" ? PAL.tomatoDeep : PAL.mustardMid;
  brush.set("crumb_crayon", reflCol, 0.65);
  brush.line(x - r * 0.5, y + r * 0.55, x + r * 0.5, y + r * 0.55);

  // 2. Crisp Early-Morning Cast Shadow extending toward the right / upper-right (-18 deg)
  const shadowLen = r * (c.inShadow ? 0.75 : 1.65);
  const shDx = cos(-16) * shadowLen;
  const shDy = sin(-16) * shadowLen * 0.55;
  const shadowPts = [
    basePts[1],
    [basePts[0][0] + shDx, basePts[0][1] + shDy],
    [basePts[5][0] + shDx * 0.9, basePts[5][1] + shDy * 0.9],
    basePts[4],
    basePts[2]
  ];
  drawPoly(shadowPts, {
    wash: PAL.tealNight,
    washOpacity: c.inShadow ? 155 : 220
  });

  // 3. Determine Lit & Shaded Facet Colors based on Crumb Type (Crust, Toasted Golden, or Inner Crumb)
  let litCol, midCol, shadeCol, rimCol;
  if (c.type === "crust") {
    litCol = c.inShadow ? PAL.mustardDeep : PAL.tomatoBright;
    midCol = PAL.tomatoMid;
    shadeCol = PAL.tomatoDark;
    rimCol = PAL.mustardLight;
  } else if (c.type === "toasted") {
    litCol = c.inShadow ? PAL.mustardMid : PAL.mustardBright;
    midCol = c.inShadow ? PAL.mustardDeep : PAL.mustardLight;
    shadeCol = PAL.tomatoDeep;
    rimCol = PAL.creamBright;
  } else {
    // Pale warm cream interior bread crumb
    litCol = c.inShadow ? PAL.creamMid : PAL.creamBright;
    midCol = c.inShadow ? PAL.mustardMid : PAL.mustardLight;
    shadeCol = c.inShadow ? PAL.tealDeep : PAL.mustardDeep;
    rimCol = PAL.creamBright;
  }

  // 4. Shaded Right/Lower Facet of the 3D Crumb
  const shadeFacet = [
    peakY < basePts[4][1] ? [peakX, peakY] : basePts[4],
    basePts[5],
    basePts[0],
    basePts[1],
    basePts[2]
  ];
  drawPoly(shadeFacet, {
    wash: shadeCol,
    washOpacity: 235
  });

  // 5. Lit Left/Top Facet of the 3D Crumb (facing the early morning window light)
  const litFacet = [
    [peakX, peakY],
    basePts[1],
    basePts[2],
    basePts[3],
    basePts[4]
  ];
  drawPoly(litFacet, {
    wash: litCol,
    washOpacity: 240,
    hatchBrush: "crumb_crayon",
    hatchColor: midCol,
    hatchWeight: 0.7,
    hatchDist: 3,
    hatchAngle: 25
  });

  // 6. Crisp Craggy Crayon Contour, Dark Contact Crevice, and Specular Ridge Glint
  // Contact crevice at bottom edge
  brush.set("crumb_crayon", PAL.tealNight, 0.95);
  brush.line(basePts[0][0], basePts[0][1], basePts[1][0], basePts[1][1]);
  brush.line(basePts[1][0], basePts[1][1], basePts[2][0], basePts[2][1]);

  // Bright morning highlight glint on the top-left ridge of the crumb
  brush.set("crumb_crayon", rimCol, r > 5.5 ? 1.15 : 0.85);
  brush.line(basePts[3][0], basePts[3][1], peakX, peakY);
  if (r > 6.5) {
    // Internal bread pore speck on larger crumbs
    brush.set("crumb_crayon", shadeCol, 0.8);
    brush.line(peakX - 1.2, peakY + 1.5, peakX + 0.8, peakY + 2.2);
  }
}

