    spacing: 0.14,
    pressure: [0.75, 1.0, 0.75],
    markerTip: false,
    noise: 0.1
  });

  brush.add("rime_white", {
    type: "default",
    weight: 1.45,
    scatter: 0.32,
    sharpness: 0.84,
    grain: 15,
    opacity: 240,
    spacing: 0.11,
    pressure: [0.55, 1.3, 0.35],
    noise: 0.45
  });

  brush.add("frost_stipple", {
    type: "spray",
