  });

  // Custom vector field for the diagonal snow squall with a subtle eddy around the hydrant
  brush.addField("squall_flow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let fx = (col / field.length) * 1200;
        let fy = (row / field[0].length) * 1200;
        let n = (noise(col * 0.08, row * 0.08) - 0.5) * 14;
        // Slight upward/leeward curl near the hydrant dome
        let dx = fx - HYD_CX;
        let dy = fy - HYD_CY;
        let d = Math.hypot(dx, dy);
        let eddy = d < 260 ? Math.sin((1 - d / 260) * Math.PI) * -10 * Math.sign(dy) : 0;
        field[col][row] = WIND_ANGLE + n + eddy;
      }
    }
    return field;
  });
}

function paintStill() {
  // Stark, icy white ground
  background("#f7f9fc");

  // 1. Atmospheric snow squall washes & soft grey-white spray
  drawBackgroundSquall();

