  drawClingingIceRime();

  // 6. Layered translucent snowdrift washes & white edge dissolution
  drawForegroundDriftsAndEdgeDissolve();

  // 7. Driving diagonal pencil flecks & snow streaks across the sheet
  drawWindblownPencilFlecks();
}

function draw() {
  const TOTAL_FRAMES = window.PIECE_SECONDS * window.PIECE_FPS;
  if (frameCount > TOTAL_FRAMES) return;

  translate(-width / 2, -height / 2);

  if (frameCount === 1) {
    paintStill();
    stillImg = get();
    initSquallMotion();
    return;
  }

  background("#f7f9fc");
  push();
  image(stillImg, 0, 0, width, height);
  pop();
  if (drawingContext && drawingContext.clear) {
    drawingContext.clear(drawingContext.DEPTH_BUFFER_BIT);
  }

  const tSec = (frameCount - 1) / window.PIECE_FPS;
  // Smooth ease-in over the first 3 frames so frame 1 continues frame 0 seamlessly
  const onset = Math.sin(constrain((frameCount - 1) / 3.0, 0, 1) * (Math.PI * 0.5));

  renderSquallMotion(tSec, onset);
}

// ============================================================================
// MOTION INITIALIZATION & PER-FRAME ANIMATION (FRAMES 2..48)
