    { br: "HB", col: "#8d9eb2", wtMin: 0.45, wtMax: 0.68, lMin: 10, lMax: 38, count: 65 },
    { br: "cpencil", col: "#73859a", wtMin: 0.42, wtMax: 0.62, lMin: 8, lMax: 26, count: 40 }
  ];
