      wt: isPellet ? random(0.85, 1.35) : random(0.65, acrossHydrant ? 1.28 : 0.95),
      wobbleFreq: random(0.3, 0.7),
      wobbleAmp: random(3, 11),
      phase: random(360),
      curved: !isPellet && i % 3 === 0
    });
