      seed: 80000 + i * 71,
      x0: random(260, 940),
      yOff: random(-8, 135),
      speed: random(310, 460),
      len: random(28, 85),
      wt: random(0.55, 1.15),
      br: isWhite ? "rime_white" : "2H",
