  for (let i = 0; i < 26; i++) {
    let ang = (i / 26) * 360 + random(-6, 6);
    let rad = random(465, 585);
    edgeVeilStreaks.push({
      seed: 95000 + i * 83,
      cx: 600 + cos(ang) * rad,
      cy: 600 + sin(ang) * rad,
      wt: random(1.6, 2.3),
      phase: random(360)
    });
  }
}

// Smooth aerodynamic streamline angle around the hydrant at (x, y)
function getStreamAngle(x, y, tSec) {
  let dx = x - HYD_CX;
  let dy = y - HYD_CY;
  let d = Math.hypot(dx, dy);
  let smoothSign = Math.tanh(dy / 42);
  let eddy = d < 280 ? Math.sin((1 - d / 280) * Math.PI) * -11.5 * smoothSign : 0;
  let gustRipple = sin(x * 0.45 + y * 0.25 - tSec * 240) * 2.8;
  return WIND_ANGLE + eddy + gustRipple;
}

function renderSquallMotion(tSec, onset) {
  const wx = cos(WIND_ANGLE);
  const wy = sin(WIND_ANGLE);
  const nx = -wy;
  const ny = wx;

  const SPAN = 960;
  const HALF_SPAN = SPAN * 0.5;
  const CX = 635;
  const CY = 595;

  // --- LAYER 1: Travelling Translucent Squall Mist Gusts ---
  noiseSeed(91100);
  for (let i = 0; i < squallMistGusts.length; i++) {
    let m = squallMistGusts[i];
    randomSeed(m.seed);

    let u = ((m.u0 + m.speed * tSec + HALF_SPAN) % SPAN + SPAN) % SPAN - HALF_SPAN;
    let uNorm = (u + HALF_SPAN) / SPAN;
    let env = Math.sin(uNorm * Math.PI) * onset;

    let x = CX + u * wx + m.v0 * nx;
    let y = CY + u * wy + m.v0 * ny;
    let halfL = m.len * 0.5 * (0.4 + 0.6 * env);

    brush.set("squall_mist", m.col, m.wt * (0.45 + 0.55 * env));
    brush.line(x - wx * halfL, y - wy * halfL, x + wx * halfL, y + wy * halfL);
  }

  // --- LAYER 2: Driving Graphite & Slate Pencil Flecks ---
  noiseSeed(91200);
  for (let i = 0; i < graphiteStreaks.length; i++) {
    let g = graphiteStreaks[i];
    randomSeed(g.seed);

    let u = ((g.u0 + g.speed * tSec + HALF_SPAN) % SPAN + SPAN) % SPAN - HALF_SPAN;
    let uNorm = (u + HALF_SPAN) / SPAN;
    let env = Math.sin(uNorm * Math.PI);

    let vWobble = g.v0 + sin(u * g.wobbleFreq + g.phase) * g.wobbleAmp;
    let x = CX + u * wx + vWobble * nx;
    let y = CY + u * wy + vWobble * ny;

    // Attenuate dark graphite slightly over the brightest upper-left specular dome highlight
    let dSpec = Math.hypot(x - (HYD_CX - 38), y - (HYD_CY - 45));
    let specFade = dSpec < 85 ? map(dSpec, 0, 85, 0.35, 1.0) : 1.0;

    let ang = getStreamAngle(x, y, tSec);
    let len = g.len * env * onset * specFade;
    let wt = g.wt * (0.35 + 0.65 * env) * (0.3 + 0.7 * onset);

    let ca = cos(ang);
    let sa = sin(ang);
    brush.set(g.br, g.col, wt);
    brush.line(x - ca * len * 0.3, y - sa * len * 0.3, x + ca * len * 0.7, y + sa * len * 0.7);
  }

  // --- LAYER 3: Ground-Skimming Drift Ribbons Along the Snowbank Contour ---
  noiseSeed(91300);
  const DRIFT_SPAN = 680;
  for (let i = 0; i < driftRibbons.length; i++) {
    let dr = driftRibbons[i];
    randomSeed(dr.seed);

    let xRel = ((dr.x0 - 260 + dr.speed * tSec) % DRIFT_SPAN + DRIFT_SPAN) % DRIFT_SPAN;
    let dNorm = xRel / DRIFT_SPAN;
    let env = Math.sin(dNorm * Math.PI) * onset;

    let x0 = 260 + xRel;
    let x1 = x0 + dr.len * 0.5 * env;
    let x2 = x0 + dr.len * env;

    let y0 = getSnowLineY(x0) + dr.yOff + sin(x0 * 0.8 + dr.phase) * 2.5;
    let y1 = getSnowLineY(x1) + dr.yOff + sin(x1 * 0.8 + dr.phase) * 2.5;
    let y2 = getSnowLineY(x2) + dr.yOff + sin(x2 * 0.8 + dr.phase) * 2.5;

    brush.set(dr.br, dr.col, dr.wt * (0.35 + 0.65 * env));
    safeSpline([[x0, y0], [x1, y1], [x2, y2]], 0.45);
  }

  // --- LAYER 4: Hydrant Rime Spindrift Plumes (Shedding Directly Across Red Cast Iron) ---
  noiseSeed(91400);
  for (let i = 0; i < rimeSpindrift.length; i++) {
    let sp = rimeSpindrift[i];
    randomSeed(sp.seed);

    let life = (tSec * sp.rate + sp.phase) % 1.0;
    // Ease out velocity as spindrift tears off the rime ridge and accelerates into the wind
    let travel = Math.pow(life, 0.82) * sp.reach * onset;
    let env = Math.sin(life * Math.PI) * onset;

    let curX = sp.ax + wx * travel;
    let curY = sp.ay + wy * travel;
    let ang = getStreamAngle(curX, curY, tSec) + sp.angOffset;
    let ca = cos(ang);
    let sa = sin(ang);

    let segLen = sp.len * (0.35 + 0.85 * env);
    let wt = sp.wt * (0.4 + 0.6 * env);

    if (sp.isStipple) {
      brush.set("frost_stipple", "#ffffff", wt * 0.75);
      brush.line(curX, curY, curX + ca * segLen * 0.6, curY + sa * segLen * 0.6);
    } else {
      brush.set("rime_white", sp.col, wt);
      brush.line(curX - ca * segLen * 0.25, curY - sa * segLen * 0.25, curX + ca * segLen * 0.75, curY + sa * segLen * 0.75);
    }
  }

  // --- LAYER 5: Crisp White Snow Streaks & Pellets Whipping Across the Hydrant ---
  noiseSeed(91500);
  for (let i = 0; i < whiteSnowStreaks.length; i++) {
    let ws = whiteSnowStreaks[i];
    randomSeed(ws.seed);

    let u = ((ws.u0 + ws.speed * tSec + HALF_SPAN) % SPAN + SPAN) % SPAN - HALF_SPAN;
    let uNorm = (u + HALF_SPAN) / SPAN;
    let env = Math.sin(uNorm * Math.PI);

    let vWobble = ws.v0 + sin(u * ws.wobbleFreq + ws.phase) * ws.wobbleAmp;
    let x = CX + u * wx + vWobble * nx;
    let y = CY + u * wy + vWobble * ny;

    let ang1 = getStreamAngle(x, y, tSec);
    let len = ws.len * env * onset;
    let wt = ws.wt * (0.35 + 0.65 * env) * (0.35 + 0.65 * onset);

    brush.set("rime_white", ws.col, wt);
    if (ws.curved && len > 16) {
      let xm = x + cos(ang1) * len * 0.5;
      let ym = y + sin(ang1) * len * 0.5;
      let ang2 = getStreamAngle(xm, ym, tSec);
      let x2 = xm + cos(ang2) * len * 0.5;
      let y2 = ym + sin(ang2) * len * 0.5;
      safeSpline([[x, y], [xm, ym], [x2, y2]], 0.45);
    } else {
      let ca = cos(ang1);
      let sa = sin(ang1);
      brush.line(x - ca * len * 0.2, y - sa * len * 0.2, x + ca * len * 0.8, y + sa * len * 0.8);
    }
  }

  // --- LAYER 6: Soft Whiteout Edge Dissolution Veil ---
  noiseSeed(91600);
  brush.set("squall_mist", "#ffffff", 1.85);
  for (let i = 0; i < edgeVeilStreaks.length; i++) {
    let ev = edgeVeilStreaks[i];
    randomSeed(ev.seed);
    let drift = sin(tSec * 120 + ev.phase) * 18 * onset;
    let x = ev.cx + wx * drift;
    let y = ev.cy + wy * drift;
    brush.line(x - wx * 55, y - wy * 55, x + wx * 55, y + wy * 55);
  }
}

// ============================================================================
// 1. BACKGROUND SQUALL (Soft grey-white spray & overcast translucent washes)
// ============================================================================
function drawBackgroundSquall() {
  brush.noStroke();

  // Batch 1: Soft slate-grey atmospheric squall washes in the central region
  // (provides the mid-high value ground so crisp white pencil rime & flecks pop)
  const squallLayers = [
    { col: "#dde4ed", alpha: 52, bleed: 0.42, count: 5, radX: 420, radY: 230 },
    { col: "#ced8e4", alpha: 46, bleed: 0.38, count: 5, radX: 340, radY: 185 },
    { col: "#bfcbe0", alpha: 38, bleed: 0.35, count: 4, radX: 260, radY: 145 }
  ];

  for (let layer of squallLayers) {
    brush.fill(layer.col, layer.alpha);
    brush.fillBleed(layer.bleed, "out");
    brush.fillTexture(0.45, 0.12);

    for (let i = 0; i < layer.count; i++) {
      let cx = 580 + random(-210, 210);
      let cy = 560 + random(-190, 170) + (cx - 600) * 0.25;
      drawTiltedCloudPoly(cx, cy, layer.radX * random(0.8, 1.25), layer.radY * random(0.8, 1.2), WIND_ANGLE, 12);
    }
  }
  brush.noFill();

  // Soft grey-white spray sheets driving diagonally
  const sprayPasses = [
    { col: "#c5d0de", wt: 1.2, count: 65, spread: 430 },
    { col: "#d8e1ec", wt: 1.4, count: 80, spread: 500 },
    { col: "#e9eff6", wt: 1.6, count: 70, spread: 540 }
  ];

  for (let sp of sprayPasses) {
    brush.set("squall_mist", sp.col, sp.wt);
    for (let i = 0; i < sp.count; i++) {
      let a = random(360);
      let r = Math.pow(random(), 0.75) * sp.spread;
      let cx = 630 + cos(a) * r * 1.15;
      let cy = 590 + sin(a) * r * 0.95;
      let len = random(140, 340);
      let x1 = cx - cos(WIND_ANGLE) * len * 0.5;
      let y1 = cy - sin(WIND_ANGLE) * len * 0.5;
      let x2 = cx + cos(WIND_ANGLE) * len * 0.5;
      let y2 = cy + sin(WIND_ANGLE) * len * 0.5;
      brush.line(x1, y1, x2, y2);
    }
  }
}

function drawTiltedCloudPoly(cx, cy, rx, ry, angleDeg, steps) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let th = (i / steps) * 360;
    let nr = 0.72 + noise(cx * 0.01 + cos(th) * 1.3, cy * 0.01 + sin(th) * 1.3) * 0.55;
    let lx = cos(th) * rx * nr;
    let ly = sin(th) * ry * nr;
    let gx = cx + lx * ca - ly * sa;
    let gy = cy + lx * sa + ly * ca;
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. HYDRANT SHOULDER (UPPER BARREL) & BONNET FLANGE
// ============================================================================
function drawHydrantShoulderAndFlange() {
  const R_BARREL = 106;

  // --- 2A. Upper Barrel Cylindrical Marker Shading ---
  // Sweep meridian strips from left (-115°) to right (+115°)
  const aSteps = 72;
  for (let i = 0; i <= aSteps; i++) {
    let deg = map(i, 0, aSteps, -112, 112);
    let nx = sin(deg);
    let nz = cos(deg);

    // Determine radius profile along Y (from -160 up to 0)
    let topP = proj(nx * R_BARREL, 0, nz * R_BARREL);
    let snowY = getSnowLineY(topP.x);

    // Subdivide vertically so we can vary ambient occlusion under the flange and near the nozzle shadow
    let ySegs = 14;
    for (let j = 0; j < ySegs; j++) {
      let y0 = map(j, 0, ySegs, -155, 0);
      let y1 = map(j + 1, 0, ySegs, -155, 0);

      // Slight flare right under the flange (y > -14)
      let r0 = R_BARREL + (y0 > -14 ? map(y0, -14, 0, 0, 7) : 0);
      let r1 = R_BARREL + (y1 > -14 ? map(y1, -14, 0, 0, 7) : 0);

      let p0 = proj(nx * r0, y0, nz * r0);
      let p1 = proj(nx * r1, y1, nz * r1);

      // Stop stroke softly inside the snowbank
      let limitY = snowY + (noise(i * 0.3, j * 0.3) - 0.3) * 16;
      if (p0.y > limitY && p1.y > limitY) continue;
      if (p0.y > limitY) {
        p0.y = limitY;
      }

      // Compute AO: dark undercut right below flange (y > -16) and cast shadow from nozzle (deg in -15..45, y < -65)
      let ao = 1.0;
      if (y1 > -18) ao *= map(y1, -18, 0, 1.0, 0.32);
      // Cast shadow from the protruding nozzle onto the lower-right barrel
      let dNoz = Math.hypot(deg - 18, (y0 + 82) * 0.75);
      if (dNoz < 48) ao *= map(dNoz, 0, 48, 0.35, 1.0);
      // Dissolve right/leeward bottom edge slightly
      if (deg > 78 && y0 < -65) ao *= 0.75;

      let col = getCadmiumColor(nx, -0.05, nz, ao);
      brush.set("cad_marker", col, random(0.65, 0.95));
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Cross-contour latitude marker strokes on the shoulder to lock in cylindrical volume
  for (let y = -125; y <= -4; y += 7) {
    let r = R_BARREL + (y > -14 ? map(y, -14, 0, 0, 7) : 0);
    // Raised cast-iron molding seam at y = -34
    if (Math.abs(y - -34) < 4) r += 3.5;

    let segStart = -108;
    let stepDeg = 18;
    for (let deg = segStart; deg < 105; deg += stepDeg) {
      let midDeg = deg + stepDeg * 0.5;
      let nx = sin(midDeg);
      let nz = cos(midDeg);
      let ny = (y === -31) ? 0.45 : (y === -37 ? -0.55 : 0);

      let pA = proj(sin(deg) * r, y, cos(deg) * r);
      let pB = proj(sin(deg + stepDeg) * r, y, cos(deg + stepDeg) * r);
      let snowY = getSnowLineY((pA.x + pB.x) * 0.5);
      if (pA.y > snowY + 8 || pB.y > snowY + 8) continue;

      let ao = y > -16 ? map(y, -16, 0, 0.95, 0.28) : 1.0;
      let col = getCadmiumColor(nx, ny, nz, ao);
      brush.set("micro_marker", col, 0.85);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Crisp cast-iron crevice lines under the shoulder molding & flange undercut
  drawCylinderArc(R_BARREL + 2, -37, -100, 102, "rotring", "#2b0506", 0.55);
  drawCylinderArc(R_BARREL + 7, -2, -108, 108, "rotring", "#1a0405", 0.85);

  // --- 2B. Bonnet Flange Rim (Y = 0 to 16, R = 125) ---
  const R_FLANGE = 125;
  const R_DOME_BASE = 103;

  // Underside bevel of flange
  for (let deg = -115; deg < 115; deg += 8) {
    let p0 = proj(sin(deg) * (R_BARREL + 6), -2, cos(deg) * (R_BARREL + 6));
    let p1 = proj(sin(deg + 8) * R_FLANGE, 3, cos(deg + 8) * R_FLANGE);
    brush.set("micro_marker", "#280506", 0.9);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Vertical outer edge of the flange (Y = 2 to 15)
  for (let deg = -112; deg <= 112; deg += 3) {
    let nx = sin(deg);
    let nz = cos(deg);
    let p0 = proj(nx * R_FLANGE, 2, nz * R_FLANGE);
    let p1 = proj(nx * R_FLANGE, 15, nz * R_FLANGE);
    let col = getCadmiumColor(nx, 0.05, nz, 0.95);
    brush.set("micro_marker", col, 0.95);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Flat top deck of the flange (Y = 15, radial ring from R_DOME_BASE to R_FLANGE)
  for (let r = R_DOME_BASE - 2; r <= R_FLANGE; r += 2.8) {
    for (let deg = -155; deg < 155; deg += 12) {
      let mid = deg + 6;
      let nx = sin(mid) * 0.25;
      let nz = cos(mid) * 0.25;
      let ny = 0.94;
      let ao = r < R_DOME_BASE + 6 ? 0.55 : 1.0;
      let col = getCadmiumColor(nx, ny, nz, ao);
      let pA = proj(sin(deg) * r, 15, cos(deg) * r);
      let pB = proj(sin(deg + 12) * r, 15, cos(deg + 12) * r);
      brush.set("micro_marker", col, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Crisp upper & lower rim contours of the bonnet flange
  drawCylinderArc(R_FLANGE, 2, -110, 110, "rotring", "#240405", 0.65);
  drawCylinderArc(R_FLANGE, 15, -115, 115, "rotring", "#4a0707", 0.5);
}

// ============================================================================
// 3. HYDRANT DOME (BONNET), RIBS, FLANGE BOLTS & PENTAGON NUT
// ============================================================================
function drawHydrantDomeAndNut() {
  const R_DOME_BASE = 102;
  const Y_FLANGE_TOP = 15;
  const Y_DOME_TOP = 114;

  // Helper for dome radius & surface slope at height y (from 15 to 114)
  function getDomeProfile(y) {
    let t = constrain((y - Y_FLANGE_TOP) / (Y_DOME_TOP - Y_FLANGE_TOP), 0, 1);
    // Classic fire hydrant bonnet: slightly tapered lower skirt up to t=0.28, then hemispherical dome
    let r;
    let ny;
    if (t < 0.28) {
      r = map(t, 0, 0.28, R_DOME_BASE, 95);
      ny = 0.14;
      // Raised cast band around t = 0.26..0.31
      if (Math.abs(t - 0.28) < 0.035) {
        r += 3.8 * Math.cos(((t - 0.28) / 0.035) * (Math.PI / 2));
        ny += (t > 0.28) ? 0.45 : -0.45;
      }
    } else {
      let u = map(t, 0.28, 1.0, 0, 1);
      r = 33 + 62 * Math.cos(u * (Math.PI * 0.48));
      ny = Math.sin(u * (Math.PI * 0.48)) * 0.85;
    }
    return { r, ny };
  }

  // Draw rear flange bolts first (those behind the dome profile)
  const boltAngles = [-135, -90, -45, 0, 45, 90, 135, 180];
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ < 0) {
      drawHexBoltVertical(sin(bDeg) * 114, 15, cos(bDeg) * 114, 8.5, 7.5);
    }
  }

  // --- 3A. Bonnet Dome Surface Marker Rendering ---
  const ySteps = 34;
  for (let j = 0; j < ySteps; j++) {
    let y0 = map(j, 0, ySteps, Y_FLANGE_TOP, Y_DOME_TOP);
    let y1 = map(j + 1, 0, ySteps, Y_FLANGE_TOP, Y_DOME_TOP);
    let prof0 = getDomeProfile(y0);
    let prof1 = getDomeProfile(y1);

    for (let deg = -114; deg <= 114; deg += 4) {
      let nx = sin(deg) * Math.sqrt(Math.max(0, 1 - prof0.ny * prof0.ny));
      let nz = cos(deg) * Math.sqrt(Math.max(0, 1 - prof0.ny * prof0.ny));
      let ny = prof0.ny;

      // 8 raised meridional cast ribs at boltAngles
      let ribBoost = 0;
      let ribNxShift = 0;
      for (let bDeg of boltAngles) {
        let dA = ((deg - bDeg + 540) % 360) - 180;
        if (Math.abs(dA) < 5.5) {
          ribBoost = 3.2 * Math.cos((dA / 5.5) * (Math.PI / 2));
          ribNxShift = (dA / 5.5) * 0.35;
        }
      }

      let r0 = prof0.r + ribBoost;
      let r1 = prof1.r + ribBoost;
      let p0 = proj(sin(deg) * r0, y0, cos(deg) * r0);
      let p1 = proj(sin(deg) * r1, y1, cos(deg) * r1);

      let ao = j < 2 ? 0.65 : (j > ySteps - 3 ? 0.72 : 1.0);
      let col = getCadmiumColor(nx + ribNxShift * cos(deg), ny, nz - ribNxShift * sin(deg), ao);
      brush.set("cad_marker", col, 0.72);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Crisp latitude contour strokes & rib edge definitions on the dome
  for (let y = Y_FLANGE_TOP + 4; y <= Y_DOME_TOP - 2; y += 6.5) {
    let prof = getDomeProfile(y);
    for (let deg = -108; deg < 108; deg += 12) {
      let mid = deg + 6;
      let s = Math.sqrt(Math.max(0, 1 - prof.ny * prof.ny));
      let col = getCadmiumColor(sin(mid) * s, prof.ny, cos(mid) * s, 1.0);
      let pA = proj(sin(deg) * prof.r, y, cos(deg) * prof.r);
      let pB = proj(sin(deg + 12) * prof.r, y, cos(deg + 12) * prof.r);
      brush.set("micro_marker", col, 0.7);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Emphasize the 8 raised meridional ribs on the dome with fine marker & pencil shadow lines
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ < -0.25) continue;
    let ptsCenter = [];
    let ptsShadow = [];
    for (let y = Y_FLANGE_TOP + 3; y <= Y_DOME_TOP - 3; y += 6) {
      let prof = getDomeProfile(y);
      let rRib = prof.r + 3.4;
      ptsCenter.push(proj(sin(bDeg) * rRib, y, cos(bDeg) * rRib));
      ptsShadow.push(proj(sin(bDeg + 4.8) * (prof.r + 0.6), y, cos(bDeg + 4.8) * (prof.r + 0.6)));
    }
    let s = 0.75;
    let ribCol = getCadmiumColor(sin(bDeg - 8) * s, 0.45, cos(bDeg - 8) * s, 1.05);
    brush.set("micro_marker", ribCol, 0.85);
    safeSpline(ptsCenter.map(p => [p.x, p.y]), 0.4);

    brush.set("rotring", "#3d0606", 0.45);
    safeSpline(ptsShadow.map(p => [p.x, p.y]), 0.4);
  }

  // Draw front flange bolts sitting on the flange deck (Y = 15, R = 114)
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ >= 0) {
      drawHexBoltVertical(sin(bDeg) * 114, 15, cos(bDeg) * 114, 8.8, 8.0);
    }
  }

  // --- 3B. Top Collar (Y = 114 to 125, R = 36) & 5-Sided Pentagon Operating Nut (Y = 125 to 150) ---
  const R_COLLAR = 36;
  for (let deg = -125; deg <= 125; deg += 6) {
    let nx = sin(deg);
    let nz = cos(deg);
    let p0 = proj(nx * R_COLLAR, 114, nz * R_COLLAR);
    let p1 = proj(nx * (R_COLLAR - 2), 125, nz * (R_COLLAR - 2));
    let col = getCadmiumColor(nx, 0.1, nz, 0.85);
    brush.set("micro_marker", col, 0.85);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
  // Collar top deck
  for (let r = 24; r <= 34; r += 2.5) {
    drawCylinderArc(r, 125, -170, 170, "micro_marker", "#eb2413", 0.7);
  }
  drawCylinderArc(R_COLLAR, 114, -115, 115, "rotring", "#2b0506", 0.6);

  // 5-Sided Pentagonal Operating Nut (Y = 125 to 150, R = 25)
  const R_PENT = 25;
  const Y_PENT_BOT = 125;
  const Y_PENT_TOP = 150;
  const pentAngles = [-142, -70, 2, 74, 146];

  // Collect faces and sort back-to-front
  let faces = [];
  for (let k = 0; k < 5; k++) {
    let a1 = pentAngles[k];
    let a2 = pentAngles[(k + 1) % 5];
    let midA = a1 + (((a2 - a1 + 540) % 360) - 180) * 0.5;
    let nx = sin(midA);
    let nz = cos(midA);
    let viewNormal = rotNormal(nx, 0, nz);
    faces.push({ a1, a2, midA, nx, nz, zOrder: viewNormal.z });
  }
  faces.sort((a, b) => a.zOrder - b.zOrder);

  for (let f of faces) {
    if (f.zOrder < -0.15) continue; // Back-facing facet
    let col = getCadmiumColor(f.nx, 0.05, f.nz, 0.95);
    let steps = 12;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let x = lerp(sin(f.a1) * R_PENT, sin(f.a2) * R_PENT, t);
      let z = lerp(cos(f.a1) * R_PENT, cos(f.a2) * R_PENT, t);
      let pBot = proj(x, Y_PENT_BOT, z);
      let pTop = proj(x, Y_PENT_TOP, z);
      brush.set("micro_marker", col, 0.85);
      brush.line(pBot.x, pBot.y, pTop.x, pTop.y);
    }
    // Chipped dark cast-iron/bronze wear along the sharp vertical edges of the wrench nut
    let eBot = proj(sin(f.a1) * R_PENT, Y_PENT_BOT, cos(f.a1) * R_PENT);
    let eTop = proj(sin(f.a1) * R_PENT, Y_PENT_TOP, cos(f.a1) * R_PENT);
    brush.set("rotring", "#1f191b", 0.65);
    brush.line(eBot.x, eBot.y, eTop.x, eTop.y);
  }

  // Pentagon Nut Top Face (Y = 150) with slight central dome
  for (let k = 0; k < 5; k++) {
    let a1 = pentAngles[k];
    let a2 = pentAngles[(k + 1) % 5];
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let vx = lerp(sin(a1) * R_PENT, sin(a2) * R_PENT, t);
      let vz = lerp(cos(a1) * R_PENT, cos(a2) * R_PENT, t);
      let pOut = proj(vx, Y_PENT_TOP, vz);
      let pIn = proj(0, Y_PENT_TOP + 3.5, 0);
      let col = getCadmiumColor(vx * 0.01, 0.96, vz * 0.01, 1.0);
      brush.set("micro_marker", col, 0.75);
      brush.line(pOut.x, pOut.y, pIn.x, pIn.y);
    }
    // Top pentagon bevel edge in dark worn iron
    let p1 = proj(sin(a1) * R_PENT, Y_PENT_TOP, cos(a1) * R_PENT);
    let p2 = proj(sin(a2) * R_PENT, Y_PENT_TOP, cos(a2) * R_PENT);
    brush.set("rotring", "#241b1d", 0.6);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Helper to draw a vertical 3D hex bolt sitting on a horizontal flange
function drawHexBoltVertical(bx, by, bz, rad, ht) {
  const hexA = [0, 60, 120, 180, 240, 300];
  // Dark cast-iron washer shadow at base
  for (let a = 0; a < 360; a += 30) {
    let p1 = proj(bx + sin(a) * (rad + 2), by + 0.5, bz + cos(a) * (rad + 2));
    let p2 = proj(bx + sin(a + 30) * (rad + 2), by + 0.5, bz + cos(a + 30) * (rad + 2));
    brush.set("rotring", "#1c0506", 0.65);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Vertical facets of hex head
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let mid = a1 + 30;
    let vn = rotNormal(sin(mid), 0, cos(mid));
    if (vn.z < -0.1) continue;
    let col = getCadmiumColor(sin(mid), 0.1, cos(mid), 0.9);
    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let vx = bx + lerp(sin(a1) * rad, sin(a2) * rad, t);
      let vz = bz + lerp(cos(a1) * rad, cos(a2) * rad, t);
      let p0 = proj(vx, by + 1, vz);
      let p1 = proj(vx, by + ht, vz);
      brush.set("micro_marker", col, 0.7);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
    let e0 = proj(bx + sin(a1) * rad, by + 1, bz + cos(a1) * rad);
    let e1 = proj(bx + sin(a1) * rad, by + ht, bz + cos(a1) * rad);
    brush.set("rotring", "#240708", 0.45);
    brush.line(e0.x, e0.y, e1.x, e1.y);
  }

  // Top hexagonal face
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let pC = proj(bx, by + ht + 1, bz);
    let p1 = proj(bx + sin(a1) * rad, by + ht, bz + cos(a1) * rad);
    let p2 = proj(bx + sin(a2) * rad, by + ht, bz + cos(a2) * rad);
    brush.set("micro_marker", "#ff3b26", 0.65);
    brush.line(p1.x, p1.y, pC.x, pC.y);
    brush.line(p2.x, p2.y, pC.x, pC.y);
    brush.set("rotring", "#330808", 0.4);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Helper to draw a horizontal 3D arc on the main hydrant axis
function drawCylinderArc(r, y, degStart, degEnd, brushName, col, wt) {
  let pts = [];
  for (let deg = degStart; deg <= degEnd; deg += 5) {
    let p = proj(sin(deg) * r, y, cos(deg) * r);
    pts.push([p.x, p.y]);
  }
  brush.set(brushName, col, wt);
  safeSpline(pts, 0.4);
}

// ============================================================================
// 4. PROTRUDING BOLTED NOZZLE, WRENCH LUGS, PENTAGON NUT & CHAIN
// ============================================================================
function drawBoltedNozzle() {
  const Y_NOZ = -68; // Nozzle center height on the hydrant shoulder

  // Helper to project a point in Nozzle cylindrical coords (r, th, z)
  // th = 0 is top (+Y), th = 90 is right (+X), th = -90 is left (-X), th = 180 is bottom (-Y)
  function projNoz(r, th, z) {
    let x = sin(th) * r;
    let y = Y_NOZ + cos(th) * r;
    return proj(x, y, z);
  }

  // Helper to draw a cylindrical band along the nozzle (+Z axis)
  function drawNozzleCylinder(z0, z1, r0, r1, zSteps, aoMult = 1.0) {
    for (let s = 0; s < zSteps; s++) {
      let za = map(s, 0, zSteps, z0, z1);
      let zb = map(s + 1, 0, zSteps, z0, z1);
      let ra = map(s, 0, zSteps, r0, r1);
      let rb = map(s + 1, 0, zSteps, r0, r1);

      for (let th = -165; th <= 165; th += 4) {
        let nx = sin(th);
        let ny = cos(th);
        let vn = rotNormal(nx, ny, 0.15);
        if (vn.z < -0.22) continue;

        let p0 = projNoz(ra, th, za);
        let p1 = projNoz(rb, th, zb);

        // Clip bottom of nozzle softly where snowdrift laps up against it
        let snowY = getSnowLineY(p0.x) + 6;
        if (p0.y > snowY && p1.y > snowY) continue;

        let col = getCadmiumColor(nx, ny, 0.12, aoMult);
        brush.set("cad_marker", col, 0.72);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // Ring contour strokes around the nozzle cylinder
    for (let z = z0; z <= z1; z += 5) {
      let r = map(z, z0, z1, r0, r1);
      for (let th = -150; th < 150; th += 15) {
        let mid = th + 7.5;
        let vn = rotNormal(sin(mid), cos(mid), 0.15);
        if (vn.z < -0.15) continue;
        let pA = projNoz(r, th, z);
        let pB = projNoz(r, th + 15, z);
        if (pA.y > getSnowLineY(pA.x) + 6) continue;
        let col = getCadmiumColor(sin(mid), cos(mid), 0.15, aoMult);
        brush.set("micro_marker", col, 0.75);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }
  }

  // --- 4A. Nozzle Mounting Flange on Barrel (Z = 92 to 114, R = 64) ---
  const R_MOUNT = 64;
  drawNozzleCylinder(92, 114, R_MOUNT + 2, R_MOUNT, 5, 0.88);

  // Flat front face of the mounting flange (Z = 114, R from 46 to 64)
  for (let r = 46; r <= R_MOUNT; r += 2.5) {
    for (let th = -165; th < 165; th += 14) {
      let pA = projNoz(r, th, 114);
      let pB = projNoz(r, th + 14, 114);
      if (pA.y > getSnowLineY(pA.x) + 6) continue;
      let col = getCadmiumColor(sin(th) * 0.25, cos(th) * 0.25, 0.94, r < 51 ? 0.55 : 0.95);
      brush.set("micro_marker", col, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
  drawNozzleRingArc(R_MOUNT, 114, -155, 145, "rotring", "#2b0506", 0.6);

  // 6 Hex Bolts around the nozzle mounting flange (R = 55, Z = 114..121)
  const nozBoltAngles = [-145, -85, -25, 35, 95, 155];
  for (let bTh of nozBoltAngles) {
    let bx = sin(bTh) * 55;
    let by = Y_NOZ + cos(bTh) * 55;
    let pTest = proj(bx, by, 116);
    if (pTest.y < getSnowLineY(pTest.x) + 4) {
      drawHexBoltForward(bx, by, 114, 5.8, 6.5);
    }
  }

  // --- 4B. Nozzle Thread Neck (Z = 114 to 140, R = 46) ---
  drawNozzleCylinder(114, 134, 46, 46, 5, 0.82);
  // Dark thread undercut groove at Z = 134..140
  drawNozzleCylinder(134, 140, 43, 43, 2, 0.35);
  drawNozzleRingArc(46, 134, -150, 145, "rotring", "#1e0405", 0.75);

  // --- 4C. Rear Wrench Lugs on Nozzle Cap (angles 60° and 140° on right/bottom-right) ---
  const lugAngles = [-130, -42, 48, 138];
  for (let lTh of lugAngles) {
    if (lTh > 0) {
      drawNozzleLug(lTh, 145, 169, 53, 69);
    }
  }

  // --- 4D. Heavy Cast Nozzle Cap Cylinder (Z = 140 to 175, R = 54) ---
  drawNozzleCylinder(140, 172, 54, 54, 7, 1.0);
  // Front bevel of nozzle cap (Z = 172 to 176, R = 54 down to 50)
  drawNozzleCylinder(172, 176, 54, 50, 2, 1.05);
  drawNozzleRingArc(54, 140, -150, 145, "rotring", "#240405", 0.7);
  drawNozzleRingArc(54, 172, -155, 150, "rotring", "#420607", 0.55);

  // --- 4E. Front/Windward Wrench Lugs on Nozzle Cap (angles -130° and -42°) ---
  for (let lTh of lugAngles) {
    if (lTh <= 0) {
      drawNozzleLug(lTh, 145, 169, 53, 69);
    }
  }

  // --- 4F. Recessed Front Face of Nozzle Cap (Z = 174..176, R = 0 to 50) ---
  for (let r = 18; r <= 50; r += 2.2) {
    // Deep recessed groove between R = 36 and R = 43
    let zFace = (r > 35 && r < 44) ? 172 : 176;
    let ao = (r > 35 && r < 44) ? 0.42 : (r < 23 ? 0.58 : 0.96);
    for (let th = -180; th < 180; th += 14) {
      let mid = th + 7;
      // Top inner lip of recess is in shadow, bottom inner lip catches sky light
      let ny = (r > 42 && r < 46) ? -cos(mid) * 0.6 : cos(mid) * 0.18;
      let nx = (r > 42 && r < 46) ? -sin(mid) * 0.6 : sin(mid) * 0.18;
      let pA = projNoz(r, th, zFace);
      let pB = projNoz(r, th + 14, zFace);
      let col = getCadmiumColor(nx, ny, 0.92, ao);
      brush.set("micro_marker", col, 0.78);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
  drawNozzleRingArc(44, 175, -180, 180, "rotring", "#260405", 0.65);
  drawNozzleRingArc(35, 175, -180, 180, "rotring", "#3b0607", 0.5);

  // --- 4G. Heavy Iron Security Chain Dangling from Bottom of Nozzle Cap ---
  drawNozzleChain();

  // --- 4H. Central 5-Sided Pentagonal Nozzle Nut (Z = 176 to 196, R = 20) ---
  const R_NOZ_PENT = 20;
  const Z_NP_BASE = 175;
  const Z_NP_TOP = 195;
  const npAngles = [-144, -72, 0, 72, 144];

  let npFaces = [];
  for (let k = 0; k < 5; k++) {
    let a1 = npAngles[k];
    let a2 = npAngles[(k + 1) % 5];
    let mid = a1 + (((a2 - a1 + 540) % 360) - 180) * 0.5;
    let vn = rotNormal(sin(mid), cos(mid), 0.1);
    npFaces.push({ a1, a2, mid, zOrder: vn.z });
  }
  npFaces.sort((a, b) => a.zOrder - b.zOrder);

  // Side walls of nozzle pentagon nut
  for (let f of npFaces) {
    if (f.zOrder < -0.2) continue;
    let col = getCadmiumColor(sin(f.mid), cos(f.mid), 0.15, 0.95);
    for (let s = 0; s <= 9; s++) {
      let t = s / 9;
      let vx = lerp(sin(f.a1) * R_NOZ_PENT, sin(f.a2) * R_NOZ_PENT, t);
      let vy = Y_NOZ + lerp(cos(f.a1) * R_NOZ_PENT, cos(f.a2) * R_NOZ_PENT, t);
      let p0 = proj(vx, vy, Z_NP_BASE);
      let p1 = proj(vx * 0.92, Y_NOZ + (vy - Y_NOZ) * 0.92, Z_NP_TOP);
      brush.set("micro_marker", col, 0.8);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
    let e0 = proj(sin(f.a1) * R_NOZ_PENT, Y_NOZ + cos(f.a1) * R_NOZ_PENT, Z_NP_BASE);
    let e1 = proj(sin(f.a1) * R_NOZ_PENT * 0.92, Y_NOZ + cos(f.a1) * R_NOZ_PENT * 0.92, Z_NP_TOP);
    brush.set("rotring", "#1d181a", 0.6);
    brush.line(e0.x, e0.y, e1.x, e1.y);
  }

  // Front pentagonal face of nozzle nut (Z = 195)
  const R_TOP_NP = R_NOZ_PENT * 0.92;
  for (let k = 0; k < 5; k++) {
    let a1 = npAngles[k];
    let a2 = npAngles[(k + 1) % 5];
    for (let s = 0; s <= 7; s++) {
      let t = s / 7;
      let vx = lerp(sin(a1) * R_TOP_NP, sin(a2) * R_TOP_NP, t);
      let vy = Y_NOZ + lerp(cos(a1) * R_TOP_NP, cos(a2) * R_TOP_NP, t);
      let pEdge = proj(vx, vy, Z_NP_TOP);
      let pCtr = proj(0, Y_NOZ, Z_NP_TOP + 2.5);
      let col = getCadmiumColor(vx * 0.02, (vy - Y_NOZ) * 0.02, 0.98, 1.0);
      brush.set("micro_marker", col, 0.75);
      brush.line(pEdge.x, pEdge.y, pCtr.x, pCtr.y);
    }
    let p1 = proj(sin(a1) * R_TOP_NP, Y_NOZ + cos(a1) * R_TOP_NP, Z_NP_TOP);
    let p2 = proj(sin(a2) * R_TOP_NP, Y_NOZ + cos(a2) * R_TOP_NP, Z_NP_TOP);
    brush.set("rotring", "#21191b", 0.65);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Helper to draw a chunky radial wrench lug on the nozzle cap
  function drawNozzleLug(thCenter, zBack, zFront, rBase, rTip) {
    const halfAng = 9.5;
    let a1 = thCenter - halfAng;
    let a2 = thCenter + halfAng;

    // 1. Side walls (a1 and a2)
    for (let side of [-1, 1]) {
      let ang = side < 0 ? a1 : a2;
      let nx = sin(ang + side * 90);
      let ny = cos(ang + side * 90);
      let vn = rotNormal(nx, ny, 0.1);
      if (vn.z < -0.15) continue;
      let col = getCadmiumColor(nx, ny, 0.1, 0.88);
      for (let r = rBase; r <= rTip; r += 2.2) {
        let p0 = projNoz(r, ang, zBack);
        let p1 = projNoz(r, ang, zFront);
        brush.set("micro_marker", col, 0.78);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // 2. Outer tip face (at rTip)
    let vnTip = rotNormal(sin(thCenter), cos(thCenter), 0.1);
    if (vnTip.z > -0.25) {
      let colTip = getCadmiumColor(sin(thCenter), cos(thCenter), 0.15, 1.0);
      for (let th = a1; th <= a2; th += 2.5) {
        let p0 = projNoz(rTip, th, zBack + 1.5);
        let p1 = projNoz(rTip, th, zFront - 1.5);
        brush.set("micro_marker", colTip, 0.82);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // 3. Front face of lug (at zFront)
    let colFront = getCadmiumColor(sin(thCenter) * 0.25, cos(thCenter) * 0.25, 0.95, 0.96);
    for (let r = rBase; r <= rTip; r += 2.2) {
      let pA = projNoz(r, a1, zFront);
      let pB = projNoz(r, a2, zFront);
      brush.set("micro_marker", colFront, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }

    // Crisp dark iron bevel edges on lug
    let c1 = projNoz(rTip, a1, zFront);
    let c2 = projNoz(rTip, a2, zFront);
    let c3 = projNoz(rTip, a1, zBack);
    let c4 = projNoz(rTip, a2, zBack);
    let b1 = projNoz(rBase, a1, zFront);
    let b2 = projNoz(rBase, a2, zFront);
    brush.set("rotring", "#241819", 0.55);
    brush.line(c1.x, c1.y, c2.x, c2.y);
    brush.line(b1.x, b1.y, c1.x, c1.y);
    brush.line(b2.x, b2.y, c2.x, c2.y);
    brush.line(c1.x, c1.y, c3.x, c3.y);
    brush.line(c2.x, c2.y, c4.x, c4.y);
  }

  function drawNozzleRingArc(r, z, thStart, thEnd, brushName, col, wt) {
    let pts = [];
    for (let th = thStart; th <= thEnd; th += 6) {
      let p = projNoz(r, th, z);
      if (p.y <= getSnowLineY(p.x) + 8) {
        pts.push([p.x, p.y]);
      }
    }
    brush.set(brushName, col, wt);
    safeSpline(pts, 0.4);
  }
}

// Helper for forward-facing hex bolts on the nozzle mounting flange
function drawHexBoltForward(bx, by, bz, rad, ht) {
  const hexA = [15, 75, 135, 195, 255, 315];
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let mid = a1 + 30;
    let vn = rotNormal(sin(mid), cos(mid), 0.15);
    if (vn.z < -0.15) continue;
    let col = getCadmiumColor(sin(mid), cos(mid), 0.2, 0.9);
    for (let s = 0; s <= 3; s++) {
      let t = s / 3;
      let vx = bx + lerp(sin(a1) * rad, sin(a2) * rad, t);
      let vy = by + lerp(cos(a1) * rad, cos(a2) * rad, t);
      let p0 = proj(vx, vy, bz);
      let p1 = proj(vx, vy, bz + ht);
      brush.set("micro_marker", col, 0.68);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let pC = proj(bx, by, bz + ht + 0.8);
    let p1 = proj(bx + sin(a1) * rad, by + cos(a1) * rad, bz + ht);
    let p2 = proj(bx + sin(a2) * rad, by + cos(a2) * rad, bz + ht);
    brush.set("micro_marker", "#e82212", 0.65);
    brush.line(p1.x, p1.y, pC.x, pC.y);
    brush.set("rotring", "#2b0607", 0.45);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Heavy iron chain links dangling from bottom of nozzle cap into the snowbank
function drawNozzleChain() {
  const links = [
    { x: -2, y: -96, z: 182, rx: 6, ry: 10, rz: 3, twist: 15 },
    { x: 3, y: -110, z: 178, rx: 4, ry: 11, rz: 6, twist: -35 },
    { x: 10, y: -124, z: 172, rx: 7, ry: 10, rz: 3, twist: 20 },
    { x: 19, y: -136, z: 165, rx: 5, ry: 9, rz: 5, twist: -25 }
  ];

  for (let lk of links) {
    let ptsOuter = [];
    let ptsInner = [];
    let ptsHi = [];
    for (let a = 0; a <= 360; a += 20) {
      let lx = cos(a) * lk.rx;
      let ly = sin(a) * lk.ry;
      let lz = cos(a + lk.twist) * lk.rz;
      let p = proj(lk.x + lx, lk.y + ly, lk.z + lz);
      if (p.y < getSnowLineY(p.x) + 8) {
        ptsOuter.push([p.x, p.y]);
        let pIn = proj(lk.x + lx * 0.65, lk.y + ly * 0.65, lk.z + lz);
        ptsInner.push([pIn.x, pIn.y]);
        if (a > 100 && a < 250) ptsHi.push([p.x - 1.2, p.y - 1.2]);
      }
    }
    brush.set("micro_marker", "#630808", 0.95);
    safeSpline(ptsOuter, 0.5);
    brush.set("rotring", "#1d1416", 0.65);
    safeSpline(ptsInner, 0.5);
    brush.set("micro_marker", "#e02414", 0.65);
    safeSpline(ptsHi, 0.5);
  }
}

// ============================================================================
// 5. CLINGING ICE RIME IN CRISP WHITE PENCIL
// ============================================================================
function drawClingingIceRime() {
  const R_BARREL = 106;
  const R_FLANGE = 125;

  // Helper to draw a cluster of crystalline rime needles pointing into the wind (-158°)
  function drawRimeTuft(sx, sy, lengthScale = 1.0, density = 5) {
    // Subtle icy blue-grey base crust
    brush.set("cpencil", "#b8cbe0", 0.75);
    brush.line(sx, sy, sx - cos(WIND_ANGLE) * 6 * lengthScale, sy - sin(WIND_ANGLE) * 6 * lengthScale);

    // Crisp white pencil crystalline needles
    for (let i = 0; i < density; i++) {
      let ang = (WIND_ANGLE + 180) + random(-24, 24);
      let len = random(4, 15) * lengthScale;
      let ox = random(-2.5, 2.5);
      let oy = random(-2.5, 2.5);
      brush.set("rime_white", i % 3 === 0 ? "#eef6ff" : "#ffffff", random(0.65, 1.15));
      brush.line(sx + ox, sy + oy, sx + ox + cos(ang) * len, sy + oy + sin(ang) * len);
    }
  }

  // --- 5A. Windward Ice Rime on Dome (Cap) & Raised Ribs ---
  // Thickest on left/windward contour (deg from -112° to -25°)
  for (let y = 16; y <= 112; y += 3.2) {
    let t = (y - 15) / (114 - 15);
    let r = t < 0.28 ? map(t, 0, 0.28, 102, 95) : 33 + 62 * Math.cos(map(t, 0.28, 1, 0, 1) * (Math.PI * 0.48));
    if (Math.abs(t - 0.28) < 0.035) r += 3.8;

    // Windward edge crust
    for (let deg = -112; deg <= -18; deg += 5.5) {
      let chance = map(deg, -112, -18, 0.95, 0.2);
      if (random() < chance) {
        let p = proj(sin(deg) * (r + 1.2), y, cos(deg) * (r + 1.2));
        let scale = map(deg, -112, -18, 1.15, 0.45);
        drawRimeTuft(p.x, p.y, scale, deg < -75 ? 4 : 2);
      }
    }

    // Extra snow/ice packed onto the horizontal dome molding band (y ~ 41..47)
    if (y > 41 && y < 48) {
      for (let deg = -105; deg <= 42; deg += 4) {
        let p = proj(sin(deg) * (r + 3.5), y + 1.5, cos(deg) * (r + 3.5));
        drawRimeTuft(p.x, p.y, map(deg, -105, 42, 0.95, 0.35), 3);
      }
    }
  }

  // Rime clinging along the windward edges of the dome's raised cast ribs
  const ribAngles = [-90, -45, 0, 45];
  for (let bDeg of ribAngles) {
    for (let y = 18; y <= 110; y += 4.5) {
      let t = (y - 15) / (114 - 15);
      let r = (t < 0.28 ? map(t, 0, 0.28, 102, 95) : 33 + 62 * Math.cos(map(t, 0.28, 1, 0, 1) * (Math.PI * 0.48))) + 3.6;
      let p = proj(sin(bDeg - 3) * r, y, cos(bDeg - 3) * r);
      drawRimeTuft(p.x, p.y, bDeg < 0 ? 0.85 : 0.45, 3);
    }
  }

  // --- 5B. Packed Ice Rime on Bonnet Flange Deck & Flange Bolts ---
  for (let deg = -118; deg <= 68; deg += 2.8) {
    let r = random(101, R_FLANGE + 1.5);
    let p = proj(sin(deg) * r, 15.5, cos(deg) * r);
    let scale = map(deg, -118, 68, 1.2, 0.35);
    if (random() < map(deg, -118, 68, 0.95, 0.35)) {
      drawRimeTuft(p.x, p.y, scale, 3);
    }
  }
  // Rime hoods on the windward flange bolts
  for (let bDeg of [-90, -45, 0, 45]) {
    let p = proj(sin(bDeg) * 114, 23.5, cos(bDeg) * 114);
    drawRimeTuft(p.x, p.y, bDeg <= 0 ? 1.1 : 0.65, 6);
  }

  // --- 5C. Rime on Top Collar & Pentagonal Operating Nut ---
  for (let y = 114; y <= 151; y += 3.5) {
    for (let deg = -125; deg <= 25; deg += 9) {
      let r = y < 125 ? 36 : 25.5;
      let p = proj(sin(deg) * r, y, cos(deg) * r);
      if (random() < map(deg, -125, 25, 0.9, 0.25)) {
        drawRimeTuft(p.x, p.y, map(deg, -125, 25, 1.0, 0.4), 3);
      }
    }
  }
  // Frost cap on top of the operating nut
  for (let i = 0; i < 18; i++) {
    let a = random(-150, 60);
    let r = random(2, 24);
    let p = proj(sin(a) * r, 151.5, cos(a) * r);
    drawRimeTuft(p.x, p.y, 0.75, 3);
  }

  // --- 5D. Windward Shoulder Rime & Snow-Line Crust ---
  for (let y = -115; y <= -3; y += 4.5) {
    for (let deg = -112; deg <= -42; deg += 6) {
      let p = proj(sin(deg) * (R_BARREL + 1.5), y, cos(deg) * (R_BARREL + 1.5));
      if (p.y < getSnowLineY(p.x) && random() < map(deg, -112, -42, 0.9, 0.15)) {
        drawRimeTuft(p.x, p.y, map(deg, -112, -42, 1.1, 0.4), 3);
      }
    }
  }

  // --- 5E. Clinging Ice Rime on the Bolted Nozzle, Lugs, Nozzle Nut & Chain ---
  const Y_NOZ = -68;
  // Upper-left windward arc of nozzle mounting flange & cap
  for (let z = 96; z <= 176; z += 3.5) {
    let r = z < 115 ? 64.5 : (z < 140 ? 46.5 : 54.5);
    for (let th = -135; th <= 28; th += 7) {
      let p = proj(sin(th) * r, Y_NOZ + cos(th) * r, z);
      if (p.y < getSnowLineY(p.x) && random() < map(th, -135, 28, 0.9, 0.25)) {
        drawRimeTuft(p.x, p.y, map(th, -135, 28, 1.05, 0.4), 3);
      }
    }
  }

  // Heavy rime on the two windward nozzle wrench lugs (-130° and -42°) and top-right lug (48°)
  for (let lTh of [-130, -42, 48]) {
    for (let r = 54; r <= 70; r += 3) {
      for (let z = 145; z <= 170; z += 4) {
        let p = proj(sin(lTh - 5) * r, Y_NOZ + cos(lTh - 5) * r, z);
        drawRimeTuft(p.x, p.y, lTh < 0 ? 0.95 : 0.5, 3);
      }
    }
  }

  // Crisp frost ring inside the recessed nozzle cap face & around the central pentagon nut
  for (let th = -165; th <= 45; th += 8) {
    let pRim = proj(sin(th) * 44, Y_NOZ + cos(th) * 44, 176);
    drawRimeTuft(pRim.x, pRim.y, 0.65, 2);

    let pNut = proj(sin(th) * 20.5, Y_NOZ + cos(th) * 20.5, random(177, 195));
    drawRimeTuft(pNut.x, pNut.y, 0.75, 3);
  }

  // Rime clinging to the dangling chain links
  for (let y = -94; y >= -134; y -= 5) {
    let p = proj(map(y, -94, -134, -4, 16), y, map(y, -94, -134, 183, 166));
    if (p.y < getSnowLineY(p.x) + 4) {
      drawRimeTuft(p.x, p.y, 0.65, 3);
    }
  }

  // Fine granular frost stipple over windward cast iron
  brush.set("frost_stipple", "#ffffff", 0.85);
  for (let i = 0; i < 45; i++) {
    let y = random(-85, 135);
    let p = proj(random(-115, -15), y, random(30, 175));
    if (p.y < getSnowLineY(p.x)) {
      brush.line(p.x, p.y, p.x + cos(WIND_ANGLE) * 8, p.y + sin(WIND_ANGLE) * 8);
    }
  }
}

// ============================================================================
// 6. FOREGROUND SNOW DRIFTS & EDGE DISSOLUTION (Layered Translucent Washes)
// ============================================================================
function drawForegroundDriftsAndEdgeDissolve() {
  brush.noStroke();

  // --- 6A. Subtle Warm Cadmium Reflected Glow in the Snow Hollow Under the Nozzle ---
  brush.fill("#e05a47", 24);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.4, 0.1);
  drawTiltedCloudPoly(602, 752, 68, 24, 14, 10);
  drawTiltedCloudPoly(695, 718, 56, 20, 18, 10);

  // --- 6B. Cool Blue-Grey Snow-Drift Shadow Washes in the Wind-Scoured Hollow ---
  const shadowDrifts = [
    { cx: 615, cy: 772, rx: 115, ry: 34, ang: 16, col: "#9fb0c4", alpha: 52 },
    { cx: 745, cy: 748, rx: 135, ry: 38, ang: 22, col: "#b0bfd1", alpha: 48 },
    { cx: 510, cy: 715, rx: 110, ry: 30, ang: 20, col: "#c2cfde", alpha: 44 },
    { cx: 660, cy: 825, rx: 220, ry: 55, ang: 19, col: "#cbd6e4", alpha: 42 }
  ];

  for (let sd of shadowDrifts) {
    brush.fill(sd.col, sd.alpha);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.45, 0.14);
    drawTiltedCloudPoly(sd.cx, sd.cy, sd.rx, sd.ry, sd.ang, 12);
  }

  // --- 6C. Main Layered Translucent Snow Drift Lapping Over the Hydrant Shoulders ---
  for (let pass = 0; pass < 3; pass++) {
    brush.fill(pass === 0 ? "#eef3f8" : "#ffffff", pass === 0 ? 115 : 155);
    brush.fillBleed(0.26, "out");
    brush.fillTexture(0.32, 0.1);

    brush.beginShape(0.35);
    for (let x = 140; x <= 1060; x += 28) {
      let sy = getSnowLineY(x) + pass * 11 + (noise(x * 0.02, pass * 5) - 0.5) * 10;
      brush.vertex(x, sy);
    }
    brush.vertex(1060, 1080);
    brush.vertex(140, 1080);
    brush.endShape(true);
  }

  // --- 6D. Outer Perimeter Whiteout Washes (Dissolving Every Detail Toward the Edges) ---
  brush.fill("#ffffff", 175);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.2, 0.05);

  const edgeClouds = [
    { cx: 600, cy: 95, rx: 580, ry: 155, ang: 4 },
    { cx: 600, cy: 1105, rx: 580, ry: 165, ang: -3 },
    { cx: 105, cy: 600, rx: 165, ry: 560, ang: 6 },
    { cx: 1095, cy: 600, rx: 175, ry: 560, ang: -5 },
    { cx: 210, cy: 210, rx: 260, ry: 210, ang: -25 },
    { cx: 990, cy: 220, rx: 260, ry: 210, ang: 25 },
    { cx: 210, cy: 990, rx: 270, ry: 220, ang: 25 },
    { cx: 990, cy: 980, rx: 280, ry: 220, ang: -25 }
  ];
  for (let ec of edgeClouds) {
    drawTiltedCloudPoly(ec.cx, ec.cy, ec.rx, ec.ry, ec.ang, 12);
  }
  brush.noFill();

  // Crisp snow-crust lip & packed snow granules right where the hydrant meets the snowbank
  for (let x = 495; x <= 785; x += 3.5) {
    let sy = getSnowLineY(x);
    let nextY = getSnowLineY(x + 10);
    // Crisp white pencil crest along the drift ridge
    brush.set("rime_white", "#ffffff", random(0.85, 1.35));
    brush.line(x, sy, x + 12, nextY + random(-2, 2));

    // Delicate blue-grey shadow line just beneath the snow lip in the nozzle hollow
    if (x > 555 && x < 655) {
      brush.set("2H", "#8596ab", 0.55);
      brush.line(x, sy + 3, x + 9, nextY + 4);
    }
  }

  // Sweeping snow-drift contour lines across the lower foreground
  brush.field("squall_flow");
  for (let i = 0; i < 95; i++) {
    let sx = random(240, 960);
    let sy = getSnowLineY(sx) + random(4, 240);
    let dEdge = Math.min(sx, 1200 - sx, 1200 - sy);
    if (dEdge < 140) continue;
    let col = random() < 0.65 ? "#ffffff" : (random() < 0.5 ? "#c5d1df" : "#a8b7c9");
    brush.set(col === "#ffffff" ? "rime_white" : "2H", col, random(0.45, 0.9));
    brush.flowLine(sx, sy, random(35, 130), WIND_ANGLE + random(-6, 6));
  }
  brush.noField();
}

// ============================================================================
// 7. WINDBLOWN PENCIL FLECKS & DRIVING SNOW STREAKS
// ============================================================================
function drawWindblownPencilFlecks() {
  brush.field("squall_flow");

  // --- 7A. Graphite & Slate Pencil Flecks Driving Diagonally Across the Squall ---
  const graphiteFlecks = [
    { br: "2H", col: "#b4c1d0", count: 420, minL: 8, maxL: 48, wt: 0.55 },
    { br: "HB", col: "#93a3b5", count: 260, minL: 5, maxL: 28, wt: 0.5 },
    { br: "cpencil", col: "#7a8b9e", count: 140, minL: 3, maxL: 16, wt: 0.45 }
  ];

  for (let gf of graphiteFlecks) {
    brush.set(gf.br, gf.col, gf.wt);
    for (let i = 0; i < gf.count; i++) {
      // Concentrate flecks toward the middle of the sheet, fading out at the margins
      let angle = random(360);
      let rad = Math.pow(random(), 0.72) * 520;
      let x = 635 + cos(angle) * rad * 1.08;
      let y = 595 + sin(angle) * rad * 0.96;

      // Avoid heavy dark graphite flecks directly over the brightest red focal highlights
      let dHyd = Math.hypot(x - (HYD_CX - 10), y - (HYD_CY - 15));
      if (dHyd < 135 && gf.col === "#7a8b9e" && random() < 0.75) continue;

      let len = random(gf.minL, gf.maxL) * map(rad, 0, 520, 1.0, 0.45);
      brush.flowLine(x, y, len, WIND_ANGLE + random(-5, 5));
    }
  }

  // --- 7B. Crisp White Pencil Snow Flecks & Driving Streaks (Especially Over & Around the Hydrant) ---
  for (let i = 0; i < 520; i++) {
    let nearHydrant = i < 210;
    let x, y;
    if (nearHydrant) {
      x = HYD_CX + random(-210, 190);
      y = HYD_CY + random(-210, 185);
    } else {
      let angle = random(360);
      let rad = Math.pow(random(), 0.8) * 510;
      x = 635 + cos(angle) * rad;
      y = 595 + sin(angle) * rad;
    }

    let len = random(3, nearHydrant ? 26 : 42);
    let wt = random(0.45, nearHydrant ? 1.05 : 0.85);
    brush.set("rime_white", i % 4 === 0 ? "#e8f2fc" : "#ffffff", wt);

    if (len < 9) {
      // Short windblown snow pellet / fleck
      let a = WIND_ANGLE + random(-8, 8);
      brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
    } else {
      brush.flowLine(x, y, len, WIND_ANGLE + random(-4, 4));
    }
  }

  brush.noField();

  // --- 7C. Final Soft White Spray Veil to Dissolve the Lower/Right Shoulder & Outer Margins ---
  brush.set("squall_mist", "#ffffff", 1.55);
  // Veil overlapping the buried right shoulder & lower drift edge
  for (let i = 0; i < 28; i++) {
    let sx = random(685, 860);
    let sy = getSnowLineY(sx) + random(-35, 35);
    brush.line(sx - 45, sy - 18, sx + 45, sy + 18);
  }

  // Soft white spray around the outer border so every detail dissolves into pure white
  brush.set("squall_mist", "#ffffff", 2.1);
  for (let i = 0; i < 90; i++) {
    let a = random(360);
    let r = random(430, 620);
    let x = 600 + cos(a) * r;
    let y = 600 + sin(a) * r;
    brush.line(x - 60, y - 24, x + 60, y + 24);
  }
}
